INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (66, '9788477224549', 'La reina de los Condenados Volumen 3', 1, '1990', 485, 'The Queen of the Damned', 'media/core/9788477224549_Yu4ICYO.jpg', 1, '2022-08-03 17:25:37.256740', '2022-09-08 17:22:06.886109', 72, 12, 6, 5, NULL, '', '0101', 'Crónicas vampíricas', 9, 'Lestat convertido en una famosa estrella del rock despierta con su música a Akasha la Reina de los Condenados. La que una vez fuera la reina del Nilo toma a Lestat como amante y mano derecha y vuelca todas sus fuerzas en la destrucción de vampiros y varones humanos con el fin de que las hembras creen en un nuevo orden.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (67, '9788420403243', 'Hombres buenos', 4, '2015', 582, NULL, 'media/core/9788420403243_Meg6bWi.jpg', 1, '2022-08-03 17:28:18.537076', '2022-09-08 17:33:14.771994', 73, 1, 6, 5, NULL, '', '0101', NULL, 10, 'A finales del siglo XVIII, cuando dos miembros de la Real Academia Española, el bibliotecario don Hermógenes Molina y el almirante don Pedro Zárate, recibieron de sus compañeros el encargo de viajar a París para conseguir de forma casi clandestina los 28 volúmenes de la Encyclopédie de D´Alembert y Diderot, que estaba prohibida en España, nadie podía sospechar que los dos académicos iban a enfrentarse a una peligrosa sucesión de intrigas, a un viaje de incertidumbres y sobresaltos que los llevaría, por caminos infestados de bandoleros e incómodas ventas y posadas, desde el Madrid ilustrado de Carlos III al París de los cafés, los salones, las tertulias filosóficas, la vida libertina y las agitaciones políticas en vísperas de la Revolución francesa. Basada en hechos y personajes reales, documentada con extremo rigor, conmovedora y fascinante en cada página.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (68, '9788477224532', 'Lestat el vampiro Volumen 2', 1, '1990', 528, 'The Vampire Lestat', 'media/core/9788477224532_FOaP24H.jpg', 1, '2022-08-03 17:31:26.361514', '2022-08-04 12:12:37.974633', 72, 12, 6, 5, NULL, '', '0101', 'Crónicas vampíricas', 9, NULL, NULL);
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (69, '9788477224525', 'Confesiones de un vampiro Volumen 1', 1, '1990', 335, 'Interview with the vampire', 'media/core/9788477224525_E6inT6y.jpg', 1, '2022-08-03 17:35:41.112535', '2022-09-08 17:15:02.055831', 72, 12, 6, 5, NULL, '', '0101', 'Crónicas vampíricas', 9, 'Anne Rice narra la conversión de un joven de Nueva Orleans en eterno habitante de la noche. El protagonista llevado por el sentimiento de culpabilidad que le ha causado la muerte de su hemano menor anhela transformarse en un ser maldito. Sin embargo ya desde el inicio de su vida sobrenatural se siente invadido por los sentimientos más humanos como el amor que lo ata a una de sus víctimas una pasión no exenta de dependencia sexual y psicológica', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (70, '9788467271256', 'El Ministerio de la Felicidad Suprema', 1, '2017', 511, 'The Ministry of Utmost Happiness', 'media/core/sin-imagen_7YXlc2u_nSWQpYY.jpg', 1, '2022-08-03 17:38:31.734108', '2022-09-08 17:39:06.415595', 74, 1, 6, 5, NULL, '', '0102', NULL, 5, 'La historia empieza con Anyum -que antes se llamaba Aftab- desenrollando una rad̕a alfombra persa en un cementerio al que llama hogar. Nos encontramos con la extraą e inolvidable Tilo y los hombres que la amaron, incluido Musa, novio y exnovio, amante y examante: sus destinos estǹ tan entrelazados lo estaban y estarǹ para siempre sus brazos', '');
