INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (95, '9788466615716', 'El santuario', 1, '2004', 603, 'Blackwood Farm', 'media/core/9788466615716.jpg', 1, '2022-08-04 16:19:30.311342', '2022-09-08 17:17:00.957897', 72, 12, 6, 5, 'La Trama', '', '0103', NULL, 8, 'Quinn Blackwood, un rico y excéntrico joven convertido en vampiro, pide la ayuda de Lestat para librarse del celoso control a que le somete Goblin, su doppelgänger. Desde que Quinn entró en el reino de los muertos, Goblin, otrora su sombra fiel, se ha convertido en una amenaza para los seres cercanos al atractivo gentleman. Lestat, intrigado, le pide a Quinn que narre la historia de su vida. Éste recuerda su infancia en el seno de una familia muy peculiar y describe sus días en Blackwood Farm, la mansión de altas columnas y extensos jardines rodeada de zonas pantanosas en la que creció y ahora reside. A pesar de su amor por Mona Mayfair, una bella bruja con la que mantiene una apasionada relación, Quinn posee una agitada vida amorosa que, junto a su imperioso deseo de beber sangre, le ha llevado a recorrer el mundo y conocer distintas épocas de la historia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (96, '9788477226765', 'La hora de las brujas Volumne 1', 1, '1992', 333, 'The witching hour', 'media/core/9788477226765.jpg', 1, '2022-08-04 16:21:54.690102', '2022-08-04 16:21:54.690102', 72, 12, 6, 5, NULL, '', '0103', NULL, 9, NULL, NULL);
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (97, '9788477226772', 'La hora de las brujas Volumen 2', 1, '1992', 309, 'The witching hour', 'media/core/9788477226772.jpg', 1, '2022-08-04 16:24:00.234032', '2022-09-08 17:20:37.186269', 72, 12, 6, 5, NULL, '', '0103', NULL, 9, 'Rowan Mayfair, neurocirujana con poderes especiales, encuentra a un ahogado en la costa de California y le devuelve a la vida. Se enamoran y establecen una apasionada alianza para desentrañar el misterio del pasado de ella y dominar un don maligno que le ha sido conferido a él tras su accidente.', '');
