INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (103, '8423309835', '1984', 7, '1984', 305, '1984', 'media/core/sin-imagen_7YXlc2u_HfNAKON.jpg', 1, '2022-08-04 17:38:58.997990', '2024-03-01 16:27:04.761278', 94, 1, 6, 5, 'DestinoLibro', '', '0103', NULL, 55, 'Londres, 1984: el Gran Hermano controla hasta el último detalle de la vida privada de los ciudadanos. Winston Smith trabaja en el Ministerio de la Verdad reescribiendo y retocando la historia para un estado totalitario que somete de forma despiadada a la población, hasta que siente que no quiere contribuir más a este sistema perverso y decide rebelarse.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (104, '9788467274271', 'La apariencia de las cosas', 1, '2018', 500, 'All Things Cease to Appear', 'media/core/9788467274271.jpg', 1, '2022-08-04 17:42:37.689975', '2022-08-04 17:42:37.689975', 95, NULL, 6, 5, NULL, '', '0103', NULL, 5, NULL, NULL);
