INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (113, '9788440641748', 'El ladrón de cuerpos', 1, '1993', 438, 'The Tale of the Body Thief', 'media/core/9788440641748.jpg', 1, '2022-08-05 08:36:25.099813', '2022-09-08 17:16:29.004236', 72, 12, 6, 5, NULL, '', '0103', NULL, 8, 'Un gran best seller de la autora de Confesiones de un vampiro Con esta nueva perla de su hipnótica narrativa, Anne Rice continúa sus extraordinarias Crónicas vampíricas iniciadas con las Confesiones de un vampiro y continuadas con Lestat, el vampiro y La reina de los condenados. Durante siglos, Lestat ha sido el príncipe incontestado en el universo oscuro y floreciente de los muertos vivientes. Está solo. De pronto, toda la razón de su existencia vampírica es puesta en cuestión. En su necesidad irreprimible de acabar con sus dudas y su soledad, Lestat se embarca en la empresa más peligrosa que ha emprendido en todos los años de su larga existencia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (114, '9788440673916', 'El sirviente de los huesos', 1, '1997', 421, 'Servant of the Bones', 'media/core/9788440673916.jpg', 1, '2022-08-05 08:38:37.620153', '2022-08-05 08:38:37.620153', 72, 12, 6, 5, NULL, '', '0103', NULL, 8, NULL, NULL);
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (115, '8466611320', 'Sangre y oro', 1, '2003', 517, 'Blood and Gold', 'media/core/8466611320.jpg', 1, '2022-08-05 10:03:07.104571', '2022-09-08 17:27:31.010151', 72, 12, 6, 5, 'La Trama', '', '0103', NULL, 8, 'Hay heridas que pueden quedar abiertas durante siglos. Deseoso de poner fin a ese dolor, asediado por los recuerdos, Marius siente que ha llegado el momento de revelar los secretos más íntimos de su milenaria existencia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (116, '9788440650160', 'La voz del Diablo', 1, '1994', 622, 'Lasher', 'media/core/9788440650160.jpg', 1, '2022-08-05 10:06:06.876651', '2022-08-05 10:06:06.876651', 72, 12, 6, 5, NULL, '', '0103', NULL, 8, NULL, NULL);
