INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (118, '9788440688293', 'Violín', 1, '1998', 346, 'Violin', 'media/core/sin-imagen_7YXlc2u_ElDPLFp.jpg', 1, '2022-08-05 10:12:04.958601', '2022-09-08 17:28:12.384686', 72, 12, 6, 5, 'La Trama', '', '0103', NULL, 8, 'Un misterioso violinista aparece cada día frente a la casa de Triana y toca para ella. Triana que está pasando por unos momentos muy difíciles a causa de la muerte de su esposo interpreta este hecho como una casualidad afortunada', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (119, '9788440694669', 'Pandora', 5, '2001', 303, 'Pandora', 'media/core/9788440694669.jpg', 1, '2022-08-05 10:14:21.558144', '2022-09-08 17:26:36.373941', 72, 12, 6, 5, 'La Trama', '', '0103', NULL, 8, 'El vampiro David Talbot invita a Pandora su igual a rememorar sus casi dos mil años de existencia. Pandora inicia su relato remontándose a su infancia mortal en el seno de una familia de patricios romanos para adentrarse luego en su vida de adulta durante la cual tuvo que huir precipitadamente de Roma y buscar refugio en Antioquía donde acabó subyugada por su gran amor Marius.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (120, '9788477220190', 'La Momia o Ramses el Condenado', 1, '1991', 444, 'The Mummy or Ramses the Damned', 'media/core/sin-imagen_hOdNddk.jpg', 1, '2022-08-05 10:18:13.680880', '2022-09-08 17:20:10.630411', 72, 12, 6, 5, NULL, '', '0103', NULL, 9, 'La trama se desarrolla en Londres, a comienzos del siglo XX, y trata del conflicto entre la familia de un arqueólogo británico y una momia loca sedienta de sangre', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (121, '9788408193296', 'Los Señores del Tiempo Vol. III', 1, '2018', 441, NULL, 'media/core/9788408193296.jpg', 1, '2022-08-05 10:24:06.624626', '2022-08-05 10:34:23.521120', 101, 1, 6, 5, NULL, '', '0103', 'Trilogía de la Ciudad Blanca', 7, NULL, NULL);
