INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (135, '9788466606608', 'Merrick', 1, '2002', 414, 'Merrick', 'media/core/9788466606608.jpg', 1, '2022-08-05 11:22:09.889066', '2022-09-08 17:24:17.622654', 72, 12, 6, 5, 'La Trama', '', '0103', NULL, 8, 'Merrick es una bellísima descendiente de les gens de couleur libres, una casta orientada a las prácticas y rituales del vudú, que surgió en Nueva Orleáns del turbio mestizaje entre las mujeres africanas y los colonizadores franceses. La joven no sabe aún que ha heredado los extraoridinarios poderes con los que sus antecesoras, las brujas de Mayfair, se hicieron famosas en otra época. A ese mundo de oscuros exotismos llega el vampiro David Talbot, procedente del reino de las tinieblas. Es él quien relata la fascinante historia de Merrick,INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (136, '9788432234446', 'Los tiempos del odio', 1, '2018', 399, NULL, 'media/core/9788432234446.jpg', 1, '2022-08-05 11:30:00.404770', '2022-08-05 11:30:00.404770', 38, 1, 6, 5, 'Biblioteca furtiva', '', '0103', NULL, 13, NULL, NULL);
