INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (139, '9788420435473', 'Sidi. Un relato de frontera', 4, '2019', 369, NULL, 'media/core/9788420435473.jpg', 1, '2022-08-05 11:38:30.411917', '2022-09-08 17:37:51.845145', 73, 1, 6, 5, NULL, '', '0103', NULL, 10, 'El arte del mando era tratar con la naturaleza humana, y él había dedicado su vida a aprenderlo. Colgó la espada del arzón, palmeó el cuello cálido del animal y echó un vistazo alrededor: sonidos metálicos, resollar de monturas, conversaciones en voz baja. Aquellos hombres olían a estiércol de caballo, cuero, aceite de armas, sudor y humo de leña.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (140, '9788467269895', 'Cáscara de nuez', 1, '2017', 194, 'Nutshell', 'media/core/9788467269895.jpg', 1, '2022-08-05 11:41:00.426876', '2023-03-14 09:01:51.049127', 116, 1, 6, 5, NULL, '', '0103', NULL, 5, '', '');
