INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (158, '9788496326927', 'La negra señora. Antropología de la muerte y el luto', 1, '2006', 505, 'La nera signora', 'media/core/9788496326927.jpg', 1, '2022-08-05 17:14:29.007670', '2022-09-08 17:04:51.927362', 129, 2, 6, 5, NULL, '', '0104', NULL, 62, 'Aceptar la muerte como el único acontecimiento ineluctable de la existencia no ha sido nunca, en ninguna cultura y en ninguna época histórica, un hecho natural. En estas páginas, Alfonso M. di Nola recorre la inmensa variedad de experiencias humanas que se oponen a la actitud laica ante la muerte y fían la suerte final al juego de las esperanzas. De los pueblos ágrafos a la sociedad contemporánea, este libro reconstruye e interpreta las técnicas del duelo, que garantizan la continuidad de la historia y transforma el carácter inaceptable del suceso fisiológico en un recuerdo reconfortante.', '');
