INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (170, '9788467221824', 'El Mesías. El niño judío', 1, '2006', 293, NULL, 'media/core/9788467221824.jpg', 1, '2022-08-06 17:34:14.380662', '2022-09-08 17:15:49.267262', 72, 1, 5, 5, NULL, '', '0104', NULL, 5, 'Anne Rice abandona momentáneamente las historias de vampiros para adentrarse en la vida de Jesucristo concretamente en los primeros años de vida de éste. La autora cede la palabra al propio Jesús quien con la voz de un niño de siete años narra sus primeros recuerdos en Alejandría y su traslado poco tiempo después y junto a su familia a Nazaret. Es la primera parte de una trilogía que podría relevarse polémica: en un sueño Jesús el niño narrador se encuentra con Satán. Una obra con la que Rice arriesgó su carrera literaria adentrándose en una historia que nada tenía que ver con lo que sus miles de seguidores esperaban', '');
