INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (174, '9788422661641', 'La piel del tambor', 1, '1995', 473, NULL, 'media/core/9788422661641.jpg', 1, '2022-08-06 17:47:25.188994', '2022-09-08 17:37:08.178223', 73, 1, 6, 5, NULL, '', '0104', NULL, 5, 'Un pirata informático que se infiltra en el Vaticano. Una iglesia barroca, en Sevilla, que mata para defenderse. Tres pintorescos malvados que aspiran a mantener viva la copla española. Una bella aristócrata andaluza. Un apuesto sacerdote-agente especialista en asuntos sucios. Un banquero celoso y su secretario ludópata. Una septuagenaria que bebe Coca-cola. La tarjeta postal de una mujer muerta un siglo atrás. Y el misterioso legado del capitán Xaloc, último corsario español, desaparecido frente a las costas de Cuba en 1898. Con esos ingredientes, Arturo Pérez-Reverte construye en La piel del tambor una ingeniosa, compleja y fascinante trama novelesca', '');
