INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (192, '9788467209068', '2666', 1, '2004', 1119, NULL, 'media/core/9788467209068.jpg', 1, '2022-08-08 16:44:12.489835', '2024-02-23 10:09:49.989780', 154, 1, 6, 5, NULL, '', '0104', NULL, 5, 'A cuatro profesores de literatura, Jean-Claude Pelletier (francés), Piero Morini (italiano), Manuel Espinoza (español) y Liz Norton (inglesa), los une su común fascinación por la obra de Beño von Archimboldi, un enigmático escritor alemán cuyo prestigio crece en todo el mundo. La complicidad entre los cuatro adquiere pronto trazas de vodevil intelectual y cosmopolita -con ménage á trois incluido-, y desemboca en un disparatado peregrinaje a Santa Teresa (trasunto de Ciudad Juárez), en la frontera de México con Estados Unidos, donde hay quien dice que Archimboldi ha sido visto. Ya en Santa Teresa, Pelletier y Espinoza se enteran de que la ciudad viene siendo desde años atrás escenario de una larga cadena de crímenes atroces. En los vertederos de la ciudad no cesan de aparecer los cadáveres de mujeres, muchas de ellas apenas adolescentes, con señales de haber sido salvajemente violadas y torturadas. Es el primer asomo de la novela al agujero negro en que terminarán por precipitarse sus múltiples y procelosos caudales, repletos de personajes memorables cuyas historias, a caballo siempre entre la risa y el horror, abarcan dos continentes e incluyen, entre muchas otras cosas, un vertiginoso travelling por la historia europea del siglo XX, por las ruinas de una cultura y una civilización en derrota en las que la literatura continúa invocando un simulacro de salvación. Resulta imposible sugerir siquiera la enormidad y las profundidades de un libro que se construye como una novela empotrada en otra novela empotrada a su vez en otra novela... y que se abre así camino en lo desconocido, allí donde -como dice uno de los personajes- tienen lugar «los combates de verdad, en donde los grandes maestros luchan contra aquello, ese aquello que nos atemoriza a todos, ese aquello que acoquina y encacha, y hay sangre y heridas mortales y fetidez».', NULL);
