INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (273, '9788420405551', 'El asedio', 1, '2010', 725, NULL, 'media/core/9788420405551.jpg', 1, '2022-08-17 17:41:51.178130', '2022-09-08 17:32:45.063862', 73, 1, 6, 5, NULL, '', '0106', NULL, 10, 'Cádiz, 1811. España lucha por su independencia mientras América lo hace por la suya. En las calles de la ciudad más liberal de Europa se libran batallas de otra índole. Mujeres jóvenes aparecen desolladas a latigazos. En cada lugar, antesINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (274, '9788420472805', 'Un día de cólera', 1, '2007', 394, NULL, 'media/core/9788420472805.jpg', 1, '2022-08-17 17:43:36.301628', '2022-09-08 17:38:28.375282', 73, 1, 6, 5, NULL, '', '0106', NULL, 10, 'Este relato no es ficción ni libro de Historia. Tampoco tiene un protagonista concreto, pues fueron innumerables los hombres y mujeres envueltos en los sucesos del 2 de mayo de 1808 en Madrid. Héroes y cobardes, víctimas y verdugos, la Historia retuvo los nombres de buena parte de ellos: las relaciones de muertos y heridos, los informes militares, las memorias escritas por actores principales o secundarios de la tragedia, aportan datos rigurosos para el historiador y ponen límites a la imaginación del novelista. Cuantas personas y lugares aparecen aquí son auténticos, así como los sucesos narrados y muchas de las palabras que se pronuncian.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (275, '9788408055174', 'Assassini', 4, '2004', 646, 'The Assassini', 'media/core/9788408055174.jpg', 1, '2022-08-17 17:45:38.703736', '2022-08-17 17:45:38.703736', 206, 1, 6, 5, 'Internacional', '', '0106', NULL, 7, NULL, '');
