INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (279, '9788408066262', 'Un lugar llamado Nada', 1, '2006', 473, 'Saving Fish from Drowning', 'media/core/9788408066262.jpg', 1, '2022-08-17 17:56:49.119113', '2022-09-08 17:06:17.701993', 210, 1, 6, 5, 'Internacional', '', '0106', NULL, 7, 'Doce amigos estadounidenses están a punto de emprender el viaje de su vida desde el pie del Himalaya en China hacia las selvas inexploradas de Brimania para profundizar en el arte y la cultura de ambos países. La mañana del día de Navidad, todos menos uno inician una excursión de medio día, pero ya no regresan. Se encuentran en medio de la selva, en un poblado secreto donde se oculta una tribu medio extinguida que ve en uno de ellos a su salvador.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (280, '9788467262544', 'Espereando al Rey', 1, '2014', 470, NULL, 'media/core/9788467262544.jpg', 1, '2022-08-17 17:59:25.644233', '2022-08-17 17:59:25.644233', 211, 1, 6, 5, NULL, '', '0106', NULL, 5, NULL, '');
