INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (282, '9788496463219', 'Memorias de una geisha', 1, '2006', 548, 'Momoirs of a Geisha', 'media/core/9788496463219.jpg', 1, '2022-08-17 18:03:59.316749', '2022-09-08 17:31:02.512850', 212, 1, 6, 5, NULL, '', '0106', NULL, 27, 'En Memorias de una geisha Arthur Golden abre una ventana a al hermético y misterioso mundo de las geishas de Kyoto, donde la sensualidad y la belleza se dan la mano con la degradación y el sometimiento. Poco antes de su muerte, Sayuri relata a un amigo su atribulada y fascinante vida: cómo, desde una mísera infancia, llegó a convertirse en una de las geishas más famosas del Japón de entreguerras, un país en el que aún resonaban los ecos feudales y donde las tradiciones ancestrales empezaban a convivir con los modos del mundo moderno', '');
