INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (290, '9788467217759', 'Las olvidadas. Una historia de mujeres creadoras', 1, '2005', 272, NULL, 'media/core/9788467217759.jpg', 1, '2022-08-18 16:43:11.777313', '2022-09-08 17:12:06.767123', 220, 31, 6, 5, NULL, '', '0106', NULL, 5, 'Las olvidadas una historia de mujeres creadoras', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (291, '9788467253160', 'Donde se alzan los tronos. La historia de una mujer que quiso ser rey', 1, '2012', 285, NULL, 'media/core/9788467253160.jpg', 1, '2022-08-18 16:45:46.118666', '2022-09-08 17:11:10.657298', 220, 16, 6, 5, NULL, '', '0106', NULL, 5, 'Cuando Carlos II, El hechizado, muere sin descendencia, afloran infinidad de pretendientes al trono de España. Tras una serie de conspiraciones e intrigas palaciegas, se impone como nuevo rey el duque de Anjou, nieto del rey Sol, que llevará el nombre de Felipe V. Comienza así una época convulsa y apasionante en la que una mujer, la princesa de los Ursinos, será la poseedora de todas las claves para alzarse con el poder.Ángeles Caso nos envuelve con una magnífica historia de vanidad, de ambición, de codazos en la corte, alianzas, conspiraciones y sexo, cargada de fina ironíay gran semejanza con la actualidad', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (292, '9788408144700', 'Todo ese fuego', 1, '2015', 254, NULL, 'media/core/9788408144700.jpg', 1, '2022-08-18 16:47:30.276061', '2022-09-08 17:12:38.307484', 220, 1, 6, 5, 'Autores españoles e iberoamericanos', '', '0106', NULL, 7, '16 de julio de 1846. En la casa parroquial del pueblecito inglés de Haworth, las tres hijas del pastor comienzan la jornada ocupándose de las tareas domésticas mientras esperan que llegue la tarde, cuando puedan sentarse juntas para dedicarse a escribir a escondidas las novelas que ansían publicar. Son las hermanas Brontë, tres mujeres solteras de alrededor de treinta años que, desde la infancia, gracias a la literatura, han sobrevivido a las tragedias familiares, la falta de recursos económicos y el aislamiento.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (293, '9788467270310', 'El libro de los espejos', 1, '2017', 305, 'The Book of Mirrors', 'media/core/9788467270310.jpg', 1, '2022-08-18 17:09:42.361981', '2022-08-18 17:09:42.361981', 221, 1, 6, 5, NULL, '', '0106', NULL, 5, NULL, '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (294, '9788433966858', 'Posesión', 1, '2001', 542, 'Possession. A Romance', 'media/core/9788433966858_OhB4s9y.jpg', 1, '2022-08-18 17:13:09.929815', '2022-09-08 17:00:25.817266', 222, 1, 6, 5, 'Compactos', '', '0106', NULL, 6, 'Un oscuro graduado en literatura inglesa descubre dos cartas inconclusas y nunca enviadas del eminente victoriano randolph Henry Ash, cuya destinataria era una mujer que posiblemente fuese su amante. La mujer es Christabel LaMotte, oscura y ambigua poetisa de la época, reivindicada en la actualidad por feministas y lesbianas. Si realmente existió una relación entre ambos, ha hecho un descubrimiento que puede catapultar su carrera académica. Ayudado por una seductora especialista en la obra de la poetisa, seguirá el rastro a través de diversos documentos y reconstruirá una historia de pasiones que encontrará su peculiar espejo en el presente.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (295, '9788420455488', 'Las Doncellas', 1, '2021', 321, 'The Maidens', 'media/core/9788420455488.jpg', 1, '2022-08-18 17:15:32.460740', '2022-09-08 17:03:03.352716', 223, 1, 6, 5, 'Negra Alfaguara', '', '0106', NULL, 10, 'A sus treinta y seis años, Mariana intenta recuperarse de la pérdida de Sebastian, el gran amor de su vida, ahogado durante unas vacaciones en una isla griega. Ella trabaja en Londres como terapeuta, pero cuando su sobrina Zoe, la única familia que le queda, la llama desde Cambridge para contarle que Tara, su mejor amiga, ha sido brutalmente asesinada cerca de la residencia de estudiantes, decide acudir en su ayuda.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (296, '9788423935826', 'Es fácil dejar de fumar, si sabes cómo', 1, '2010', 212, 'The Easy Way to Stop Smoking', 'media/core/9788423935826.jpg', 1, '2022-08-18 17:19:02.573914', '2022-09-08 17:05:18.912922', 224, 20, 6, 5, NULL, '', '0106', NULL, 18, 'Allen Carr escribió este libro para ayudar a los fumadores que no podían acudir a su exitosa charla EASYWAY. Desde 1985 se han vendido millones de ejemplares en todo el mundo y ha sido traducido a más de veinticinco idiomas.Reconocido mundialmente como el sistema más eficaz para dejar de fumar, EASYWAY tiene un programa empresarial que en España ha sido adoptado por diversas empresas como MERCEDES BENZ, AENA, FRIGO, FRUDESA, CAIXA CATALUÑA e IBERDROLA. El metodo EASYWAY consigue un 70% de exito anual como promedio, lo que le sitúa muy por encima de otros metodos para dejar de fumar. Quien sigue el metodo EASYWAY no sólo dejará de fumar inmediatamente, sino que lo encontrará fácil y disfrutará del proceso. Funciona para todos, incluso para el fumador empedernido, y no requiere ningún tipo de sustitutivo, medicamento o truco. Cualquiera que siga sus intrucciones se mantendrá como no fumador y estará feliz de serlo durante el resto de su vida. www.esfacil.espasa.com', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (297, '9788479539535', 'El poder de la presencia', 2, '2016', 346, 'Presence - Bringing your boldest self to your biggest challenges', 'media/core/9788479539535.jpg', 1, '2022-08-18 17:22:20.132490', '2022-09-08 17:05:53.845795', 225, 20, 6, 5, NULL, '', '0106', NULL, 53, 'Amy Cuddy, reconocida psicóloga social y profesora de Harvard, afirma que no es necesario experimentar una epifanía espiritual o esforzarse por alcanzar una profunda transformación interior para dominar la presencia. En cambio, nos ofrece estrategias muy sencillas para dejar atrás las aprensiones y estar psicológicamente presentes en los desafíos cotidianos una entrevista de trabajo, una conversación difícil, una charla en público, una cita, una actuación recurriendo a nuestro mejor aliado: el cuerpo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (298, '9788408235514', 'Aquitania', 10, '2021', 407, NULL, 'media/core/9788408235514.jpg', 1, '2022-08-18 17:24:09.378008', '2022-08-18 17:24:09.378008', 101, 16, 6, 5, 'Autores españoles e iberoamericanos', '', '0106', NULL, 7, NULL, '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (299, '9788418859014', 'El legado de Maude Donegal // El hijo superviviente', 1, '2022', 279, 'Cardiff, by the Sea // The Surviving Child', 'media/core/9788418859014.jpg', 1, '2022-08-18 17:27:20.809841', '2022-08-18 17:27:20.809841', 226, 22, 6, 5, 'Nuevos tiempos', '', '0106', NULL, 16, NULL, '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (300, '9788409300129', 'Carrion. Un canalla sin ventura', 1, '2021', 268, NULL, 'media/core/9788409300129.jpg', 1, '2022-08-18 17:36:20.435223', '2022-09-08 17:10:23.896800', 227, 1, 6, 5, NULL, '', '0106', NULL, 63, 'Una aventura marítima hasta el fin del mundo en pleno siglo XVI, que demuestra cómo el rigor documental puede ir de la mano de una trama ágil y apasionante, llena de acción, humor y un lenguaje de época genuino cargado de improperios. Un viaje épico junto a personajes de la talla del Elcano o Urdaneta, a través del estrecho de Magallanes, la batalla de Villalar o las islas de las Especias. Sumérgete en el relato de un viejo soldado con salitre en las venas, Juan Pablo de Carrión, y acompáñale en sus sufridas gestas y sus holgadas infamias. Para amantes de la novela histórica o la novela clásica de aventuras que busquen un libro emocionante, divertido y diferente; acompañado de increíbles ilustraciones, mapas y grabados de época. ''Carrión'' ha sido el mayor crowdfunding para una novela en España. Del guionista de ''Lezo'' (Premio Popular del Salón de Barcelona 2021) y ''Espadas del fin del mundo''. ''Un canalla sin ventura'' es la primera parte de una trilogía.', 'Es una caja con mapas, tarjetas,...');
