INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (336, '8422643979', 'Posesión', 1, '1992', 572, 'Possession A Romance', 'media/core/8422643979.jpg', 1, '2022-08-30 08:26:41.602501', '2022-09-08 17:00:35.201558', 222, 1, 6, 5, NULL, '', '02_01', NULL, 5, 'Un oscuro graduado en literatura inglesa descubre dos cartas inconclusas y nunca enviadas del eminente victoriano randolph Henry Ash, cuya destinataria era una mujer que posiblemente fuese su amante. La mujer es Christabel LaMotte, oscura y ambigua poetisa de la época, reivindicada en la actualidad por feministas y lesbianas. Si realmente existió una relación entre ambos, ha hecho un descubrimiento que puede catapultar su carrera académica. Ayudado por una seductora especialista en la obra de la poetisa, seguirá el rastro a través de diversos documentos y reconstruirá una historia de pasiones que encontrará su peculiar espejo en el presente.', '');
