INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (420, '9788435006071', 'El Señor de los últimos días', 1, '1994', 262, NULL, 'media/core/9788435006071.jpg', 1, '2022-09-08 16:43:14.991316', '2022-09-08 16:43:14.991316', 321, 16, 6, 5, 'Narrativas históricas', '', '02_03', NULL, 47, NULL, 'A comienzos del año 1000, el monje Alfonso de León ve un cometa que presagia la venida del anticristo y los más prodigiosos fenómenos. A partir de ahí, el escritor mexicano Homero Aridjis despliega un maravilloso fresco de la España medieval.');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (421, '9788492695065', 'Nadie lo ha oído', 1, '2009', 270, 'I denna stilla natt', 'media/core/9788492695065.jpg', 1, '2022-09-08 16:46:09.223693', '2022-09-08 16:46:09.223693', 322, 14, 6, 5, NULL, '', '02_03', NULL, 20, NULL, 'Cuando el fotógrafo alcohólico Henry Dahlström aparece asesinado en pleno centro de Gotland, las pesquisas policiales apuntan directamente a algunos de sus compañeros de juerga. El caso no parece revestir mayor misterio, hasta que el comisario Anders Knutas descubre que el fallecido recibió una importante cantidad de dinero el día anterior a su muerte. Paralelamente, la señora Jannson denuncia la desaparición de su hija Fanny, de catorce años, y la policía inicia inmediatamente la investigación de este supuesto caso de secuestro. Sin embargo, la investigación da un giro inesperado cuando el portero del piso de Dahlström descubre una caja con fotos de carácter pederasta en las que aparece la joven Fanny. Knutas necesitará todo su talento y la ayuda de su amigo periodista Johan Berg para descubrir qué se esconde detrás de este terrible caso.');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (422, '9788496284050', 'El secreto de Monna Lisa', 1, '2004', 453, NULL, 'media/core/9788496284050.jpg', 1, '2022-09-08 16:48:46.357746', '2022-09-08 16:48:46.357746', 323, 16, 6, 5, NULL, '', '02_03', NULL, 30, NULL, 'En su primera novela, Dolores García consigue acercarnos a lo que podría haber sido el lado desconocido del genio florentino Leonardo Da Vinci. A través de su narrador -Francesco Melzi, un discípulo de Da Vinci-, asistimos a las últimas horas de Leonardo, en la corte del rey francés, Luís XII. Melzi, intrigado por la razón por la que el maestro está obsesionado con su obra La Gioconda, la única que le ha acompañado en todos sus viajes, le pide que le explique su historia. Da Vinci empezará entonces el fascinante relato de su vida, desde el momento en que se ve obligado a huir de Milán tras la caída del poder de Ludovico I, El Moro su mecenas, y volver a su Florencia natal, en donde conocerá a un ser fascinante que cambiará su vida: Lisa Gherardini, la Monna Lisa.');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (423, '9788440658333', 'La granja de cuerpos', 1, '1995', 349, 'The Body farm', 'media/core/9788440658333.jpg', 1, '2022-09-08 16:54:10.655307', '2022-09-08 16:54:10.655307', 324, 14, 6, 5, 'Éxito internacional', '', '02_03', 'Kay Sacarpetta', 8, NULL, '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (424, '9788481092820', 'La peligrosa idea de Darwin', 1, '1999', 876, 'Darwin''s Dangerous Idea', 'media/core/9788481092820.jpg', 1, '2022-09-09 15:27:03.559759', '2022-09-09 15:27:03.559759', 325, 15, 6, 5, NULL, '', '02_03', NULL, 46, 'A pesar de haber sido sometida al continuo acoso de quienes han tratado de limitar o negar sus implicaciones, la teoría darwiniana de la evolución por selección natural, una de las más controvertidas de todos los tiempos, se mantiene vigente y abierta a nuevas interpretaciones y desarrollos.El autor describe con gran agudeza la teoría de Darwin y extiende sus argumentos hasta sus últimas y sorprendentes consecuencias. El lector tiene en sus manos una de las más profundas reflexiones sobre la significación intelectual del darwinismo, un audaz, innovador y atractivo análisis sobre el efecto de renovación que la teoría de Darwin ha supuesto en nuestra actual visión del mundo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (425, '9788422662372', 'Historia de los Griegos', 1, '1996', 311, 'Storia dei Greci', 'media/core/9788422662372.jpg', 1, '2022-09-09 15:30:59.188154', '2022-09-09 15:30:59.188154', 326, 2, 6, 5, NULL, '', '02_03', NULL, 96, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (426, '9788423355747', 'Vida, la gran historia', 3, '2019', 546, NULL, 'media/core/9788423355747.jpg', 1, '2022-09-09 15:33:53.489378', '2022-09-09 15:33:53.489378', 287, 15, 6, 5, 'Imago Mundi', '', '02_03', NULL, 59, 'El mayor viaje a la vida desde su aparición en la Tierra hasta hoy, contado por su mayor conocedor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (427, '9788499928081', 'Homo Deus. Breve historia del mañana', 1, '2017', 428, 'Homo Deus. A Brief History of Tomorrow', 'media/core/9788499928081.jpg', 1, '2022-09-09 15:55:01.618128', '2022-09-09 15:55:01.618128', 291, 2, 6, 5, NULL, '', '02_03', NULL, 97, 'Tras el éxito deSapiens, Yuval Noah Harari vuelve su mirada al futuro para ver hacia dónde nos dirigimos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (428, 'CAT_CAL_GUL', 'Museu Calouste Gulbenkian Catálogo', 1, '1982', 1, NULL, 'media/core/sin-imagen_EPrAJQ0.jpg', 1, '2022-09-09 16:00:18.947843', '2022-09-09 16:00:18.947843', 327, 18, 6, 5, NULL, '', '02_03', NULL, 98, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (429, '9788467235166', 'Roma y los bárbaros. Una historia alternativa', 1, '2008', 397, 'An Alternative Roman History', 'media/core/9788467235166.jpg', 1, '2022-09-09 16:06:31.992618', '2022-09-09 16:06:31.992618', 328, 2, 6, 5, NULL, '', '02_03', NULL, 99, 'Este es un libro sorprendente y divertido. No podía ser de otro modo tratándose de una obra de Terry Jones, el director de películas de los Monty Phyton como La vida de Brian. Pero es también un libro serio, que, como ha dicho el profesor Cunliffe, de la Universidad de Oxford, “restablece el equilibrio y sitúa a los romanos en una perspectiva correcta”. Escrito con pasión e irreverencia, pero basado en los resultados más recientes de la investigación histórica, su propósito esINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (430, '9788422662983', 'Historia de Roma', 1, '1994', 386, 'Stroia di Roma', 'media/core/sin-imagen_mzHwoqP.jpg', 1, '2022-09-09 16:08:57.062848', '2022-09-09 16:10:21.313661', 326, 11, 5, 5, NULL, '', '02_03', NULL, 96, 'Historia de Roma ofrece una serie de retratos apasionantes y veraces que iluminan en sus justos terminos a los protagonistas de aquella epoca irrepetible.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (431, '9788449303661', 'El choque de civilizaciones (y la reconfiguración del orden mundial)', 1, '1997', 386, 'The clash of civilizations and the remanking of world order', 'media/core/9788449303661.jpg', 1, '2022-09-09 16:14:55.216770', '2022-09-09 16:14:55.216770', 329, 2, 6, 5, 'Estado y Sociedad', '', '02_03', NULL, 100, 'El presente libro, basado en un influyente artículo que ha configurado la totalidad de los debates políticos de estos últimos años (Foreign Policy), es un informe incisivo y profético, en la línea del Francis Fukuyama de El fin de la historia, sobre las distintas formas adoptadas por la política mundial tras la caída del comunismo. La fuente fundamental de conflictos en el universo posterior a la guerra fría, según Huntington, no tiene raíces ideológicas o económicas, sino más bien culturales: El choque de civilizaciones dominará la política a escala mundial; las líneas divisorias entre las civilizaciones serán los frentes de batalla del futuro. Y, a medida que la gente se vaya definiendo por su etnia o su religión, Occidente se encontrará más y más enfrentado con civilizaciones no occidentales que rechazarán frontalmente sus más típicos ideales: la democracia, los derechos humanos, la libertad, la soberanía de la ley y la separación entre la Iglesia y el Estado. Así, Huntington -al tiempo que presenta un futuro lleno de conflictos, gobernado por unas relaciones internacionales abiertamente desoccidentalizadas- acaba recomendando un más sólido conocimiento de las civilizaciones no occidentales, con el fin, paradójicamente, de potenciar al máximo la influencia occidental, ya sea a través del fortalecimiento de las relaciones entre Rusia y Japón, del aprovechamiento de las diferencias existentes entre los estados islámicos o del mantenimiento de la superioridad militar en el este y el sudeste asiáticos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (432, '9788422695349', 'La inmigración explicada a mi hija', 1, '2001', 131, 'L''immigration expliquée à ma fille', 'media/core/9788422695349.jpg', 1, '2022-09-09 16:20:05.783310', '2022-09-09 16:20:05.783310', 330, 2, 6, 5, NULL, '', '02_03', NULL, 96, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (433, '9788422695356', 'El Islam explicado a nuestros hijos', 1, '2002', 93, 'L''Islam expliqué aux enfants', 'media/core/9788422695356.jpg', 1, '2022-09-09 16:25:39.526830', '2022-09-09 16:25:39.526830', 331, 2, 6, NULL, NULL, '', NULL, NULL, 101, 'El 11 de Septiembre de 2001, un atentado golpea el mundo Occidental. Dos aviones se estrellan contra las Torres Gemelas de Manhattan; Am:amp;#233;rica est:amp;#225; consternadas y los medios de comunicaci:amp;#243;n no cesan de emitir im:amp;#225;genes de guerra; el miedo a un nuevo ataque terrorista se propaga y todos los :amp;#225;rabes se convierten en sospechosos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (434, '8422627159', 'Historia del tiempo. Del Big bang a los agujeros negros', 1, '1988', 280, 'A Brief History of Time', 'media/core/8422627159.jpg', 1, '2022-09-09 16:29:46.547911', '2022-09-09 16:29:46.547911', 332, 2, 6, 5, NULL, '', '02_03', NULL, 5, '" Historia del tiempo " es un libro de divulgación sobre el espacio y el tiempo escrito por uno de los físicos teóricos más prestigiosos de la actualidad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (435, '9788422673095', 'Viajes por Marruecos', 1, '1998', 538, NULL, 'media/core/9788422673095.jpg', 1, '2022-09-09 16:33:18.947272', '2022-09-09 16:33:18.947272', 333, 28, 6, 5, NULL, '', '02_03', NULL, 5, 'Viajes por Marruecos, uno de los títulos insignia de la Biblioteca Grandes Viajeros, narra las peripecias de Domingo Badía, Alí Bey, por el norte de África a principios del siglo XIX. Explorador, aventurero y agente de la corona española, según la leyenda Domingo Badía Leblich, más conocido como Alí Bey, recorrió todo el norte de África haciéndose pasar por un príncipe musulmán y fue el primer europeo en visitar y describir La Meca. Su singular peripecia, relatada con rigurosa atención al detalle y abundantes pinceladas de humor, alcanzó enorme éxito al publicarse en 1814, pero había sido deformada por motivos políticos y por la fantasía de sus contemporáneos.Salvador Barberá, autor de la presente edición, sigue paso a paso el itinerario de Alí Bey, examinando sobre el terreno la exactitud de sus observaciones, y ofrece una versión rigurosa y contrastada de su fascinante aventura.', 'Incluye mapa');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (436, '9788491814122', 'Circe', 1, '2019', 441, NULL, 'media/core/9788491814122.jpg', 1, '2022-09-09 16:38:24.054660', '2022-09-09 16:38:24.054660', 334, 1, 6, 5, 'Alianza de Novelas', '', '02_03', NULL, 69, 'En el palacio de Helios, dios del sol y el más poderoso de los titanes, nace una niña. Pero Circe es una niña rara: carece de los poderes de su padre y de la agresiva capacidad de seducción de su madre. Cuando acude al mundo de los mortales en busca de compañía, descubre que sí posee un poder, el poder de la brujería, con el que puede transformar a sus rivales en monstruos y amenazar a los mismísimos dioses.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (437, '9788498157710', 'Los Omeyas y la formación de Al-Ándalus Vol VI', 1, '2008', 478, 'Conquistadores, emires y califas', 'media/core/9788498157710.jpg', 1, '2022-09-09 16:44:34.774663', '2022-09-09 16:44:34.774663', 335, 11, 6, 5, NULL, '', '02_03', 'Historia de España', 102, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (438, '9788422698043', 'Casadas, monjas, rameras y brujas. La olvidada historia de la mujer espñaola en el Renacimiento', 1, '2002', 326, NULL, 'media/core/9788422698043.jpg', 1, '2022-09-09 16:50:41.081747', '2022-09-09 16:50:41.081747', 336, 11, 6, 5, NULL, '', '02_03', NULL, 19, 'Hasta hace bien poco, los relatos de historia marginaban por completo a la mujer, como si ese pasado fuera obra exclusiva de los hombres, salvo en aquellos contados casos en que el protagonismo de la mujer era tan notorio que no podía dejarse de lado: tal era el de Isabel la Católica, tal el de Santa Teresa, tal el de la princesa de Éboli. Pero por lo demás, la mujer quedaba en la sombra, como si no hubiera existido. Manuel Fernández Álvarez saca ahora a la mujer española del Renacimiento de ese olvido. Ha querido verla en su vivir cotidiano, en los distintos papeles que le había tocado asumir, lo mismo los más honorables, como el de esposa o el de monja, como en aquellos otros más oscuros y dudosos, bordeando el desprecio social, cuando no al margen de la ley. Así van desfilando en la obra aquellas otras pobres mujeres marginadas, ya por la pobreza, ya por la raza, ya por su profesión: madres solteras, criadas, esclavas, conversas, moriscas y gitanas, e incluso las rameras y, por supuesto, las malditas, las más temidas y aborrecidas: las mismas brujas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (439, '9788417229276', 'Cuando ofuimos árabes', 1, '2018', 332, NULL, 'media/core/9788417229276.jpg', 1, '2022-09-09 16:53:53.721615', '2022-09-09 16:53:53.721615', 295, 11, 6, 5, 'Al-ándalus', '', '02_03', NULL, 68, 'Cuando fuimos árabes es una declaración de principios. Un libro al servicio de un consejo: que debemos habitar nuestra historia. El autor parte de la consideración de España como un territorio más antiguo que el concepto de estado-nación, y más acorde con la idea de nación-cultura de Menéndez Pelayo; es decir, un territorio habitado por sus textos y ajeno a las cristalizaciones jurídicas de sus habitantes. En esta ocasión, González Ferrín retoma su idea de la historia como continuidad y movimiento (desarrollada ya en su Historia general de Al Ándalus, así como en La angustia de Abraham, ambas publicadas por Almuzara) para personalizar una visión distinta de Al Ándalus. A lo largo del libro, el autor despliega su erudición en islamología (avalado por más de treinta años de estudio), y propone un necesario cambio de paradigma: la alteridad del islam es un constructo al servicio de una Europa cerrada, y puede y debe contrarrestarse desde España mediante una asimilación intelectual de todo cuanto implicó realmente el islam medieval en la Península; ese tiempo en que fuimos árabes... Porque el árabe fue el idioma culto de una España que legó al Renacimiento europeo nombres como Averroes o Abentofáil, sin los cuales hubiera sido difícil que la Ilustración naciera tal y cómo lo hizo. La complejidad de nuestra historia requiere acercamientos posmodernos para reconocer las fronteras líquidas de realidades como Europa y el islam, especialmente si está escrito desde una tierra europea en la que hubo un tiempo en que fuimos árabes.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (440, '9788422676188', 'La época de las catedrales. Arte y sociedad, 980-1420', 1, '1997', 334, 'Le temps des cathédrales. L''art et la societé, 980-1420', 'media/core/9788422676188.jpg', 1, '2022-09-09 16:58:12.363185', '2022-09-09 16:58:12.363185', 269, 11, 6, 5, NULL, '', '02_03', NULL, 103, 'Georges Duby sitúa las altas producciones del Occidente medieval en el movimiento general de la civilización y ofrece las claves para penetrar en este universo de formas fascinantes. Muestra cómo, en el siglo X, el gobierno de la producciónartíticapasa de manos de los reyes a las de los monjes; cómo, cien años más tarde, el renacimiento urbano establece la catedral como foco de las mayores innovaciones; y cómo, en el siglo XIV, la iniciativa artísitica vuelve a los príncipes y se abre a los valores profanos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (441, '9788408042341', 'Homínidos', 1, '2002', 344, 'Waiting', 'media/core/9788408042341.jpg', 1, '2022-09-09 17:01:43.911762', '2022-09-09 17:01:43.911762', 337, 1, 6, 5, 'Internacional', '', '02_03', NULL, 7, 'La vida de Arthur Banks da un giro inesperado cuando descubre la existencia de otra especie de homínidos que quiere terminar con la supremacía del hombre actual.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (442, '9788489367500', 'El arquitecto de Tombuctú. Es Saheli, el granadino', 1, '2008', 509, NULL, 'media/core/9788489367500.jpg', 1, '2022-09-09 17:04:21.937839', '2022-09-09 17:04:21.937839', 208, 1, 6, 5, NULL, '', '02_03', NULL, 25, '«Poeta soy, y la arquitectura es la poesía del barro y la piedra. Por eso, al igual que canto y recito, algún día os levantaré palacios y mezquitas...» En el año 1337, el granadino Abu Isaq Es Saheli llega a la ciudad de Fez como embajador de Kanku Mussa, emperador del Reino de los Negros. Tras ser recibido con todos los honores, es víctima de un complot contra su vida. En venganza, Fez declara la guerra a Tremecén, con el control de las rutas de caravanas como objetivo encubierto. Mientras se recupera, Es Saheli escribirá su propia Rihla, el relato de su vida de caminante: su infancia como hijo del alamín del gremio de los perfumeros de Granada, su atormentada juventud, el pronto éxito y los excesos de la bohemia, el doloroso exilio del reino nazarí, su viaje a El Cairo, su paso por Damasco, Bagdad, Yemen y La Meca, su pasión por la arquitectura egipcia? Hasta desembocar en su principal legado: la construcción de la gran mezquita de Tombuctú. La vida de Es Saheli es tan apasionante como la de León el Africano y otros genios medievales. Con El arquitecto de Tombuctú, Manuel Pimentel ha firmado mucho más que una brillante novela histórica, ya que sus páginas son toda una invitación a dejarse inundar por las fragancias, las pasiones y el espíritu de Al Andalus y el misterio sereno de África. Además, esta lectura nos da a conocer al padre del arte sudanés, el poeta granadino cuyas construcciones han servido de inspiración a otros genios como Antoni Gaudí y Miquel Barceló.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (443, '8475970125', 'Escritos sobre Jazz Vol II', 1, '1984', 324, 'Autres écrits sur le Jazz', 'media/core/8475970125.jpg', 1, '2022-09-09 17:09:01.928785', '2022-09-09 17:09:01.928785', 153, 2, 6, 5, NULL, '', '02_03', NULL, 104, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (444, '9788467252361', 'Por el bien del Imperio. Historia del Mundo desde 1945', 1, '2011', 1183, NULL, 'media/core/9788467252361.jpg', 1, '2022-09-09 17:12:33.605909', '2022-09-09 17:12:33.605909', 338, 11, 6, 5, NULL, '', '02_03', NULL, 105, '«Cuando se han cumplido ya setenta años de aquellas promesas la frustración no puede ser mayor», dice Fontana, que tenía catorce años en 1945. «No hay paz –Irak, Afganistán, Libia o Darfur dan testimonio de ello–, la extensión de la democracia es poco más que una apariencia y en algunos lugares ni siquiera eso.» De esa sensación de engaño nace este libro, un estudio ameno, minucioso y profundo que analiza el rumbo del mundo en los últimos setenta años: desde la Guerra Fría, el nuevo imperalismo, el experimento comunista y las revoluciones frustradas de la década de 1970 hasta la crisis financiera actual y las grandes amenazas como la sequía, el cambio climático o el terrorismo. Un libro imprescindible para entender nuestro presente y asomarnos a nuestro futuro.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (445, '9788437507231', 'El Capital en el siglo XXI', 1, '2014', 649, 'Le Capital au XXI siècle', 'media/core/9788437507231.jpg', 1, '2022-09-09 17:16:03.652976', '2022-09-09 17:16:03.652976', 339, 2, 6, 5, NULL, '', '02_03', NULL, 106, 'Para Thomas Piketty, los debates intelectuales y políticos sobre la distribución de la riqueza se han alimentado sobre todo de grandes prejuicios y de muy pocos datos. En ese campo de batalla han convergido ideas sobre la igualdad entre los ciudadanos, el derecho de las personas a ser retribuidas conforme a sus méritos, la confianza en que el crecimiento económico mitiga de manera natural los contrastes entre los más favorecidos y los francamente abandonados, pero la información concreta, referida a un plazo largo y a diversas geografías, no se había empleado con suficiente rigor para entender cómo se acumula el patrimonio, qué consecuencias sociales tiene ese proceso y qué pueden hacer los Estados para enfrentarlo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (446, '9788467236880', 'Memoorias de un beduino en el Congreso de los Diputados', 1, '2009', 226, NULL, 'media/core/9788467236880.jpg', 1, '2022-09-09 17:19:50.803098', '2022-09-09 17:19:50.803098', 340, 32, 6, 5, NULL, '', '02_03', NULL, 107, 'En Memorias de un beduino... José Antonio Labordeta recuerda su época como diputado en el Congreso de los Diputados por la Chunta Aragonesista (séptima y octava legislaturas), ofrece semblanzas de los políticos (Aznar, Zapatero, Acebes, Rubalcaba…) y brinda su versión sobre temas como las controversias que se crearon en varias emisoras de radio (la COPE, la SER…), el «No a la Guerra» o la Comisión del 11-M. Un recorrido por el Congreso de los Diputados por el político más querido de España.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (447, '9788491990604', 'La Civilización en la mirada', 1, '2019', 230, 'Civilizations. How do we look?/ The Eye of Faith', 'media/core/9788491990604.jpg', 1, '2022-09-09 17:23:21.882869', '2022-09-09 17:23:21.882869', 259, 11, 6, 5, NULL, '', '02_03', NULL, 7, 'Toda civilización se configura en torno a unas imágenes compartidas colectivamente. Sus miembros se caracterizan por un modo peculiar de ver el mundo en que viven, de modo que la diferencia de las percepciones marca la diversidad de cada civilización. Mary Beard lo ilustra con una doble y fascinante exploración. La primera parte se refiere al arte del cuerpo: a las diversas visiones del cuerpo humano a través del tiempo y del espacio, desde las gigantescas estatuas de los faraones a los guerreros de terracota de China. La segunda aborda un tema todavía más complejo: el de las imágenes de Dios y de los dioses. Y nos lleva a una reflexión acerca de los problemas que todas las religiones, antiguas o modernas, han tenido para representar lo divino. Su propósito es mostrarnos cómo la diferencia de las percepciones de lo que vemos marca la diversidad de las civilizaciones.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (448, '8422646293', 'Trilogía de las fundaciones: Fundación; Fundación e Imperio; Segunda Fundación', 1, '1994', 789, 'Foundation; Founation and Empire; Second Foundation', 'media/core/8422646293.jpg', 1, '2022-09-26 10:36:10.285615', '2022-09-26 10:43:10.444503', 341, 3, 6, 5, NULL, '', '02_04', NULL, 108, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (449, '8422646234', 'El robot humano', 1, '1993', 580, NULL, 'media/core/8422646234.jpg', 2, '2022-09-26 10:42:21.498799', '2022-09-26 10:45:44.499835', 341, 3, 6, 5, NULL, '', '02_04', NULL, 5, 'Que iene que hacer un robot para demostar su humanidad? Cuando salió de la cadena de monaje, el NDR113 no era más que un cerebro empotrado en una estructura humanoide de metal y plástico. Sin embargo, el NDR113 o Andrew Martin, como llegó a ser conocido no era un robot corriente. Aunque fue diseñado como asistente domestico, muy pronto sus propietarios se percataron de sus extraordinarias cualidades. Su diferencia despertó pasiones encontradas entre los hombres: admiración, temor y fascinación. Andrew Martin fue un artista excepcional y a lo largo de su trayectoria adquirió celebridad como escultor, escritor y científico. Conquistó la libertad, se cambió de cuerpo y amasò una fortuna. Tuvo algunos amigos y muchos enemigos. Sólo una cosa le estuvo vedada: la condición de ser humano. Para alcanzar esa anhelada meta libró una prolongada y difícil btalla que finalmente se saldó con una paradoja suprema... El robot humano, fruto de la fecunda colaboración de Asimov y Silverberg, está basada en el relato The Bicentennial Man y constituye un aporte tan divertido como agudo a las celebérrimas historias de robots de Isaac Asimov.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (450, '8422646250', 'Robots e Imperio', 1, '1994', 520, 'Robots and Empire', 'media/core/8422646250.jpg', 1, '2022-09-26 10:48:35.669380', '2022-09-26 10:48:35.669380', 341, 3, 6, NULL, NULL, '', NULL, NULL, 108, 'olaria el mundo originario de Gladia (el romance del terrestre Elijah Baley en Aurora) se ha extinguido misteriosamente. Ya han pasado doscientos años después de aquel encuentro Baley ha muerto y la longeva solariana deja pasar los últimos años... cuando los incipientes colonos de la Tierra y al frente un descendiente de Elijah Baley solicitan permiso para recuperar los miles y miles de robots que habrán quedado abandonados en Solaria. Gladia es la única nativa de aquel mundo que queda y necesitarán su ayuda.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (451, '8422646269', 'Tríptico del Imperio: Las corrientes del espacio; En la arena estelar; Un guijarro en el cielo', 1, '1994', 803, NULL, 'media/core/8422646269.jpg', 1, '2022-09-26 10:52:20.302387', '2024-02-22 19:12:35.921015', 341, 3, 6, 5, NULL, '', '02_04', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (452, '8486472741', 'Puerta al Infierno; Amos de títeres', 1, '1987', 1, 'The Door into Summer; The Puppet Masters', 'media/core/8486472741.jpg', 1, '2022-09-26 10:56:53.764939', '2022-09-26 10:56:53.764939', 342, 3, 6, 5, 'Obras estelares de la Ciencia Ficción', '', '02_04', 'Serie Andrómeda', 109, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (453, '8486472717', 'La Edad de Oro de la Ciencia Ficción', 1, '1987', 510, 'Before the golde Age', 'media/core/8486472717.jpg', 1, '2022-09-26 11:01:18.998487', '2022-09-26 11:01:18.998487', 341, 3, 6, 5, 'Obras estelares de la Ciencia Ficción', '', '02_04', 'Serie Andrómeda', 109, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (454, '9788467264951', 'El regreso del Catón', 1, '2015', 598, NULL, 'media/core/9788467264951_kbVaCNN.jpg', 1, '2022-09-26 11:06:15.102968', '2022-09-26 11:06:15.102968', 181, 1, 6, 5, NULL, '', '02_04', NULL, 15, 'El regreso del Catón cuenta los viajes del Catón y otros aventureros, desde Mongolia hasta Israel, pasando por Estambul. Todo ello financiado por un matrimonio de nonagenarios multimillonarios y siguiendo las pistas que les brindan viejas cartas y los textos bíblicos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (455, '8422646242', 'Los robots de Aurora', 1, '1993', 508, 'The Robots of Dawn', 'media/core/8422646242.jpg', 1, '2022-09-26 11:13:49.942441', '2022-09-26 11:13:49.942441', 341, 3, 6, 5, NULL, '', '02_04', NULL, 108, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (456, '8422646277', 'Preludio a la Fundación', 1, '1994', 508, 'Prelude to Foundation', 'media/core/8422646277.jpg', 1, '2022-09-26 11:16:30.781492', '2022-09-26 11:16:30.781492', 341, 3, 6, 5, NULL, '', '02_04', NULL, 96, 'Corre el año 12020 de la Era Galáctica y el emperador Cleón I se siente incómodo en su trono. En Trántor la gran capital del Imperio Galáctico 40.000 millones de personas han creado una civilización de una complejidad tecnológica y cultural inimaginable. Cuando el joven psicohistoriador Hari Seldon llega a Trántor para participar en un congreso se convierte en el hombre más buscado del Imperio. El psicohistoriador intentará que su portentosa teoría sobre el futuro no caiga en malas manos mientras forja la llave del futuro: un poder que será conocido como la Fundación', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (457, 'v', 'Fundación y Tierra', 1, '1995', 519, 'Foundation and Earth', 'media/core/8422646315.jpg', 1, '2022-09-26 11:19:21.841439', '2022-09-26 11:19:21.842438', 341, 3, 6, 5, NULL, '', '02_04', NULL, 96, 'Golan Trevize, ex consejero de la primera Fundaci#n, se encuentra con que debe realizar una tarea formidable: determinar el futuro del desarrollo gal#ctico. Pero, #qu# fuerza instintiva ha llevado a Trevize a esta extraordinaria idea? #Procede acaso de lo m#s profundo de la Historia antigua de otro gran mundo llamado Tierra? Trevize debe averiguar la respuesta a estas preguntas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (458, '8422646323', 'La enciclopedia galáctica', 1, '1993', 182, NULL, 'media/core/8422646323.jpg', 1, '2022-09-26 11:22:51.625419', '2022-09-26 11:22:51.625419', 341, 3, 6, 5, NULL, '', '02_04', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (459, '8422646226', 'Crónicas de robots: Navidades sin Rodney ¡Qué pena!; Sueños de robot', 1, '1973', 589, NULL, 'media/core/8422646226.jpg', 1, '2022-09-26 11:26:22.124992', '2022-09-26 11:26:22.124992', 341, 3, 6, 5, NULL, '', '02_04', NULL, 96, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (460, '8422646285', 'Hacia la Fundación', 1, '1994', 444, 'Forward the Foundation', 'media/core/8422646285.jpg', 1, '2022-09-26 11:29:22.732794', '2022-09-26 11:29:22.732794', 341, 3, 6, 5, NULL, '', '02_04', NULL, 96, 'Mientras Hari Seldon se esfuerza por perfeccionar su revolucionaria teoría de la psicohistoria, el gran Imperio Galáctico está al borde de un colapso apocalíptico. Seldon y aquellos a los que más quiere se convierten en peones en la lucha por el poder: quien lo controle a él controlará la psicohistoria, y con ella el futuro de la Galaxia. Entre los que desean convertir la psicohistoria en un arma se encuentran un político, el emperador Cleón, y un despiadado general. En su último acto de servicio a la humanidad, Seldon debe apañárselas para salvar el trabajo de toda su vida de las garras de ambos e ir en busca de sus verdaderos herederos y del sueño de una nueva Fundación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (461, '8422646307', 'Los límites de la Fundación', 1, '1994', 475, 'Foundation''s Edge', 'media/core/8422646307.jpg', 1, '2022-09-26 11:33:05.752204', '2022-09-26 11:33:05.752204', 341, 3, 6, 5, NULL, '', '02_04', NULL, 108, '', '');
