INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (464, '9788467263435', '¡Quemad Barcelona!', 1, '2015', 574, 'Cremeu Barcelona!', 'media/core/9788467263435.jpg', 1, '2022-09-26 11:48:35.132657', '2022-09-26 11:48:35.132657', 345, 1, 6, 5, NULL, '', '02_04', NULL, 15, 'La República agoniza y la guerra está perdida, y la Barcelona es ya una sombra de lo que era. En estas condiciones llega la orden de Moscú, del Komintern de arrasar la ciudad, destruir las vías de comunicación y centros neurálgicos de energía, agua y transporte. La guerra en Europa empezará pronto, España será estratégica; no hay que dejar nada a Franco que pueda usar luego contra nosotros.', '');
