INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (467, '9788467259896', 'En las trincheras', 1, '2009', 355, NULL, 'media/core/9788467259896.jpg', 1, '2022-09-26 12:05:47.950992', '2022-09-26 12:05:47.950992', 347, 33, 6, 5, NULL, '', '02_04', NULL, 112, 'Las crónicas de Gaziel, el gran reportero de la Primera Guerra Mundial. La guerra contada desde primera línea.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (468, '9788467264258', 'La última noche de Víctor Ros', 1, '2013', 442, NULL, 'media/core/9788467264258.jpg', 1, '2022-09-26 12:09:17.275630', '2022-09-26 12:13:00.071136', 147, 14, 6, 5, 'Víctor Ros', '', '02_04', NULL, 34, 'Una peligrosa asesina fugada. Un joven muerto en extrañas circunstancias. Una familia repleta de secretos. Un pasado oscuro y una traición. Por fin un caso que pondrá a prueba el talento del detective más carismático e inteligente del siglo XIX, Víctor Ros. Suiza, 1882. Bárbara Miranda, una psicópata custodiada por el Sello de Brandenburgo, escapa de su celda y desaparece. Oviedo, un año después. Ramón Férez, primogénito de un acaudalado industrial, aparece asesinado delante de la verja de acceso a la Casa Férez. Para desesperación de las fuerzas del orden de la ciudad, no dejan de aparecer sospechosos del asesinato del joven, y el juez encargado del sumario, Agustín Casamajó, incapaz de encontrar al verdadero culpable, decide llamar a su gran amigo y famoso detective, Víctor Ros. Pero el caso no será fácil para él: tendrá que evitar las trampas que le colocarán en su camino las personas que menos espera, y se encontrará con un amor del pasado al que traicionó en su juventud. Víctor Ros, con la ayuda de su hijo adoptivo y de su perspicaz esposa, ¿encontrará al culpable y evitará más muertes? ¿Podrá salir airoso del caso más peligroso de su vida? O por el contrario, ¿seremos testigos de su última noche?', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (469, '9788467264234', 'El caso de la Viuda Negra', 1, '2010', 344, NULL, 'media/core/9788467264234.jpg', 1, '2022-09-26 12:12:13.251892', '2022-09-26 12:13:29.485478', 147, 14, 6, 5, 'Vctor Ros', '', '02_04', NULL, 113, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (470, '9788408125792', 'Vuelven', 1, '2014', 378, 'The Returned', 'media/core/9788408125792.jpg', 1, '2022-09-26 12:16:50.190528', '2022-09-26 12:16:50.190528', 348, 1, 6, 5, NULL, '', '02_04', NULL, 7, '¿Qué pasaría si alguien a quien has perdido volviera? Harold y Lucille Hargrave han vivido durante décadas con la pena de haber perdido a su único hijo, Jacob. Un día, un agente del FBI aparece en su puerta de la mano de Jacob, sigue teniendo ocho años y el mismo aspecto que tenía el día de su muerte. A lo largo y ancho del mundo, los muertos están volviendo del más allá. Nadie sabe cómo ni porqué, o si se trata de un milagro o un anuncio del fin de nuestros días.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (471, '9788467264210', 'Hombres sin mujeres', 1, '2015', 252, 'Omna no inau otokotachi', 'media/core/9788467264210.jpg', 1, '2022-09-26 12:20:50.703439', '2022-11-27 07:04:01.242626', 243, 1, 6, 5, NULL, '', '02_04', NULL, 114, '', '');
