INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (474, '9788467273564', 'La muerte del comendador', 1, '2018', 474, 'Kishidancho Goroshi', 'media/core/9788467273564.jpg', 1, '2022-09-26 12:34:40.535159', '2024-05-11 17:04:51.149989', 243, 1, 6, 5, NULL, '', '02_04', 'Libro 1', 114, 'En plena crisis de pareja, un retratista de cierto prestigio abandona Tokio en dirección al norte de Japón. Confuso, sumido en sus recuerdos, deambula por el país hasta que, finalmente, un amigo le ofrece instalarse en una pequeña casa aislada, rodeada de bosques, que pertenece a su padre, un pintor famoso.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (475, '9788467271928', 'Agatha Raisin y el manatial de la muerte', 1, '2017', 1, 'Agatha Raisin and tjhe Wellspring of Detah', 'media/core/9788467271928.jpg', 1, '2022-09-26 12:39:00.459455', '2022-09-26 12:39:00.459455', 349, 1, 6, 5, NULL, '', '02_04', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (476, '9788490663196', 'Patria', 2, '2016', 642, NULL, 'media/core/9788490663196.jpg', 1, '2022-09-26 12:42:40.538259', '2023-04-19 08:16:07.586230', 350, 1, 6, 5, 'Andanzas', '', '02_04', NULL, 12, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (477, '9788422697299', 'Los refugios de piedra', 1, '2002', 849, 'The Shelters of Stone', 'media/core/9788422697299.jpg', 1, '2022-09-28 15:59:21.379869', '2022-09-28 15:59:21.379869', 87, 1, 6, 5, NULL, '', '02_04', NULL, 5, 'Los Refugios de Piedra comienza cuando Ayla y Jondalar terminan su épico viaje a través de Europa en compañía de sus amigos, los animales Lobo, Relinchona y Corredor, y son bienvenidos por los zelandones, la gente del pueblo de Jondalar.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (478, '9788467220827', 'Juego de niños', 1, '2005', 374, NULL, 'media/core/9788467220827.jpg', 1, '2022-09-28 16:03:16.892704', '2023-04-19 08:15:35.938332', 351, 1, 6, 5, NULL, '', '02_04', NULL, 15, 'Luisa es una escritora divorciada dos veces, madre de Elba, una hija que concibió en un “viaje de apareamiento” y a la que siempre ha dicho que es adoptada, para evitar explicar la realidad de su concepción. Es una mujer apacible, burguesa, que ha conseguido un cierto equilibrio emocional con Enrique, un hombre pragmático y cariñoso, con el que mantiene una relación estable, sin sobresaltos. Escribe novelas de intriga que tienen por protagonista a Carmen O’Inns, mezcla de caribeña e irlandesa, una psiquiatra que resuelve casos imposibles con la sola ayuda de su gran atractivo y su portentoso cerebro. Su nuevo thriller pretende tratar de la maldad en estado puro, y en especial de la maldad de los niños porque ¿hay algo más aterrador que la crueldad infantil? Así, la novela de Luisa comienza con el asesinato de un niño en un prestigioso colegio. La novelista está en esa etapa de la creación literaria en la que tiene que dar vida a los sospechosos del crimen, que serán dos adultos, una profesora y el padre de la víctima y dos niños, compañeros del colegio, pero que aún no tiene bien definidos. Paralelamente a las cavilaciones literarias de Luisa, su vida está sufriendo transformaciones importantes. En primer lugar, Elba, su hija, va a cambiar de colegio y asistir al mismo en el que ella estudió de niña y coincidiendo con esta circunstancia, la novelista ha decidido contar a su hija la verdad sobre su nacimiento, ya que la niña parece obsesionada por descubrir sus raíces. Pero cuando Elba escucha la verdad no parece creer a su madre y Luisa piensa que quizá ha cometido un error de consecuencias imprevisibles. Mientras desarrolla la trama de su novela, Luisa se da cuenta de que los hechos que narra tienen mucho que ver con un episodio casi olvidado de su propia infancia. La muerte accidental de un compañero durante un juego en el que Luisa tomaba parte. El niño muerto, Antonio, era hermano gemelo de Miguel y ambos amigos de Sofía, una niña mimada y segura de sí misma. Los cuatro jugaban a policías y ladrones cuando Sofía y Antonio se subieron a un gran macetero que terminó por volcar. Miguel optó por agarrar a Sofía, y su hermano terminó desnucado contra el borde de un estanque vacío. Para su sorpresa, el primer día que acompaña a su hija al colegio, Luisa se encuentra con estos dos amigos casi olvidados. Sofía, que ha perdido su belleza y su posición social, aunque no su fuerte personalidad y que ahora imparte clases en su antiguo colegio y Miguel, padre de Miki, un niño tímido que coincide en la clase con Elba y con Avril, la hija de Sofía. Poco a poco, la ficción de la novela que escribe Luisa y la realidad de su vida comienzan a entrelazarse de una forma cada vez más inquietante. Elba y Avril se convierten en inseparables hasta que conocen a Tony, el hijo adulto de Miguel de un anterior matrimonio que lleva el nombre de su tío muerto y que adora a su hermano pequeño. Poco tiempo después, Miki muere al caer por las escaleras del colegio. Luisa, ayudada por Enrique, su pareja, intenta investigar las circunstancias de la muerte y descubren que Miki pudo no estar tan solo como se dijo al caer por las escaleras. Pero los más sorprendente es que los posibles sospechosos son: Sofía, Avril, Elba y también Miguel, el padre de Miki; todos ellos tienen alguna razón para cometer el crimen. ¿La vida se repite?, ¿La realidad imita la ficción?', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (479, '9788422693369', 'Alamut', 1, '1992', 502, NULL, 'media/core/9788422693369.jpg', 1, '2022-09-28 16:06:18.347296', '2022-09-28 16:06:18.347296', 352, 1, 6, 5, NULL, '', '02_04', NULL, 93, 'En la ciudadela de Alamut, un inexpugnable nido de águilas en las montañas del norte de Persia, Hassan Ibn Saba se dispone a derribar el imperio otomano con apenas un puñado de guerreros de la secta de los hashashins (término que dio origen a la palabra asesino). Utiliza para ello un método tan inhumano como infalible: la ilusión del paraíso. Embriagados de vino y hachís, en la creencia de que han sido premiados con una visita al jardín de Alá, los jóvenes guerreros pierden el miedo a la muerte. Una de las novelas que mejor han relatado la historia de la fortaleza de Alamut y sus míticos asesinos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (480, '9788422675754', 'La maldición de Copérnico', 1, '1998', 459, 'Der Fluch des Kopernikus', 'media/core/9788422675754.jpg', 1, '2022-09-28 16:09:55.472394', '2022-09-28 16:09:55.472394', 276, 1, 6, 5, NULL, '', '02_04', NULL, 15, 'La solitaria lucha de un hombre contra la InquisiciónINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (481, '9788422677024', 'Longitud', 1, '1995', 179, 'Longitude', 'media/core/sin-imagen_AXMj4u3.jpg', 1, '2022-09-28 16:14:15.452189', '2022-09-28 16:14:15.452189', 353, 1, 6, 5, NULL, '', '02_04', NULL, 76, 'Dava Sobel narra la historia del científico y relojero escoces John Harrison, un genio solitario cuyos logros fueron rechazados por la elite científica de su tiempo, pero que consiguió resolver un problema aparentemente imposible: descubrir un metodo que permitiera a los marineros determinar la longitud exacta de su posición en el mar. No se trataba de ninguna curiosidad excentrica: antes de descubrir la longitud, los barcos solían desviarse tanto de su rumbo que los marineros morían de inanición o de escorbuto antes de haber alcanzado ningún puerto. Necesitaban mucha suerte para llegar a su destino, ya que ninguna nave contaba con metodos fiables para establecer su posición en alta mar. Millares de vidas humanas, la expansión político-económica y las crecientes fortunas de las naciones que flotaban en los oceanos dependían de este hallazgo. En 1714, el gobierno ingles convocó un concurso y ofreció una elevada recompensa para aquel que lograra desarrollar un metodo capaz de determinar la longitud exacta. El reto de resolver el legendario dilema lo aceptaron científicos de la talla de Galileo, Newton o Halley. Harrison trabajó durante más de cuarenta años para fabricar un cronómetro perfectoy al fin lo logró', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (482, '9788422676140', 'Peón de Rey', 1, '1998', 458, NULL, 'media/core/9788422676140.GIF', 1, '2022-09-28 16:17:10.639498', '2022-09-28 16:17:10.639498', 354, 1, 6, 5, NULL, '', '02_04', NULL, 73, 'Un libro radical. Un corte hondo y esclarecedor en un momento clave de la historia de España, cuando el país está naciendo y andan buscando asiento todos los rasgos de su personalidad futura. El ambiente, los personajes, los sentimientos, los motivos, los ideales, las metas, el amor, los modelos de futuro... Un universo entero recogido en un libro que se lee como una aventura y se recuerda profundamente.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (483, '9788467235258', 'El hombre del balcón', 1, '2008', 231, 'Mannen pa balkongen', 'media/core/9788467235258.jpg', 1, '2022-09-28 16:20:32.093222', '2022-09-28 16:25:43.959501', 355, 14, 6, 5, NULL, '', '02_04', 'Temor frío', 101, 'Esta es la turbadora tercera entrega de la serie detectivesca protagonizada por Martin Beck, serie iniciada en los años sesenta e inspiradora de gran parte de la novela negra escrita a partir de entonces. Alguien se dedica a asesinar niñas en los ya no tan pacíficos parques de Estocolmo: las asesina después de haber abusado de ellas. Los ciudadanos están preocupados y temerosos. El inspector de policía Martin Beck tiene dos testigos: un insensible maleante que no piensa hablar y un niño de tres años que no puede decir demasiado.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (484, '9788467235265', 'Crepúsculo en Oslo', 1, '2009', 371, 'Det som aldri skjer', 'media/core/9788467235265.jpg', 1, '2022-09-28 16:25:04.147456', '2022-09-28 16:25:04.147456', 356, 14, 6, 5, NULL, '', '02_04', 'Temor frío', 115, 'En la ciudad de Oslo, una conocida presentadora de televisión aparece asesinada en su domicilio. El superintendente Yngvar Stubo y la que fuera profiler del FBI Inger Johanne Vik, son requeridos para llevar a cabo la investigación. Pareja tanto en la vida real como en la profesional, Sutbo y Vik se muestran reticentes a llevar el caso ya que acaban de ser padres; sin embargo, se ven forzados a aceptarlo dada la naturaleza del mismo. Todo apunta a un asesino en serie de gusto perverso que se deleita escenificando sus crímenes. Mientras Stubo se vuelca en el análisis meticuloso de los detalles que rodean cada crimen, Vik ahonda en una teoría que coge fuerza a medida que traza el perfil del presunto asesino: la posible conexión entre los hechos presentes y su pasado como miembro del FBI.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (485, '9788467235234', 'La princesa de hielo', 1, '2007', 378, 'Isprinsessan', 'media/core/9788467235234.jpg', 1, '2022-09-28 16:28:58.781086', '2022-09-28 16:28:58.781086', 357, 14, 6, 5, NULL, '', '02_04', 'Temor frío', 113, 'Tras muchos años de ausencia, la joven escritora Erica vuelve a su pueblo natal, donde ha heredado la casa de sus padres recientemente fallecidos. Erica decide darse un paseo por las calles donde transcurrieron los primeros años de su vida, pero tras el aviso de unos vecinos, descubre que su amiga de la infancia, Alex, acaba de suicidarse. Conmocionada, inicia una investigación y descubre que Alex estaba embarazada. La historia da un nuevo giro cuando la autopsia revela que su amiga no se suicidó sino que fue asesinada. La policía detiene al principal sospechoso, Anders, un artista fracasado que mantenía una relación especial con la víctima.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (486, '9788467235241', 'Petirrojo', 1, '2008', 555, 'Rødstrupe', 'media/core/9788467235241.jpg', 1, '2022-09-28 16:32:53.128150', '2022-09-28 16:32:53.128150', 45, 14, 6, 5, NULL, '', '02_04', 'Temor frío', 101, 'Año 1944. Daniel, combatiente del frente oriental, muere asesinado en las trincheras de Leningrado. En un hospital de Viena, un soldado herido dice ser Daniel. Entre él y la enfermera Helena surge un romance. Año 1999. El investigador Harry Hole dispara por accidente a un agente de los servicios secretos durante la visita a Noruega del presidente Clinton. Harry Hole es trasladado a la policía de seguridad ciudadana, donde se le asigna la misión de comprobar la información sobre una red de tráfico de armas relacionada con círculos de viejos y nuevos nazis.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (487, '9788467235272', 'Las marismas', 1, '2006', 278, 'Myrin', 'media/core/9788467235272.jpg', 1, '2022-09-28 16:36:21.952798', '2022-09-28 16:36:21.952798', 358, 14, 6, 5, NULL, '', '02_04', 'Temor frío', 101, 'Premio La Llave de Cristal 2002. Un hombre aparece asesinado en su casa en el barrio Las Marismas de Nordurmri, en Reikiavik. La policía encuentra escondida en su escritorio una vieja foto de la tumba de una niña de cuatro años. Y es precisamente esa foto la que conduce a los investigadores hacia el pasado tenebroso de aquel hombre, a sus antiguas relaciones y a un drama familiar. Esta historia coincide con la desaparición de una joven de su propio banquete de boda. Los inspectores, Erlendur y Sigurdur Óli, se enfrentan en los dos casos a enredados y complicados pasados de familias aparentemente corrientes.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (488, '9788415717270', 'EL vagabundo de las estrellas', 1, '2013', 366, 'The Star Rover', 'media/core/9788415717270.jpg', 1, '2022-09-29 17:24:47.275141', '2022-09-29 17:24:47.275141', 359, 1, 6, 5, 'Otraslatitudes', '', '02_04', NULL, 116, 'El vagabundo de las estrellas es la última novela que escribió Jack London. Es una feroz crítica de la tortura y de la pena de muerte, y una metáfora del placer emancipador de la lectura.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (489, '9788467229769', 'Firmin', 1, '2007', 216, 'Firmin: Adventures of a Metropolitan Lowlife', 'media/core/9788467229769.jpg', 1, '2022-09-29 17:31:10.522585', '2022-09-29 17:31:10.522585', 360, 1, 6, 5, NULL, '', '02_04', NULL, 14, 'Un relato de humor negro sobre el poder de la literatura.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (490, '9788422671374', 'Las cenizs de Ángela', 1, '1997', 445, 'Angela''s Ashes', 'media/core/9788422671374.jpg', 1, '2022-09-29 17:34:23.943271', '2022-09-29 17:34:23.943271', 310, 1, 6, 5, NULL, '', '02_04', NULL, 113, 'PREMIO PULITZER 1997. Premio del Círculo Nacional de Críticos Literarios. Premio Los Angeles Times. Libro del Año 1997 (ABBY). Más de 11.000.000 de lectores en EE.UU y Europa. Nº 1en las listas de bestsellers de todo el mundo. 50 semanas como libro más vendido en todas las librerías durante 1998. En este magnífico libro se narran los duros comienzos de una familia emigrante irlandesa, vista a través de un niño. Por ello, el lector se encontrará con grandes dosis de humor y compasión transmitidos a través de su autor, Frank McCourt. Es una extraordinaria obra donde Frank McCourt nos muestra el amor, la dignidad y el humor de una infancia marcada por el hambre, la muerte y el dolor.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (491, '9788467232950', 'Los Buddenbrook', 1, '2008', 795, 'Buddenbrooks. Verfall einer Familie', 'media/core/9788467232950.jpg', 1, '2022-09-29 17:39:24.183694', '2022-09-29 17:39:24.183694', 361, 1, 6, 5, NULL, '', '02_04', NULL, 93, 'Thomas Mann escribió ésta, su primera novela, en 1901, a los 25 años, y fue sobre todo por ella que recibió en 1929 el Premio Nobel de Literatura. La ciudad de Lübeck y su propia familia sirvieron de inspiración a Thomas Mann para escribir esta extraordinaria saga familiar que abarca cuatro generaciones y un espacio temporal entre 1835 y 1877. En ella no sólo traza un gigantesco fresco de una época y una sociedad, sinó también un hondo y sutil retrato de la naturaleza humana: ganadores y perdedores, valientes y cobardes, suerte y desgracia, riqueza y pobreza.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (492, '8422632225', 'El último testamento de Oscar WIlde', 1, '1986', 273, 'The Last Testament of Oscar Wilde', 'media/core/8422632225.jpg', 1, '2022-09-29 17:44:04.600682', '2022-09-29 17:44:04.600682', 362, 1, 6, 5, NULL, '', '02_04', NULL, 93, 'Ficticio relato autobiográfico en el que se narran las vicisitudes de sus últimos años, la pobreza y el exilio parisino de quien había llegado a ser el dramaturgo más aplaudido y admirado de Londres.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (493, '842780377', 'Rojo y Negro', 1, '1975', 450, NULL, 'media/core/sin-imagen_ZRXxLD9.jpg', 1, '2022-09-29 17:49:17.822672', '2022-09-29 17:49:17.822672', 363, 1, 6, 5, 'Obras selectas', '', '02_04', NULL, 117, 'En un aserradero perdido en los bosques del Franco Condado, un joven seminarista despreciado por su ruda familia, lleno de sueños y ambiciones, lee un libro. Poco sospecha que su vida está a punto de dar un giro decisivo y que su entrada como preceptor en casa de monsieur de Rênal será el comienzo de su apertura al amor, a la vida y, finalmente, al crimen. En esta novela, inspirada en un hecho real, su joven e inolvidable protagonista, Julián Sorel. Plebeyo enamorado y soberbio, rebelde e ingenuo, se verá sometido a la cruel piedra de toque que le ofrece un mundo dominado por las jerarquías, el dinero y el clero.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (494, '842780085', 'Relatos 1883-1884-1885', 1, '1975', 488, NULL, 'media/core/sin-imagen_vtERv9A.jpg', 1, '2022-09-29 17:51:59.495219', '2022-09-29 17:51:59.495219', 364, 1, 6, 5, 'Obras selectas', '', '02_04', NULL, 117, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (495, '9788415594024', 'La lección de August', 4, '2013', 410, 'Wonder', 'media/core/9788415594024.jpg', 1, '2022-09-29 17:56:28.342017', '2022-09-29 17:56:28.342017', 365, 1, 6, 5, 'Nube de tinta', '', '02_04', NULL, 11, 'finalistaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (496, '9788484282006', 'David Copperfield', 1, '2003', 1022, 'The Personal History of David Copperfield', 'media/core/9788484282006.jpg', 1, '2022-09-29 18:00:11.421283', '2022-09-29 18:00:11.421283', 366, 1, 6, 5, 'Clásica Maior', '', '02_04', NULL, 119, 'La huella autobiográfica que Charles Dickens (1812-1870) dejó en David Copperfield, una de sus obras más importantes, convirtió este libro en el más cercano a su corazón. David, como Dickens, vivió una infancia feliz leyendo y asistiendo a la escuela hasta que su suerte cambió. La transmutación íntima de ambos, protagonista y autor, fue compleja y sutil. Aunque ficción y realidad no siempre coinciden, las desdichas de la niñez, el trabajo en la abogacía, la condición de escritor y varios de los personajes responden a la experiencia personal de su autor. Narrada desde la distancia del adulto, la vida de David Copperfield encierra sátira y humor irónico, luto y angustia, pero también mucha alegría y ruido de personas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (497, 'M23387', 'El osito Winnie y el árbol de la miel', 1, '1968', 1, NULL, 'media/core/M23387.jpg', 1, '2022-10-01 17:11:54.128501', '2022-11-27 10:59:53.095053', NULL, 34, 6, 5, 'Colección Sonrisa', '', '02_05', NULL, 120, '', '');
