INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (500, '8485351061', 'Viaje a las comunas', 1, '1978', 72, 'Freak Brothers "Grass Roots"', 'media/core/8485351061.jpg', 1, '2022-10-01 17:27:54.107410', '2022-10-01 17:27:54.107410', 368, 35, 6, 5, NULL, '', '02_05', NULL, 123, 'Portada.- Ilustración de Gilbert Shelton y Dave SheridanINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (501, '9788403098428', 'Frases célebres de niños', 14, '2008', 141, NULL, 'media/core/9788403098428.jpg', 1, '2022-10-01 17:31:52.445773', '2022-10-01 17:31:52.445773', 369, 36, 6, 5, NULL, '', '02_05', NULL, 87, 'Hay un momento en la vida de los niños en el que empiezan a hacer sus propias deducciones, y como todavía están sin manipular, a veces, tienen una claridad de ideas que a los mayores nos desconcierta. Estas frases ingeniosas se suelen quedar en el ámbito familiar, pero por fin gracias a este libro, les vamos a dar la importancia que se merecen. Algunas de las reflexiones que hay aquí parecen de Sócrates o de Confucio, pero sólo son niños... Abre el libro por cualquier parte y prueba a leer sólo una página.', '');
