INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (503, '9788415046554', 'La Edad de Oro', 1, '2019', 1, NULL, 'media/core/sin-imagen_XiV09SB.jpg', 1, '2022-10-01 17:43:03.414525', '2022-10-01 17:43:03.414525', 371, 30, 6, 5, NULL, '', '02_05', NULL, 63, 'This fascimile edition of the original edtion of "La Edad de Oro: Publicacion mensual de recreo e instruccion dedicada á los niños de América" published in New York in 1889, compiles the 4 issues published monthly in that year in the form of a journal, which ceased on that same year, and a [fifth] additional volume edited in 2019 which contains other text of the authorship of José Martí or related to the author. This is a fascimile of edición príncipe from the Cuban Heritage Collection, University of Miami.', 'Colabora en la edición: Caros Martín Aires');
