INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (520, '9788409300136', 'Espadas del fin del mundo', 1, '2021', 1, NULL, 'media/core/9788409300136.jpg', 1, '2022-11-27 11:28:53.405169', '2022-11-27 11:28:53.405169', 383, 34, 6, 5, NULL, '', '02_05', NULL, 63, 'Espadas del fin del mundo'' es un cómic de acción y ambientación histórica. Narra los combates de Cagayán, una espectacular escaramuza entre soldados castellanos de la época de los tercios y piratas japoneses, que tuvo lugar en 1582 al norte de las islas Filipinas, punto de encuentro entre occidente y oriente. El cómic ya ha agotado una tirada inicial de 2.000 ejemplares, ha sido reseñado en varios medios y cuenta con más de 4.000 fans en Facebook. Tras meses de espera, esta reedición revisada aumenta hasta 100 el número de páginas con bocetos, grabados de época, un relato y documentación variada del periodo y sus protagonistas', '');
