INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (538, '9788426419231', 'Todo Mafalda', 2, '2012', 672, NULL, 'media/core/9788426419231.jpg', 1, '2022-11-29 11:18:52.299009', '2022-11-29 11:18:52.299009', 389, 34, 6, 5, NULL, '', '02_05', NULL, 21, 'Quino con cada uno de sus libros, lleva ya muchos años demostrándonos que los niños son los depositarios de la sabiduría. Lo malo para el mundo es que a medida que crecen van perdiendo el uso de la razón, se les olvida en la esucela lo que sabían al nacer, se casan sin amor, trabajan por dinero, se cepillan los dientes, se cortan las uñas, y al final -convertidos en adultos miserables- no se ahogan en un vaso de agua sino en un plato de sopa. Comprobar esto en cada libro de Quino es lo que más se parece a la felicidad: la quinoterapia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (539, '9788498151138', 'Asterix el Galo', 1, '2005', 1, 'Atérix Le Gaulois', 'media/core/9788498151138.jpg', 1, '2022-11-29 11:43:03.872324', '2022-11-29 11:43:03.872324', 390, 34, 6, 5, NULL, '', '02_05', NULL, 139, 'Estamos en el año 50 antes de Jesucristo. Toda la Galia se halla ocupada por los romanos... ¿Toda? ¡No! una aldea poblada por irreductibles galos resiste todavía y siempre al invasor. Y la vida no resulta fácil para las guarniciones de legionarios de los campamentos fortificados de Babaorum, Acuarium, Laudanum y Petibonum...', 'También Albert Uderzo');
