INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (661, '8410018040813', 'La especualción inmobiliaria', 2, '1986', 160, 'La specualziones edilizia', 'media/core/8410018040813.jpg', 1, '2023-03-15 19:03:58.330090', '2023-03-15 19:03:58.330090', 478, 1, 6, 5, NULL, '', '03_03', NULL, 126, 'Este libro constituye una excelente muestra de la sensibilidad narrativa de Italo Calvino para captar los conflictos y los cambios de la sociedad italiana tras la caída del fascismo y la conclusión de la segunda Guerra Mundial. La especulación inmobiliaria es la historia de un intelectual de izquierdas con mala conciencia que decide lanzarse al escabroso mundo de los negocios. La realidad se encargará de demostrarle, en una cadena de falsas esperanzas y amargos desencantos, su irremediable fracaso como hombre práctico.', '');
