INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (663, '9788490323595', 'Europesadilla. Alguien se ha comido a la clase media', 1, '2013', 1, NULL, 'media/core/9788490323595.jpg', 1, '2023-03-16 07:40:20.570880', '2023-03-16 07:40:20.570880', 480, 29, 6, 5, 'Debolsillo', '', '03_03', NULL, 171, 'Varios monstruos recorren Europa: ¿Evitarán sus ciudadanos convertirse en su menú?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (664, '843078215X', 'Ecología, hoy', 7, '1982', 189, NULL, 'media/core/843078215X.jpeg', 1, '2023-03-16 07:43:40.531605', '2023-03-16 07:43:40.531605', 481, 38, 6, 5, 'Hay que saber', '', '03_03', NULL, 172, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (665, '9788492979110', 'Manifiesto de economistas aterrados', 2, '2011', 61, 'Manifeste d''èconomistes atterrés', 'media/core/9788492979110.jpg', 1, '2023-03-16 07:48:02.788561', '2023-03-16 07:53:45.673360', 482, 39, 6, 5, NULL, '', '03_03', NULL, 173, 'Cuatro prestigiosos economistas de diversa procedencia teórica redactaron este Manifiesto en septiembre de 2010 al que, en menos de tres meses, se han adherido 3.000 personas del mundo de la economía y el pensamiento. En él denuncian diez falsas evidencias (?los mercados financieros favorecen el crecimiento económico?, ?hay que dar confianza a los mercados para financiar la deuda pública?...) y unos programas de ajuste que están agravando la crisis económica y aumentando la desigualdad social. También proponen veintidós medidas para debatir otra estrategia económica. El Manifiesto ha tenido un enorme éxito de público en Francia y se ha convertido en un grito de alarma. Por su claridad, su brevedad y precisión expositiva, ha ofrecido a los ciudadanos los medios teóricos para mostrar el abismo que existe entre las afirmaciones de los portavoces de los mercados financieros y la fragilidad de sus diagnósticos.', 'Et Alii:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (666, '9788423344710', '¡Indignaos!', 1, '2011', 60, 'Indignez-vous', 'media/core/9788423344710.jpg', 1, '2023-03-16 07:52:29.507532', '2023-03-16 07:54:17.437796', 483, 39, 6, 5, 'Imago Mundi', '', '03_03', 'Vol 195', 59, 'Un alegato contra la indiferencia y a favor de la insurrección pacífica. El libro que ha despertado la conciencia de más de un millón de franceses.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (667, 'GT1952', 'Guía turística de la provincia de Barcelona', 1, '1952', 152, NULL, 'media/core/sin-imagen_jAgEmWo.jpg', 1, '2023-03-16 08:09:30.087466', '2023-03-16 08:09:30.087466', NULL, 18, 6, 5, NULL, '', '03_03', NULL, 174, '', '');
