INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (669, 'M3478', 'Crímenes de guerra en Vietnam', 3, '1968', 1, 'War Crimes in Vietnam', 'media/core/M3478.jpg', 1, '2023-03-16 08:16:39.865636', '2023-03-16 08:16:39.865636', 484, 2, 6, 5, NULL, '', '03_03', NULL, 175, 'Cuando la opinión pública occidental se encontraba narcotizada por la oprimente propaganda emanada de los Estados Unidos, este increiblemente lúcido anciano que contaba por entonces con noventa y cinco años, denunciaba las atrocidades cometidas por ese país en Vietnam, las que, como los crímenes nazis o los de los militares en Argentina, surgirían a la luz muchos años más tarde. Con el conflicto de Vietnam de fondo, Russell efectuaba un impecable estudio de ese absurdo que se dio en llamar "la guerra fría".', '');
