INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (679, '9780194230506', 'Treasure Island', 1, '2000', 73, NULL, 'media/core/9780194230506.jpg', 1, '2023-03-17 07:40:23.978657', '2023-03-17 07:40:23.978657', 494, 1, 6, 5, 'Thriller & Adventure', '', '03_03', 'Stage 4 (1400 headwords)', 179, '''Suddenly, there was a high voice screaming in the darkness: "Pieces of eight! Pieces of eight! Pieces of eight!" It was Long John Silver''s parrot, Captain Flint! I turned to run ...'' But young Jim Hawkins does not escape from the pirates this time. Will he and his friends find the treasure before the pirates do? Will they escape from the island, and sail back to England with a ship full of gold?', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (680, '9780194229500', 'One-way ticket Short stories', 1, '2000', 38, NULL, 'media/core/9780194229500.jpg', 1, '2023-03-17 07:51:39.877514', '2023-03-17 07:51:39.877514', 495, 1, 6, 5, 'Human Interest', '', '03_03', 'Stage 1 (400 headwords)', 179, 'Tom Walsh had a lot to learn about life. He liked travelling, and he was in no hurry. He liked meeting people, anyone and everyone. He liked the two American girls on the train. They were nice and very friendly. They knew a lot of places. Tom thought they were fun. Tom certainly had a lot to learn about life. This is a collection of short stories about adventures on trains. Strange, wonderful, and frightening things can happen on trains - and all of them happen here.', '');
