INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (703, '9788408142683', 'Los mejores consejos de fotografía', 1, '2015', 128, NULL, 'media/core/9788408142683.jpg', 1, '2023-03-19 11:00:28.673570', '2023-03-19 11:00:28.673570', 508, 38, 6, 5, 'geoPlaneta', '', '03_03', NULL, 7, 'Ya sea con un móvil o con una cámara réflex digital grande, con este libro de Lonely Planet mejoran tanto las habilidades como las imágenes que resultan de practicarlas.El galardonado fotógrafo Richard I''Anson ha viajado por el mundo desde hace 30 años y ha sido el creador de la galería fotográfica de Lonely Planet.Un diseño rompedor y llamativo que se adecua perfectamente al ritmo del viaje.Consejos claros y precisos de un experto.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (704, '9788408150480', 'Los mejores consejos de vídeo', 1, '2016', 128, NULL, 'media/core/9788408150480.jpg', 1, '2023-03-19 11:03:49.822116', '2023-03-19 11:03:49.822116', 509, 38, 6, 5, 'geoPlaneta', '', '03_03', NULL, 7, 'El vídeo es una herramienta muy potente para capturar lo vivido en un viaje. Allí donde la fotografía ofrece la instantánea de un momento único, el vídeo construye un collage de imágenes, puntos de vista y acción en tiempo real.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (705, '9788437631257', 'Pequeño diccionario visual de términos arquitectónicos', 1, '2013', 228, NULL, 'media/core/9788437631257.jpg', 1, '2023-03-19 11:08:24.118715', '2023-03-19 11:08:24.118715', 510, 40, 6, 5, 'Cuadernos Arte cátedra', '', '03_03', NULL, 153, 'En este " Pequeño diccionario visual " el lector encontrará de forma sencilla, accesible y manejable un conjunto de términos relacionados con el arte y las disciplinas básicas que lo componen: arquitectura, pintura, escultura. Junto a las principales disciplinas mencionadas aparecen otras como la alfarería, la cerámica, la heráldica, la glíptica, la orfebrería, la ebanistería, la eboraria o el grabado. Las voces aparecen traducidas al inglés, francés, alemán e italiano.Este libro nos ayudará a comprender mejor el arte, las técnicas artísticas en sus distintas manifestaciones y servirá como punto de partida para posteriores estudios y profundizar en los distintos significados de los vocablos que aquí aparecen.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (706, '9788496669710', 'Cómo leer paisajes', 1, '2011', 243, 'How to Read the Landscape', 'media/core/9788496669710.jpg', 1, '2023-03-19 12:05:57.111394', '2023-03-19 12:05:57.111394', 511, 38, 6, 5, NULL, '', '03_03', NULL, 187, 'Este volumen proporciona una guía concisa y accesible a la maravillosa variedad de paisajes que nos podemos encontrar a nuestro alrededor. Cada forma del terreno ofrece las claves para comprender cómo y por qué un área determinada se desarrolló a lo largo del tiempo hasta dar el paisaje que vemos en la actualidad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (707, '9788496669826', 'Cómo leer edficios', 1, '2013', 243, 'How to Read Buikdings', 'media/core/9788496669826.jpg', 1, '2023-03-19 12:09:10.261073', '2023-05-13 10:10:19.975506', 512, 38, 6, 5, NULL, '', '03_03', NULL, 187, 'Cómo leer un edificio es una introducción práctica a la observación y la apreciación de la arquitectura. Es una guía para la lectura de los indicios históricos y arquitectónicos inherentes a todo edificio. Muy práctica por su cómodo formato de bolsillo, pero lo suficientemente rigurosa como para ofrecerle las respuestas adecuadas, esta obra:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (708, '9788422682028', 'El lenguaje de las flores', 1, '2000', 1, NULL, 'media/core/9788422682028.jpg', 1, '2023-03-19 12:13:22.320566', '2023-03-19 12:13:22.320566', 513, 18, 6, 5, NULL, '', '03_03', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (709, '8428201714', 'Guía de cempo de las estrellas y los planetas del los hemisferios norte y sur', 1, '1979', 416, 'A Field Guieto the Stars and Planets', 'media/core/8428201714_mBTq1JD.jpg', 1, '2023-03-19 12:24:47.478956', '2023-03-19 12:24:47.478956', 514, 18, 6, 5, NULL, '', '03_03', NULL, 36, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (710, 'B30287', 'El Universo', 3, '1969', 258, 'L''Universo', 'media/core/sin-imagen_Z4O6KLD.jpg', 1, '2023-03-19 12:29:41.727199', '2023-03-19 12:29:41.727199', 515, 38, 6, 5, 'Nueva colección Labor', '', '03_03', NULL, 148, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (711, '978842740687', 'Azul Vermeer', 1, '2013', 441, NULL, 'media/core/9788427040687.jpg', 1, '2023-03-21 08:27:31.781263', '2023-03-21 08:27:31.781263', 516, 1, 6, 5, NULL, '', '03_04', NULL, 188, 'Azul Vermeer, de Mar Mella, es una novela de narrativa española que nos adentra con pulso magistral en el desconocido mundo del arte y los coleccionistas privados, en las intrigas que se esconden tras las galerías más prestigiosas del mundo y en el submundo que oculta el mercado negro de obras sin catalogar. Dos historias de amor separadas en el tiempo pero unidas por el misterio de un cuadro desaparecido; dos personas obsesionadas por el talento del maestro flamenco Vermeer de Delft; un juego de claroscuros unido, pincelada a pincelada, a una obra maestra sin catalogar. La novela revelación del año que te hará descubrir y amar el arte y los colores. Quienes hayan disfrutado con La tabla esmeralda no deben perderse esta novela. Azul Vermeer es la primera novela de Mar Mella, autora que fue finalista del Premio Ateneo de Sevilla 2011. Vermeer de Delft es uno de los artistas más carismáticos y apreciados por la sociedad española.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (712, '9788408030690', 'El maestro del Prado y las pinturas proféticas', 1, '2013', 309, NULL, 'media/core/9788408030690.jpg', 1, '2023-03-21 08:30:19.528074', '2023-03-21 08:30:19.528074', 66, 1, 6, 5, NULL, '', '03_04', NULL, 7, 'Descubre de la mano de Javier Sierra los secretos que se ocultan tras las pinturas más importantes del Museo del PradoINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (713, '9788467226287', 'Asesinato en la Via Apia', 1, '2007', 493, 'Murder on the Appian Way', 'media/core/9788467226287.jpeg', 1, '2023-03-21 08:34:22.164278', '2023-03-21 08:34:22.164278', 517, 1, 6, 5, NULL, '', '03_04', NULL, 15, '', '');
