INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (716, '9788467226263', 'El enigma de Catilina', 1, '2006', 550, 'Catilina''s Riddle', 'media/core/9788467226263.jpg', 1, '2023-03-21 08:42:15.869370', '2023-03-21 08:42:15.869370', 517, 1, 6, 5, NULL, '', '03_04', NULL, 15, 'Harto del desorden y la polución de Roma, Goridano el Sabueso se ha marchado a vivir al campo. Allí traba amistad con Sergio Catilina, conspirador en ciernes que quiere presentarse a las elecciones consulares con su programa radical y populista. La gran ocasión para que Gordiano, con la ayuda de su hijo, saque a relucir su talento, y de paso aumente su ya considerable fortuna.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (717, '9788467226300', 'El cerco de Massilia', 1, '2008', 294, 'Lat seen in Massilia', 'media/core/9788467226300.jpg', 1, '2023-03-21 08:44:58.840468', '2023-03-21 08:44:58.840468', 517, 1, 6, 5, NULL, '', '03_04', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (718, '9788420413099', 'El tango de la Guardia Vieja', 1, '2012', 490, NULL, 'media/core/9788420413099.jpg', 1, '2023-03-21 08:47:56.092606', '2023-03-21 08:47:56.092606', 73, 1, 2, 5, NULL, '', '03_04', NULL, 10, 'La trepidante aventura de Max Costa y Mecha Inzunza les lleva a recorrer tres escenarios distintos del convulso siglo XX: pasarán en 1928 por Buenos Aires gracias a una extraña apuesta entre dos músicos, en Niza se verán envueltos una trama de espionaje durante los años de la Guerra Civil española y los primeros vientos de la segunda Guerra Mundial, para terminar en Sorrento, en los años sesenta, embarcados en una inquietante partida de ajedrez.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (719, '9788420419688', 'Falcó', 1, '2016', 291, NULL, 'media/core/9788420419688.jpg', 1, '2023-03-21 08:50:31.022812', '2023-03-21 08:50:31.022812', 73, 1, 6, 5, NULL, '', '03_04', 'Falcó Vol I', 10, '«El mundo de Falcó era otro, y allí los bandos estaban perfectamente definidos: de una parte él, y de la otra todos los demás.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (720, '9788420419572', 'Eva', 1, '2017', 388, NULL, 'media/core/9788420419572.jpg', 1, '2023-03-21 08:52:37.483045', '2023-03-21 08:52:37.483045', 73, 1, 6, 5, NULL, '', '03_04', 'Falcó Vol II', 10, '«No me tengas por una de esas burguesitas perdidas entre las filas obreras. Soy una agente soviética, y tus criminales jefes fascistas podrían pedirte cuentas.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (721, '9788420432458', 'Sabotaje', 1, '2018', 372, NULL, 'media/core/9788420432458.jpg', 1, '2023-03-21 08:55:33.666771', '2023-03-21 08:55:33.666771', 73, 1, 6, 5, NULL, '', '03_04', 'Falcó Vol III', 10, '', 'Librito adjunto titulado "El París de Sabotaje"');
