INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (730, '9788467266566', 'Historia de un canalla', 1, '2016', 863, NULL, 'media/core/9788467266566.jpg', 1, '2023-03-21 09:42:53.609507', '2023-03-21 09:42:53.609507', 522, 1, 6, 5, NULL, '', '03_04', NULL, 34, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (731, '9788467264265', 'El gran robo del oro español', 1, '2015', 380, NULL, 'media/core/9788467264265.jpg', 1, '2023-03-21 09:45:52.616593', '2023-03-21 09:45:52.616593', 147, 1, 6, 5, NULL, '', '03_04', 'Victor Ros', 34, 'Un robo espectacular. Una maniobra de distracción impecable. Un tesoro nacional en peligro. Un país al borde de la quiebra. Un reto inesperado.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (732, '9788467262919', 'La corona', 1, '2014', 506, 'The Crown', 'media/core/9788467262919.jpg', 1, '2023-03-21 09:49:17.963354', '2023-03-21 09:49:17.963354', 524, 1, 6, 5, NULL, '', '03_04', NULL, 89, 'Londres, 25 de mayo de 1537 Cuando se anuncia una muerte en la hoguera, las tabernas de los alrededores de Smithfield encargan barricas de cerveza adicionales, pero cuando quien va a morir en la hoguera es una mujer y además de noble cuna, llegan carros de cerveza. Yo viajaba en uno de esos carros el viernes de la semana de Pentecostés, en el vigésimo octavo año del reinado de Enrique VIII, para ofrecer plegarias por el alma de la traidora condenada a morir: lady Margaret Bulmer. Cuando la joven novicia Joanna Stafford, hija de la primera dama de la reina Catalina de Aragón, se entera de que su querida prima Margaret va a ser ejecutada públicamente en la hoguera, rompe el voto de clausura y se escapa del monasterio del priorato de Dartford. Sin embargo es detenida junto con su padre, sir Richard Stafford, también presente en la ejecución, y acusados ambos de intentar sabotearla, son encerrados en la Torre de Londres. El padre de Joanna sufre atroces torturas mientras la novicia es tratada con amabilidad y respeto, pero su trato privilegiado se debe al interés que sus dotes intelectuales suscitan en el arzobispo de Winchester. La novicia tendrá que realizar un importante encargo: buscar una misteriosa reliquia portadora de enormes poderes, la corona del primitivo rey de la cristiandad Athelstan, hecha con las espinas de la corona de Cristo. La responsabilidad del cierre de los monasterios de Inglaterra y la vida de su padre están ahora en las manos de Joanna...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (733, '9788408141471', 'La chica del tren', 5, '2015', 491, 'The Girl on the Train', 'media/core/9788408141471.jpg', 1, '2023-03-21 09:52:36.549239', '2023-03-21 09:52:36.549239', 525, 1, 6, 5, NULL, '', '03_04', NULL, 7, '¿Estabas en el tren de las 8.04? ¿Viste algo sospechoso?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (734, '9788467264708', 'El dios del desierto', 1, '2015', 439, 'Desert God', 'media/core/9788467264708.jpg', 1, '2023-03-21 09:58:27.101508', '2023-05-13 10:11:53.046811', 79, 1, 6, 5, NULL, '', '03_04', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (735, '9788467250947', 'Alcazaba', 1, '2012', 476, NULL, 'media/core/9788467250947.jpg', 1, '2023-03-21 10:01:24.474333', '2023-03-21 10:01:24.474333', 215, 16, 6, 5, NULL, '', '03_04', NULL, 190, 'Judit, conocida por todos como la Guapísima por su extraordinaria belleza, aún no ha cumplido los veinticinco años cuando enviuda de Aben Ahmad al-Fiqui, un musulmán con el que su padre la casó por conveniencia. Tras su muerte, Judit, de origen judío, decide buscar nuevo marido, pero es rechazada tanto por musulmanes como por judíos debido a la situación extrema que se vive en Mérida, una ciudad donde imperan las revueltas y las rencillas y donde todos se toleran pero se temen. La calma tensa que preside la relación entre árabes, beréberes, muladíes, judíos y cristianos muy pronto se resquebrajará. La rivalidad y el miedo, además de la codicia de los gobernantes y los feroces tributos anuales que deben rendir a Córdoba hará que se rebelen contra el poder central de Abderramán II.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (736, '9788467231182', 'Episodios nacionales - La España trágica', 1, '2008', 463, NULL, 'media/core/9788467221299.jpg', 1, '2023-03-21 10:27:30.845258', '2023-03-21 10:27:30.845258', 527, 16, 6, 5, NULL, '', '03_04', 'Quinta Serie II', 46, '', '');
