INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (751, '9788481099027', 'La economía del miedo', 5, '2012', 330, NULL, 'media/core/9788481099027.GIF', 1, '2023-03-21 11:10:06.295024', '2023-03-21 11:10:06.295024', 528, 2, 6, 5, NULL, '', '03_04', NULL, 46, 'Alguien escribió una alegoría. En ella, la Gran Recesión dice a los perdedores: lamentamos sinceramente el destino que habéis tenido, pero las leyes de la economía son despiadadas y es preciso que os adaptéis a ellas reduciendo las protecciones. Si os queréis enriquecer debéis aceptar previamente una mayor precariedad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (752, '9788422658535', 'Con España en el corazón', 1, '1995', 206, NULL, 'media/core/9788422658535.jpg', 1, '2023-03-21 11:15:13.231342', '2023-03-21 11:15:13.231342', NULL, 15, 6, 5, NULL, '', '03_04', NULL, 5, 'Primer discurso de la Corona y los mensajes navideños del Rey 1975 - 1995. Edición conmemorativa', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (753, '9788417496203', 'Comprar a Marx por Amazon', 1, '2019', 122, NULL, 'media/core/9788417496203.jpg', 1, '2023-03-21 11:18:20.175162', '2023-03-21 11:18:20.175162', 529, 2, 6, 5, NULL, '', '03_04', NULL, 191, '¿Qué queda de las grandes utopías políticas que han marcado la modernidad? En este diccionario utópico actualizado, el politólogo Pablo Simón traza un recorrido personal, de la A a la Z, por conceptos que un día sacudieron el mundo. Anarquía, barricada, obrero, pueblo, república o socialismo son examinados a la luz de un presente que ha arrojado fuera de la mesa los ideales del siglo pasado.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (754, '8430782885', 'Diccionario/Atlas de Mineralogía', 1, '1974', 1, NULL, 'media/core/8430782885.jpg', 1, '2023-03-21 11:21:58.352121', '2023-03-21 11:21:58.352121', 530, 40, 6, 5, 'Diccionario/Atlas', '', '03_04', NULL, 172, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (755, '9788499421155', 'Por qué Marx tenía razón', 1, '2011', 226, 'Why Marx Was Right', 'media/core/9788499421155.jpg', 1, '2023-03-21 11:25:57.344206', '2023-03-21 11:25:57.344206', 531, 2, 6, 5, NULL, '', '03_04', NULL, 192, 'Este libro se originó a partir de una única y llamativa posibilidad: ¿Y si todas las objeciones que se plantean más habitualmente a la obra de Marx estuvieran equivocadas? ¿O, cuando menos, aun no siendo desatinadas del todo, sí lo fueran en su mayor parte? Con esto no pretendo insinuar que Marx no diera jamás un paso en falso. No soy de ese género de izquierdistas que, por un lado, proclaman devotamente que todo es susceptible de crítica y, al mismo tiempo, cuando se les pide que propongan aunque solo sean tres puntos importantes que se puedan reprochar a las tesis de Marx, reaccionan con malhumorado silencio. Yo mismo tengo mis propias dudas acerca de algunas de las ideas marxianas y creo que este libro lo pondrá suficientemente de manifiesto. Pero la verdad es que Marx tuvo la suficiente razón a propósito del suficiente número de cuestiones importantes como para que llamarse marxista pueda ser una descripción razonable de uno mismo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (756, '9788447369614', 'La armonía es numérica', 1, '2010', 156, NULL, 'media/core/9788447369614.jpg', 1, '2023-03-21 11:34:36.150024', '2023-03-21 11:34:36.150024', NULL, 15, 6, 5, 'El mundo es matemático', '', '03_04', NULL, 193, 'Un gran matemático dijo en una ocasión que la música era "el placer que experimenta la mente humana al contar sin darse cuenta de que está contando". Las conexiones entre música y matemáticas son muchas y fascinantes, desde la relación entre armonía y número que asombró a los pitagóricos hasta las ingeniosas técnicas de repetición y traslación empleadas por Bach, Mozart y muchos otros para componer algunas de sus obras maestras.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (757, '9788447369706', 'Las matemáticas de la vida. Modelos numéricos para la biología y la ecología', 1, '2011', 154, NULL, 'media/core/9788447369706.jpg', 1, '2023-03-21 11:38:15.718604', '2023-03-21 11:38:15.718604', 532, 15, 6, 5, 'El mundo es matemático', '', '03_04', NULL, 193, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (758, '9788447369607', 'Mapas del metro y redes neuronales. La teoría de grafos', 1, '2010', 136, NULL, 'media/core/9788447369607.jpg', 1, '2023-03-21 11:41:14.661619', '2023-03-21 11:41:14.661619', 533, 15, 6, 5, 'El mundo es matemático', '', '03_04', NULL, 193, '', '');
