INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (781, '9788440620507', 'Deryni. Jaque Mate', 1, '1991', 288, 'Deryni Checkmate', 'media/core/9788440620507.jpg', 1, '2023-03-22 08:46:54.002064', '2023-03-22 08:46:54.002064', 538, 13, 6, 5, 'Nova fantasía', '', '04_01', 'Las crónicas de los Deryni II', 8, 'En una Edad Media alternativa, los Deryni, un grupo de magos y telépatas, antaño poderosos, se enfrentan a la autoridad de la pujante religión cristiana y a sus ansias de primacía. El joven rey Kelson y su paladín de estirpe Deryni, el duque Alaric Morgan, desafían las más poderosas armas de la Iglesia: la excomunión y el interdicto. Junto al peligro de perder el apoyo y la comprensión de sus súbditos amenazados por el Interdicto eclesial, Kelson y Morgan deberán enfrentarse también al poder de Warin de Grey, un fanático ungido con los milagrosos atributos de la santidad y empecinado en una terrible "guerra santa" contra los Deryni.', '');
