INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (797, '9788496208872', 'Danza de dragones', 1, '2012', 1131, 'A DAnce with Drgons', 'media/core/9788496208872.jpg', 1, '2023-03-22 12:00:43.034132', '2023-03-22 12:00:43.049754', 543, 13, 6, 5, 'Gigamesh éxitos', '', '04_01', 'Canción de Hielo y Fuego V', 200, 'Canción de hielo y fuego: Libro quintoLa novela río más espectacular jamás escritaDaenerys Targaryen intenta mitigar el rastro de sangre y fuego que dejó en las Ciudades Libres al erradicar la esclavitud en Meereen. Mientras, un enano parricida, un príncipe de incógnito, un capitán implacable y un enigmático caballero acuden a la llamada de los dragones desde el otro lado del mar Angosto, ajenos al peligro que se cierne sobre el Norte, y que solo las menguadas huestes de uno delos reyes en discordia y la Guardia de la Noche se aprestan a afrontar.George R.R. Martin sigue añadiendo sutiles e intrincadas tramas a su impresionante retablo de intrigas y pasiones, y sumando admiradores incondicionales. Rebasa las barreras de los géneros como si nunca hubieran existido: Danza de dragones marca su consagración definitiva entre los más grandes creadores de la historia de la literatura, más allá de cualquier distinciónde etiquetas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (798, '9788496208995', 'Festín de cuervos', 1, '2007', 793, 'A Fest for Crows', 'media/core/9788496208995.jpg', 1, '2023-03-22 12:05:02.531665', '2023-03-22 12:05:02.531665', 543, 13, 6, 5, 'Gigamesh ficción', '', '04_01', 'Canción de Hielo y Fuego IV', 200, 'Canción de hielo y fuego: Libro cuarto La novela río más espectacular jamás escrita. Mientras los vientos del otoño desnudan los árboles, las últimas cosechas se pudren en los pocos campos que no han sido devastados por la guerra, y por los ríos teñidos de rojo bajan cadáveres de todos los blasones y estirpes. Y aunque casi todo Poniente yace extenuado, en diversos rincones florecen nuevas e inquietantes intrigas que ansían nutrirse de los despojos de un reino moribundo. George R.R. Martin continúa sumando hordas de seguidores incondicionales mientras desgrana, con pulso firme y certero, una de las experiencias literarias más ambiciosas y apasionantes que se hayan propuesto nunca en el terreno de la fantasía. Festín de cuervos, como la calma que precede a la tem', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (799, '9788496208988', 'Tormenta de espadas (2 volúmnees)', 1, '2007', 1167, 'A Storm of Swords', 'media/core/9788496208988.jpg', 1, '2023-03-22 12:12:41.832919', '2023-03-22 12:12:41.832919', 543, 13, 6, 5, 'Gigamesh ficción', '', '04_01', 'Canción de Hielo y Fuego III', 200, 'La novela río más espectacular jamás escrita.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (800, '9788496208971', 'Choque de reyes', 1, '2007', 884, 'A Clash of Kings', 'media/core/9788496208971.jpg', 1, '2023-03-22 12:15:07.065627', '2023-03-22 12:15:07.065627', 543, 13, 2, 5, 'Gigamesh ficción', '', '04_01', 'Canción de Hielo y Fuego II', 200, 'Canción de Hielo y Fuego: Libro Segundo, la continuación del best-seller Juego de tronos. La novela río más espectacular jamás escrita. Un cometa del color de la sangre hiende el cielo cargado de malos augurios. Y hay razones sobradas para pensar así: los Siete Reinos se ven sacudidos por las luchas intestinas entre los nobles por la sucesión al Trono de Hierro. En la otra orilla del océano, la princesa Daenerys Targaryen conduce a su pueblo de jinetes salvajes a través del desierto. Y en los páramos helados del Norte, más allá del Muro, un ejército implacable avanza impune hacia un territorio asolado por el caos y las guerras fraticidas. George R.R. Martin, con pulso firme y enérgico, nos deleita con un brillante despliegue de personajes, engranando una trama rica, densa y sorprendente. Nos vuelve testigos de luchas fraticidas, intrigas y traiciones palaciegas en una tierra maldita por la guerra, donde fuerzas ocultas se alzan de nuevo y acechan para reinar en las noches del largo invierno que se avecina. Éxito rotundo de ventas, destinado a la distribución masiva tanto en tiendas especializadas como generales.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (801, '9788496208964', 'Juego de tronos', 1, '2007', 772, 'A Game of Thrones', 'media/core/9788496208964.jpg', 1, '2023-03-22 12:18:59.866342', '2023-03-22 12:18:59.866342', 543, 13, 6, 5, 'Gigamesh ficción', '', '04_01', 'Canción de Hielo y Fuego I', 200, 'Tras el largo verano, el invierno se acerca a los Siete Reinos. Lord Eddars Stark, señor de Invernalia, deja sus dominios para unirse a la corte del rey Robert Baratheon el Usurpador, hombre díscolo y otrora guerrero audaz cuyas mayores aficiones son comer, beber y engendrar bastardos. Eddard Stark desempeñará el cargo de Mano del Rey e intentará desentrañar una maraña de intrigas que pondrá en peligro su vida... y la de los suyos. En un mundo cuyas estaciones duran décadas y en el que retazos de una magia inmemorial y olvidada surgen en los rincones más sombrios y maravillosos, la traición y la lealtad, la compasión y la sed de venganza, el amor y el poder hacen del juego de tronos una poderosa trampa que atrapa en sus fauces a los personajes... y al lector', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (802, '9788416035373', 'El caballero de los siete reinos', 1, '2015', 280, 'A Knight of Seven Kingdoms', 'media/core/9788416035373.jpeg', 1, '2023-03-22 12:21:51.625001', '2023-03-22 12:21:51.625001', 543, 13, 6, 5, 'Gigamesh ficción', '', '04_01', NULL, 200, 'Las andanzas de un caballero de Poniente Los tres primeros relatos de Dunk y EggMuchas son las historias que se cuentan sobre Aegon V el Improbable y ser Duncan el Alto, su leal comandante de la Guardia Real. Pero la magia y la épica de la leyenda esconden la verdadera naturaleza de los héroes: la determinación de un huérfano del Lecho de Pulgas que llegó a caballero, el arrojo de un príncipe que cambió la corte por los caminos y una amistad inquebrantable capaz de vencer intrigas, traiciones... y revueltas. Durante los reinados de Daeron II y Aerys I, cuando las heridas de la rebelión de los Fuegoscuro todavía estaban abiertas, tienen lugar las primeras aventuras de un caballero fornido y bonachón y de su escudero, un infante real, fiel y de fuerte temperamento. A medio camino entre la fantasía heroica y la novela de caballerías, El caballero de los Siete Reinos narra las peripecias de dos héroes bondadosos en una tierra despiadada.«En la tradición epicofantástica, Martin es el mejor con diferencia.» Time Magazine', '');
