INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (804, '9788422672982', 'Ramsés. La dama de Abu Simbel', 1, '1998', 383, 'Ramsès. La dame d''Abou Simbel', 'media/core/9788422672982.jpg', 1, '2023-03-23 07:27:20.291757', '2023-03-23 07:27:20.291757', 118, 16, 6, 5, NULL, '', '04_01', 'Ramsés Vol. IV', 15, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (805, '9788422667674', 'Ramsés. El hijo de la luz', 1, '1996', 383, 'Ramsès. Le fils de la lumière', 'media/core/9788422667674.GIF', 1, '2023-03-23 07:31:00.902272', '2023-03-23 07:45:11.961604', 118, 16, 6, 5, NULL, '', '04_01', 'Ramsés. Vol I', 15, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (806, '9788422660217', 'La pirámide asesinada', 1, '1995', 447, 'La pyramide assassinée', 'media/core/9788422660217.jpg', 1, '2023-03-23 07:34:31.792636', '2023-03-23 07:34:31.792636', 118, 16, 6, 5, NULL, '', '04_01', NULL, 15, 'Pazair es un joven juez en una provincia del sur del antiguo Egipto. Neferet es médico en Menfis la gran ciudad del norte adonde Pazair es llamado. Conforme a las predicciones de un viejo visionario un monstruoso complot ha sido maquinado para derrocar a Ramsés el Grande. Nada podrá evitarlo nada excepto un insignificante juez que se niega a firmar un documento administrativo que no entiende. Con la ayuda de su hermano de sangre Suti el juez Pazair busca la verdad. En el camino se encuentra con Neferet bellísima doctora que ha logrado triunfar en su carrera a pesar de la oposición del jefe de los médicos de la corte. El juez se enamora de ella y llega a descubrir la traición de un importante general del ejército egipcio. Pero los implicados en el complot están decididos a acabar con Pazair. Éste es el motivo por el que el juez es detenido y por lo que hacen creer a Neferet que él ha muerto.', '');
