INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (810, '9788425340369', 'El río sagrado', 1, '2006', 330, 'El río sagrado', 'media/core/9788425340369.jpg', 1, '2023-03-23 08:18:29.548409', '2023-03-23 08:18:29.548409', 546, 16, 6, 5, 'Novela Histórica', '', '04_01', NULL, 45, 'El autor la acción hasta las costas galaicoportuguesas, a las puertas de la invasión romana, desde la mirada de Turio, un niño con poderes adivinatorios. En la obra tienen una gran presencia los elelementos sobrenaturales, centrados en ese joven de salud delicada que acompaña a las tropas resistentes y actúa como intermediario entre los dioses y los hombres, y que Aguiar combina magistralmente con la recreación histórica de la vida, la cultura y creencias de los antiguos pobladores del norte de la Península Ibérica.', '');
