INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (817, '9788466659345', 'Mater familias', 1, '2016', 382, 'Deadly Election', 'media/core/9788466659345.JPG', 1, '2023-03-23 08:46:02.166231', '2024-02-22 19:03:41.622499', 551, 1, 6, 5, NULL, '', '04_01', NULL, 8, 'En uno de los lotes de la casa de subastas donde trabaja Flavia Albia se ha descubierto un cadáver en descomposición. ¿De quién se trata? ¿Cómo ha llegado hasta ahí?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (818, '9788466661256', 'El cementerio de las Hespérides', 1, '2017', 459, 'The Graveyard  of the Hesperides', 'media/core/9788466661256.JPG', 1, '2023-03-23 08:49:17.180263', '2023-03-23 08:49:17.180263', 551, 1, 6, 5, NULL, '', '04_01', NULL, 8, 'De la aclamada Lindsey Davis (“Emperatriz de la intriga histórica” para El Periódico de Catalunya; “La Agatha Christie de la Antigua Roma” según Santiago Posteguillo), creadora del queridísimo personaje de Marco Didio Falco, llega la nueva novela protagonizada por la hija de este, Flavia Albia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (819, '9788435062787', 'Los idus de Abril', 1, '2014', 444, 'The Ides of April', 'media/core/9788435062787.jpg', 1, '2023-03-23 08:53:00.832630', '2023-03-23 08:53:00.832630', 551, 1, 6, 5, 'Narrativas históricas', '', '04_01', NULL, 47, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (820, '9788435062367', 'Némesis. La XX novela de Marco Didio Falco', 1, '2011', 508, 'Nemesis', 'media/core/9788435062367.jpg', 1, '2023-03-23 08:56:39.371317', '2023-03-23 08:56:39.371317', 551, 1, 6, 5, 'Narrativas históricas', '', '04_01', NULL, 47, 'La gran maestra de la novela histórica presenta la vigésima entrega de su aclamada serie protagonizada por Marco Didio Falco, en la que vemos al más célebre detective de la historia abrumado de nuevo por enrevesados problemas familiares, a los que la muerte de su padre, lejos de ponerles fin, no hace sino complicar hasta extremos delirantes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (821, '8422634449', 'Almas muertas, El capote y otros relatos', 1, '1991', 530, NULL, 'media/core/8422634449.jpeg', 1, '2023-03-23 09:00:50.983391', '2023-03-23 09:00:50.983391', 552, 1, 6, 5, 'Biblioteca de Plata de los Clásicos Rusos', '', '04_01', NULL, 5, '', '');
