INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (850, '9788427014695', 'En costas extrañas', 1, '1990', 278, 'On Stranger Tides', 'media/core/9788427014695.jpeg', 2, '2023-03-24 12:31:43.684917', '2023-04-01 07:36:32.390275', 519, 1, 6, 5, NULL, '', '04_02', NULL, 188, 'Una extraordinaria novela de fantasia historica centrada en la pirateria del siglo XVIII en el Caribe.1718. Barbanegra uno de los ultimos piratas que se enfrentaron a la flota del rey Jorge de Inglaterra aterroriza las costas del Caribe. En tan desagradable compañia y en contra de su voluntad navega John Chandagnac tenedor de libros y titiritero. No parece un buen candidato a pirata ni alguien dado a las oscuras maquinaciones de la hechiceria pero un capitan borracho lo rebautiza como Jack Shandy y llega a convertirse en uno de sus líderes... con precio puesto a su cabeza.', '');
