INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (867, '9788481098846', 'Eterno reposo y otras narraciones', 1, '2013', 245, NULL, 'media/core/9788481098846.jpg', 1, '2023-03-25 07:42:11.382361', '2023-03-25 07:42:11.382361', 579, 29, 6, 5, NULL, '', '04_02', NULL, 46, 'El presente volumen reúne por primera vez en castellano una selección de los cuentos de Vasili Grossman. El autor de Vida y destino escribió cuentos toda su vida, desde los primeros publicados en los años treinta, y que despertaron la admiración de Gorki, hasta los escritos poco antes de morir en 1964. Eterno reposo y otras narraciones incluye ocho textos escritos entre 1953 y 1963: «Abel», «Tiergarten», «La Madonna Sixtina», «Eterno reposo», «Mamá», «El camino», «Fósforo» y «En Kislovodsk». Son pues contemporáneos de la redacción de Vida y destino y los últimos fueron escritos cuando Grossman, ya enfermo, daba por perdida su obra maestra requisada por la KGB. Escritos con una sensibilidad extrema, estos cuentos nos muestran a Grossman en el punto culminante de su escritura, en la que aparecen los grandes temas que prevalecen también en Vida y destino y en Todo fluye. La sumisión y la mezquindad de unos, la revuelta y la bondad de otros; la solidaridad y el sacrificio del hombre en lucha; el absurdo de la guerra y la voracidad de las maquinarias ciegas del Estado totalitario; el secreto de la vida y de la libertad y la búsqueda de «la humanidad del ser humano», para utilizar la expresión de Grossman en «La Madonna Sixtina».', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (868, '8435003507', 'Egidio, el grnajero de Ham / Hoja de niggle / El herrero de Wootton mayor', 2, '1982', 144, 'Farmer Giles of Ham / Leaf by Niggle / Smith of Eoottom Major', 'media/core/8435003507.jpg', 1, '2023-03-25 07:47:00.110544', '2023-03-25 07:47:00.110544', 580, 13, 6, 5, NULL, '', '04_02', NULL, 210, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (869, '8445070703', 'El Señor de los Anillos. Apéndices', 1, '1987', 174, 'The Lord of Rongs. Appendix', 'media/core/8445070703.jpg', 1, '2023-03-25 07:50:02.310382', '2023-05-13 10:11:00.556100', 580, 13, 6, 5, NULL, '', '04_02', NULL, 210, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (870, '844507038X', 'El Silmarillion', 5, '1987', 415, 'The Silmarillion', 'media/core/844507038X.jpg', 1, '2023-03-25 07:56:12.899296', '2023-05-13 10:11:12.738878', 580, 13, 2, 5, NULL, '', '04_02', NULL, 210, 'Este libro es el cuerpo central de los textos narrativos de JRR Tolkien, una obra que no pudo publicar en vida porque creció junto a él. Tolkien comenzó a escribirlo mucho antes que El Hobbit, obra concebida como historia independiente, pero que fue parte de los que él llamaba un "tema que acopia y se ramifica", y del que emergió El Señor de los Anillos. El Silmarillion cuenta la historia de la Primera Edad, el antiguo drama del que hablan los personajes de El Señor de los Anillos, y en cuyos acontecimientos algunos de ellos tomaron parte, como Elrond y Galadriel. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (871, '8422616335', 'El Señor de los Anillos', 1, '1986', 1095, 'The Lord of the Rings', 'media/core/8422616335.jpg', 1, '2023-03-25 08:01:40.768415', '2023-03-25 08:01:40.768415', 580, 13, 6, 5, NULL, '', '04_02', NULL, 214, 'La vigorosa prosa épica y el rico universo literario de J.R.R. Tolkien gira en torno a un tema básico: la inevitable corrupción que apareja todo poder y el subsiguiente combate entre las fuerzas del bien y del mal, inequívoco reflejo del eterno conflicto que dirimen las civilizaciones y los hombres desde los albores de la historia. Magistrales novelas que plasman el sólido ideario lingüístico, poético y filosófico de uno de los autores más importantes de nuestro tiempo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (872, '9781405281904', 'The Best Bear in All the World', 1, '2016', 103, NULL, 'media/core/9781405281904.jpeg', 1, '2023-03-25 08:06:08.477229', '2023-03-25 08:06:08.477229', 581, 27, 6, 5, NULL, '', '04_02', NULL, 215, '', 'With E H Shepard');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (873, '9788498380798', 'El niño con el pijama de rayas', 8, '2007', 217, 'The Boy in the Striped Pyjamas', 'media/core/9788498380798.jpg', 1, '2023-03-25 08:09:16.828189', '2023-03-25 08:09:16.829185', 48, 1, 6, 5, NULL, '', '04_02', NULL, 29, 'Aunque el uso habitual de un texto como éste es describir las características de la obra, por una vez nos tomaremos la libertad de hacer una excepción a la norma establecida. No sólo porque el libro que tienes en tus manos es muy difícil de definir, sino porque estamos convencidos de que explicar su contenido estropearía la experiencia de la lectura. Creemos que es importante empezar esta novela sin saber de qué trata.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (874, '8422624141', 'Miedo y Asco en Las Vegas', 1, '1987', 206, 'Fear and Loathing in Las Vegas', 'media/core/8422624141.jpeg', 1, '2023-03-25 08:12:57.681205', '2023-03-25 08:12:57.681205', 582, 1, 6, 5, NULL, '', '04_02', NULL, 216, '', '');
