INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (897, '9788408197522', 'Egipto', 6, '2019', 1, NULL, 'media/core/9788408197522.jpg', 1, '2023-03-27 06:08:19.066605', '2023-03-27 06:08:19.066605', 600, 18, 6, 5, 'geoPlaneta', '', '04_03', NULL, 7, 'La guía más completa de Egipto, con mapas claros y los mejores consejos para planificar el viaje.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (898, '9788408112389', 'Historia de España', 5, '2018', 266, 'histoire de l''Espagne', 'media/core/9788408112389.jpg', 1, '2023-03-27 06:11:31.005081', '2023-03-27 06:11:31.005081', 441, 2, 6, 5, 'Contemporánea Humanidades', '', '04_03', NULL, 61, 'Este autentico best seller nos ofrece una visión innovadora de la historia de España, desde sus orígenes hasta el cambio político de 1996, que integra los hallazgos más recientes de la investigación y se propone combatir el viejo tópico de "España es diferente". El autor reivindica los rasgos positivos que se manifiestan en la conquista de America, la importancia de la Ilustración en la Península o el curso temprano de su proceso de modernización. Joseph Perez afirma que, como todos los países, España tiene su originalidad pero que no constituye un mundo aparte y explica las razones de una peculiaridad más aparente que real. Su propósito es demostrarnos que nuestro país pertenece a la familia de las naciones europeas no sólo desde 1985, con la adhesión a las instituciones comunitarias, sino desde siempre, o casi siempre.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (899, '8426411487', 'El nombre de la rosa', 12, '1985', 607, 'Il nome della rosa', 'media/core/8426411487.jpg', 1, '2023-03-27 06:14:19.509763', '2023-03-27 06:14:19.509763', 104, 1, 6, 5, NULL, '', '04_03', NULL, 21, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (900, '9788467267907', 'Nada', 1, '2009', 276, NULL, 'media/core/9788467267907.jpg', 1, '2023-03-27 06:19:51.574875', '2023-03-27 06:19:51.574875', 601, 1, 6, 5, NULL, '', '04_03', NULL, 15, 'Andrea llega a Barcelona para estudiar Letras. Sus ilusiones chocan, inmediatamente, con el ambiente de tensión y emociones violentas que reina en casa de su abuela. Andrea relata el contraste entre este sórdido microcosmos familiar—poblado de seres extraños y apasionantes—y la frágil cordialidad de sus relaciones universitarias, centradas en la bella y luminosa Ena. Finalmente los dos mundos convergen en un diálogo dramático.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (901, '8422652234', 'El extraño caso del Dr. Jekyll y Mr. Hyde', 1, '1994', 152, 'Dr. Jekyll and Mr. Hyde', 'media/core/8422652234.jpg', 1, '2023-03-27 06:23:35.938825', '2023-03-27 06:23:35.938825', 494, 1, 6, 5, NULL, '', '04_03', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (902, '9788423350995', 'El guardián invisible', 1, '2016', 427, NULL, 'media/core/9788423350995.jpg', 1, '2023-03-27 06:27:47.961652', '2023-03-27 06:27:47.961652', 145, 1, 6, 5, 'Booket', '', '04_03', 'Trología del Baztán I', 55, 'Impactante thriller que tiene su mejor baza en el contraste entre lo racional y científico, y lo legendario y mítico.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (903, '9788423351008', 'Legado en los huesos', 1, '2016', 549, NULL, 'media/core/9788423351008.jpg', 1, '2023-03-27 06:29:59.864778', '2023-03-27 06:29:59.864778', 145, 1, 6, 5, 'Booket', '', '04_03', 'Trología del Baztán 2', 55, 'Tras El guardián invisible, más emoción, más tensión, más revelaciones en el segundo volumen de la Trilogía del Baztán. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (904, '9788423351015', 'Ofrenda a la tormenta', 1, '2016', 544, NULL, 'media/core/9788423351015.jpg', 1, '2023-03-27 06:32:13.946916', '2023-03-27 06:33:15.694642', 145, 1, 6, 5, 'Booket', '', '04_03', 'Trología del Baztán 3', 55, 'El desenlace de la Trilogía del Baztán. Nunca lo habrías imaginado.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (905, '9788422698456', 'Crónica de una muerte anunciada', 1, '2002', 140, NULL, 'media/core/9788422698456.jpg', 1, '2023-03-27 06:41:52.538329', '2023-03-27 06:41:52.538329', 602, 1, 6, 5, NULL, '', '04_03', NULL, 230, 'Un hombre regresa al pueblo donde ocurrió un asesinato desconcertante 27 años atrás, con la determinación de descubrir la verdad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (906, '9788433966544', 'Los desnudos y los muertos', 5, '2015', 695, 'The Naked and the Dead', 'media/core/9788433966544.jpg', 1, '2023-03-27 06:46:19.595781', '2023-03-27 06:46:19.595781', 603, 1, 6, 5, 'Colección compactos', '', '04_03', NULL, 6, 'Los desnudos y los muertos apareció en los Estados Unidos en mayo de 1948, exactamente tres años después del día de la victoria de los aliados en la Segunda Guerra Mundial. Norman Mailer tenía entonces veintiséis años, y tras graduarse en Harvard y alistarse en el ejército había estado entre las tropas que ocuparon Japón después de la derrota. La crítica calificó su obra como «la más grande novela de guerra escrita en este siglo», que con el tiempo se ha convertido en un libro mítico. Mailer fue comparado con Hemingway y Tolstói y se situó de inmediato entre los grandes de la literatura americana.En Anopopei, un pequeño islote del Pacífico en forma de ocarina, un universo cerrado donde rigen leyes y sentimientos muy diferentes de los de la vida de los civiles, una patrulla de jóvenes soldados, microcosmos de la sociedad americana están Hearn, un joven intelectual que lee a Rilke; el realista e implacable sargento Croft; Ridges, un campesino sureño; Red Valsen, minero de Montana y anarcosindicalista; Gallagher, un irlandés católico de los barrios bajos de Boston y, planeando sobre todos ellos, la poderosa sombra del general Cummings, nacido en la América más profunda e integrista, secretamente fascinado por el nuevo orden del fascismo..., es enviada en una misión de reconocimiento, una larga marcha por un terreno desconocido y lleno de minas que acabará en una pesadilla de abyección y heroísmo, posiblemente tan gratuita como la guerra misma.Empujados al último límite, permanentemente desnudos ante la muerte, los héroes de Mailer cuestionan las verdades del pasado y la vigencia de los ideales americanos, viven obsesionados por el sexo y padecen y hacen padecer a otros las corrupciones y arbitrariedades del poder.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (907, '8447300048', 'La insoportable levedad del ser', 1, '1992', 316, 'Nesnesitelná lehkost byti', 'media/core/8447300048.jpeg', 1, '2023-03-27 06:50:23.792465', '2023-03-27 06:50:23.792465', 604, 1, 6, 5, 'Narrativa actual', '', '04_03', NULL, 32, 'Esta es una extraordinaria historia de amor, o sea de celos, de sexo, de traiciones, de muerte y también de las debilidades y paradojas de la vida cotidiana de dos parejas cuyos destinos se entrelazan irremediablemente. Guiado por la asombrosa capacidad de Milan Kundera de contar con cristalina claridad, el lector penetra fascinado en la trama compleja de actos y pensamientos que el autor va tejiendo con diabólica sabiduría en torno a sus personajes. Y el lector no puede sino terminar siendo el mismo personaje, cuando no todos a la vez. Y es que esta novela va dirigida al corazón, pero también a la cabeza del lector. En efecto, los celos de Teresa por Tomás, el terco amor de éste por ella opuesto a su irreflenable deseo de otras mujeres, el idealismo lírico y cursi de Franz, amante de Sabina, y la necesidad de ésta, amante también de Tomás, de perseguir incansable, una libertad que tan sólo la conduce a la insoportable levedad del ser, se convierten de simple anécdota en reflexión sobre problemas filosóficos que, afectan a cada uno directamente, cada día.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (908, '9788484288282', 'Pioneros de la ciencia ficción russa', 1, '2013', 346, NULL, 'media/core/9788484288282.jpg', 1, '2023-03-27 06:54:46.463878', '2023-03-27 06:54:46.463878', 605, 3, 6, 5, 'Rara avis', '', '04_03', NULL, 119, 'Reunimos en este libro cinco espléndidos relatos de los padres de la ciencia ficción rusa, desconocidos en lengua española. «Entre la vida y la muerte» (1892) de Alekséi N. Apujtin plantea el dilema de laconciencia enfrentada a la muerte y recrea una inquietante experiencia de déjà vu. «En otro planeta» (1896) de Porfiri P. Infántiev relata un asombroso viaje a Marte, habitado por monstruosas pero inteligentísimas y benevolentes criaturas que han creado una civilización anfibia e inventado técnicas e instrumentos que se adelantan a nuestros modernos dvd, satélites artificiales o paneles de energía solar. De Valeri Y. Briúsov recogemos dos intensas visiones apocalípticas: en «La Montaña de la Estrella» (1899), un explorador errante descubre una extrañísima y cruel civilización de origen marciano asentada en un desierto africano; «La República de la Cruz del Sur» (1904-1905) anticipa tanto la dictadura del proletariado como las historias de zombis en la crónica de una epidemia de locura en una próspera república fundada en el Polo Sur. Por último, «El misterio de las paredes» (1906) de Serguéi R. Mintslov gira en torno a un aparato que permite ver y oír lo ocurrido hace siglos entre las paredes de un edificio.', 'No es el autor. Es quien ha hecho la selección');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (909, '9788417578374', 'La Almería vaciada', 1, '2020', 61, NULL, 'media/core/9788417578374.jpg', 1, '2023-03-27 06:57:29.416666', '2023-03-27 06:57:29.416666', 572, 1, 6, 5, 'Narradores almerienses', '', '04_03', 'Relatos de verano II', 231, 'Relatos incluídos: Cabañuelas de agosto, por Diego Reche Ningún pasado fue mejor, por Carmelo Martínez Anaya Un camino fácil, por Carmen Lorenzo Benavides Paseo por las vastas soledades, por Ginés Bonillo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (910, '9788494469930', 'Los del sud us matarem a tots', 1, '2016', 381, NULL, 'media/core/9788494469930.jpg', 1, '2023-03-27 07:01:27.308574', '2023-03-27 07:01:27.308574', 606, 1, 6, 5, 'Distorsions', '', '04_03', NULL, 232, 'És l''any 2032 i, després d''una època de convulsions polítiques i geològiques, Catalunya viu subjugada al poder andorrà. En aquest món postapocalíptic Valero Sanmartí ja és una vella glòria, un humorista fracassat amb un xou per a nostàlgics a BCN World, el parc d''atraccions en què s''ha convertit Barcelona. Escrit amb format "tria la teva aventura", a "Los del sud us matarem a tots" el lector haurà d''ajudar el Valero a recuperar la dignitat perduda, reunint els supervivents de la Catalunya Nova per liderar-los en una guerra civil contra la Catalunya Vella. Una crítica ferotge, corrosiva i sanguinària de la realitat catalana en la qual els personatges més visibles del món polític, cultural i econòmic català apareixen caricaturitzats, deformats i maltractats fins a uns extrems mai vistos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (911, 'B39028', 'Coyuntura económica y reformismo burgués', 1, '1968', 215, NULL, 'media/core/B39028.jpg', 1, '2023-03-27 07:06:08.002115', '2023-03-27 07:06:08.002115', 607, 2, 6, 5, 'ariel quincenal', '', '04_03', NULL, 144, 'Cinco estudios de la historia de España', '');
