INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (929, '8474612500', 'El principe y elmendigo', 1, '1983', 1, NULL, 'media/core/8474612500.jpeg', 1, '2023-03-28 07:32:54.233462', '2023-03-28 07:32:54.233462', 622, 1, 6, 5, NULL, '', '04_04', NULL, 234, '"Y si yo pudiera vestirme una vez, dulce señor, como vos vais vestido; tan solo una vez  Ah! ¿Te gustaría? Pues así será. Quítate tus andrajos y ponte estas galas, muchacho. Es una dicha breve, pero no por ello menos viva. Lo haremos mientras podamos y nos volveremos a cambiar antes de que alguien venga a molestarnos. Pocos minutos más tarde, el pequeño Príncipe de Gales estaba ataviado con los confusos andrajos de Tom, y el pequeño Príncipe de la Indigencia estaba ataviado con el vistoso plumaje de la realeza. Los dos fueron hacia un espejo y se pararon uno junto al otro, y, hete aquí, un milagro: no parecía que se hubiera hecho cambio alguno! Se miraron mutuamente con asombro, luego al espejo, luego otra vez uno al otro. Por fin, el perplejo principillo dijo: ¿Qué dices a esto?  Ah, Vuestra Merced, no me pidáis que os conteste! No es conveniente que uno de mi condición lo diga. Entonces lo diré yo. Tienes el mismo pelo, los mismos ojos, la misma voz y porte, la misma figura y estatura, el mismo rostro y continente que yo. Si saliéramos desnudos públicamente, no habría nadie que pudiera decir quién eras tú y quién el Príncipe de Gales. El príncipe y el mendigo, editada por primera vez en Canadá en 1881 antes de ser publicada en los Estados Unidos en 1882, es la primera novela histórica de Mark Twain. Ambientada en 1547, cuenta la historia y aventuras de dos niños de apariencia física idéntica: Tom Canty, un mendigo que vive con su padre cruel en Offal Court, Londres, y el príncipe Eduardo, hijo de Enrique VIII de Inglaterra.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (930, '8474612853', 'Vidas paralelas. Demóstenes y Cicerón // Pericles y Fabio Máximo', 1, '1984', 173, NULL, 'media/core/8474612853.jpg', 1, '2023-03-28 07:37:16.405635', '2023-03-28 07:37:16.405635', 623, 2, 6, 5, NULL, '', '04_04', NULL, 234, 'Vidas paralelas, de Plutarco constituye uno de los libros que más ha influido sobre la cultura occidental. Ha sido lectura favorita de varios conquistadores y de hombres de letras como Montaigne y Shakespeare. La frase "varón de Plutarco" se ha hecho proverbial para designar a un hombre de virtudes superiores. Al gran número de hechos que Plutarco reunió, con igual sentido crítico que el que puede exigirse a un historiador moderno, se une el alto criterio moral con que valora.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (931, '8474613108', 'LLuvias primaverales / Un sueño', 1, '1984', 179, NULL, 'media/core/8474613108.jpg', 1, '2023-03-28 07:39:33.897944', '2023-03-28 07:39:33.897944', 624, 1, 6, 5, NULL, '', '04_04', NULL, 234, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (932, '8474613841', 'La hija del capitán', 1, '1984', 174, NULL, 'media/core/8474613841.jpg', 1, '2023-03-28 07:41:57.573505', '2023-03-28 07:41:57.573505', 625, 1, 6, 5, NULL, '', '04_04', NULL, 234, 'La hija del capitán es una novela histórica aunque narre hechos prácticamente contemporáneos a la vida de Pushkin. La obra está considerada como una de las mejores de la literatura rusa y, en palabras de Gogol, ''la pureza y la simplicidad alcanzan tal altura, que la verdad misma parece artificial y caricaturesca.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (933, '8474612896', 'Los últimos días de Pompeya', 1, '1984', 200, NULL, 'media/core/8474612896.jpg', 1, '2023-03-28 07:44:47.041326', '2023-04-05 10:07:54.640585', 737, 1, 6, 5, NULL, '', '04_04', NULL, 234, 'Pompeya, año 79 d.C. Glauco, Diones, Nydia y Arbaces viven los cuatro días previos a la erupción del Vesubio, ajenosINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (934, '8474612926', 'La casa y el mundo', 1, '1984', 174, NULL, 'media/core/8474612926.jpg', 1, '2023-03-28 07:47:05.668470', '2023-03-28 07:47:05.668470', 627, 1, 2, 5, NULL, '', '04_04', NULL, 234, 'Bengala, India, principios del siglo XX. El aristócrata y terrateniente Nikhil,contraviniendo todas sus tradiciones familiares y los convencionalismos socialesde la época, se casa con la joven Bimala, una chica de baja extracciónsocial y tez bastante oscura. Su amor es idílico y los esposos están entregadosel uno al otro hasta que aparece su amigo Sandip, un revolucionarioradical y entusiasta que constituye el contrapunto del pacífico y hasta pasivoNikhil.Después de oírlo en un mitin propugnando el movimiento Swadeshi, unapropuesta para la autosuficiencia india enmarcada en la dinámica generalde la independencia, Bimala acoge a Sandip en la casa de su marido, dondeestablece su cuartel general, y acaba involucrándose en su tarea política.Inevitablemente, una joven Bimala que lo desconoce casi todo del mundose sentirá fuertemente atraída por él y se establecerá finalmente un triánguloamoroso.Bimala empieza a cuestionarse su matrimonio con Nikhil y experimentapor primera vez un amor que va más allá de la devoción. Aunque Nikhiles consciente bien pronto de esta situación, su actitud es dejar que Bimalacrezca y decida por sí misma, ya que su matrimonio fue un arreglo cuandotodavía era una niña.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (935, '8474612829', 'Tamarís', 1, '1984', 186, NULL, 'media/core/8474612829.jpg', 1, '2023-03-28 07:49:46.505359', '2023-03-28 07:49:46.505359', 628, 1, 6, 5, NULL, '', '04_04', NULL, 234, 'Expresión directa del espíritu romántico decimonónico desde el punto de vista femenino, liberador de prejuicios ancestrales con respecto a la mujer y su mundo, mucho más cómplice y amistoso con el hombre moderno, en un entorno campestre que pone en contradicción la vitalidad e imaginación burguesa con el enraizamiento y los valores tradicionales del campesino .', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (936, '8474613906', 'El jugador', 1, '1984', 159, NULL, 'media/core/8474613906.jpg', 1, '2023-03-28 07:51:54.606937', '2023-03-28 07:51:54.606937', 534, 1, 6, 5, NULL, '', '04_04', NULL, 234, 'Novela de indudable trasfondo autobiográfico, EL JUGADOR (1866) refleja los dos grandes impulsos -el juego y la pasión amorosa- que dominaron la vida de Fiódor Dostoyevski (1821-1881). En medio de una galería de personajes desarraigados y trashumantes que deambulan por la ciudad-balneario de Wiesbaden (el «Roulettenburg» de la ficción), la patética figura de Aleksei Ivanovich personifica el goce y la angustia del tipo humano que acaba por canalizar toda su capacidad de protesta en la pasión por el juego como vía de acceso, mediante el dolor y el envilecimiento, a una libertad vorazmente deseada.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (937, '8474613256', 'El Conde Lucanor', 1, '1984', 244, NULL, 'media/core/8474613256.jpg', 1, '2023-03-28 09:45:34.860363', '2023-03-28 09:45:34.860363', 629, 21, 6, 5, NULL, '', '04_04', NULL, 234, '', '');
