INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (939, '8474613949', 'El esplin de Paris', 1, '1985', 183, NULL, 'media/core/8474613949.jpg', 1, '2023-03-28 09:52:03.069511', '2023-03-28 09:52:03.069511', 631, 29, 6, 5, NULL, '', '04_04', NULL, 234, 'ENTRE todos los poetas modernos, Charles-Pierre Baudelaire (París, 1821-1867) ocupa un lugar privilegiado. Es quien mejor ha sobrevivido a su tiempo y quien mayor influencia ha ejercido sobre la poesía posterior.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (940, '8474613264', 'María Estuardo // Guillermo Tell', 1, '1984', 203, NULL, 'media/core/8474613264.jpg', 1, '2023-03-28 09:54:15.826729', '2023-03-28 09:54:15.826729', 632, 1, 6, 5, NULL, '', '04_04', NULL, 234, '', '');
