INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (943, '8474612799', 'El extraño caso del Dr. Jekyll y Mr. Hyde', 1, '1984', 200, NULL, 'media/core/8474612799.jpg', 1, '2023-03-28 10:01:02.569414', '2023-03-28 10:01:02.569414', 494, 1, 6, 5, NULL, '', '04_04', NULL, 234, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (944, '8474612470', 'La ilustre casa de Ramires', 1, '1893', 208, NULL, 'media/core/8474612470.jpeg', 1, '2023-03-28 10:03:55.774522', '2023-03-28 10:03:55.774522', 635, 1, 6, 5, NULL, '', '04_04', NULL, 234, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (945, '8474613205', 'Tom Jones', 1, '1984', 288, NULL, 'media/core/8474613205.jpg', 1, '2023-03-28 10:06:39.787086', '2023-03-28 10:06:39.787086', 636, 1, 6, 5, NULL, '', '04_04', 'Vol. II', 234, 'Está considerada la obra maestra de Fielding y es una de las primeras y más influyentes novelas inglesas. Fue recibida con gran entusiasmo por el público de la época.Tom Jones es apuesto y gentil, valiente y mujeriego. Es bueno aunque las apariencias le contradicen. Un cuadro de costumbres donde las lacras sociales se encuentran con las mejores apariencias.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (946, '8474612462', 'Los viajes de Gulliver', 1, '1983', 345, NULL, 'media/core/8474612462.jpg', 1, '2023-03-28 10:09:56.018743', '2023-03-28 10:09:56.018743', 637, 1, 6, 5, NULL, '', '04_04', NULL, 234, 'Los viajes de Gulliver (1726), aparecido como obra anónima siete años después del Robinson Crusoe de Defoe, cuenta los fantásticos viajes del cirujano y capitán de barco Lemuel Gulliver tras su naufragio en una isla perdida. Pronto Gulliver descubrirá que la isla está habitada por una increíble sociedad de seres humanos de tan solo seis pulgadas de estatura, los liliputienses, engreidos y vanidosos ciudadanos de Liliput. En un segundo viaje Gulliver descubre Brodbingnag, una tierra poblada por hombres gigantes, de gran capacidad práctica, pero incapaces de pensamientos abstractos. En su tercer viaje va a parar a la isla volante de Laputa, cuyos habitantes son científicos e intelectuales, ciertamente pedantes, obsesionados con su particular campo de investigación pero totalmente ignorantes del resto de la realidad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (947, '8474613094', 'Libro de su vida', 1, '1984', 213, NULL, 'media/core/8474613094.jpeg', 1, '2023-03-28 10:12:52.382203', '2023-03-28 10:12:52.382203', 638, 31, 6, 5, NULL, '', '04_04', NULL, 234, 'El Libro de la Vida es, ciertamente, un documento histórico. Este libro recoge la vida de santa Teresa de Jesús, y está escrito por la propia santa. Documenta época y cultura, así como el entorno, clima social y religioso, usanzas, cultura y religiosidad de la Castilla de entonces. Todo este contenido es secundario, pues el verdadero clima del libro es interno, pertenece al mundo del alma de la autora. Teresa de Jesús escribió este libro porque le pasó una cosa fuera de serie, y "esa cosa fuera de serie" de cara a lo trascendente, en su relación con Dios, es lo que narra aquí. La última intención del relato no es "informar" al lector, sino comunicar con él en empatía profunda.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (948, '8474612454', 'Leyendas de la Alhambra', 1, '1983', 187, NULL, 'media/core/8474612454.jpg', 1, '2023-03-28 10:25:47.402000', '2023-03-28 10:25:47.402000', 496, 27, 6, 5, NULL, '', '04_04', NULL, 234, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (949, '8474612446', 'Amor y pedagogía // Nada menos que todo un hombre', 1, '1983', 181, NULL, 'media/core/8474612446.jpg', 1, '2023-03-28 10:27:45.887736', '2023-03-28 10:27:45.887736', 639, 1, 6, 5, NULL, '', '04_04', NULL, 234, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (950, '9788408182627', 'Morder la manzana. La revolución será feminista o no será', 1, '2018', 286, NULL, 'media/core/9788408182627.jpg', 1, '2023-03-28 10:30:13.375718', '2023-03-28 10:30:13.375718', 640, 2, 6, 5, NULL, '', '04_04', NULL, 7, 'Bienvenidas a nuestra revolución.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (951, '9788416306855', 'España de mierda', 1, '2015', 189, NULL, 'media/core/9788416306855.jpg', 1, '2023-03-28 10:33:03.208719', '2023-03-28 10:33:03.208719', 641, 1, 6, 5, NULL, '', '04_04', NULL, 30, 'Una novela on the road hilarante, bella, onírica y canalla por las tierras de España.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (952, '9783836562881', 'Gutav Klimt. Dibujos y pinturas', 1, '2019', 662, NULL, 'media/core/9783836562881.jpg', 1, '2023-03-28 10:38:07.954141', '2023-03-28 10:38:07.954141', 642, 18, 6, 5, 'Bibliotheca Universalis', '', '04_04', NULL, 152, 'Déjese hechizar por Gustav Klimt. Un siglo después de su muerte, el artista sigue sorprendiendo con su desvergonzado erotismo, sus deslumbrantes superficies y su experimentación artística. Maestro del arte vienés de finales del XIX y pionero del movimiento secesionista, Klimt creó un deslumbrante legado de tonos suntuosos y texturas de pan de...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (953, '9788481097313', 'Por la gracia de Dios. Catolicismo y libertades en España', 1, '2008', 184, NULL, 'media/core/9788481097313.jpeg', 1, '2023-03-28 10:42:36.992345', '2023-03-28 10:42:36.992345', 572, 2, 6, 5, NULL, '', '04_04', NULL, 46, 'Este volumen, a través de textos de gran calado de Blanco White, Modesto Lafuente, Valera, Menéndez Pelayo, Ganivet y Azaña, tiene la voluntad de ampliar la perspectiva sobre una cuestión que, desde los inicios del siglo XIX y hasta el presente, ha distorsionado la comprensión de nuestra historia y ha provocado tensiones sociales, sin lograr por el momento hallar un acuerdo que satisfaga a todos.Edición y prólogo de José María Ridao.', 'Prólogo de José María Ridao.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (954, '9788467268829', 'Aristóteles. El deseo de aprender', 1, '2017', 315, 'Aristotle. The desire to understand', 'media/core/sin-imagen_nsSKIg1.jpg', 1, '2023-03-28 10:46:41.035567', '2023-03-28 10:46:41.035567', 643, 2, 6, 5, NULL, '', '04_04', NULL, 15, 'Una de las afirmaciones fundamentales de Aristóteles consiste en que todos los seres humanos tenemos deseo de saber. Según el filósofo, a la actividad de comprender le acompaña el placer. La filosofía surge de la capacidad del hombre de sentir asombro y temor. No podemos permanecer contentos hasta que no tenemos una explicación del por qué los cielos son como son, por ejemplo. Este descontento nos arrastra a querer buscar explicaciones y, en la búsqueda de explicaciones, los hombres tropiezan con dificultades, las cuales son el punto de partida de la filosofía. Cuando nos cuestionamos cómo es el mundo que nos rodea, se pone en marcha la actividad filosófica: lo que deseamos es hacer el mundo inteligible, es decir, comprensible. Además, comprender el mundo supone también conocer el lugar que ocupamos en él, de modo que entendiendo el cosmos llegamos a comprendernos a nosotros mismos', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (955, '988467268812', 'El surco del tiempo', 1, '2017', 235, NULL, 'media/core/9788467268812.jpg', 1, '2023-03-28 10:49:31.492826', '2023-03-28 10:49:31.492826', 644, 2, 6, 5, NULL, '', '04_04', NULL, 15, 'Como Sócrates, el profesor Lledó vuelve una y otra vez a los mismos temas. Y, sin embargo, como en los coloquios socráticos, en seguida se percibe una perspectiva distinta, una aproximación nueva y una mayor exigencia de conocimiento. En las páginas de este libro, Emilio Lledó realiza, a partir del Fedro de Platón, una meditación sobre la función de la escritura, el papel de la memoria en la constitución de la persona, la configuración de la consciencia en la lectura de los grandes textos y la libertad de exprexión. Que es, claro está, una reflexión sobre los componentes de nuestra intimidad, sobre la felicidad, la amistad, el tiempo, sobre la voz escrita que nos habla desde el pasado y sobre ese yo surcado implacablemente por el tiempo, porque estamos hechos de tiempo, de memoria y de lecturas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (956, '9788467268843', 'Historia de la filosofía mediaval', 1, '2017', 266, NULL, 'media/core/sin-imagen_qV4Wq9k.jpg', 1, '2023-03-28 10:53:05.882819', '2023-03-28 10:53:05.882819', 645, 2, 6, 5, NULL, '', '04_04', NULL, 15, 'El conocimiento de la filosofía medieval ensanchará el horizonte mental del hombre moderno occidental y lo llevará a comprender sus mismas raíces culturales y espirituales. El autorizado filósofo de la ciencia Alexandre Koyré, en su libro Estudio de historia del pensamiento científico, dice claramente: «La filosofía escolástica ha sido algo muy grande. Son los escolásticos los que han llevado a cabo la educación de Europa y han creado la terminología de la que nos servimos aún; son ellos quienes con su trabajo han permitido a Occidente volver a tomar, o incluso, más exactamente, tomar contacto con la filosofía antigua. Así, a pesar de las apariencias, hay una verdadera –y profunda– continuidad entre la filosofía medieval y la filosofía moderna. Descartes y Malebranche, Spinoza y Leibniz, muy a menudo no hacen más que continuar la obra de sus predecesores medievales». El futuro de Europa, e incluso de Occidente, difícilmente se podrá realizar sin conocimiento de lo que debe al Medioevo y desligado de él. Esta Historia de la filosofía medieval se propone exponer cuidadosa y objetivamente qué han dicho los autores aquí tratados, cómo lo han dicho y por qué, subrayando la incidencia de su doctrina no solo en la filosofía de nuestro tiempo, sino también en nuestra misma cultura actual.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (957, '9788401305412', 'Las damas de oriente. Grandes viajeras por los países árabes', 1, '2005', 420, NULL, 'media/core/9788401305412.jpg', 1, '2023-03-28 10:56:37.247858', '2023-03-28 10:56:37.247858', 646, 31, 6, 5, NULL, '', '04_04', NULL, 17, 'Las apasionantes biografías de unas fascinantes mujeres que abandonaron el confort de sus mansiones por una vida nómada, y en ciudades como Bagdad, El Cairo, Damasco o Estambul aún se las recuerda.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (958, '9788467224283', 'Los hijos de Húrin', 1, '2007', 256, 'The Tale of the Children of Húrin', 'media/core/9788467224283.jpeg', 1, '2023-03-30 07:43:07.038073', '2023-03-30 07:43:07.038073', 580, 13, 6, 5, NULL, '', '04_05', NULL, 214, 'El origen de la Tierra MediaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (959, '9788435061377', 'La peste negra. Pronto, lejos y tarde', 1, '2006', 314, NULL, 'media/core/9788435061377.jpg', 1, '2023-03-30 07:46:20.102041', '2023-03-30 07:46:20.102041', 647, 16, 6, 5, 'Narrativas históricas', '', '04_05', NULL, 47, 'Ante los devastadores efectos de la peste negra, que asola Europa a mediados del siglo XIV, el papa Clemente VI convoca un concilio de médicos para tratar de acabar con la pandemia. Ahmed, un árabe cordobés, Moisés un judío catalán y el católico florentino Doménico Tornaquinci, serán los encargados de seguir una pista sobre un remedio que parece curar la peste y que está teniendo éxito en un pueblo de España. Lo que aparentemente debería ser un viaje sin problemas, se va complicando al ser víctimas de extraños ataques, dirigidos por alguien que conoce su misión muy bien. ¿Conseguirán nuestros protagonistas dar con el remedio?¿Quién quiere hacer fracasar la expedición y que la peste negra siga desolando Europa?. El autor, además de desarrollar un trama de aventuras en un entorno que nos retrata fielmente la situación Europea, aprovecha el viaje para establecer una serie de debates entre nuestros tres protagonistas, dándonos una visión muy interesantes de las relaciones, coincidencias y diferencias entre las tres culturas: árabe, judía y cristina.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (960, '9788467228502', 'El enigma de París', 1, '2007', 296, NULL, 'media/core/9788467228502.jpg', 1, '2023-03-30 07:49:13.786154', '2023-03-30 07:49:13.786154', 648, 1, 6, 5, NULL, '', '04_05', NULL, 15, 'Un rompecabezas mortalINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (961, '8422629216', 'El reino de los réprobos', 1, '1989', 519, 'The Kingdom of the Wicked', 'media/core/8422629216.jpg', 1, '2023-03-30 07:53:40.493037', '2023-03-30 07:53:40.493037', 649, 1, 2, 5, NULL, '', '04_05', NULL, 93, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (962, '9788422696889', 'La caverna de las ideas', 1, '2000', 380, NULL, 'media/core/9788422696889.jpeg', 1, '2023-03-30 07:56:48.445373', '2023-03-30 07:56:48.445373', 650, 1, 6, 5, NULL, '', '04_05', NULL, 5, 'Cuerpos mutilados de efebos sondescubiertos en las calles de Atenas,crímenes inexplicables que no parecenseguir ningún orden lógico. HeraclesPóntor, el Descifrador de Enigmas, seencargará de resolverlos con ayuda de unode los filósofos de la célebre Academiaplatónica, Diágoras de Medonte. Pero elpropio texto de La caverna de las ideas, queel lector tiene ahora en sus manos, tambiénesconde secretos: sus traductoresdesaparecen o mueren, y el actual seenfrenta a un enigma milenario quedesborda su capacidad de juicio y en el quese imbricará tanto la novela como lapercepción de cada lector.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (963, '9788422653967', 'El ojo del faraón', 1, '1993', 370, 'L''occhio del faraone', 'media/core/9788422653967.GIF', 1, '2023-03-30 08:01:01.933805', '2023-03-30 08:01:01.933805', 651, 16, 6, 5, NULL, '', '04_05', NULL, 5, 'Los últimos años del faraón Neferkara Pepi coinciden con los últimos estertores de la VI dinastía, que marcará el fin del Imperio Antiguo. Sin embargo, sólo Ipuwer, “el hombre del corazón honesto”, entre todos los cortesanos, se atreve a revelar al faraón la verdad acerca de la caótica y subversiva situación en que se encuentra el pueblo sobre el que Neferkara Pepi ha gobernado durante casi un siglo. Con ello da pie a la rememoración de un torbellino de imágenes: jardines exóticos, eclipses lunares, gatos mágicos, pigmeos danzantes y fiestas populares que van trazando la historia del reinado de este faraón. Basándose en los hechos recogidos en el famoso “Papiro de la revolución” y en otros numerosos documentos históricos y arqueológicos, Boris de Rachewiltz y Valentí Gómez i Oliver recrean con intensidad y colorido una etapa crucial de la civilización egipcia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (964, '9788481094770', 'Una mujer, una casa, una novela', 1, '2004', 173, 'Eine Frau, eine Wohnung, ein Roman', 'media/core/9788481094770.jpg', 1, '2023-03-30 08:04:47.556693', '2023-03-30 08:04:47.556693', 652, 1, 6, 5, NULL, '', '04_05', NULL, 46, 'Un joven de diecisiete años se dispone a acceder al universo de los adultos de la mano de una madre empeñada en que el muchacho comience a trabajar. Pero el joven tiene sus propios proyectos, y por ello lleva una doble vida: durante el día trabaja como aprendiz de comerciante y en las noches redacta crónicas periodísticas para diarios locales. Su gran sueño es conquistar a una mujer, vivir en su propia casa y escribir una novela. Una novela que se escribe al fin casi imperceptiblemente, a través de detalles y digresiones en apariencia fútiles, y no sin una buena dosis de ironía, perplejidad, contradicciones, dolor y sueños, ingredientes básicos de un mundo en construcción.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (965, '9788422653943', 'El diccionario de Lemprière', 1, '1994', 672, 'Lemprière''s Dictionary', 'media/core/9788422653943.jpg', 1, '2023-03-30 08:09:11.265534', '2023-03-30 08:09:11.265534', 653, 1, 6, 5, NULL, '', '04_05', NULL, 216, 'John Lemprière, un erudito joven de Jersey, acude a Londres en 1788, tras la muerte de su padre, para reclamar su herencia. Obsesionado por la manera en que los mitos clásicos parecen irrumpir en su vida (su padre, como Acteón, ha muerto destrozado por los perros que guardaban a la virginal hija del noble del lugar mientras se bañaba desnuda; una prostituta ha sido asesinada con una lluvia de oro fundido, en una clara referencia a la seducción de Dánae por Zeus), consulta a dos sabios doctores que le aconsejan que escriba un diccionario clásico. Pero la vida del joven John en Londres no será sólo la de un estudioso dedicado a la investigación y la escritura de su obra. Sometido a la implacable persecución de los poderosos miembros de la Cábala, un grupo de descendientes de hugonotes, el joven se verá obligado para salvar su vida a desentrañar los misterios de la relación o más bien violento contencioso: todos los hombres de la familia Lemprière han muerto asesinados que une a su familia con el grupo secreto y con la todopoderosa Compañía de las Indias Orientales. Vínculos que nos harán retroceder en el tiempo y viajar por el mundo, pues se remontan al sitio de La Rochelle, en 1627, escenario de una de las más sangrientas matanzas que registra la historia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (966, '9788484609537', 'Prométeme que serás libre', 2, '2011', 765, NULL, 'media/core/9788484609537.jpg', 1, '2023-03-30 08:13:58.892450', '2023-03-30 08:13:58.892450', 654, 16, 6, 5, 'TH novela', '', '04_05', NULL, 7, 'UNA TRAGEDIA Y UNA PROMESA FORJARÁN SU DESTINOINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (967, '9788467215076', 'El león, la bruja y el armario', 1, '2005', 236, 'Tye lion, the witch and the wardrobe', 'media/core/9788467215076.jpg', 1, '2023-03-30 08:18:09.382463', '2023-03-30 08:19:23.015705', 655, 13, 6, 5, NULL, '', '04_05', 'Crónicas de Narnia', 15, 'Cuatro niños que viven en una casa solitaria descubren un armario que da acceso a Narnia, un país congelado en un invierno eterno y sin Navidad. Cumpliendo con las viejas profecías, los niños–junto con el león Aslan- liberarán al país de la tiranía de la Bruja Blanca.Las Crónicas de Narnia es un clásico de la literatura infantil.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (968, '9788467215083', 'El sobrino del mago', 1, '2005', 254, 'the Magician''s Nephew', 'media/core/9788467215083.jpg', 1, '2023-03-30 08:21:52.359390', '2023-04-01 07:54:55.373264', 655, 13, 6, 5, NULL, '', '04_05', 'Crónicas de Narnia 1', 15, 'Un clásico de la literatura infantil con el que descubrir un nuevo mundo lleno de seres mitológicos, animales parlantes y brujas malvadas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (969, '9788467215137', 'La última batalla', 1, '2005', 1, NULL, 'media/core/9788467215137.jpg', 1, '2023-03-30 08:23:54.697817', '2023-03-30 08:23:54.697817', 655, 13, 6, 5, NULL, '', '04_05', 'Crónicas de Narnia 7', 15, 'Durante los últimos días de Narnia, el lugar se enfrenta a su desafío más cruel; no se trata de un invasor de fuera sino de un enemigo interno. Mentiras y traición han echado raíces, y únicamente el rey y un grupo reducido de seguidores leales puede impedir la destrucción de todo lo que más quiern en este magnífico colofón de Las Crónicas de Narnia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (970, '9788467215106', 'El principe Caspian', 1, '2005', 1, NULL, 'media/core/9788467215106.jpeg', 1, '2023-03-30 08:25:36.289698', '2023-03-30 08:25:36.289698', 655, 13, 6, 5, NULL, '', '04_05', 'Crónicas de Narnia 4', 15, 'Narnia, la tierra donde todo puede sucederINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (971, '9788467215090', 'El caballo y el muchaho', 1, '2005', 1, NULL, 'media/core/9788467215090.jpg', 1, '2023-03-30 08:27:19.549015', '2023-03-30 08:27:19.549015', 655, 13, 6, 5, NULL, '', '04_05', NULL, 15, 'En un viaje desesperado dos fugitivos se encuentran y, con la ayuda de Aslan, aúnan sus fuerzas no sólo para huir sino también para evitar la conspiración que se cierne sobre el rey Archenland. Pero una batalla terrible decidirá su destino y también el de Narnia. Tercera aventura deLas crónicas de Narnia, un clásico de la literatura juvenil, que ha creado escuela en el género fantástico.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (972, '9788408059295', 'La travesía del Viajero del albar', 1, '2006', 312, 'The Voyage of the Dawn Treader', 'media/core/9788408059295.jpeg', 1, '2023-03-30 17:16:28.223737', '2023-03-30 17:16:28.223737', 655, 13, 6, 5, NULL, '', '04_05', 'Crónicas de Narnia 5', 7, 'Un viaje al auténtico fin del mundo, donde múltiples profecías se verán cumplidas...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (973, '9788467215113', 'La travesía del Viajero del albar', 1, '2005', 1, NULL, 'media/core/9788467215113.jpeg', 1, '2023-03-30 17:18:27.848979', '2023-03-30 17:18:27.848979', 655, 13, 6, 5, NULL, '', '04_05', 'Crónicas de Narnia 5', 15, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (974, '9788467215120', 'La silla de plata', 1, '2005', 1, NULL, 'media/core/9788467215120.jpeg', 1, '2023-03-30 17:20:29.756058', '2023-03-30 17:20:29.756058', 655, 13, 6, 5, NULL, '', '04_05', 'Crónicas de Narnia 6', 15, 'A través de peligros inauditos y cavernas profundas, marcha un noble grupo de amigos al rescate de un príncipe cautivo. Sin embargo, su misión en la Tierra Inferior los lleva a enfrentarse cara a cara con una maldad más hermosa y letal de lo que habrían esperado encontrar jamás.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (975, '9788425340161', 'El mercader de juncos', 1, '2006', 357, 'La princesse des jonques', 'media/core/9788425340161.jpg', 1, '2023-03-30 17:24:08.101182', '2023-03-30 17:24:08.101182', 656, 16, 6, 5, 'Novela Histórica', '', '04_05', NULL, 45, 'Thriller histórico con una trama de suspense excelentemente urdida en torno a dos familias de comerciantes rivales, en la China de la dinastía Ming. Cheng Liang posee la flota de juncos más poderosa del Mar de China. Pretende casar a su hijo con la bella Shennong, hija de su adbersario comercial. El crimen del tesorero de Cheng y el posterior secuestro de Shennong indican que alguien está dispuesto a todo con tal de impedir el matrimonio, alguien que firma con una o ensangrentada.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (976, '8435005089', 'Los hechos del Rey Arturo y sus nobles caballeros', 1, '1986', 337, 'The Acts of King Arthur abd his Noble Knights', 'media/core/8435005089.jpg', 1, '2023-03-30 17:28:13.170879', '2023-03-30 17:28:13.170879', 657, 1, 6, 5, 'Narrativas', '', '04_05', NULL, 47, 'Steinbeck resucita bellamente el cautivante mundo del rey Arturo y sus nobles caballeros de la Tabla Redonda -que incluye al mago Merlín y a los amores entre la bella Ginebra y Lanzarote del Lago- con todo su irrepetible esplendor medieval.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (977, '9788477228257', 'La estatua de piedra', 1, '1993', 140, 'The sleep of Stone', 'media/core/9788477228257.jpg', 1, '2023-03-30 17:33:34.081736', '2023-03-30 17:33:34.081736', 658, 13, 6, 5, NULL, '', '04_05', 'El vuelo del dragón', 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (978, '9788422663973', 'Los fuegos del Edén', 1, '1996', 447, 'Fires of Eden', 'media/core/9788422663973.jpg', 1, '2023-03-30 17:36:28.199624', '2023-03-30 17:36:28.199624', 659, 1, 6, 5, NULL, '', '04_05', NULL, 107, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (979, '9788422695387', 'Apocalipsis', 1, '2002', 477, NULL, 'media/core/9788422695387.jpeg', 1, '2023-03-30 17:40:10.298037', '2023-03-30 17:40:10.298037', 660, 1, 6, 5, NULL, '', '04_05', NULL, 5, 'Roberto viaja a Madrid y por azar descubre los misterios que esconden los viejos túneles del metro. Desde la Consejería de Cultura una atractiva funcionaria busca el cadaver de Velázquez siguiendo las instrucciones que un comando neonazi le envía por fax. Ambos acabarán en el mismo agujero.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (980, '9788483654804', 'El cumpleaños secreto', 1, '2013', 547, 'The Secret Keeper', 'media/core/9788483654804.jpg', 1, '2023-03-30 17:45:08.825816', '2023-03-30 17:45:08.836331', 661, 1, 6, 5, 'Suma de letras', '', '04_05', NULL, 235, '1959INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (981, '9788467266856', 'Un cuento oscuro', 1, '2016', 683, 'Unprooted', 'media/core/9788467266856.jpeg', 1, '2023-03-30 17:48:10.355955', '2023-03-30 17:48:10.355955', 662, 14, 6, 5, NULL, '', '04_05', NULL, 15, '«Tiene todo lo que me gusta: una gran heroína, mitos y leyendas, y giros sorprendentes.» Cassandra ClareINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (982, '9788422683780', 'El señor del caos', 1, '2000', 601, 'The Overseer', 'media/core/9788422683780.jpeg', 1, '2023-03-30 17:51:57.738596', '2023-04-01 07:55:18.715879', 663, 16, 6, 5, NULL, '', '04_05', NULL, 107, 'La Rueda del Tiempo de Robert Jordan es la saga de fantasía más importante de los últimos años.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (983, 'B25744', 'El misterio de las catedrales', 2, '1968', 251, 'Le mystere des cathedrales', 'media/core/B25744.jpg', 1, '2023-03-30 17:56:36.133581', '2023-03-30 17:56:36.133581', 664, 36, 6, 5, 'Otros mundos', '', '04_05', NULL, 17, 'Este libro constituye un sorprendente y revelador estudio sobre las obras maestras del arte g#tico, as# como un compendio de la sabidur#a herm#tica. Obra poblada de s#mbolos y referencias a los m#s diversos aspectos del conocimiento, El misterio de las catedrales es uno de los libros m#s fecundos y enigm#ticos de toda la historia. El legado de Fulcanelli invita a la interpretaci#n y a lo largo de los a#os ha promovido una saludable pol#mica intelectual.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (984, '9788467268720', 'Un abogado rebelde', 1, '2016', 492, 'rogue Lawyer', 'media/core/9788467268720.jpg', 1, '2023-03-30 17:59:25.316525', '2023-03-30 17:59:25.316525', 124, 14, 6, 5, NULL, '', '04_05', NULL, 211, 'Sebastian Rudd no es el típico abogado: lleva arma y su oficina es una camioneta a prueba de balas conducida por su guardaespaldas, que a su vez es su asistente legal y único amigo. Defiende a quienes otros no querrían ni ver: un drogadicto, un chico tatuado que supuestamente forma parte de un culto satánico acusado de acosar y matar a dos niñas pequeñas, un criminal en el corredor de la muerte, un hombre arrestado por disparar a unos geo al entrar por error en su casa... ¿Por qué estos clientes?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (985, '8422641801', 'La lógica del vampiro', 1, '1990', 136, NULL, 'media/core/8422641801.jpeg', 1, '2023-03-30 18:02:24.830063', '2023-03-30 18:02:24.830063', 665, 1, 6, 5, NULL, '', '04_05', NULL, 216, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (986, '8422624982', 'Réquiem por los que van a morir', 1, '1988', 211, 'A Prayer for the Dying', 'media/core/8422624982.jpg', 1, '2023-03-30 18:07:07.880254', '2023-03-30 18:07:07.880254', 666, 1, 6, 5, NULL, '', '04_05', NULL, 236, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (987, '8422636220', 'Bajo el cielo de Novgorod', 1, '1991', 410, 'Sous le ciel de Novgorod', 'media/core/8422636220.jpeg', 1, '2023-03-30 18:09:59.749163', '2023-03-30 18:09:59.749163', 667, 16, 6, 5, NULL, '', '04_05', NULL, 72, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (988, '9788422686736', 'El laboraatorio de los alquimistas', 1, '2000', 476, 'Das Labor des Alchemisten', 'media/core/9788422686736.jpeg', 1, '2023-03-31 06:07:45.756582', '2023-03-31 06:07:45.756582', 668, 1, 6, 5, NULL, '', '04_05', NULL, 74, 'Durante la inaguración de la catedral, Münich se llena de comediantes y titiriteros que seducen al público con todo tipo de espectáculos. Pero la aparición de un cadáver decapitado llena la ciudad de revelaciones espantosas y rumores terribles. Un fascinante relato que combina hábilmente el humor más irónico con el suspense más impactante.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (989, '9788467230451', 'Invierno en Madrid', 1, '2007', 665, 'Winter in Madrid', 'media/core/9788467230451.jpeg', 1, '2023-03-31 06:11:02.329298', '2023-03-31 06:11:02.329298', 669, 1, 6, 5, NULL, '', '04_05', NULL, 107, 'Año 1940. Imparables, los alemanes invaden Europa. Madrid pasa hambre y se ha convertido en un hervidero de espías de todas las potencias mundiales. Harry Brett es un antiguo soldado que conoció la Guerra Civil y quedó traumatizado tras la evacuación de Dunkerque. Ahora trabaja para el servicio secreto británico: debe ganarse la confianza de su antiguo condiscípulo Sandy Forsyth, quien se dedica a negocios turbios en la España del Caudillo. Por el camino, Harry se verá envuelto en un juego muy peligroso y asaltado por amargos recuerdos. Mientras tanto, la novia de Sandy, una antigua enfermera de la Cruz Roja llamada Barbara Clare, tiene su propia misión secreta: encontrar a su antiguo amante, Bernie Piper, un voluntario comunista de las Brigadas Internacionales que desapareció tras la batalla del Jarama. Inolvidable, irresistible e imprescindible, Invierno en Madrid es una novela de amor y espionaje que trata sobre la dificultad de elegir en un mundo marcado por la guerra. "Invierno en Madrid tiene el potencial suficiente, desde el punto de vista literario, para convertirse en un fenómeno como La sombra del viento o Soldados de Salamina." Enric Castelló, La Vanguardia "Una novela con calidad literaria que, literalmente, uno no puede dejar de leer: llena de giros inesperados,', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (990, '9788467274592', '14 de julio', 1, '2019', 185, '14 juillet', 'media/core/9788467274592.jpg', 1, '2023-03-31 06:14:07.299296', '2023-03-31 06:14:07.299296', 670, 1, 6, 5, NULL, '', '04_05', NULL, 114, 'El autor de El orden del día (Premio Goncourt 2017) narra, en un relato subyugante, los episodios desconocidos del estallido de la Revolución francesa.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (991, '8422643049', 'Parque Jurásico', 1, '1992', 501, 'Jurassic Park', 'media/core/8422643049.jpg', 1, '2023-03-31 06:17:28.440491', '2023-03-31 06:17:28.440491', 130, 13, 2, 5, NULL, '', '04_05', NULL, 96, 'En una isla remota, un grupo de hombres y mujeres emprende una carrera contra el tiempo para evitar un desastre mundial provocado por la desmedida ambición de comercializar la ingeniería genetica. Pero todos los esfuerzos resultarán vanos cuando el inescrupuloso proyecto quede fuera de control y el mundo a merced de unas bestias monstruosas...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (992, '9788467258417', 'Rónin', 1, '2013', 857, NULL, 'media/core/9788467258417.jpeg', 1, '2023-03-31 06:20:54.500581', '2023-03-31 06:20:54.500581', 122, 1, 6, 5, NULL, '', '04_05', NULL, 15, 'Ronin, de Francisco Narla, autor de otras obras como Assur o Caja negra, es una novela cargada de aventuras de la narrativa española, que rescata un hecho histórico inédito, la presencia de una delegación de samuráis en nuestro país. Ronin está basado en un hecho real: un emperador japonés quiso establecer lazos comerciales con la gran potencia mundial que en el siglo XVII era España y mandó una embajada de samuráis a nuestro país. Una novela de apasionantes aventuras en escenarios exóticos: Filipinas en la época colonial, Acapulco, Veracruz, Madrid, Sevilla y por supuesto, Japón. La narración de un momento histórico glorioso: el imperio español en el que no se ponía el sol. Esta novela histórica de aventuras gustará además a los amantes de la cultura japonesa y la literatura fantástica.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (993, '9788467255362', 'Victus', 1, '2012', 591, NULL, 'media/core/9788467255362.jpeg', 1, '2023-03-31 06:24:12.680744', '2023-03-31 06:24:12.680744', 672, 16, 6, 5, NULL, '', '04_05', NULL, 237, 'Victus es una novela histórica que nos narra la guerra de Sucesión española, un conflicto que puede considerarse como la primera de las contiendas mundiales y que termina el 11 de septiembre de 1714 con el apocalíptico asalto a Barcelona. También es la tragedia de Martí Zuviría, un joven barcelonés, alumno aventajado del marqués de Vauban, que se convierte en un genio de la ingeniería militar.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (994, '9788467249668', 'En la corte del Lobo', 1, '2011', 725, 'Wolf Hall', 'media/core/9788467249668.jpeg', 1, '2023-03-31 06:27:35.159249', '2023-03-31 06:27:35.159249', 673, 16, 6, 5, NULL, '', '04_05', NULL, 58, 'Inglaterra, en 1520, está a un paso del desastre. El rey Enrique VIII no consigue engendrar un heredero varón y quiere divorciarse de su mujer, Catalina de Aragón, para casarse con Ana Bolena, pero el cardenal Wolsey, su principal asesor, no obtiene más que negativas del papa. En este clima de desconfi anza y necesidad llega a la corte Thomas Cromwell, al principio como segundo de Wolsey y más tarde como su sucesor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (995, '9788416237142', 'Una primavera de perros', 1, '2016', 282, 'Non è stagione', 'media/core/9788416237142.jpg', 1, '2023-03-31 06:32:38.951098', '2023-03-31 06:32:38.951098', 674, 14, 6, 5, 'Black Salamandra', '', '04_05', 'SERIE ROCCO SCHIAVONE 3', 29, 'Con cada nuevo episodio, este subjefe de policía romano de pura cepa -desterrado a una pequeña ciudad al pie de los Alpes por ciertos comportamientos de dudosa licitud- ha ido adquiriendo una dimensión más incisiva y profunda, para deleite de sus cientos de miles de seguidores.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (996, '9788401337321', 'Después del anochecer', 1, '2009', 440, 'Just After Sunset', 'media/core/9788401337321.jpg', 1, '2023-03-31 06:35:38.320095', '2023-03-31 06:35:38.320095', 8, 12, 6, 5, NULL, '', '04_05', NULL, 17, 'Una colección de trece relatos impactantes y escalofriantes. En su primer libro de cuentos desde Todo es eventual (Plaza & Janés, 2006), Stephen King nos lleva por mundos fascinantes y terribles donde todo puede ocurrir. Misterios sin resolver, asesinatos y venganzas, accidentes y muertos que creen estar vivos, horribles experimentos farmacéuticos, una mujer que no para de correr para olvidar, una niña que cura enfermedades terminales... Con excepción de «El gato del infierno», escrita en los años setenta, King escribió estos relatos después de su famoso roce con la muerte, y la crítica los ha calificado como los mejores.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (997, '9788427045231', 'La fragilidad del crisantemo', 1, '2019', 1, NULL, 'media/core/9788427045231.jpg', 1, '2023-03-31 06:38:18.537338', '2023-03-31 06:38:18.537338', 675, 1, 6, 5, NULL, '', '04_05', NULL, 41, 'Una fascinante novela situada en el esplendoroso y legendario Japón clásico del siglo IX.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (998, '9788422659464', 'La ley del amor', 1, '1995', 277, NULL, 'media/core/9788422659464.jpeg', 1, '2023-03-31 06:41:55.558552', '2023-03-31 06:41:55.558552', 676, 1, 6, 5, NULL, '', '04_05', NULL, 96, 'La pasión amorosa es etendida aquí como una fuerza arroladora que, por encima de todos los obstáculos, acabará imponiéndose si somos capaces de aceptar su ley, la ley del amor.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (999, '8422643081', 'Los vampiros de la mente', 1, '1992', 989, 'Carrion Comfort', 'media/core/8422643081.jpeg', 1, '2023-03-31 06:45:45.607897', '2023-03-31 06:45:45.607897', 659, 1, 6, 5, NULL, '', '04_05', NULL, 107, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1000, '9788467265569', 'El castillo', 1, '2015', 671, NULL, 'media/core/9788467265569.jpeg', 1, '2023-04-01 06:46:44.146157', '2023-04-01 06:46:44.146157', 111, 16, 6, 5, NULL, '', '04_05', 'Trilogía mediaval I', 73, 'Entre la Tierra Llana y el Pirineo aragonés se encuentra el monumento militar románico más importante de Europa: el castillo-abadía de Loarre, una fortaleza impresionante, construida cuando esa zona era una peligrosa tierra de frontera. ¿Cómo se edificó? ¿Quién logró tal hazaña?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1001, '9788467256833', 'Circo Máximo. La ira de Trajano', 1, '2013', 1117, NULL, 'media/core/9788467256833.jpg', 1, '2023-04-01 06:50:59.712698', '2023-04-01 06:50:59.712698', 156, 16, 6, 5, NULL, '', '04_05', 'Trilogía de Trajano II', 15, 'Circo Máximo es la historia de Trajano y su gobierno, guerras y traiciones, lealtades insobornables e historias de amor imposibles. Hay una vestal, un juicio, inocentes acusados, un abogado especial, mensajes cifrados, códigos secretos, batallas campales, fortalezas inexpugnables, asedios sin fin, dos aurigas rivales, el Anfiteatro, los gladiadores y tres carreras de cuadrigas. Hay también un caballo especial, diferente a todos, leyes antiguas olvidadas, sacrificios humanos, amargura y terror, pero también destellos de nobleza y esperanza, como la llama de Vesta, que mientras arde preserva a Roma. Sólo que hay noches en las que la llama del Templo de Vesta tiembla. La rueda de la Fortuna comienza entonces a girar. En esos momentos, todo puede pasar y hasta la vida del propio Trajano, aunque él no lo sepa, corre peligro. Y, esto es lo mejor de todo, ocurrió: hubo un complot para asesinar a Marco Ulpio Trajano.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1002, '9788448038243', 'Sólo tú puedes salvar a la Humanidad. Una aventura de Johnny Maxwell', 1, '2009', 207, 'Only You Can Save Mankind', 'media/core/9788448038243.jpg', 1, '2023-04-01 06:54:06.374166', '2023-04-01 06:54:06.374166', 109, 1, 6, 5, NULL, '', '04_05', NULL, 9, 'Nueva publicación de las aventuras de Johnny Maxwell. Edición revisada por el autor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1003, '9788408008033', 'La conjura de Cortés', 1, '2012', 374, NULL, 'media/core/9788408008033.jpg', 1, '2023-04-01 06:57:36.346540', '2023-04-01 06:57:36.346540', 181, 1, 6, 5, 'Autores Españoles e Iberoamericanos', '', '04_05', 'Trilogía de Martín Ojo de plata 3', 7, 'La conjura de Cortés culmina el recorrido de Matilde Asensi por el Siglo de Oro español, visto esta vez desde la Nueva España. Una manera de contemplar la historia que le ha hecho acreedora del reconocimiento de los lectores y la crítica, y que, cómo no, está plagada de intrigas, corrupción, aventuras e imaginación.En esta novela, Catalina se ve obligada a desenmascarar una gran conjura ideada por sus enemigos para derrocar al rey de España. La aparición de un mapa que desvela dónde encontrar el legendario tesoro de Hernán Cortés desempeñará un papel clave en el plan de Catalina para descubrir a los traidores y cumplir su palabra de acabar con los Curvo.La doble personalidad deCatalina Solís/Martín Nevares se enfrentará además a un grave peligro para su equilibrio: el amor. Una vez más, Matilde Asensi sorprenderá a sus lectores con un final inesperado.Un broche de oro para la trilogía de Martín Ojo de Plata que siguen millones de lectores.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1004, '9788475883496', 'Plans de futur', 1, '2013', 254, NULL, 'media/core/9788475883496.jpg', 1, '2023-04-01 07:01:23.470745', '2023-04-01 07:01:23.470745', 678, 1, 6, 5, NULL, '', '04_05', NULL, 238, 'L''esperança, l''esperit de superació i la solidaritat familiar són els eixos d?aquesta obraINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1005, '9788467246124', 'La confesión', 1, '2011', 475, 'The Confession', 'media/core/9788467246124.GIF', 1, '2023-04-01 07:05:02.042129', '2023-04-01 07:05:02.042129', 124, 1, 6, 5, NULL, '', '04_05', NULL, 211, 'Travis Boyette es un asesino. En 1998, en una pequeña ciudad de Texas, raptó, violó y estranguló a una de las chicas más guapas y más populares del instituto. Enterró el cadáver en un lugar donde nadie lo encontraría nunca y luego esperó. Observó impasible mientras la policía detenía a Donte Drumm, la estrella del equipo de fútbol que nada había tenido que ver con el crimen. Donte fue acusado, declarado culpable y condenado a muerte.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1006, '9788499981789', 'Misión olvido', 1, '2012', 511, NULL, 'media/core/9788499981789.jpg', 1, '2023-04-01 07:07:43.701725', '2023-04-01 07:07:43.701725', 204, 1, 6, 5, 'TH novela', '', '04_05', NULL, 7, 'Incapaz de recomponer sus propios pedazos, la profesora Blanca Perea acepta a la desesperada lo que anticipa como un tedioso proyecto académico. Su estabilidad personal acaba de desplomarse, su matrimonio ha saltado por los aires. Confusa y devastada, la huida a la insignificante universidad californiana de Santa Cecilia es su única opción.El campus que la acoge resulta, sin embargo, mucho más seductor de lo previsto, agitado en esos días por un movimiento cívico contrario a la destrucción de un paraje legendario a fin de construir en él un enorme centro comercial. Y la labor que la absorbe?la catalogación del legado de su viejo compatriota Andrés Fontana, fallecido décadas atrás?dista enormemente de ser tan insustancial como prometía.A medida que se afana en vertebrar la memoria de aquel hispanista olvidado, junto a ella va ganando cercanía Daniel Carter, un colega americano veterano y atractivo que no ocupa el sitio que debería ocupar. Entre ambos hombres, uno a través de sus testimonios póstumos y otro con su complicidad creciente, Blanca se verá arrastrada hacia un entramado de sentimientos encontrados, intrigas soterradas y puertas sin cerrar.¿Por qué nadie se preocupó nunca de rescatar lo que Andrés Fontana dejó a su muerte? ¿Por qué, después de treinta años, alguien tiene interés en que todo aquello se destape al fin? ¿Qué tiene que ver la labor inconclusa del viejo hispanista con todo lo que está ocurriendo ahora en Santa Cecilia? ¿Qué le movió a desempolvar la historia no contada de las misiones del Camino Real? Antes de encontrar respuestas, Blanca aún tiene mucho que entender. Amores cruzados, certezas a medias e intereses silenciados que acabarán por salir a la luz. Viajes de ida y vuelta entre España y Estados Unidos, entre el presente y el pasado de dos lenguas y dos mundos en permanente reencuentro. Entre el hoy y el ayer de aquellos trasterrados que, saltando fronteras y obstáculos, vivieron a caballo entre ambos empujados por la necesidad, el deber o la pasión.Desde los viejos franciscanos que a lomos de mulas fundaron las míticas misiones californianas a los hispanistas y escritores exiliados que a pesar de la nostalgia nunca lograron regresar. De los militares norteamericanos que llenaron la España agridulce de los años cincuenta de bases, dólares y cigarrillos rubios a un impetuoso estudiante dispuesto a cualquier cosa por una mujer.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1007, '9788422661375', 'El escribano del Secreto', 1, '1996', 318, NULL, 'media/core/9788422661375.jpeg', 1, '2023-04-01 07:19:57.591433', '2023-04-01 07:19:57.591433', 90, 1, 6, 5, NULL, '', '04_05', NULL, 5, 'Desde tiempos de Torquemada, que llevaba registro de todos los chascarrillos que los ocurrentes lanzaban durante los interrogatorios y los tormentos, la Santa Inquisición tuvo un libro secreto de sus procedimientos y un amanuense a quien se le otorgaba el título de Escribano del Secreto.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1008, '9788477227632', 'La revelación de un rey', 1, '1992', 460, 'King''s Test', 'media/core/9788477227632.jpg', 1, '2023-04-01 07:24:01.216788', '2023-04-01 07:24:01.216788', 539, 13, 6, 5, NULL, '', '04_05', 'La Estrella de los Guardianes 2', 9, 'https://es.wikipedia.org/wiki/La_revelaci%C3%B3n_de_un_rey', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1009, '9788477227649', 'El sacrificio del rey', 1, '1993', 524, 'King''s Sacrifice', 'media/core/9788477227649.GIF', 1, '2023-04-01 07:27:34.398010', '2023-04-01 07:27:34.398010', 539, 13, 6, 5, NULL, '', '04_05', 'La Estrella de los Guardianes 3', 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1010, '9788427014879', 'Cena en el palacio de la discordia', 1, '1991', 238, 'Dinner at Devian''s Palace', 'media/core/9788427014879.jpg', 1, '2023-04-01 07:39:56.499852', '2023-04-01 07:39:56.499852', 519, 1, 6, 5, 'GranSuperFiccion', '', '04_05', NULL, 41, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1011, '9788432212536', 'El asombroso viaje de Pomponio Flato', 1, '2008', 190, NULL, 'media/core/9788432212536.jpg', 1, '2023-04-01 07:48:12.939871', '2023-04-01 07:55:34.327900', 96, 1, 6, 5, 'Biblioteca Breve', '', '04_05', NULL, 13, 'En el siglo I de nuestra era, Pomponio Flato viaja por los confines del Imperio romano en busca de unas aguas de efectos portentosos. El azar y la precariedad de su fortuna lo llevan a Nazaret, donde va a ser ejecutado el carpintero del pueblo, convicto del brutal asesinato de un rico ciudadano. Muy a su pesar, Pomponio se ve inmerso en la solución del crimen, contratado por el más extraordinario de los clientes: el hijo del carpintero, un niño candoroso y singular, convencido de la inocencia de su padre, hombre en apariencia pacífico y taciturno, que oculta, sin embargo, un gran secreto. Cruce de novela histórica, novela policíaca, hagiografía y parodia de todas ellas, aquí se ajustan las cuentas a muchas novelas de consumo, y se construye una nueva modalidad del género más característico de Eduardo Mendoza: la trama detectivesca original e irónica, que desemboca en una sátira literaria y en una desternillante creación novelesca. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1012, '9788432225581', 'El secreto de la modelo extraviada', 1, '2015', 314, NULL, 'media/core/9788432225581.jpg', 1, '2023-04-01 07:52:01.572324', '2023-04-01 07:52:01.572324', 96, 1, 6, 5, 'Biblioteca Breve', '', '04_05', NULL, 13, 'En la nueva novela de Eduardo Mendoza, El secreto de la modelo extraviada, el detective loco que protagonizó El misterio de la cripta embrujada, El laberinto de las aceitunas y recientemente El enredo de la bolsa y la vida recuerda un caso aparentemente cerrado de los ochenta y no ceja en su empeño de resolverlo más de veinte años después. El detective más divertido de la narrativa española nos cuenta aquí su doble aventura:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1013, '9788432237126', 'Las barbas del profeta', 1, '2020', 196, NULL, 'media/core/9788432237126.jpg', 1, '2023-04-01 07:54:23.188179', '2023-04-01 07:54:23.188179', 96, 29, 6, 5, 'Biblioteca Breve', '', '04_05', NULL, 13, 'Como muchos niños de la posguerra española, Eduardo Mendoza estudió en el colegio una asignatura denominada Historia Sagrada, resumen e ilustración de algunos pasajes de la Biblia que hicieron nacer en él la fascinación por la palabra escrita y por los mundos de ficción, además de enseñarle a distinguir entre lo real y lo imaginario.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1014, 'B15982', 'Guía para el estudio de principios básicos de química de Gray / Haight', 1, '1970', 145, 'Study Guide for Gray/Haight Basic Principles of Chemistry', 'media/core/B15982.jpg', 1, '2023-04-02 08:00:41.779574', '2023-04-02 08:00:41.779574', 679, 38, 6, 5, NULL, '', '04_06', NULL, 239, '', '');
