INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1038, '9788431526269', 'El libro del jardín. Diseño, mantenimiento, calendario de labores', 1, '2004', 1, NULL, 'media/core/9788431526269.jpeg', 1, '2023-04-02 10:16:16.727514', '2023-04-02 10:16:16.727514', 698, 38, 6, 5, NULL, '', '04_06', NULL, 252, '¿Tiene las semillas de una planta poco conocida y quiere saber cómo cultivarla? Aquí hallará una tabla de casi doscientas plantas herbáceas, con datos sobre exposición, dimensiones, características, utilización ideal, época de floración e información general sobre los procedimientos de cultivo. ¿Quiere plantar árboles pero desea saber antes qué puede esperar en cuanto a frutos y flores, en cuanto a dimensiones, en cuanto a época de floración, etc.?', '');
