INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1048, '9788499350813', 'Un corto viaje a Portugal', 1, '2011', 157, NULL, 'media/core/9788499350813.jpg', 1, '2023-04-03 07:00:45.464156', '2023-04-03 07:00:45.464156', 706, 18, 6, 5, 'Anaya touring club', '', '04_06', NULL, 66, 'Guía: una guía cultural y monumental. Diez lugares, acontecimientos, característicasINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1049, '9788493508494', 'Marrakech', 1, '2008', 175, NULL, 'media/core/9788493508494.jpg', 1, '2023-04-03 07:04:26.345438', '2023-04-03 07:04:26.345438', 707, 18, 6, 5, NULL, '', '04_06', NULL, 260, 'Ecos Travel Books cuenta con dos colecciones de guías de viajes: Mundo Insólito, que invita a recorrer países y regiones del planeta y City Breaks, dedicadas a las escapadas urbanas. Son guías con un diseño actual y fácil uso. Elaboradas y contrastadas sobre el terreno por un equipo de expertos que han sabido escoger lo mejor de cada país y ciudad para ofrecerlo a los viajeros. En castellano.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1050, '8475970044', 'Gran Bretaña 1989/1990', 1, '1989', 366, NULL, 'media/core/8475970044.jpg', 1, '2023-04-03 07:10:17.445278', '2023-04-03 07:10:17.445278', 572, 18, 6, 5, 'Las guías del trotamundos', '', '04_06', NULL, 261, 'La Guide de Routard tiene casi 30 años (La primera apareció en 1973). Durante este tiempo ha formado parte del equipaje de muchos viajeros seguidores de la filosofía del creador de la Routard, Philippe Gloaguen: un trotamundos es aquel que sueña con descubrir el mundo y los seres humanos que lo habitan. Continuando con la idea primaria de ser útil, TROTAMUNDOS se ha adaptado totalmente a las necesidades y prioridades del viajero del siglo XXI.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1051, '8475970311', 'París 1986/1987', 1, '1986', 231, NULL, 'media/core/8475970311.jpg', 1, '2023-04-03 07:13:34.604207', '2023-04-03 07:13:34.604207', 572, 18, 6, 5, 'Las guías del trotamundos', '', '04_06', NULL, 261, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1052, '9788480230506', 'Castilla y León. León, Zamora y Salamanca', 1, '1994', 279, NULL, 'media/core/9788480230506.jpg', 1, '2023-04-03 07:18:36.395169', '2023-04-03 07:18:36.395169', 572, 18, 6, 5, 'Las guías del trotamundos', '', '04_06', 'Vol 1', 262, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1053, '8475970524', 'Marruecos 1989/1990', 1, '1989', 189, NULL, 'media/core/8475970524.jpg', 1, '2023-04-03 07:22:23.153282', '2023-04-03 07:22:23.153282', 572, 18, 6, 5, 'Las guías del trotamundos', '', '04_06', NULL, 104, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1054, '8475970044-1', 'Gran Bretaña - Irlanda 1985/1986', 1, '1985', 211, NULL, 'media/core/8475970044-1.jpg', 1, '2023-04-03 07:25:41.142754', '2023-04-03 07:25:41.142754', 572, 18, 6, 5, 'Las guías del trotamundos', '', '04_06', NULL, 104, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1055, '8475970532', 'Irlanda 1989/1990', 1, '1989', 194, NULL, 'media/core/8475970532.jpg', 1, '2023-04-03 07:31:17.805508', '2023-04-03 07:31:17.805508', 572, 18, 6, 5, 'Las guías del trotamundos', '', '04_06', NULL, 104, 'Guía de viajes sobre Irlanda con toda la información necesaria para el viajero tanto antes de partir como en su estancia allí. Contiene un capítulo de generalidades con datos sobre alojamiento, clima, cultura, gastronomía, folklore, geografía, historia, idioma... Además de información sobre cómo ir: agencias de viajes y medios de transporte. El libro nos invita a visitar libremente ciudades y lugares de interés como: Wexford o Comeragh Mountains en la costa sur; la península de Dingle al Shannon; las islas de Aran; la calzada de los gigantes en el Ulster o Dublin. Con un recorrido por la historia y la sociedad actual, lugares de interés con excursiones y rutas aconsejables, las mejores direcciones para comer y alojarse en función de cada presupuesto o los mejores locales para tomar una copa, escuchar música y bailar.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1056, '9788499350264', 'París', 1, '2010', 525, NULL, 'media/core/9788499350264.jpg', 1, '2023-04-03 07:49:39.978467', '2023-04-03 07:49:39.978467', 572, 18, 6, 5, 'Guías TresD', '', '04_06', NULL, 263, 'ANTES de salir de viaje Las claves para comprender la realidad que París despliega ante nuestros ojos: la impronta de más de 2.000 años de historia, sus acontecimientos más destacados; el urbanismo y los estilos arquitectónicos desde Notre-Dame a las últimas vanguardias; el carácter del Barrio Latino o de Montparnasse; el arte de sus museos, únicos en el mundo; la gastronomía y los vinos... París visto por los pintores y los escritores... Más de mil imágenes que avivarán el deseo de conocer sus ambientes, los paisajes, las obras de arte... DURANTE el viaje La manera más inteligente de descubrir París: 19 itinerarios por sus lugares más emblemáticos y toda la información práctica (restaurantes, alojamientos, compras...) que se precisa para disfrutarlo al máximo. DESPUES del viaje Un libro bellísimo, auténtica obra de referencia sobre París en su biblioteca.', 'Adjunta Guia Express con más de 300 direcciones');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1057, '9788499350240', 'Nueva York', 1, '2010', 417, NULL, 'media/core/9788499350240.jpg', 1, '2023-04-03 07:54:38.287919', '2023-04-03 07:54:38.287919', 572, 18, 6, 5, 'Guías TresD', '', '04_06', NULL, 263, 'Una mirada nueva con la guía más práctica. ANTES de salir de viaje Las claves para comprender la metrópoli multicultural más abigarrada del mundo: su Historia, desde los primeros colonos a la reconstrucción del World Trade Center; sus Costumbres y Forma de vida exportadas al resto del mundo; su Arquitectura única: cómo se construyeron sus imponentes rascacielos; el Arte que atesoran sus museos: el MomA, el Metropolitan, el Guggenheim; Nueva York visto por los Pintores y los Escritores... Las imágenes que avivarán el deseo de conocer sus ambientes, los paisajes, las obras de arte... DURANTE el viaje La manera más inteligente de descubrir Nueva York: 9 itinerarios por sus lugares más emblemáticos y toda la información práctica (restaurantes, alojamientos, compras, espectáculos...) que se precisa para disfrutarlo al máximo. DESPUES del viaje Un libro bellísimo, auténtica obra de referencia sobre Nueva York en su biblioteca.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1058, '9788403512429', 'Grecia. Atenas y la península', 9, '2014', 327, 'Eyewitness Travel Guide, Greece (Athens & the Mainland)', 'media/core/9788403512429.jpg', 1, '2023-04-03 07:58:00.878845', '2023-04-03 08:02:41.083609', 572, 18, 6, 5, 'DK Guías Visuales', '', '04_06', NULL, 264, 'Grecia, que por su situación geográfica combina elementos de los Balcanes, Oriente Medio y el Mediterráneo, y que tiene más de 2.000 islas diseminadas desde el mar Egeo hasta el Jónico, es uno de los países europeos más visitados, pero también uno de los menos conocidos. Tras una aproximación a la historia del país, la guía ofrece un recorrido por los mejores itinerarios de Atenas y el resto de la península, todo ello aderezado con ilustraciones, más de 750 fotografías a todo color, maquetas y planos. Sin olvidarse, por supuesto, de toda la información indispensable para el viajero, como es la relación de hoteles y restaurantes, la mejor época para viajar, dónde realizar las mejores compras, actividades culturales, etc.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1059, '9788403510432', 'Londres', 1, '2016', 379, 'Travel Guide, London', 'media/core/9788403510432.jpg', 1, '2023-04-03 08:01:08.741459', '2023-04-03 08:01:08.741459', 569, 18, 6, 5, 'DK Guías Visuales', '', '04_06', NULL, 264, 'Totalmente actualizada, incluye exclusivos planos alzados y vistas tridimensionales de los barrios más importantes que conviene explorar a pie.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1060, '9788467029017', 'Nueva York', 1, '2010', 363, NULL, 'media/core/9788467029017.jpg', 1, '2023-04-03 08:05:53.871521', '2023-04-03 08:05:53.871521', 572, 18, 6, 5, 'Guías Clave', '', '04_06', NULL, 265, 'Una colección de guías que se convertirán en tu mejor compañero de viaje . Las guías clave ofrecen toda la información necesaria para conocer a fondo los destinos turísticos más solicitados y sacar el máximo partido al viaje.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1061, '9788467032185', 'Florencia y Toscana', 1, '2010', 298, NULL, 'media/core/9788467032185.jpg', 1, '2023-04-03 08:08:34.436604', '2023-04-03 08:08:34.436604', 572, 18, 2, 5, 'Guías Clave', '', '04_06', NULL, 265, 'Con información detallada que facilita la elección de los mejores hoteles y restaurantes, los lugares que de verdad hay que ver, una práctica guía de tiendas, reseñas de web interesantes sobre los sitios, horarios de transportes, consejos e, incluso, una guía de conversación, la Guía Clave de Florencia y Toscana se convertirá en tu mejor compañero de viaje.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1062, '9788375462661', 'Tuscany. Florence · Siena · Pisa Express Map', 1, '2012', 1, NULL, 'media/core/9788375462661.jpg', 1, '2023-04-03 08:14:17.987541', '2023-04-03 08:15:18.416610', 572, 42, 6, 5, NULL, '', '04_06', NULL, 266, '', '');
