INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1085, '9788487189197', 'Los métodos de la Calidad Total', 1, '1989', 213, 'Les Outils de la Qualité Totale', 'media/core/9788487189197.jpg', 1, '2023-04-04 06:44:52.748616', '2023-04-04 06:44:52.748616', 710, 38, 6, 5, NULL, '', '04_07', NULL, 269, 'Generalidades. Elección de las tecnologías mediante la fiabilidad. Dominio del procedimiento de fabricación. Dominio de la calidad de las entradas/salidas. Análisis de las causas. Elementos de matemáticas. Problemas y ejercicios.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1086, '8424702638', 'Introduccion a la teleinformática', 1, '1988', 219, 'Intorduction a la Téléinformatique', 'media/core/sin-imagen_14UVzYZ.jpg', 1, '2023-04-04 06:50:03.809425', '2023-04-04 06:50:03.809425', 711, 38, 6, 5, NULL, '', '04_07', NULL, 270, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1087, '9782746045026', 'PHP y MySQL', 1, '2009', 590, NULL, 'media/core/9782746045026.jpg', 1, '2023-04-04 06:54:52.943626', '2023-04-04 06:54:52.943626', 712, 38, 6, 5, 'Informática técnica', '', '04_07', NULL, 271, 'Este libro sobre PHP y MySQL se dirige a los diseñadores y programadores que deseen utilizar PHP y MySQL para desarrollar un sitio web dinámico e interactivo. En la primera parte del libro, el autor presenta la implantación de una base de datos MySQL: lenguaje SQL (lenguaje de consulta estructurado), utilización de las funciones MySQL, construcción de una base de datos (tablas, índices, vistas) sin olvidar las técnicas avanzadas, como la búsqueda de texto completo o el desarrollo de rutinas. En la segunda parte del libro, después de presentar las características básicas del lenguaje PHP, el autor se centra en las necesidades específicas del desarrollo de sitios web dinámicos e interactivos, aportando respuestas precisas y completas con relación a sus aspectos principales: gestión de los formularios, gestión de las sesiones, envío de mensajes electrónicos y, por supuesto, acceso a una base de datos MySQL. Ilustrado con abundantes ejemplos comentados, este libro (escrito a partir de las versiones 5 de PHP y de MySQL) es a la vez completo y sintético, y le permite ir al grano. Los ejemplos citados en el libro pueden descargarse en esta página.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1088, '9688800651', 'Intorducción moderna a la ciencia dela computación. Con un enfoque algorítmico', 1, '1986', 316, NULL, 'media/core/9688800651.jpg', 1, '2023-04-04 06:58:52.946381', '2023-04-04 06:58:52.946381', 713, 38, 6, 5, NULL, '', '04_07', NULL, 272, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1089, '9788441535992', 'Fundamentos de programación iOS7', 1, '2014', 563, 'Learning iOS Development: A Hands-on Guide to the Fundamentals of iOS Programming', 'media/core/sin-imagen_XN9CBHk.jpg', 1, '2023-04-04 07:04:34.577897', '2023-04-04 07:04:34.577897', 714, 38, 6, 5, NULL, '', '04_07', NULL, 273, 'La expresión «El futuro está en la tecnología móvil» es cada vez más habitual. La evolución de iOS ha sido extraordinaria desde el lanzamiento del iPhone, tanto en lo referido a las API como a las herramientas para el desarrollador, generando dispositivos Apple con más recursos y más facilidad de uso.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1090, '9688801135', 'Algortimos y estructuras de datos', 1, '1987', 301, 'Algorithms & Data Structures', 'media/core/9688801135.jpg', 1, '2023-04-04 07:09:10.634816', '2023-04-04 07:09:10.634816', 715, 38, 6, 5, NULL, '', '04_07', NULL, 272, 'https://en.wikipedia.org/wiki/Algorithms_%2B_Data_Structures_%3D_Programs', '');
