INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1098, '8470872850', 'Logística en Informática de Aprovisionamiento', 1, '1990', 480, NULL, 'media/core/8470872850.jpg', 1, '2023-04-04 08:35:54.976029', '2023-04-04 08:35:54.976029', 722, 38, 6, 5, NULL, '', '04_07', NULL, 276, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1099, '9788428316873', 'Redes locales. Teoría y programación de las redes IBM', 1, '1989', 182, 'Reseaux locaux IBM. Programmation NET BIOS', 'media/core/sin-imagen_HxleoJD.jpg', 1, '2023-04-04 08:39:04.006691', '2023-04-04 08:39:04.006691', 723, 38, 6, 5, NULL, '', '04_07', NULL, 277, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1100, '9788476151785', 'Metodología de la programación. Aplicaciones en BASIC, COBOL y PASCAL', 1, '1991', 313, NULL, 'media/core/9788476151785.jpg', 1, '2023-04-04 08:42:07.868464', '2023-04-04 08:42:07.868464', 724, 38, 6, 5, 'Informática de gestión', '', '04_07', NULL, 274, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1101, '8436545710784', 'La ratita presumida', 1, NULL, 1, NULL, 'media/core/8436545710784.jpeg', 1, '2023-04-04 08:47:00.838918', '2023-04-04 08:47:00.838918', NULL, 27, 6, 5, NULL, '', '04_07', NULL, NULL, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1102, '8422639769', 'Memorial del convento', 1, '1992', 331, 'Memorial do convento', 'media/core/8422639769.jpeg', 1, '2023-04-04 10:53:42.614110', '2023-04-04 10:53:42.614110', 725, 1, 6, 5, NULL, '', '05_01', NULL, 14, 'El volumen recorre un periodo de aproximadamente 30 a#os en la historia de Portugal durante la #poca de la Inquisici#n. El planteamiento registra no s#lo el hecho hist#rico, sino que reconstruye la vida popular de la #poca, en un recorrido por los diferentes pueblos de los alrededores de Lisboa.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1103, '8422635569', 'Los hechos del Rey Arturo y sus nobles caballeros', 1, '1979', 408, 'The Acts of King Arthur and his Noble Knights', 'media/core/8422635569.jpg', 1, '2023-04-04 10:56:52.401410', '2023-04-04 10:56:52.401410', 657, 1, 6, 5, NULL, '', '05_01', NULL, 93, 'Steinbeck resucita bellamente el cautivante mundo del rey Arturo y sus nobles caballeros de la Tabla Redonda -que incluye al mago Merlín y a los amores entre la bella Ginebra y Lanzarote del Lago- con todo su irrepetible esplendor medieval.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1104, '9788422647508', 'El puente de Alcántara', 1, '1995', 907, 'Die Brücke von Alcántara', 'media/core/9788422647508.jpeg', 1, '2023-04-04 11:01:07.999357', '2023-04-04 11:01:07.999357', 726, 16, 6, 5, NULL, '', '05_01', NULL, 93, '“Un gran fresco de la España del año 1000 ” Jacinto Antón, Babelia. El puente de Alcántara marcó un hito en la consolidación de la narrativa histórica como género literario, y es todavía la mejor y más completa novela sobre la España de las tres culturas escrita hasta el momento. A través de las peripecias de un poeta árabe andaluz, un médico judío y un joven escudero escudero cristiano, Baer pinta un colorido fresco de la España del siglo XI, al tiempo que reconstruye la evolución de las relaciones entre las culturas y religiones que representan cada uno de ellos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1105, '8422635585', 'Memorias de Cristobal Colón', 1, '1987', 807, 'The Memoirs of Christopher Columbus', 'media/core/8422635585.jpg', 1, '2023-04-04 11:04:55.618711', '2023-04-04 11:04:55.618711', 727, 16, 6, 5, NULL, '', '05_01', NULL, 278, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1106, '8422635526', 'El vellocino de oro', 1, '1983', 537, 'The Gloden Fleece', 'media/core/8422635526.jpg', 1, '2023-04-04 11:08:50.703486', '2023-04-04 11:08:50.703486', 728, 16, 2, 5, NULL, '', '05_01', NULL, 93, 'El Argo, una galera de guerra, partió de Yolcos llevando a bordo una asombrosa tripulación de héroes y semidioses (Hércules, Orfeo, Atalanta, Cástor, Pólux, Linceo y otros muchos) con el objetivo de robar el famoso Vellocino de Oro, celosamente custodiado por el rey de Cólquide. Esta historia de maravillas y portentos, de extraordinarios episodios que se suceden sin interrupción y que llevan a los héroes por toda la costa meridional del mar Negro, es asimismo una admirable reconstrucción del caracter y las costumbres griegas (el amor a la comida, el temor a la venganza de los espectros y los dioses), y el más completo y veraz de los muchos relatos que a los largo de los siglos se han escrito sobre esta remota y fascinante aventura marítima', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1107, '8422635488', 'Sinuhé, el egipcio', 1, '1968', 698, 'Sinuhe, egyptiläinen', 'media/core/8422635488.jpg', 1, '2023-04-04 11:13:15.173413', '2023-04-04 11:13:15.173413', 729, 16, 6, 5, NULL, '', '05_01', NULL, 96, 'En el ocaso de su vida, el protagonista de este relato confiesa: "Porque yo, Sinuhe, soy un hombre y como tal he vivido en todos los que han existido antes que yo, y viviré en todos los que existan después de mí. Viviré en las risas y en las lágrimas de los hombres, en su bondad y su maldad, en su debilidad y su fuerza."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1108, '842264746X', 'El druida', 1, '1994', 509, 'Druids', 'media/core/842264746X.jpg', 1, '2023-04-05 09:29:20.524227', '2023-04-05 10:04:50.363424', 730, NULL, 6, 5, NULL, '', '05_01', NULL, 74, 'Ainvar, guardián del Bosque Sagrado y jefe druida, guía a los galos en la lucha contra la colonización romana. Su antiguo rival, el príncipe guerrero Vercingetórix, se convierte en su aliado y lidera esta insurrección contra el procónsul romano Julio César, ávido de anexionar la legendaria civilización gala a su imperio. Con él colaboran mercaderes ambiciosos y jefes tribales corruptos. La inicial aparición de pacíficas factorías romanas en la zona pronto se tiñe con batallas sanguinarias, asedios a ciudades, conspiraciones, asesinatos, sacrificios humanos y subastas de prisioneros. La profunda entrega del druida a la causa de su pueblo se combina con la devoción por la naturaleza y un fuerte instinto de protección del modelo poligámico. Por sus apasionados brazos pasan tanto princesas como esclavas. Una novela intensa y rigurosa donde los valores sublimes de un pueblo amante de la naturaleza chocan con la realidad de la guerra, la traición, el asesinato y los sacrificios rituales.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1109, '842263550X', 'Fuego del Paraíso', 1, '1991', 483, 'Fire from Heaven', 'media/core/842263550X.jpg', 1, '2023-04-05 09:31:52.259329', '2023-04-05 10:05:53.436443', 173, 16, 6, 5, NULL, '', '05_01', 'Trilogía de Alejandro Magno I', 72, 'En una corte en la que conviven el refinamiento y la crueldad, el amor y la traición, el joven Alejandro Magno se muestra ya a muy temprana edad como un niño singular, con una perspicacia poco común y un talento innato tanto para comprender las tácticas bélicas como para moverse con soltura entre las intrigas palaciegas. Sus amistades, los equilibrios de poder entre los que se mueve, su afán de conocimiento y sus relaciones sentimentales son algunos de los aspectos de Alejandro en lo que con la profundidad y brillantez que la caracterizan, se centra Mary Renault en esta primera entrega del monumental fresco que dedicó a Alejandro Magno.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1110, '8422647427', 'El papiro de Saqqara', 1, '1994', 550, 'Scroll of Saqqara', 'media/core/8422647427.jpg', 1, '2023-04-05 09:34:35.849099', '2023-04-05 10:05:00.207909', 268, 16, 6, 5, NULL, '', '05_01', NULL, 48, 'Khaemuast, cuarto hijo de Ramsés II y virtual gobernante del vasto imperio faraónico, es un hombre sabio y austero. El control de la administración y la vida cortesana son arduas obligaciones a las que se ve arrastrado por la incompetencia de su padre, más interesado en la pompa y el boato que en el difícil ejercicio del poder. Por el contrario, la verdadera pasión del príncipe es la historia, la magia y la medicina, y su prurito es hallar el mítico pargamino de Thot, la fuente de la vida para los antiguos egipcios.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1111, '8422647478', 'Espartaco', 1, '1994', 359, 'The Gladiators', 'media/core/8422647478.jpeg', 1, '2023-04-05 09:36:40.386390', '2023-04-05 10:05:40.891452', 732, 16, 6, 5, NULL, '', '05_01', NULL, 93, 'La insólita aventura de una banda de gladiadores y esclavos que tuvo en jaque durante más de dos años a las poderosas legiones del Imperio Romano. Koestler recrea con gran fuerza dramática esta gesta libertaria.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1112, '8422647451', 'Los jardines de Luz', 1, '1994', 263, 'Les jardins de lumière', 'media/core/8422647451.jpg', 1, '2023-04-05 09:39:53.834176', '2023-04-05 10:06:05.509997', 733, 16, 6, 5, NULL, '', '05_01', NULL, 279, 'En el inicio de la era cristiana y cerca de las orillas del Tigris comienza la historia de un hombre que, bautizado con el nombre de Mani, llegará a ser el fundador de una doctrina universal, conciliadora de tres religiones y reveladora de una visión del mundo profundamente humana y tan audaz que acabaría siendo perseguida ferozmente por todos los imperios de su tiempo. Amin Maalouf recrea en Los Jardines de Luz la azarosa existencia de este hombre singular llamado en Egipto «el apóstol de Jesús» y conocido en China como «el Buda de Luz», que le conducirá, a través de numerosos avatares, desde la gran metrópoli de Ctesifonte a las populosas ciudades de la India y a la ciudad de Beth-Lapat, donde le espera la muerte.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1113, '9788422647492', 'Claudio el dios y su esposa Mesalina', 1, '1995', 536, 'Claudius the God and his Wife Mesalina', 'media/core/9788422647492.jpg', 1, '2023-04-05 09:42:39.846659', '2023-04-05 10:56:48.200619', 728, 16, 6, 5, NULL, '', '05_01', NULL, 5, 'En el díptico que integran «Yo, Claudio» y CLAUDIO EL DIOS Y SU ESPOSA MESALINA, la amplitud y la profundidad de los conocimientos sobre la Antigüedad clásica de ROBERT GRAVES (1895-1985) se conjugan con una prosa de enorme belleza a la que da aliento una poderosa y viva imaginación, capaz de reconstruir toda la grandeza y miseria de la Roma imperial. Segundo y último volumen de la supuesta «autobiografía» de este singular emperador, destinado a serlo contra sus propias inclinaciones, en él Claudio alcanza la púrpura imperial y encauza todos sus esfuerzos, con el apoyo del pueblo llano, a reparar el legado de estragos y desastres que ha recibido de su antecesor, sin que su inesperado ascenso, no obstante, le procure la felicidad personal.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1114, '9788422647522', 'El bosque de la larga espera', 1, '1995', 669, 'Het Woud der Verwachting', 'media/core/9788422647522.jpg', 1, '2023-04-05 09:46:12.631353', '2023-04-05 09:46:12.631353', 734, 16, 6, 5, NULL, '', '05_01', NULL, 93, 'El melancólico Carlos de Orleans y el ambicioso duque de Borgoña luchan para defender sus respectivas casas en un episodio de la Guerra de los Cien Años, que enfrentó a Francia e Inglaterra a caballo entre los siglos XIV y XV. Una de las novelas históricas más intensas escritas en el siglo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1115, '9788422647515', 'El Ángel Sombrío', 1, '1994', 394, 'Johannes Angelos', 'media/core/9788422647515.jpg', 1, '2023-04-05 09:48:46.971758', '2023-04-05 09:48:46.971758', 729, 16, 6, 5, NULL, '', '05_01', NULL, 93, 'La lucha ha sido larga, dura y cruenta, pero, a sangre y fuego, en la primavera de 1453, los otomanos logran vencer la resistencia desesperada que opone la capital del Imperio bizantino. Entre los asediados destaca la figura del misterioso Giovanni Angelos, un hombre con un pasado oscuro y tan temido como admirado por los nobles y generales de Constantino. Aun a sabiendas de que la caída de Constantinopla es inevitable, Angelos decide ir hasta allí. Las consecuencias son imprevisibles: se enamorará de la orgullosa hija del duque Lucas Notara y no podrá ocultar para siempre su gran secreto? En El ángel sombrío, publicada también con anterioridad como El sitio de Constantinopla, Mika Waltari (autor también de la conocida novela Sinué, el egipcio) describe magistralmente los últimos días de la ciudad, pero también de sus protagonistas, y nos demuestra una vez más por qué está considerado un autor legendario dentro de la novela histórica.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1116, '8422635534', 'Aníbal', 1, '1990', 732, 'Hannibal. Der Roman Karthagos', 'media/core/8422635534.jpg', 1, '2023-04-05 09:52:40.672038', '2023-04-05 09:52:40.672038', 735, 16, 6, 5, NULL, '', '05_01', NULL, 93, 'Antígono, heleno asentado en Cartago, cuenta la historia de Aníbal, el gran comandante africano que en el siglo III a.C. se atrevió a desafiar el poder de Roma. Uno de los genios militares más grandes de la historia en una de las novela históricas más célebres de las últimas décadas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1117, '8422647400', 'Las memorias de Lord Byron', 1, '1991', 197, 'The Memoirs of Lord Byron', 'media/core/8422647400.jpg', 1, '2023-04-05 09:55:37.991298', '2023-04-05 09:55:37.991298', 736, 16, 6, 5, NULL, '', '05_01', NULL, 93, 'Quemadas inmediatamente después de su muerte, las memorias del más enigmático de los poetas románticos ingleses son reconstruidas aquí tras años de investigaciones. Genial, libertino, doliente y, sobre todo, profundamente humano.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1118, '8422647486', 'Los últimos días de Pompeya', 1, '1995', 563, 'The Last Days of Pompeii', 'media/core/8422647486.jpg', 1, '2023-04-05 09:59:05.738517', '2023-04-05 09:59:05.738517', 737, 16, 6, 5, NULL, '', '05_01', NULL, 5, 'Pompeya, año 79 d.C. Glauco, Diones, Nydia y Arbaces viven los cuatro días previos a la erupción del Vesubio, ajenosINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1119, '8422631091', 'Leon el Africano', 1, '1988', 379, 'Léon l''Africain', 'media/core/8422631091.jpg', 1, '2023-04-05 10:01:25.404920', '2023-04-05 10:01:25.404920', 733, 16, 6, 5, NULL, '', '05_01', NULL, 279, 'En una época de crisis en la que dos grandes imperios pugnan por la supremacía en el Mediterráneo, Hasan, nacido en Granada poco antes de 1492 y más conocido como León el Africano, emprende una extraordinaria peregrinación que, guiado por su pasión de vivir, lo llevará a la misteriosa ciudad de Tombuctú, a los quince reinos negros situados entre el Níger y el Nilo, y a la deslumbrante Constantinopla. Finalmente, sus conocimientos y experiencias, donde se funden la cultura oriental y la occidental, el mundo cristiano y el del islam, serán puestos al servicio del papa León X y de Julio de Médicis.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1120, '8422635577', 'La piedr angular', 1, '1992', 514, 'La pierre angulaire', 'media/core/8422635577.jpg', 1, '2023-04-05 10:30:03.866562', '2023-04-05 10:30:03.866562', 84, 16, 6, 5, NULL, '', '05_01', NULL, 58, 'Impresionante retablo del mundo feudal, La Piedra Angular sitúa su acción a principios del siglo XIII. La vida de los señores feudales, el ambiente de los torneos, la envidia y la ambición de mayores riquezas contrastan con la miseria de los peregrinos, de los vagabundos que se escapan de los horrores de la guerra. Los protagonistas del extenso relato son inlvidables: Ansiau, ciego, mendicante, con su orgullo de antuguo cruzado; Herbert, codicioso, violento y sensual; Haguenier, noven y exaltado, consagrado al servicio de su dama y luego de Dios. La autora estudia a través de estos seres los eternos problemas del hombre y de la historia para hacernos comprender aquellas cosas que hicieron cambiar la vida y las costumbres de los hombres pero también a aquellas que dieron origen a tantas tragedias individuales y colectivas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1121, '8422635550', 'Juliano, el Apóstata', 1, '1983', 580, 'Julian', 'media/core/8422635550.jpg', 1, '2023-04-05 10:33:09.446302', '2023-04-05 10:33:09.446302', 738, 16, 6, 5, NULL, '', '05_01', NULL, 93, 'La vida de Juliano, considerado a menudo “un héroe de la resistencia” contra el cristianismo en nombre de los valores del helenismo, es la historia de un fracaso, pero sobre todo la de una lucha sin cuartel por la libertad de culto y contra la intolerancia religiosa durante las últimas décadas del siglo IV d.C.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1122, '8422635496', 'El médico de Córdoba', 1, '1991', 290, 'Le médecin de Cordoue', 'media/core/8422635496.jpg', 1, '2023-04-05 10:36:59.888989', '2023-04-05 10:36:59.888989', 739, 16, 6, 5, NULL, '', '05_01', NULL, 72, 'En el siglo XII Córdoba, capital califal de al-Andalus, era una ciudad de calles pavimentadas, de magníficos jardines y con una de las universidades más reputadas del mundo medieval. En ella convivían tres culturas: la árabe, la cristiana y la judía.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1123, '8422647443', 'El muhaho persa', 1, '1994', 509, 'The Persian Boy', 'media/core/8422647443.jpeg', 1, '2023-04-05 10:39:16.915990', '2023-04-05 10:39:16.915990', 173, 16, 6, 5, NULL, '', '05_01', NULL, 72, 'Basada en una figura histórica, El muchacho persa cuenta los últimos años de vida de Alejandro Magno a traves de los ojos del que fuera su amante, Bagoas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1124, '8422635518', 'El gran emperador y sus autómatas', 1, '1991', 347, 'Le Grand Empereur et ses automates', 'media/core/8422635518.jpg', 1, '2023-04-05 10:42:16.187156', '2023-04-05 10:42:16.187156', 740, 16, 6, 5, NULL, '', '05_01', NULL, 279, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1125, '8422635607', 'La visita en el tiempo', 1, '1990', 294, NULL, 'media/core/8422635607jpg.jpg', 1, '2023-04-05 10:52:39.788756', '2023-04-05 10:52:39.788756', 741, 16, 2, 5, NULL, '', '05_01', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1126, '8422635542', 'Yo, Claudio', 1, '1991', 500, 'I, Cludius', 'media/core/8422635542.jpg', 1, '2023-04-05 10:56:18.197118', '2023-04-05 10:56:18.197118', 728, 16, 6, 5, NULL, '', '05_01', NULL, 5, 'Llegado a los últimos años de su vida y temeroso de caer asesinado víctima de una conspiración, el emperador Claudio (o "Clau-Clau-Claudio", o "Claudio el idiota") decide consignar por escrito su larga y azarosa vida desde los días en que gobernaba su tío abuelo Augusto, a cuya sombra su esposa Livia movía los hilos del poder. En esta novela inolvidable vemos desfilar delante de nosotros todo el esplendor y miseria de los primeros años del Imperio Romano, embarcado muy pronto en una espiral de conspiraciones, crueldad y violencia bajo los reinados del taciturno Tiberio y del extravagante Calígula. Lectura apasionante desde su primera línea, "Yo, Claudio" es sin duda una de las cinco mejores novelas históricas de todos los tiempos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1127, '8422647419', 'Creación', 1, '1982', 692, 'Creation', 'media/core/8422647419.jpg', 1, '2023-04-05 10:59:02.608478', '2023-04-05 10:59:02.608478', 738, 16, 6, 5, NULL, '', '05_01', NULL, 93, 'Creación una de las novelas más ambiciosas de Gore Vidal , narra el periplo de Ciro Espitama, embajador de un imperio que se extiende desde el Mediterráneo hasta la India, en su afán por resolver algunos de los grandes enigmas de todos los tiempos. De este modo, su espléndido relato se convierte en fascinante recorrido por los tiempos de Buda, Confucio, Anaxágoras, Herodoto, Pericles y Sócrates. En el ámbito de la novela histórica, probablemente no exista una obra que refleje con tanta fuerza, amplitud y precisión el ambiente de una época como Creación .', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1128, '9788466656412', 'El Príncipe Lestat', 1, '2015', 547, 'Prince Lestat', 'media/core/9788466656412.jpg', 1, '2023-04-05 11:21:17.467640', '2023-04-05 11:21:17.467640', 72, 12, 6, 5, NULL, '', '05_01', 'Crónicas vampíricas', 8, '«Beberé de tu sangre y tú beberás la mía. Nos conoceremos y amaremos el uno al otro, y seremos hermanos por siempre jamás, sangre de la misma sangre. »INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1129, '9788466647915', 'El don del Lobo', 1, '2012', 506, 'The Wolf Gift', 'media/core/9788466647915.jpg', 1, '2023-04-05 11:24:04.363843', '2023-04-05 11:24:04.363843', 72, 12, 6, 5, NULL, '', '05_01', 'Crónicas del Lobo', 8, 'Una anciana da la bienvenida a su majestuosa casa familiar al joven reportero delSan Francisco Observer Reuben Holding. Él tiene que escribir un artículo sobre la mansión, y ella quiere venderla con cierta urgencia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1130, '9788427016101', 'La fuerza de su mirada', 1, '1992', 487, 'The Stress of Her Regard', 'media/core/9788427016101.jpeg', 1, '2023-04-05 11:26:51.552164', '2023-04-05 11:26:51.552164', 519, 13, 2, 5, 'Gran Fantasy', '', '05_01', NULL, 41, 'La obra cumbre de la fantasía histórica moderna. Una recreación apasionante del romanticismo inglés tras la que ni vampiros ni poetas han vuelto a ser los mismos. El doctor Michael Crawford se hospeda en una posada inglesa de camino hacia su boda. Ebrio en medio de una tormenta y temeroso de perder el anillo con el que desposará a su prometida, lo coloca en el dedo de una estatua para recogerlo más tarde. Durante la noche despierta sobresaltado y recuerda dónde lo ha dejado; cuando sale a buscarlo descubre que la estatua no está. Aunque aún no lo sabe, Crawford ya se ha casado... La fuerza de su mirada es la obra más elaborada y satisfactoria de Powers. Conjuga de forma impecable la ambientación histórica, biografías apócrifas de Byron, Shelley y Keats, y una increíble reelaboración de los mitos fantásticos más arraigados en la cultura popular. Nephelim, lamias y otros seres de longevidad extraordinaria pueblan una novela única y maravillosa en la que se mezclan acción, erotismo, drama y humor.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1131, '9788427017405', 'La últiima partida', 1, '1993', 629, 'Last Call', 'media/core/9788427017405.jpg', 1, '2023-04-05 11:29:41.628298', '2023-04-05 11:29:41.628298', 519, 13, 6, 5, 'Gran Fantasy', '', '05_01', NULL, 41, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1132, '9788467246872', 'Sangre en la calle del turco', 1, '2011', 506, NULL, 'media/core/9788467246872.jpeg', 1, '2023-04-05 11:32:18.371744', '2023-04-05 11:32:18.371744', 742, 1, 6, 5, NULL, '', '05_01', NULL, 211, 'Fernando Besora, un joven periodista natural de Reus, busca hacerse un hueco en el panorama literario de la Espa#a de 1870. Preparando una cr#nica, encuentra una pista tenebrosa sobre un asunto acaecido en Madrid que lo conducir# hasta una peligrosa secta. A la vez se enfrenta al reto imposible de su amor por Paloma Azpeitia, en un tiempo donde las mujeres eran utilizadas por sus familias como moneda de cambio. Pero sobre todo se ve involucrado en la oscura trama que se teje alrededor del general Prim, cuyo deseo de acabar con la dinast#a borb#nica se ve entorpecido por las ambiciones de personajes como el duque de Montpensier o el general Serrano.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1133, '9788422666028', 'Los Nombres. Su significado y su influencia secreta sobre el carácter y el destino', 1, '1995', 475, NULL, 'media/core/9788422666028.jpg', 1, '2023-04-05 11:36:52.550230', '2023-04-18 17:52:27.489978', 743, 15, 6, 5, NULL, '', '05_01', NULL, 280, 'Este amplio diccionario de nombres propios permite al lector profundizar en el conocimiento del significado, los antecedentes y el anecdotario que rodean a la mayoría de los nombres de persona conocidos y lo que se oculta detrás de ellos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1134, '9788467250176', 'Northumbria, el último reino', 1, '2006', 377, 'The Last Kingdom', 'media/core/9788467250176.jpeg', 1, '2023-04-05 11:40:59.153288', '2023-04-05 11:40:59.153288', 744, 16, 6, 5, NULL, '', '05_01', NULL, 47, 'En el 866 Uthred, un joven anglo-sajón de ascendencia aristocrática, vive escindido entre dos mundos antagónicos. Desde pequeño vive entre vikingos, pues fue raptado por estos, lo que le otorga una situación privilegiada desde la que enjuiciar las costumbres, las creencias y los ritos de sajones y daneses. Poco a poco Uthred va ganándose el respeto de los vikingos por su audacia y su valentía, pero, como no podía ser de otra manera, llega un momento en que la cuestión de la identidad se convierte para él en un peso difícil de soportar.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1135, '9788467253221', 'Las voces del Pamano', 1, '2004', 638, 'Les veus del Pamano', 'media/core/9788467253221.jpeg', 1, '2023-04-05 11:44:37.129195', '2023-04-05 11:44:37.129195', 745, 1, 6, 5, NULL, '', '05_01', NULL, 58, '«Macondo está en los Pirineos.» Die Welt Tina, una pacífica maestra, fotografía al azar una escuela de un pequeño pueblo de un valle del Pallars que está a punto de ser demolida. Tras la pizarra, se encuentra una cajita que contiene una larga carta escrita en un cuaderno escolar que jamás llegó a su destinatario. Poco a poco, Tina se irá adentrando en la memoria de esos valles e irá desvelando las piezas de una historia de maquis, falangistas y héroes anónimos envuelta en la bruma del olvido Una novela extraordinaria sobre las luces y las sombras de la guerra; sobre la fuerza de la vivencia y la fragilidad del recuerdo histórico.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1136, '9788408103257', 'LOs asesinos del emperador', 1, '2011', 1174, NULL, 'media/core/9788408103257.jpg', 1, '2023-04-05 11:47:49.546362', '2023-04-05 11:47:49.546362', 156, 16, 6, 5, 'Autores Españoles e Iberoamericanos', '', '05_01', 'Trilogía de Trajano I', 7, 'El ascenso de Trajano, el primer emperador hispano de la Historia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1137, '8435011062', 'Lilith', 1, '1988', 327, NULL, 'media/core/8435011062.jpg', 1, '2023-04-05 11:54:37.170469', '2023-04-05 11:54:37.170469', 746, 1, 6, 5, 'fantásticas', '', '05_01', NULL, 47, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1138, '9788435011006', 'Antología de la literatura fantástica', 1, '1989', 437, NULL, 'media/core/9788435011006.jpeg', 1, '2023-04-05 11:58:29.382691', '2023-04-05 11:58:29.382691', 572, 29, 6, 5, 'fantásticas', '', '05_01', 'Antología de la Literatura Fantástica', 47, 'De Oriente a Occidente, de la antigüedad a nuestro siglo, he aquí algunas de las piezas fantásticas más significativas y logradas de la historia literaria. «El fruto de oro de la imaginación», el cuento fantástico, muestra aquí su vertiginosa fascinación.', 'Jorge Luis >Borges; Adolfo Bioy Casares; Silvina Ocampo');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1139, '8435011097', 'El color que cayó del cielo', 1, '1988', 297, 'The Call of Cthulhu', 'media/core/8435011097.jpeg', 1, '2023-04-05 12:03:10.199061', '2023-04-05 12:03:10.199061', 747, 12, 6, 5, 'Fantásticas', '', '05_01', NULL, 47, '«No podía regresar a aquel caos difuso de bosque antiguo y colinas, o en-frentar otra vez el páramo calcinado gris donde el pozo de agua negra boste-zaba profundo junto a los ladrillos y las piedras derruidas.» Un meteorito atraviesa millones de kilómetros y se incrusta en las colinas de Arkham. Al romperse, una tonalidad supranatural, nunca vista, emerge e infecta las napas de agua. Desde el elemento vital, pasa a los animales y a los seres humanos, a quienes trastorna y enloquece. La amenaza cobra un carácter impenetrable y escapar se torna imposible. Las ilustraciones del dibujante Salvador Sanz, de marcado estilo hiperrea-lista, rubrican esta novela corta de terror metafísico ?traducida por Elvio Gandolfo? a través de un poderoso manejo de contrastes y de la irrupción de la luz. La mitología característica del maestro de a literatura fantástica y de terror toma nueva vida a través de la técnica de Sanz, quien recrea con maestría el hedor que rodea los bosques tenebrosos de Arkham.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1140, '9788435011174', 'La alforjas de Kai-Lung', 1, '1990', 290, 'The Wallet of Kai Lung', 'media/core/9788435011174.jpg', 1, '2023-04-05 12:07:41.547000', '2023-04-05 12:07:41.547000', 748, 1, 6, 5, 'Fantásticas', '', '05_01', NULL, 47, 'Publicado originalmente en 1900 y el primero de los libros que Enerst Bramah dedicó a kai Lung, es una suma de relatos, refinados, irónicos, sobre la vida y tradiciones chinas de la época Ming.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1141, '9788435011150', 'Historias de fantasmas de la literatura de inglesa', 1, '1989', 397, 'The Oxford Book of English Ghost Stories', 'media/core/9788435011150.jpg', 1, '2023-04-05 12:53:00.271685', '2023-04-05 12:53:00.271685', 572, 12, 6, 5, 'Fantásticas', '', '05_01', 'Vol I', 47, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1142, '9788435011167', 'Historias de fantasmas de la lliteratura inglesa', 1, '1989', 386, 'The Oxford Book of English Ghost Stories', 'media/core/9788435011167.jpeg', 1, '2023-04-05 12:55:57.594832', '2023-04-05 12:55:57.594832', 749, 12, 6, 5, 'Fantásticas', '', '05_01', 'Vol II', 47, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1143, '9788435011198', 'Siempre hemos vivido en el castillo', 1, '1990', 189, 'We Have Always Lived in the Castle', 'media/core/9788435011198.jpg', 1, '2023-04-05 13:02:45.898003', '2023-04-05 13:02:45.898003', 750, 13, 6, 5, 'fantásticas', '', '05_01', NULL, 47, 'Merricat lleva una vida solitaria en una gran casa apartada del pueblo. Allí pasa las horas recluida con su bella hermana mayor y su anciano tío Julián. En el hogar de los Blackwood los días discurrían apacibles si no fuera porque los otros miembros de la familia murieron envenenados allí mismo, en el comedor, seis años atrás.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1144, '9788491046691', 'Historia  de la Unión Soviética. De la Revolución >Bolchevique a Gorbachov', 2, '2017', 434, NULL, 'media/core/9788491046691.jpg', 1, '2023-04-05 13:05:54.287064', '2023-10-24 10:51:04.112368', 751, 2, 6, 5, NULL, '', '07_03', NULL, 69, 'Hace cien años, a finales de 1917, cristalizó uno de los episodios que se habían de revelar decisivos en la historia del siglo XX: la revolución bolchevique acabó definitivamente con el imperio zarista y alumbró la Unión de Repúblicas Socialistas Soviéticas, oficialmente disuelta en 1991 con la dimisión de su último dirigente, Mijaíl Gorbachov. En este libro se examina en detalle lo que la Unión Soviética fue y representó como una de las dos superpotencias del siglo XX, en la firme convicción de que su sistema experimentó cambios notables con el paso del tiempo y se desplegó conforme a patrones diferentes en los distintos espacios geográficos que abarcó el país más extenso del globo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1145, '9788467249743', 'La sonrisa etrusca', 1, '1985', 308, NULL, 'media/core/9788467249743.jpg', 1, '2023-04-05 13:09:04.430648', '2023-04-05 13:09:04.430648', 752, 1, 6, 5, NULL, '', '05_01', NULL, 5, 'Un viejo campesino calabres llega a casa de sus hijos en Milán para someterse a una revisión medica. Allí descubre su último afecto, una criatura en la que volcar toda su ternura: su nieto, que se llama Bruno, como a el le llaman sus camaradas partisanos. Y vive tambien su última pasión: el amor de una mujer que iluminará la etapa final de su vida concediendole toda su plenitud.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1146, '9788499427904', 'No todo vale', 1, '2019', 1, NULL, 'media/core/9788499427904.jpg', 1, '2023-04-05 13:12:05.785424', '2023-04-05 13:12:05.785424', 753, 2, 6, 5, NULL, '', '05_01', NULL, 192, 'Un viaje por los vericuetos legales del procés, y lo que destapan de lo ocurrido en Cataluña.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1147, '9788498923100', 'La guerra de Sucesión de España (1700-1714)', 201, '2010', 498, NULL, 'media/core/9788498923100.jpg', 1, '2023-04-05 13:16:02.211480', '2023-04-05 13:16:02.211480', 754, 2, 6, 5, NULL, '', '05_01', NULL, 61, 'La Guerra de Sucesión de España fue el más importante de los conflictos armados de su tiempo. La Guerra de Sucesión de España fue "una guerra tan universal como no se ha visto nunca", en palabras del Almirante de Castilla, que se extendió por el conjunto de Europa y por America. Pero donde su trascendencia fue mayor fue precisamente en territorio español, donde tomó el cariz de una guerra civil y cuyo resultado iba a marcar profundamente la evolución posterior de la monarquía española. Objeto de numerosos estudios locales y de polemicas de la más diversa naturaleza, resulta sorprendente que no pudieramos disponer en la actualidad de una visión de conjunto que sintetizase los resultados de las investigaciones de las últimas decadas en todas las diversas dimensiones del conflicto: militares, políticas y sociales. Esto es lo que ha elaborado el profesor Albareda que aporta, además, los hallazgos de su propia investigación en los archivos europeos para ofrecernos aquí una visión amplia, documentada e innovadora de un episodio crucial de nuestra historia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1148, '9788490322505', 'Pensar rápido, pensar despacio', 6, '2019', 544, 'Thinking,Fast and Slow', 'media/core/9788490322505.jpg', 1, '2023-04-05 13:24:52.670777', '2023-04-05 13:24:52.670777', 755, 2, 6, 5, 'Debolsillo', '', '05_01', NULL, 34, 'EnPensar rápido, pensar despacio, un éxito internacional, Kahneman nos ofrece una revolucionaria perspectiva del cerebro y explica los dos sistemas que modelan cómo pensamos. Daniel Kahneman, uno de los pensadores más importantes del mundo, recibió el premio Nobel de Economía por su trabajo pionero en psicología sobre el modelo racional de la toma de decisiones. Sus ideas han tenido un profundo impacto en campos tan diversos como la economía, la medicina o la política, pero hasta ahora no había reunido la obra de su vida en un libro.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1149, '9788467246834', 'La Gran Armada', 1, '2011', 445, 'The Sapnish Armada', 'media/core/9788467246834.jpeg', 1, '2023-04-05 13:28:31.812577', '2023-04-05 13:28:31.812577', 756, 11, 6, 5, NULL, '', '05_01', NULL, 15, 'Tras su intento de invadir Inglaterra, la Armada de 130 navíos fl etada por Felipe II desapareció a fi nales del verano de 1588 en los mares septentrionales. ¿Cuál fue la realidad de la amenaza española y por qué fracasó? Para dar respuesta a estas preguntas, Geoffrey Parker analiza gran cantidad de información —no estudiada hasta ahora— procedente de los archivos más importantes de España y Holanda. Esta información se completa con el descubrimiento de los restos de la Armada, tres de cuyos barcos han sido estudiados por el arqueólogo marino, Colin Martin. Esta reconstrucción de La Gran Armada llega a conclusiones inesperadas y destruye algunos mitos vigentes durante mucho tiempo en la historiografía anglosajona. Por encima de todo, se trata de un relato que da vida a uno de los sucesos más apasionantes de la historia mundial.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1150, '9788467267693', 'La Guerra Civil Española', 1, NULL, 1, NULL, 'media/core/sin-imagen_O8DIIxh.jpg', 1, '2023-04-05 13:31:14.211582', '2023-04-05 13:31:14.211582', 757, 11, 6, 5, NULL, '', '05_01', NULL, 5, 'En el septuagesimo aniversario del estallido del trágico conflicto español, Paul Preston, hispanista de prestigio internacional, actualizó y amplió su estudio de la Guerra Civil teniendo en cuenta tanto las últimas investigaciones y polemicas historiográficas como abundante material inedito, ofreciendo su versión definitiva de La guerra civil española.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1151, '9788467255126', 'La Segunda Guerra Mundial', 1, '2012', 1100, 'The Secind World War', 'media/core/9788467255126.jpeg', 1, '2023-04-05 13:34:57.055215', '2023-04-05 13:34:57.055215', 758, 11, 6, 5, NULL, '', '05_01', NULL, 281, 'La segunda guerra mundial constituye la culminación de toda una carrera dedicada a la investigación y la narración históricas. Armado con la erudición más actualizada, apoyándose en un descomunal trabajo de investigación en el que siguen prevaleciendo las cartas y los diarios de los combatientes, y desplegando sus asombrosos recursos narrativos -que le permiten casar los grandes acontecimientos con las anécdotas más reveladoras-, Beevor nos muestra aquí el inmenso retablo de una guerra que se extendió desde el Atlántico Norte al Pacífico Sur, desde las nevadas estepas septentrionales a los áridos desiertos del norte de África; desde la jungla de Birmania hasta las fronteras de la Europa oriental; desde los prisioneros del Gulag reclutados para los batallones de castigo hasta las indecibles crueldades de la guerra entre China y Japón.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1152, '8422647435', 'El sueño de Confucio', 1, '1991', 315, 'Le rêve de Confucius', 'media/core/8422647435.peg.jpeg', 1, '2023-04-05 13:37:31.000729', '2023-04-05 13:37:31.000729', 740, 16, 6, 5, NULL, '', '05_01', NULL, 279, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1153, '9788422667001', 'Anales', 1, '1998', 570, NULL, 'media/core/9788422667001.jpeg', 1, '2023-04-10 08:18:26.776411', '2023-04-10 08:18:26.776411', 760, 11, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'Cornelio Tácito (ca. 56 - ca. 120), cumbre de la historiografía latina, al final de su vida escribió los Anales, obra en la que desenmascara a los emperadores de la familia Julio-Claudia, como Augusto, Tiberio, Calígula o Nerón. Al mismo tiempo, el historiador denuncia el servilismo del Senado. Por ello, los Anales han sido fundamentales para hacer de Tácito el eximio, y a veces nefando, maestro de políticos y gobernantes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1154, '9788422667018', 'Tratados', 1, '1998', 214, NULL, 'media/core/9788422667018.jpg', 1, '2023-04-10 08:22:25.266715', '2023-04-10 08:22:25.266715', 474, 2, 2, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'La compleja figura de Cicerón domina el panorama literario de la República romana tardía, ámbito en el que el conjunto de su obra se erige como un monumento central de la prosa latina clásica. Sus tratados filosóficos realizan la traslación a Roma de la herencia cultural griega.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1155, '9788422666974', 'De la naturaleza', 1, '1998', 286, NULL, 'media/core/sin-imagen_TNHReOw.jpg', 1, '2023-04-10 08:27:52.111315', '2023-04-10 08:27:52.111315', 761, 2, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'https://es.wikipedia.org/wiki/De_la_naturaleza_de_las_cosas', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1156, '9788422666943', 'Guerra de las Galias', 1, '1998', 251, NULL, 'media/core/9788422666943.jpeg', 1, '2023-04-10 08:31:23.222484', '2023-04-10 08:31:23.222484', 762, 11, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'Con el nombre de La guerra de las Galias se conocen los siete libros que Julio César (100 a. C. - 44 a. C.) dedicó a contar las campañas desarrolladas durante siete años (del 58 al 52) en las Galias, junto con las incursiones en Britania y en el territorio de los germanos. A cada año le corresponde un libro. Con La guerra de las Galias, Julio César pretendía extender la aureola de su fama explicando de una forma aparentemente aséptica la importancia y dificultad de sus hazañas. Y en este sentido, el hecho de no regatear elogios a sus lugartenientes ni rebajarles los méritos era un medio más de incorporarlos a su causa manteniendo su espíritu de colaboración. Sin embargo, estas pinceladas justificativas tienen&lt;;br /:GT;poco o nada que ver con la auténtica finalidad de la obra, que no era otra que ensalzar y magnificar unos logros bélicos que le permitieran ponerse a la altura de Pompeyo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1157, '9788422678991', 'Don Quijote de la Mancha', 1, '2000', 1, NULL, 'media/core/9788422678991.jpeg', 1, '2023-04-10 08:34:53.385775', '2023-04-10 08:34:53.385775', 680, 1, 2, 5, 'Clásicos españoles', '', '05_02', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1158, '9788422678960', 'Lazarillo de Tormes', 1, '1999', 142, NULL, 'media/core/9788422678960.jpg', 1, '2023-04-10 08:37:22.119806', '2023-04-10 08:37:22.119806', 141, 1, 2, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'https://es.wikipedia.org/wiki/La_vida_de_Lazarillo_de_Tormes', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1159, '9788422679004', 'Vide del Buscón', 1, '1999', 1, NULL, 'media/core/9788422679004.jpg', 1, '2023-04-10 08:40:00.232447', '2023-04-10 08:40:00.232447', 763, 1, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'Hijo de un ladrón y de una bruja. Pablos, el Buscón, entra al servicio de un joven rico, vive en Alcalá, en la corte y acaba viajando a América. Aunque su argumento no deja de ser muy similar al de otras obras del género. El Buscón no es una novela picaresca al uso. La maestría de su escritura, la vivacidad y sarcasmo en la descripción de personajes y situaciones, la inteligente crueldad de sus anécdotas, hacen de ella, una obra que rebasa los límites de su género, una novela picaresca que da una vuelta de tuerca al arquetipo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1160, '9788422679028', 'La Celestina', 1, '1999', 1, NULL, 'media/core/9788422679028.jpeg', 1, '2023-04-10 08:45:50.986201', '2023-04-10 08:45:50.986201', 764, 1, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'https://es.wikipedia.org/wiki/La_Celestina', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1161, '9788422678984', 'Libro de la vida', 1, '1999', 450, NULL, 'media/core/9788422678984.jpg', 1, '2023-04-10 08:48:04.586528', '2023-04-10 08:48:04.586528', 638, 31, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'El Libro de la Vida es, ciertamente, un documento histórico. Este libro recoge la vida de santa Teresa de Jesús, y está escrito por la propia santa. Documenta época y cultura, así como el entorno, clima social y religioso, usanzas, cultura y religiosidad de la Castilla de entonces. Todo este contenido es secundario, pues el verdadero clima del libro es interno, pertenece al mundo del alma de la autora. Teresa de Jesús escribió este libro porque le pasó una cosa fuera de serie, y "esa cosa fuera de serie" de cara a lo trascendente, en su relación con Dios, es lo que narra aquí. La última intención del relato no es "informar" al lector, sino comunicar con él en empatía profunda.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1162, '9788422679059', 'El sí de las niñas', 1, '2001', 147, NULL, 'media/core/9788422679059.jpeg', 1, '2023-04-10 08:50:47.157727', '2023-04-10 08:50:47.157727', 765, 41, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'Moratín, neoclásico por raciocinio y por criterio artístico, lleva en sí, por temperamento, los tiempos nuevos. En esta obra, justamente celebrada como la mejor de su producción, reivindica el derecho de los jóvenes al matrimonio por amor y no por imposición familiar. Desde un tono de bondad amable, «El sí de las niñas» es un alegato contra los métodos educativos de la época en los mismos inicios del siglo XIX, hecho por un autor dramático que, por ilustrado, trataba de educar desde las tablas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1163, '9788422661184', 'Obras Completas I. Poesía', 1, '1996', 844, NULL, 'media/core/9788422661184.jpg', 1, '2023-04-10 08:55:26.330239', '2023-04-10 08:55:26.330239', 766, 4, 6, 5, NULL, '', '05_02', NULL, 46, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1164, '9788422679011', 'Fuente Ovejuna', 1, '2000', 183, NULL, 'media/core/9788422679011.jpeg', 1, '2023-04-10 08:58:03.701209', '2023-04-10 08:58:03.701209', 767, 41, 2, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'En este drama, el protagonista es todo el pueblo de fuenteovejuna, con lo cual adquiere la obra una grandeza épica extraordinaria. Dicho pueblo, cansado de los atropellos del cruel comendador mayor de calatrava, Don Femán Gómez de Guzmán y de su gente de armas, se levanta contra el, asalta el castillo y le da muerte conjuntamente con sus allegados, arrojándolo por una ventana y arrastrando luego su cuerpo entre el vecindario triunfante. - La justicia llega al lugar, y mediante terribles tormentos, se esfuerza pr descubrir quien es el asesino del comendador, mas “todos a una” contestan: “Fuenteovejuna”, callando el nombre del culpable, que realmente fue frondoso por vengarse de los atropellos del comendador contra Laurencia, a quien ama. Los reyes católicos, que llegaron fuenteovejuna para hacer justicia, absuelven al pueblo y hacen que este, en adelante, no dependa del señorío de la nombrada orden de calatrava, sino de la propia corona.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1165, '9788422679035', 'El alcalde de Zalamea', 1, '2000', 189, NULL, 'media/core/9788422679035.jpeg', 1, '2023-04-10 09:00:28.390647', '2023-04-10 09:00:28.390647', 768, 41, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, '«El alcalde de Zalamea» es una de las obras más populares de Calderón de la Barca y contiene todos los grandes ingredientes de la literatura universal: venganza, pasión, crimen, honor, orgullo, justicia, lucha de clases... Esta universalidad unida a la maestría en la dramatización es lo que hace de esta obra publicada en 1651 un clásico imprescindible, un texto sorprendentemente actual pese a haber sido escrito hace más de tres siglos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1166, '9788422679042', 'El Criticón', 1, '2000', 948, NULL, 'media/core/9788422679042.jpeg', 1, '2023-04-10 09:03:44.428351', '2023-04-10 09:03:44.428351', 769, 1, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'Baltasar Gracián (1601-1658) es el maestro del estilo conceptista. Fue jesuita y alcanzó en su orden no sólo fama de gran predicador, sino también altos grados, pero cierta profanidad en sus escritos le acarreó contratiempos, amargando sus últimos años. El Héroe, El Discreto, El Político, Agudezay arte de ingenio son algunos de sus títulos famosos. Pero El Criticón es considerado unánimemente, a lo largo de los siglos, como su obra maestra. La primera parte apareció en 1651, en Zaragoza, bajo el semiseudónimo de Lorenzo Gracián; La segunda en 1653, y la tercera en 1657. El Criticón es una gran novela alegórico-filosófica. Sus dos principales personajes, Critilo y Andrenio, representan respectivamente el hombre civilizado y el hombre de la naturaleza. A lo largo de sus viajes y aventuras -transcurridos en las tres edades de la vida- ambos personajes, antes de parar en la isla de la Inmortalidad, encaran muchedumbre de parajes y no menor cantidad de temas. La influencia de El Criticón ha sido muy extensa y se mantiene viva. Por ello es Gracian uno de los espíritus españoles más universales.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1167, '9788422678953', 'Cantar de Mio Cid', 1, '2000', 1, NULL, 'media/core/9788422678953.jpeg', 1, '2023-04-10 09:06:14.136156', '2023-04-10 09:06:14.136156', NULL, 4, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'https://www.caminodelcid.org/cid-historia-leyenda/cantar-mio-cid/', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1168, '9788422667025', 'Satiricón // El asno de Oro (Apuleyo)', 1, '1998', 1, NULL, 'media/core/9788422667025.jpg', 1, '2023-04-10 09:10:55.709967', '2023-04-10 09:10:55.709967', 770, 1, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'A pesar de las dudas y dificultades que planean sobre la figura de Petronio, refinado aristócrata del tiempo de Nerón, y la fecha de elaboración de su obra, El Satiricón continúa siendo una de las composiciones de la Antigüedad que mayor interés despiertan en el lector moderno. Una vez superada la sensación de desconcierto que provoca el estado fragmentario en que nos ha llegado y las dificultades para reconstruir el argumento central, este único testimonio (junto con El asno de oro) del género novelesco en Roma nos depara la cautivadora y dinámica narración en primera persona de las peripecias de Encolpio, un pobre diablo que se busca la vida junto a sus amigos en un mundo lastrado por la corrupción y el libertinaje.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1169, '9788422667049', 'Eneida', 1, '1998', 331, NULL, 'media/core/9788422667049.jpeg', 1, '2023-04-10 09:13:41.982498', '2023-04-10 09:13:41.982498', 771, 1, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'La"Eneida,"el gran poema épico de Publio Virgilio Marón (Andes, Mantua, 70 a. C.-Bríndisi, 19 a. C.) que no pudo terminar, exalta los orígenes del pueblo romano a través de Eneas, héroe troyano de estirpe divina, y narra sus viajes y las guerras que hubo de sostener para establecer su linaje en el Lacio. La influencia de Homero es evidente y las referencias a la Ilíada y la Odisea, constantes; pero su finalidad concreta era conseguir que los romanos estuvieran orgullosos de serlo, que se sintieran herederos de los dioses y de los héroes que habían forjando su historia nacional, y, sobre todo, exaltar la figura de Augusto como materialización y eclosión del glorioso destino de Roma. A Virgilio nunca le satisfizo plenamente su obra; trató de destruirla y en su testamento prohibió su publicación, pero el emperador Augusto lo impidió', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1170, '9788422667032', 'La Roma legendaria', 1, '1998', 490, NULL, 'media/core/sin-imagen_2E4PWFQ.jpg', 1, '2023-04-10 09:16:38.667961', '2023-04-10 09:16:38.667961', 772, 11, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1171, '9788422678977', 'Romancero', 1, '2000', 260, NULL, 'media/core/9788422678977.jpeg', 1, '2023-04-10 09:19:16.798677', '2023-04-10 09:19:16.798677', NULL, 4, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'https://es.wikipedia.org/wiki/Romancero_viejo_(poes%C3%ADa)', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1174, '9788422666936', 'Odas y epodos', 1, '1997', 299, NULL, 'media/core/9788422666936_GMzdv4v.jpg', 1, '2023-04-10 09:32:15.173483', '2023-04-10 09:34:40.544725', 773, 4, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'Quinto Horacio Flaca es, junto con Virgilio, el segundo gran poeta de Roma, modelo y punto de referencia d elas generaciones siguientes. Su obra nos revela en igual medida un testimonio histórico concreto y un paradigma artístico de alcance universal. Las Odas y los Epodos de Horacio pueden integrarse desde el punto de vista de la teoría moderna, en el ámbito de la poesía lírica. Sin embargo, mientras las Odas siguen el modelo de Alceo, Safo, Anacreonte y Píndaro, los Epodos pueden considerarse como una poetización del insulto, aunque éste quede a veces en un segundo Plano.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1175, '9788422666967', 'Metamorfosis', 1, '1997', 428, NULL, 'media/core/9788422666967.jpg', 1, '2023-04-10 09:37:43.914714', '2023-04-10 09:37:43.914714', 774, 11, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'Las "Metamorfosis" constituyen una obra de madurez en la que Ovidio manifiesta toda su experiencia acumulada basada en una amplia tradición elegíaca, lírica y trágica. En las "Metamorfosis", Ovidio explica la historia de casi 250 mitos y leyendas de la Antigüedad romana y sus diversas transformaciones. En ella aparecen transformaciones de dioses, de animales y de seres inanimados, pero no cabe duda de que las metamorfosis más importantes de toda la obra las sufren los seres humanos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1176, '9788422666998', 'Farsalia', 1, '1998', 310, NULL, 'media/core/9788422666998.jpg', 1, '2023-04-10 09:46:08.964327', '2023-04-10 09:46:08.964327', 775, 4, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'Considerada la epopeya latina más grandiosa después de la «Eneida» de Virgilio (LB 1194), la FARSALIA es la composición que ha valido fama universal a Marco Anneo LUCANO (39-65), cuya vida efímera se vio truncada por la inquina de Nerón y el fracaso de la conspiración de Pisón. Dividida en diez cantos, es un poema épico inconcluso -se interrumpe en los avatares de César junto a Cleopatra en Egipto- dedicado a relatar la guerra civil entre Julio César y Pompeyo, que tuvo en la batalla entablada cerca de Farsalo un desenlace fatal para el bando de este último, siendo respecto a los anteriores poemas épicos uno de sus rasgos más llamativos, determinado por la corriente estoica en que se inscribe (no en balde Séneca, tío del autor, fue uno de sus máximos representantes), que no da cabida a los dioses tradicionales, dejando entrever tan sólo la presencia de la Fortuna. Acreedora de diferente suerte crítica según las épocas -siempre ha sido más valorada por movimientos como el barroco y el romanticismo, que han colocado el sentimiento y la pasión por encima de los preceptos y los cánones-, en ella, como dijera en su día M. Dolç, «la palabra deja de ser medio de expresión y de valoración estética, para convertirse en una sensación de color, sonido y sabor». El presente volumen recupera la magnífica edición hecha en su día por SEBASTIÁN MARINER, sin incorporar más novedad que una sucinta nota bibliográfica que recoge las últimas aportaciones al sugerente texto del ilustre poeta cordobés.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1177, '9788422666981', 'Poesías // Elegías (Propercio)', 1, '1998', 1, NULL, 'media/core/9788422666981.jpeg', 1, '2023-04-10 09:49:34.715107', '2023-04-10 09:49:34.715107', 776, 4, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, '', 'https://es.wikipedia.org/wiki/Propercio');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1178, '9788422666950', 'Tratados', 1, '1997', 215, NULL, 'media/core/9788422666950.jpeg', 1, '2023-04-10 09:51:27.802030', '2023-04-10 09:51:27.802030', 777, 2, 6, 5, 'Clásicos latinos', '', '05_02', NULL, 5, 'Los Tratados morales son pequeñas obras, no propiamente diálogos sino ensayos sobre problemas de moral. Los temas abordados en ellos son muy variados, desde cómo ha de ser la clemencia de los gobernantes, hasta cómo debe el sabio aprovechar su tiempo de ocio: De la Providencia, De la firmeza del sabio, De la felicidad, De la vida retirada o del ocio, De la serenidad del alma, De la brevedad de la vida, De la clemencia y, además, la Consolación a Polibio constituyen un libro en el que Seneca, el más ilustre exponente del estoicismo de la epoca imperial, nos muestra su filosofía del vir fortis, del dominio de sí mismo, de la fidelidad a la propia conciencia y de la entrega y servicio a los demás.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1179, '9788422679066', 'Don Juan Tenorio', 1, '2000', 1, NULL, 'media/core/9788422679066.jpeg', 1, '2023-04-10 09:54:55.504906', '2023-04-10 09:54:55.504906', 778, 1, 6, 5, 'Clásicos españoles', '', '05_02', NULL, 5, 'Don Juan Tenorio es el personaje más célebre del teatro español. La historia de este burlador de mujeres comienza en los días de Carnaval y acaba en el Día de Difuntos. Don Juan es un seductor que se mofa de todos los valores sociales establecidos. Pero su vida cambiará al conocer a doña Inés. Gracias a su amor, el alma de don Juan se salvará de las llamas del infierno. En esta adaptación destaca la fidelidad al sentido de la obra original de José Zorrilla y sus principales rasgos literarios. Esta fidelidad, tanto en el texto como en las magníficas ilustraciones que lo acompañan, contribuye a mantener la ambientación histórica de este clásico universal.Existe una guía de lectura de descarga gratuita en la que, capítulo a capítulo, se ofrece la posibilidad de analizar la obra desde diferentes puntos de vista a través de las actividades.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1180, '8422652102', 'Artículos', 1, '1993', 343, NULL, 'media/core/8422652102.jpg', 1, '2023-04-10 09:59:28.598300', '2023-04-10 09:59:28.598300', 779, 17, 6, 5, NULL, '', '05_02', NULL, 282, 'En esta edición de Artículos de Mariano José de Larra se presentan 8 de sus artículos periodísticos más importantes en función de su difusión, fama, sentido del humor, importancia del tema tratado e información política y social que aportan sobre la época del autor. Presentados en orden cronológico, lo que facilita el estudio de la evolución literaria de Larra y de su propia personalidad, estos artículos de costumbres ofrecen múltiples juicios y análisis dolorosos e implacables sobre la realidad española del momento (noviembre 1832-diciembre 1836), en un estilo que es una mezcla entre lo discursivo, próximo al ensayo, y la narración o diálogo. que a veces recuerdan al cuento. Se incluye un cuaderno guía del profesorado.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1181, '9788422662747', 'El elegido', 1, '1997', 320, 'Der Erwählte', 'media/core/9788422662747.jpeg', 1, '2023-04-10 10:02:52.847555', '2023-04-10 10:02:52.847555', 361, 1, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 93, 'El Elegido es una gran novela sobre las bajas pasiones y el arrepentimiento. Thomas Mann se sirve de la figura de Gregorius, el papa Gregorio V, y de la galería de personajes que pulularon a su alrededor para mostrar la podredumbre de la Iglesia de su tiempo, pero sobre todo para explorar el alma humana. Junto a una convincente recreación de la época, lo más atractivo de esta gran novela de Mann son los pensamientos, sentimientos, las dudas y los conflictos personales a los que enfrenta a sus personajes.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1182, '9788422662693', 'La máscara de Apolo', 1, '1990', 430, 'The Mask of Apollo', 'media/core/9788422662693.jpg', 1, '2023-04-10 10:05:31.899940', '2023-04-10 10:05:31.899940', 173, 1, 2, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 93, 'A través de la mirada del actor Nicérato, que viaja por la Grecia clásica en el siglo IV a.C., se asiste a ese fascinante mundo en el que se cruzan Apolo y Platón y los acontecimientos más importantes de la historia antigua.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1183, '9788422662778', 'Reina de Trovadores', 1, '1997', 429, 'Die Löwin von Aquitanien', 'media/core/9788422662778.jpg', 1, '2023-04-10 10:09:03.385425', '2023-04-10 10:09:03.385425', 781, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 48, 'Precursora de una renovación cultural y estética que marcó el futuro de Europa, Leonor de Aquitania, imponente en su papel de reina y de mujer, reúne todos los requisitos que hacen de una figura histórica un referente para sucesivas generaciones. Nieta de Guillermo IX de Aquitania, y esposa de Luis VII de Francia y más tarde de Enrique II de Inglaterra, Leonor fue mucho más que la mujer ambiciosa que participó en una cruzada y luchó toda su vida por controlar los hilos del poder político. Musa de trovadores, se rodeó de una pléyade de músicos y poetas que conformaron unos ideales de vida desconocidos en el siglo XII.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1184, '9788422662754', 'Los hombres del mar', 1, '1996', 405, 'Die Männer vom Meer. Nordland Saga', 'media/core/9788422662754.jpeg', 1, '2023-04-10 10:12:45.209701', '2023-04-10 10:12:45.209701', 782, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 93, 'Secuestrado por un soldado cerca de la ciudad danesa de Haithabu, el joven Björn Hasenscharte emprenderá una larga odisea en la que no faltan héroes, piratas vikingos, magos, comerciantes y guerreros. Una extraordinaria saga del siglo X.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1185, '9788422662792', 'El romance de Leonardo', 1, '1998', 729, 'Leonardo da Vinci. Vokressie bogie', 'media/core/9788422662792.jpeg', 1, '2023-04-10 10:19:26.338065', '2023-04-10 10:19:26.338065', 783, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 5, 'Mediante la figura de Leonardo da Vinci, Merezhkovski nos ofrece un soberbio retrato de toda una época de esplendor artístico y científico. Desde sus inicios como arquitecto al servicio de Ludovico Sforza a sus enfrentamientos con Miguel Ángel y Rafael o sus pugnas con papas, príncipes y cortesanos de todo tipo, la vida de Leonardo da Vinci es un apasionante recorrido por la Italia del siglo XVI. Edición de bolsillo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1186, '9788422662730', 'Yo, Zenobia, Reina de Palmira', 1, '1995', 315, 'Moi, Zenobia, reine de Palmyre', 'media/core/9788422662730.jpeg', 1, '2023-04-10 10:23:26.460660', '2023-04-11 10:37:41.443411', 784, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 48, 'Zenobia convirtió Palmira en una hermosa y refinada ciudad, pensando en convertirla en la capital de un reino árabe que habría de suceder a Roma en el gobierno del mundo. Pero el emperador Aureliano puso fin a su sueño. Esta novela es el relato de la vida de una mujer valerosa que fue capaz de desafiar a las legiones romanas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1187, '9788422662679', 'La hja de Homero', 1, '1983', 265, 'Homer''s Daughter', 'media/core/9788422662679.jpg', 1, '2023-04-10 10:26:05.056623', '2023-04-10 10:26:05.056623', 728, 16, 2, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 93, 'Esta original novela de Robert Graves narra la historia de una notable princesa italiana, Nausícaa, que vivió setecientos años antes de Cristo y salvó el trono de su padre de las ambiciones de los usurpadores y a dos de sus hermanos de una muerte violenta, librándose ella misma de un desagradable matrimonio gracias a la inesperada ayuda de un noble cretense que había naufragado en las costas de Sicilia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1189, '9788422662785', 'El últmio templario', 1, '1995', 447, 'The Imageof Our Lord', 'media/core/9788422662785.jpg', 1, '2023-04-10 10:53:10.380176', '2023-04-10 10:53:10.380176', 785, 16, 2, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 74, 'La Inquisición no ha conseguido arrancar el secreto mejor guardado de la historia al único superviviente templario. Nicolás de Lirey será el encargado de la investigación, pero para lograr su objetivo deberá sortear las trampas tendidas por el Vaticano, el rey Felipe el Hermoso y una oscura secta llamada Opus Christi.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1190, '9788481098778', 'Trilogía americana (pastoral Americana // Me casé con una comunista // La mancha humana)', 1, '2011', 1212, 'American Pastoral // Married a Communist // The Human Stain', 'media/core/9788481098778.jpeg', 1, '2023-04-10 10:57:19.240919', '2023-04-10 10:57:19.240919', 786, 1, 6, 5, NULL, '', '05_02', NULL, 46, 'Este volumen reúne por primera vez en castellano las tres novelas que componen la Trilogia americana de Philip Roth: Pastoral americana (1997), Me case con un comunista (1998) y La mancha humana (2000). Las tres tienen un mismo protagonista, Nathan Zuckerman, quizá el personaje central de la novelística de Roth, alter ego del escrito o "alter mente" como el mismo lo llama. A traves de sus ojos, se reflejan tres momentos de la realidad americana posterior a la Segunda Guerra Mundial, las decadas de los sesenta, los cincuenta y los noventa, respectivamente.En Pastoral americana, Zuckerman cuenta la historia de Swede Levov, encarnación del sueño americano: atleta legendario en sus años de estudiante, casado con una antigua Miss Nueva Jersey y heredero de la fábrica de su padre. Hasta que un día de 1968, la America idílica por la que luchó se le hunde.Me case con un comunista es la historia de Iron Rinn, hombre hecho a sí mismo, que de trabajador en una mina llega a ser un famoso actor radiofónico. Soldado en la Segunda Guerra Mundial, defensor de los derechos oprimidos, acaba en la lista negra y sin empleo denunciado por su mujer durante los furiosos años del macartismo.Finalmente, La mancha humana muestra cómo Coleman Silk, decano de universidad, ve su reputación y su carrera', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1191, 'ARG-11723', 'El vino del estío', 5, '1972', 221, 'Dandelion Wine', 'media/core/ARG-11723.jpeg', 1, '2023-04-10 11:07:32.658204', '2023-04-10 11:07:32.658204', 787, 1, 6, 5, NULL, '', '05_02', NULL, 210, 'En tres prodigiosos meses, Douglas Spaulding observa, escucha, saborea las sorpresas rituales de un verano: el descubrimiento de la vida y la muerte, el últimos tranvía, la limpieza de las alfombras, la aparición de las hamacas en los porches, la cosecha del vino del estío... pero tambien máquinas y magias extraordinarias: la Máquina de la Felicidad que casi destruye la felicidad de su inventor; la Máquina Verde, que pasea a dos viejas señoras por las calles del pueblo; la Máquina del Tiempo en el cuerpo de un viejo coronel; la Mujer Máquina, la terrible y fabulosa Madame Tarot...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1192, '9788422662709', 'El etrusco', 1, '1994', 589, 'Turns, Kuolematon', 'media/core/9788422662709.jpeg', 1, '2023-04-10 11:10:09.652516', '2023-04-19 08:11:23.426560', 729, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 93, 'Como el héroe troyano Eneas, el protagonista de esta novela, Lario Turmo, está predestinado a superar las mil y una pruebas que Afrodita pondrá en su largo peregrinar por Asia Menor y Grecia. Las guerras contra el poder de Roma, así como las intrigas y los celos, afligen su existencia, pero al mismo tiempo le dan la fuerza necesaria para reconocerse como un escogido de los dioses. Quizá desde Homero nadie lograba convertir el viaje en una aventura narrativa tan fascinante como Mika Waltari en El Etrusco.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1193, '9788422662686', 'Faraón', 1, '1996', 815, 'Faraon', 'media/core/9788422662686.jpg', 1, '2023-04-10 11:13:19.284316', '2023-04-10 11:13:19.284316', 788, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 5, 'La trama de Faraón se desarrolla en el siglo XI a. n. e., época del hijo del Sol, el inmortal Ramsés XIII. Un magnífico fresco histórico que muestra la enconada lucha entre el poder real y la casta sacerdotal en defensa de sus privilegios. Los clases sociales más importantes del imperio en decadencia ―el alto y el bajo clero, el ejército, los mercaderes, la nobleza y el campesinado― mostrarán sus aspiraciones y limitaciones en medio de un feroz combate entre el sumo sacerdote Herhor y Ramsés XIII.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1194, '9788422662726', 'Diario de Nerón', 1, '1995', 467, 'Journal de Nerón', 'media/core/sin-imagen_V1lYLHM.jpg', 1, '2023-04-10 11:16:28.573519', '2023-04-10 11:16:28.573519', 789, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 93, 'Basándose en una completa documentación, el autor recupera la figura de un Nerón formidablemente humano y empeñado en levantar el Imperio de la Belleza frente a la incomprensión de cuantos lo rodean', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1195, '9788422662761', 'Gengis Kan. EL soberano del cielo', 1, '1994', 731, 'Ruelr of the Sky. A novel of Genghis Khan', 'media/core/9788422662761.jpeg', 1, '2023-04-10 11:20:14.138293', '2023-04-10 11:20:14.138293', 790, 16, 6, 5, 'Momentos estelares de la Historia', '', '05_02', NULL, 93, 'Guerrero infatigable, audaz estratega, genial visionario... La vida de Gengis Kan ha sido fascinante. Sus extraordinarias hazañas lo han convertido en un héroe casi legendario, aún recordado por el pueblo mongol que bajo su mando alcanzó su máximo apogeo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1196, '9788417552664', 'El club de lectura de David Bowie', 1, '2019', 287, 'The Bowie Book Club', 'media/core/9788417552664.jpg', 1, '2023-04-10 11:25:17.934739', '2023-04-10 11:25:17.934739', 791, 31, 6, 5, NULL, '', '05_02', NULL, 283, 'En el mundo pasan tantas cosas, y tan rápido, que no tienes tiempo ni de leer. Se publican tantos libros, tantísimos, que no sabes cuál elegir. Tres años antes de morir, David Bowie reveló los 100 libros que habían forjado su carrera y cambiado su forma de ver el mundo. Este es su legado y una invitación irresistible a sumergirte de verdad en los libros y en su poder para transformarnos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1197, '9788416638802', 'Sobre los huesos de los muertos', 2, '2019', 235, 'Prowadz swój plug przez kosci umarlych', 'media/core/9788416638802.jpg', 1, '2023-04-10 11:37:37.724699', '2023-04-10 11:37:37.724699', 792, 1, 2, 5, 'Nuevos Tiempos', '', '05_02', NULL, 16, 'Olga Tokarczuk, una de las voces más vigorosas de la narrativa polaca contemporánea, despliega en este arrebatador thriller metafísico todas las contradicciones del alma humana.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1198, '8427298641', 'Ocho casos de Poirot', 1, NULL, 187, 'The Underdog and other Stories', 'media/core/8427298641.jpeg', 1, '2023-04-10 11:41:31.092860', '2023-04-10 11:41:31.092860', 793, 14, 6, 5, NULL, '', '05_02', NULL, 135, 'Una selección excelente de intrincados misterios.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1199, '8427298420', 'Poirot investiga', 1, NULL, 173, 'Poirot investigates', 'media/core/8427298420.jpeg', 1, '2023-04-10 11:43:56.864089', '2023-04-10 11:43:56.864089', 793, 14, 6, 5, NULL, '', '05_02', NULL, 135, 'Tras los famosos casos de Styles y del Campo de Golf, la fama de Poirot crece día a día, llegando a convertirse en el detective predilecto de la buena sociedad británica. A esta época pertenecen estos relatos, como ''La aventura de la tumba egipcia''.', '');
