INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1240, '9788498387544', 'Harry Potter y el legado maldito', 1, '2016', 321, 'Harry Potter and the Cursed Child - Parts One and Two', 'media/core/9788498387544.jpg', 1, '2023-04-11 10:09:00.877376', '2025-06-12 11:22:13.202844', 799, 41, 6, 2, NULL, '', '0105', 'Pates uno y dos', 29, 'DIECINUEVE AÑOS DESPUÉS...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1241, '9788466334778', 'Tiempos de hielo', 1, '2016', 365, 'Temps glaciaires', 'media/core/9788466334778.jpg', 1, '2023-04-11 10:12:19.981477', '2023-04-11 10:12:19.981477', 5, 14, 6, 5, 'Debolsillo', '', '05_03', 'Comisario Adamsberg 8', 16, 'Alice Gauthier, una respetable profesora de matemáticas de sesenta y seis años, aparece muerta en su bañera. Todo apunta a un suicidio, pero ciertos detalles, como un extraño signo trazado en el lugar del suceso, hacen pensar que quizá haya algo más detrás de su muerte, por lo que el caso es derivado al equipo de la Brigada Criminal del comisario Adamsberg.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1242, '9788466331180', 'Bajo los vientos de Neptuno', 1, '2015', 489, 'Sous les vents de Neptune', 'media/core/9788466331180.jpg', 1, '2023-04-11 10:14:27.008205', '2023-04-11 10:34:27.856822', 5, 14, 6, 5, 'Debolsillo', '', '05_03', 'Comisario Adamsberg 4', 16, 'El comisario Adamsberg deberá enfrentarse en esta ocasión al caso más personal de toda su carrera y, por lo tanto, tambien al más peligroso.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1243, '9788466331197', 'La tercera virgen', 1, '2015', 479, 'dans les bois éternels', 'media/core/9788466331197.jpg', 1, '2023-04-11 10:16:30.218162', '2023-04-11 10:34:55.236878', 5, 14, 6, 5, 'Debolsillo', '', '05_03', 'Comisario Adamsberg 5', 16, 'El comisario Adamsberg deberá enfrentarse en esta ocasión al caso más personal de toda su carrera y, por lo tanto, tambien al más peligroso.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1244, '9788466331203', 'Un lugar incierto', 1, '2015', 345, 'Un lieu incertain', 'media/core/9788466331203.jpg', 1, '2023-04-11 10:18:24.486119', '2023-04-11 10:35:26.883023', 5, 14, 2, 5, 'Deb', '', '05_03', 'Comisario Adamsberg 6', 16, 'Diecisiete pares de zapatos con sus respectivos pies cercenados dentro y alineados mirando a un antiguo cementerio de Londres aparecen un día sin ninguna explicación.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1245, '9788466346382', 'Cuando slae la reclusa', 1, '2019', 402, 'Quand sort la recluse', 'media/core/9788466346382.jpg', 1, '2023-04-11 10:20:37.667993', '2023-04-11 10:20:37.667993', 5, 14, 6, 5, 'Debolsillo', '', '05_03', 'Comisario Adamsberg 9', 16, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1246, '9788466331111', 'Los que van a morir te saludan', 1, '2015', 238, 'Ceux qui vont mourir te saluent', 'media/core/9788466331111.jpg', 1, '2023-04-11 10:23:32.966759', '2023-04-11 10:23:32.966759', 5, 14, 6, 5, 'Debolsillo', '', '05_03', NULL, 16, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1247, '9788466331210', 'El Ejército Furioso', 1, '2015', 361, 'L''Armée furieuse', 'media/core/9788466331210.jpg', 1, '2023-04-11 10:25:41.422784', '2023-04-11 10:25:41.422784', 5, 14, 6, 5, 'Debolsillo', '', '05_03', 'Comisario Adamsberg 7', 16, 'Un nuevo caso en el que los actos criminales más morbosos se mezclan con magia, mito y superstición. Un nuevo caso para el comisario Adamsberg.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1248, '9788466331234', 'Fluye el Sena', 1, '2015', 135, 'Coule la Seine', 'media/core/9788466331234.jpg', 1, '2023-04-11 10:27:45.053707', '2023-04-11 10:39:16.134328', 5, 14, 6, 5, 'Debolsillo', '', '05_03', 'Comisario Adamsberg (Tres casos)', 16, 'Tres novelas del infalible comisario Adamsberg que tienen como escenario la ciudad de París.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1249, 'BU12', 'Vercingétorix', 1, '1971', 234, 'Vercingétorix', 'media/core/BU12.jpg', 1, '2023-04-11 10:31:06.676875', '2023-04-11 10:31:06.676875', 800, 16, 6, 5, NULL, '', '05_03', NULL, 40, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1250, '8434545055', 'Momentos estelares de la Ciencia', 1, '1984', 142, 'Breakthroughs in Science', 'media/core/8434545055.jpeg', 1, '2023-04-11 10:33:16.133478', '2023-04-11 10:33:16.133478', 341, 15, 6, 5, NULL, '', '05_03', NULL, 3, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1251, '9788498150308', 'La saga / Fuga de J.B.', 1, '2005', 701, NULL, 'media/core/9788498150308.jpeg', 1, '2023-04-12 06:08:49.477596', '2023-04-12 06:08:49.477596', 801, 1, 6, 5, 'Clásicos españoles', '', '05_04', NULL, 264, 'La saga/fuga de J.B. es la historia de una ciudad imaginaria, Castroforte del Baralla, un lugar mítico y de gran complejidad fantástica donde sus habitantes se debaten entre la irrealidad y la tradición. La novela de más impacto de Torrente Ballester, que rompió con todos los moldes del género en España, apuntando con genial maestría hacia la técnica más innovadora de la vanguardia de calidad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1252, '9788498150018', 'El Árbol de la ciencia', 1, '2004', 285, NULL, 'media/core/9788498150018.jpg', 1, '2023-04-12 06:11:45.144041', '2023-04-12 06:11:45.144041', 802, 1, 6, 5, 'Clásicos españoles', '', '05_04', NULL, 264, 'Publicada en 1911, El árbol de la ciencia (para el propio Pío Baroja «el libro más acabado y completo de todos los míos») es la obra en la que la técnica narrativa del novelista -el gusto por la sucesión ininterrumpida de acontecimientos, la abundancia de personajes secundarios, la hábil articulación de situaciones críticas, el impresionismo descriptivo, el rápido trazo de caracteres- alcanza su mayor eficacia, así como aquella en que, en palabras de Azorín, se halla «mejor que en ningún otro libro el espíritu de Baroja».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1253, '8474612217', 'Aventuras de Sherlock Holmes', 1, '1983', 185, NULL, 'media/core/8474612217.jpeg', 1, '2023-04-12 06:15:18.014400', '2023-04-12 06:15:18.014400', 501, 1, 6, 5, 'Grandes genios de la Literatura Universal', '', '05_04', 'Vol 18', 234, 'Sherlock Holmes había dado ya muestras de su genio en Estudio en Escarlata y en El signo de los cuatro, pero los lectores no se dieron cuenta de su genialidad. Entonces a Conan Doyle —¿a Watson?— se le ocurrió la brillante idea de pasear al detective por una serie de relatos cortos. Empezó publicándolos en la revista Strand en julio de 1891. En octubre, cuando sólo se habían publicado tres historias, los editores le imploraban más aventuras de Holmes, el público agotaba las ediciones y Doyle subía sus tarifas. La presión del público era tal, que antes de terminar los doce relatos que componen este volumen, el autor empezó a acariciar la idea de acabar con su criatura.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1254, '8402059112', 'Escritos políticos 1914/1932', 2, '1979', 249, 'Politik des Gewissens, die Politischen Schriften 1914 - 1932', 'media/core/sin-imagen_LPSnccc.jpg', 1, '2023-04-12 06:19:49.097310', '2023-04-12 06:19:49.097310', 803, 2, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1255, '8402056105', 'El caminante', 1, '1978', 105, 'Wanderung', 'media/core/8402056105.jpg', 1, '2023-04-12 06:22:32.690627', '2023-04-12 06:22:32.690627', 803, 28, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Hermann Hesse escribió algunas de las prosas y poesías más hermosas de su obra inspirándose en sus paseos por la naturaleza. El caminante es un documento enriquecedor de una de las fases más importantes de su evolución: su distanciamiento de los rituales de la existencia y la seguridad burguesas, el paso de la vida activa a la vida contemplativa. Ilustrado con acuarelas a color.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1256, '9788401429040', 'Leyendas medievales', 2, '1987', 224, 'Geschichten aus den Mittelalter', 'media/core/sin-imagen_pi1TXpF.jpg', 1, '2023-04-12 06:27:25.455625', '2023-04-12 06:27:25.455625', 803, 29, 6, 5, NULL, '', '05_04', NULL, 17, '"Leyendas Medievales" es una rareza de Hermann Hesse. No es un libro propiamente de él, sino que es más una recopilación y traducción de su parte, lo cual no quita poder ganar un acercamiento a los intereses del mismísimo autor. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1257, '8402005284', 'Siddharta', 15, '1977', 176, 'Siddharta', 'media/core/8402005284.jpg', 2, '2023-04-12 06:30:39.466790', '2023-09-20 11:02:30.032770', 803, 1, 6, 5, NULL, '', '05_04', NULL, 126, 'Esta novela, ambientada en la India tradicional, relata la vida de Siddhartha, un hombre para quien el camino de la verdad pasa por la renuncia y la comprensión de la unidad que subyace en todo lo existente. En sus páginas, el autor ofrece todas las opciones espirituales del hombre.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1258, '8420610445', 'El lobo estepario', 14, '1979', 222, 'Der Steppenwolf', 'media/core/8420610445.jpg', 1, '2023-04-12 06:34:37.000631', '2023-04-12 06:34:37.000631', 803, 1, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'Encrucijada de todas las obsesiones e intuiciones de Hermann Hesse (1877-1962) y exponente de su singular talento para el relato, El lobo estepario se inscribe dentro del empeño, patente a lo largo de toda su obra, por iluminar la zona oscura de la condición humana a fin de poner al descubierto su carga trágica y su incierto destino.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1259, '842061095X', 'Bajo las ruedas', 8, '1978', 168, 'Unterm Rad', 'media/core/842061095X.jpg', 2, '2023-04-12 06:37:29.480926', '2023-09-20 11:07:25.841437', 803, 1, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'Publicada en 1906, "Bajo las ruedas" es una prodigiosa recreación del mundo de la adolescencia, pero en ella Hermann Hesse (1877-1962) formula también una severa acusación contra los sistemas educativos que se imponen a costa de la imaginación y del cultivo armónico de las facultades espirituales, emocionales y físicas. Separado del medio de su infancia y obligado por padres y profesores a una agotadora preparación para el ingreso en un seminario, su protagonista, Hans Giebenrath, logra finalmente su objetivo, pero al elevado precio de perder primero su sensibilidad y, más tarde, su equilibrio emocional.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1260, '8420613096', 'El Aleph', 9, '1980', 183, NULL, 'media/core/8420613096.jpg', 1, '2023-04-12 06:40:46.387653', '2023-04-12 06:40:46.387653', 804, 29, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'Este volumen reúne dieciocho relatos de Jorge Luis Borges, entre ellos quizá los más elogiados y repetidamente citados. Tanto «El inmortal» como «Los teólogos», «Deutsches Requiem» y «La espera» muestran las posibilidades expresivas de la «estética de la inteligencia» borgiana, inimitable fusión de mentalidad matemática, profundidad metafísica y captación poética del mundo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1261, '8432226262', 'El reino de este mundo', 8, '1980', 145, NULL, 'media/core/8432226262.jpg', 1, '2023-04-12 06:48:59.461905', '2023-04-12 06:48:59.461905', 805, 1, 6, 5, 'Biblioteca Breve', '', '05_04', NULL, 13, 'Una de las obras maestras del escritor cubano, El reino de este mundo narra, a través de la voz del esclavo negro Ti Noël, el tránsito que sufrió Haití al pasar a convertirse, de colonia francesa gobernada por blancos, en una nación negra regida por el primer monarca coronado del Nuevo Mundo. En una atmósfera lujuriosa y sensual que delata el barroquismo y el realismo mágico de su autor, este relato nos permite conocer las rebeliones de Mackandal, las aventuras de Pauline Bonaparte, así como la tiranía del rey negro Henri Christophe.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1262, '11723-1976', 'El lazarillo de Tormes', 1, '1976', 89, NULL, 'media/core/sin-imagen_cxeiyO2.jpg', 1, '2023-04-12 06:53:20.827412', '2023-04-12 06:53:20.827412', NULL, 1, 6, 5, 'Biblioteca Antártica Pocket', '', '05_04', NULL, 288, 'https://es.wikipedia.org/wiki/La_vida_de_Lazarillo_de_Tormes', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1263, '8429710868', 'Oferiu flors als rebels que fracassaren', 7, '1980', 172, NULL, 'media/core/8429710868.jpg', 1, '2023-04-12 06:58:12.767526', '2023-04-12 06:58:12.767526', 806, 1, 6, 5, 'Col.lecció universal de butxaca El Cangur', '', '05_04', NULL, 2, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1264, '8426440055', 'El cuarto de Jacob', 1, '1980', 225, 'Jacob''s Room', 'media/core/8426440055.jpg', 1, '2023-04-12 07:01:20.772560', '2023-04-12 07:01:20.772560', 807, 1, 6, 5, 'Ediciones de bolsillo', '', '05_04', NULL, 21, 'La novela en la que Virginia Woolf descubrió su verdadero estilo e inició la gran revolución de la escritura modernista.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1265, '8420600687', 'Elogio de la locura', 1, '1984', 180, NULL, 'media/core/8420600687.jpeg', 1, '2023-04-12 07:04:25.807397', '2023-04-12 07:04:25.807397', 808, 2, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'Desiderio Erasmo, más conocido como Erasmo de Rotterdam (1467-1536), uno de los personajes más influyentes en la Europa de su época, escribió Elogio de la locura en un contexto social y cultural convulsionado por la lucha entre la tradición medieval y las nuevas premisas que apuntaba el humanismo. A lo largo de esta obra que Erasmo dedica a su amigo Tomás Moro, parece querer convencer al mundo de que la Insensatez, la Estulticia o la Locura son el origen de todas las bondades, diversiones y deleites que el ser humano disfruta. Acompañadas de la ebriedad, la adulación, la pereza, la ignorancia..., reclama sus méritos con desfachatez y gracia, en un discurso impregnado de ironía. Pero ¿qué pretende Erasmo con este "elogio"? ¿Qué esconde? ¿En qué consiste este juego de ingenio? ¿Es todo una burla? En Elogio de la locura Erasmo crea un espejismo seductor y contundente que, impregnado del humanismo cristiano que preconizaba, le sirve de excusa para describir la necedad del mundo y arremeter a dentelladas contra todo lo humano y lo divino. Erasmo supo expresar con gran talento literario y con amplísimo saber los cansancios, las esperanzas, las dudas, las ambigüedades de una época turbada e incierta, pero son tantos los juicios contradictorios que expone en su obra, tan diversas las actitudes que despertó entre los hombres más insignes de su tiempo, que sus contemporáneos no llegaron a concluir nunca una síntesis final de su pensamiento.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1266, '8432301787', 'Movimientos socieales en Andalucía (1820 - 1936)', 1, '1976', 176, NULL, 'media/core/8432301787.jpeg', 1, '2023-04-12 07:07:54.462858', '2023-04-12 07:07:54.462858', 809, 15, 6, 5, 'Estudios de Historia Contemporánea', '', '05_04', NULL, 84, 'Movimientos sociales en Andalucía (1820-1936), de Antonio Mª Calero, intenta ofrecer una síntesis de los conocimientos actuales sobre el tema, al tiempo que plantea una serie de problemas e hipótesis que puedan contribuir a explicar el movimiento obrero andaluz de los dos últimos siglos. Para establecer con el máximo rigor posible los hechos sociales se insiste en el análisis cuantitativo, rectificando de paso una serie de lugares comunes a los que ha sido tan propensa la historiografía sobre temas andaluces. Junto al movimiento campesino se da especial relieve al minero y urbano, casi desconocidos hasta el presente, y de gran importancia en la evolución de la sociedad andaluza; todo ello buscando las características diferenciadoras específicamente regionales. Como hipótesis básica se propone el que Andalucía es una región colonizada: por la nobleza de origen castellano en el Antiguo Régimen, la oligarquía terrateniente en el sistema liberal y el capital extranjero en minas e industria, situación mantenida por el Estado de la Restauración. En el análisis de los diversos fenómenos se intenta articular esta realidad de base con la evolución de la coyuntura económica y los cambios en el sistema político, sin desdeñar -como no desdeñaban los dirigentes obreros coetáneos- las posibles peculiaridades culturales del pueblo andaluz.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1267, 'B2216', 'Ritmo lento', 1, '1969', 314, NULL, 'media/core/B2216.jpg', 1, '2023-04-12 07:10:53.886982', '2023-04-12 07:10:53.886982', 103, 1, 6, 5, 'Biblioteca Breve de bolsillo', '', '05_04', NULL, 13, 'Una novela ambiciosa que formula una pregunta sobre el valor de las ataduras, del compromiso afectivo, y la posibilidad de soñar un futuro fuera de los límites del racionalismo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1268, 'B18512', 'A la hora que cierran los bares', 1, '1998', 96, NULL, 'media/core/B18512.jpg', 1, '2023-04-12 07:16:23.641462', '2023-04-12 07:16:23.641462', 810, 29, 6, 5, NULL, '', '05_04', NULL, 289, 'Ocho relatos cortos de Soledad Puértolas:A la hora en que cierran los baresEl origen del deseoLa llamada nocturnaLa orilla del DanubioLa vida ocultaVentajas de la primera personaEn el límite de la ciudadLa corriente del golfo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1269, 'B35123', 'Las palabras del mundo', 1, '1998', 93, NULL, 'media/core/B35123.jpg', 1, '2023-04-12 07:20:01.077833', '2023-04-12 07:20:01.077833', 811, 27, 6, 5, NULL, '', '05_04', NULL, 289, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1270, 'B36665', 'Profesoón peligrosa', 1, '1998', 96, NULL, 'media/core/B36665.jpg', 1, '2023-04-12 07:24:56.417058', '2023-04-12 07:24:56.417058', 812, 27, 6, 5, 'Escritores españoles de hoy', '', '05_04', NULL, 289, '', '');
