INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1272, 'B36676', 'Reflexiones de Robinsón ante un bacalao', 1, '1998', 95, NULL, 'media/core/B36676.jpg', 1, '2023-04-12 07:31:32.611088', '2023-04-12 07:31:32.611088', 814, 27, 6, 5, 'Escritores españoles de hoy', '', '05_04', NULL, 289, 'Robinsón es un sacerdote corrupto en excedencia que se dedica al blanqueo de dinero de la Iglesia. Sus cenas y comidas son tan importantes como sus negocios y ya que no hace mucho caso de algún mandamiento, tampoco lo hace respecto al sexo: Muriel es su pareja.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1273, 'B36674', 'El tiburón y el ángel', 1, '1998', 96, NULL, 'media/core/B36674.jpg', 1, '2023-04-12 07:35:13.064277', '2023-04-12 07:35:13.064277', 815, 27, 6, 5, 'Escritores españoles de hoy', '', '05_04', NULL, 289, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1274, 'B35122', 'Alba, reina de las avispas', 1, '1998', 95, NULL, 'media/core/B35122.jpg', 1, '2023-04-12 07:37:52.136267', '2023-04-12 07:37:52.136267', 816, 27, 6, 5, 'Escritores españoles de hoy', '', '05_04', NULL, 289, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1275, 'B33094', 'El cuento de Sirena', 1, '1998', 96, NULL, 'media/core/B33094.jpeg', 1, '2023-04-12 07:40:15.642473', '2023-04-12 07:40:15.642473', 801, 27, 6, 5, 'Escritores españoles de hoy', '', '05_04', NULL, 289, 'El narrador de esta historia, que se corresponde con el autor, Gonzalo Torrente Ballester, utiliza una serie de datos y personas reales, como su primera esposa, Josefina Malvido y sus primos de Vilaxoán -él escribe Vilaxuán-, en un tiempo y lugares muy concretos, articulando un relato que oscila entre lo real y lo fantástico, sin salirse nunca del cauce de lo verosímil, indispensable para el interés de lo narrado.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1276, '8474940621', 'El vagabundo', 1, '1982', 62, NULL, 'media/core/8474940621.jpeg', 1, '2023-04-12 07:43:57.345002', '2023-04-12 07:43:57.345002', 817, 27, 6, 5, NULL, '', '05_04', NULL, 290, '...y después de comer nos reunimos junto al fuego y le pregunté por sus andanzas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1277, '8481300160', 'El espejo en el espejo', 1, '1993', 95, 'Der Spiegel im Spiegel: ein Labyrinth', 'media/core/8481300160.jpg', 1, '2023-04-12 07:48:01.254070', '2023-04-12 07:48:01.254070', 818, 27, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Las treinta narraciones de" El espejo en el espejo" conforman un delicioso laberinto literario en el que resuenan ecos mitológicos, kafkianos y borgianos. Michael Ende ahonda en temas como la búsqueda de la identidad, la desolación de la guerra, el amor, el absurdo de una sociedad entregada al mercantilismo, la magia, la angustia, la falta de libertad y la imaginación, entre otros. Temas que se entretejen junto a un sinfín de historias, escenarios y personajes como, por ejemplo, Hor, que mora en un edificio gigantesco, completamente vacío, donde cada palabra pronunciada en voz alta genera un eco infinito. O el muchacho que, bajo la experta dirección de su padre y maestro, sueña con tener alas y va creándolas pluma a pluma, músculo a músculo. O la catedral de ferrocarriles que contiene el templo al dinero y flota sobre el espacio vacío y crepuscular, negando la salida a los viajeros. O la comitiva que baja de las Montañas del Cielo en busca de la palabra perdida. Ángeles que braman con el sonido del bronce, bailarines que giran perpetuamente tras el telón, astronautas que arrastran carneros, puertas erigidas en mitad de la nadaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1278, '8481300144', 'En la madrugaday otros relatos', 1, '1993', 95, NULL, 'media/core/8481300144.jpg', 1, '2023-04-12 07:51:05.877790', '2023-04-12 07:51:05.877790', 819, 27, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1279, '8481300136', 'Agostino', 1, '1993', 96, NULL, 'media/core/8481300136.jpg', 1, '2023-04-12 08:06:16.383324', '2023-04-12 08:06:16.383324', 820, 27, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Agostino es la historia de un despertar sexual, de la abrupta pérdida de la inocencia por parte de un atormentado adolescente de la burguesía romana; es el relato de su educación sentimental, que se consuma en el seno de una idílica relación madre-hijo en la que el amor materno es correspondido por un sentimiento ambivalente: una atracción a la vez ingenua e impura, etérea y carnal, que empieza a fermentar en Agostino el día en el que su madre, una viuda joven y cargada de sensual vitalidad, conoce, durante unas vacaciones en la playa toscana, a un hombre con el que coquetea. Su inesperada aparición desata en Agostino una inquietud hasta entonces desconocida. El brusco descubrimiento de que su madre es, también y antes que nada, una mujer convierte su inocente sentimiento de admiración y amor filial en una edípica pulsión erótica que turba al adolescente. Desorientado y resentido, en un orgulloso acto de rebelión, Agostino intenta liberarse del dulce yugo materno y se integra en una pandilla de gamberros que lo repele y lo atrae, y a la que se aferra con masoquista determinación para superar la crisis existencial que marcará su ingreso en la edad adulta.Escrita en 1942 y rechazada por la censura fascista, esta novela, que asienta las bases del estilo narrativo de Moravia, fue finalmente publicada en 1945 y le va...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1280, '848130008X', 'Arcadia todas las noches', 1, '1993', 93, NULL, 'media/core/848130008X.jpg', 1, '2023-04-12 08:10:02.201418', '2023-04-12 08:10:02.201418', 175, 2, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Guillermo Cabrera Infante ha reunido cinco extensos ensayos sobre sendas figuras fundamentales del cine norteamericano: Orson Welles, Alfred Hitchcock, Howard Hawks, John Huston y Vicente Minnelli. La aproximación del escritor al mundo del cine, que ha fecundado poderosamente su obra narrativa, había dado ya sobradas muestras de penetración y agudeza en el terreno de la crónica breve en los textos recogidos en Un oficio del siglo XX. Abordando ahora el estudio extenso, en un planteo de extraordinaria amenidad e inventiva, completamente alejada de la postiza seriedad convencional, Cabrera revela una insólita capacidad de síntesis crítica a la vez que una particular aptitud para convertir en cautivadora, no ya para el especialista,sino aun para el simple aficionado al cine y el lector común, la materia, sugerente y múltiple, que le procuran los años de esplendor de Hollywood. Homenaje al gran cine americano del ayer más próximo que gravita sobre la actualidad, Arcadia todas las noches es una de las piezas más brillantes y lúcidas del Cabrera Infante ensayista.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1281, '8481300071', 'En el balneario', 1, '1993', 95, NULL, 'media/core/8481300071.jpeg', 1, '2023-04-12 08:13:53.940526', '2023-04-12 08:13:53.940526', 803, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1282, '8481300233', 'Ataúdes de artesanía', 1, '1993', 95, NULL, 'media/core/8481300233.jpg', 1, '2023-04-12 08:17:19.237031', '2023-04-12 08:17:19.237031', 822, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Este es un relato basado en hechos reales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1283, '848130011X', 'El ermitaño de la calle 69', 1, '1993', 95, 'The kermit of 69th street', 'media/core/848130011X.jpg', 1, '2023-04-12 08:20:54.365542', '2023-04-12 08:20:54.365542', 823, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '"El ermitaño de la calle 69" es un escritor muy semejante al propio Kosinski, que recuerda su vida con humor y sin olvidar las muchas dificultades que ha superado. Además de sus vivencias, abundan las citas literarias y las referencias a la cultura judía. Un libro extrañamente conmovedor.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1284, '8481300020', 'Los jefes', 1, '1993', 96, NULL, 'media/core/8481300020.jpeg', 1, '2023-04-12 08:23:28.527138', '2023-04-12 08:23:28.527138', 86, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Edición crítica con estudio introductorio y guía de lectura. Si en el contexto de las actitudes, las tramas, los modelos de personajes y la conciencia crítica, los cuentos de Los jefes significan un anuncio de lo que serán sus novelas posteriores, en el ámbito del estilo ocurre lo mismo. Las audacias técnicas que descubrimos desde La ciudad y los perros, y comprobamos aumentadas, al menos hasta La guerra del fin del mundo, en los años ochenta, comienzan a vislumbrarse en esos relatos que piden, además, espacios más amplios. Por otro lado, frente al realismo mágico, que triunfa en la década de los sesenta, y es considerado por la crítica como un modelo propiamente hispanoamericano, la escritura de Vargas Llosa huye de elementos míticos o fantásticos y se instala más bien en un realismo que trata de dar una visión totalizadora de la realidad, y concentra todos los esfuerzos en los logros técnicos, antes que en los anecdóticos o argumentales.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1285, '8481300039', 'Los propios dioses', 1, '1993', 95, 'The gods themselves', 'media/core/8481300039.jpg', 1, '2023-04-12 08:25:37.452351', '2023-04-12 08:25:37.452351', 341, 27, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '¿Que podríamos hacer con un suministro de energía gratuita e inagotable?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1286, '8481300217', 'El pan de los años mozos', 1, '1993', 94, NULL, 'media/core/8481300217.jpg', 1, '2023-04-12 08:28:34.109438', '2023-04-12 08:28:34.109438', 825, 27, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Hace siete años que el joven Walter Fendrich ha emigrado a la ciudad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1287, '8481300225', 'Asesinato en Prado del Rey y otras historias', 1, '1993', 94, NULL, 'media/core/8481300225.jpg', 1, '2023-04-12 08:30:44.908223', '2023-04-12 08:30:44.908223', 814, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Carvalho en un caso «televisivo».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1288, '8481300012', 'El tercer hombre', 1, '1993', 94, 'The third Man', 'media/core/8481300012.jpg', 1, '2023-04-13 06:07:51.601325', '2023-04-13 06:09:02.142586', 826, 1, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Publicada originalmente en 1950, El tercer hombre se sitúa en una Viena dividida en cuatro zonas bajo el control de Estados Unidos, Gran Bretaña, Francia y la Unión Soviética, en los años inmediatamente posteriores a la segunda guerra mundial, y describe de un modo crudo y desapasionado la dureza de la vida en unas condiciones de necesidad extrema. Ejemplar del arte narrativo de Greene y de la influencia que sobre él ejercieron las técnicas narrativas cinematográficas, El tercer hombre ha quedado como uno de los relatos más densos y vigorosos del gran escritor inglés', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1289, '8481300195', 'El césped y otros relatos', 1, '1993', 94, NULL, 'media/core/8481300195.jpeg', 1, '2023-04-13 06:11:24.420076', '2023-04-13 06:11:24.420076', 827, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1290, '8481300209', 'Los misterios de colores', 1, '1993', 94, NULL, 'media/core/8481300209.jpg', 1, '2023-04-13 06:13:42.638373', '2023-04-13 06:13:42.638373', 216, 1, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Esta novela, que forma un todo con `La oscura historia de la prima Montse`, se centra en la idea de que la Iglesia Católica disfruta de un status de privilegio en España. Esta postura arrastra a interferir en la vida cotidiana de sus habitantes, desviándose de su misión divina poco propensa a los placeres terrenales para robar al pueblo y, especialmente, controlar las almas. La Iglesia adopta una actitud perjudicial e inapropiada en contradicción con las prescripciones eclesiásticas que se destacan en la obra.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1291, '8481300152', 'Los cuadernos de un vate vago', 1, '1993', 96, NULL, 'media/core/8481300152.jpg', 1, '2023-04-13 06:17:13.398323', '2023-04-13 06:17:13.398323', 801, 29, 2, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Torrente Ballester reflexiona acerca de cómo nacieron algunas de sus novelas. Entre 1961 y 1976, Torrente recogió gran parte de sus notas trabajo en cintas magnetofónicas. Al magnetófono le contaba sus problemas durante la escritura, le hablaba acerca de la gestación de varias de sus obras o de sus miedos y sus alegrías. A veces, incluso, le contaba al magnetófono la historia y luego la transcribía.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1292, '8481300101', 'Leyendas de Guatemala', 1, '1993', 94, NULL, 'media/core/8481300101.jpg', 1, '2023-04-13 06:19:45.413869', '2023-04-13 06:19:45.413869', 828, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Las "Leyendas de Guatemala" constituyen un mundo de revelaciones, mitad mito, mitad verdad. Obra para ser leída en voz alta, su espíritu abierto hace percibir la sonoridad poética de la maravillosa cadencia musical que desprenden sus párrafos, en los que ofrece al lector el conocimiento integral de las tradiciones y los mitos de la América prehispánica, colonial y contemporánea. En su conjunto, el argumento de las leyendas plantea el conflicto cultural que envuelve al hombre americano en pugna constante con las fuerzas de la naturaleza y los mitos que él mismo crea para interpretar el sentido del destino.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1293, '8481300004', 'La hojarasca', 1, '1993', 95, NULL, 'media/core/8481300004.jpg', 1, '2023-04-13 06:21:21.161458', '2023-04-13 06:21:55.868907', 602, 1, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'EnLa hojarasca nació Macondo, ese poblachón cercano a la costa atlántica colombiana que ya se ha convertido en una de los grandes mitos de la literatura universal.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1294, '8481300187', 'El jardín de senderos que se bifurcan', 1, '1993', 92, NULL, 'media/core/8481300187.jpg', 1, '2023-04-13 06:24:37.337297', '2023-04-13 06:24:37.337297', 804, 27, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '"El jardín de senderos que se bifurcan" es un cuento escrito en 1941 por el escritor y poeta argentino Jorge Luis Borges. Fue la historia que dio su nombre a la colección de relatos "El jardín de senderos que se bifurcan" en 1941; fue publicada nuevamente en su totalidad en la colección "Ficciones" de 1944.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1295, '8481300055', 'La coartada perfecta', 1, '1993', 95, 'The perfect Allibi', 'media/core/8481300055.jpeg', 1, '2023-04-13 06:27:32.302959', '2023-04-13 06:27:32.302959', 829, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '1.- La coartada perfecta: Howard planea al detalle el asesinato de George, que crió a su novia como si fuera su propia hija.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1296, '8481300063', 'La partida', 1, '1993', 92, NULL, 'media/core/8481300063.jpg', 1, '2023-04-13 06:30:37.173744', '2023-04-13 06:30:37.173744', 830, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'La partida es el primer libro de cuentos publicado por Miguel Delibes. El argumento de los cuentos, por lo general, se basa en experiencias del propio escritor o en situaciones muy cercanas a él. “La partida”, cuento que da título a este libro de diez relatos, recoge, por ejemplo, el enrolamiento de un muchacho en un barco mercante y tiene no pocos rasgos autobiográficos, al evocar las experiencias del novelista en la Marina española durante la Guerra Civil. Estas experiencias aparecen también en las novelas La sombra del ciprés es alargada y Madera de héroe.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1297, '8481300179', 'Los compañeros de Livingstone', 1, '1993', 95, 'Livingstone''s companions', 'media/core/8481300179.jpg', 1, '2023-04-13 06:34:03.057103', '2023-04-13 06:34:03.057103', 831, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Incluye los siguientes cuentos:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1298, '8481300047', 'Café de artistas y otros papeles volanderos', 1, '1993', 95, NULL, 'media/core/8481300047.jpeg', 1, '2023-04-13 06:41:34.958156', '2023-04-13 06:41:34.958156', 832, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Collage de escenas sobre los habituales de un café madrileño de los años cuarenta, a través de cuyas historias conocemos sus preocupaciones, el hambre, el peso de la reciente guerra civil sobre sus vidas, las costumbres... Un joven de provincias viaja a Madrid dispuesto a triunfar, pero a su llegada entra en un café frecuentando por artistas, literatos y gente de la bohemia, donde nadie le hace caso. Allí conoce finalmente a Rosaura, joven de la que se enamora perdidamente.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1299, '8481300098', 'La perla', 1, '1993', 94, 'The Pearl', 'media/core/8481300098.jpg', 1, '2023-04-13 06:43:40.326738', '2023-04-13 06:43:40.326738', 657, 1, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Esta novela breve narra el hallazgo de una perla de incalculable valor y las consecuencias que acarrea a un modesto pescador, Kino, cuyo hijo ha sido víctima de la picadura de un escorpión. Sin embargo, el interés de esta novela reside en el enfrentamiento entre dos mundos, el de los ricos y el de los pobres, y en el proceso de cambio en las relaciones humanas en función de la situación económica de las personas. Esto explica que sea una novela ampliamente usada en la escuela para invitar a la reflexión ética.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1300, '8481300128', 'Las armas secretas y otros relatos', 1, '1993', 93, NULL, 'media/core/8481300128.jpg', 1, '2023-04-13 06:46:15.351413', '2023-04-13 06:46:15.351413', 833, 44, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, 'Esta edición contiene tres de los cinco relatos de la edición original,Cartas de mamá,El perseguidor y Las armas secretas', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1301, '8481300241', 'Fuera del torbellino', 1, '1993', 95, 'Out of the Whirlpool', 'media/core/8481300241.jpg', 1, '2023-04-13 06:50:30.700840', '2023-04-13 06:50:30.700840', 834, 27, 6, 5, 'Biblioteca de Literatura Universal', '', '05_04', NULL, 130, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1302, '844020115X', 'Diccionario de Economía A/H', 1, '1987', 1, 'Every man''s Dctionary of economics', 'media/core/844020115X.jpg', 1, '2023-04-13 06:55:23.447273', '2023-04-13 06:57:34.909051', 835, 40, 6, 5, 'Biblioteca de economía', '', '05_04', 'Tomo I', 80, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1303, '8440201168', 'Diccionario de Economía L/Z', 1, '1987', 1, 'Every man''s Dctionary of economics', 'media/core/8440201168.jpeg', 1, '2023-04-13 06:57:21.408254', '2023-04-13 06:57:21.408254', 835, 40, 6, 5, 'Biblioteca de economía', '', '05_04', 'Tomo II', 80, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1304, '8475301878', 'Libertad de elegir', 1, '1987', 437, 'Free to choose', 'media/core/sin-imagen_RbvXVhA.jpg', 1, '2023-04-13 07:00:31.500462', '2023-04-13 07:00:31.500462', 836, 2, 6, 5, 'Biblioteca de economía', '', '05_04', NULL, 80, 'Reeditar Libertad de elegir es más que reeditar un clásico. Es un homenaje a la sencillez y a la eficacia con las queINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1305, '8475302866', 'Capitalismo, socialismo y democracia', 1, '1988', 203, 'Capitalism, Socialism and Democracy', 'media/core/8475302866.jpg', 1, '2023-04-13 07:14:31.572497', '2023-04-13 07:18:00.741062', 837, 2, 6, 5, 'Biblioteca de economía', '', '05_04', 'Tomo II', 80, '¿Puede sobrevivir el capitalismo? ¿Puede funcionar el socialismo? Estamos ante uno de los ensayos más influyentes del siglo XX, una obra multidisciplinar que ofrece uno de los análisis más precisos del capitalismo jamás escritos. Schumpeter traza un cuadro en el que los ciclos económicos son la esencia del capitalismo, el fruto de la innovación y la destrucción creativa que reemplaza lo viejo y obsoleto por lo nuevo y eficiente, un proceso que a largo plazo beneficia al conjunto de la sociedad. Sin embargo, el autor se aleja de todo dogma y atisba la viabilidad del socialismo democrático. La obra continúa desconcertando hoy por igual a progresistas y conservadores dogmáticos, y es esencial para comprender los cambios económicos y políticos de las últimas décadas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1306, '8475302785', 'Capitalismo, socialismo y democracia', 1, '1988', 300, 'Capitalism, Socialism and Democracy', 'media/core/sin-imagen_NztASMd.jpg', 1, '2023-04-13 07:17:40.159441', '2023-04-13 07:17:40.159441', 837, 2, 6, 5, 'Biblioteca de economía', '', '05_04', 'Tomo I', 80, '¿Puede sobrevivir el capitalismo? ¿Puede funcionar el socialismo? Estamos ante uno de los ensayos más influyentes del siglo XX, una obra multidisciplinar que ofrece uno de los análisis más precisos del capitalismo jamás escritos. Schumpeter traza un cuadro en el que los ciclos económicos son la esencia del capitalismo, el fruto de la innovación y la destrucción creativa que reemplaza lo viejo y obsoleto por lo nuevo y eficiente, un proceso que a largo plazo beneficia al conjunto de la sociedad. Sin embargo, el autor se aleja de todo dogma y atisba la viabilidad del socialismo democrático. La obra continúa desconcertando hoy por igual a progresistas y conservadores dogmáticos, y es esencial para comprender los cambios económicos y políticos de las últimas décadas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1307, '8475302130', 'Lo pequeño es hermoso', 1, '1988', 309, 'Small is Beautiful', 'media/core/8475302130.jpg', 1, '2023-04-13 07:21:14.044590', '2023-04-13 07:21:14.044590', 838, 2, 6, 5, 'Biblioteca de economía', '', '05_04', NULL, 80, 'Traducido a más de treinta idiomas, Lo pequeño es hermoso es un vigoroso alegato contra una sociedad distorsionada por el culto al crecimiento económico. Su tesis es que necesitamos una profunda reorientación de los objetivos de nuestra economía y nuestra técnica para ponerlas al servicio -y a la escala- del hombre. Inspirándose en fuentes tan diversas como las Encíclicas de los Papas, la economía budista y las obras de Mao-Tsé-tung, Schumacher presenta su visión del uso adecuado de los recursos humanos y naturales, la problemática del desarrollo y las formas de organización y propiedad empresarial. El dilema de la energía nuclear, la utilidad de la autonomía regional, el agudo problema del desempleo y las perspectivas del socialismo se tratan en sus páginas con un estilo persuasivo y ágil que huye del lenguaje de los especialistas para dirigirse directamente al hombre de la calle. Considerado por The Times Literary Supplement como uno de los cien libros más influyentes de los publicados desde la Segunda Guerra Mundial, la obra de E. F. Schumacher, presenta al lector temas de gran actualidad después de casi 40 años de su primera edición.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1308, '8475307248', 'La sociedad de suma cero', 1, '1988', 220, 'The zero-sum Society', 'media/core/8475307248.jpeg', 1, '2023-04-13 07:24:29.487148', '2023-04-13 07:24:29.487148', 839, 2, 6, 5, 'Biblioteca de economía', '', '05_04', NULL, 80, '', '');
