INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1317, '9788498032512', '8 contes de Nadal', 1, '2007', 92, NULL, 'media/core/9788498032512.jpeg', 1, '2023-04-13 07:52:27.095799', '2023-04-13 07:52:27.095799', 841, 44, 6, 5, NULL, '', '05_04', NULL, 174, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1318, '8420613126', 'El extranjero', 10, '1980', 143, 'L''Etranger', 'media/core/8420613126.jpeg', 1, '2023-04-13 07:55:46.765379', '2023-04-13 07:55:46.765379', 842, 1, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'Albert Camus (1913-1960) no sólo fue uno de los escritores más prestigiosos de la generación que llegó a la madurez entre las ruinas, la frustración y la desesperanza de la Europa demolida por las dos Guerras Mundiales, sino que el paso del tiempo agiganta cada vez más su figura excepcional y el valor de su obra.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1319, '8432230073', 'El misterio de la cripta embrujada', 5, '1984', 178, NULL, 'media/core/8432230073.jpg', 1, '2023-04-13 07:58:49.824298', '2023-04-13 07:58:49.824298', 96, 1, 6, 5, 'Biblioteca de bolsillo', '', '05_04', NULL, 13, '"En aquella época me entretenía leer novelas policíacas. Acababa de leer una de Ross McDonald cuyo nombre no recuerdo, y tuve el capricho de seguir sus pasos a mi manera, más como un homenaje que como parodia. Así empecé y acabé, casi de un tirón, en el plazo de una semana, "El misterio de la cripta embrujada". Nunca más he vuelto a escribir con tanta despreocupación ni con tanto placer ni con tanto aprovechamiento de las horas." Eduardo Mendoza.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1320, '8473390997', 'Obras escogidas 2', 1, '1975', 540, NULL, 'media/core/8473390997.jpg', 1, '2023-04-13 08:02:51.493188', '2023-04-13 08:02:51.493188', 843, 2, 6, 5, NULL, '', '05_04', 'Tomo II', 196, '', 'y Friedrich Engels');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1321, '9788498031690', 'El conte de Nadal de l''Auggie Wren', 1, '2006', 58, NULL, 'media/core/9788498031690.jpeg', 1, '2023-04-13 08:05:49.396173', '2023-04-13 08:05:49.396173', 844, 27, 6, 5, NULL, '', '05_04', NULL, 174, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1322, '8496414779', 'Llibre de les bèsties', 1, '2005', 116, NULL, 'media/core/8496414779.jpeg', 1, '2023-04-13 08:09:46.182149', '2023-04-13 08:09:46.182149', 845, 2, 6, 5, 'biblioteca bâsica d''El Periódico', '', '05_04', NULL, 2, 'Una sàtira sobre la lluita pel poder, una crítica de la societat del final del segle xiii representada al·legòricament pel món dels animals.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1323, '9788497643702', 'Cuaderno de notas', 1, '2007', 341, NULL, 'media/core/9788497643702.jpg', 1, '2023-04-13 08:13:19.704751', '2023-04-13 08:13:19.704751', 846, 2, 6, 5, 'Clásicos de la Literatura', '', '05_04', NULL, 184, '', 'Prologado y anotado por Miguel Ángel Ramos');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1324, '9788497644587', 'El fantasma de Baskerville', 1, '2007', 180, 'The Canterville Ghost', 'media/core/9788497644587.jpg', 1, '2023-04-13 08:15:51.886867', '2023-04-13 08:15:51.886867', 498, 1, 6, 5, 'Clásicos de la Literatura', '', '05_04', NULL, 184, 'El castillo Canterville Chase ha pasado a tener nuevos dueños, una familia inglesa a la que no asustan las advertencias de que en él habita un fantasma. De hecho, es tal su indiferencia ante los fenómenos paranormales, que se burlan constantemente del espectro.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1325, '9788493669515', 'Bartleby, el escribiente', 1, '2016', 118, 'Bartleby the Scrivener: A Story of Wall Street', 'media/core/9788493669515.jpg', 1, '2023-04-13 08:18:40.941401', '2023-04-13 08:18:40.941401', 847, 1, 6, 5, NULL, '', '05_04', NULL, 291, 'Bartleby, el escribiente es una de las narraciones más originales y conmovedoras de la historia de la literatura. Melville escribió este relato a mediados del siglo xix, pero por él no parece haber pasado el tiempo. Nos cuenta la historia de un peculiar copista que trabaja en una oficina de Wall Street. Un día, de repente, deja de escribir amparándose en su famosa fórmula: «Preferiría no hacerlo». Nadie sabe de dónde viene este escribiente, prefiere no decirlo, y su futuro es incierto pues prefiere no hacer nada que altere su situación. El abogado, que es el narrador, no sabe cómo actuar ante esta rebeldía, pero al mismo tiempo se siente atraído por tan misteriosa actitud. Su compasión hacia el escribiente, un empleado que no cumple ninguna de sus órdenes, hace de este personaje un ser tan extraño como el propio Bartleby. El libro está ilustrado por Javier Zabala, Premio Nacional de Ilustración 2005.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1326, 'NoRef', 'Los cachorros', 1, '1967', 117, NULL, 'media/core/NoRef.jpg', 1, '2023-04-14 06:11:50.327183', '2023-04-14 06:11:50.327183', 86, 1, 6, 5, 'Palabra e Imagen', '', '05_04', NULL, 21, 'Cuando Mario Vargas Llosa publicó "Los cachorros" en 1967 era ya un escritor consagrado, en su plenitud de narrador. Relato que busca en todo momento una voz plural (según el autor obra más cantada que contada), que ondula de un personaje a otro, de lo subjetivo a lo objetivo, ha suscitado una increíble cantidad de interpretaciones: evocación de juventud, parábola sobre la impotencia de una clase social, castración del artista en el mundo subdesarrollado, y otras muchas. Cualquiera puede ser cierta porque "Los cachorros" tiene la intensidad y el carácter ambiguo de las grandes obras maestras.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1327, '8421170090', 'Guerra del Tiempo', 3, '1973', 139, NULL, 'media/core/8421170090.jpg', 1, '2023-04-14 06:16:44.148751', '2023-04-14 06:16:44.148751', 805, 44, 6, 5, 'Ediciones de bolsillo', '', '05_04', NULL, 285, 'Si las magistrales novelas de Alejo Carpentier (1904-1980) le sitúan en la cima de la narrativa contemporánea en lengua castellana, sus relatos -en los que también se dan cita los motivos y las preocupaciones del resto de su obra narrativa- muestran con singular brillantez el dominio de la forma y el lenguaje. Esta nueva edición de GUERRA DEL TIEMPO Y OTROS RELATOS contiene, además de los siete cuentos que integraban la anterior -«El Camino de Santiago», «Viaje a la semilla», «Semejante a la noche» (variaciones, los tres, sobre el tema del tiempo), y «Oficio de tinieblas», «Los fugitivos», «Los advertidos» y «El derecho de asilo»-, tres nuevas piezas, pertenecientes a la primera etapa creadora de Carpentier: «El estudiante», «El milagro del ascensor» -ambas inéditas hasta ahora en España- e «Historia de lunas».', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1328, '8436512138', 'Confesiones de un adicto a la esperanza', 1, '1978', 318, NULL, 'media/core/8436512138.jpeg', 1, '2023-04-14 06:23:38.121811', '2023-04-14 06:23:38.121811', 848, 32, 6, 5, NULL, '', '05_04', NULL, 129, 'Estas memorias del célebre líder contracultural, que abarcan su estancia en prisión, su cinematográfica fuga y su viaje al corazón del radicalismo político, constituyen una suerte de odisea psiquedélica en la estela de las experiencias de Victor Serge, Arthur Koestler y George Orwell. ''Confesiones de un adicto a la esperanza'' es el cautivador y atemporal canto a la libertad de quien, con su cuestionamiento de la autoridad y su entusiasta divulgación del potencial de las sustancias psiquedélicas, dejó una huella indeleble en el curso de la historia contemporánea.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1329, '9788498150322', 'Poesía medieval', 1, '2005', 119, NULL, 'media/core/9788498150322.jpeg', 1, '2023-04-14 06:27:08.922861', '2023-04-14 06:27:08.922861', 849, 4, 6, 5, 'Clásicos españoles', '', '05_04', NULL, 264, '', 'Es una selección');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1330, '8433460161', 'Yonqui', 1, '1977', 156, 'Junkie', 'media/core/8433460161.jpeg', 1, '2023-04-14 06:30:37.229514', '2023-04-14 06:30:37.229514', 850, 1, 6, 5, 'Narrativa contemporánea', '', '05_04', NULL, 292, 'William Burroughs publicó Yonqui, en 1953, gracias a los buenos oficios de Allen Ginsberg, que se paseó con el manuscrito bajo el brazo por diversas editoriales hasta dar con Carl Solomon, un editor más valiente y más desesperado que otros, y que años después confesó que era tal el terror que le daba trabajar con semejante material que estuvo a punto de sufrir un colapso. Y así fue como apareció uno de los libros míticos de la literatura americana de nuestro siglo, pero también uno de los más prohibidos y subterráneos, en una editorial marginal, bajo el pseudónimo de William Lee. Burroughs aún no era el autor de El almuerzo desnudo, ni se había constituido en el gran visionario de nuestra época, que ha inspirado a escritores, a músicos, a pintores y a cineastas, pero en esta descarnada, deslumbrante crónica de una adicción los vagabundeos en busca de droga, la avidez por el chute, la peculiar sexualidad y las no menos extrañas relaciones nacidas en la comunión de la droga estaba ya el fundamento de toda su obra posterior. Para Burroughs, un audaz explorador del lado más salvaje de la vida y la literatura, todo debe ser experimentado hasta el límite, aunque él nunca pierde la distancia de la inteligencia. Para llegar al paraíso de la droga hay que hundirse en su infierno, puesto que ambos son lo mismo, y la degradación nunca está muy lejos de la revelación. Porque la droga, finalmente, no es un medio para aumentar el goce ni un estimulante: es una manera de vivir.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1331, '8420423122', 'El crepísculo celta', 1, '1985', 194, 'The celtic Twilight', 'media/core/8420423122.jpg', 1, '2023-04-14 06:35:06.354153', '2023-04-14 06:35:06.354153', 851, 44, 6, 5, NULL, '', '05_04', NULL, 10, 'Aunque sea conocido como uno de los poetas más famosos del siglo XX, William Butler Yeats fue también un destacado exponente de las tradiciones míticas y mágicas occidentales. En El crepúsculo celta, rescata "con precisión y candidez" muchas de las cosas que "ha visto y oído" sobre "la tierra de las hadas". Hadas, duendes, brujas y bosques encantados pueblan estos cuentos maravillosos que Yeats recopiló en la provincia donde pasó su infancia y que se han convertido en un referente ineludible para los amantes de la literatura fantástica.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1332, '8437501407', 'Una realidad aparte', 1, '1979', 301, 'A Separate Reality (Further Conversations with don Juan)', 'media/core/8437501407.jpg', 1, '2023-04-14 06:39:05.907960', '2023-04-14 06:39:05.907960', 852, 1, 6, 5, 'Colección popular', '', '05_04', NULL, 166, 'En esta segunda entrega de la serie en la que Carlos Castaneda describe las enseñanzas de don Juan Matus, el autor continúa sus conversaciones y aprendizajes con el brujo yaqui. En su camino hacia el conocimiento de sí mismo, y ayudado por diversas plantas visionarias como el toloache, el peyote y cierta clase de hongos, Castaneda se adentra paso a paso en la deslumbrante cosmovisión de su maestro y gurú. La interiorización de su experiencia en este místico universo llevará al lector a atestiguar la transformación del escritor que, una vez superado el aturdimiento de su inmersión en lo desconocido, aprende a vencer antiguas ide-as y prejuicios acuñados desde su niñez. En este volumen, la fusión de rituales, alucinóge-nos, misticismo y pasajes autobiográficos traslada al personaje a distintos estados de con-ciencia que le permiten atisbar otros entornos misteriosos y complejos. Este libro es, así, una invitación a desplazarse hacia una realidad aparte en la que la sabiduría, que brota de estas páginas, espera ser descubierta.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1333, 'B32111', 'Un empeño caballeresco', 1, '1972', 151, 'The Knightly Quest', 'media/core/B32111.jpg', 1, '2023-04-14 06:42:50.677042', '2023-04-14 06:42:50.677042', 853, 1, 6, 5, 'edicio', '', '05_04', NULL, 21, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1334, '8402063748', 'Los pasos perdidos', 3, '1980', 282, NULL, 'media/core/8402063748.jpeg', 1, '2023-04-14 06:45:18.573523', '2023-04-14 06:45:18.573523', 805, 1, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Pieza magistral de la narrativa latinoamericana y perfecta ilustración del concepto de "lo real maravilloso", "Los pasos perdidos", publicada en 1953, inauguró el periodo de plenitud creadora de la obra de Alejo Carpentier (1904-1980). Novela inspirada en experiencias personales vividas por el autor en el interior de Venezuela, el viaje que lleva al anónimo protagonista a remontar el Orinoco hasta el interior de la selva en busca de un primitivo instrumento musical, se revela asimismo como un retroceso en el tiempo, a través de las etapas históricas más significativas de América, hasta los mismos orígenes, hasta la época de las primeras formas y de la invención del lenguaje.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1335, '8420615137', 'Cándido y otros cuentos', 5, '1984', 221, NULL, 'media/core/8420615137.jpeg', 1, '2023-04-14 06:48:06.718623', '2023-04-14 06:48:06.718623', 615, 44, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'Tanto los tratados históricos de VOLTAIRE (1694-1778), como sus ensayos dirigidos contra la superstición, la intolerancia y el fanatismo, resultan difícilmente disociables de sus relatos filosóficos. Las narraciones volterianas son ciertamente paradigmáticas de ese estilo literario, tanto por la intensidad que los propósitos pedagógicos de la Ilustración alcanzan en sus páginas, como por la armonía con que se ensamblan la forma y el fondo, el argumento y la finalidad ejemplificadoras. El presente volumen, presentado y seleccionado por Paulino Garagorri, incluye cinco cuentos -«Memnón», «Micromegas», «Historia de los viajes de Escarmentado» y «El hombre de los cuarenta escudos», además de CÁNDIDO-, centrados todos ellos en la sátira del mundo europeo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1336, '22083', 'Fatras', 1, '1977', 281, NULL, 'media/core/22083.jpg', 1, '2023-04-14 06:52:33.967229', '2023-04-19 08:09:47.910021', 854, 4, 6, 5, 'Collection Folio', '', '05_04', NULL, 293, 'La poésie peut naître des images aussi bien que des mots, surtout chez un Prévert qui, d''abord homme de cinéma, a un sens aigu de l''image et de ses pouvoirs de suggestion. C''est la confrontation de ces deux moyens d''expression que propose Fatras ou quelques-uns des collages auxquels s''applique depuis longtemps Jacques Prévert ont été reproduits parmi les textes qu''il a écrits dans les années 60. On retrouve dans les uns comme dans les autres les thèmes essentiels de son oeuvre poétique.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1337, '8410018006079', 'El otoño en Pekín', 3, '1984', 284, 'L''automne a Pekin', 'media/core/8410018006079.jpg', 1, '2023-04-14 07:13:05.028767', '2023-04-14 07:13:05.028767', 153, 1, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Esta mañana Amadís Dudu ha perdido el autobús. Tal inconveniente, lejos de resolverse normalmente, supone para Dudu el comienzo de una serie de extraordinarias aventuras que no tardarán en conducirle al gran desierto de Exopotamia. Allí, precisamente porque se trata de un desierto, Dudu entabla conocimiento con una multitud de personajes pintorescos, al tiempo que se ve involucrado en el extravagante proyecto de construcción de una línea ferroviaria. Naturalmente, ni Pekín ni el otoño tienen nada que ver con todo esto. De hecho, aquí casi nada tiene que ver con nada, y no se hace necesario que nadie saque conclusiones. No obstante, si el lector se empeña en ello, no será difícil que, a través de la delirante y cómica peripecia de Dudu, llegue a ese centro secreto en torno al cual gira la obra entera de Boris Vian y en el cual, entrelazados, se esconden el amor y la muerte.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1338, '8432213616', 'El beso de la mujer araña', 1, '1978', 287, NULL, 'media/core/8432213616.jpeg', 1, '2023-04-14 07:16:37.299066', '2023-04-14 07:16:37.299066', 855, 1, 6, 5, 'Nueva narrativa Hispánica', '', '05_04', NULL, 13, 'Un gran clásico de la literatura contemporáneaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1339, '8402077757', 'Pájaros de fuego', 1, '1979', 183, 'Little birds', 'media/core/8402077757.jpeg', 1, '2023-04-14 07:21:07.225274', '2023-04-14 07:21:07.225274', 856, 44, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'La genialidad narrativa de Anaís nin y su exquisita sensibilidad permiten que el sexo, tema central de éstos fantásticos trece relatos, supere lo puramente pornográfico y constituya una bellísima y poética indagación sobres la imaginación erótica del ser humano. Un libro sorprendente y sugerente: un ejemplo de literatura erótica que se trasciende a si misma.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1340, '8427908040', 'La colmena', 32, '1978', 293, NULL, 'media/core/8427908040.jpeg', 1, '2023-04-14 07:25:18.499575', '2023-04-14 07:25:18.499575', 832, 1, 6, 5, 'Libros de bolsillo', '', '05_04', NULL, 202, 'La colmena, seguramente la obra más valiosa de Camilo José Cela, es un testimonio fiel de la vida cotidiana en las calles, cafés y alcobas de aquel Madrid de 1943, pero es también una amarga crónica existencial. Un aire de rutina y fatalidad ha invadido la conciencia de las gentes. Todos creen que las cosas pasan porque sí y que nada tiene remedio. Entre la abigarrada multitud se oye el solitario zumbido de muchos seres confusos y a la deriva. Como es habitual en su obra, Cela presenta la vida española sin piedad, con agria ironía y humorismo atroz. Sin embargo, de vez en cuando, un soplo compasivo alivia la áspera y dolorida realidad. Eduardo Alonso, que ha preparado esta edición, es novelista y profesor de literatura.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1341, '9788478804122', 'La guarida del gusano blanco', 1, '1994', 254, 'The Lair of the White Worm', 'media/core/9788478804122.jpeg', 1, '2023-04-14 07:28:54.325217', '2023-04-14 07:28:54.325217', 857, 12, 6, 5, 'Bolsitemas', '', '05_04', NULL, 26, 'Lambton, una historia del folclore popular inglés que se remonta al menos al siglo XIV. En 1860, un australiano llamado Adam Salton llega a Inglaterra invitado por su tío abuelo. Al llegar en barco a Southampton, Salton es recibido por el anciano Richard, quien lo nombra heredero de sus posesiones, entre ellas Lesser Hill, donde a su llegada se verá abrumado por eventos aterradores y misteriosos. Su vecino, Edgar Calwall, es un hombre extraño obsesionado con el hipnotismo y pronto conocerá una dama llamada Arabella March relacionada con extrañas desapariciones que tienen que ver con una antigua criatura que acecha el paisaje rural de Derbyshire. Sin duda, una apasionante obra de terror gótico que llegó a ser adaptada al cine en 1988 por el director Ken Russell.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1342, '8402062202', 'Delta de Venus', 5, '1981', 314, 'Dela of Venus', 'media/core/8402062202.jpeg', 1, '2023-04-14 07:31:08.278206', '2023-04-14 07:31:08.278206', 633, 44, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Escritos a principios de la década de 1940 por encargo de un excéntrico coleccionista de libros que insistía en pedir «menos poesía» y descripciones más explícitas en las escenas sexuales, los relatos de Delta de Venus no vieron la luz hasta los años setenta. Ambientados en torno al París de la época e hilados por la aparición recurrente de personajes comunes de distinta importancia según cada cuento, ofrecen una visión libre de las relaciones humanas, en la que el erotismo y el ansia de placer no excluyen la belleza, el sentimiento, la amistad y la búsqueda de la autenticidad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1343, '8429710248', 'La meva Crsitina i altres contes', 6, '1978', 125, NULL, 'media/core/8429710248.jpeg', 1, '2023-04-14 07:34:30.911737', '2023-04-14 07:34:30.911737', 858, 44, 6, 5, 'Col·lecció universal de butxaca', '', '05_04', NULL, 2, 'La meva Cristina i altres contes es un recull unitari format per setze contes que Rodoreda publicà el 1967 amb una voluntat de renovar el genere. L''escriptura, treballada i intensa, i una imaginació poderosa han donat com a resultat uns contes d''abast universal que s''allunyen de la cronica i del realisme estricte i conviden el lector a universos singulars marcats per una fantasia ben personal, d''una autentica creadora.Carme Arnau, escriptora i crítica literària, ha centrat els seus treballs en la literatura catalana contemporània i, de manera especial, en l''obra de Merce Rodoreda, a la qual ha dedicat nombrosos articles i assaigs guanyadors de diversos premis, com el Crítica Serra d''Or, el Josep Vallverdú i el de la Fundació Merce Rodoreda, entre d''altres. Actualment dirigeix la publicació de l''Obra completa de la novel·lista, d''Edicions 62.á', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1344, '9788420646312', 'El Horla', 1, '1994', 59, NULL, 'media/core/9788420646312.jpeg', 1, '2023-04-14 07:37:44.335071', '2023-04-14 07:37:44.335071', 859, 27, 6, 5, 'Alizanza cien', '', '05_04', NULL, 69, 'El Horla es un fascinante relato escrito en el s.XIX, en pleno fervor de las teorías de Mesmer sobre el magnetismo y el hipnotismo; en él, el autor nos regala algunos de los momentos más memorables de la literatura fantástica. En un soberbio juego narrativo, el lector contemplará como un hombre es acosado por su propia conciencia, o tal vez sea un ser diabólico quien intenta adueñarse de su voluntad. El protagonista lucha por recuperar su identidad en un ambiente claustrofóbico que se cierra sobre sí mismo, conduciéndolo a través de la espiral de la locura. Alba Pérez ilustra exquisitamente con acrílicos sobre papel de grabado esta novela que pondrá los pelos de punta a más de uno y que, sin duda, entretendrá con su prosa reposada y preciosista a los audaces lectores que se atrevan a leerlo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1345, '8402061451', 'Ecue-Yamba-O', 1, '1979', 203, NULL, 'media/core/8402061451.jpeg', 1, '2023-04-14 07:40:21.721916', '2024-12-17 17:58:33.280206', 805, 1, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, '¡Écue-Yamba-ó! es la primera novela de Alejo Carpentier y narra la vida de Menegildo Cue, negro cubano en los primeros años del siglo XX. Aunque se ha venido clasificando dentro del cajón desastre llamado «novela aforcubana», lo cierto es que esta obra es una de las más influyestes dentro de su género, y muy reveladora dentro de la producción del autor. Deslumbra y emociona con un crisol de tendencias estilísticas existentes a principios del siglo pasado. Adorna sus detalladas descripciones naturalistas con vanguardistas metáforas del Futurismo. Es una obra fundamental para entender la realidad cubana de inicios de siglo, al propio Carpentier, y una piedra angular dentro de la literatura hispanoamericana.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1346, '8402070221', 'Nova Express', 1, '1980', 187, 'Nova Express', 'media/core/8402070221.jpg', 1, '2023-04-14 07:44:44.445101', '2023-04-14 07:44:44.445101', 850, 3, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1347, '8437501067', 'Las Enseñanzas de Don Juan', 1, '1974', 301, 'The Teachings of Don Juan ( A Jaqui Way of Knowledge)', 'media/core/8437501067.jpg', 1, '2023-04-14 07:48:23.815208', '2023-04-14 07:48:23.815208', 852, 1, 6, 5, NULL, '', '05_04', NULL, 166, 'Primero de los libros de este antropólogo en el que narra la primera etapa del aprendizaje que lo convertirá en hombre de conocimiento bajo la guía de un brujo yaqui. Por diversos medios, don Juan sumerge a su discípulo en una realidad no ordinaria, inexplicable para nuestros esquemas de pensamiento pero no para la sabiduría antigua que trasmite el maestro.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1348, 'M32114', 'Oscar Wilde', 1, '1972', 174, 'Oscar Wilde', 'media/core/M32114.jpg', 1, '2023-04-14 07:51:42.028920', '2023-04-14 07:51:42.028920', 860, 31, 2, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1349, '8420618713', 'Rinoceronte', 1, '1982', 201, 'Rhinocéros', 'media/core/8420618713.jpeg', 1, '2023-04-14 08:35:30.987867', '2023-04-14 08:35:30.987867', 861, 41, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'El teatro de lonesco es la realización de un anhelo colectivo fundado en el desparpajo de su ruptura lógica, en la huida inexorable desde lo natural visible, elementos que están en la base misma de su comicidad. Esto le permite formular con gran lucidez sus concepciones básicas: el humor es libertad; la imaginación no es arbitraría, es reveladora; nada más racional que la imaginación, lo Irracional es la vida. Es indudable que una pieza como El rinoceronte representa la concreción deslumbrante de tan original teoría del teatro.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1350, '9788498150254', 'La arboleda perdida', 1, '2005', 349, NULL, 'media/core/9788498150254.jpeg', 1, '2023-04-14 08:38:45.341163', '2023-04-14 08:38:45.341163', 862, 32, 6, 5, 'Clásicos españoles', '', '05_04', 'Vols 1 y 2', 264, 'Obra completa compuesta por tres volúmenes. La arboleda perdida es el evocador título que dio Rafael Alberti a la obra destinada a recoger sus memorias. Si el primer volumen, escrito en el exilio, abarca los años que van desde 1902 hasta 1931 y da cuenta de sus primeros recuerdos. El segundo recoge el periodo comprendido entre 1931 y 1987, marcado por la nostalgia de su tierra y la incertidumbre del regreso. El tercero, que llega hasta 1996, está dominado por el adentramiento definitivo e irremediable en ese golfo de sombras anticipado ya por su sensibilidad, pero también por la esperanza de que el paso del tiempo no alcance a borrar las huellas de una existencia de enorme plenitud y riqueza que abarca prácticamente la totalidad de uno de los siglos más apasionantes de nuestra historia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1351, '9788498150261', 'Poema de Mio Cid', 1, '2005', 301, NULL, 'media/core/9788498150261.jpeg', 1, '2023-04-14 08:40:54.397992', '2023-04-14 08:40:54.397992', NULL, 4, 6, 5, 'Clásicos españoles', '', '05_04', NULL, 264, 'https://es.wikipedia.org/wiki/Cantar_de_mio_Cid', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1352, '9788498150247', 'Novelas ejemplares', 1, '2005', 587, NULL, 'media/core/9788498150247.jpg', 1, '2023-04-14 08:43:22.690870', '2023-04-14 08:43:22.690870', 680, 1, 6, 5, 'Clásicos españoles', '', '05_04', NULL, 264, 'https://es.wikipedia.org/wiki/Novelas_ejemplares', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1353, '8433904248', 'La banda de la casa de la bomba y otras crónicas de la era pop', 1, '1975', 255, 'The Pump House Gang', 'media/core/8433904248.jpeg', 1, '2023-04-14 08:46:24.964512', '2023-04-14 08:46:24.964512', 863, 1, 6, 5, 'Serie Informal', '', '05_04', NULL, 6, 'Tom Wolfe examina provocativamente, sobre el terreno, los recientes monstruos sagrados, lasinstituciones de la era pop, los representantes de la nueva cultura: los surfers, los locos de la moto, los Muchachos de la Melena y la estética de lo rancio, Hefner (Playboy), el rey de los reclusos voluntarios, la top-less trucada con silicona, el revoltijo mcluhaniano, los swinging London, las heathfields y las dolies, los hoteles climatizaods, la decadencia del cocktail-party y la aparición de la cena-con-mono, la nueva etiqueta de la nueva café-society neoyorkina.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1354, '847389054X', 'Un tranvía llamado deseo', 1, '1988', 122, 'A Streetear Named Desire', 'media/core/847389054X.jpg', 1, '2023-04-14 08:50:32.093594', '2023-04-14 08:50:32.093594', 853, 41, 6, 5, 'Colección escena', '', '05_04', NULL, 294, 'https://es.wikipedia.org/wiki/Un_tranv%C3%ADa_llamado_Deseo_(obra_de_teatro)', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1355, '9426-65', 'La metamorfosis', 1, '1966', 144, 'Die Verwandlung', 'media/core/9426-65.jpg', 1, '2023-04-14 17:07:11.111813', '2023-04-14 17:07:11.111813', 864, 1, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, '«Al despertar Gregorio Samsa una mañana, tras un sueño intranquilo, se encontró en su cama convertido en un monstruoso insecto.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1356, '8436510674', 'Cartas del Yagé', 1, '1977', 104, NULL, 'media/core/8436510674.jpeg', 1, '2023-04-14 17:11:24.269120', '2023-04-14 17:11:24.269120', 850, 29, 6, 5, NULL, '', '05_04', NULL, 129, 'Las cartas de la ayahuasca, libro publicado originalmente en 1963, es un volumen de correspondencia y otros escritos de William Burroughs y Allen Ginsberg. La mayor parte de estos textos datan de 1953, y constituyen una crónica del viaje que en ese año hizo Burroughs a la selva amazónica de Colombia y del Perú en busca del yagué o la ayahuasca, una planta de míticas propiedades alucinógenas y telepáticas. En el transcurso de su crónica epistolar, Burroughs comparte con Ginsberg numerosas anécdotas e historias, entre las que se incluyen ciertos conceptos que más tarde utilizaría en novelas como El almuerzo desnudo. El volumen termina con una larga carta de Ginsberg, escrita en 1960, en la que el famoso poeta de la Beat Generation le relata a su mentor Burroughs los experimentos que él mismo realizó también con la ayahuasca.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1357, '8471627159', 'Ishi, el último de su tribu', 1, '1978', 184, 'ISHI last of his tribe', 'media/core/8471627159.jpg', 1, '2023-04-14 17:14:55.430436', '2023-04-14 17:15:38.148420', 865, 45, 6, 5, NULL, '', '05_04', NULL, 242, 'Este libro cuenta la historia inquietante y heroica de Ishi -el niño, el hombre, el único superviviente de su tribu-.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1358, '8420616532', 'El elctrón es zurdo y otros ensayos científicos', 7, '1984', 248, 'Extracts of: The Left Hand of the Electron - The Solar System and Back - From Earth to Heaven', 'media/core/8420616532.jpg', 1, '2023-04-14 17:19:17.852051', '2023-04-14 17:19:17.852051', 341, 15, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'Esta recopilación de artículos de divulgación científica escritos por Isaac Asimov se abre con un divertido trabajo sobre la capacidad pronosticadora de la novela científica, al que siguen dos ensayos en torno a las leyes que gobiernan la expansión y miniaturización en la naturaleza. «El electrón es zurdo» pertenece a una serie de cinco trabajos que se ocupan de la paridad y la simetría en el mundo inanimado y en los seres vivos. El resto de los artículos examinan muy diversos temas: los océanos, la certidumbre y la incertidumbre en la física, los axiomas de Euclides y las razones por las cuales fueron considerados como una verdad absoluta durante dos mil años, etcétera.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1359, '8420612774', 'Cuentos /1', 6, '1980', 534, 'Obras en prosa I. Cuentos de Edgar Allan Poe', 'media/core/8420612774.jpg', 1, '2023-04-14 17:22:43.434105', '2023-04-14 17:22:43.434105', 497, 44, 6, 5, 'El libri de bolsillo', '', '05_04', NULL, 69, 'Esta edición en dos volúmenes ofrece la recopilación de los 67 Cuentos publicados a lo largo de su vida por Edgar Alan Poe (1809-1849) en la magnífica traducción llevada a cabo por Julio Cortázar. El primer volumen reúne las narraciones dominadas por el terror, la presencia de lo sobrenatural, la preocupación metafísica y el gusto por el análisis, mientras que el segundo recoge las exploraciones sobre el pasado y el futuro, los bellos relatos contemplativos que encierran la filosofía de Poe sobre el paisaje, la serie de estampas grotescas y los cuentos de carácter satírico.', 'Prólogo y traducción de Julio Cortázar');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1360, '840205854X', 'Los mitos del Cthulhu III', 2, '1981', 249, 'Tales of the Cthulhu Mythos', 'media/core/840205854X.jpg', 1, '2023-04-14 17:26:01.619572', '2023-04-14 17:26:01.619572', 747, 44, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Anticipada por notables precedentes y enriquecida posteriormente por otros escritores, corresponde sin embargo a Howard Phillips Lovecraft el papel más importante en la invención de LOS MITOS DE CTHULHU, ciclo de narraciones de horror cósmico ambientadas en muchos primigenios de caos y espanto. El presente volumen ofrece una completa panorámica del desarrollo de los mitos y reúne las piezas fundamentales en la configuración de ese singular e inquietante universo que remueve en el interior del lector profundos terrores atávicos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1361, '8402058418', 'Los mitos del Cthulhu II', 2, '1981', 216, 'Tales of the Cthulhu', 'media/core/8402058418.jpg', 1, '2023-04-14 17:28:10.772532', '2023-04-14 17:28:10.772532', 747, 44, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Anticipada por notables precedentes y enriquecida posteriormente por otros escritores, corresponde sin embargo a Howard Phillips Lovecraft el papel más importante en la invención de LOS MITOS DE CTHULHU, ciclo de narraciones de horror cósmico ambientadas en muchos primigenios de caos y espanto. El presente volumen ofrece una completa panorámica del desarrollo de los mitos y reúne las piezas fundamentales en la configuración de ese singular e inquietante universo que remueve en el interior del lector profundos terrores atávicos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1362, '8402057926', 'Los mitos del Cthulhu I', 2, '1981', 269, 'Tales of the Cthulhu Mythos', 'media/core/8402057926.jpg', 1, '2023-04-14 17:29:55.054409', '2023-04-14 17:29:55.054409', 747, 44, 2, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Anticipada por notables precedentes y enriquecida posteriormente por otros escritores, corresponde sin embargo a Howard Phillips Lovecraft el papel más importante en la invención de LOS MITOS DE CTHULHU, ciclo de narraciones de horror cósmico ambientadas en muchos primigenios de caos y espanto. El presente volumen ofrece una completa panorámica del desarrollo de los mitos y reúne las piezas fundamentales en la configuración de ese singular e inquietante universo que remueve en el interior del lector profundos terrores atávicos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1363, '847389040X', 'La gata sobre el tejado de zinc caliente', 1, '1983', 83, 'A Cat on a Hof Tin Roof', 'media/core/847389040X.jpg', 1, '2023-04-14 17:33:52.849898', '2023-04-14 17:33:52.849898', 853, 41, 6, 5, 'Colección escena', '', '05_04', NULL, 294, '"La gata sobre el tejado de zinc caliente" es una de las obras maestras de Tennesse Williams. Expresa su visión de los oscuros y primitivos elementos que acechan bajo la superficial civilización del Sur norteamericano. Una calurosa noche de verano en la residencia de una riquísimo plantador de algodón del Mississippi, una familia presa del pasado se desintegra entre acusaciones de lujuria, codicia y envidia', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1364, '9788402093967', 'Carta al padre', 3, '1983', 102, 'Brief an den vater', 'media/core/9788402093967.jpeg', 1, '2023-04-14 17:36:06.699828', '2023-04-14 17:36:06.699828', 864, 27, 6, 5, 'Libro amigo', '', '05_04', NULL, 126, 'Cuando Kafka escribió esta carta bajo el pretexto de fundamentar ante su padre el miedo que sentía por él, utilizó todas sus argucias de abogado. Sabemos esto ya que él mismo hubo de confesárselo a Milena Jessenska, su segundo gran amor, a quien le permitió la lectura del original, aunque en éste se hablase de ella. Esta carta debió haber sido quemada por Max Brod. Al salvarla de la hoguera, éste salvó la llave maestra de todos los escritos de Kafka. En ella se basan todas las interpretaciones de lo que el autor denominaba ?el revolverse de la mosca en la hoja de papel engomado?, es decir, él mismo en su casa paterna.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1365, '8402047831', 'Fundación e Imperio', 7, '1982', 253, 'Foundation and Empire', 'media/core/8402047831.jpeg', 1, '2023-04-14 17:39:30.644449', '2023-04-14 17:39:30.644449', 341, 3, 6, 5, 'Libro amigo', '', '05_04', 'Trilogía de las Fundaciones 2', 126, 'Isaac Asimov es el autor más influyente y destacado de la ciencia ficción y la divulgación científica del siglo xx. Fundación e imperio es la segunda novela de la trilogía de Las Fundaciones, una de las obras maestras del género.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1366, '8402048323', 'Seguns Fundación', 7, '1982', 251, 'Second Foundation', 'media/core/8402048323.jpeg', 1, '2023-04-14 17:42:10.756886', '2023-04-14 17:42:10.756886', 341, 3, 6, 5, 'Libro amigo', '', '05_04', 'Trilogía de las Fundaciones 3', 126, 'Hari Seldon predijo la caída del Imperio, y, con el fin de restaurar la civilización en el menor tiempo posible, creó dos Fundaciones. La primera fue establecida en Términus a plena luz del conocimiento público. La segunda, «en el otro extremo de la galaxia», tomó forma bajo un velo de total silencio, ya que custodia las leyes de la psicohistoria, que solo son válidas mientras permanezcan en secreto. Cuando la Primera Fundación fue conquistada por el poder de una solaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1367, '8421751026', 'El león de Comarre / A la caída de la noche', 2, '1980', 222, 'The Lion of Comarre / Against the Fall of Night', 'media/core/8421751026.jpeg', 1, '2023-04-14 17:49:46.331568', '2023-04-14 17:49:46.331568', 577, 3, 6, 5, 'Ciencia Ficción', '', '05_04', NULL, 295, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1368, '9788497643528', 'Relatos cómicos', 1, '2008', 159, NULL, 'media/core/9788497643528.jpg', 1, '2023-04-14 17:53:06.086585', '2023-04-14 17:53:06.086585', 497, 44, 6, 5, 'Clásicos de la Literatura', '', '05_04', NULL, 184, 'Esta magnífica edición de Edimat está compuesta por ocho relatos, en los que Edgar Allan Poe fantasea sobre una serie de situaciones y personajes absolutamente absurdos. Los títulos de los cuentos son:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1369, '9788402093950', 'El proceso', 3, '1983', 259, 'Der Prozess', 'media/core/9788402093950.jpeg', 1, '2023-04-14 17:55:23.156948', '2023-04-14 17:55:23.156948', 864, 1, 6, 5, 'LIbro amigo', '', '05_04', NULL, 126, 'Una mañana cualquiera, Josef K., joven empleado de un banco,se despierta en la pensión donde reside con la extraña visitade unos hombres que le comunican que está detenido -aunque por elmomento seguirá libre-. Le informan de que se ha iniciado un procesocontra él, y le aseguran que conocerá los cargos a su debidotiempo. Así comienza una de las más memorables y enigmáticaspesadillas jamás escritas. Para el protagonista, Josef K., el procesolaberíntico en el que inesperadamente se ve inmerso supone una tomade conciencia de sí mismo, un despertar que le obliga a reflexionarsobre su propia existencia, sobre la pérdida de la inocencia y laaparición de la muerte. La lectura de El proceso producecierto «horror vacui» pues nos sumerge en una existencia absurda,en el filo de la navaja entre la vida y la nada.Max Brod, amigo, editor y albacea literario de Kafka trassu muerte, conoció la existencia de la obra en 1914, pues Kafka,según su costumbre, le leyó algunos pasajes. Desde un primermomento quedó fascinado por la fuerza de la historia, por lo queinsistió, como en otras ocasiones, en que se publicara, contra lahabitual reticencia de su autor. Tras la prematura muerte por tuberculosisde Kafka en 1924, y a pesar de que el autor había manifestado enuna nota su deseo de que todos sus escritos fuesen destruidos sin ser leídos,Max Brod decidió publicar El proceso años después.La presente edición recoge el texto íntegro y la ordenaciónde Kafka sin los expurgos y arbitrariedades de las primeras ediciones deMax Brod.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1370, '8420612979', 'El Castillo', 4, '1978', 365, 'Das Schlos', 'media/core/8420612979.jpeg', 1, '2023-04-14 17:59:07.850437', '2023-04-14 17:59:07.850437', 864, 1, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'El castillo es considerada por muchos especialistas de la obra kafkiana como la cúspide literaria del escritor praguense, debido tanto a su complejidad estructural y a su madurez simbólica y metafórica, como a la densidad intelectual de los motivos que la forman. Efectivamente, en El castillo, escrito en la última fase de la vida del autor, cuando la enfermedad progresaba con una desesperante tenacidad, la fuerza expresiva de Kafka alcanza una intensidad inusual, siendo testimonio de la falta de compromisos del autor, de su firme voluntad de enfrentarse a un terrible reto existencial: el «asalto contra la última frontera terrenal», su deseo de ser «final o principio». Esta madurez e intensidad, su extraordinario estilo, el cual, como dijo Hermann Hesse, convierte a Kafka en un rey secreto de la prosa alemana, hacen de la novela El castillo un joven clásico de la literatura universal, un clásico que, como El proceso , ha desencadenado un alud de interpretaciones y comentarios, no sólo literarios, sino filosóficos, teológicos, psicológicos, políticos y sociológicos, demostrando así que ha tocado el nervio de nuestra época.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1371, '9788433920423', 'La conjura de los necios', 42, '2010', 389, 'A Confederacy of Dunces', 'media/core/9788433920423.jpeg', 1, '2023-04-14 18:02:09.255223', '2023-04-14 18:02:09.255223', 866, 1, 6, 5, 'Colección compactos', '', '05_04', NULL, 6, 'La Conjura De Los Necios es una disparatada, ácida e inteligentísima novela. Pero no sólo eso, también es tremendamente divertida y amarga a la vez. La carcajada escapa por sí sola ante las situaciones desproporcionadas de esta gran tragicomedia. Ignatius J. Really es, probablemente, uno de los mejores personajes jamás creados y al que muchos no dudan en comparar con el Quijote. Más aún, es el antiprotagonista perfecto para una novela repleta de excelentes personajes, situados en la portuaria ciudad de Nueva Orleans, magistral Ignatius. Él es un incomprendido, una persona de treinta y pocos años que vive en la casa de su madre y que lucha por lograr un mundo mejor desde el interior de su habitación. Pero cruelmente se verá arrastrado a vagar por las calles de Nueva Orleans en busca de trabajo, obligado a adentrarse en la sociedad, con la que mantiene una relación de repulsión mutua, para poder sufragar los gastos causados por su madre en un accidente de coche mientras conducía ebria. El autor, John K. Toole, consigue una crítica clase media. Logra mantener el interés del lector (incluso mayor en una segunda lectura que en la primera) con un abanico de personajes a cuál más desagradable. No deja títere con cabeza y, a través de la tortuosa y enrevesada personalidad de Ignatius, da un repaso a la época que le tocó vivir en un tono de burla que contrasta con la triste visión de las vidas de los personajes retratados. No encontramos únicamente una loca y angustiosa historia de crítica social, sino que el argumento engancha desde el comienzo. Momento en el que, como dice su protagonista, Fortuna hace girar su rueda hacia abajo y nunca sabemos cual es la desagradable sorpresa que nos depara el destino. A partir de aquí, unas situaciones enganchan con otras, al igual que lo van haciendo los personajes, y se va formando una enorme bola de nieve que terminará estallando al final de la novela. Tras terminar La Conjura De Los Necios, a sus 32 años, el autor intentó infructuosamente que la publicasen. Ello derivó en una profunda depresión que le condujo al suicidio. Gracias a la tenacidad e insistencia de su madre hoy podemos disfrutar de esta deliciosa obra galardonada con el Premio Pulitzer. También podemos encontrar publicada La Biblia De Neón, novela escrita cuando el autor tenía 16 años.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1372, '8420602469', 'El Dorado. Crónica de la expedición de Pedro de Lleua y Lope de Aguirre', 1, '1987', 170, NULL, 'media/core/8420602469.jpg', 1, '2023-04-14 18:06:06.689107', '2023-04-14 18:06:06.689107', 867, 45, 6, 5, 'El libro de bolsillo', '', '05_04', NULL, 69, 'De los numerosos episodios terribles y truculentos en los que abundó el transcurso de la conquista del continente americano, pocos han llamado tanto la atención a historiadores, literatos, psiquiatras e incluso cineastas como la EXPEDICIÓN DE PEDRO DE URSUA Y LOPE DE AGUIRRE por el Amazonas, aventura que se emprendió teniendo como fondo el espejismo de EL DORADO, mito en el que confluyeron realidades y fantasías, anhelos e intereses de diversos grupos humanos. Testigo presencial y superviviente afortunado del «alzamiento de Don Fernando de Guzmán y Lope de Aguirre y otros tiranos», FRANCISCO VÁZQUEZ escribió su CRÓNICA hacia 1562, cuando los hechos estaban todavía muy recientes en su memoria. El final de esta dramática relación que retrata como pocas la hoy casi inimaginable experiencia de aquellos hombres trasplantados a un continente virgen lo marca la muerte del «fuerte caudillo de los marañones», solo, vencido y abandonado por todos los suyos, lejos de volver a pisar tierras peruanas, como pretendía. La presente edición de Javier Ortiz de la Tabla aporta, además de un cuidadoso texto, numerosos datos sobre la azarosa vida del audaz rebelde. En esta misma colección: «Naufragios» (H 4193), de Cabeza de Vaca; «Los cuatro viajes. Testamento» (H 4188), de Cristóbal Colón, y «Brevísima relación de la destruición de las Indias» (H 4237), de Las Casas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1373, '8423907112', 'Historia de una taberna', 5, '1976', 226, NULL, 'media/core/8423907112.jpeg', 1, '2023-04-14 18:09:52.115992', '2023-04-14 18:09:52.115992', 868, 1, 6, 5, 'Colección Austral', '', '05_04', NULL, 18, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1374, '9788408071457', 'El pedestal de las estatuas', 2, '2007', 538, NULL, 'media/core/9788408071457.jpg', 1, '2023-04-15 06:21:26.058417', '2023-04-15 06:21:26.058417', 50, 1, 6, 5, 'Autores Españoles e Iberoamericanos', '', '05_05', NULL, 7, 'El descubrimiento de unos cuadernos desconocidos de Antonio Pérez, el secretario de Felipe II, permite desvelar la Historia oculta de aquellos años en España. El propio secretario reconoce, en sus últimos días, que continúa con vida gracias al arcón donde guarda copia de documentos, legajos, cartas y toda clase de pruebas que implican en asesinatos y siniestras estrategias a la monarquía, a la Iglesia y a casi toda la nobleza, desde los Reyes Católicos hasta Carlos V y su enigmático heredero. Es la confesión total de Antonio Pérez, el más temido verdugo del poder, que terminó siendo víctima de sí mismo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1375, '9788467226324', 'El veredicto de César', 1, '2006', 350, 'The judgement of Caesar', 'media/core/sin-imagen_WoYnpIF.jpg', 1, '2023-04-15 06:21:46.063729', '2023-04-15 06:44:39.548640', 517, 16, 6, 5, NULL, '', '05_05', 'Roma Sub Rosa', 296, 'Corre el año 48 a.C. Y Julio César se halla involucrado en las querellas dinásticas entre Ptolomeo y Cleopatra, hermanos rivales por el trono de Egipto, mientras sostiene un apasionado romance con la reina del Nilo. César continúa enfrentado políticamente con el general Pompeyo, quien a su vez planea un violento ataque a ese reino. Allí también se encuentran Gordianus, el detective romano, con su esposa Bethesda, quien padece una enfermedad y espera curarse en ls aguas del río sagrado.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1376, '9788467229929', 'El triunfo de César', 1, '2008', 277, 'The triumph of Caesar', 'media/core/9788467229929.jpg', 1, '2023-04-15 06:35:44.208734', '2023-04-15 06:35:44.208734', 517, 16, 2, 5, NULL, '', '05_05', 'Roma Sub Rosa', 297, 'https://es.wikipedia.org/wiki/El_triunfo_de_C%C3%A9sar', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1377, '9788467226256', 'El brazo de la Justicia', 1, '2006', 335, 'Arms of Nemesis', 'media/core/9788467226256.jpeg', 1, '2023-04-15 06:38:36.182019', '2023-04-15 06:38:36.182019', 517, 16, 6, 5, NULL, '', '05_05', 'Roma Sub Rosa', 15, 'Nada es lo que parece a primera vista en el segundo caso de la serie de misterio de la antigua Roma.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1378, '9788467226249', 'Sangre romana', 1, '1993', 412, 'Roman Blood', 'media/core/9788467226249.jpeg', 1, '2023-04-15 06:41:54.142085', '2023-04-15 06:41:54.142085', 517, 16, 6, 5, NULL, '', '05_05', 'Roma Sub Rosa', 15, 'La inefable sagacidad y el inquebrantable humor de Giordiano en este primer caso de la serie de misterio de la antigua Roma.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1379, '9788467226317', 'La adivina de Roma', 1, '2007', 336, 'A Mist of Propheties', 'media/core/9788467226317.jpeg', 1, '2023-04-15 06:44:24.729697', '2023-04-15 06:44:24.729697', 517, 16, 6, 5, NULL, '', '05_05', 'Roma Sub Rosa', 280, 'Una novela apasionante, llena de intrigas y misterios, sobre la antigua Roma. El Imperio se tambalea bajo la presión de la guerra civil entre Julio César y Pompeyo, mientras el detective Gordiano investiga el asesinato de la joven y hermosa adivina Casandra. Gordiano descubrirá una conspiración en la que están implicadas algunas de las damas más poderosas de la ciudad. Personajes como el propio César, Cicerón o Marco Antonio y escenarios como Roma, Alejandría o Egipto nos acompañan en una apasionante historia que podría haber cambiado el destino de Roma.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1380, '9788435006682', 'Tres manos en la fuente. La IX novela de Marco Didio Falco', 1, '1998', 359, 'Three Hands in the Fountain', 'media/core/9788435006682.jpg', 1, '2023-04-15 06:51:41.448393', '2023-04-15 07:11:21.902614', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'De nuevo en Roma tras su peligrosa misión en Hispania, Marco Didio Falco intenta dar un nuevo impulso a su vida profesional asociándose con su viejo amigo Petronio, al tiempo que lidia con sus endémicos problemas familiares. Pero un macabro y espectacular caso vendrá a alterar todos sus planes: Un asesino en serie que tiene atemorizadas a todas las muchachas romanas está sembrando de manos humanas los sistemas de canalización de aguas de la capital del Imperio. Nadie como Falco para resolver un enigma como éste.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1381, '9788435006996', 'Una virgen de más, La XI novela de Marco Didio Falco', 1, '1999', 424, 'One Virgin Too Many', 'media/core/9788435006996.jpg', 1, '2023-04-15 06:54:39.154750', '2023-04-15 06:54:39.154750', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'La desaparición de una niña malcriada que se siente amenazada por su familia es el punto de arranque de esta nueva entrega de la serie. El Philip Marlowe de la Roma imperial no parece muy interesado en el caso, pero el hallazgo de un cadáver cambia por completo las cosas. Sin duda es la novela negra más divertida del año y una de las más redondas de la serie.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1382, '9788435006118', 'Último acto en Palmira. La VI novela de Marco Didio Falco', 1, '1994', 458, 'Last act in Palmyra', 'media/core/9788435006118.jpg', 1, '2023-04-15 06:57:36.293469', '2025-05-07 08:49:55.853930', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Las cosas no marchan bien en Roma para Marco Didio Falco, que debe aceptar una misión en Oriente para ganarse la vida. Junto a su inseparable Helena Justina, se integrarán en una compañía de teatro en la que se han producido varios asesinatos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1383, '9788435006736', 'La carrera del honor', 1, '1998', 366, 'Te Course of Honour', 'media/core/9788435006736.jpg', 1, '2023-04-15 07:01:20.888600', '2023-04-15 07:01:20.888600', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', NULL, 47, 'La vida del joven Vespasiano: su carrera política, sus amores, sus intrigas y luchas de poder.... Todo ello contado desde la óptica de una esclava de la que estuvo enamorada y a la que su posición política obligó a mantener en la sombra.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1384, '9788435061292', 'Ver Delfos y morir. La XVII novela de Marco Didio Falco', 1, '2006', 498, 'See Delphi and Die', 'media/core/9788435061292.jpg', 1, '2023-04-15 07:04:15.064527', '2023-04-15 07:04:15.064527', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'La acción de la última entrega de las aventuras de Marco Didio Falco nos traslada a Grecia, adonde ha ido en viaje de estudios el cuñado de Marco, Aulo. En apariencia se trataría de un viaje en familia para controlar un poco al joven, pero, como es natural, no tarda en verse envuelto todo en una serie de enigmáticos asesinatos de mujeres que las compañías que organizan viajes se han cuidado mucho de no difundir. Como viene siendo habitual en los últimos años, a la creación de una intriga salpicada de divertidas escenas y a la recreación fiel de un momento histórico, Lindsey Davis añade un guiño a la situación de nuestro tiempo. En esta ocasión el objetivo de sus ironías son los viajes organizados y la catadura moral de las agencias de viajes. En este aspecto se trata sin duda de una de las novelas más divertidas de la serie, y resulta muy irónico que, después de que Londres haya sido designada como sede de los Juegos Olímpicos de 2012, la acción de la novela se sitúe en el ambiente de una competición olímpica.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1385, '9788435061513', 'Las Saturnales. La XVIII novela de Marco Didio Falco', 1, '2007', 508, 'Saturnalia', 'media/core/9788435061513.jpg', 1, '2023-04-15 07:07:27.058725', '2023-04-15 07:07:27.058725', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Esta vez Lindsey Davis nos sitúa en una de las fiestas más curiosas de la Roma Antigua, las Saturnales, donde durantes siete días con sus agitadas noches parece que todo está permitido.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1386, '9788435061926', 'Alejandría. La XIX novela de Marco Didio Falco', 1, '2009', 507, 'Alexandria', 'media/core/9788435061926.jpg', 1, '2023-04-15 07:10:03.437723', '2023-04-15 07:10:03.437723', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Acosado por su aristocrática esposa, Falco se embarca con destino a Alejandría con el propósito de visitar algunas de las siete maravillas del mundo. Sin embargo, al poco de su llegada aparece un cadáver en la célebre biblioteca de esa ciudad, y eso le involucra en una investigación que le llevará a conocer a fondo los entresijos de las pequeñas luchas políticas en el seno de una institución cultural tan emblemática como la Biblioteca de Alejandría. Como siempre en Davis, su texto puede trasladarse fácilmente a nuestros días y a la mayoría de entidades culturales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1387, '9788435060141', 'Oda a un banquero. La XII novela de Marco Didio Falco', 1, '2000', 427, 'Ode to a Banker', 'media/core/9788435060141.jpg', 1, '2023-04-15 07:18:45.615376', '2023-04-15 07:18:45.615376', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Si en ¡A los leones! Lindsey Davis ponía en solfa el mundo del espectáculo, en esta obra, que le valió el prestigioso Premio Sherlock, ha puesto a los escritores, agentes y editores en su punto de mira. La investigación en la que se ve involucrado Marco Didio Falco en esta ocasión es apasionante, sus peripecias en la Roma imperial son desternillantes, pero es evidente que Davis nos habla también del no menos cómico mundo de las letras, que parece no haber cambiado tanto a través de los siglos. Sencillamente, genial.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1388, '9788435006613', 'Una conjura en Hispania. LA VIII novela de Marco Didio Falco', 1, '1996', 476, 'A Dying Light in Corduba', 'media/core/9788435006613.jpg', 1, '2023-04-15 07:21:59.382160', '2023-04-15 07:21:59.382160', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Segundo volumen de la serie que tiene como protagonista a Marco Didio Falco, detective de la época de Vespasiano. Un periplo por la Italia del año 70 d.C., además de una deliciosa y divertidísima aventura.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1389, '9788435006385', 'Tiempo para escapar. La VII novela de Marco Didio Falco', 1, '1995', 480, 'Time to Depart', 'media/core/9788435006385.jpg', 1, '2023-04-15 07:24:46.240098', '2023-04-15 07:24:46.240098', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'En el verano del año 72 Marco Didio Falco y su novia Helena Justina regresan a Roma. Durante su ausencia, su amigo el oficial Petronio Longo ha conseguido llevar ante los tribunales a uno de los jefes del hampa romana. Pero las cosas pronto se complican.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1390, '9788435006026', 'El oro de Poseidón. La V novela de Marco Didio Falco', 1, '1994', 424, 'Poseidon''s Gold', 'media/core/9788435006026.jpg', 1, '2023-04-15 07:27:40.159219', '2023-04-15 07:27:40.159219', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Tras su regreso a Roma, Marco Didio Falco se convierte en principal sospechoso del asesinato de un ex legionario al que el hermano del detective debía dinero. Para colmo, su novia Helena Justina se ve involucrada en el asunto.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1391, '9788435005883', 'La mano de hierro de Marte. La IV novela de Marco Didio Falco', 1, '1993', 397, 'The Iron Hand of Mars', 'media/core/9788435005883.jpg', 1, '2023-04-15 07:31:18.801265', '2023-04-15 07:31:18.801265', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'En Germania, en los confines del Imperio, ha estallado la insurrección. Y mientras Tito César, hijo de Vespasiano, intenta seducir a la novia de Marco Didio Falco, éste es enviado a investigar el asunto.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1392, '9788435061001', 'Los fiscales. La XV novela de Marco Didio Falco', 1, '2004', 428, 'The Accusers', 'media/core/9788435061001.jpg', 1, '2023-04-15 07:34:00.354162', '2023-04-15 07:34:00.354162', 551, 16, 2, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Marco Didio Falco se encuentra de nuevo en Roma y se pone al servicio de Silio Itálico y Pacio Africano, dos abogados de creciente fama y riqueza en la capital del Imperio sobre cuyos métodos (que incluyen el chantaje) circulan todo tipo de rumores. El hallazgo del cadáver del senador Rubirio Metelo, en lo que a todas luces parece un suicidio, es el primer caso que cae en manos de Falco, pero como suele suceder en todos sus casos, nada es tan fácil y simple como parece. Novela con sorpresas y un desenlace inesperado, en la que la autora convierte Roma en una ciudad tan propicia para el crimen y la intriga como puedan serlo el Londres victoriano o Nueva York en nuestros días.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1393, '9788435060523', 'Un cadáver en los baños. La XIII novela de Marco Didio Falco', 1, '2001', 424, 'A Body in the Bath House', 'media/core/9788435060523.jpg', 1, '2023-04-15 07:37:50.583879', '2023-04-15 07:37:50.583879', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Esta vez en Britania, Maco deberá investigar una serie de extrañas muertes durante la construcción de un palacio. Los dardos irónicos de la gran escritora van dirigidos, en esta ocasión, al gremio de los arquitectos y constructores que hinchan desmesurada e injustificadamente los gastos y engañan a sus clientes. Para exclarecer el misterio Marco se convertirá en inspector de las obras y su asombro irá en aumento a medida que vaya conociendo los entresijos de la construcción. Una de las novelas más divertidas escritas hasta la fecha por Davis.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1394, '842264603X', 'La plata de Britania', 1, '1991', 317, 'The Silver Pigs', 'media/core/842264603X.jpeg', 1, '2023-04-15 07:44:26.462098', '2023-04-15 07:44:26.462098', 551, 16, 6, 5, NULL, '', '05_05', 'Marco Didio Falco', 93, 'Marco Didio Falco cree tener entre manos un trabajo sencillo, pero en realidad deberá enfrentarse a una compleja conspiración que pretende derribar al emperador Vespasiano. Vertiginoso y divertido relato policial en la Roma del siglo I. Disponible guía de lectura gratuita para profesores.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1395, '9788435061162', 'En busca de infamia. La XVI novela de Marco Didio Falco', 1, '2005', 430, 'Scandal takes a holiday', 'media/core/9788435061162.jpeg', 1, '2023-04-15 07:46:57.776749', '2023-04-15 07:46:57.776749', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'En esta ocasión el escenario de las correrías de Marco Didio Falco es la playa de Ostia, donde se retira con el propósito de hacer algunas visitas familiares y reposar, y el caso al que se enfrenta es la misteriosa desaparición de Infamia, un afamado comentarista de los amoríos y desventuras de los principales ciudadanos romanos. Por supuesto, es evidente que son muchos los que se benefician de esta oportuna desaparición, pero las indagaciones pronto ponen a Falco tras la pista de un enigmático pirata, y, al mismo tiempo, le ponen en contacto con un joven auriga, una muchacha de románticas ideas y toda una espléndida galería de secundarios, como es habitual en Lindsey Davis.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1396, '9788435005715', 'La estatua de bronce. La II novela de Marco Didio Falco', 1, '1992', 475, 'Shadows in Bronze', 'media/core/9788435005715.jpg', 1, '2023-04-15 07:53:09.104476', '2023-04-15 07:53:09.104476', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Un día cualquiera del año 70 a. C., sin acontecimientos especiales para un hombre como Marco Didio Falco: deshacerse de algún que otro cadáver, seguir la pista de un complot contra el emperador o conseguir algún pequeño beneficio traficando con plomo robado. Pero el trabajo rutinario del más sarcástico y desengañado investigador de la Roma Imperial da un vuelco cuando el azar le pone sobre el rastro de Barnadas, un extraño personaje que parece tener algo personal contra Didio Falco.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1397, '9788435005852', 'La Venus de cobre. La III novela de Marcos Didio Falco', 1, '1993', 357, 'Venus in Copper', 'media/core/9788435005852.jpg', 1, '2023-04-15 07:56:35.512663', '2023-04-15 07:56:35.512663', 551, 1, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Marco Didio Falco protagoniza una nueva entrega de sus aventuras en la antigua Roma. Esta vez sus problemas domésticos vienen a engrosar su ya compleja situación profesional, siempre sometida a los caprichos y mezquindades de Tito César.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1398, '9788435060745', 'El mito de Júpiter. La XIV novela de Marco Didio Falco', 1, '2003', 421, 'The Myth of Jupiter', 'media/core/sin-imagen_j1dQJXk.jpg', 1, '2023-04-15 08:01:40.355436', '2023-04-15 08:01:40.355436', 551, 16, 6, 5, 'Narrativas históricas', '', '05_05', 'Marco Didio Falco', 47, 'Londinium vuelve a ser el escenario de las correrías de Marco Didio Falco, per en esta ocasión ya no se trata de los ambientes palaciegos ni en el mundo de la construcción de su novela anterior (Un cadáver en los baños), sino de los barrios bajos de la ciudad. El momento de desarrollo y relativo esplendor que está experimentando la ciudad la convierten en un vivero de maleantes, estafadores y comerciantes sin escrúpulos y reina una sensación de inseguridad ciudadana un poco alarmante, que puede echa al traste con los proyectos del rey Togibundo. Las cosas se complican cuando empiezan a aparecer cadáveres, y, aprovechando que Falco se encuentra de vacaciones en la ciudad, se le encarga a él la investigación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1399, '9788497593793', 'It', 1, '1987', 1503, 'It', 'media/core/9788497593793.jpg', 1, '2023-04-15 09:57:31.158069', '2023-04-15 09:57:52.783305', 8, 12, 6, 5, 'Bestseller', '', '05_05', NULL, 11, '¿Quien o que mutila y mata a los niños de un pequeño pueblo norteamericano?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1400, '9788477020929', 'La Habitación de la Torre. 13 cuentos de fantasmas', 1, '2004', 227, 'The room in the Tower', 'media/core/9788477020929.jpg', 2, '2023-04-15 10:03:15.896598', '2023-04-15 10:54:29.558552', 870, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'E. F. Benson (1867-1940) fue, junto con M. R. James uno de los maestros victorianos de la «ghost story», un territorio del terror cuya exploración inició el gran escritor irlandés Joseph Sheridan Le Fanu. Benson y James pertenecían a la misma sociedad literaria de Cambridge, la Chitchat Society, y mantuvieron una buena relación durante cincuenta años. Al igual que James, Benson trata de alejarse de los escenarios clásicos de ruinas, pasadizos y tinieblas, para insertar el horror en las zonas más familiares de la vida cotidiana, donde acechan las fuerzas de lo desconocido. No obstante, los cuentos de Benson –menos eruditos, menos elusivos, tal vez más inquietantes que los del Dr. James– insisten en la exploración de las zonas más oscuras de la psique humana, los fenómenos extraños y el mundo de los sueños, y consiguen transmitir a través de una escritura controlada y llena de recursos su emoción preferida –también la nuestra–: el terror.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1401, '9788477020851', 'El Guardavías y otros cuentos de fantasmas', 1, '1993', 229, 'The Signalman', 'media/core/9788477020851.jpg', 1, '2023-04-15 10:06:19.073276', '2023-04-15 10:06:19.073276', 366, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'El interés de Charles Dickens (1812 - 1870) por lo gótico permaneció vivo a lo largo de su vida y, a pesar de que ha sido considerado tradicionalmente como un escritor realista, en los últimos tiempos se reconoce la importancia de los elementos macabros y sobrenaturales en su obra, en la cual se lleva hacia un mayor grado de sofisticación el retrato de la mente criminal, iluminando con ello aspectos hasta entonces no desvelados de la ficción.El crimen y los criminales, en cuanto que aberración de la conducta no como problema judicial siempre fascinaron a Dickens, como se puede apreciar en El manuscrito de un loco y Una confesión encontrada en una prisión de la época de Carlos II, incluidos en el presente volumen. Gran parte de los cuentos de fantasmas de Dickens están intercalados en sus novelas y son referidos por algún personaje inmerso en la trama; otros fueron publicados en Navidad, siguiendo la tradición victoriana de ocupar la velada de Nochebuena escuchando y contando historias de terror y de aparecidos. En todas ellas Dickens hace cómplice al lector, le sienta al amor de un buen fuego, y le hace beber de las fuentes del auténtico relato de tradición oral.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1402, '9788477020837', 'Dickon el Diablo y otros relatos extraordinarios', 1, '1993', 218, NULL, 'media/core/9788477020837.jpeg', 1, '2023-04-15 10:09:26.735714', '2023-04-15 10:09:26.735714', 871, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'Joseph Sheridan Le Fanu (1818-1873), heredero de la tradición gótica, nos ha legado una colección incomparable de relatos donde abundan los misterios escabrosos, las crónicas de fantasmas y el terror sobrenatural, mostrándose siempre como un maestro renovador del cuento de terror. Le Fanu es el verdadero iniciador de la «ghost story» contemporánea; imaginó una de las pesadillas más ilustres del género de vampiros: Carmilla, la fascinante mujer vampiro, y dio vida a un personaje singular: el doctor Martin Hesselius, que prefigura a los detectives ocultistas profesionales a la manera de Van Helsing –el cazavampiros de Drácula–, John Silence, el investigador de Algernon Blackwood, o Carnacki, el cazafantasmas de Hodgson.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1403, '9788477020356', 'Klosterheim, o la Mosca', 1, '1991', 220, 'Klosterheim or, The masque', 'media/core/9788477020356.jpg', 1, '2023-04-15 10:12:21.053682', '2023-04-15 10:12:21.053682', 872, 12, 2, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'La Guerra de los Treinta Años asola Europa.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1404, '9788477020363', 'Los Episodios de Vathek', 1, '1991', 187, 'Histoire du Prince Alasi et de la Pricesse Firouzkah / Histoire du Prince Barkiarokh', 'media/core/9788477020363.jpeg', 1, '2023-04-15 10:16:25.457738', '2023-04-15 10:16:25.457738', 873, 12, 2, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'Prefacio de Stéphane Mallarmé. Traducción y notas de Mauro Armiño. Tres días y dos noches bastaron a William Beckford (1760-1844)para escribir «Vathek» (1787), una rara obra maestra del horror gótico que adopta la forma de un cuento oriental.Heredero de una rica familia inglesa con plantaciones en Jamaica, Beckford recibió una esmerada educacióny se interesó por la música, la pintura y la literatura. Fue miembro del Parlamento inglés y siempre llevóun tren de vida excéntrico favorecido por sus riquezas: ordenó construir una fabulosa abadía neogótica en Fonthill.Beckford escribió «Vathek» en francés, como un cuento filosófico pero narrado al estilo de las «Mil y una noches», y pidió a su amigoel reverendo Samuel Henley que lo tradujera al inglés. Henley lo hizo y lo publicó con otro título sin menciónni permiso del autor, lo que obligó a Beckford a publicar al año siguiente la versión original con su título y autor.Esta urgencia dejó fuera de la edición varias historias que estaban inacabadas y que Beckford pensaba intercalaren el texto principal. Estos relatos, «Los episodios», no fueron redescubiertos y publicados hasta 1912.El califa Vathek es un tirano ávido de placeres tiene cinco palacios dedidados a los cinco sentidosy de conocimientos mágicos ha construido una torre para leer el destino en las estrell...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1405, '9788477025467', 'La maldición de la momia. Relatos de horror sobre el antiguo Egipto', 1, '2006', 652, NULL, 'media/core/9788477025467.jpg', 1, '2023-04-15 10:19:28.001952', '2023-04-15 10:19:28.017577', NULL, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, '«Querrías volver a poseerme, Demonio, pero te digo que no podrás, porque ya me llega el fin y diré a los matarifes del dios Shu: ¡Adelante!» Así concluye el Papiro de Nu,perteneciente a El libro de los muertos, que se conserva en el Museo Británico. La fascinación de la literatura fantásticaoccidental por la figura de la momia egipcia es la consecuencia del temor ancestral a los resucitados (vampiros, zombies...)unido al miedo por lo diferente y extraño: una cultura ya desaparecida, oriental y pagana. Lejos de ser un fantasma,la momia es un cadáver que regresa físicamente del más allá para atormentar a los vivos, un resucitado que viene a ajustarnoslas cuentas, dispuesto a hacernos daño, a acabar con nosotros de forma brutal. La maldición de la momia. Relatos de horror sobre el antiguo Egipto reúne veinte relatos y un poema,y es la primera recopilación en lengua castellana que se publica sobre tan apasionante mito literario (y cinematográfico).En ella el lector encontrará desde los grandes nombres de la narrativa fantástica como Arthur Conan Doyle,Sax Rohmer, Rudyard Kipling, Willa Carter o Robert Bloch, hasta sorprendentes incursiones en el género de conocidosocultistas como el Conde Louis de Hamon o C.W. Leadbeater. Todos ellos contribuyen a definir y engrandecer el mitode la momia, su poética, su trasfond...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1406, '9788477020783', 'Tres piezas góticas', 1, '1993', 241, 'The Castle of Otranto / The Castle Spectre / Zastrozzi', 'media/core/9788477020783.jpeg', 1, '2023-04-15 10:24:44.266515', '2023-04-15 10:24:44.266515', 874, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'En el presente volumen, número 10 de la colección Gótica, el aficionado encontrará tres obras pertenecientes al primer periodo gótico: El Castillo de Otranto, la novela fundacional del género, en la cual Walpole intentó restituir lo maravilloso y lo sobrenatural al reino de la ficción, ya que ambos habían sido desterrados del reino de lo real; El Espectro del Castillo, debida a El Monje (CD 4) (GOT 3) de Lewis, fue la primera representación de un drama gótico -en el Drury Lane Theatre de Londres en 1797-, e intenta llevar a la escena los mismos presupuestos estéticos de grandeza y terror que impregnan sus novelas, lo cual explica que el teatro gótico se convirtiera en un verdadero fenómeno de masas. Zastrozzi, obra de juventud del gran poeta romántico Percy Bysse Shelley, aporta al género gótico la singular figura del malvado Zastrozzi, que a pesar de ser condenado por la justicia, es descrito como un semidiós, como alguien que ha cumplido su destino de un modo consciente, no dando síntoma alguno de remordimiento o arrepentimiento, alcanzando en medio de sus crímenes una suprema inocencia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1407, '9788477020721', 'Cuentos Góticos', 1, '1993', 190, NULL, 'media/core/9788477020721.jpeg', 1, '2023-04-15 10:28:53.181913', '2023-04-15 10:28:53.181913', 875, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'En los Cuentos góticos Mary Shelley deja en claro sus sólidas maneras narrativas y la herencia cultural de su tiempo. Las historias de este volumen están envueltas en un ambiente romántico y tratan de describir caracteres cuyo elemento más significativo es el estar sometido a la influencia de fuertes pasiones, que a veces dan pie a sucesos sobrenaturales o extraordinarios en extremo, o son el producto de este tipo de acontecimientos. El libro se compone de ocho narraciones breves que se desarrollan en ambientes misteriosos, tenebrosos, lúgubres en algunos casos. Sin bien todos los cuentos tienen ciertas características afines, podemos separarlos por temáticas y grupos: están, por un lado, los cuentos sobre resurrecciones y su relación con el tiempo, tales como “Roger Dodsworth. El inglés reanimado”, “Valerio. El romano reanimado” y “El mortal inmortal”; del otro, subsisten los cuentos puramente románticos y góticos: “Ferdinando Eboli”, “Historia de Pasiones”, “La transformación”, “El sueño” y “El heredero de Mondolfo”. Cada una de las historias es una buena representación de lo que es el verdadero género gótico dentro de la literatura, pues en todas ellas abundan sus elementos más representativos: castillos en ruinas, personajes enajenados por sus más profundos sentimientos, un ambiente meramente medieval, calabozos, mazmorras, torreones y situaciones fantásticas e irreales que parecen salidas de los sueños más locos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1408, '9788477020509', 'Wieland, o la Transformación', 1, '1992', 228, 'Wieland, or The Transformation Memoirs of Carwin, the Biloquist', 'media/core/9788477020509.jpg', 1, '2023-04-15 10:32:10.865983', '2023-04-15 10:32:10.865983', 876, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'Charles Brockden Brown (1771-1810) fue elprimer escritor profesional americano, y Wieland o La Transformación-su primera novela (1798)-, además de ser un incomparable relatode «terror gótico», constituye el primer esfuerzo porcrear una literatura americana sólida. MaryShelley, cuyo espíritu armonizaba completamente con las creacionesde Brown, encontró en el personaje de Carwin, un precedentepara Frankenstein. En una tierra desprovistade castillos y fantasmas -pero saturada de teocracia puritana y fanatismoreligioso- Brown encontró materia para construir un relatogótico, recreando la extraña historia de un granjero, presade una locura maníaca, que asesina sin piedad a su familia obedeciendoun inescrutable mandato divino. Directamente implicado en esta siniestratrama, destaca el personaje de Carwin, «el biloquista»,un ser dotado de una facultad afín a la ventriloquía quele permite proyectar su voz a distancia, creando así un efecto debilocación.La presente edición de Wieland se completa conLasMemorias de Carwin, el biloquista, un relato donde Carwincuenta las circunstancias de su propia historia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1409, '9788477020479', 'El Monje', 1, '1991', 308, 'The Monk', 'media/core/9788477020479.jpeg', 1, '2023-04-15 10:34:59.460391', '2023-04-15 10:34:59.460391', 877, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'EL MONJEINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1410, '9788477021292', 'Zanoni, o el secreto de los inmortales', 1, '1995', 311, 'Zanoni', 'media/core/9788477021292.jpg', 1, '2023-04-15 10:39:26.580847', '2023-04-15 10:39:26.580847', 737, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'Edward Bulwer Lytton, el célebre autor de Los últimos días de Pompeya, realizó algunassobresalientes incursiones en la literatura fantástica, como Zanoni o A Strange Story. La larga sombra del vampiro ha oscurecido a losdemás inmortales góticos, como Fausto, el Judío Errante, o Zanoni, el cual pertenece a una sociedad secreta -más antiguaque los Rosacruces- que utilizaba el poder de la vida eterna para buenos propósitos. El personaje central de la narración es un sermisterioso, de origen desconocido, de quien se cuentan cosas extraordinarias, que vive consagrado a sus estudios herméticos hasta que se enamorade la bella Viola Pisani, ídolo de la ópera de Nápoles. Desde ese momento, los amantes estarán sometidos a toda suerte devicisitudes; un drama mágico que concluye durante los días del Terror, bajo el imperio de Robespierre y la sombra ominosa de la guillotina.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1411, '9788477021094', 'El Golem', 1, '1994', 204, 'Der Golem', 'media/core/9788477021094.jpeg', 1, '2023-04-15 10:53:25.162389', '2023-04-15 10:53:25.162389', 878, 12, 6, 5, 'Valdemar Gótica', '', '05_05', NULL, 24, 'https://es.wikipedia.org/wiki/El_Golem', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1412, '9788477020547', 'Antología española de Literatura Fantástica', 1, '1992', 543, NULL, 'media/core/9788477020547.jpeg', 1, '2023-04-15 10:56:56.442815', '2023-04-15 10:56:56.442815', NULL, 12, 6, 5, NULL, '', '05_05', NULL, 24, 'Los más de cincuenta autores y cien relatos que configuran esta Antología española de literatura fantástica --la antología temática más completa y ambiciosa realizada hasta la fecha-- pretenden alumbrar hacia un brumoso mundo de sueños forjados en el trastero de nuestras letras, que no ha sido pródiga en fabulaciones fantásticas... tal vez porque al español no le ha bastado imaginar mundos fantásticos, sino que ha necesitado también vivirlos; y lo que llevó en 1605 a un hidalgo aburrido a combatir lanza en ristre frente a unos molinos, no fue tanto la locura o los libros como la necesidad imperiosa de buscar, lejos del mezquino rincón, un horizonte más noble a su mirada... el mismo horizonte que, un siglo atrás, había impulsado hacia la quimera de América a los soberbios vagabundos que un día dejaron su patria por el mar. De los autores, veintiuno corresponden al periodo que va desde el siglo XIII al XIX, y treinta al XX, dado que el verdadero desarrollo del género pertenece a los últimos tiempos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1413, '9788477026853', 'El Monje', 2, '2011', 501, NULL, 'media/core/9788477026853.jpg', 1, '2023-04-15 11:03:58.595012', '2023-04-15 11:03:58.595012', 877, 12, 6, 5, 'El club Diógenes', '', '05_05', NULL, 24, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1414, '9788477226260', 'Engendro de la muerte', 1, '1992', 458, 'Deadspawn', 'media/core/9788477226260.jpg', 1, '2023-04-15 11:08:34.579981', '2023-04-15 11:08:34.579981', 879, 12, 6, 5, 'Fantasía Terror', '', '05_05', 'Crónicas necrománticas Vol 5', 9, 'El Habitante ha despojado a Harry Keogh de su necrolenguaje. Ya no puede hablar con los muertos y es casi un hombre normal, lo que para él es como sufrir una lobotomía. En su incapacitada mente se encuentran todos los secretos de la Gran Mayoría y las fórmulas matemáticas que rigen el continuo de Möbius. Y ahora, otro monstruoso muerto viviente acecha al mundo y está dispuesto a robarle sus poderes metafísico prohibidos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1415, '9788477226253', 'El lenguaje de los muertos', 1, '1992', 446, 'Deadspeak', 'media/core/9788477226253.jpg', 1, '2023-04-15 11:12:24.640555', '2023-04-15 11:13:16.337599', 879, 12, 6, 5, 'Fantasía Terror', '', '05_05', 'Crónicas necrománticas Vol 4', 9, 'En las montañas de los Balcanes se alza el castillo de los Ferenczy, la fortaleza de los wamphyri. En él, Janos Ferenczy, vampiro y hechicero, ha despertado de su sueño de siglos. Para calmar sus deseos de sangre necesita seres humanos vivos y con sus terribles armas pretende aplastar a la indefensa humanidad que ha depositado en Harry Keogh sus esperanzas de salvación. Pero Harry ha perdido su facultad de comunicarse con los muertos y los numerosos gritos de advertencia procedentes del más allá caen en el vacío.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1416, '9788477225669', 'El origen del mal', 1, '1991', 447, 'The Source', 'media/core/9788477225669.jpeg', 1, '2023-04-15 11:16:33.884774', '2023-04-15 11:16:33.884774', 879, 12, 6, 5, 'Fantasía Terror', '', '05_05', 'Crónicas necrománticas Vol 3', 9, 'La invasión de la Tierra por un ejercito de seres mostruoso podría producir espeluznantes reacciones. Sin embargo, sería muchísimo peor si esos invasores fueran además...¡vampiros! El nigromante Harry Keogh ha descubierto que los científicos sovieticos han abierto, sin querer, una puerta hacia la peor de las pesadillas que puede imaginar la humanidad. La fuente de todas las leyendas negras se hace accesible para todo aquel que se atreva a cruzar la Puerta. Y tambien para algunos que no se atreven...,pero que no tienen más remedio que cruzarla.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1417, '9788477225652', '¡Vampiros!', 1, '1991', 408, 'Wamphyri!', 'media/core/9788477225652.jpeg', 1, '2023-04-15 11:21:52.611180', '2023-04-15 11:21:52.611180', 879, 12, 6, 5, 'Fantasía Terror', '', '05_05', 'Crónicas necrománticas Vol 2', 9, 'Seres enterrados y que piensan...pero cuyos pensamientos sólo pueden expresar a través de Harry Keogh, el necroscopio. Ésa es la facultad de Harry, y también su carga, pues a veces los no-muertos piensan cosas incocebibles. Harry Keogh ha vencido por fin al nigromante y ampiro Boris Dragosani, aliado de la peor facción de la KGB soviética. Pero en la batalla, Harry ha perdido, si no la vida, al menos la corporeidad. Ahora es una mente, o alma, descarnada y prisionera del continuo metafísico de Möbius, por el que deambula comunicándose con vampiros y almas errantes de ese mismo ámbito. En este estado, Harry debe enfrentarse a un nuevo enemigo, Yulian Bodescu, un joven vampiro corrompido que siente una extra necesidad: descubrir a su verdadero padre y difundir su obra en el extranjero.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1418, '9788477225645', 'El que habla con los muertos', 1, '1990', 420, 'Necroscope', 'media/core/9788477225645.jpg', 1, '2023-04-15 11:24:22.985702', '2023-04-15 11:24:22.985702', 879, 12, 6, 5, 'Fantasía Terror', '', '05_05', 'Crónicas necrománticas Vol 1', 9, 'Un terrible demonio se encuentra en los Balcanes, en Rumania. Enterrado desde hace siglos en suelo consagrado, aprisionado por cadenas de plata y por la tierra, el vampiro urde siniestras conspiraciones. Boris Dragosani es utilizado por los servicios secretos rusos como el humano intermediario del vampiro. Dragosani está deseoso de explorar la insondable maldad del vampiro, y este le enseñará las horribles artes de la nigromancia, otorgándole la capacidad de arrancar todos los secretos de la mente y el cuerpo de los muertos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1419, '9788483838778', 'Catalanes todos', 1, '2014', 334, NULL, 'media/core/9788483838778.jpg', 1, '2023-04-15 11:27:24.977149', '2023-04-15 11:27:24.977149', 13, 1, 6, 5, 'Colección Andanzas', '', '05_05', NULL, 12, 'El miserable Juanito Oliva, el siniestro Santiago Salvatierra, el cura Leopoldo Roca, la medium Ramona Codolls, el pragmático Jose Batiste, el sórdido Jaime Casellas, el novillero Alfonso Matagalls..., y otros más, forman un heterogeneo grupo de catalanes que se conocen en el ejercito de Franco durante la guerra civil. Al volver a Barcelona, tras la caída de la ciudad, las peripecias de cada uno se cruzan en una trama agria y sarcástica a traves de la cual se muestra cómo cambia la sociedad a lo largo de los últimos 75 años. Tambien evolucionan los protagonistas del libro, y algunos se verán convertidos en símbolos universales. Catalanes todos recorre varios momentos de la dictadura en Barcelona, de la transición y de las manifestaciones históricas reclamando el Estatut o la independencia. Pero lo hace empleando el humor más mordaz y los tipos más representativos, las escenas más descacharrantes, pero con certeras cargas críticas de profundidad. Las crónicas de alta sociedad, las visitas de Franco, los negocios de unos y las penurias de otros, desfilan en la novela para entender la vida real de una ciudad muy distinta a como algunos quisieran recordar.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1420, '9788483833988', 'Paseos con mi madre', 1, '2011', 179, NULL, 'media/core/9788483833988.jpeg', 1, '2023-04-15 11:29:11.341838', '2023-04-15 11:29:11.341838', 13, 1, 6, 5, 'Colección Andanzas', '', '05_05', NULL, 12, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1421, '9788420407098', 'El puente de los asesinos', 1, '2011', 353, NULL, 'media/core/9788420407098.jpg', 1, '2023-04-15 11:33:52.809062', '2025-09-03 11:39:09.788087', 73, 1, 6, 5, NULL, '', '05_05', 'Las aventuras del Capitán Alatriste VII', 10, 'La septima entrega de "Las aventuras del capitán Alatriste". Cruza el puente de los Asesinos con Arturo Perez-Reverte y vive la trepidante conspiración para asesinar al dogo de Venecia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1422, '9788420471013', 'Corsarios de levante', 1, '2006', 348, NULL, 'media/core/9788420471013.jpg', 1, '2023-04-15 11:36:18.857264', '2025-09-04 09:13:26.681469', 73, 1, 2, 5, NULL, '', '05_05', 'Las aventuras del Capitán Alatriste VI', 10, 'En esta sexta entrega de «Las aventuras del capitán Alatriste» la acción transcurre de las costas de Berbería a las bocas de Constantinopla: desembarcos, saqueos, abordajes, corsarios, piratas y esclavos, cuando el Mediterráneo era un mar español.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1423, '9788420400211', 'El caballeo del jubón amarillo', 1, '2003', 348, NULL, 'media/core/9788420400211.jpg', 1, '2023-04-15 12:08:01.195422', '2025-09-04 09:11:02.686010', 73, 1, 6, 5, NULL, '', '05_05', 'Las aventuras del Capitán Alatriste V', 10, 'En esta quinta entrega de «Las aventuras del capitán Alatriste» Diego Alatriste e Íñigo Balboa se enfrentarán entre estocadas e intrigas palaciegas a una conspiración en la corte de Felipe IV.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1424, '9788422690139', 'El oro del Rey', 1, '2000', 267, NULL, 'media/core/9788422690139.jpg', 1, '2023-04-15 12:10:51.767833', '2025-09-04 09:11:20.867567', 73, 1, 2, 5, NULL, '', '05_05', 'Las aventuras del Capitán Alatriste IV', 5, 'Sevilla, 1626. A su regreso de Flandes, donde han participado en el asedio y rendición de Breda, el capitán Alatriste y el joven mochilero Íñigo Balboa reciben el encargo de reclutar a un pintoresco grupo de bravos espadachines para una peligrosa misión, relacionada con el contrabando del oro que los galeones españoles traen de las Indias. Los bajos fondos de la turbulenta ciudad andaluza, el corral de los Naranjos, la cárcel real, las tabernas de Triana, los arenales del Guadalquivir, son los escenarios de esta nueva aventura, donde los protagonistas reencontrarán traiciones, lances y estocadas, en compañía de viejos amigos y de viejos enemigos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1425, '9788422679233', 'El sol de Breda', 1, '1998', 254, NULL, 'media/core/9788422679233.jpeg', 1, '2023-04-15 12:12:59.408362', '2025-09-04 09:11:50.152817', 73, 1, 6, 5, NULL, '', '05_05', 'Las aventuras del Capitán Alatriste III', 5, 'En esta tercera entrega de «Las aventuras del capitán Alatriste» se escenifican las batallas y el asedio de la ciudad de Breda en 1625 por los tercios españoles en Flandes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1426, '9788422672531', 'Limpieza de sangre', 1, '1997', 253, NULL, 'media/core/9788422672531.jpeg', 1, '2023-04-15 12:16:59.320257', '2025-09-04 09:12:16.754595', 73, 1, 6, 5, NULL, '', '05_05', 'Las aventuras del Capitán Alatriste II', 5, 'En esta segunda entrega de «Las aventuras del capitán Alatriste» la trama pondrá en juego la vida de los amigos del capitán, haciendo surgir del pasado los fantasmas de viejos enemigos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1427, '9788422666776', 'El Capitán Alatriste', 1, '1996', 237, NULL, 'media/core/9788422666776.jpg', 1, '2023-04-15 12:19:15.143811', '2025-09-03 11:36:09.075955', 73, 1, 6, 5, NULL, '', '05_05', 'Las aventuras del Capitán Alatriste I', 5, 'Acción, historia y aventura se dan cita como un torbellino en las inolvidables páginas de esta primera noveladela serie «Las aventuras del capitán Alatriste», que comienza cuando el valeroso protagonista acepta un peligroso encargo...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1428, '9788401325229', 'El infiltrado', 1, '1993', 536, 'The night manager', 'media/core/9788401325229.jpeg', 1, '2023-04-15 12:22:06.082541', '2023-04-15 12:22:06.082541', 559, 1, 6, 5, NULL, '', '05_05', NULL, 17, 'Pine es un soldado veterano de pasado oscuro que acepta incorporarse alservicio de inteligencia británico con la misión de introducirse en elmundo de Dicky Roper, un traficante internacional de armas que tiene sucentro de acción en una isla del Caribe. Tras varias peripecias que lellevarán a El Cairo, a Suiza y a Cornualles para mezclarse contraficantes menores, los servivios secretos secuestran al hijo de Ropersolo para que Pine lo salve y pueda acceder, al fin, a la isla privadadel traficante, quien no tardará demasiado en descubrir para quiéntrabaja realmente Pine.. Plenamente consciente del cambio de los centros de poder desde 1990, LeCarré ha creado un nuevo personaje similar al mítico Smiley paraprotagonizar esta novela, construida en flash back desde los recuerdosde Pine, en un escenario donde las rivalidades entre las grandespotencias han sido suplantadas por organizaciones criminales que sededican al contrabando de armas y al tráfico de drogas, y cuyos voracestentáculos llegan a todos los estamentos sociales y políticos...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1429, '9788401385285', 'Nuestro juego', 1, '1995', 372, 'Our game', 'media/core/9788401385285.jpg', 1, '2023-04-15 12:24:44.468559', '2023-04-15 12:24:44.468559', 559, 1, 6, 5, NULL, '', '05_05', NULL, 17, 'NUESTRO JUEGOINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1430, '9788483651568', 'El jardín olvidado', 18, '2012', 537, NULL, 'media/core/9788483651568.jpg', 1, '2023-04-15 12:26:44.612724', '2023-04-15 12:26:44.612724', 661, 1, 6, 5, NULL, '', '05_05', NULL, 27, 'En vísperas de la Primera Guerra Mundial una niña es abandonada en un barco con destino a Australia. Una misteriosa mujer llamada La Autora ha prometido cuidar de ella, pero desaparece sin dejar rastro...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1431, '9788484607915', 'El tiempo entre costuras', 1, '2011', 631, NULL, 'media/core/9788484607915.jpg', 1, '2023-04-15 12:30:25.489284', '2023-04-15 12:30:25.489284', 204, 1, 6, 5, 'TH novela', '', '05_05', NULL, 26, 'La joven modista Sira Quiroga abandona Madrid en los meses convulsos previos al alzamiento arrastrada por el amor des­ bocado hacia un hombre a quien apenas conoce. Juntos se instalan en Tánger, una ciudad mundana, exótica y vibrante en la que todo lo impensable puede hacerse realidad. Incluso la traición y el abandono de la persona en quien ha depositado toda su confianza. El tiempo entre costuras es una aventu­ ra apasionante en la que los talleres de alta costura, el glamur de los grandes hoteles, las conspiraciones políticas y las oscuras misiones de los servicios secre­ tos se funden con la lealtad hacia aque­ llos a quienes queremos y con el poder irrefrenable del amor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1432, '9788480900478', 'Cerdanya 1:50000', 1, '2022', 1, NULL, 'media/core/sin-imagen_BC2BWxe.jpg', 1, '2023-04-16 06:33:59.540163', '2023-04-16 06:34:55.584185', NULL, 42, 6, 5, NULL, '', '04_06', NULL, 268, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1433, '8421606891', 'Elementos de dibujo lineal', 14, '1973', 1, NULL, 'media/core/8421606891.jpg', 1, '2023-04-16 06:46:57.488333', '2023-04-16 06:46:57.488333', 881, 38, 6, 5, NULL, '', '05_06', NULL, 298, '', '');
