INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1436, '9771579337002', 'Vanguardia Dossier. Agua el desafio del siglo XXI', 1, '2006', 1, NULL, 'media/core/9771579337002.jpg', 1, '2023-04-16 07:00:52.335190', '2023-04-16 07:00:52.335190', 572, 43, 6, 5, NULL, '', '05_06', 'Número 21 Octubre/Dicembre 2006', 43, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1437, 'B00F7UQSD6', '(Fotocopia) El cuento de las naciones. Tabla rasa del gran debate español', 1, '2017', 269, NULL, 'media/core/sin-imagen_CmwcpQj.jpg', 1, '2023-04-16 07:08:47.662756', '2025-05-09 10:09:29.088340', 882, 2, 6, 5, NULL, '', '05_06', NULL, NULL, 'La apuesta independentista del Gobierno catalán y, en menor medida, la del vasco, auguran que el debate nacional siempre latente en España ha de hacer crisis y resolverse de una forma u otra en los próximos meses.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1438, 'MyT_1', 'Curso M&T de tecnología musical. Sonido, acústica y psicoacústica', 1, NULL, 1, NULL, 'media/core/sin-imagen_4SX6qDX.jpg', 1, '2023-04-16 07:23:13.618803', '2023-04-19 08:08:53.341448', 883, 38, 6, 5, NULL, '', '05_06', 'Manual 1', 300, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1439, 'MyT_2_3', 'Curso M&T de tecnología musical. Principios de síntesis / Generación analógica', 1, NULL, 1, NULL, 'media/core/sin-imagen_TVaP3Ty.jpg', 1, '2023-04-16 07:24:40.571601', '2023-04-19 08:08:37.098146', NULL, 38, 6, 5, NULL, '', '05_06', 'Manuales 2 y 3', 300, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1440, '0881885584', 'The MIDI implementation book', 1, '1986', 1, NULL, 'media/core/sin-imagen_EBVYllp.jpg', 1, '2023-04-16 07:28:39.473280', '2023-04-19 08:07:59.733249', 884, 38, 6, 5, NULL, '', '05_06', NULL, 301, 'The complete collection of every MIDI implementation charge (the industry standard method for showing an instrument''s MIDI features) ever produced! This is a collection of data supplied directly from the manufacturers which allows you to find MIDI functions for a specific instrument, compare features of similar instruments or find equipment to solve specific MIDI problems. This book lists the complete MIDI capabilities of more than 200 MIDI products from virtually every MIDI manufacturer in the world.', '');
