INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1462, 'B27449', 'Viaje a La Alcarría', 1, '1966', 1, '255', 'media/core/B27449.jpg', 1, '2023-04-17 07:41:59.161918', '2023-04-17 07:41:59.161918', 832, 1, 6, 5, NULL, '', '04_07', NULL, 10, 'Con el morral a la espalda y la cantimplora sujeta a la hebilla del cinturón, el viajero recorre las carreteras y los pueblos de la Alcarria. Es el suyo un caminar lento, con mañanas de atmósfera limpia, mediodías calurosos y noches que se le echan encima, como con susto. De pueblo en pueblo el viajero va viviendo curiosos encuentros, minúsculas anécdotas y sorprendentes conversaciones que, impertérrito, transcribe con una suave prosa que aúna realismo, comicidad y ternura. Pero el viaje termina. El viajero dejó atrás la Alcarria con sus notas a cuestas y un algo de pena. A cambio, nos queda un libro que demuestra una de las más arraigadas afirmaciones de Cela: «El escritor, aun el que más sedentario pudiera parecer, es siempre un irredento vagabundo y ése es su mayor timbre de gloria y libertad».', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1463, 'B1998', 'La familia de Pascual Duarte', 1, '1968', 203, NULL, 'media/core/B1998.jpg', 1, '2023-04-17 07:44:54.772210', '2023-04-17 07:44:54.772210', 832, 1, 6, 5, NULL, '', '04_07', NULL, 10, 'Publicada inicialmente en 1942, La familia de Pascual Duarte marca un hito decisivo en la literatura española y es, después del Quijote, el libro español más traducido a otras lenguas. Pascual Duarte, campesino extremeño hijo de un alcohólico, nos cuenta su vida mientras espera su propia ejecución en la celda de los condenados a muerte. Víctima de una inexorable fatalidad, Pascual Duarte es un ser primitivo y elemental dominado por la violencia, única respuesta que conoce a la traición y al engaño. Pero esa siniestra apariencia no es más que la máscara que oculta su incapacidad para luchar contra la maldad de los demás y la desvalida impotencia que alberga en el fondo de su alma. La familia de Pascual Duarte ha ganado con los años fuerza y dramatismo y su protagonista, que no ha perdido el encanto primigenio, es ya un arquetipo de alcance universal.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1464, 'B33314', 'La colmena', 1, '1966', 258, NULL, 'media/core/B33314.jpg', 1, '2023-04-17 07:47:55.053299', '2023-04-17 07:47:55.053299', 832, 1, 6, 5, NULL, '', '04_07', NULL, 10, 'La colmena, seguramente la obra más valiosa de Camilo José Cela, es un testimonio fiel de la vida cotidiana en las calles, cafés y alcobas de aquel Madrid de 1943, pero es también una amarga crónica existencial. Un aire de rutina y fatalidad ha invadido la conciencia de las gentes. Todos creen que las cosas pasan porque sí y que nada tiene remedio. Entre la abigarrada multitud se oye el solitario zumbido de muchos seres confusos y a la deriva. Como es habitual en su obra, Cela presenta la vida española sin piedad, con agria ironía y humorismo atroz. Sin embargo, de vez en cuando, un soplo compasivo alivia la áspera y dolorida realidad. Eduardo Alonso, que ha preparado esta edición, es novelista y profesor de literatura.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1465, '848519702X', 'Libro de Buen Amor', 1, '1975', 222, NULL, 'media/core/848519702X.jpg', 1, '2023-04-17 07:53:49.982282', '2023-04-17 07:58:33.381832', 901, 30, 6, 5, NULL, '', '04_07', 'Tomo II', 317, 'https://es.wikipedia.org/wiki/Libro_de_buen_amor', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1466, '8485197011', 'Libro de Buen Amor', 1, '1975', 1, NULL, 'media/core/8485197011.jpg', 1, '2023-04-17 07:57:28.936762', '2023-04-17 07:57:28.936762', 901, 30, 6, 5, NULL, '', '04_07', 'Tomo I', 317, 'El libro de buen amor pertenece al Mester de Clerecía del siglo XIV, compuesto entre los años 1330 y 1343. Es decir, que se compone de versos irregulares que no siempre se avienen a las conveniencias del movimiento. Sería más bien una miscelánea que incluye canciones, fábulas y sermones. Pero sí es cierto que, al tratarse de diversas historias, los juglares podían aprender y recitar partes del libro con mayor comodidad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1467, '9788419013231', 'Cants', 1, '2006', 107, NULL, 'media/core/9788419013231.jpg', 1, '2023-04-18 16:23:16.448659', '2023-04-18 16:23:16.448659', 902, 4, 6, 5, 'Clàssics de Grècia i Roma', '', '06_02', NULL, 11, 'Cants de Safo es una obra precursora i representa un model per a les escriptores que la van seguir, en tant que l''autora hi crea un llenguatge nou per expressar l''amor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1468, '9788418059223', 'El Cuáquero', 1, '2022', 480, 'The Quaker', 'media/core/9788418059223.jpg', 1, '2023-04-18 16:26:37.971565', '2023-04-18 16:26:37.971565', 903, 14, 6, 5, 'Catedral NOIR', '', '06_02', NULL, 318, 'Una ciudad presa del miedo. Un asesino en serie. Un inspector con todo por demostrar.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1469, '9788419179968', 'Hazañas de un joven Don Juan // La once mil vergas', 1, '2022', 248, 'Les Trois Don JUan // Les Onze Mille Verger ou les Amours d''un hospodar', 'media/core/9788419179968.jpg', 1, '2023-04-18 16:32:36.016460', '2023-04-18 16:32:36.016460', 904, 44, 6, 5, NULL, '', '06_02', NULL, 38, 'Los dos relatos que publicamos, el mítico Las once mil vergas y Las hazañas de un joven don Juan, que datan de 1907 y de 1911, son dos himnos a la virilidad y al placer; catálogos asombrosos de todas las prácticas, desviaciones y orientaciones sexuales que ofrecen, de forma burlesca, sexo «bruto» envuelto en las obsesiones y fantasías del poeta. Al hacerlo, nos permiten hacernos preguntas y criticar los valores y la violencia del sistema al que pertenecen: el de la dominación masculina. En este sentido, constituyen documentos excepcionales y únicos de su tiempo. En Las hazañas de un joven don Juan, Roger se marcha de vacaciones a su castillo en el campo, donde fornicará con todas las mujeres de su familia y con casi todas las del servicio. Es todo un inventario de depravaciones que más bien parece escrito para ironizar sobre la literatura pornográfica y sobre los vicios de la sociedad francesa. En Las once mil vergas se narra la historia de Mony Vibescu, un príncipe rumano que va a París en busca de aventuras. Allí conocerá a la prostituta Culculine dAncône. Tras su regreso a Bucarest, se le invita a participar en la guerra ruso-japonesa como teniente ruso y aceptará motivado por las «perversiones» que una guerra es capaz de proporcionar y encubrir. Guillaume Apollinaire, que fue uno de los primeros en inventariar las obras de "el infiernillo" de la Biblioteca Nacional, se ha convertido, por propio derecho, en uno de los máximos exponentes de la literatura erótico-pornográfica de todos los tiempos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1470, '9788417442590', 'Los fabulosos Freak Brothers', 1, '2020', 152, 'The Fabulous Furry Freak Brothers', 'media/core/9788417442590.jpg', 1, '2023-04-18 16:36:43.930762', '2023-04-18 17:52:11.287812', 368, 34, 6, 5, NULL, '', '02_05', 'Tomo 2', 136, 'Libro de historietas encuadernado en rústica de 152 páginas interiores en blanco y negro más cubioertas en color que contiene el primer voluemen de la edición integral de las aventuras de Los Fabulosos Freak Brothers publicadas en la prensa norteamericana por Ripp Off press. La historia del cómic está llena de parejas de éxito, pero trío sólo hay uno y lo forman Fat Freddy, Freewheelin Franklin y Phineas Freakers, los fabulosos Freak Brothers. Pese a que basan su existencia en la ley del mínimo esfuerzo, los tres barandas creados por Gilbert Shelton se verán involucrados en las situaciones más estrafalarias y protagonizarán los viajes más chungos imaginables, peripecias sensacionales siempre sazonadas con mandanga de la buena y cachondeo fundamental. Cincuenta años viviendo al límite. Una epopeya alucinógena que atraviesa el siglo contra viento y marea y que cincuenta años después sigue siendo emblema de libertad. El talento de Gilbert Shelton comenzó a despuntar bien temprano, con la aparición por primera vez en 1959 de Superserdo (Wonder Warthog) en una revista universitaria. Su devastadora parodia de la figura del superhéroe se convertiría con el tiempo en un clásico que a día de hoy sigue reeditándose, sólo superado por Los fabulosos Freak Brothers y su gato Freddy, publicados por primera vez en 1969 y consolidados como uno de los baluartes del underground yanqui. A través de los años, Shelton ha seguido creando cómics donde el sentido del humor corrosivo y la acción supersónica se dan la mano. A día de hoy, afincado en París y en estrecha colaboración con Pic, Shelton sigue trabajando incansable en Not Quite Dead, una serie de historietas cortas sobre un trasnochado grupo de rock que viene apareciendo en diversas publicaciones de cómic de todo el mundo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1471, '9788418809316', 'Los fabulosos Freak Brothers', 1, '2022', 144, 'The Fabolous Furry Freak Brothers', 'media/core/9788418809316.jpg', 1, '2023-04-18 16:39:00.995332', '2023-04-18 17:52:43.186943', 368, 34, 6, 5, NULL, '', '02_05', 'Tomo 3', 136, 'Marrulleros, haraganes, politoxicómanos, antisistema, inútiles por vocación y, al n y al cabo, personas corrientes, interesadas por el béisbol, la música, los derechos sociales, la televisión, otra calada, la abolición del trabajo y el futuro de la humanidad. Clásicos por excelencia de la historieta underground, triposa y contracultural, Fat Freddy, Freewheelin Franklin y Phineas Freakears están a punto de levantar el culo del sofá para dar la vuelta al mundo en este tercer volumen de sus aventuras completas. Medio siglo conviviendo y todavía no han perdido la ilusión! Un material de primera! El talento de Gilbert Shelton comenzó a despuntar bien temprano, con la aparición por primera vez en 1959 de Superserdo (Wonder Warthog) en una revista universitaria. Su devastadora paro dia de la fi gura del superhéroe se convertiría con el tiempo en un clásico que a día de hoy sigue reeditándose, sólo superado por Los fabulosos Freak Brothers y su gato Freddy, publicados por primera vez en 1969 y consolidados como uno de los baluartes del underground yanqui. A tra vés de los años, Shelton ha seguido creando cómics donde el sentido del humor corrosivo y la acción supersónica se dan la mano. A día de hoy, afi ncado en París y en estrecha colaboración con Pic, Shelton sigue trabajando incansable en Not Quite Dead, una serie de historietas cortas sobre un trasnochado grupo de rock que viene apareciendo en diversas publicaciones de cómic de todo el mundo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1472, '9788418008016', 'Azul', 1, '2020', 158, NULL, 'media/core/9788418008016.jpg', 2, '2023-04-18 16:41:47.575493', '2023-09-30 11:47:45.819324', 905, 44, 6, 5, 'Alma clásicos ilustrados', '', '06_02', NULL, 319, 'Rubén Darío es tal vez el máximo exponente del modernismo literario latinoamericano. Su estilo es rico en imágenes vivas y sugerentes, con una estética que nos remite tanto a paisajes orientales como a cuentos de hadas sirviéndose de una métrica precisa y un léxico altamente evocador. Escrito durante su estancia en Chile, Azul marcó la madurez personal y literaria del autor y lo dio a conocer en todo el mundo.', 'El otro ejemplar está en la habitación de Raquel 02_04R');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1474, '9788417858407', 'Romancero gitano', 1, '2021', 256, NULL, 'media/core/9788417858407.jpg', 1, '2023-04-18 16:45:25.409814', '2024-02-22 19:19:56.654185', 766, 4, 6, 5, NULL, '', '06_02', NULL, 320, 'Un clásico de la literatura española reinterpretado por uno de nuestros ilustradores contemporáneos más originales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1475, '9788467254983', 'La comida de la familia', 1, '2013', 388, NULL, 'media/core/9788467254983.jpeg', 1, '2023-04-18 16:48:48.284665', '2023-04-22 07:04:06.018822', 906, 47, 6, 5, NULL, '', '06_03', NULL, 101, 'elBulli es ya para siempre un referente gastronómico ineludible. La inventiva, sofi sticación, imaginación y tecnica de Ferran Adrià y su equipo han revolucionado la manera de entender la restauración. Pero ¿que comía diariamente la familia de elBulli? ¿Te has preguntado alguna vez que comen los grandes chefs? ¿Cómo es posible cocinar a diario para una brigada de 75 personas? ¿Quieres organizarte en casa como en un restaurante para tener el menú a punto en el momento de comer? Ferran Adrià ha reunido 31 menús equilibrados y sabrosos, con ingredientes frescos y elaboración cuidadísima pero fácil, para que tu familia, o la de un profesional, pueda aprovechar la experiencia del día a día en la cocina del mejor restaurante del mundo. Comer bien y variado es una necesidad que aporta calidad de vida, pero tambien es un placer. Gracias a este libro podrá planifi car diferentes menús para cada día de la semana.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1476, '9788467263817', 'El gran libro de las legumbres', 1, '2015', 235, NULL, 'media/core/9788467263817.jpeg', 1, '2023-04-18 16:53:58.014297', '2023-04-22 07:03:39.964593', 907, 47, 6, 5, NULL, '', '06_03', NULL, 321, 'El objetivo de este libro es el de convertirse en la biblia de los amantes de las legumbres. Dividido en siete capítulos (lentejas, garbanzos, judía blanca y verde, habas, guisante y un dedicado a otras legumbres), explica la historia, los beneficios, la conservación y la manera de cocinar estos alimentos, a traves de aproximadamente 200 recetas. "Con la colaboración del Departament de Cultura de la Generalitat"', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1477, '9788467055207', 'El rayo que no cesa', 1, '2019', 112, NULL, 'media/core/9788467055207.jpg', 1, '2023-04-18 16:56:17.700882', '2023-04-18 16:56:17.700882', 100, 4, 6, 5, NULL, '', '06_02', NULL, 265, 'Uno de los más conmovedores libros de la poesía castellana contemporáneaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1478, '9788467265293', 'El caso de la modelo extraviada', 1, NULL, 1, NULL, 'media/core/9788467265293.jpg', 1, '2023-04-18 16:58:47.241848', '2023-04-18 16:58:47.241848', 96, 1, 6, 5, NULL, '', '06_02', NULL, 14, 'En la nueva novela de Eduardo Mendoza, El secreto de la modelo extraviada, el detective loco que protagonizó El misterio de la cripta embrujada, El laberinto de las aceitunas y recientemente El enredo de la bolsa y la vida recuerda un caso aparentemente cerrado de los ochenta y no ceja en su empeño de resolverlo más de veinte años después. El detective más divertido de la narrativa española nos cuenta aquí su doble aventura:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1479, '9788467274264', 'La muerte del comendador', 1, '2019', 496, NULL, 'media/core/sin-imagen_WslVXnz.jpg', 1, '2023-04-18 17:01:53.889279', '2023-04-18 17:01:53.889279', 243, 1, 6, 5, NULL, '', '06_02', 'Libro 2', 114, 'El trepidante y esperado desenlace de la novela más reciente de Haruki Murakami.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1480, '9788467243963', 'Las armas y las letras. Literatura y Guerra Civil (1936-1939)', 1, NULL, 1, NULL, 'media/core/9788467243963.jpeg', 1, '2023-04-18 17:05:32.399192', '2023-04-18 17:05:32.399192', 908, 2, 6, 5, NULL, '', '06_02', NULL, 58, 'Considerado ya un clásico, agotado y buscado como libro de culto, Las armas y las letras es una mirada libre, minuciosa y completa sobre la literatura en la guerra civil española. Desfi lan por estas páginas cientos de escritores en amenísimas y agudas semblanzas, el célebre y el desconocido, el audaz y el cobarde, el perseguido y el perseguidor, el activista y el silencioso o silenciado, el viejo y el joven, todos buscando para sí y para su tiempo una salvación que no siempre fue posible. Tratado de armas y de letras, pero sobre todo libro que cambió alguno de los prejuicios que más habían oxidado la literatura española. Andrés Trapiello consiguió darnos lo mejor de aquellos años en una historia que muchos leyeron y leerán como una apasionante novela, pero que es, además, una mirada tan veraz como misericordiosa, y tan necesaria como imprescindible.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1481, '9788401027055', 'Nunca', 1, '2021', 840, NULL, 'media/core/9788401027055.jpg', 1, '2023-04-18 17:08:16.508078', '2023-04-18 17:08:16.508078', 197, 1, 6, 5, NULL, '', '06_02', NULL, 17, 'En el desierto del Sáhara, dos agentes de inteligencia siguen la pista a un poderoso grupo terrorista arriesgando sus vidas -y, cuando se enamoran perdidamente, sus carreras- a cada paso.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1482, '9788439730118', 'Lord Jim', 1, '2015', 448, 'Lord Jim', 'media/core/9788439730118.jpg', 1, '2023-04-18 17:26:26.793601', '2023-04-18 17:26:26.793601', 909, 1, 6, 5, 'Grandes clásico Literatura Random House', '', '06_02', NULL, 11, 'En Lord Jim, Marlowe, una de las creaciones cumbre de Conrad, relata a un grupo de atentos compañeros la tragedia de Jim, un hombre de mar que en cierto momento de su vida se ve traicionado por un fatal golpe de debilidad moral. A partir de entonces su existencia se convertirá en una despiadada lucha con su pasado, en un intento por alcanzar la redención.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1483, '9788439737322', 'Bajo el volcán', 1, '2020', 520, 'Under the Volcano', 'media/core/9788439737322.jpg', 1, '2023-04-18 17:29:04.894795', '2023-04-18 17:29:04.894795', 910, 1, 6, 5, 'Grandes clásico Literatura Random House', '', '06_02', NULL, 11, 'Es Día de Muertos y Geoffrey Firmin pasea por las cantinas de Quauhnáhuac mientras dos volcanes, el Popocatépetl y el Iztaccíhuatl, se asoman como trágico recordatorio de la crisis que tiene con Yvonne, quien acaba de regresar a México como último recurso para evitar la caída de su matrimonio y de Firmin, su esposo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1484, '8424935063', 'Romancero tradicional de las lenguas hispánicas (español-portugués-catalán-sefardí', 1, '1977', 254, NULL, 'media/core/sin-imagen_h0iNE8e.jpg', 1, '2023-04-18 17:33:16.492809', '2023-04-18 17:33:16.492809', NULL, 4, 6, 5, NULL, '', '06_02', NULL, 322, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1485, '9788430623402', 'El mundo de la Antigüedad tardía. De Marco Aurelio a Mahoma', 2, '2021', 268, 'The World of Late Antiquity', 'media/core/9788430623402.jpg', 1, '2023-04-18 17:36:42.793314', '2023-04-18 17:36:42.793314', 911, 11, 6, 5, 'Clásicos radicales', '', '06_02', NULL, 323, 'Con este extraordinario libro, Peter Brown acuñó para la posteridad el concepto de Antigüedad tardía, indispensable para entender la historia europea, al arrojar una mirada nueva sobre los cambios culturales, religiosos y sociales entre el 200 y el 700 d. C. Su visión, rica, colorida y alejada de la tan reiterada idea del declive y caída del imperio, muestra hasta qué punto este periodo crucial marcó profundamente la evolución divergente de Occidente y Oriente Próximo. Todavía vivimos los resultados de este profundo contraste.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1486, 'B963', 'Susy, "La pelirroja"', 1, '1971', 162, 'Susy Rodtop', 'media/core/B963.jpg', 1, '2023-04-19 08:30:11.983127', '2023-04-19 08:30:57.657785', 912, 48, 6, 5, NULL, '', '06_01', NULL, 324, '', '');
