INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1488, '9782070552481', 'Cendrillon', 1, '2003', 68, NULL, 'media/core/9782070552481.png', 1, '2023-04-19 08:37:05.887274', '2023-04-19 08:37:05.887274', 913, 27, 6, 5, NULL, '', '06_01', NULL, 293, 'Il était une fois une citrouille changée en carrosse tout doré... Il était une fois une princesse endormie pendant cent ans, réveillée par un prince charmant... Il était une fois une jeune fille dont les moindres mots se changeaient en joyaux... Il était une fois trois contes pour rêver et continuer de croire au pouvoir merveilleux des fées.', '');
