INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1613, '9788417978655', 'American Noir', 5, '2020', 331, 'The Best American Noir of the Century', 'media/core/9788417978655.jpg', 1, '2023-04-22 09:38:50.599514', '2023-04-22 10:41:55.380162', 572, 14, 6, 5, 'Navona_Ficciones', '', '06_06', NULL, 38, '"De entre todos los retoños que brotaron de la ficción hard-boiled, el genero negro es el más escrupulosamente estudiado. (…) La importancia social de lo negro radica en su capacidad para fundarse sobre los grandes temas de raza, clase, genero y corrupción sistemica. El júbilo dominante y el atractivo definitivo de lo negro consisten en hacer de la condena una diversión. (…) Lo negro no va a morir: nos brinda un divertimento demasiado demencial para no florecer en las mentes de los escritores modernos que desearían viajar en el tiempo para llegar a 1948 y vivir el malestar general y la psicosis de la posguerra. Los relatos de este volumen son una gozada. Ponga a trabajar su malsana curiosidad y lealos todos. Encontrará repulsión y atracción". JAMES ELLROY', 'Edición de James Ellroy y Otto Penzler');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1614, '9788494966880', 'La mente reaccionaria. El Conservadurismo desde Edmund Burke hasta Donald Trump', 1, '2019', 316, 'The Reactionary Mind: Conservatism from Edmund Burke to Donald Trump (2017)', 'media/core/9788494966880.jpg', 1, '2023-04-22 09:43:18.245591', '2023-04-22 10:42:41.370026', 951, 2, 6, 5, NULL, '', '06_06', NULL, 340, 'Robin remonta el conservadurismo hasta sus raíces en la reacción contra la Revolución Francesa. Desde Edmund Burke hasta Antonin Scalia y Donald Trump, y desde John C. Calhoun hasta Ayn Rand. Avanza la idea de que todas las ideologías de derechas, desde el siglo XVIII hasta hoy, son improvisaciones sobre un tema: la experiencia sentida de tener poder, verlo amenazado y tratar de recuperarlo. Cuando se publicó en 2011, “La mente reaccionaria” desató un feroz debate. Desde entonces ha sido aclamado como "el libro que predijo a Trump" (New Yorker) y "una de las obras políticas más influyentes de la última década" (Washington Monthly). Actualizado para incluir la elección de Trump y sus primeros cien días en el cargo, este libro es más relevante que nunca.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1615, '9788408232421', 'El asesinato de Platón', 1, '2020', 919, NULL, 'media/core/9788408232421.jpg', 1, '2023-04-22 09:47:17.826752', '2023-04-22 10:42:16.089287', 952, 16, 6, 5, 'Autores Españoles e Iberoamericanos', '', '06_06', NULL, 7, 'La ateniense Altea, una de las más brillantes discípulas de Platón, no sabe que tiene a su peor enemigo en su propia casa, y que tanto ella como el bebé que espera se encuentran en peligro. Por su parte, su amigo y maestro Platón arriesga la vida para intentar hacer realidad su gran proyecto: un gobierno en el que impere la justicia en lugar de la corrupción, y donde la razón se imponga a la retórica vacía de los demagogos. Un gobierno ideal que traería la paz a los pueblos y en el que las mujeres podrían llegar a gobernar.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1616, '9788417700300', 'Nacionalidades y nacionalismos. Autonomías, federalismo, autodeterminación', 1, '2019', 292, NULL, 'media/core/9788417700300.jpg', 1, '2023-04-22 09:50:41.762696', '2023-04-22 10:43:07.702888', 953, 2, 6, 5, NULL, '', '06_06', NULL, 341, 'No dejaba de ser premonitorio el análisis que Jordi Solé desarrollaba en 1987, con motivo de la introducción a la edición catalana del libro.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1617, '9788417847210', 'Europa', 1, '2019', 289, NULL, 'media/core/9788417847210.JPG', 1, '2023-04-22 09:54:48.521293', '2023-04-22 10:42:27.217508', 954, 1, 6, 5, NULL, '', '06_06', NULL, 342, 'Llevamos a Europa a la sala de operaciones y la abrimos en canal. Metemos las ma-nos en la herida y acercamos la luz a los grandes órganos enfermos. Nos damos cuenta de que las lesiones son tantas y tan profundas que no merece la pena interve-nir. Guardamos el bisturí y nos limitamos a señalar con el dedo las zonas afectadas mientras les decimos a los alumnos de Medicina que rodean el quirófano: «Miren: fronteras necrosadas por el odio, pulmones encharcados en el pus del miedo, viejas mentiras resquebrajando la columna, el hemisferio izquierdo aletargado tras el gran ictus de Dios, tumoraciones metastásicas del poder. El diagnóstico lo conocen to-dos ustedes: colapso de la civilización. Mortal de nece(si)dad». Existen novelas difíciles de escribir y existen novelas que parecen imposibles. Esta ha necesitado los recursos narrativos de varios géneros literarios para ser conta-da. La novela negra y su encarnación del mal, el texto de ciencia ficción y los desas-tres de la incomunicación, el relato bélico y la fría articulación de la violencia, la estéti-ca gótica y el terror a lo que no conocemos, el testimonio social y el aire contamina-do del poder. El resultado es la gigantografía de lo que somos y de lo que hacemos. La esperanza no es la promesa de un día mejor, sino la toma de conciencia de que aún tenemos o...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1618, '9788476695098', 'Doña Oráculo', 1, '2001', 476, 'Lady Oracle', 'media/core/9788476695098.jpeg', 1, '2023-04-22 09:59:26.265057', '2023-04-22 09:59:26.265057', 955, 1, 6, 5, NULL, '', '06_04', NULL, 339, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1619, '9788467257847', 'Las grandes familias / La caída de los cuerpos / Cita en los infiernos', 1, '2010', 834, 'Les grandes familles / La Chute des corps / Rendez-vous aux Enfers', 'media/core/9788467257847.jpg', 1, '2023-04-22 10:04:07.388288', '2023-04-22 10:42:53.339869', 956, 1, 6, 5, NULL, '', '06_06', NULL, 343, 'Las grandes familias es el libro por el que Maurice Druon –uno de los hombres de letras más influyentes en la cultura francesa del siglo XX– ganó el premio Goncourt en 1948.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1620, '9788415140269', 'Las cenizas de Ángela', 20, '2020', 507, 'Angela''s Ashes', 'media/core/9788415140269.jpg', 1, '2023-04-22 10:47:56.153718', '2023-04-22 10:47:56.153718', 310, 31, 6, 5, NULL, '', '06_04', NULL, 344, 'Un libro que ya es un clásico con más de 17 millones de ejemplares vendidos. Premio Pulitzer.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1621, '9788427019393', 'Cara de mono', 1, '1994', 350, 'Taiko', 'media/core/9788427019393.jpeg', 1, '2023-04-22 10:52:12.091652', '2023-04-22 10:52:12.091652', 957, 16, 6, 5, NULL, '', '06_04', 'Taiko 1', 41, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1622, '978427019461', 'Enemigo de Buda', 1, '1995', 281, 'Taiko', 'media/core/9788427019461.jpeg', 1, '2023-04-22 10:55:19.025019', '2023-04-22 10:55:19.025019', 957, 16, 6, 5, NULL, '', '06_04', 'Taiko 2', 41, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1623, '9788467254914', 'Contestación a la pregunta: ¿Qué es la ilustración? (Extractos)', 1, '2012', 138, 'Was ist Auf klärung?', 'media/core/9788467254914.jpg', 1, '2023-04-22 10:59:14.996573', '2023-04-22 10:59:14.996573', 958, 2, 6, 5, NULL, '', '06_04', NULL, 73, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1624, '9788466354592', 'Opresión y resistencia. Escritos contra el totalitarismo 1937-1949', 1, '2021', 415, NULL, 'media/core/9788466354592.jpg', 1, '2023-04-22 11:02:04.283004', '2023-04-22 11:02:04.283004', 94, 2, 6, 5, 'Debolsillo', '', '06_04', NULL, 11, 'Imprescindible complemento ensayístico de las novelas1984yRebelión en la granja, la presente antología reúne una treintena de textos escritos entre 1937 y 1949 en los que George Orwell analiza y denuncia los totalitarismos que marcaron el siglo XX. El autor pasa revista a temas tan diversos como la guerra civil española, el imperialismo británico, la obra de Arthur Koestler, la mentalidad nacionalista, el inicio de la «guerra fría» (expresión que acuñó) o la figura de Gandhi, pero siempre hace hincapié en el pensamiento crítico, evaluando los hechos sin aceptar simplificaciones partidistas ni generalizaciones fáciles. En el contexto actual de manipulación,fake news y opiniones vacuas, sus palabras nos animan a estar siempre alerta, primera forma de resistencia frente a la amenaza latente de la opresión.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1625, '9788490658055', 'El estudiante de Salamanca y otros grandes éxitos', 1, '2022', 219, NULL, 'media/core/9788490658055.jpeg', 1, '2023-04-22 11:04:25.386272', '2023-04-22 11:04:25.386272', 618, 4, 6, 5, 'Alba Poesía', '', '06_04', NULL, 119, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1626, '9788413143750', 'El problema de los tres cuerpos', 1, '2021', 408, NULL, 'media/core/9788413143750.GIF', 1, '2023-04-22 11:09:28.297318', '2023-04-22 11:09:28.297318', 959, 3, 6, 5, NULL, '', '06_04', 'Trilogía de los tres Cuerpos Vol 1', 11, 'EL PROBLEMA DE LOS TRES CUERPOS (TRILOGIA DE LOS TRES CUERPOS 1)INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1627, '9788413143767', 'El bosque oscuro', 1, '2021', 569, NULL, 'media/core/9788413143767.JPG', 1, '2023-04-22 11:12:01.072887', '2023-04-22 11:12:01.072887', 959, 3, 6, 5, NULL, '', '06_04', 'Trilogía de los tres Cuerpos Vol 2', 11, 'La esperada continuación deEl problema de los tres cuerpos, el mejor libro de ciencia ficción y fantasía de 2016 segúnEl Periódico, y uno de los diez mejores libros de ficción de 2016 segúnPlayground.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1628, '9788413143774', 'El fin de la muerte', 1, '2021', 734, NULL, 'media/core/9788413143774.jpeg', 1, '2023-04-22 11:14:31.786102', '2023-04-22 11:15:18.521247', 959, 3, 6, 5, NULL, '', '06_04', 'Trilogía de los tres Cuerpos Vol 3', 11, 'El desenlace de la magistral trilogía de ciencia ficción con 4 millones de lectores en China, convertida en unbest seller de The New York Times y de Spiegel.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1629, '9788467238907', 'Las ilusiones perdidas', 1, '2006', 678, 'Illusions perdues', 'media/core/9788467238907.jpeg', 1, '2023-04-23 06:42:36.316553', '2023-04-23 06:42:36.316553', 610, 1, 6, 5, NULL, '', '06_06', NULL, 5, 'Obra maestra de Balzac, Las ilusiones perdidas cuenta la historia de un joven de provincias con ambiciones artísticas que sueña con triunfar en París. La odisea de Lucien Rubempr# desde la inocencia de su Angulema natal hasta el fango del fracaso constituye uno de los periplos narrativos m#s audaces, embelesadores e imponentes de la narrativa del siglo XIX.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1630, '9788467219449', 'El pintor de batallas', 1, '2006', 276, NULL, 'media/core/9788467219449.jpeg', 1, '2023-04-23 06:44:48.375269', '2023-04-23 06:44:48.375269', 73, 1, 6, 5, NULL, '', '06_06', NULL, 75, 'En una torre junto al Mediterráneo, en busca de la foto que nunca pudo hacer, un antiguo fotógrafo pinta un gran fresco circular en la pared: el paisaje intemporal de una batalla. Lo acompañan en la tarea un rostro que regresa del pasado para cobrar una deuda mortal, y la sombra de una mujer desaparecida diez años atrás. En torno a esos tres personajes, Arturo Pérez-Reverte ha escrito la más intensa y turbadora historia de su larga carrera de novelista.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1631, '9788435061988', 'Rebeldes y traidores. La revolución de Cromwell', 1, '2012', 1018, 'Rebels and traitors', 'media/core/9788435061988.jpg', 1, '2023-04-23 06:48:26.668107', '2023-04-23 06:48:26.668107', 551, 16, 6, 5, 'Narrativas históricas', '', '06_06', NULL, 47, 'Las guerras civiles inglesas que azotaron los reinos de Inglaterra, Escocia e Irlanda en el amplio período que va de 1639 a 1651 es el auténtico protagonista de este espectacular fresco histórico. El juicio y ejecución del rey Carlos I, el exilio de su hijo Carlos II, el nacimiento de la Commonwealth y la etapa del protectorado bajo el gobierno de Oliver Cromwell son mojones en un camino en que las luchas están teñidas de enfrentamientos tanto ideológicos y políticos como religiosos. Uno de los grandes aciertos de Lindsey Davis consiste en focalizar su relato en los personajes de Juliana Lovell, esposa de un realista, y Gideon Jukes, un parlamentario convencido, lo que le permite mostrar los acontecimientos sin tomar partido y dejando que sea el propio lector quien juzgue a sus personajes y sus acciones. Otro de los grandes aciertos de esta gran novela consiste en, a través de los viajes de los personajes, mostrar los efectos de las guerras y de las luchas no sólo en Londres, sino en muy diversos puntos de los tres reinos implicados en los acontecimientos. Una novela magnífica que expone de un modo muy claro unos años decisivos en la historia universal.', 'Incluye mapa de la guerra civil inglesa');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1632, '9788467267099', 'El silencio de la ciudad blanca', 1, '2016', 470, NULL, 'media/core/9788467267099.jpeg', 1, '2023-04-23 06:53:29.579398', '2023-04-23 06:53:29.579398', 101, 14, 6, 5, NULL, '', '06_06', 'Trilogía de la Ciudad Blanca 1', 15, '«Una ciudad aterrorizada por el regreso de unos asesinatos rituales. Un experto en perfiles criminales que esconde una tragedia. Un thriller hipnótico cuyas claves descansan en unos misteriosos restos arqueológicos»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1633, '9788467254044', 'La noche en que Frankestein leyó el Quijote', 1, '2012', 221, NULL, 'media/core/9788467254044.jpg', 1, '2023-04-23 06:55:42.669606', '2024-03-06 10:50:35.649893', 156, 1, 6, 5, NULL, '', '06_06', NULL, 15, 'Con un estilo ágil y ameno, Santiago Posteguillo nos guía desde la Biblioteca de Alejandría hasta hoy en un viaje lleno de hallazgos insospechados: nos descubre manuscritos prohibidos y obras maestras que estuvieron a punto de no ver la luz, escritores que cometieron crímenes no ficticios e incluso genios que, tal vez, burlaron su propia muerte. En cada capítulo hay emoción y suspense: son historias reales, algunas verdaderamente insólitas, pero todas tienen en común la pasión por la literatura. Conocerás el secreto de Alejandro Dumas y que Dostoievski ganó una apuesta sobrehumana con El jugador; te sorprenderá saber que un descuido del presidente Eisenhower provocó grandes quebraderos de cabeza al autor de El Señor de los Anillos. Y, por supuesto, si lees con atención Frankenstein, de Mary Shelley, identificarás el rastro de cierto ingenioso hidalgo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1634, '10235', 'Le Petit Prince', 1, '1964', 95, NULL, 'media/core/10235.gif', 1, '2023-04-23 07:01:24.538988', '2023-04-23 07:01:24.538988', 961, 27, 6, 5, NULL, '', '06_06', NULL, 293, 'El Principito. Uno de los clásicos más queridos de todos los tiempos, ilustrado con las acuarelas del autor que han cautivado la imaginación de grandes y pequeños durante generaciones.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1635, '9788467268423', 'El cuaderno gris', 1, '2016', 864, NULL, 'media/core/9788467268423.jpeg', 1, '2023-04-23 07:14:41.404809', '2023-04-23 07:14:41.404809', NULL, 1, 6, 5, NULL, '', '06_02', NULL, 58, 'Una obra maestra en una edición renovada.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1636, '9788467271621', 'El gigante enterrado', 1, '2017', 358, 'The buried giant', 'media/core/9788467271621.jpeg', 1, '2023-04-23 07:18:05.274326', '2023-04-23 07:18:05.274326', 963, 1, 6, 5, NULL, '', '06_02', NULL, 5, 'Inglaterra en la Edad Media. Del paso de los romanos por la isla sólo quedan ruinas, y Arturo y Merlín–amados por unos, odiados por otros–son leyendas del pasado. Entre la bruma todavía habitan ogros, y británicos y sajones conviven en unas tierras yermas, distribuidos en pequeñas aldeas. En una de ellas vive una pareja de ancianos–Axl y Beatrice–que toma la decisión de partir en busca de su hijo. Éste se marchó hace mucho tiempo, aunque las circunstancias concretas de esa partida no las recuerdan, porque ellos, como el resto de habitantes de la región, han perdido buena parte de la memoria debido a lo que llaman «la niebla». En su periplo se encontrarán con un guerrero sajón llamado Wistan; un joven que lleva una herida que lo estigmatiza; y un anciano Sir Gawain, el último caballero de Arturo vivo, que vaga con su caballo por esas tierras con el encargo, según cuenta, de acabar con un dragón hembra que habita en las montañas. Juntos se enfrentarán a los peligros del viaje, a los soldados de Lord Brennus, a unos monjes que practican extraños ritos de expiación y a presencias mucho menos terrenales. Pero cada uno de estos viajeros lleva consigo secretos, culpas pendientes de redención y, en algún caso, una misión atroz que cumplir.Sumando el viaje iniciático, la fábula y la épica,', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1637, '9788497859813', 'Cosas no aburridas para ser la mar de feliz', 1, '2013', 1, NULL, 'media/core/9788497859813.jpg', 1, '2023-04-23 07:24:17.576420', '2023-04-23 07:24:17.577428', 964, 20, 6, 5, NULL, '', '06_06', NULL, 320, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1638, '9788490667804', 'La madre de Frankestein', 1, '2020', 550, NULL, 'media/core/9788490667804.jpg', 1, '2023-04-23 07:27:27.497024', '2023-04-23 07:27:27.497024', 965, 1, 6, 5, 'Colección Andanzas', '', '06_06', 'Episodios de una Guerra Interminable 5', 12, 'El apasionante relato de una mujer y un hombre que optaron por resistir en los tiempos más difíciles. La novela más intensa y emotiva del ciclo de los Episodios de una Guerra Interminable.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1639, '9788416237401', 'Polvo y sombra', 1, '2020', 379, 'Pulvis et umbra', 'media/core/9788416237401.jpg', 1, '2023-04-23 07:32:30.368643', '2023-04-23 07:32:30.368643', 674, 1, 6, 5, 'Black', '', '06_06', 'Rocco Schiavone 6', 29, 'El buen tiempo no acaba de llegar a Aosta y el subjefe Rocco Schiavone tiene que lidiar con dos crímenes mientras repasa latín con Gabriele, el vecino adolescente cuya madre nunca está en casa. El cadáver de una transexual ha aparecido en el río Dora y casi a la vez, en un prado a las afueras de la capital, un pastor ha descubierto el cuerpo inerte de un hombre que esconde, en el bolsillo, una nota con el número de móvil de Schiavone. Y cuando el subjefe empieza a olerse que no se trata de un homicidio sin importancia, como pretenden algunos mandos, sino de algo mucho peor, recibe instrucciones de abandonar la investigación. De nuevo, el policía más políticamente incorrecto sólo podrá aclarar lo que está pasando saltándose los procedimientos y enfrentándose a todos los estamentos y engranajes del poder.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1640, '9788417430511', 'Antología de relatos góticos', 1, '2019', 319, NULL, 'media/core/9788417430511.jpg', 1, '2023-04-23 07:36:39.862505', '2023-04-23 07:36:39.862505', 572, 44, 6, 5, 'Alma clásicos ilustrados', '', '06_02', NULL, 319, 'Escuchar historias de miedo a la luz de una hoguera es algo que nos fascina desde los albores de la humanidad. Como reacción al espíritu racional de laIlustración, algunos autores del siglo XVIII apelaron a aquello que más nos asusta y se escapa a la razón: así nació el cuento de terror gótico. Con él nosadentramos en un mundo siniestro de castillos, tormentas nocturnas, fantasmas vengativos, monstruos innombrables, música de órgano y puertaschirriantes. En esta selección encontrarás algunas de las mejores narraciones del terror gótico clásico, escritas por los nombres fundamentales del género.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1641, '9788420438177', 'Una historia de España', 1, '2019', 246, NULL, 'media/core/9788420438177.jpg', 1, '2023-04-23 07:44:06.483123', '2023-04-23 07:44:06.483123', 73, 11, 6, 5, NULL, '', '06_06', NULL, 10, 'Un relato ácido, divertido, personal y poco ortodoxo de Arturo Pérez-Reverte sobre la historia de España.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1642, '9788467062144', 'El caso de la viuda peligrosa', 1, '2021', 285, 'The Case of Dangerous Dowager', 'media/core/9788467062144.jpg', 1, '2023-04-23 09:40:52.044889', '2023-04-23 09:40:52.044889', 967, 14, 6, 5, NULL, '', '06_06', 'Serie Perry Mason', 19, '', 'Matilda Benson contrata los servicios de Perry Mason para recuperar los pagarés que su nieta Sylvia Oxman firmó con un misterioso hombre de negocios para saldar sus deudas de juego en un casino flotante que opera en aguas internacionales. Si no los recupera, el esposo de Sylvia los usará en su contra en el proceso de divorcio para obtener la custodia de su hijo.');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1643, '9788418008078', 'Antología de cuentos cortos', 1, '2021', 270, NULL, 'media/core/9788418008078.jpg', 1, '2023-04-23 09:43:14.309813', '2023-04-23 09:43:14.309813', 572, 44, 6, 5, 'Alma clásicos ilustrados', '', '06_02', NULL, 319, 'Escribir un buen cuento es una tarea exigente, tanto o más difícil que escribir una gran novela. Cuando un autor logra plasmar todas las emociones humanas y crear retratos imperecederos de personajes en un relato, identificamos el verdadero genio literario y la lectura se convierte en un intenso placer, dado que contienen los mismos ingredientes que una gran novela, pero se leen en poco tiempo. La presente selección permitirá a los amantes de la buena literatura disfrutar de los mejores relatos cortos de grandes autores, con una gran variedad de temáticas y estilos. Una magnífica selección de pequeñas joyas literarias ideal para los amantes de la buena literatura.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1644, '9788417747961', 'Los imperios ibéricos y la globallización de Europa (siglos XV a XVII)', 1, '2019', 432, NULL, 'media/core/9788417747961.jpg', 1, '2023-04-23 09:46:25.935301', '2023-04-23 09:46:25.935301', 968, 11, 6, 5, NULL, '', '06_02', NULL, 346, 'La historia de España y Portugal está plagada de estereotipos que, a menudo, se usan tanto para alimentar el triunfalismo como un pesimismo paralizante. Solo los pueblos que conocen los contrastes de su historia pueden entender el pasado para, desde él, construir su futuro. Este libro afronta la de ambos países y sus imperios desde la perspectiva del papel crucial que desempeñaron en la globalización primitiva y del impacto que esta tuvo en sus sociedades y en Europa en general, así como en las áreas de dominio en África, Asia y América. Años de investigación y reflexión, y una comparación sistemática con los países de su entorno, han permitido a Bartolomé Yun seleccionar para el lector los hechos básicos y contestar cuestiones de calado. ¿Estaban capacitados los pueblos de Iberia para las empresas que hubieron de afrontar? ¿Eran eficientes su tecnología, sus conocimientos o sus instituciones? ¿Estuvieron sus élites a la altura de estos retos? ¿Qué tipo de relaciones sociales facilitó el imparable ascenso de Iberia y cuál fue el precio que pagaron sus sociedades? ¿Fueron capaces de cambiar para mantener el dominio del mundo? ¿Podemos hablar de decadencia en el sentido habitual?', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1645, '9788418059896', 'Mensajes de un mundo olvidado', 1, '2022', 198, NULL, 'media/core/9788418059896.jpg', 1, '2023-04-23 10:00:24.697451', '2023-04-23 10:00:24.697451', 630, 2, 6, 5, NULL, '', '06_06', NULL, 318, '"No perdamos el tiempo, porque el tiempo no va a nuestro favor sino en nuestra contra. En una epoca en la que reina el sinsentido, no nos apoyemos en el sólido intelecto y abandonemos ya la vana creencia humanista de que en un mundo plagado de armas y repleto de desconfianza mutua pueda conseguirse algo con palabras."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1646, '9788418526169', 'El vuelo de los buitres (El desastre de Annual y la guerra del Rif', 1, '2021', 365, NULL, 'media/core/9788418526169.jpg', 1, '2023-04-23 10:03:37.273588', '2023-04-23 10:03:37.273588', 969, 11, 6, 5, NULL, '', '06_06', NULL, 346, 'Este libro narra una novedosa historia de la batalla de Annual, que en 1921 enfrentó a los rifeños encabezados por Abd el-Krim y el Ejército español en Marruecos al mando del general Manuel Fernández Silvestre. Una batalla que levantó en armas a todo un pueblo y abrió las puertas a la proclamación de la efímera República del Rif. La guerra en el Rif significó uno de los mayores descalabros del Ejército español: allí perdieron la vida unos 12.000 hombres en pocos días, y el impacto en la opinión pública, que reclamó depurar responsabilidades, provocó una grave crisis política que puso en jaque al Gobierno y a la misma monarquía. Utilizando documentación de primera mano, con testimonios inéditos de la época, El vuelo de los buitres es un relato apasionante que consigue atrapar al lector reconstruyendo los hechos que se produjeron durante esos días, tanto en el campo de batalla como en Melilla, en los aduares rifeños o en Madrid. Una investigación rigurosa, llevada a cabo de forma minuciosa y exhaustiva, un ensayo único que cambiará el punto de vista español y el rifeño sobre aquellos acontecimientos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1647, '9788417007935', 'Frankestein en Bagdad', 1, '2019', 323, 'Frankshtayn fi Baghdad', 'media/core/9788417007935.jpg', 1, '2023-04-24 06:08:08.054849', '2023-04-24 06:08:08.054849', 970, 1, 6, 5, NULL, '', '06_06', NULL, 347, 'Después de la segunda guerra de Irak, en el Bagdad todavía ocupado por las tropas estadounidenses, un trapero decide recolectar algunos de los restos humanos que encuentra esparcidos por las calles y formar con ellas un único cadáver al que poder dar sepultura. Pero, para su sorpresa, el cuerpo cobrará vida y pondrá patas arriba el día a día de una comunidad variopinta: una anciana que desde hace años espera el regreso de su hijo desaparecido en la guerra con Irán, un avaro hotelero que pretende hacerse con todos los edificios del barrio o un joven periodista que, mientras intenta olvidar a una mujer, irá tras la pista de esta singular criatura.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1649, '9788446020301', 'Los pueblos prerromanos de la península ibérica', 3, '2018', 193, NULL, 'media/core/9788446020301.jpg', 1, '2023-04-24 06:12:23.794447', '2023-04-24 06:12:23.794447', 971, 11, 6, 5, 'Akal Universitaria', '', '06_06', 'Historia antugua', 196, 'El estudio de los pueblos prerromanos de la península Ibérica constituye una parcela de la Historia antigua que se ha desarrollado extraordinariamente en las últimas décadas, fruto de un mayor número de excavaciones arqueológicas, planteadas con una metodología más científica, así como de los progresos en disciplinas auxiliares como la filología, la epigrafía, la numismática y la relectura de los textos clásicos. De esta manera, en los últimos años se ha ido formando una disciplina, la Paleohispanística, que busca el conocimiento cada vez más completo de las poblaciones prerromanas tanto desde el punto de vista étnico como cultural, lingüístico, económico, social, político y religioso. Es desde esta perspectiva global desde la que se realiza el estudio de los pueblos prerromanos de la península Ibérica, con especial interés en sus formas de organización social y política, su economía y su religión, procurando reflejar la complejidad de problemas que supone su estudio. Cronológicamente se extiende desde el siglo VI hasta el siglo I a.C., es decir, desde el momento en que aparecen las primeras noticias literarias sobre ellos, en el contexto de las colonizaciones fenicia y griega, hasta su conquista por Roma. Realizado desde una perspectiva eminentemente histórica, apoyado en fuentes literarias #principalmente las noticias de los autores griegos y latinos#, arqueológicas, epigráficas y numismáticas y, en general, de cualquier tipo de material que permita hacer una reconstrucción de estas sociedades, la obra recoge tanto la opinión común de los especialistas como los principales temas de debate.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1650, '9772604204528', 'Clara Campoamor. La lucha por los derechos de la mujer', 1, '2019', 1, NULL, 'media/core/9772604204528.jpeg', 1, '2023-04-24 06:21:34.815146', '2023-04-24 06:21:34.815146', 572, 43, 6, 5, 'National Geographic Historia', '', '06_06', 'Grandes mujeres nº 5', 32, '“Resolved lo que queráis, pero afrontando la responsabilidad de dar entrada a esa mitad de género humano en política, para que la política sea cosa de dos, porque solo hay una cosa que hace un sexo solo: alumbrar; las demás las hacemos todos en común, y no podéis venir aquí vosotros a legislar, a votar impuestos, a dictar deberes, a legislar sobre la raza humana, sobre la mujer y sobre el hijo, aislados, fuera de nosotras”. Era el año 1935 cuando Clara Campoamor escribía estas palabras en El voto femenino y yo: mi pecado mortal, una obra en la que exponía la lucha por el derecho de voto de las mujeres y en la que había invertido muchas horas los años anteriores. En diciembre de 1931 había sido aprobada la nueva Constitución que reconocía ese derecho, un triunfo logrado tras muchas dificultades y decepciones.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1651, '9788420439655', 'La vida contada por un sapiens a un neandertal', 1, '2020', 216, NULL, 'media/core/9788420439655.jpg', 1, '2023-04-24 06:25:18.382168', '2023-04-24 07:15:35.086177', 972, 15, 6, 5, 'Narrativa hispánica', '', '06_06', NULL, 10, 'Hace años que el interés por entender la vida, sus orígenes y su evolución resuena en la cabeza de Juan José Millás, de manera que se dispuso a conocer, junto a uno de los mayores especialistas de este país en la materia, Juan Luis Arsuaga, por qué somos como somos y qué nos ha llevado hasta donde estamos. La sabiduría del paleontólogo se combina en este libro con el ingenio y la mirada personal y sorprendente que tiene el escritor sobre la realidad. Porque Millás es un neandertal (o eso dice), y Arsuaga, a sus ojos, un sapiens.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1652, '9788466672542', 'Un asesinato brillante', 1, '2022', 227, 'Magpie Murders', 'media/core/9788466672542.jpg', 1, '2023-04-24 06:28:37.210146', '2023-04-24 06:28:37.210146', 973, 14, 6, 5, 'La Trama', '', '06_06', NULL, 11, 'Susan Ryeland ha sido durante años la editora del excéntrico escritor superventas Alan Conway. Los lectores adoran al protagonista de su serie más famosa, el detective Atticus Pünd, que se dedica a resolver crímenes en la década de los cincuenta por pueblecitos ingleses aparentemente tranquilos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1653, '9788499984414', 'Los 10 mitos del nacionalismo catalán', 2, '2014', 221, NULL, 'media/core/9788499984414.jpg', 1, '2023-04-24 06:38:15.414456', '2023-04-24 06:38:15.414456', 975, 2, 6, 5, 'Temas de hoy', '', '06_06', NULL, 7, '«El libro pretende explicar cómo hemos llegado al desafío actual. Cuáles han sido los hechos y cuáles las mentiras que han conducido al callejón sin salida en el que el nacionalismo ha colocado a la sociedad catalana y a las instituciones catalanas y españolas», Joaquín Leguina INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1654, '9788411071734', 'Todo va a mejorar', 1, '2022', 482, NULL, 'media/core/9788411071734.jpg', 1, '2023-04-24 06:40:49.418797', '2023-04-24 06:40:49.418797', 965, 1, 6, 5, 'Colección Andanzas', '', '06_06', NULL, 12, 'En un mundo perfecto de felicidad obligatoria, denunciar la mentira puede costarte la vida.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1655, '9788412455441', 'Mujeres solas', 1, '2022', 188, 'Ronrii ûman', 'media/core/9788412455441.jpg', 1, '2023-04-24 06:44:24.051716', '2023-04-24 06:44:24.051716', 976, 44, 6, 5, NULL, '', '06_06', NULL, 348, 'Cinco mujeres, cinco vidas habitadas por el desasosiego, intentando librarse de los estrechos corsés de una moral opresiva en una sociedad asfixiante y normativizada. Las protagonistas de Mujeres solas no son mujeres corrientes, o tal vez sí lo han sido, pero ahora, fracasadas las expectativas sociales puestas en ellas, comienzan a ser libres en esa búsqueda de un nuevo sentido más allá de su pasado. Sólo ahora es cuando son capaces de desvelar sus deseos más íntimos, recónditos y transgresores, en un entorno que les exige una existencia muda y relegada a un plano secundario.Una joven llega a identificarse con el autor o la autora de una serie de incendios en escuelas y disfruta con la imagen de un fuego devorador. Una esposa decide poner en riesgo su vida perfecta y monótona tras el recuerdo de un amante egoísta que le hizo conocer la pasión y el sufrimiento. Una dependienta que teme a las multitudes observa atónita cómo una niña perversa roba en los grandes almacenes. Una viuda joven se ve impelida a revisar su breve vida conyugal arrastrada por unos sueños premonitorios que cobran más presencia que su propia vida. Una anciana a la que la muerte le ha arrebatado sus seres queridos es asaltada por encuentros fortuitos con suicidas.   Crueldad, hipersensibilidad, fragilidad, desequilibrio, sexualidad, perversión y búsqueda del placer pueblan estas vidas que se entrecruzan en un magistral lienzo tejido con las diferentes formas de la soledad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1656, '9788418578557', 'Eso no estaba en mi libro de Historia del Flamenco', 1, '2022', 306, NULL, 'media/core/9788418578557.jpg', 1, '2023-04-24 06:51:52.643113', '2023-04-24 06:51:52.643113', 977, 11, 6, 5, NULL, '', '06_06', NULL, 68, '¿Por qué se unió Tragabuche a los bandoleros llamados Siete niños de Écija? ¿Murió dos veces el Beni de Cádiz? ¿De quién se dijo que el que no fuera a escucharlo cantar es que no tenía vergüenza? ¿Qué relación tenían las Camelias con Valle-Inclán o los hermanos Romero de Torres?, ¿Por qué se organizó realmente el Concurso flamenco de Granada? ¿Qué se escondía en los cafés-cantantes? ¿Qué mágica relación existe entre el toro y el cante? ¿Quién era la bailaora de la que decían que mareaba mirarla? El flamenco es un tesoro inabarcable en sus formas y en sus tiempos. Desde que el flamenco no era flamenco hasta que fue declarado Patrimonio Inmaterial de la Humanidad por la Unesco ha estado presente en todo el mundo, desde el cabo de Trafalgar al Paralelo de Barcelona, desde el Levante hasta los fandangos de Huelva. E incluso, cómo no, traspasando las fronteras, no en vano la primera cátedra de guitarra flamenca se creó en Róterdam. Pero como todo gran tesoro esconde grandes secretos. Eduardo J. Pastor Rodríguez desentraña en esta apasionante y deliciosa obra muchos de los interrogantes que rodean al mundo del flamenco dotándole de ese embrujo que lo hace eterno. «Eduardo Pastor, conocido por sus numerosas publicaciones sobre flamenco, se expresa en un lenguaje sabroso, espontáneo y elegante». Jacques Issorel, Catedrático honorario de la Universidad de Perpignan (Francia)', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1657, '9788467234190', 'El hombre más buscado', 1, '2009', 393, 'A Most Wanted Man', 'media/core/9788467234190.jpeg', 1, '2023-04-24 06:54:59.303584', '2023-04-24 06:54:59.303584', 559, 14, 6, 5, NULL, '', '06_06', NULL, 34, 'Si buscas una gran novela, solo tienes que encontrar a un hombre: John le Carré.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1658, '9789878358468', 'Últimas palabras', 1, '2021', 272, 'Last words', 'media/core/9789878358468.jpg', 1, '2023-04-24 06:58:48.595483', '2023-04-24 06:59:50.158310', 850, 32, 6, 5, NULL, '', '06_06', NULL, 349, 'Últimas palabras es sin dudas el libro más íntimo de William S. Burroughs, uno de los malditos tutelares de la literatura contemporánea. Se trata del diario que el autor llevó durante los últimos nueve meses de su vida, y abarca todos los ámbitos de su interés: la crítica cultural, la literatura, las drogas, la ecología, sus diatribas políticas, sus amigos ignotos y famosos, los miedos y miserias de la vejez, los vaivenes de la creación literaria y su irrefrenable pasión por los gatos. Trata también sobre la muerte ?en su caso inminente?, y en esa vena reflexiona sobre el fallecimiento de dos de sus grandes amigos ?Allen Ginsberg y Timothy Leary? para hacer luego un recuento de su existencia y de sus propios arrepentimientos. En suma, esta suerte de testamento constituye un retrato conmovedor y crepuscular del mayor autor de la Beat Generation, polémico como nadie, provocador como pocos, que ni la sombra del final fue capaz de amedrentar.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1659, '9788418526312', 'Lo pasado no es un sueño', 1, '2021', 192, NULL, 'media/core/9788418526312.jpg', 1, '2023-04-24 07:02:57.162756', '2023-04-24 07:02:57.162756', 978, 1, 6, 5, NULL, '', '06_06', NULL, 346, '''Tenía ocho años cuando mi abuelo me tomó de la mano y no la soltó hasta que encontramos a mis padres en Atenas. Quién sabe qué podría haber pasado si me hubiera quedado en el pueblo. Era 1946. Principios de la primavera de 1946. Los almendros florecían uno al lado del otro y el campo estaba en su esplendor.'' Así empieza la novela más autobiográfica de Theodor Kallifatides y una de las más apreciadas por sus cientos de miles de lectores. Una semana antes de que Kallifatides huyera del pueblo, un grupo de fascistas con armas en la mano había obligado a toda la gente a reunirse en el cementerio. Allí se quedaron jóvenes y viejos aterrorizados mientras su infame capo los llamaba lentamente a uno tras otro para finalmente seleccionar a algunos hombres que se llevó con él. Sus cuerpos nunca fueron encontrados. Con su característica sencillez y humanidad, nos narra su vida desde que abandona su pueblo natal hasta que retorna a él para recibir el homenaje de sus vecinos convertido ya en un escritor consagrado. Así descubrimos la infancia y la adolescencia en la Atenas gobernada por regímenes autoritarios, el nacimiento de la conciencia política y de clase, el descubrimiento de la sexualidad y el amor, el exilio a Suecia, la sorprendente capacidad para rehacer allí su vida laboral y formar una familia, y su trayectoria como escritor en la lengua de acogida, el sueco. Kallifatides nos brinda otro libro magistral, para deleite de los que ya conocen su obra y de los que todavía tienen la suerte de poder descubrirla.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1660, '9788423356300', 'Los santos inocentes', 1, '2019', 154, NULL, 'media/core/9788423356300.jpg', 1, '2023-04-24 07:05:52.193567', '2023-04-24 07:05:52.193567', 830, 1, 6, 5, 'Destinos clásicos', '', '06_06', NULL, 59, 'Edición conmemorativa del centenario Miguel Delibes (1920-2020).Con prólogo de Manuel Vilas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1661, '9788418037542', 'Trilogía Fundación', 1, '2022', 830, NULL, 'media/core/9788418037542.jpg', 1, '2023-04-24 07:09:12.459008', '2023-04-24 07:09:12.459008', 341, 3, 6, 5, 'Nova', '', '06_06', NULL, 11, 'La edición ilustrada de la obra cumbre de Isaac Asimov, con 11 ilustraciones del artista Gabriel Björk Stiernström y traducción de Manuel de los Reyes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1662, '9788467236446', 'Anatomía de un instante', 1, '2009', 428, NULL, 'media/core/9788467236446.jpeg', 1, '2023-04-24 07:12:07.880505', '2023-04-24 07:12:07.880505', 245, 17, 2, 5, NULL, '', '06_06', NULL, 5, '«Este libro es un ensayo en forma de crónica o una crónica en forma de ensayo. Este libro no es una ficción. Este libro es la anatomía de un instante: el instante en que Adolfo Suárez permaneció sentado en la tarde del 23 de febrero de 1981 mientras las balas de los golpistas zumbaban a su alrededor en el hemiciclo del Congreso de los Diputados y todos los demás parlamentarios -todos menos dos: el general Gutiérrez Mellado y Santiago Carrillo- buscaban refugio bajo sus escaños. Este libro es la crónica de ese gesto y la crónica de un golpe de estado y la crónica de unos años decisivos en la historia de España. Este libro es un libro imprescindible. Un libro único.»', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1663, '9788466671781', 'Roma soy yo', 1, '2022', 685, NULL, 'media/core/9788466671781.jpg', 2, '2023-04-24 07:14:55.071590', '2026-01-02 12:50:15.804183', 156, 16, 6, 5, NULL, '', '06_06', NULL, 11, 'Si alguna vez hubo un hombre nacido para cambiar el curso de la Historia, ese fue Julio César. Su leyenda, veinte siglos después, sigue más viva que nunca.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1664, 'B3189', 'La cocina de siempre', 1, '1993', 1, NULL, 'media/core/B3189.jpg', 1, '2023-04-24 07:21:44.921146', '2023-04-24 07:21:44.921146', NULL, 47, 6, 5, NULL, '', '06_03', NULL, 130, '', '');
