INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1666, '9788467948950', 'Corto Maltés: la juventud (edición blanco y negro', 1, '2022', 55, NULL, 'media/core/9788467948950.jpg', 1, '2023-04-24 07:38:05.320231', '2023-04-24 07:38:05.320231', 980, 34, 6, 5, NULL, '', '0107', NULL, 350, 'LAS AVENTURAS DE JUVENTUD DEL MÍTICO MARINERO DE PRATT Publicada originalmente en el diario francés Le Matin de Paris, La juventud despeja algunas incógnitas sobre la biografía del marino de Malta. La acción nos traslada a 1905. Corto asiste a los últimos compases de la guerra ruso-japonesa en Manchuria. Allí se tropezará con el corresponsal de guerra Jack London y trabará una extraña amistad con un desertor del ejército ruso, el infame Rasputín.Norma Editorial recupera en orden cronológico todas las aventuras del gran clásico de Hugo Pratt. Todo un hito del noveno arte disponible ahora en dos espectaculares ediciones a color y en blanco y negro.', '');
