INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1692, '9788426727480', 'Django 2', 1, '2020', 511, NULL, 'media/core/9788426727480.jpg', 1, '2023-04-24 11:21:31.398845', '2023-04-24 11:21:31.398845', 1001, 38, 6, 5, NULL, '', '04_07', NULL, 241, 'Descubra el proceso completo para desarrollar aplicaciones web profesionales con Django. Este libro le guiará a traves de la creación de cuatro proyectos prácticos con Django para saber cómo resolver problemas comunes e implementar las mejores prácticas de desarrollo. A lo largo de la lectura aprenderá a construir una aplicación blog, un sitio web social para compartir imágenes, una tienda online y una plataforma e-learning. El libro no solo trata el desarrollo de aplicaciones web con Django, sino tambien cómo mejorar la experiencia de usuario mediante AJAX y JavaScript, integrar otras tecnologías como Redis y Celery, así como crear APIs REST para exponer servicios a terceros. Al finalizar el libro, dispondrá de un conocimiento profundo sobre cómo construir aplicaciones web avanzadas con Django. Contenidos del libro: Crear proyectos web profesionales con Django Utilizar Django con otras tecnologías como Redis y Celery Desarrollar aplicaciones Django reutilizables Crear funcionalidades avanzadas, optimizar código y utilizar la cache Añadir internacionalización a proyectos Django Mejorar la experiencia de usuario utilizando JavaScript y AJAX Añadir funcionalidades sociales a los proyectos 2Construir APIs REST para exponer funcionalidades a terceros', '');
