INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1699, '9788476283844', 'Mapas y Civilización. Historia de la Cartografía en su contexto cultural y social', 1, '2002', 234, 'Maps and Man: An Examination of Cartography in Relation to Cunture and Civilization', 'media/core/9788476283844.jpg', 1, '2023-04-25 06:31:29.245314', '2023-04-25 06:31:29.245314', 1005, 11, 6, 5, 'La Estrella Polar', '', '06_06', NULL, 51, 'Esta obra no es un tratado sobre el arte de hacer mapas, sino más bien sobre la apreciación de los mapas y sobre su sentido. También puede ser considerada como una fuente de prototipos cartográficos o como una antología de mapas, cartas náuticas y planos. Sin ser un sustituto de una cartoteca, este libro conducirá de una forma ideal a una mejor utilización de tales medios.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1700, '9788422690924', 'El enigma de la esfinge. Las causas, el curso y el propósito de la evolución', 1, '2001', 416, NULL, 'media/core/9788422690924.jpeg', 1, '2023-04-25 06:34:56.141255', '2023-04-25 06:34:56.141255', 287, 2, 6, 5, NULL, '', '06_06', NULL, 96, 'Al igual que la esfinge, inmutable, planteó a Edipo un enigma cuya solución significaría la salvación de Tebas, la evolución plantea a los científicos no uno, sino múltiples enigmas. No tanto en la teoría general, que después de vencerINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1701, '9788435005371', 'Imperio', 1, '1988', 501, 'Empire', 'media/core/9788435005371.jpeg', 1, '2023-04-25 06:38:08.354406', '2023-04-25 06:38:08.354406', 738, 16, 6, 5, 'Narrativas Edhasa', '', '06_06', NULL, 47, 'A caballo entre los siglos XIX y XX los Estados Unidos viven la transformación de una joven república en un imperio mundial. Una joven, Caroline Sanford, se enfrenta nada menos que al poderoso William Randolph Hearst para defender sus propias ambiciones.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1702, '9788498152425', 'Creación', 1, '2005', 617, 'Creation', 'media/core/9788498152425.GIF', 1, '2023-04-25 06:41:33.633832', '2023-04-25 06:41:33.633832', 738, 16, 6, 5, 'Novela Histórica', '', '06_06', NULL, 264, 'Creación, una de las novelas más ambiciosas de Gore Vidal , narra el periplo de Ciro Espitama, embajador de un imperio que se extiende desde el Mediterráneo hasta la India, en su afán por resolver algunos de los grandes enigmas de todos los tiempos. De este modo, su espléndido relato se convierte en fascinante recorrido por los tiempos de Buda, Confucio, Anaxágoras, Herodoto, Pericles y Sócrates. En el ámbito de la novela histórica, probablemente no exista una obra que refleje con tanta fuerza, amplitud y precisión el ambiente de una época como Creación', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1703, '9788467264241', 'El enigma de la calle Calabria', 1, '2011', 303, NULL, 'media/core/9788467264241.jpeg', 1, '2023-04-25 06:44:46.608618', '2023-04-25 06:44:46.608618', 147, 14, 6, 5, NULL, '', '06_06', 'Victor Ros 3', 355, 'En el tercer caso de Víctor Ros, el autor combina personajes y situaciones reales con pura ficción para ofrecernos un apasionante retrato de la Barcelona de finales del siglo XIX.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1704, '9788466657990', 'Cicatriz', 1, '2015', 571, NULL, 'media/core/9788466657990.jpg', 1, '2023-04-25 06:47:04.861295', '2023-04-25 06:47:04.861295', 6, 1, 6, 5, NULL, '', '06_06', NULL, 8, 'Simon Sax podría ser un tipo afortunado. Es joven, listo y está punto de convertirse en multimillonario si vende su gran invento -un asombroso algoritmo- a una multinacional. Y, sin embargo, se siente solo. Su éxito contrasta con sus nulas habilidades sociales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1705, '9788467268263', 'El cazador de la oscuridad', 1, '2016', 475, 'Il cacciatore del buio', 'media/core/9788467268263.JPG', 1, '2023-04-25 06:51:00.088877', '2023-04-25 06:51:00.088877', 1006, 14, 6, 5, NULL, '', '06_06', 'Marcus & Sandra 2', 356, 'Marcus es sacerdote y tiene un don: detecta el mal que anida en las personas. Sandra es fotógrafa de la policía. Y también tiene un don: puede hacer visible lo invisible. Ahora ambos han unido sus talentos para atrapar a un asesino abominable: alguien que sólo escoge como víctimas a parejas jóvenes. La investigación de los crímenes les lleva al Vaticano, al archivo donde se atesoran los mayores crímenes de la humanidad. Un inventario del mal absoluto. Un lugar siniestro donde todo es oscuridad. Con un ritmo vertiginoso, Carrisi teje una historia en la que el lector libra la misma lucha que Marcus y se enfrenta a los mismos enigmas que intenta descifrar Sandra, sintiendo las mismas esperanzas y el mismo miedo hasta la última línea.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1706, '9788433979667', 'El gigante enterrado', 1, '2016', 364, 'The buried giant', 'media/core/9788433979667.jpg', 1, '2023-04-25 06:57:10.339396', '2023-04-25 06:57:10.339396', 963, 1, 6, 5, 'Panorama de narrativas', '', '06_06', NULL, 6, 'Inglaterra en la Edad Media. Del paso de los romanos por la isla sólo quedan ruinas, y Arturo y Merlín–amados por unos, odiados por otros–son leyendas del pasado. Entre la bruma todavía habitan ogros, y británicos y sajones conviven en unas tierras yermas, distribuidos en pequeñas aldeas. En una de ellas vive una pareja de ancianos–Axl y Beatrice–que toma la decisión de partir en busca de su hijo. Éste se marchó hace mucho tiempo, aunque las circunstancias concretas de esa partida no las recuerdan, porque ellos, como el resto de habitantes de la región, han perdido buena parte de la memoria debido a lo que llaman «la niebla». En su periplo se encontrarán con un guerrero sajón llamado Wistan; un joven que lleva una herida que lo estigmatiza; y un anciano Sir Gawain, el último caballero de Arturo vivo, que vaga con su caballo por esas tierras con el encargo, según cuenta, de acabar con un dragón hembra que habita en las montañas. Juntos se enfrentarán a los peligros del viaje, a los soldados de Lord Brennus, a unos monjes que practican extraños ritos de expiación y a presencias mucho menos terrenales. Pero cada uno de estos viajeros lleva consigo secretos, culpas pendientes de redención y, en algún caso, una misión atroz que cumplir.Sumando el viaje iniciático, la fábula y la épica, Kazuo Ishiguro ha construido u...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1707, '9788467249101', 'El prisionero del Cielo', 1, '2011', 379, NULL, 'media/core/9788467249101.jpeg', 1, '2023-04-25 07:01:14.898490', '2023-04-25 07:01:14.898490', 1007, 1, 2, 5, NULL, '', '06_06', NULL, 15, 'Te emocionarás como la primera vez.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1708, '9788408081180', 'El juego del ángel', 1, '2008', 667, NULL, 'media/core/9788408081180.jpg', 1, '2023-04-25 07:03:30.117468', '2023-04-25 07:03:30.117468', 1007, 1, 6, 5, NULL, '', '06_06', NULL, 7, 'La próxima vez que quieras salvar un libro, no te juegues la vida...Te llevaré a un lugar secreto donde los libros nunca muerenINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1709, '9788408043645', 'La sombra del viento', 41, '2005', 574, NULL, 'media/core/9788408043645.jpg', 1, '2023-04-25 07:06:36.513160', '2023-04-25 07:06:36.513160', 1007, 1, 6, 5, NULL, '', '06_06', NULL, 7, 'El mayor éxito internacional de la novela española. Más de un millón de ejemplares vendidos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1710, '9788423662159', 'Marina', 10, '2006', 286, NULL, 'media/core/9788423662159.jpg', 1, '2023-04-25 07:09:39.220735', '2023-04-25 07:09:39.220735', 1007, 1, 6, 5, 'Escritores de hoy', '', '06_06', NULL, 56, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1711, '9788467271027', 'Tierra de campos', 1, '2017', 406, NULL, 'media/core/9788467271027.jpg', 1, '2023-04-25 07:12:38.280028', '2023-04-25 07:12:38.280028', 183, 1, 6, 5, NULL, '', '06_06', NULL, 216, 'Con el objetivo de enterrar a su padre en el pueblo donde nació, Daniel emprende un viaje en un vehículo muy particular, un coche fúnebre, conducido por un chófer ecuatoriano, pintoresco y charlatán, de la mejor estirpe cómica. ¿Quién es de verdad Dani Mosca? Quizá, como sostiene él mismo, es sólo un tipo que hace canciones, sobre todo canciones de amor. Pero es también el niño que creció en un barrio humilde; que encontró la amistad más profunda de esa manera accidental en que uno encuentra las grandes cosas de la vida; que viajó y disfrutó de su oficio en la música hasta que la tríada clásica de los excesos (sexo, drogas y rock and roll) desintegró el grupo que había formado con sus amigos del alma; y cuya vida se sostuvo en un equilibrio precario pero resistente entre el deseo y la realidad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1712, '9788417910556', 'No digas nada', 1, '2020', 450, 'Say Nothing', 'media/core/9788417910556.jpg', 1, '2023-04-25 07:17:24.541119', '2023-04-25 07:17:24.541119', 1008, 17, 6, 5, 'Reservoir Books', '', '06_06', NULL, 11, 'En diciembre de 1972, varios encapuchados secuestraron a Jean McConville, una viuda de treinta y ocho años con diez hijos a su cargo. Nadie dudó, en aquel barrio católico de Belfast, que se trataba de una represalia del IRA. Sin embargo, el crimen no empezó a resolverse hasta 2003, cinco años después de los acuerdos de paz del Viernes Santo, al ser desenterrados los restos mortales de McConville en una playa solitaria.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1713, '978494711237', 'Puñal de claveles', 1, '2017', 187, NULL, 'media/core/978494711237.jpeg', 1, '2023-04-25 07:22:47.080870', '2023-04-25 07:22:47.080870', 1009, 1, 6, 5, NULL, '', '06_06', NULL, 357, 'Pura apareció en la puerta del solitario cortijo, puso la mano derecha como toldo a los ojos y tendió la vista a lo largo del camino, que se extendía zigzagueando entre los declives de las montañas. La protagonista de PUÑAL DE CLAVELES es pedida en matrimonio por el contrabandista y dueño del cortijo de los Tollos, Antonio el Peneque, algo que ella acepta "sin alegría y sin repugnancia". PUÑAL DE CLAVELES fue fruto del compromiso de Carmen de Burgos "Colombine" como activista pionera en defensa de los derechos de la mujer y probablemente es una obra imprescindible para comprender su extensa trayectoria literaria, por su trascendencia social, por ser una de sus últimas creaciones y porque Federico García Lorca se basó, en parte, en ella para escribir uno de los textos cumbre del teatro contemporáneo, Bodas de sangre, lo que la convierte en un relato esencial. La autora se inspiró en el llamado crimen del Cortijo del Fraile -que tuvo lugar en 1928 y que, como recogió la prensa de la época, fue un suceso con repercusión en todo el país- para escribir una novela amena, liberadora y apasionante. TERESA MUÑOZ PINILLOS', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1714, '9788401022876', 'Las tinieblas y el alba', 1, '2020', 927, 'The Evening and the Morning', 'media/core/9788401022876.jpg', 1, '2023-04-25 07:25:35.962194', '2023-04-25 07:25:35.962194', 197, 16, 6, 5, NULL, '', '06_06', NULL, 17, 'Año 997, finales de la Edad Oscura. Inglaterra se enfrenta a los ataques de los galeses por el oeste y de los vikingos por el este. La vida es difícil y aquellos que ostentan algo de poder lo ejercen con puño de hierro y, a menudo, en conflicto con el propio rey.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1715, '8422633469', 'Enterrad mi corazón en Wunded Knee', 1, '1990', 526, 'Bury my Heart at Wounded Knee', 'media/core/8422633469.jpg', 1, '2023-04-25 07:30:36.349610', '2023-04-25 07:30:36.349610', 1010, 17, 6, 5, NULL, '', '06_06', NULL, 5, 'Publicado por primera vez en 1970 y pronto convertida en un best séller internacional, Enterrad mi corazón en Wounded Knee narra por primera vez la historia del Oeste americano contada por las víctimas de la colonización.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1716, '9788467226935', 'La carretera', 1, '2007', 236, 'The Road', 'media/core/9788467226935.jpg', 1, '2023-04-25 07:33:32.304360', '2023-04-25 07:33:32.304360', 1011, 1, 6, 5, NULL, '', '06_06', NULL, 34, 'Una demoledora fábula sobre el futuro del ser humano, destinada a convertirse en la obra maestra del autor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1717, '8432043788', 'Ciudadano Hugues', 1, '1986', 423, 'Citizen Hugues', 'media/core/8432043788.jpg', 1, '2023-04-25 07:39:48.233177', '2023-04-25 07:39:48.233177', 1012, 17, 6, 5, 'Documento', '', '06_06', NULL, 7, 'Howard Hughes es en un personaje legendario. Películas como Ciudadano Kane de Orson Welles o The Aviator de Martin Scorsese han retratado a este excentrico y misterioso millonario. Atrapado entre el poder y la locura, la historia de Hughes constituye un verdadero drama humano cuya realidad supera cualquier ficción. En el punto culminante de su riqueza y aislamiento, Hughes llevó una especie de diario y rigió su imperio por correspondencia, plasmando por escrito sus órdenes, proyectos, ideas, temores y deseos. En 1974, unos desconocidos robaron sus archivos secretos. Pese a las investigaciones del FBI y la CIA, los documentos no aparecieron, hasta que Michael Drosnin descubrió el misterio. En Ciudadano Hughes, Drosnin narra la historia del gran robo de Hughes, y construye un retrato escalofriante en el que el propio Hughes nos introduce en el misterio de su mente.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1718, '8420600083', 'Utopía', 2, '1985', 201, 'Libellus vere aureus, nec minus salutaris quam festivus, de optimo reipublicae statu, deque nova ins', 'media/core/8420600083.jpg', 1, '2023-04-25 10:35:14.673512', '2023-04-25 10:35:14.673512', 1013, 2, 6, 5, 'El libro de bolsillo', '', '06_04', NULL, 69, 'Una crítica al orden social establecido en la Europa del siglo XVI, que ha trascendido a su época.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1719, '8421704613', 'Sala de lo criminal', 1, '1976', 190, 'Cour d''Assises', 'media/core/8421704613.jpeg', 1, '2023-04-25 10:38:51.290469', '2023-04-26 06:02:12.640768', 107, 14, 6, 5, 'las novelas de Simenon', '', '06_04', NULL, 295, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1720, '8421704303', 'Los suicidas', 1, '1973', 191, 'Les suicides', 'media/core/8421704303.jpg', 1, '2023-04-25 10:41:35.759589', '2023-04-25 10:41:35.759589', 107, 14, 6, 5, 'las novelas de Simenon', '', '06_04', NULL, 295, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1721, '9788466331807', 'El otro nombre de Laura', 1, '2018', 415, 'The Silver Swan', 'media/core/9788466331807.jpg', 1, '2023-04-25 10:45:31.045377', '2023-04-25 10:45:31.045377', 1014, 14, 6, 5, 'Debolsillo', '', '06_04', 'Quirke 2', 11, 'John Banville, tras el pseudónimo de Benjamin Black, nos ofrece una nueva novela negra de trama y ambiente apasionantes, protagonizada por su genial y oscuro patólogo Quirke.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1722, '9788466331791', 'El secreto de Christine', 1, '2020', 444, 'Christine Falls', 'media/core/9788466331791.jpg', 1, '2023-04-25 10:47:43.145042', '2023-04-25 10:47:43.145042', 1014, 14, 6, 5, 'Debolsillo', '', '06_04', 'Quirke 1', 11, 'Premio Príncipe de Asturias de las Letras 2014 a John Banville por «su inteligente, honda y original creación novelesca» y a su «otro yo, Benjamin Black, autor de turbadoras y críticas novelas policíacas.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1723, '9788440644022', 'Primera sangre', 1, '1994', 435, 'First >Blood', 'media/core/9788440644022.jpeg', 1, '2023-04-25 10:52:11.305296', '2023-04-25 10:52:11.305296', 1015, 1, 6, 5, NULL, '', '06_04', NULL, 8, 'https://es.wikipedia.org/wiki/First_Blood_(novela)', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1724, '9788437608136', 'Las uvas de la ira', 15, '2020', 609, 'The Grapes of Wrath', 'media/core/9788437608136.jpg', 1, '2023-04-25 10:54:43.580239', '2023-04-25 10:54:43.580239', 657, 1, 6, 5, 'Letras universales', '', '06_04', NULL, 153, 'John Steinbeck también sufrió los efectos de la Depresión; fue testigo del éxodo rural masivo que emigra del norte hacia el sur y tomó en los años 30 partido por los explotados, los jornaleros emigrantes." Las uvas de la ira" es la crónica de una familia depauperada en su viaje hacia una tierra de promisión, buscando trabajo y mejores condiciones de vida. Steinbeck sabe trascender lo puramente propagandístico o moralizante cuando unos personajes de ficción llenos de profundidad y humanidad, auténticos luchadores, no dudan en denunciar los abusos del poder y la despiadada crueldad y desamparo que sufren los más débiles.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1725, '9788408243205', 'La Conquista de América contada pata escépticos', 1, '2021', 619, NULL, 'media/core/9788408243205.jpg', 1, '2023-04-25 10:58:22.361282', '2023-04-25 10:58:22.361282', 26, 15, 6, 5, NULL, '', '06_04', NULL, 7, 'La conquista de América es una historia recurrente, llena de contradicciones, alianzas, traiciones y desencuentros. Pero detrás del relato que todos conocemos están las vidas de los personajes que lo protagonizaron y que, con sus decisiones ?en unas ocasiones meditadas y en otras fruto de increíbles casualidades?, cambiaron el rumbo de la historia mundial para siempre.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1726, '9788435018814', 'La Peste', 1, '2020', 1, 'La Peste', 'media/core/9788435018814.jpg', 1, '2023-04-25 11:00:23.202366', '2023-04-25 11:01:03.987910', 842, 1, 2, 5, 'Pocket', '', '06_04', NULL, 47, 'La peste narra las consecuencias del aislamiento de toda una ciudad, lo cual pone de manifiesto lo mejor y lo peor que cada uno de sus ciudadanos lleva dentro: sus miedos, traiciones, individualismo, pero también la solidaridad, la compasión, el espíritu de colaboración con el prójimo en tareas comunes... Novela apasionante , de gran densidad de pensamiento y de profunda comprensión del ser humano, se ha convertido en uno de los clásicos más indiscutibles de la literatura francesa de todos los tiempos y en uno de los más leídos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1727, '9788494845185', 'Una raza que desaparece. Los indios tehuelches de la Patagonia', 1, '2022', 76, NULL, 'media/core/9788494845185.jpg', 1, '2023-04-25 11:07:54.463175', '2023-04-25 11:07:54.463175', 1016, 45, 6, 5, 'Leer y viajar clásico', '', '06_04', NULL, 358, 'Este librito, publicado en 1894, es la primera defensa de los pueblos indígenas de la Patagonia. No había indicios de un defensor de los nativos americanos en Ramón Lista, el primer explorador de la Patagonia, involucrado en la masacre de los onas durante la expedición de 1886 a Tierra del Fuego. Gracias a la influencia de su suegro, fue nombrado gobernador de la región de Santa Cruz. Allí conoce a Kolia, una mujer tehuelche, y de esta relación nace una hija. Cuando la esposa de Lista se entera, se suicida de un tiro. Desde hace dos años, Lista vive con los tehuelches. Para estar más cerca de Kolia y su hijo, traslada la capital a Río Gallegos. De esta vida en común extrae lecciones sobre lo que entonces se llama Berbería y Civilización y descubre Berbería del lado de Argentina. Así, ocho años después de haber masacrado a los Onas, escribió “Una que desaparece", un alegato a favor de la Civilización, la de los indígenas. Nada de esto impedirá que Julio Argentino Roca, el presidente argentino, continúe con la “Conquista del Desierto” y extermine casi por completo a los pueblos originarios de la Patagonia. Cuando apareció el libro de Lista, sólo quedaban quinientos tehuelches.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1728, '8422622939', 'La balada de Caín', 1, '1987', 224, NULL, 'media/core/8422622939.jpg', 1, '2023-04-25 11:11:27.488377', '2023-04-25 11:11:27.488377', 1017, 1, 6, 5, NULL, '', '06_04', NULL, 58, 'PREMIO NADAL 1986. LA NOVELA QUE ENCUMBRÓ A MANUEL VICENTINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1729, '8471690292', 'Crónicas moriscas. Leyendas de la conquista de España', 1, '2001', 397, NULL, 'media/core/8471690292.jpg', 1, '2023-04-25 11:17:10.412065', '2023-04-25 11:17:10.412065', 496, 45, 6, 5, 'Bibliotec de escritores y temas granadinos', '', '06_04', NULL, 359, 'Washington Irving mundialmente famoso como literato romántico, fallecido hace poco más de un siglo; gran amante de España y de sus tradiciones y leyendas medievales, escribió sus bellísimos Cuentos de la Alhambra que se han publicado en numerosas ediciones; pero la fecunda mente y ágil pluma de tan ilustre escritor redactó también otras maravillosas e interesantes narraciones sobre nuestro país, entre las cuales destacan las "Leyendas de la Conquista de España" y "Crónicas moriscas", estas últimas, que sepamos, no traducidas hasta ahora al español. Las leyendas y crónicas no constituyen una obra histórica en el verdadero sentido de la palabra, sino un relato literario con "fundamento histórico". La amplitud de su contenido y los relatos tan sugestivos descritos en prosa poética despiertan el interés del lector.Leyendas y crónicas que en su conjunto constituyen una encantadora lectura. Por ello, este cautivador libro no debe faltar en ninguna biblioteca de seleccionado gusto literario.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1730, '9788417079260', 'Las nuevas Noches Árabes', 1, '2017', 317, NULL, 'media/core/9788417079260.jpg', 1, '2023-04-25 11:21:03.358284', '2023-04-25 11:21:03.358284', 494, 44, 6, 5, 'Misterio', '', '06_04', NULL, 360, 'En 1877, Stevenson viaja a la localidad francesa de Grèz con el fin de aliviar su enfermedad pulmonar. Por entonces estaba escribiendo una serie de pequeños ensayos que aparecerían en 1881 con el título de Virginibus Puerisque. Allí conoció a Fanny van der Grift, una norteamericana casada y con un hijo, con la que se casaría después de que ella obtuviera el divorcio. Stevenson se embarcó hacia California para celebrar la boda, y los recién casados recorrieron en viaje de luna de miel aquellas tierras entonces vírgenes (viaje que recogió en Los colonos de Silverado, en esta misma colección). Hasta su viaje a Francia, Stevenson sólo había escrito artículos, a los que siguieron otros dos libros de viajes: An Inland Voyage y The Amateur Emigrant. Fue a partir de este giro copernicano en su vida cuando comienza a escribir, entre 1877 y 1880, sus primeros relatos, que envía al London Magazine, al Cornhill Magazine y al Temple Bar, donde aparecen sucesivamente. En 1882 Stevenson reúne estos primeros cuentos en un volumen titulado Las nuevas noches árabes. Su carácter fragmentario no impide que la obra pueda leerse como una novela, pues las historias se entrelazan, al estilo de Las mil y una noches, bajo un denominador común: la aventura de la supervivencia en un medio hostil. Entre estos relatos se encuentran El club de los suicidas, El diamante del Rajá, y El pabellón de los Links -cima del genio narrativo de Stevenson, según Conan Doyle, quien lo consideraba «el mejor cuento del mundo». La presente edición incorpora la novela El dinamitero (1885), sobre los atentados cometidos en 1884 en Londres por militantes independentistas irlandeses, por cuanto enlaza con los demás relatos a través del personaje común del príncipe Florizel.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1731, '9788497594035', 'Últimas tardes con Teresa', 12, '2006', 471, NULL, 'media/core/9788497594035.gif', 1, '2023-04-25 11:23:35.081829', '2023-04-25 11:23:35.081829', 216, 1, 6, 5, 'Debolsillo', '', '06_04', NULL, 11, 'Ambientada en una Barcelona de claroscuros y contrastes, Últimas tardes con Teresa narra los amores de Pijoaparte, típico exponente de las clases más bajas marginadas cuya mayor aspiración es alcanzar prestigio social, y Teresa, una bella muchacha rubia, estudiante e hija de la alta burguesía catalana. Los personajes de esta novela a la vez romántica y sarcástica pertenecen ya, por derecho propio, a la galería de retratos que configuran toda una época. Hito de la literatura española contemporánea, esta obra consolidó internacionalmente el nombre de su autor.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1732, '9788498150063', 'La Tía Tula', 1, '2004', 141, NULL, 'media/core/9788498150063.JPG', 1, '2023-04-25 11:26:19.650170', '2023-04-25 11:26:19.650170', 639, 1, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, 'La tía Tula, sin duda la más popular de las novelas de Miguel de Unamuno (1864-1936), es, según su autor, «la historia de una joven que, rechazando novios, se queda soltera para cuidar a unos sobrinos, hijos de una hermana que se le muere. Vive con el cuñado, a quien rechaza para marido, pues no quiere manchar con el débito conyugal el recinto en que respiran aire de castidad sus hijos. Satisfecho el instinto de maternidad, ¿para qué perder su virginidad? Es virgen madre». Pero sobre este cañamazo argumental teje Unamuno una obra cargada de sentidos plurales: Tula, la protagonista, que encarna la concepción tradicional de la familia y de la mujer y que es, a al vez, víctima de ella, ejemplifica la figura del agonista unamuniano dividido en mil contradicciones. Anna Caballé, profesora de Literatura Española de la Universidad de Barcelona, ofrece en la Introducción un estudio que explora en los distintos planos -ideológico, psicológico y artístico- las numerosas sugerencias que en La tía Tula se condensan', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1733, 'B20736', 'Cuentakilómetros', 1, '2017', 158, NULL, 'media/core/B20736.jpg', 1, '2023-04-25 11:29:19.531271', '2023-04-25 11:29:19.531271', 1019, 1, 6, 5, 'Hotusa', '', '06_04', NULL, 32, 'Un viajero sin nombre llega a México. Con un pasado desconocido y un futuro incierto, solo el presente funciona para él en una visita al país de lo inesperado, donde el protagonista resulta ser cada lugar y la realidad, lamás convincente de las ficciones. Comienza así un viaje en el que se describen los acontecimientos más insólitos y singulares que tienen lugar en las distintas regiones por las que pasa, capítulo a capítulo, kilómetro a kilómetro. Acaballo entre la novela y el libro de viajes, Cuentakilómetros transita por un mundo literario cercano al realismo mágico, siguiendo una hábil estructura de episodios muy breves y casi autónomos, que culminan con un giro inesperado ysorprendente.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1734, '9788448030278', 'La Vengadora', 1, '1995', 430, 'The Avenger', 'media/core/9788448030278.jpg', 1, '2023-04-25 11:33:14.379170', '2023-04-25 11:33:14.379170', 658, 13, 6, 5, NULL, '', '06_04', 'La Puerta del Caos III', 9, 'Los dioses del Orden responden a la súplica del Sumo Iniciado y tienden una trampa para acabar con la usurpadora Ygorla, la hija del demonio Narid-na-Gost.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1735, '9788448030261', 'La Usurpadora', 1, '1995', 351, 'The Pretender', 'media/core/9788448030261.jpg', 1, '2023-04-25 11:35:03.469640', '2023-04-25 11:35:03.469640', 658, 13, 6, 5, NULL, '', '06_04', 'La Puerta del Caos II', 9, 'Tanto los dioses como los mortales se han olvidado de Ygorla. Y ese error podría costarles la pérdida de sus mundos. La hija del demonio ha alcanzado la mayoría de edad... y el mundo tiene una nueva y terrible emperatriz.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1736, '9788448030254', 'La Impostora', 1, '1995', 320, 'The Deceiver', 'media/core/9788448030254.jpeg', 1, '2023-04-25 11:36:17.270973', '2023-04-25 11:37:38.513395', 658, 13, 6, 5, NULL, '', '06_04', 'La Puerta del Caos I', 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1737, '8432038873', 'El Príncipe', 1, '1983', 123, NULL, 'media/core/8432038873.jpg', 1, '2023-04-25 15:49:52.391535', '2023-04-25 15:49:52.391535', 1020, 2, 6, 5, 'Clásicos univesales Planeta', '', '06_04', NULL, 7, 'Redactado por Nicolás Maquiavelo (1469-1527) en 1513, cuando se hallaba en el ostracismo a causa del triunfante retorno al poder de los Médicis, El Príncipe ha pasado a la historia del pensamiento por constituir el arranque de la reflexión teórica sobre los orígenes del poder y la estructura del mismo. En medio de las exhortaciones moralizadoras, los encubrimientos retóricos y las justificaciones ideológicas, la contraposición entre la "fortuna" y la "virtud", capital en la obra, es una de las articulaciones conceptuales mediante las que comienza la política a abrirse paso como saber científico y como práctica sometida a pautas de regularidad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1738, '8420692190', 'Las flores del mal', 1, '1985', 196, 'Les fleurs du mal', 'media/core/sin-imagen_ptlDfmi.jpg', 1, '2023-04-25 15:52:05.858889', '2023-04-25 15:52:05.858889', 631, 4, 6, 5, 'El libro de bolsillo', '', '06_04', NULL, 69, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1739, 'B43031', 'El coqueto aerodinámico rocanrol color caramelo de ron', 1, '1972', 93, 'The Kandy-Kolored Tangerine-Flake Streamline Baby', 'media/core/B43031.jpg', 1, '2023-04-25 15:55:46.524947', '2023-04-25 15:55:46.524947', 863, 17, 6, 5, 'Arquitectura y diseño', '', '06_04', NULL, 12, 'Tom Wolfe no es arquitecto, ni crítico, ni cosa parecida, aunque hayamos incluido esta selección de textos suyos en la Serie de arquitectura y diseño. Es simplemente un periodista al que le gusta explicar los sucesos culturales de nuestra sociedad actual. Pero sus escritos son tan sugerentes que han hecho ver a los arquitectos fenómenos en la ciudad, la arquitectura y el diseño que ellos por sí mismos fueron incapaces de detectar. El ha sido el «descubridor» de Las Vegas o de la arquitectura electrográfica. Pero los cuatro escritos que publicamos no tocan solamente aspectos de la arquitectura y del diseño, sino también de muchos otros campos en los que se reflejan los sucesos culturales que se produjeron a lo largo de los años sesenta. Cuando publicamos la primera edición de este libro en 1972, Tom Wolfe era un perfecto desconocido. Hoy, cuando su obra está casi por entero publicada en nuestro idioma, nos satisface poder verificar, diez años después, que nunca es tarde para reconocer a un autor que ahora es aclamado como uno de los más insignes pioneros del Nuevo periodismo norteamericano. Recomendamos este libro en especial a aquellos que se interesen por los dragsters, la tabla hawaiana, la moda del vestido y del peinado, los coches «pichicateados», el arte culto y popular o el modo en que disfrutan el tiempo libre jóvenes y mayores, en particular en la Costa Oeste de Estados Unidos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1740, '9788495808936', '¿Acaso no matan a los caballos?', 1, '2002', 170, 'Tey Shoot Horses, Don''t They?', 'media/core/9788495808936.jpg', 1, '2023-04-25 15:59:42.034733', '2023-04-25 15:59:42.034733', 1021, 1, 6, 5, 'Clásicos Gimlet', '', '06_04', NULL, 361, 'La Gran Depresión de los años treinta obligó a mucha gente a tomar medidas desesperadas para sobrevivir. Los concursos de resistencia de baile, que florecieronen aquella época, parecían una manera fácil de ganar dinero extra, uno sólo tenía que bailar hasta caer rendido. Pero, en ocasiones, la competencia entre los participantes y la violencia del baile llegaban a extremos insospechados. En ¿Acaso no matan a los caballos? Asistimos, hora tras hora, al escalofriante espectáculo que dan dos de los bailarines.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1741, '8423900983', 'Libro de Buen Amor', 14, '1976', 161, NULL, 'media/core/8423900983.jpeg', 1, '2023-04-25 16:01:57.831142', '2023-04-25 16:01:57.831142', 901, 4, 6, 5, 'Colección Austral', '', '06_04', NULL, 18, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1742, '9788417821807', 'Arsène Lupin. Caballero ladrón', 1, '2021', 222, 'Arsène Lupin, gentleman cambreioler', 'media/core/9788417821807.jpg', 1, '2023-04-25 16:04:39.345268', '2023-04-25 16:04:39.345268', 1022, 1, 6, 5, 'Ficción', '', '06_04', NULL, 30, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1743, '9788415625575', 'A sangre y fuego. Héroes, bestias y márires de España', 1, '2013', 311, NULL, 'media/core/9788415625575.jpg', 1, '2023-04-25 16:07:23.471703', '2023-04-25 16:07:23.471703', 1023, 44, 6, 5, NULL, '', '06_04', NULL, 347, 'Héroes, bestias y mártires de EspañaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1744, '8433912011', 'A la rica marihuana y otros sabores', 2, '1981', 235, 'Red-dirt marijuana and Other Tastes', 'media/core/8433912011.jpg', 1, '2023-04-25 16:12:27.370154', '2023-04-25 16:12:27.370154', 1024, 17, 6, 5, NULL, '', '06_04', NULL, 6, 'Terry Southern es uno de los pioneros y maestros del llamado Nuevo Periodismo. Así lo reconoce Tom Wolfe en su libro El Nuevo Periodismo, donde afirma: «Fue el primer ejemplo que yo descubrí de una forma de periodismo en la que el reportero empieza preparando un artículo de encargo (ve a Mississippi y entérate de lo que ocurre cuando 500 bastoneras púberes se enfrentan en competición) y acaba escribiendo una curiosa forma de autobiografía.» En estos textos -en torno al mundo de la droga, la música, la política exterior yanqui, la CIA, el periodismo, la moral convencional, Frau Kafka, Franz Kafka & Doctor Freud, y también Mickey Spillane, etc., etc.- se detecta con una gran sagacidad la sensibilidad de la década de los sesenta.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1745, '8402067107', 'El amante de Lady Chatterley', 2, '1982', 379, 'Lady Chatterley''s Lover', 'media/core/8402067107.jpeg', 1, '2023-04-25 16:15:09.003458', '2023-04-25 16:15:09.003458', 1025, 1, 6, 5, 'Club Bruguera', '', '06_04', NULL, 126, 'Inválido de guerra, Sir Clifford Chatterley y su esposa Connie llevan una existencia acomodada, aparentemente plácida, rodeada de los placeres burgueses de las reuniones sociales y regida por los correctos términos que deben ser propios de todo buen matrimonio. Connie, sin embargo, no puede evitar sentir un vacío vital. La irrupción en su vida de Mellors, el guardabosque de la mansión familiar, la pondrá en contacto con las energías más primarias e instintivas y relacionadas con la vida. La fuerte corriente relacionada con la energía sexual que recorre casi toda la obra de D. H. Lawrence encuentra una de sus máximas expresiones en EL AMANTE DE LADY CHATTERLEY, novela que se vio envuelta en la polémica y el escándalo desde el momento de su aparición.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1746, '8485855033', 'La danza macabra de holbein', 1, '1980', 100, NULL, 'media/core/8485855033.jpeg', 1, '2023-04-25 16:19:25.504441', '2024-02-22 19:03:21.980669', 1026, 36, 6, 5, NULL, '', '06_06', NULL, 362, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1747, '840204719X', 'Fundación', 8, '1982', 254, 'Foundation', 'media/core/840204719X.jpg', 1, '2023-04-25 16:21:45.359862', '2023-04-25 16:21:45.359862', 341, 3, 6, 5, 'Libro amigo', '', '06_04', NULL, 126, 'Isaac Asimov es el autor más influyente y destacado de la ciencia ficción y la divulgación científica del siglo XX. ''Fundación'' es el comienzo de la primera trilogía de Las Fundaciones, una de las obras maestras del género. Mucho tiempo después de que la Tierra pasara al olvido, la galaxia se unificó alrededor de un Imperio pacífico gobernado desde la majestuosa ciudad de Trántor. El sistema funcionó y prosperó durante incontables generaciones. Todo el mundo creía que duraría eternamente... Todos menos Hari Seldon, la mente científica más poderosa de su tiempo. Sus investigaciones en el campo de la psicohistoria (las matemáticas aplicadas a las grandes aglomeraciones humanas) auguraban un desastre imposible de prevenir. El Imperio estaba condenado... Pero el Plan Seldon era una estrategia a largo plazo, destinada a minimizar las peores consecuencias del futuro que se avecinaba. Para ello se establecieron dos Fundaciones en ambos extremos de la galaxia. Esta es la historia de la primera.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1748, '842390444X', '¡Adiós  "Cordera"! y otros couentos', 6, '1977', 147, NULL, 'media/core/842390444X.jpeg', 1, '2023-04-25 16:24:46.439399', '2023-04-25 16:24:46.439399', 611, 44, 6, 5, 'Colección Austral', '', '06_04', NULL, 18, 'https://es.wikipedia.org/wiki/%C2%A1Adi%C3%B3s,_Cordera!', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1749, '9788492257317', 'Elogio de la insurrección', 1, '1997', 160, NULL, 'media/core/9788492257317.jpg', 1, '2023-04-26 06:18:08.437650', '2023-04-26 06:18:08.437650', 1027, 2, 6, 5, NULL, '', '06_04', NULL, 341, 'Donatien Alphonse François de Sade (1740-1814) ha dejado de ser un autor maldito. Sus obras, condenadas durante más de un siglo al infierno de las bibliotecas, se editan y comentan sin censura o cortapisa. Pero, ¿quién lee hoy al marqués? Su nombre evoca a lo sumo placeres cruentos, y se olvida que, además de un fabuloso escritor, Sade fue pensador sólito a la par que subversivo. Sus ideas sobre Dios, la naturaleza o la condición humana de las que aquí se ofrece una breve antología componen un verdadero elogio de la insurrección.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1750, '9788416288649', 'El alma del hombre bajo el Socialismo', 1, '2016', 92, NULL, 'media/core/9788416288649.jpg', 1, '2023-04-26 06:21:05.098936', '2023-04-26 06:21:05.098936', 498, 2, 6, 5, NULL, '', '06_04', NULL, 341, 'Oscar Wilde, esteta, dramaturgo, presidiario en la intolerante y vengativa sociedad victoriana, nos dejó obras notables, desde La importancia de llamarse Ernesto hasta El retrato de Dorian Gray o Vera y los nihilistas, además de algunos ensayos que muestran su preocupación por el arte, la cultura y la sociedad. Uno de esos ensayos es El alma del hombre bajo el socialismo, donde, en su defensa del socialismo, ha cía afirmaciones, como las siguientes, que siguen vigentes: A través de la desobediencia, se ha progresado; a través de la desobediencia, y a través de la rebelión. El socialismo, el comunismo, o como uno quiera llamarlo, al convertir la propiedad privada en riqueza pública, y al reemplazar la competencia por la cooperación, restituirá a la sociedad su condición de organismo sano, y asegurará el bienestar material de cada miembro de la comunidad. Dará a la vida una base y un medio adecuados.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1751, '9788417700973', 'Principios del Comunismo', 1, '2020', 96, NULL, 'media/core/9788417700973.jpg', 1, '2023-04-26 06:24:15.264430', '2023-04-26 06:24:15.264430', 1028, 2, 6, 5, NULL, '', '06_04', NULL, 341, '''Principios del comunismo'' es el precedente inmediato de un texto que dejaría una huella indeleble en la historia de la humanidad: el ''Manifiesto del Partido Comunista''. La redacción de los Principios le había sido encargada a Engels por la Liga de los Comunistas, organización cuya historia está aquí recogida por el propio Engels. Este volumen incluye también el texto que Lenin escribió con motivo del fallecimiento de Engels, el 5 de agosto de 1985.', 'Texto seguido de:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1752, '9788467254938', 'De las conjuras. (Extracto de Discursos sobre la primera década de Tito Livio)', 1, '2012', 133, 'Discorsi sopra la prima deca di Tito Livio (extractos)', 'media/core/9788467254938.jpg', 1, '2023-04-26 06:30:16.524770', '2023-05-13 10:10:39.456021', 1020, 2, 6, 5, 'Great Ideas', '', '06_04', NULL, 73, '"El muerto no puede pensar en la venganza."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1753, '9788420646695', 'La sombras del mundo (cuentos)', 1, '1995', 93, NULL, 'media/core/9788420646695.jpg', 1, '2023-04-26 06:34:07.251616', '2023-04-26 06:34:07.251616', 1029, 44, 6, 5, 'Alianza Cien', '', '06_04', NULL, 69, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1754, '9780141192970', 'Nationalism. All the great nations of Europe have their victims in other parts of the world', 1, '2010', 91, NULL, 'media/core/9780141192970.jpg', 1, '2023-04-26 06:37:49.147389', '2023-04-26 06:37:49.147389', 627, 2, 6, 5, 'Great Ideas', '', '06_04', NULL, 11, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1755, '9788491050155', 'Los pazos de Ulloa', 1, '2015', 391, NULL, 'media/core/9788491050155.jpg', 1, '2023-04-26 06:40:29.952169', '2023-04-26 06:40:29.952169', 1030, 1, 6, 5, 'Penguin clásicos', '', '06_04', NULL, 11, 'Edición de Marina Mayoral, catedrática de literatura española en la Universidad Complutense de MadridINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1756, '9788476518076', 'El arte de la guerra. Los trece artículos', 1, '2012', 176, NULL, 'media/core/9788476518076.jpeg', 1, '2023-04-26 06:44:11.029223', '2023-04-26 06:44:11.029223', 1031, 2, 6, 5, 'Los pequeños libros de la sabiduría', '', '06_04', NULL, 363, 'Sun Tzu enseña que la guerra siempre es negativa, incluso para el vencedor, y que lo ideal es vencer sin llegar a luchar. Ésta es la esencia de la antigua sabiduría taoísta aplicada a la resolución de todos los conflictos humanos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1757, 'Austral_1', 'La rebelión de las masas', 14, NULL, 226, NULL, 'media/core/Austral_1.jpg', 1, '2023-04-26 06:48:38.720995', '2023-04-26 06:48:38.720995', 473, 2, 6, 5, 'Colección Austral', '', '06_04', NULL, 18, 'La obra más difundida y famosa de Ortega y Gasset.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1758, '8421704273', 'El hombre del perrito', 1, '1973', 186, 'L''homme au petit chien', 'media/core/8421704273.jpg', 1, '2023-04-26 06:53:12.693017', '2023-04-26 06:53:12.693017', 107, 14, 6, 5, 'las novelas de Simenon', '', '06_04', NULL, 295, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1759, '2415223292602', 'Microversos en red. Poesía en un tuit', 1, '2020', 74, NULL, 'media/core/2415223292602.jpg', 1, '2023-04-26 06:56:27.559132', '2023-04-26 06:56:27.559132', 572, 4, 6, 5, 'Verso & cuento', '', '06_04', NULL, 11, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1760, '9788467256307', 'El hereje', 1, '2013', 463, NULL, 'media/core/sin-imagen_IokoxKj.jpg', 1, '2023-04-26 06:59:05.120418', '2023-04-26 06:59:05.120418', 830, 16, 6, 5, NULL, '', '06_04', NULL, 58, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1761, '9788418952104', 'El librero de la Atlántida', 1, '2021', 434, NULL, 'media/core/9788418952104.jpg', 1, '2023-04-26 07:01:41.149994', '2023-04-26 07:01:41.149994', 208, 1, 6, 5, 'Libros en el bolsillo', '', '06_04', NULL, 68, 'Con el hallazgo de unos restos arqueológicos durante la construcción de una urbanización de lujo en Sanlúcar de Barrameda, arranca esta fascinante novela que le seducirá desde sus primeras líneas. Alejandro, un tímido librero de Cádiz, sólo tiene por amigo a un viejo marinero, el Corcho, que cuenta leyendas de antiguas ciudades sumergidas mientras bebe en las tabernas de la Caleta gaditana. Un estudio científico, que asegura que se avecina una nueva glaciación y que desmonta la común creencia del calentamiento global, modifica los planes de expansión de una importante empresa constructora, desatando una guerra por acumular suelo. Mientras, la naturaleza parece encolerizada con los hombres que la golpean. Y, como telón de fondo, el mito de la más grande, poderosa y mágica de todas las civilizaciones. El librero de la Atlántida es una novela sorprendente, ágil y hermosa, que removerá sus más profundas inquietudes y reavivará sus intuiciones más primitivas y atávicas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1762, '9788423341474', 'El legado Göring', 1, '2009', 455, NULL, 'media/core/9788423341474.jpg', 1, '2023-04-26 07:04:52.591851', '2023-04-26 07:04:52.591851', 1033, 1, 6, 5, 'Bestseller Internacional', '', '06_04', NULL, 59, 'Un conde italiano, propietario de un cuadro de Vermeer, acepta la oferta del canónigo de la catedral de Florencia de esconder la pintura ante el acoso de un oficial de las SS que quiere obtenerla a toda costa. Lo que no sabe es que el canónigo actúa en connivencia con los nazis. Veinte años más tarde, la viuda del oficial alemán regresa con una nueva identidad y unos documentos que amenazan con sacudir los cimientos de la Iglesia católica.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1763, '8434580357', 'El retrato de Dorian Gray', 1, '1982', 204, NULL, 'media/core/8434580357.jpg', 1, '2023-04-26 07:07:55.211182', '2023-04-26 07:07:55.211182', 498, 1, 6, 5, 'Biblioteca básica Salvat', '', '06_04', NULL, 3, 'El genial Oscar Wilde (1854-1900) quiso hacer de la belleza un refinamiento de la inteligencia, y para ello creó a uno de sus personajes más famosos Dorian Gray, un hombre que encarna el mal y su castigo. El retrato de Dorian Gray es una de las piedras angulares en los debates entre la ética y la estética, el bien y el mal, el arte y la vida. Un clásico de la literatura que sigue asombrando a todo tipo de lectores.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1764, '9788498150315', 'El sí de las niñas', 1, '2005', 126, NULL, 'media/core/9788498150315.jpg', 1, '2023-04-26 07:15:40.436231', '2023-04-26 07:15:40.436231', 765, 1, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, 'Moratín, neoclásico por raciocinio y por criterio artístico, lleva en sí, por temperamento, los tiempos nuevos. En esta obra, justamente celebrada como la mejor de su producción, reivindica el derecho de los jóvenes al matrimonio por amor y no por imposición familiar. Desde un tono de bondad amable, «El sí de las niñas» es un alegato contra los métodos educativos de la época en los mismos inicios del siglo XIX, hecho por un autor dramático que, por ilustrado, trataba de educar desde las tablas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1765, '9788498150285', 'Los intereses creados', 1, '2005', 126, NULL, 'media/core/9788498150285.JPG', 1, '2023-04-26 07:18:51.778402', '2023-04-26 07:18:51.778402', 1034, 1, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, '"Mundo es este de toma y daca, lonja de contratación, casa de cambio, y antes de pedir ha de ofrecerse... Para salir adelante con todo, mejor que crear afectos es crear intereses". Sobre esta base ideológica y sobre la pauta de la commedia dellarte, construye el premio Nobel Jacinto Benavente su mejor obra, Los intereses creados.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1766, '9788498150025', 'Fuente Ovejuna', 1, '2005', 124, NULL, 'media/core/9788498150025.jpeg', 1, '2023-04-26 07:20:31.688701', '2023-04-26 07:20:31.688701', 767, 41, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, 'En este drama, el protagonista es todo el pueblo de fuenteovejuna, con lo cual adquiere la obra una grandeza épica extraordinaria. Dicho pueblo, cansado de los atropellos del cruel comendador mayor de calatrava, Don Femán Gómez de Guzmán y de su gente de armas, se levanta contra el, asalta el castillo y le da muerte conjuntamente con sus allegados, arrojándolo por una ventana y arrastrando luego su cuerpo entre el vecindario triunfante. - La justicia llega al lugar, y mediante terribles tormentos, se esfuerza pr descubrir quien es el asesino del comendador, mas “todos a una” contestan: “Fuenteovejuna”, callando el nombre del culpable, que realmente fue frondoso por vengarse de los atropellos del comendador contra Laurencia, a quien ama. Los reyes católicos, que llegaron fuenteovejuna para hacer justicia, absuelven al pueblo y hacen que este, en adelante, no dependa del señorío de la nombrada orden de calatrava, sino de la propia corona.', '');
