INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1773, '9788498150179', 'Eloísa está debajo de un almendro', 1, '2005', 174, NULL, 'media/core/9788498150179.jpeg', 1, '2023-04-26 07:36:54.762326', '2024-02-22 18:58:52.907955', 1038, 41, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1774, '9788498150360', 'Poeta en Nueva Work', 1, '2005', 126, NULL, 'media/core/9788498150360.JPG', 1, '2023-04-26 07:38:52.809227', '2023-04-26 07:38:52.809227', 766, 4, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1775, '9788498150117', 'El perro del hortelano', 1, '2005', 127, NULL, 'media/core/9788498150117.jpeg', 1, '2023-04-26 07:40:12.693301', '2023-04-26 07:40:12.693301', 767, 41, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1776, '9788498150056', 'Nada', 1, '2005', 287, NULL, 'media/core/9788498150056.jpeg', 1, '2023-04-26 07:42:36.661655', '2023-04-26 07:42:36.676179', 601, 1, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, 'Andrea llega a Barcelona para estudiar Letras. Sus ilusiones chocan, inmediatamente, con el ambiente de tensión y emociones violentas que reina en casa de su abuela. Andrea relata el contraste entre este sórdido microcosmos familiar—poblado de seres extraños y apasionantes—y la frágil cordialidad de sus relaciones universitarias, centradas en la bella y luminosa Ena. Finalmente los dos mundos convergen en un diálogo dramático. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1777, '9788498150070', 'El burlador de Sevilla', 1, '2005', 142, NULL, 'media/core/9788498150070.jpg', 1, '2023-04-26 07:44:56.156989', '2023-04-26 07:44:56.156989', 1039, 41, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, '"El burlador de Sevilla" es la primera obra en la que se desarrolla el mito de Don Juan, personaje universal del teatro en lengua castellana y uno de los más célebres, junto con la figura del Comendador, de toda nuestra literatura. Esta nueva edición, además de ofrecer un texto firmemente establecido a partir del cotejo de las ediciones facsímiles de la obra y de algunas otras variantes registradas en distintas representaciones, aclara el prolongado debate acerca de la autoría, que, tras una reciente serie de estudios basados en análisis objetivos y nuevas metodologías contrastables, apunta sin lugar a dudas al actor y dramaturgo Andrés de Claramonte, contemporáneo de otros autores de renombre como Tirso de Molina o Lope de Vega, a quienes largamente se han atribuido varias de sus obras.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1778, '9788498150186', 'Soledades y otros poemas', 1, '2005', 237, NULL, 'media/core/sin-imagen_LEpwW83.jpg', 1, '2023-04-26 07:46:36.269311', '2023-11-14 18:59:45.778681', 1040, 4, 6, 5, 'Clásicos españoles', '', '06_04', NULL, 264, '', '');
