INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1781, '9788418481345', 'Rebelión en Asturias', 1, '2021', 104, 'Révolte dans les Asturies', 'media/core/9788418481345.jpg', 1, '2023-04-26 08:41:55.813631', '2023-04-26 08:41:55.813631', 842, 41, 6, 5, NULL, '', '06_04', NULL, 364, 'Rebelión en Asturias relata la insurrección obrera de 1934 y la implacable represión del ejercito enviado por la República para contenerla y que terminó por regar de sangre toda la región. Un año despues de la sublevación, desde Argel y con solo 22 años, Albert Camus escribió esta obra de teatro como homenaje al espíritu de lucha del pueblo asturiano y a las más de 1500 personas que fueron asesinadas, en su mayor parte civiles. En palabras de Romain Rolland, "desde la Comuna de París no se había visto nada tan hermoso como el movimiento revolucionario de Asturias".', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1782, '848000200987', 'La Ciencia Ficción a la luz de gas', 1, '1990', 281, NULL, 'media/core/848000200987.jpeg', 1, '2023-04-26 08:45:10.960704', '2023-04-26 08:45:10.960704', 572, 44, 6, 5, NULL, '', '06_04', NULL, 365, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1783, '9788402085306', 'En el camino', 2, '1983', 400, 'On the Road', 'media/core/9788402085306.jpeg', 1, '2023-04-26 08:48:46.911063', '2023-04-26 08:48:46.911063', 1041, 1, 6, 5, 'Libro amigo', '', '06_04', NULL, 126, 'Con el paso del tiempo, En el camino, un libro que fue la biblia y el manifiesto de la generación beat, se ha convertido en una «novela de culto» y en un clásico de la literatura norteamericana.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1784, '8471666871', 'Jorge Manrique', 1, '1980', 267, NULL, 'media/core/8471666871.jpg', 1, '2023-04-26 08:51:02.745295', '2023-04-26 08:51:02.745295', 1042, 31, 6, 5, 'Escritores de todos los tiempos', '', '06_04', NULL, 366, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1785, '9788415130208', 'La juguetería errante. Un misterio para Gervase Fen', 9, '2016', 312, 'The Moving Toyshop', 'media/core/9788415130208.jpg', 1, '2023-04-26 08:54:37.278510', '2023-04-26 08:54:37.278510', 1043, 14, 6, 5, NULL, '', '06_04', 'Gervase Fen 3', 367, 'La juguetería errante es un clásico de la novela de detectives inglesa, considerado unánimemente una de las cumbres indiscutibles del género.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1786, 'Gerona_1924', 'Otras lecciones de cosas (Lecturas Científicas))', 7, '1924', 193, NULL, 'media/core/Gerona_1924.jpg', 1, '2023-04-26 09:00:56.058353', '2023-04-26 09:00:56.058353', 1044, 36, 6, 5, NULL, '', '06_04', NULL, 368, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1787, '9788497612517', 'Elogio del Islam español', 1, '2005', 118, NULL, 'media/core/9788497612517.jpg', 1, '2023-04-26 09:12:09.076097', '2023-04-26 09:12:09.076097', 1045, 45, 6, 5, NULL, '', '06_04', NULL, 369, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1788, '9788494653162', 'Cuentos de Terror', 2, '2017', 191, NULL, 'media/core/9788494653162.jpg', 1, '2023-04-26 09:14:25.290916', '2023-04-26 09:14:25.290916', 871, 12, 6, 5, 'Misterio', '', '06_04', NULL, 360, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1789, '8433460145', 'Gaseosa de ácido eléctrico', 1, '1978', 402, NULL, 'media/core/8433460145.jpeg', 1, '2023-04-26 09:24:55.668779', '2023-04-26 09:26:22.796841', 863, 17, 6, 5, NULL, '', '06_04', NULL, 224, 'Sin ser novela, esta es una obra maestra de la novela: así de simple. En Gaseosa de ácido eléctrico Tom Wolfe pone en juego toda su reconocida habilidad literaria para dar cuenta de las andanzas, físicas y mentales, de Ken Kesey (el autor de Alguien voló sobre el nido del cuco) y su grupo durante las primeras experiencias públicas con LSD.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1790, '9788445007587', 'Conduciendo a ciegas', 1, '1999', 243, 'Driving Blind', 'media/core/9788445007587.jpg', 1, '2023-04-26 09:29:00.674738', '2023-04-26 09:29:00.674738', 787, 44, 6, 5, NULL, '', '06_04', NULL, 7, 'En estos veintidós relatos, Bradbury nos transporta una vez más a estos lugares increíbles, los destinos del corazón, revelados como no los hemos visto nunca antes, ni en la luz brillante del día ni en la oscuridad de la noche. Inolvidables excursiones a lo fantástico, viajes gloriosos a través del tiempo y la memoria, intercalados con extraños e inesperados desvíos a lo incómodo y desconcertante, donde las sorpresas esperan detrás de cada curva y más allá de cada señal del camino.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1791, 'Losada_1966', 'Teatro 2', 1, '1966', 254, NULL, 'media/core/Losada_1966.jpg', 1, '2023-04-26 09:33:20.346914', '2023-04-26 09:33:20.346914', 853, 41, 2, 5, NULL, '', '06_04', NULL, 370, '', '- La noche de la IguanaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1792, '9788416995141', 'La moral anarquista. Justicia y Moralidad', 1, '2017', 122, NULL, 'media/core/9788416995141.jpg', 1, '2023-04-26 09:35:24.392243', '2023-04-26 09:35:24.392243', 1046, 2, 6, 5, NULL, '', '06_04', NULL, 341, 'El debate central del anarquismo de finales el XIX sobre el amoralismo y la legitimidad del robo o el uso de la dinamita como prácticas revolucionarias estarán muy presentes cuando Kropotkin publique La moral anarquista. Con esta obra, Kropotkin fija las líneas maestras de un proyecto largamente acariciado: establecer una filosofía moral para el anarquismo.Kropotkin defiende que la filosofía anarquista se basa en la filosofía de la evolución y que existe una moral pública anterior a la ley basada en ?hábitos de moral? surgidos de la cooperación, una cooperación necesaria en la lucha por la existencia y más importante para la evolución que la lucha dentro de cada especie.Las necesidades de la vida en sociedad requieren de hábitos morales, unos hábitos que permiten fundar una ?teoría? moral. Kropotkin define una moral que se aleja radicalmente de los sistemas éticos basados en la recompensa y el cálculo utilitario en la vida presente o futura, y apunta a una moral nueva sin ningún tipo de sanción ni obligación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1793, '8474613221', 'Artículos de costumbres', 1, '1984', 180, NULL, 'media/core/8474613221.jpg', 1, '2023-04-26 09:38:25.675766', '2023-04-26 09:38:25.675766', 779, 17, 6, 5, NULL, '', '06_04', NULL, 194, 'Paradigma del Romanticismo español más auténtico, Larra fue un agudísimo observador de la realidad que lerodeaba. Sus artículos de costumbres son ventanas abiertas a la España del siglo xix; sus comentarios políticos, dardosenvenenados contra unas estructuras anquilosadas; sus textos de crítica literaria, acertados análisis repletos depropuestas e ideas para mejorar el panorama de las letras españolas y desligarse de la por entonces omnipresenteinfluencia de la literatura francesa. Larra es hijo de su tiempo, pero también un escritor actual cuya influencia aúnes palpable dos siglos después de su nacimiento. «La ironía de Larra burlona a trechos, y a trechos, amarga essiempre extraordinariamente personal. Sus cuadros de costumbres, llenos de flechas emponzoñadas contra el patriotismode los castellanos viejos o la cerrazón de los facciosos partidarios de Don Carlos, figuran por derecho propio entrelas obras más importantes de nuestra literatura». Juan Goytisolo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1794, '8474613884', 'Ensayos', 1, '1984', 247, NULL, 'media/core/8474613884.jpeg', 1, '2023-04-26 09:41:07.459888', '2023-04-26 09:41:07.459888', 1047, 2, 6, 5, NULL, '', '06_04', NULL, 194, 'En 1571, tras sufrir un accidente montando a caballo, Michel de Montaigne abandona su posición como magistrado de Burdeos para retirarse a su castillo y empezar a escribir. Ese es el inicio, casi novelesco, de una de las obras más importantes de la cultura occidental. «No enseño ni adoctrino, lo que hago es relatar», afirma Montaigne. Y entretanto dialoga con los pensadores clásicos sobre todo tipo de cuestiones relativas a la condición humana. Sus escritos son continuas tentativas de encontrar respuestas casi como si se tratara de un experimento, una probatura, unessai, un ensayo. El hilo conductor: una reflexión acerca de «sí mismo».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1795, '8474613914', 'La religiosa', 1, '1985', 247, 'La religiense', 'media/core/8474613914.jpeg', 1, '2023-04-26 09:44:02.630561', '2023-04-26 09:44:02.630561', 1048, 1, 6, 5, NULL, '', '06_04', NULL, 194, 'A Suzanne Simonin no le espera el matrimonio, ni la vida acomodada de sus hermanas. A Suzanne Simonin sus padres le reservan la clausura de un convento. Empobrecido tras las generosas dotes concedidas a las dos hermanas mayores —y sin garantías de su paternidad—, el señor Simonin obliga a Suzanne a tomar los hábitos pese a su absoluta falta de vocación.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1796, '8474614732', 'Obra poética I', 1, '1985', 206, NULL, 'media/core/8474614732.jpg', 1, '2023-04-26 16:17:19.048079', '2023-04-26 16:17:19.048079', 1049, 4, 6, 5, NULL, '', '06_04', NULL, 194, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1797, '8474614740', 'Obra Poética II', 1, '1985', 171, NULL, 'media/core/8474614740.jpg', 1, '2023-04-26 16:18:36.601953', '2023-04-26 16:18:36.601953', 1049, 4, 6, 5, NULL, '', '06_04', NULL, 194, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1798, '8485348400', 'Viaje alrededor del Mundo', 1, '1982', 174, 'A naturalist''s voyage round the world', 'media/core/sin-imagen_pFMHYIT.jpg', 1, '2023-04-26 16:21:39.140972', '2023-04-26 16:21:39.140972', 476, 28, 6, 5, NULL, '', '06_04', NULL, 371, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1799, '9788423918331', 'Poesías completas', 1, '1997', 466, NULL, 'media/core/9788423918331.jpg', 1, '2023-04-26 16:24:02.491346', '2023-04-26 16:24:02.491346', 1035, 4, 6, 5, 'Colección Austral', '', '06_04', NULL, 18, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1800, '9788422694564', 'Un asunto de honor (Cachito)', 1, '1995', 120, NULL, 'media/core/9788422694564.jpg', 1, '2023-04-26 16:27:24.625766', '2023-04-26 16:27:24.625766', 73, 27, 6, 5, NULL, '', '06_04', NULL, 75, 'Relato corto, cuento breve, moderna historia de hadas y piratas, de buenos y malos, escrita con una acción trepidante y un humor agridulce y desesperado, Un asunto de honor cuenta la historia de Manolo, joven camionero y ex-presidiario, y María, la Cenicienta cuya virginidad ha sido vendida por el malvado Portugués Almeida. Este relato fue llevado al cine por Enrique Urbizu bajo el título de Cachito', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1801, '9788422694571', 'La sombra del águila', 1, '1993', 120, NULL, 'media/core/9788422694571.jpeg', 1, '2023-04-26 16:29:39.244988', '2023-04-26 16:29:39.244988', 73, 27, 6, 5, NULL, '', '06_04', NULL, 75, 'La sombra del águila narra una historia ficticia basada en un hecho real: durante la campaña de Rusia de 1812, en un combate adverso para las tropas napoleónicas, un batallón de antiguos prisioneros españoles, enrolados a la fuerza en el ejercito frances, intenta desertar, pasándose a los rusos. Interpretando erróneamente el movimiento, el Emperador lo toma por un acto de heroísmo y ordena en su auxilio una carga de caballería que tendrá imprevisibles consecuencias.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1802, '8435003213', 'La república de los sabios', 1, '1973', 183, 'Die Gelehrtenrepublik', 'media/core/8435003213.jpg', 1, '2023-04-26 16:33:01.608455', '2023-04-26 16:33:01.608455', 1050, 1, 6, 5, NULL, '', '06_04', NULL, 210, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1803, '8485316703', 'La sacerdotisa del mar', 1, '1982', 211, 'The Sea Priestess', 'media/core/8485316703.jpeg', 1, '2023-04-26 16:36:52.366523', '2023-04-26 16:36:52.366523', 1051, 1, 6, 5, NULL, '', '06_04', NULL, 372, 'La Sacerdotisa del Mar es la aclamada novela en la que Dion Fortune presenta a su personaje de ficción más poderoso, Vivien Le Fay Morgan, una iniciada en la Senda Hermética. Vivien tiene la habilidad de transformarse en imágenes mágicas, y aquí se convierte en Morgan Le Fay, ¡sacerdotisa del mar de la Atlántida e hija adoptiva de Merlín! Desesperadamente enamorado de Vivien, Wilfred Maxwell trabaja junto a ella en un retiro aislado junto al mar, investigando estos misterios ocultos. Pronto se ven inextricablemente atraídos por un antiguo culto a través del cual aprenden el significado esotérico del flujo y reflujo magnético de las mareas lunares.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1804, '8426414346', 'Don Quijote de la Mancha (adaptación JL Giménenz-Frontín)', 1, '2002', 211, NULL, 'media/core/8426414346.jpeg', 1, '2023-04-26 16:39:47.549919', '2023-04-26 16:39:47.549919', 680, 1, 6, 5, 'Grandes autores', '', '06_04', NULL, 21, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1805, '8423920232', 'La vida es sueño / El alcalde de Zalamea', 1, '1982', 219, NULL, 'media/core/8423920232.jpeg', 1, '2023-04-26 16:41:51.950759', '2023-04-26 16:41:51.950759', 768, 41, 6, 5, 'Selecciones Austral', '', '06_04', NULL, 18, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1807, '9788422686156', 'Iacobus', 1, '2000', 379, NULL, 'media/core/9788422686156.jpeg', 1, '2023-04-26 17:10:45.902118', '2023-04-26 17:12:56.855944', 181, 1, 6, 5, NULL, '', '07_01', NULL, 96, 'Galcerñan de Born es un caballero de la orden de los hospitalarios, enemigos de los templarios. Su gran capacidad para resolver enigmas llega a oídos del Papa Juan XXII quien decide encargarle una misión: descubrir a los culpalees de las muertes del Papa Clemente, del rey Felipe y de Guillermo de Nogaret. Con la ayuda de Jonás, su hijo, aunque éste aún no sabe lo que es y de Sara, la hechicera judía de pelo blanco, consiguen la prueba definitiva que implicaba a los templarios en estos asesinatos, como venganza por haber quemado en la hoguera al gran Maestre del Temple.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1808, '9788408053163', 'Peregrinatio', 1, '2004', 127, NULL, 'media/core/9788408053163.jpg', 1, '2023-04-26 17:15:49.585829', '2023-04-26 17:15:49.585829', 181, 28, 6, 5, NULL, '', '07_01', NULL, 7, 'Un homenaje al Camino de Santiago Año de 1324. El ex caballero hospitalario Galcerán de Born, el Perquisitore, preocupado ante las noticias que recibe acerca de la conducta inapropiada de su hijo, Jonás, y de su disoluta vida en la corte de Barcelona, decide enviarle una misiva que contiene órdenes muy precisas para el joven y se convertirá en su Liber peregrinationis. Acompañado por un caballero de Cristo (antiguos templarios), Jonás de Born iniciará una nueva andadura en su vida: prestará el solemne juramento de la caballería iniciática, convirtiéndose así en gentilhombre y adalid de la antigua Sabiduría y el Conocimiento. Para ello, recorrerá el Camino de Santiago o de la Gran Perdonanza, como un peregrino más, descubrirá toda la magia y el simbolismo que se encuentran en la ruta, reflexionará larga y seriamente sobre su futuro e irá cumpliendo, uno a uno, todos los rituales de su iniciación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1809, '9788425341977', 'Te daré la Tierra', 1, '2008', 738, NULL, 'media/core/9788425341977.jpg', 1, '2023-04-26 17:18:40.087202', '2023-04-26 17:18:40.087202', 1052, 16, 6, 5, NULL, '', '07_01', NULL, 45, 'Pasión, amistad, envidia, honor y venganza en la Barcelona del siglo XI.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1810, '8422637685', 'El Ocho', 1, '1991', 697, 'The Eight', 'media/core/8422637685.jpg', 1, '2023-04-26 17:21:37.299185', '2023-04-26 17:21:37.299185', 61, 22, 6, 5, NULL, '', '07_01', NULL, 107, 'Tras las míticas piezas de ajedrez de Montglane se oculta un secreto celosamente preservado durante siglos...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1811, '9788477224129', 'Arturo', 1, '1990', 618, 'Arthur (The Pendragon Cyle, book III)', 'media/core/9788477224129.jpg', 1, '2023-04-26 17:25:29.679709', '2023-04-26 17:25:29.679709', 1053, 13, 6, 5, NULL, '', '07_01', 'Ciclo Pendragón 3', 9, 'Los señores de Inglaterra intentan descubrir quién de entre todos ellos podrá convertirse en Supremo Monarca.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1812, '9788477224112', 'Merlín', 1, '1989', 602, 'Merlin (The Pendragon Cyle, book II)', 'media/core/9788477224112.jpg', 1, '2023-04-26 17:28:11.528135', '2023-04-26 17:28:11.528135', 1053, 13, 6, 5, NULL, '', '07_01', 'Ciclo Pendragón 2', 9, 'Merlín, igual que su padre el bardo Taliesin, tiene que llevar a cabo una gran misión. Mientras Taliesin imaginó en una canción el Reino de Verano, Merlín ha de hacerlo realidad. Detrás de ese propósito se esconde el glorioso objetivo de su vida: preparar la llegada de Pendragon, el gran monarca de Inglaterra y Señor del Reino de Verano y León de Logres. Merlín crece en sabiduría y honor, deja su huella en los corazones que lo conocen y cambia el curso de la Historia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1813, '9788477224105', 'Taliesin', 1, '1989', 633, 'Taliesin (The Pendragon Cyle, book I)', 'media/core/9788477224105.jpg', 1, '2023-04-26 17:30:45.518446', '2023-04-26 17:30:45.518446', 1053, 13, 6, 5, NULL, '', '07_01', 'Ciclo Pendragón 1', 9, 'El príncipe Taliesin reunía toda la grandeza humana, nobleza y bondad, mansedumbre majestad y sinceridad, cautivaba a los más encumbrados personajes con sus poemas y canciones. Ésta es una historia que abarca dos mundos, un sueño que canta en el corazón, un amor que engendra el milagro de Merlín... de Arturo... y un destino que es más que un reino.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1814, '9788467261844', 'Tres novelas de Nestor Burma', 1, '2008', 496, NULL, 'media/core/9788467261844.jpeg', 1, '2023-04-26 17:39:55.220416', '2023-04-26 17:39:55.220416', 1054, 14, 6, 5, NULL, '', '07_01', NULL, 373, '', '- Calle de la Estación, 120INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1815, '9788420473062', 'Amanecer', 5, '2009', 826, 'Breaking Dawn', 'media/core/9788420473062.jpg', 1, '2023-04-26 17:43:44.853528', '2023-04-26 17:43:44.853528', 1055, 48, 6, 5, NULL, '', '07_01', 'Crepúsculo 4', 10, '""No tengas miedo", le susurre. "Somos como una sola persona". De pronto me abrumó la realidad de mis palabras. Ese momento era tan perfecto. Me rodeó con los brazos, me estrechó contra el y hasta la última de mis terminaciones nerviosas cobró vida propia. "Para siempre", concluyó el."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1816, '9788422662969', 'El descubrimiento del cielo', 1, '1996', 827, 'De Ontdekking van de Hemel', 'media/core/9788422662969.jpeg', 1, '2023-04-26 17:47:52.104564', '2023-04-26 17:47:52.104564', 1056, 1, 6, 5, NULL, '', '07_01', NULL, 114, 'La Haya, 1967á: estas son las coordenadas del encuentro de Max y Onno, dos seres verdaderamente excepcionales de cuya confluencia surge la paternidad físico-espiritual de Quinten. Engendrado en el cuerpo de la violoncelista Ada y criado por Sophia, su enigmática abuela, Quinten goza de una educación privilegiada en la que ningún elemento ha sido escogido al azará: la magia de la astronomía, la arquitectura renacentista, la cábala, la filosofía, el arte… y, por supuesto, la trágica memoria histórica del siglo XX. Pero todo resulta poco para quien, como Quinten, ha recibido la misión sagrada de partir en busca del perdido sacro testimonio y devolverselo ni más ni menos que a Dios. He aquí, por tanto, una novela incontestablemente faústica, repleta de sabiduría y de sorpresas, capaz de implicar al lector en una irónica y a la vez doliente epopeya, escrita por uno de los grandes novelistas y pensadores contemporáneos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1817, '9788420469287', 'Crepúsculo', 15, '2008', 504, 'Twilight', 'media/core/9788420469287.jpg', 1, '2023-04-26 17:50:18.176361', '2023-04-26 17:50:18.176361', 1055, 48, 6, 5, NULL, '', '07_01', 'Crepúsculo 1', 10, '«Hay tres cosas de las que estoy completamente segura. Primera, Edward es un vampiro. Segunda, una parte de él se muere por beber mi sangre. Y tercera, estoy total y perdidamente enamorada de él.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1818, '9788420472324', 'Eclipse', 1, '2008', 623, 'Eclipse', 'media/core/9788420472324.jpg', 1, '2023-04-26 17:53:12.641489', '2023-04-26 17:53:12.641489', 1055, 48, 6, 5, NULL, '', '07_01', 'Crepúsculo 3', 10, 'Después de Crepúsculo y Luna Nueva llega por fin Eclipse, la tercera parte de la saga de Stephenie MeyerINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1819, '9788420472362', 'Luna nueva', 1, '2008', 572, 'New moon', 'media/core/9788420472362.jpg', 1, '2023-04-26 17:55:51.303110', '2023-04-26 17:55:51.303110', 1055, 48, 6, 5, NULL, '', '07_01', 'Crepúsculo 2', 10, '"Cuando el papel me cortó el dedo, solo salió una gota de sangre del pequeño rasguño. Entonces, todo pasó muy rápido. "¡No!", rugió Edward. Aturdida y desorientada, mire a los ojos enfurecidos de seis vampiros repentinamente hambrientos."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1820, '8422641372', 'La sobrina del alfarero', 1, '1992', 475, 'The Potter''s Niece', 'media/core/8422641372.jpeg', 1, '2023-04-26 18:01:51.523268', '2023-04-26 18:01:51.523268', 564, 1, 6, 5, NULL, '', '07_01', NULL, 5, 'Con éste continúa la apasionante saga familiar iniciada con El legado de los Drayton.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1821, '9788467219616', 'Jonathan Strange y el señor Norrell', 1, '2005', 807, 'Jonathan Strange & Mr. Norrell', 'media/core/9788467219616.jpeg', 1, '2023-04-26 18:06:02.708964', '2023-04-26 18:06:02.708964', 1058, 1, 6, 5, NULL, '', '07_01', NULL, 189, 'Una de las novelas más brillantes y originales que han aparecido en el panorama anglosajón en los últimos tiempos. Como una auténtica obra de orfebrería literaria, Susana Clarke ha imaginado un universo fantástico completo y coherente hasta en sus últimos detalles, creando en el lector la ilusión de sumergirse en una historia de absoluto realismo y verosimilitud.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1822, '9788429790641', 'La sangre de Dios', 1, '2001', 218, 'The Blood of God', 'media/core/9788429790641.jpeg', 1, '2023-04-26 18:09:03.589559', '2023-04-26 18:09:03.589559', 550, 22, 6, 5, NULL, '', '07_01', 'Trilogía Templaria III', 5, 'Simón Draco,detective privado, descubre una compleja trama en torno a la reliquia de la sangre de Cristo,a partir de la cual un laboratorio de ingenieria genética se propone devolverle la vida.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1823, '9788429787702', 'Las trompetas de Jericó', 1, '2000', 252, 'The Trumpets of Jerico', 'media/core/9788429787702.jpeg', 1, '2023-04-26 18:11:46.207553', '2023-04-26 18:11:46.207553', 550, 22, 6, 5, NULL, '', '07_01', 'Trilogía Templaria II', 5, 'Año 1943. Los nazis están perdiendo la segunda guerra mundial. Un arqueólogo alemán encuentra en Venecia la pista del Arca de la Alianza que los templarios ocultaron en un cementerio de Túnez en 1308. En la antigüedad, el Arca de la Alianza se reveló como una formidable arma de guerra que otorgó a los judíos la posesión de la Tierra Prometida. La noticia del hallazgo conmociona a Hitler y a los jerarcas nazis, que ven una posibilidad de inclinar la balanza de la guerra a su favor. Así nace la operación Trompetas de Jericó, en memoria de la ciudad destruida por el conjuro del Arca. Himmler comprende que sólo un cabalista puede tener el conocimiento necesario para hacer funcionar el Arca y encarga a Otto Von Kessler, un héroe de guerra nazi al que las multinacionales han retirado del frente, que lo encuentre. Von Kessler localiza a un famoso cabalista judío en el campo de concentración de Auschwitz y le ofrece la vida de su familia a cambio de que ponga el poder del Arca al servicio de Alemania. El judío acepta. Integrado en una comisión alemana recorre la España deprimida de los años de hambre para recuperar el nombre secreto de Dios necesario para sus operaciones cabalísticas. Mientras tanto Churchill y la Casa Blanca, conocedores del proyecto alemán, encargan desbaratarlo a sus respectivos servicios secretos. También intervienen los que se consideran los legítimos herederos del Arca: el Vaticano y los propios templarios que salen a la luz después de siglos de silencio para reivindicar su patrimonio más sagrado. Pero la fuerza del Arca, nuevamente despierta después de milenios, parece determinar su propio destino al margen de los designios de los hombres.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1824, '9788422673880', 'El pompeyano', 1, '1998', 373, 'Der Pompejaner', 'media/core/9788422673880.jpeg', 1, '2023-04-26 18:15:30.018066', '2023-04-26 18:15:30.018066', 276, 16, 6, 5, NULL, '', '07_01', NULL, 253, 'En el siglo I d.C., el esclavo Lucio Cecilio Afrodisio, de la ciudad de Pompeya, en la Campania, accede a la condición de liberto, y con ello cobra carta de ciudadanía. Diversos negocios fructíferos le permiten prosperar y encumbrarse a los estadios más elevados del escalafón social. Ya en su condición de rico, se vera enredado en una misteriosa trama de asesinatos; en el curso de las pesquisas que emprende para descifrar el enigma, halla, en un baúl que contiene los arcanos de la ciudad, una profecía antiquísima: en el octavo mes del año 832 después de la fundación de Roma, Pompeya desaparecerá.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1825, '9788423341610', 'Millennium 3', 1, '2009', 854, 'Lufstlottet som sprängdes', 'media/core/9788423341610.jpg', 1, '2023-04-27 06:07:57.476908', '2023-04-27 06:07:57.476908', 1060, 14, 6, 5, 'Colección Áncora y Delfín', '', '07_01', 'La reina en el palacio de las corrientes de aire', 59, 'Los lectores que llegaron con el corazón en un puño al final de La chica que soñaba con una cerilla y un bidón de gasolina quizás prefi eran no seguir leyendo estas líneas y descubrir por sí mismos cómo sigue la serie y, sobre todo, qué le sucede a Lisbeth Salander.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1826, '9788423341009', 'La chica que soñaba con una cerilla y un bidón de gasolina', 1, '2009', 749, 'Flickan som lekte med elden', 'media/core/9788423341009.jpg', 1, '2023-04-27 06:11:06.612162', '2023-04-27 06:11:06.612162', 1060, 14, 6, 5, 'Colección Áncora y Delfín', '', '07_01', 'Millennium 2', 59, 'Lisbeth Salander se ha tomado un tiempo: necesita apartarse del foco de atención y salir de Estocolmo. Trata de seguir una férrea disciplina y no contestar a las llamadas ni a los mensajes de Mikael, que no entiende por qué ha desaparecido de su vida sin dar ningún tipo de explicación. Lisbeth se cura las heridas de amor en soledad, aunque intente distraer el desencanto mediante el estudio de las matemáticas y con ciertos placeres en una playa del Caribe.¿Y Mikael? El gran héroe vive buenos momentos en Millennium, con las finanzas de la revista saneadas y el reconocimiento profesional por parte de los colegas. Ahora tiene entre manos un reportaje apasionante sobre el tráfico y la prostitución de mujeres procedentes del Este que le ha propuesto Dag Svensson, periodista de investigación, y su mujer, la criminóloga e investigadora de género Mia Bergman.Las vidas de los dos protagonistas parecen haberse separado por completo, pero entretanto... una muchacha, atada a una cama, soporta un día tras otro las horribles visitas de un ser despreciable y, sin decir palabra, sueña con una cerilla y un bidón de gasolina, con la forma de provocar el fuego que acabe con todo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1828, '9788467230765', 'Los hombres que no amaban a las mujeres', 1, '2005', 666, 'Män som hatar kvinnor', 'media/core/9788467230765.GIF', 1, '2023-04-27 06:15:50.805410', '2023-04-27 06:15:50.805410', 1060, 14, 6, 5, NULL, '', '07_01', 'Millennium 1', 58, 'Harriet Vanger desapareció hace treinta y seis años en una isla sueca propiedad de su poderosa familia. A pesar del despliegue policial, no se encontró ni rastro de la muchacha. ¿Se escapó? ¿Fue secuestrada? ¿Asesinada? El caso está cerrado y los detalles olvidados. Pero su tío Henrik Vanger, un empresario retirado, vive obsesionado con resolver el misterio antes de morir. En las paredes de su estudio cuelgan cuarenta y tres flores secas y enmarcadas. Las primeras siete fueron regalos de su sobrina; las otras llegaron puntualmente para su cumpleaños, de forma anónima, desde que Harriet desapareció. Mikael Blomkvist acepta el extraño encargo de Vanger de retomar la búsqueda de su sobrina. Periodista de investigación y alma de la revistaMillennium, dedicada a sacar a la luz los trapos sucios de la política y las finanzas, Blomkvist está vigilado y encausado por una querella por difamación y calumnia presentada por un gran grupo industrial que amenaza con arruinar su carrera y su reputación. Contará con la colaboración inesperada de Lisbeth Salander, una peculiar investigadora privada, socialmente inadaptada, tatuada y llena de piercings, y con extraordinarias e insólitas cualidades.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1829, '9788467251197', 'Los peces no cierran los ojos', 1, '2012', 113, 'I pesci non chiudono gli occhi', 'media/core/9788467251197.jpeg', 1, '2023-04-27 06:20:32.315828', '2023-04-27 06:20:32.315828', 1061, 1, 6, 5, NULL, '', '07_01', NULL, 14, '«Nacer y crecer en Nápoles agota el destino: vaya uno donde vaya, ya lo ha recibido como dote, mitad lastre, mitad salvoconducto.» Un hombre recuerda el verano de sus diez años en un pueblo costero cerca de Nápoles, los años en que se anhela un futuro desde el que sólo se puede mirar atrás. Entre la pesca y los libros, los paseos en solitario y los encuentros con los muchachos del barrio, transcurren sus días, hasta que conoce a una niña sin nombre que le descubre el peso de palabras como amor o justicia.    INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1830, '9788416995332', 'Clase antes que nación. Trabajadores, movimiento obrero y cuestión nacional en la Barcelona metropo', 1, '2017', 429, NULL, 'media/core/9788416995332.jpg', 2, '2023-04-27 06:27:30.588182', '2023-04-27 06:27:30.588182', 1062, 11, 6, 5, NULL, '', '07_01', NULL, 341, 'Los diversos capítulos que integran esta obra destapan la aparente paradoja de que la asunción por parte de los trabajadores de perspectivas nacionales fue paralela al declive de la catalanidad en el seno de la propia clase obrera. A medida que la composición geográfica de la clase trabaja dora se diversificó, incrementó sus vínculos con el catalanismo, pasando del desinterés casi atávico de la CNT hasta la Guerra Civil, a la militancia bañada en claros elementos nacionalizadores del PSUC de mediados de los sesenta. En cualquier caso, ese tardío catalanismo asumido por el movimiento obrero nunca fue más allá de una propuesta federalista de base plurinacional–alejada ya del modelo federal libertario–que pudiera satisfacer las demandas de especificidad nacional catalana dentro de la solidaridad con el resto de pueblos del Estado. Hablar de independencia–o de separación, como habitualmente la denominaban–es, al menos hasta 2008, un anacronismo. Y a pesar de esta última afirmación, la zona de Cataluña obrera por excelencia, el área metropolitana, continúa siendo hoy el mayor agujero para el independentismo. Ni a lo largo del siglo XIX ni durante el XX los trabajadores de esta zona situaron la cuestión nacional o territorial por delante de los intereses de clase, y todo ello en un contexto de cambios en la composició...', 'Con Juanjo RomeroINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1831, '9788491819820', 'El marino que perdió la gracia del mar', 5, '2020', 209, 'Gogo no Eiko', 'media/core/9788491819820.jpg', 1, '2023-04-27 06:31:10.994413', '2023-04-27 06:31:10.994413', 1063, 1, 6, 5, NULL, '', '07_01', NULL, 69, 'Noboru es un adolescente de trece años huérfano que vive con su madre viuda, encargada de una importante tienda de modas, en Yokohama. Él y sus amigos son buenos estudiantes, pero eso no impide que formen una inquietante pandilla con particulares ideas acerca de la existencia y el honor, de la vida y la muerte. Noboru asiste a la relación que su madre entabla con Ryuji, un marino al que envuelve en cierta aura heroica y al cual ensalza frente a sus amigos. Sin embargo, poco a poco pero inexorablemente, Ryuji irá cayendo en desgracia con el chico y con el clan de adolescentes, que sólo hallarán una forma drástica de redimirlo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1832, '9788467264166', 'Almas muertas', 1, '2015', 359, 'Miórtvyie dushi', 'media/core/sin-imagen_Y1M1Cmj.jpg', 1, '2023-04-27 06:37:08.089527', '2023-04-27 06:37:08.089527', 552, 1, 6, 5, NULL, '', '07_01', NULL, 5, 'Creador junto con Aleksandr Pushkin de la gran prosa rusa del siglo XIX que habría de prolongarse en Dostoyevski, Tolstói y Chéjov, Nikolái Gógol plasmó en «Almas muertas» la misma visión ácida y satírica de Rusia que impregna sus Historias de San Petersburgo, entre las que se cuentan relatos tan célebres como «La nariz» y «El abrigo». La publicación en 1842 de la presente novela, que alcanzó notable repercusión y levantó algún revuelo, le valió gran fama y consolidó su reputación de gran narrador. Su protagonista, Chíchikov, pergeña el plan de comprar "almas muertas" -esto es, la propiedad de siervos fallecidos- para así poder pedir un crédito al Estado, con esta propiedad como aval, antes del siguiente censo. El relato de sus andanzas por la Rusia rural, así como de su resultado, es una de las cimas de la literatura de este país, en la que se puede apreciar el talento de Gógol no sólo para la sátira, sino también para la descripción de inolvidables caracteres.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1833, '9788422662815', 'El ídolo perdido', 1, '1996', 459, 'Relic', 'media/core/9788422662815.jpg', 1, '2023-04-27 06:40:24.953741', '2023-04-27 06:40:24.953741', 1080, 22, 6, 5, NULL, '', '07_01', NULL, 96, 'THE RELIC (EL IDOLO PERDIDO) (INSPECTOR PENDERGAST 1)INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1834, '8422641321', 'Madre Tierra, Padre Cielo', 1, '1992', 349, 'Mother Earth Father Sky', 'media/core/8422641321.jpeg', 1, '2023-04-27 06:49:48.177758', '2023-04-27 06:49:48.177758', 93, 1, 6, 5, NULL, '', '07_01', NULL, 5, 'La joven Chagak escapa milagrosamente a la matanza de su pueblo y se refugia en una isla remota, donde recibe la protección de un anciano que la ayuda a rehacerse. Sin embargo, un malvado cazador de focas irrumpirá en la isla, provocando un dramático cambio en su vida...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1835, '9788422685111', 'La importancia de llamarse Ernesto y otras comedias', 1, '2000', 338, NULL, 'media/core/9788422685111.jpeg', 1, '2023-04-27 06:53:36.447543', '2023-04-27 06:53:36.447543', 498, 41, 6, 5, NULL, '', '07_01', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1836, '9788422658207', 'Las historias naturales', 1, '1995', 242, NULL, 'media/core/9788422658207.jpg', 1, '2023-04-27 06:56:47.713870', '2023-04-27 06:56:47.713870', 1029, 1, 6, 5, NULL, '', '07_01', NULL, 5, 'Entre la novela histórica (con las guerras carlistas de fondo), y la novela fantástica, Las historias naturales debe su importancia en la historia de la literatura sobre todo a su innegable calidad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1837, '9788467245134', 'Para leer al anochecer. Historias de fantasmas', 1, '2009', 235, 'To be Read at Dusk', 'media/core/9788467245134.jpg', 1, '2023-04-27 07:00:41.684931', '2023-04-27 07:00:41.684931', 366, 21, 6, 5, NULL, '', '07_01', NULL, 374, 'Charles Dickens estuvo interesado durante toda su vida por los fenómenos misteriosos. Su natural inclinación hacia el drama y lo macabro hicieron de él un extraordinario escritor de cuentos de fantasmas. Para leer al anochecer presenta trece de las más célebres y espeluznantes historias de fantasmas escritas por Dickens —«El fantasma en la habitación de la desposada», «El juicio por asesinato», «El guardavías», «Fantasmas de Navidad», «El Capitán Asesino y el pacto con el Diablo», «La visita del señor Testador» o «La casa encantada», entre otras—, en una nueva traducción al castellano. Villanos que mueren ahorcados, mujeres misteriosas que encargan retratos desde el más allá, marinos desaparecidos que hacen visitas inesperadas a los vivos, viajeros victorianos que se encuentran con siniestros niños en oscuros caserones… Puro talento gótico.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1838, '9788467261943', 'Primera memoria', 1, '2012', 210, NULL, 'media/core/9788467261943.jpeg', 1, '2023-04-27 07:02:51.918255', '2023-04-27 07:02:51.918255', 141, 1, 6, 5, NULL, '', '07_01', NULL, 15, 'Con la guerra civil, «lejana y próxima a un tiempo, quizás más temida por invisible», como telón de fondo, Primera memoria, Premio Nadal 1959, narra el paso de la niñez a la adolescencia de Matia la protagonista y de su primo Borja.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1839, '9788467261936', 'Demonios familiares', 1, '2014', 174, NULL, 'media/core/9788467261936.jpg', 1, '2023-04-27 07:05:11.798609', '2023-04-27 07:05:11.798609', 141, 1, 6, 5, NULL, '', '07_01', NULL, 15, 'El último regalo de una autora inolvidable.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1840, '9788432044731', 'El cumpleaños del Arca', 1, '1991', 196, 'The Ark''s anniversary', 'media/core/9788432044731.jpeg', 1, '2023-04-27 07:10:33.718073', '2023-04-27 07:10:33.718073', 1066, 32, 6, 5, 'Documento', '', '07_01', NULL, 7, 'Cuando Gerald Durrell tenía seis años comunicó a su madre que se proponía llegar a tener su propio zoo. Esta es la historia de cómo esta ambición infantil llegó a convertirse en realidad, de cómo su sueño se materializó con el tiempo en The Jersey Wildlife Preservation Trust, una de las instituciones más importantes del mundo en la conservación y defensa de la vida animal.<br /> El autor, ya sea persiguiendo a un director de banco o a un cerdo enano, buscando mecenas o tras la pista de una salmanquesa Gunther, no pierde nada de su entusiasmo, y, como un nuevo Noé, reúne una prodigiosa colección de animales raros y exóticos para salvarlos de la extinción.<br /> A un tiempo extraordinariamente divertido y profundamente serio en lo que se refiere a la función de un zoo a fines del siglo XX, este entrañable libro de aventuras, con animales dentro y fuera de su zoo, apasionará a los innumerables lectores de Durrell y le hará tener muchos más.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1841, '9788422658092', 'Congo', 1, '1993', 361, 'Congo', 'media/core/9788422658092.jpeg', 1, '2023-04-27 07:12:58.573228', '2023-04-27 07:12:58.573228', 130, 13, 6, 5, NULL, '', '07_01', NULL, 96, 'En el corazón del África salvaje se desarrolla una apasionante aventura en pos de encontrar la ciudad perdida de Zinj, punto clave de una terrible intriga internacional. Sus protagonistas: una chica ambiciosa al servicio de una poderosa multinacional; un joven científico californiano; Amy, un gorila entrañable; y un experto cazador que conoce los misterios de la selva. Todos ellos se enfrentan a peligros mortales: pigmeos siniestros, bestias monstruosas, ríos de lava, espías de naciones enemigas, mercenarios implacables...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1842, '9788476727126', 'La isla de los pingüinos', 1, '1994', 251, 'L''île des pingouins', 'media/core/9788476727126.jpg', 1, '2023-04-27 07:16:24.833852', '2023-04-27 07:16:24.833852', 633, 1, 6, 5, 'Grandes autores Literatura Universal', '', '07_01', NULL, 205, 'En esta parodia de la historia de la civilización, Anatole France ha elegido como protagonista a un animal gracioso y endomingado que recuerda a la caricatura de los burgueses de finales del XIX y principios del XX: los pingüinos. La isla de los pingüinos arranca con un episodio hilarante: el bautizo por error, a cargo de san Maël, de los pingüinos del ártico. A partir de ahí, Anatole France describe en forma novelada los rasgos más notables de la historia de la humanidad, mezclando el amor y la guerra, el poder absoluto y la revolución, la religión y la especulación financiera, incluso insinuando la guerra nuclear y denunciando los rasgos característicos del actual proceso de globalización, que a lo que se ve, no son nada nuevos. Es difícil a veces contener la risa al leer este texto heredero de Rabelais y Swift y que se anticipa a Orwell.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1843, '8408461087', 'La oscura historia de la prima Montse', 1, '1996', 303, NULL, 'media/core/8408461087.jpg', 1, '2023-04-27 07:20:33.331441', '2023-04-27 07:20:33.331441', 216, 1, 6, 5, 'Nuestros clásicos contemporáneos', '', '07_01', NULL, 7, 'La novela arranca con la visita de un hombre, diez años después, al lugar donde se fraguó su tragedia. Condenada al derribo, nada queda del antiguo esplendor de la torre de sus tíos, la adinerada, católica y encopetada familia de los Claramunt.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1844, '9788416237227', 'Años de sequía', 1, '2017', 364, 'The Dry', 'media/core/9788416237227.jpg', 1, '2023-04-27 07:23:27.888425', '2023-04-27 07:23:27.888425', 1067, 1, 6, 5, 'Black Salamandra', '', '07_01', NULL, 11, 'Volver a Kiewarra, pequeña comunidad al sureste de Australia, es lo último que el investigador de delitos financieros Aaron Falk desea. Y no sólo por el sol abrasador y la sequía pertinaz que han dejado al ganado famélico, a los granjeros desesperados y a la población desquiciada, sino también por el temor a que su presencia reavive las heridas que su precipitada partida dejó abiertas veinte años atrás. Sin embargo, cuando le comunican que Luke Hadler, su amigo de la infancia, y su familia han muerto de forma violenta, presuntamente en un acto de parricidio y posterior suicidio, se siente obligado a regresar.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1845, '9788423359660', 'Lo que la marea esconde', 1, '2021', 414, NULL, 'media/core/9788423359660.jpg', 1, '2023-04-27 07:26:05.393455', '2023-04-27 07:26:05.393455', 1068, 1, 6, 5, 'Colección Áncora y Delfín', '', '07_01', NULL, 7, 'La presidenta del Club de la Bahía de Santander, una de las mujeres más poderosas de la ciudad, ha aparecido muerta en el camarote de una preciosa goleta que con unos pocos y selectos invitados del mundo del tenis surcaba el mar al anochecer.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1846, '8422621355', 'El Mediterráneo y los bárbaros del Norte', 1, '1985', 221, NULL, 'media/core/8422621355.jpg', 1, '2023-04-27 07:29:49.059898', '2023-04-27 07:29:49.059898', 1069, 2, 6, 5, NULL, '', '07_01', NULL, 5, 'La confrontación de dos mentalidades que deben ser complementarios. Dos Europas buscan trabajosamente hace siglos una unidad cultural que todavía no se ha conseguido.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1847, '9788481098785', 'Manuel Azaña. José Ortega y Gasset. Dos visiones de España', 1, '2005', 141, NULL, 'media/core/9788481098785.jpeg', 1, '2023-04-27 08:16:21.418791', '2023-04-27 08:16:21.418791', 1070, 32, 6, 5, NULL, '', '07_01', NULL, 46, 'Prefacio de José María Ridao. ¿El destino histórico de un «pueblo infusible» o un tema de negociación y debate? La discusión sobre el Estatuto de Autonomía de Cataluña enfrentó en 1932 a dos figuras irrepetibles en la política española. Un combate dialéctico plagado de ingenio, metáforas y alusiones que, setenta años después, resulta tremendamente revelador de dos formas de entender España que siguen muy presentes en la política actual. «Nadie tiene derecho a decir que su solución es la mejor porque es la más patriótica; se necesita que, además de patriótica, sea acertada.» Manuel Azaña. «El problema catalán no se puede resolver, sólo se puede conllevar.» José Ortega y Gasset.', 'Ridao es el editor');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1848, '8422628333', 'Capitalimo y morfología urbana en España', 1, '1990', 151, NULL, 'media/core/8422628333.jpeg', 1, '2023-04-27 08:20:09.903379', '2023-04-27 08:20:09.903379', 1071, 2, 6, 5, 'Círculo Universidad', '', '07_01', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1849, '8422628260', 'Historia de las ideas políticas I', 1, '1988', 484, 'Histoire des idées politiques', 'media/core/8422628260.jpeg', 1, '2023-04-27 08:24:10.467371', '2023-04-27 08:24:10.467371', 1072, 11, 6, 5, 'Círculo Universidad', '', '07_01', NULL, 375, 'La distinción entre «doctrinas políticas» e «ideas políticas» es, para todos los colaboradores de este libro, fundamental. Según el Littré, la doctrina es «el conjunto de dogmas, bien religiosos, bien filosóficos, que dirigen a un hombre en la interpretación de los hechos y en la dirección de su conducta». Según ello, la doctrina es, por consiguiente, un sistema completo de pensamiento que descansa sobre un análisis teórico del hecho político. En este sentido, se habla de la doctrina de Aristóteles, de Cardin Le Bret o de Montesquieu, de los «doctrinarios» de la Restauración o de la «doctrina radical» cuyos elementos Alain trató de conjuntar. La expresión «ideas políticas» es más amplia. Aquí no se trata solamente de analizar los sistemas políticos elaborados por algunos pensadores, sino de volver a instalar estos sistemas dentro de un contexto histórico, de esforzarse por ver cómo nacieron y qué representaban para los hombres que vivían en esa época. Esta Historia de las ideas políticas, cuya primera edición en Editorial Tecnos se remonta a 1961, con numerosas reediciones y reimpresiones, es fácilmente considerada una obra clásica del pensamiento contemporáneo, de constante referencia en los estudios políticos de todos los países occidentales.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1850, '8422628279', 'Historia de las ideas políticas II', 1, '1990', 563, 'Histoire des idées politiques', 'media/core/8422628279.jpeg', 1, '2023-04-27 08:26:21.382364', '2023-04-27 08:26:21.382364', 1072, 11, 6, 5, 'Círculo Universidad', '', '07_01', NULL, 375, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1851, '9788481098891', 'Noviembre de una capital', 1, '1991', 229, 'Novembre d''une capitale', 'media/core/9788481098891.jpeg', 1, '2023-04-27 08:32:15.896534', '2023-04-27 08:32:15.896534', 1073, 1, 6, 5, NULL, '', '07_01', NULL, 46, 'En noviembre de 1944, los guerrilleros comunistas albaneses lanzan el asalto final para libertar Tirana de las tropas nazis. El grupo de Sherif Goren y Javer Kurti tiene la misión de tomar la estación de radio del bulevar Mussolini, el lugar desde el que se han estado lanzando las consignas propagandísticas de los invasores durante la guerra. Todo un símbolo de la ocupación y la represión, y de lo que deberá cambiar en la nueva Albania, aunque pocos de los partisanos que se enfrentan a las casamatas de hormigón y las torretas de los blindados llegarán a verla. Mientras, en el otro extremo de la ciudad, en una escena de caos y confusión, una riada humana formada por colaboracionistas, burguesses y otras personas que no tienen ningún interés en conocer la nueva Albania intenta huir de la ciudad en llamas. Aunque no se trate de una obra política, sino del relato de la lucha de sangre y  fuego de unos hombres por unos ideales que acabaron traicionándolos sin piedad, esta novela coral publicada originalmente en 1975 cobra especial significada leída a principios del siglo XXI, sabido el resultado de la utopía comunista y sus escalofriantes semejanzas con los totalitarismos a los que se enfrentó.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1852, '9788432207822', 'Sin noticias de Gurb', 1, '2004', 143, NULL, 'media/core/9788432207822.jpg', 1, '2023-04-27 08:34:42.596990', '2023-04-27 08:34:42.596990', 96, 1, 6, 5, 'Biblioteca Eduardo Mendoza', '', '07_01', NULL, 13, 'Perdido en la Barcelona preolímpica, el extraterrestre Gurb pone al servicio de su supervivencia la extraña cualidad de adoptar el aspecto que le plazca. Se pierde con la apariencia de Marta Sánchez, mientras su compañero alienígena inicia la búsqueda en la jungla urbana. Por su diario personal vamos conociendo las increíbles peripecias de un extraterrestre en Barcelona. En este relato de carácter paródico y satírico la invención de Eduardo Mendoza convierte la Barcelona cotidiana y absurda en el escenario de una carnavalada. Tras las máscaras pintarrajedas y grotescas se revela el verdadero rostro del hombre urbano actual y, tras el estilo literario, la acerada conciencia artística del escritor.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1853, '9788483101612', 'Soldados de Salamina', 1, '2003', 209, NULL, 'media/core/9788483101612.jpg', 1, '2023-04-27 08:36:40.334846', '2023-04-27 08:36:40.334846', 245, 17, 2, 5, 'Colección Andanzas', '', '07_01', NULL, 12, 'Cuando en los meses finales de la guerra civil española las tropas republicanas se retiran hacia la frontera francesa, camino del exilio, alguien toma la decisión de fusilar a un grupo de presos franquistas. Entre ellos se halla Rafael Sánchez Mazas, fundador e ideólogo de Falange, quizá uno de los responsables directos del conflicto fratricida. Sánchez Mazas no sólo logra escapar de ese fusilamiento colectivo, sino que, cuando salen en su busca, un miliciano anónimo le encañona y en el último momento le perdona la vida. Su buena estrella le permitirá vivir emboscado, protegido por un grupo de campesinos de la región, aunque siempre recordará a aquel miliciano de extraña mirada que no lo delató. El narrador de esta aventura de guerra es un joven periodista que se propone reconstruir el relato real de los hechos y desentrañar el secreto de sus enigmáticos protagonistas. Un quiebro inesperado, sin embargo, le llevará a descubrir que el significado de esta historia se encuentra donde menos podía esperarlo: porque uno no encuentra lo que busca, sino lo que la realidad le entrega.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1854, '9788489164161', 'El baile de las Sirenas y otros relatos extraños', 1, '1999', 171, NULL, 'media/core/sin-imagen_fLYNYtZ.jpg', 1, '2023-04-27 08:39:22.244738', '2023-04-27 08:39:22.244738', 1074, 44, 6, 5, NULL, '', '07_01', NULL, 63, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1855, '8422620219', 'Réquiem por un campesino español / Imán', 1, '1985', 336, NULL, 'media/core/8422620219.jpeg', 1, '2023-04-27 08:43:56.064186', '2023-04-27 08:43:56.064186', 1075, 1, 6, 5, NULL, '', '07_01', NULL, 58, 'Réquiem por un campesino español recoge un dramático episodio de la guerra civil en un pueblecito aragonés. Mosén Millán se dispone a ofrecer una misa en sufragio del alma de un joven a quien había querido como a un hijo. Mientras aguarda a los asistentes, el cura reconstruye los hechos: el fracaso de su mediación, con la que creyó poder salvar al joven, pero que sólo sirvió para entregarlo a sus ejecutores. El relato es de una perfecta sobriedad y de una sencillez no por ello menos profunda y estremecedora. La narración sobrecoge por su ajustado realismo, por la eficacia de sus símbolos y por el profundo conocimiento de los mecanismos de la conciencia, puesto de manifiesto a través de la evocación del sacerdote. Sin duda, Réquiem por un campesino español es una de las mejores obras de Ramón J. Sender y un libro definitivo sobre nuestra guerra civil, alejado de cualquier panfletarismo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1856, '9788422675709', 'La Ley de Murphy', 1, '1997', 271, 'The Complete Murphy''s Law', 'media/core/9788422675709.jpeg', 1, '2023-04-27 08:57:25.625424', '2023-04-27 08:57:25.625424', 1076, 36, 6, 5, NULL, '', '07_01', NULL, 376, 'La vida cotidiana está regida por una ley universal, que afirma que no se puede saber cuál es la profundidad de un charco hasta que no se ha metido el pie en él, o que nada es tan bonito de cerca como de lejos. Adentrarse en las páginas de este libro es un antídoto contra el mal humor, aunque leerlo no evita que la tostada se siga cayendo por el lado de la mantequilla.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1857, '842262415X', 'El genio', 1, '1987', 201, 'Das Genie', 'media/core/842262415X.jpeg', 1, '2023-04-27 09:00:25.064721', '2023-04-27 09:00:25.064721', 1077, 1, 6, 5, NULL, '', '07_01', NULL, 14, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1858, '9788493440107', 'Mujeres del Quijote', 1, '2005', 238, NULL, 'media/core/9788493440107.jpg', 1, '2023-04-27 09:07:57.362610', '2023-04-27 09:07:57.362610', 1078, 36, 6, 5, NULL, '', '07_01', NULL, 377, 'La genial novelista de La Niña de Luzmela o La Esfinge Maragata recrea aquí los personajes femeninos de la obra cervantina, encuadrados en su época, y como símbolos del eterno femenino. Maritornes, Dulcinea, Zoraida, Teresa Panza, el ama y la sobrina…, todas tienen su momento de gloria', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1859, '9788433971234', 'A sangre fría', 1, '2007', 434, 'In Cold Blood', 'media/core/9788433971234.jpg', 1, '2023-04-27 09:11:11.965787', '2023-04-27 09:11:11.965787', 822, 1, 6, 5, 'Biblioteca Truman Capote', '', '07_01', NULL, 6, 'El 15 de noviembre de 1959, en un pueblecito de Kansas, los cuatro miembros de la familia Clutter fueron salvajemente asesinados en su casa. Los crímenes eran, aparentemente, inmotivados, y no se encontraron claves que permitieran identificar a los asesinos. Cinco años después, Dick Hickcock y Perry Smith fueron ahorcados como culpables de las muertes. A partir de estos hechos, y tras realizar largas y minuciosas investigaciones con los protagonistas reales de la historia, Truman Capote dio un vuelco a su carrera de narrador y escribió "A sangre fría", la novela que le consagró definitivamente como uno de los grandes de la literatura norteamericana del siglo xx. Capote sigue paso a paso la vida del pequeño pueblecito, esboza retratos de los que serían víctimas de una muerte tan espantosa como insospechada, acompaña a la policía en las pesquisas que condujeron al descubrimiento y detención de Hickcock y Smith y, sobre todo, se concentra en los dos criminales psicópatas hasta construir dos personajes perfectamente perfilados, a los que el lector llegará a conocer íntimamente. "A sangre fría", que fue bautizada, pionera y provocativamente, por Capote como una «non fiction novel», es un libro estremecedor que, desde la fecha misma de su publicación, se convirtió en un clásico.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1860, '9788467258851', 'Adiós a las armas', 1, '2013', 356, 'A Farewell to Arms', 'media/core/9788467258851.jpeg', 1, '2023-04-27 09:14:27.591648', '2023-05-13 10:09:42.192334', 1079, 1, 6, 5, NULL, '', '07_01', NULL, 211, 'No amaba a Catherine Barkley, ni se le ocurría que pudiera amarla. Aquello era como el bridge, un juego donde te largas a hablar en vez de manejar las cartas. Eso pensaba el teniente americano Frederic Henry, conductor de ambulancias en el frente italiano durante la Primera Guerra Mundial, al poco de conocer a esta bella enfermera británica. Lo que parecía un juego se convirtió en pasión intensa, mientras la guerra lo arrasaba todo y los hombres desfilaban bajo la lluvia, agotados y hambrientos, sin pensar más que en huir de la muerte.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1861, '9788491817574', 'La primera vuelta al Mundo', 1, '2019', 291, 'il primo viaggio intorno al mondo', 'media/core/9788491817574.jpg', 1, '2023-04-27 09:18:27.333548', '2023-04-27 09:18:27.333548', 1080, 28, 6, 5, NULL, '', '07_01', NULL, 69, 'Cuando Gabriel García Márquez recibió en 1982 el Premio Nobel de Literatura abrió su discurso con un homenaje dedicado a Antonio Pigafetta y a su «libro breve y fascinante, en el cual ya se vislumbran los gérmenes de nuestras novelas de hoy». Este libro relata la expedición, financiada por la Corona de Castilla, de las cinco naves al mando del portugués Magallanes, que, el 10 de agosto de 1519, partía de Sevilla con el fin de buscar el camino más corto hasta las "islas de las Especias". Tres años más tarde, el 8 de septiembre de 1522, y al mando del vasco Juan Sebastián Elcano, arribaba al puerto de Sevilla la nave Victoria, con sólo dieciocho hombres, «los más flacos y destrozados que podía ser». Si bien hubo algún beneficio económico, por encima de todo se había dado por primera vez la vuelta al mundo y se iniciaba una nueva era en la comunicación hacia el oeste. Pigafetta, embarcado sólo por afán de fama, con voluntad de escribir un libro que contase «todas las cosas pasadas día a día durante nuestro viaje» (no pocas ni poco accidentadas), dio fin a su intento y legó a la posteridad la relación de este viaje extraordinario.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1862, '9788422698036', 'La aventura de los godos', 1, '2002', 194, NULL, 'media/core/9788422698036.jpeg', 1, '2023-04-27 09:21:30.363999', '2023-04-27 09:21:30.363999', 1081, 11, 6, 5, NULL, '', '07_01', NULL, 378, 'Hubo un tiempo en el que solo mencionar la terrible lista de los Reyes Godos provocaba el pánico de los enflaquecidos alumnos de la posguerra española. La aridez y la supuesta inutilidad de ese episodio creaban enormes cefaleas entre los niños de los años 40 y 50. Sin embargo, tras el turbio enunciado, se encontraba un mundo fascinante y misterioso lleno de aventuras emocionantes propias de cualquier película, donde la épica fuera el condimento esencial. Los godos fueron testigos de un periodo asombroso en la crónica mundial, vieron caer Imperios como el Romano, y levantarse otros como el Musulmán y, mientras tanto edificaban un Estado en el solar Hispano.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1863, '9788467235562', 'Gomorra', 1, '2007', 336, 'Gomorra', 'media/core/9788467235562.jpeg', 1, '2023-04-27 09:23:59.091762', '2023-04-27 09:23:59.091762', 1082, 17, 6, 5, NULL, '', '07_01', NULL, 211, 'Este increíble y fascinante relato real es un viaje al imperio empresarial y delictivo de la Camorra, que comienza y termina bajo el signo de las mercancías. Las mercancías «frescas», bajo las formas más variadas (videojuegos, relojes, ropa de marca) llegan al puerto de Nápoles, y para ser almacenadas y escondidas se sacan de los gigantescos contenedores e invaden antiguos palacetes, previamente vaciados por completo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1864, '8432205311', 'El Perfume', 8, '1986', 239, 'das perfum. Die geschichte eines Mörders', 'media/core/8432205311.jpeg', 1, '2023-04-27 09:28:34.251706', '2023-04-27 09:28:34.251706', 1083, 1, 2, 5, NULL, '', '07_01', NULL, 13, 'Jean-Baptiste Grenouille tiene su marca de nacimiento: no despide ningún olor. Al mismo tiempo posee un olfato prodigioso que le permite percibir todos los olores del mundo. Desde la miseria en que nace, el protagonista escala posiciones sociales convirtiéndose en un afamado perfumista. Crea perfumes capaces de hacerle pasar inadvertido o inspira simpatía, amor... Para obtener estas fórmulas debe asesinar a jóvenes muchachas vírgenes, obtener fluidos corporales y licuar sus olores íntimos. Su arte se convierte en una suprema e inquietante prestidigitación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1865, '9788477224914', 'El paladín de la noche', 1, '1989', 474, 'The Paladin of the Night', 'media/core/9788477224914.jpg', 1, '2023-04-27 09:48:43.438532', '2023-04-27 09:48:43.438532', 539, 13, 6, 5, NULL, '', '07_02', 'La rosa del profeta 2', 9, 'Khardan y Zohra, acompañados por Mathew, son conducidos al castillo de Zhakrin, plaza fuerte gobernada por la hechicera negra y por su esposo, el Señor de los Caballeros, servidores ambos del perverso dios de la noche y el mal. Mientras tanto, en la ciudad de Kich, el imán feisal intenta convertir a los nómadas capturados y encarcelados por las tropas del emir, para luego emprender una cruel guerra santa. El Paladín de la Noche es el segundo volumen de esta trilogía fantástica y épica de ambientación oriental.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1866, '9788477224921', 'El profeta de Akhran', 1, '1990', 461, 'The Prophet of Akhran', 'media/core/9788477224921.jpg', 1, '2023-04-27 09:51:58.821976', '2023-04-27 09:52:34.284205', 539, 13, 6, 5, NULL, '', '07_02', 'La rosa del profeta 3', 9, 'Khardan, Zohra, Mathew y Auda Ibn Jad hacen un viaje hasta el Tel, lugar de asentamiento de las tribus nómadas. Al llegar a los campamentos del desierto, Khardan logra reivindicarse ante su pueblo y es nombrado profeta de Akhran...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1867, '9788477224907', 'La voluntad del dios errante', 1, '1990', 539, 'The Will of the Wanderer', 'media/core/9788477224907.png', 1, '2023-04-27 09:55:50.649933', '2023-04-27 09:55:50.649933', 539, 13, 6, 5, NULL, '', '07_02', 'La rosa del profeta 1', 9, 'Cuando Akhran el Errante, el dios del desierto, decreta que dos clanes deben unirse a pesar de su ancestral rivalidad, la primera reacción es de rebeldía, aunque acaban doblegándose al mandato. Enemigos desde siempre, el impetuoso príncipe Khardan y la voluntariosa princesa Zohra tienen que contraer matrimonio para impedir que Quar, el dios de la Realidad, la Avaricia y la Misericordia, esclavice a sus pueblos. Pero ¿podrán Khardan y Zohra evitar traicionarse entre sí y mantener la frágil alianza hasta el tan deseado florecimiento del legendario cactus llamado Rosa del Profeta?', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1868, '9788477221043', 'La reina de la oscuridad', 1, '1985', 446, 'Dragons of Spring Dawing', 'media/core/9788477221043.jpg', 1, '2023-04-27 10:06:32.664099', '2023-04-27 10:06:32.664099', 539, 13, 6, 5, NULL, '', '07_02', 'Crónicas de la Dragonlance III', 9, 'Timun Mas publica las“Crónicas de la Dragonlance”, la trilogía que da inicio a una de sus colecciones de más éxito, en edición de bolsilloINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1869, '9788477224938', 'Apéndices', 1, '1990', 377, 'Dragonlance (The Complete Krynn Source Book)', 'media/core/9788477224938.jpeg', 1, '2023-04-27 10:09:25.621444', '2023-04-27 10:09:25.621444', 539, 13, 6, 5, NULL, '', '07_02', NULL, 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1870, '9788477229063', 'La magia de Krynn', 1, '1992', 351, 'The Magic of Krynn', 'media/core/9788477229063.jpeg', 1, '2023-04-27 10:11:59.838058', '2023-04-27 10:11:59.838058', 539, 13, 6, 5, NULL, '', '07_02', 'Cuentos de la Dragonlance I', 9, 'Timun Mas pone a la venta la serie completa de Cuentos de la Dragonlance en una económica edición de bolsillo durante el mes de marzo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1871, '9788477221869', 'La guerra de los enanos', 1, '1988', 528, 'War of the Twins', 'media/core/9788477221869.jpeg', 1, '2023-04-27 10:18:17.489720', '2023-04-27 10:21:19.094171', 539, 13, 6, 5, NULL, '', '07_02', 'Leyendas de la Dragonlance II', 9, '¿Dónde está el Poder? ¿Dónde su Umbral, su Portal? Cien años después del Cataclismo, Raistlin-Fistandantilus sigue incansable la trayectoria que se ha trazado para intentar convertirse en el ser más poderoso del universo. Sin embargo, el mago descubre que el acceso al Poder, que debía estar en la Torre de Palanthas, se ha esfumado de ese lugar. El sabio historiador Astinus le revela que, para hallarlo, ha de trasladarse a Zhaman, fortaleza situada en Thorbardin, patria de los Enanos de las Montañas y plaza donde murió Fistandantilus... ¿Qué destino espera a Raistlin, si es la reencarnación del perverso archimago? Los Enanos de las Montañas están enzarzados en una cruenta guerra con los Enanos de las Colinas, que ansían apoderarse del supuesto tesoro de aquéllos. Raistlin, Caramon, Crysania y un numeroso ejército de Caballeros de Solamnia, bárbaros y campesinos deciden apoyar a los Enanos de las Colinas para poder entrar en Thorbardin. No obstante, a través de Tas, Raistlin recibe un mensaje de su Reina de la Oscuridad: Ven a casa , frase que desconcierta, enloquece y obsesiona al mago. Una vez más las autoras siguen la línea iniciada en las Crónicas de la Dragonlance y mantenida en el volúmen I de la trilogía Leyendas de la Dragonlance , creando nuevos personajes y aventuras que capturan el interés del lector. Selección de novelas de la Saga de la Dragonlance', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1872, '9788477221852', 'El templo de Istar', 1, '1988', 504, 'Time of the Twins', 'media/core/9788477221852.JPG', 1, '2023-04-27 10:21:05.107682', '2023-04-27 10:21:05.107682', 539, 13, 2, 5, NULL, '', '07_02', 'Leyendas de la Dragonlance I', 9, 'La Guerra de la Lanza ha terminado, y la Oscuridad ha desaparecido. ¿O tal vez no? Porque hay quien ansía reinstaurarla en Krynn. Raistlin, el mago de los ojos como relojes de arena, quiere ser más poderoso que su Reina de la Oscuridad y propagar el Mal en el mundo. El hechicero goza de un desmesurado poder porque Fistandantilus, el archimago más perverso del orbe, se ha encarnado en él. Sólo dos personas pueden detener a Raistlin. Una es Crysania, una bella sacerdotisa, Hija venerable de Paladine, que no tiene en cuenta la flaqueza de sus sentimientos al enfrentarse al hechicero. La otra es Caramon, quien todavía sufre por no poder proteger ya a su hermano. El guerrero debe, ante todo, aceptarse a sí mismo para luego redimir a su gemelo. Crysania y Caramon junto al impetuoso kender, Tas, son catapultados al pasado gracias a la magia, para que vivan la reencarnación de Raistlin, y contemplen el agónico acontecimiento del Cataclismo, que hundirá la orgullosa ciudad de Istar en el fondo del Mar Sangriento. Las autoras Margaret Weis y Tracy Hickman han creado esta segunda trilogía, Leyendas de la Dragonlance , tanto o más interesante que la que formaba las Crónicas de la Dragonlance . En las Leyendas aparecen algunos de los personajes que intervenían en las Crónicas y se incorporan otros protagonistas, produciéndose nuevas y apasionantes situaciones tanto en el Presente como en el Pasado. Selección de novelas de la Saga de la Dragonlance', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1873, '9788477227182', 'Flint, rey de los Gullys', 1, '1992', 365, 'Flint the King', 'media/core/9788477227182.jpeg', 1, '2023-04-27 10:25:06.532257', '2023-04-27 10:25:06.532257', 1084, 13, 6, 5, NULL, '', '07_02', 'Preludios de la Dragonlance, segunda trilogía II', 9, 'Durante el mes de mayo, Timun Mas publica los seis volúmenes que componen los Preludios de la Dragonlance en edición de bolsilloINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1874, '9788477227175', 'La misión de Riwerwind', 1, '1992', 392, 'Riverwind the Plainsman', 'media/core/9788477227175.JPG', 1, '2023-04-27 10:28:31.332741', '2023-04-27 10:28:31.332741', 1085, 13, 6, 5, NULL, '', '07_02', 'Preludios de la Dragonlance, segunda trilogía I', 9, 'Durante el mes de mayo, Timun Mas publica los seis volúmenes que componen los Preludios de la Dragonlance en edición de bolsilloINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1875, '9788477225508', 'Los Hermanos Majere', 1, '1991', 391, 'Brothers Majere', 'media/core/9788477225508.gif', 1, '2023-04-27 10:31:48.030122', '2023-04-27 10:31:48.030122', 1086, 13, 6, 5, NULL, '', '07_02', 'Preludios de la Dragonlance III', 9, 'Durante el mes de mayo, Timun Mas publica los seis volúmenes que componen los Preludios de la Dragonlance en edición de bolsilloINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1876, '9788477225492', 'El país de los kenders', 1, '1991', 384, 'Kendermore', 'media/core/9788477225492.jpg', 1, '2023-04-27 10:34:10.928392', '2023-04-27 10:34:10.928392', 1084, 13, 6, 5, NULL, '', '07_02', 'Preludios de la Dragonlance II', 9, 'Durante el mes de mayo, Timun Mas publica los seis volúmenes que componen los Preludios de la Dragonlance en edición de bolsillo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1877, '9788477225485', 'El guardián de Lunitari', 1, '1990', 497, 'Darkness & Light', 'media/core/9788477225485.jpeg', 1, '2023-04-27 10:36:40.773199', '2023-04-27 10:36:40.773199', 1085, 13, 6, 5, NULL, '', '07_02', 'Preludios de la Dragonlance I', 9, 'Los personajes clave de la saga Dragonlance se reúnen en El Último Hogar para despedirse antes de que cada uno emprenda viaje en busca de aventuras y fortuna. Allí están Caramon, Raistlin, Kitiara, Sturm, Flint, Tanis y Tass, y todos se comprometen a reunirse otra vez en el mismo lugar al cabo de cinco años. Es el preludio de una larga historia. La novela se centra en las vicisitudes de Kitiara y Sturm. Éste quiere ir a Solamnia, su patria, para buscar a su padre y Kitiara decide acompañarlo. Selección de novelas de la Saga de la Dragonlance', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1878, '9788477223030', 'El caballero de Solamnia', 1, '1989', 384, 'Heroes-Weasel''s Luck', 'media/core/9788477223030.jpg', 1, '2023-04-27 10:49:06.256158', '2023-04-27 10:49:06.256158', 1087, 13, 6, 5, NULL, '', '07_02', 'Héroes de la Dragonlance III', 9, 'Timun Mas pone a la venta la primera trilogía de la serie Héroes de la Dragonlance en una edición de bolsillo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1879, '9788477223023', 'Espada de reyes', 1, '1989', 416, 'Heroes Stormblade', 'media/core/9788477223023.jpeg', 1, '2023-04-27 10:52:06.649086', '2023-04-27 10:52:06.649086', 1088, 13, 6, 5, NULL, '', '07_02', 'Héroes de la Dragonlance II', 9, 'Timun Mas pone a la venta la primera trilogía de la serie Héroes de la Dragonlance en una edición de bolsillo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1880, '9788477223016', 'La leyenda de Huma', 1, '1989', 463, 'The Legend of Huma', 'media/core/9788477223016.jpeg', 1, '2023-04-27 10:54:43.089277', '2023-04-27 10:54:43.089277', 1089, 13, 6, 5, NULL, '', '07_02', 'Héroes de la Dragonlance I', 9, 'De la mano de Astinus de Palanthas, el lector se remonta en el tiempo para conocer la vida de Huma, el Caballero de Solamnia, primer Lancero. Este paladín de la Orden de la Corona está predestinado a descubrir dónde se halla la poderosa Drangonlance, obra de los mismos dioses, única arma capaz de derrotar a la legendaria Reina de la Oscuridad y sus hordas de dragones, que desde tiempos inmemoriales asuelan el mundo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1881, '9788445071656', 'IV Theanu', 1, '1991', 248, 'Theanu', 'media/core/9788445071656.jpg', 1, '2023-04-27 10:58:44.905085', '2023-04-27 10:58:44.905085', 1090, 13, 6, 5, NULL, '', '07_02', 'Los libros de Terramar', 210, '¡Déjate llevar por la magia de Terramar!INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1882, '9788445070697', 'III La costa más lejana', 1, '1988', 238, 'The Farthest Shore', 'media/core/9788445070697.jpg', 1, '2023-04-27 11:01:36.539951', '2023-04-27 11:01:36.539951', 1090, 13, 6, 5, NULL, '', '07_02', 'Los libros de Terramar', 210, '¡Déjate llevar por la magia de Terramar!INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1883, '8445070525', 'II Las tumbas de Atuan', 1, '1986', 169, 'The Tombs of Atuan', 'media/core/8445070525.jpeg', 1, '2023-04-27 11:04:01.954097', '2023-04-27 11:04:01.954097', 1090, 13, 6, 5, NULL, '', '07_02', 'Los libros de Terramar', 210, 'Han pasado más de diez años desde que Ged se enfrentara a su propia sombra en Un mago de Terramar. Capaz ahora de actuar en beneficio de otros, decide recobrar la runa de la unión, la mitad perdida del anillo de Erreth-Akbé, guardado, se cuenta, en las Tumbas de Atuan. La sacerdotisa de las Tumbas es Arha, que lleva el significativo apodo de la Devorada, y que no tiene identidad, pues la ha perdido para ponerse al servicio de los Sin Nombre, las potestades tenebrosas de Terramar.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1884, '8445070266', 'I Un mago de Terramar', 1, '1983', 213, 'A Wizard of Earthsea', 'media/core/8445070266.jpeg', 1, '2023-04-27 11:07:02.872919', '2023-04-27 11:07:02.872919', 1090, 13, 6, 5, NULL, '', '07_02', 'Los libros de Terramar', 210, 'En el mundo de Terramar la magia es un elemento indispensable. Un principio fundamental rige ese mundo: el equilibrio entre la vida y la muerte, que pocos pueden alterar. Pasados diez años, Ged capaz ya de actuar en beneficio de otros, decide recobrar la mitad de un anillo perdido en las tumbas de Atuan; sin embargo la sacerdotisa le involucrará en las profundidades de Terramar. ". ¡Déjate llevar por la magia de Terramar!', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1885, '9788477225225', 'Anghara', 1, '1994', 383, 'Aisling', 'media/core/9788477225225.jpeg', 1, '2023-04-27 11:20:06.738988', '2023-04-27 11:20:06.738988', 658, 13, 6, 5, '1994', '', '07_02', 'Indigo 8', 9, 'Parece como si la larga búsqueda de Índigo estuviera a punto de finalizar. Seis enfrentamientos han quedado atrás, y la muchacha regresa por fin a casa.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1886, '9788477225218', 'Espectros', 1, '1993', 335, '1993', 'media/core/9788477225218.jpg', 1, '2023-04-27 11:23:19.705058', '2023-04-27 11:23:19.705058', 658, 13, 6, 5, NULL, '', '07_02', 'Indigo 7', 9, 'Durante medio siglo, Índigo ha vagado por el mundo sin envejecer, sin cambiar e incapaz de morir, buscando los demonios que ella misma liberó tiempo atrás. Éste es su destino y el precio de su desatino.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1887, '9788477225201', 'Avatar', 1, '1992', 353, 'Avatar', 'media/core/9788477225201.jpg', 1, '2023-04-27 11:32:20.695821', '2023-04-27 11:32:20.695821', 658, 13, 6, 5, NULL, '', '07_02', 'Indigo 6', 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1888, '9788477225195', 'Troika', 1, '1991', 319, 'Troika', 'media/core/9788477225195.jpeg', 1, '2023-04-27 11:34:47.449181', '2023-04-27 11:34:47.449181', 658, 13, 6, 5, NULL, '', '07_02', 'Indigo 5', 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1889, '9788477225188', 'Nocturno', 1, '1990', 358, 'Nocturne', 'media/core/9788477225188.jpeg', 1, '2023-04-27 11:38:15.549445', '2023-04-27 11:38:15.549445', 658, 13, 6, 5, NULL, '', '07_02', 'Indigo 4', 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1890, '9788477224181', 'Infanta', 1, '1990', 383, 'Infanta', 'media/core/9788477224181.jpg', 1, '2023-04-27 11:40:36.446420', '2023-04-27 11:40:36.446420', 658, 13, 6, 5, NULL, '', '07_02', 'Indigo 3', 9, 'n un solitario y yermo pedazo de tundra, allí donde los límites de un pequeño reino se encuentran con las enormes murallas heladas de los glaciales meridionales, las ruinas de una torre solitaria arrojan su perversa sombra sobre la llanura', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1891, '9788477224174', 'Infierno', 1, '1990', 276, 'inferno', 'media/core/9788477224174.jpeg', 1, '2023-04-27 11:43:11.382677', '2023-04-27 11:43:11.398296', 658, 13, 6, 5, NULL, '', '07_02', 'Indigo 2', 9, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1892, '9788477224167', 'Némesis', 1, '1989', 298, 'Nemesis', 'media/core/sin-imagen_v6Wd9FF.jpg', 1, '2023-04-27 11:45:23.102122', '2023-11-14 18:58:48.522291', 658, 13, 6, 5, NULL, '', '07_02', 'Indigo 1', 9, 'Hace tiempo, mucho tiempo, la maldad de la humanidad provocó la ruina del mundo. La Madre Tierra, cansada de la ingratitud de sus hijos, desató su cólera y quiso vengarse de ellos. Todo quedó aniquilado, arrasado; los hombres aullaban y clamaban piedad, pero la Tierra no los escuchó. En medio de tanto dolor y ruina, sólo un hombre fue salvado por la Madre, quien le encargó que construyera una torre, la Torre de los Pesares, en la que debía encerrarse mientras durase la destrucción. Este hombre, el Hombre de las Islas, el Hijo del Mar, sería el que debería repoblar el mundo cuando acabara el castigo. Pero jamás ningún ser humano debía acercarse a la Torre, ni mucho menos penetrar en ella. La princesa Anghara sabía que no podía, que no debía aproximarse a la Torre. Era tabú. Pero lo hizo. Llevada por su loca curiosidad, la hija del rey del Carn Caille, entró en ella, encontró un cofre y lo abrió. Al hacerlo vio que estaba vacío, pero escuchó ligeros siseos como si fuera aire lo que salía de él. Ahora los demonios andaban sueltos y sobre el mundo cayó de nuevo la maldición de la Madre Tierra. Sólo Anghara podía reparar su imprudencia y debía buscar y enfrentarse a la misma fuerza destructora que ella liberó. Y Némesis la esperaba... Némesis es el primer volumen de una larga serie, formada por ocho libros, debida a la ágil pluma de la ya famosa Louise Cooper, que narra con detalle de filigrana la inquietante historia de Anghara, la curiosa princesa que, a modo de Pandora, desató el Mal en el mundo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1893, '8422633450', 'El Iniciado', 1, '1988', 364, 'The Initiate', 'media/core/8422633450.jpeg', 1, '2023-04-27 11:51:13.991701', '2023-04-27 11:51:13.991701', 658, 13, 6, 5, NULL, '', '07_02', 'El señor del tiempo I', 379, '“Tarod, Tarod, Tarod…” Una voz desconocida pronuncia este nombre martilleando sin cesar el cerebro del joven que no sabe cómo se llama ni por quién ha sido engendrado. El muchacho lo adopta como su nombre. Tarod reside en un fastuoso castillo, situado en la Península de la Estrella, donde habitan los Sumos Sacerdotes de Aeoris, dios del Bien, dios del Orden, y es instruido en las artes arcanas, convirtiéndose en uno de los hechiceros de mayor rango. Es el iniciado. Pero un día la voz se materializa en una forma humana de espíritu demoníaco. Es Yandros, personificación del mal. Por él sabrá que ha sido designado para volver a introducir el Caos en el mundo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1894, '9788477221463', 'El Proscrito', 1, '1988', 354, 'The Outcast', 'media/core/9788477221463.jpg', 1, '2023-04-27 11:54:00.321287', '2023-04-27 11:54:00.321287', 658, 13, 6, 5, NULL, '', '07_02', 'El señor del tiempo II', 9, 'Para huir del terrible destino al que el Círculo le había condenado, Tarod logra detener el Péndulo que rige el ineludible fluir del Tiempo. Y el Tiempo deja de existir. Tarod, prisionero en un limbo sin ayer ni mañana, vive resignándose a su inmortalidad... cuando un Warp, la terrible tempestad desencadenada por las fuerzas del Caos, arrastra a dos seres humanos, un hombre y una mujer, hasta el Castillo de la Península de la Estrella. Ella es Cyllan, una humilde boyera dotada de poderes parapsicológicos, y por la que Tarod sentirá un amor intenso y puro. Él, Drachea, el presuntuoso heredero del Margrave de la provincia de Shu. Encerrados los tres en el Castillo, provocarán nuevos y terribles acontecimientos hasta lograr que el Tiempo reemprenda su lento e Inexorable camino. En el momento en que Tarod detuvo el Péndulo, la espada del verdugo estaba a punto de abatirse sobre su cabeza... El regreso del Tiempo significa, pues, su muerte, a menos que logre encontrar una vía de escape, una salvación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1895, '9788432215698', 'Tiempo de silencio', 1, '2015', 286, NULL, 'media/core/9788432215698.jpg', 1, '2023-04-27 11:57:02.077321', '2023-04-27 11:57:02.077321', 1091, 1, 6, 5, 'Austral', '', '07_02', NULL, 7, 'A partir de un accidente estúpido y de sus consecuencias—no por evitables menos determinadas—el autor nos muestra con ojo irónico el panorama completo de los estratos sociales de la ciudad. Lo más significativo del libro, no obstante, es su decidido y revolucionario empeño por alcanzar una renovación estilística a partir—ya que no en contra—del monocorde realismo de la novela española de la epoca en que apareció. La primera edición de Tiempo de silencio apareció en Seix Barral en 1961 y alcanzó casi inmediatamente una extraordinaria resonancia crítica. Traducida al ingles, al frances, al italiano, al alemán, al holandes, al portugues, al sueco, al checo, al rumano, al finlandes, al danes, al polaco..., dondequiera ha sido señalada como una obra excepcional. La presente edición tiene carácter definitivo, por cuanto en ella se han restituido al texto la plena totalidad de las supresiones que había forzado a introducir en el la censura del regimen franquista.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1896, '8473930061', 'El Lazarillo de Tormes  // La Celestina', 1, '1975', 284, NULL, 'media/core/8473930061.jpg', 1, '2023-04-27 12:00:56.128188', '2023-04-27 12:00:56.128188', NULL, NULL, 6, 5, NULL, '', '07_02', NULL, 380, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1897, '8420600806', 'Historia de las ciencias 2. La revolución científica de los siglos XVI y XVII', 1, '1985', 185, 'A Hisroty of Sciences', 'media/core/8420600806.jpg', 1, '2023-04-27 17:02:47.763789', '2023-04-27 17:02:47.763789', 1092, 11, 6, 5, 'El libro de bolsillo', '', '07_02', NULL, 69, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1898, '9788497620253', 'El largo adiós', 1, '2002', 575, 'The Long Goo-bye', 'media/core/9788497620253.JPG', 1, '2023-04-27 17:05:37.810884', '2023-04-27 17:05:37.810884', 217, 14, 6, 5, NULL, '', '07_02', NULL, 361, 'Cuando Philip Marlowe conoció a Terry Lennox, ni tan sólo imaginaba que estaba a punto de involucrarse en uno de sus casos más complicados. La multimillonaria mujer de Lennox aparece brutalmente asesinada y todo apunta a que el homicida ha sido el mismo Lennox, quien acaba de matarse en Tijuana sin motivo alguno. Pero a Marlowe hay alguna pieza que no le encaja en el rompecabezas. Conocía bien a Terry y su manera de ser no cuadra con la personalidad de un suicida. Empeñado en conocer la verdad, indagará en el caso de los Lennox a pesar de los intereses implicados en ocultar los motivos de lamuerte del matrimonio.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1899, '9788497620178', 'No hay orquídeas para miss Blandish', 1, '2002', 300, 'No Orchids for Miss Blandish', 'media/core/9788497620178.jpg', 1, '2023-04-27 17:09:27.090363', '2023-04-27 17:09:27.090363', 1093, 14, 6, 5, NULL, '', '07_02', NULL, 361, 'No hay orquídeas para miss Blandish es la primera novela de James Hadley Chase, con la que alcanzó directamente la fama, con más de cuatro millones de ejemplares vendidos en el mundo entero. El autor combinó en ella, como en una coctelera, todos los ingredientes posibles: atracadores de bancos, policías corruptos y sádicos, un detective privado con una secretaria explosiva, secuestros, drogas, alcohol, perversiones sexuales y un psicópata asesino cuya brutalidad y sangre fría han resultado difícilmente homo-logables desde entonces. La banda de los Grisson, capitaneada por una madraza despiadada que tiene en su hijo Slim un digno sucesor, secuestra a una bella y rica heredera, miss Blandish, cuya vida se transforma a partir de ese hecho en un veloz descenso a los infiernos. Porque Slim Grisson encontrará en ella el objeto perfecto para saciar sus más oscuros deseos...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1900, '9788497620161', 'El espía que surgió del frío', 1, '2002', 366, 'Rhe Spy Who Came in from the Cold', 'media/core/9788497620161.jpeg', 1, '2023-04-27 17:12:03.433223', '2023-04-27 17:12:03.433223', 559, 14, 2, 5, NULL, '', '07_02', NULL, 361, 'En este clásico, el autor recrea un mundo jamás conocido antes en la novela de suspense. Con los conocimientos acumulados durante sus años en el servicio de inteligencia británica, le Carré saca a la luz los interiores un tanto turbios del espionaje internacional de la mano de Alec Leamas, un agente británico durante los primeros años de la guerra fría en Berlín. Leamas es responsable de mantener a sus agentes dobles protegidos y con vida, pero los alemanes del Este empiezan a matarlos, por lo que su superior, Control, le pide que vuelva a Londres no para echarle del cuerpo sino para encargarle una misión un tanto complicada.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1901, '9788495808882', 'La máscara de Dimitrios', 1, '2002', 382, 'The Mask of Dimitrios', 'media/core/9788495808882.jpg', 1, '2023-04-27 17:15:09.422170', '2023-04-27 17:15:09.422170', 1094, 14, 6, 5, NULL, '', '07_02', NULL, 361, 'Charles Latimer, un profesor universitario ya retirado y conocido escritor de novelas policiacas, se encuentra de vacaciones en Turquía donde el coronel Haki, un miembro de la policía truca, no deja mostrar un interés inusitado por él. Haki, gran amante de las novelas de detectives pretende regalarle la trama de su próximo libro. No es la primera vez que Latimer se encuentra con este tipo de proposiciones, conm lo que Latimer busca desesperadamente una manera de irse por la tangente hasta que el coronel le dice me pregunto, míster Latimer, si usted sentirá interés o no por verdaderos asesinos. Años después, cuando miró al pasado, Latimer entendió que la verdadera obsesión empezó en Estambul. Fue allá, de la boca del coronel Haki, donde escuchó por primera vez el nombre de dimitrios Makropoulos. También fue allá donde por primera vez vio un cadáver, recién sacado del Bósforo. Acuchillado, abandonado, flotando entre porquería. Y con esto, de alguna manera, todas las imágenes del pasado de un europeo torturado fluyeron por su mente como si de una pesadilla se tratase: asesinatos, insurreciones y la extraordinaria doble vida de los espías. Pero Latimer, todo lo contrario a la policía, no podía abandonar a dimitrios, incluso si descubrir quién era ponía en riesgo su propia vida.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1902, '9788416540129', 'Meditaciones. El manga', 1, '2015', 1, NULL, 'media/core/9788416540129.jpg', 1, '2023-04-29 06:48:16.750341', '2023-04-29 06:48:16.750341', 467, 34, 6, 5, NULL, '', '07_02', NULL, 381, 'Adaptación al manga de los pensamientos y reflexiones del emperador romano Marco Aurelio, redactados en el momento crepuscular del imperio.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1903, '9788425430886', 'El arte de la guerra. El manga', 1, '2012', 1, NULL, 'media/core/9788425430886.jpg', 1, '2023-04-29 06:50:26.053941', '2023-04-29 06:50:26.053941', 1031, 34, 6, 5, NULL, '', '07_02', NULL, 382, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1904, '9788402071729', 'El almuerzo desnudo', 2, '1982', 280, 'Nacked lunch', 'media/core/9788402071729.jpg', 1, '2023-04-29 06:53:38.223902', '2023-04-29 06:53:38.223902', 850, 1, 6, 5, 'Club Bruguera', '', '07_02', NULL, 126, 'El almuerzo desnudo, una de las novelas más míticas de la literatura norteamericana, es un descenso a los infiernos de la droga y una denuncia horrorizada y sardónica, onírica y alucinatoria de la sociedad actual, un mundo sin esperanza ni futuro. Burroughs dispara sus flechas contra las religiones, el ejército, la universidad, la sexualidad, la justicia corrupta, los traficantes tramposos, el colonialismo, la burocracia y la psiquiatría representada por el siniestro Dr. Benway, el gran manipulador de conciencias, el experto en Control total.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1905, '8402070949', 'La hierba roja', 2, '1982', 178, 'L''herbe rouge', 'media/core/8402070949.jpg', 1, '2023-04-29 06:57:00.436105', '2023-04-29 06:57:00.436105', 153, 1, 6, 5, 'Club Bruguera', '', '07_02', NULL, 126, 'El ingeniero Wolf y su ayudante, el mecánico Lazuli, construyen una máquina del tiempo gracias a la que Wolf pretende, mediante el retorno a su infancia, conjurar todos los errores y todas las obsesiones que le habían acosado entonces. Sólo exorcizando aquellas sombras estará, cree el, en condiciones de recuperar la facultad de gozar de los fugaces instantes de felicidad que le brinda la vida. Pero todos sabemos que los inquisidores no aceptan semejantes audacias y quien sabe si Wolf conseguirá sobreponerse a ellos…Esta es tal vez la novela más intimista y menos burlesca de Vian, y muchas de las situaciones remiten sin duda a su vida personal. No obstante, a la ternura que inspira esta historia, a la vez dolorosa y patetica, Vian no puede dejar de añadir, como siempre en toda su obra, la desbordante fantasía y la lúcida insolencia que otorga a personajes e historias esa mágica y contagiosa vitalidad que atrapa de principio a fin a sus lectores de ayer y de hoy, más que incondicionales adictos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1906, '9788402079701', 'El visitante y otras historias', 2, '1983', 186, 'A Prospect of the Sea', 'media/core/9788402079701.jpeg', 1, '2023-04-29 07:00:32.403181', '2023-04-29 07:00:32.403181', 1095, 44, 6, 5, 'Club Bruguera', '', '07_02', NULL, 126, 'La obra de Dylan Thomas, galés, alcohólico, y bohemio, revaloriza el poder creador de la imaginación y la gran función alumbradora que el mundo cotidiano y el mítico, entremezclados, tienen para la poesía. Prueba de ello la constituyen los textos reunidos en este volumen bajo el título genérico de El visitante y otras historias, selección realizada por Thomas antes de su muerte. Estos catorce textos del celebrado autor del Retrato del artista cachorro compendian la casi totalidad de sus preocupaciones temáticas y expresivas: el sentimiento mágico de la Naturaleza y la pasión del hombre por sus orígenes, así como los paraísos de la infancia, son los motivos recurrentes de estas páginas. Su ardor vital y su fabuloso verbo creador exploran ámbitos inéditos y siguen, como en el caso de Blake y Rimbaud, el camino iluminado de todos los poetas visionarios anteriores.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1907, '8475309097', 'Ética y Política', 1, '1985', 256, NULL, 'media/core/8475309097.jpeg', 1, '2023-04-29 07:04:40.397185', '2023-04-29 07:04:40.397185', 1096, 2, 6, 5, 'Bibliotec de Economía, Política y Sociología', '', '07_02', NULL, 80, 'El origen de Ética y Política es un curso monográfico que José Luis López Aranguren impartió en 1960-61 en la Facultad de Filosofía y Letras de la por entonces denominada Universidad Central (desde 1970 Universidad Complutense de Madrid), donde impartía sus clases. Dadas las peculiaridades de la situación sociopolítica española de la época, se trataba de un conjunto de contenidos que se apartaban de lo que era usual.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1908, '8472917304', 'El principio federativo', 1, '1985', 163, 'Le principe fédératif', 'media/core/8472917304.jpeg', 1, '2023-04-29 07:08:09.111569', '2023-04-29 07:08:09.111569', 1097, 2, 6, 5, 'Los grandes pensdores', '', '07_02', NULL, 329, 'https://es.wikipedia.org/wiki/Principio_federativo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1909, '8459902676', 'Discurso preliminar de a enciclopedia', 1, '1985', 188, 'Discours préliminaire de l''Encyclopédie', 'media/core/8459902676.jpeg', 1, '2023-04-29 07:12:34.935560', '2023-04-29 07:12:34.935560', 1098, 2, 6, 5, 'Los grandes pensdores', '', '07_02', NULL, 329, 'Escrito que, tras la invita­ción de Denis Diderot, se publicó en 1751 al comienzo del primer volumen de la Enciclopedia (v.). Por su firmeza lógica constituye una obra autónoma, síntesis de la concepción filosófica de los enciclopedis­tas y documento de la fe racionalista del siglo XVIII. Reconociendo en Descartes al fundador de la nueva metodología cientí­fica, D’Alembert evitó la pendiente incli­nada del dogmatismo y volvió de nuevo al empirismo inglés. Los conceptos con que traza el cuadro de los conocimientos hu­manos y de sus relaciones derivan directa­mente del Ensayo sobre el intelecto humano (v.) de Locke.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1910, '847291688X', 'Discurso sobre el espíritu positivo', 1, '1984', 157, 'Discours sur l''esprit positif', 'media/core/847291688X.jpg', 1, '2023-04-29 07:16:02.753651', '2023-04-29 07:16:02.753651', 1099, 2, 6, 5, 'Los grandes pensdores', '', '07_02', NULL, 329, 'El "Discurso sobre el espíritu positivo", publicado en 1844, es una introducción sintética y completa al pensamiento de Auguste Comte (1789-1857), fundador y maestro de la corriente positivista que tanta influencia ejerció en la filosofía del siglo XIX. Obra de madurez, acota con vigor los momentos fundamentales de la concepciones comteanas y los agrupa en páginas tan escasas como concisas y transparentes. Como indica Julián Marías, la obra es sin duda una incomparable exposición de todo el sistema comteano, «con una ventaja esencial sobre toda exposición ulterior: cualquier libro positivista nos da lo que Comte ha sido para sus continuadores; la obra original, en cambio, nos da el pensamiento auténtico y primitivo». Versión y prólogo de Julián MaríasINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1911, '8472916839', 'Pensamiento filosóficos. Investigaciones filosóficas sobre el origen y la naturaleza de lo bello', 1, '1984', 153, 'Pensées philosophiques. Recherches philosophiques sur l''origine et la nature du beau', 'media/core/8472916839.jpg', 1, '2023-04-29 07:19:42.316269', '2023-04-29 07:19:42.316269', 1048, 2, 6, 5, 'Los grandes pensdores', '', '07_02', NULL, 329, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1912, '8449971926', 'Discurso del método', 1, '1984', 171, 'Discours de la méthode', 'media/core/8449971926.jpeg', 1, '2023-04-29 07:22:23.191654', '2023-04-29 07:22:23.191654', 1100, 2, 6, 5, 'Los grandes pensdores', '', '07_02', NULL, 329, 'El Discurso, texto eminentemente filosófico, marca el punto de ruptura con el mundo conceptual del medievo, dominado por la escolástica.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1913, '8472915697', 'Dialogos. Aplogía de Socrates, Criton, Laques, Fedon', 1, '1983', 221, NULL, 'media/core/8472915697.jpg', 1, '2023-04-29 07:25:18.650918', '2023-04-29 07:25:18.650918', 1101, 2, 6, 5, 'Los grandes pensdores', '', '07_02', NULL, 329, 'https://es.wikipedia.org/wiki/Di%C3%A1logo_plat%C3%B3nico', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1914, '9788422659747', 'El rey', 1, '1990', 191, 'The King', 'media/core/9788422659747.GIF', 1, '2023-04-30 07:50:26.886990', '2023-04-30 07:50:26.886990', 1102, 1, 6, 5, NULL, '', '07_02', NULL, 90, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1915, '8485047184', 'Kama Sutra', 1, '1973', 276, NULL, 'media/core/sin-imagen_RDmLKKK.jpg', 1, '2023-04-30 07:54:15.351062', '2023-04-30 07:54:15.351062', 633, 10, 6, 5, NULL, '', '07_02', NULL, 383, 'https://es.wikipedia.org/wiki/Kama-sutra', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1916, '9788420467177', 'Cabo Trafalgar', 6, '2004', 260, NULL, 'media/core/9788420467177.jpeg', 1, '2023-04-30 07:56:56.622769', '2023-04-30 07:56:56.622769', 73, 16, 6, 5, NULL, '', '07_02', NULL, 10, 'Trafalgar 1805: Habrás estado allíINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1917, '8472234061', 'Groucho y yo', 4, '1977', 341, 'Groucho and me', 'media/core/8472234061.jpg', 1, '2023-04-30 08:01:08.158014', '2023-04-30 08:01:08.158014', 1103, 31, 6, 5, 'Cuadernos ínfimos', '', '07_02', NULL, 12, 'Groucho y su yo, fundidos aquí en uno solo, escribieron, como era inevitable suponer, un libro que sólo puede escribirse como�, bueno, indescriptible. También será inevitable, si el lector siente la curiosidad por saber a ciencia cierta quiénes y cómo son Groucho y el yo-de-Groucho, que compre y lea estas memorias muy particulares, porque nosotros tan sólo podremos adelantarle aquí que, aunque uno y otro sean de naturaleza profundamente similar, también son, paradójicamente, muy distintos. En tanto que Groucho, ese incómodo insumiso, entrometido, criticón e insolente mujeriego, dinamita la sociedad, siembra el absurdo y el desconcierto por doquier y no comprende cómo alguien puede pertenecer a un club del que él sea socio, el yo-de-Groucho no piensa sino en medrar y enriquecerse en esa misma sociedad que dice despreciar y se arrima a cualquiera con tal de que le introduzca en el club más selecto. Pero lo cierto es que los dos gozan por igual del don privilegiado de hacernos morir de risa�', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1918, '9788422689157', 'La vida de os insectos', 1, '2001', 251, 'Jizn nassekomykh', 'media/core/9788422689157.jpg', 1, '2023-04-30 08:06:36.031457', '2023-04-30 08:06:36.031457', 1104, 1, 6, 5, NULL, '', '07_02', NULL, 58, 'Un domingo por la tarde, a principios de otoño, todo discurre como siempre en un balneario de Crimea: algunos se reúnen para hacer negocios, un padre inicia a su hijo en los secretos de la existencia, algunos filosofan y otros buscan amor, sexo o droga. Pero a veces las cosas se complican y una pisada puede acabar con sus vidas, un murciélago puede convertirse en la sombre de la muerte o una cinta matamoscas puede dar fin a tiernos proyectos. Porque Arthur, Sam, Marina,Natasha, Dimitri y tantos otros inolvidables protagonistas de esta historia, viven su peripecia como hombres y mujeres a la vez que como insectos. Y al igual que todos nosotros, van en busca de la luz, sucumben a las órdenes incomprensibles del instinto y se enfrentan ante el enigma de eso que se agita y nos arrastra, y que llamamos vida.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1919, '8422651335', 'El Cliente', 1, '1993', 489, 'The Client', 'media/core/8422651335.jpg', 1, '2023-04-30 08:10:00.813621', '2023-04-30 08:10:00.813621', 124, 1, 6, 5, NULL, '', '07_02', NULL, 15, 'Un senador ha muerto, y Mark Sway, un chico de once años, es el único que sabe dónde está escondido el cadáver. En el FBI quieren que revele el paradero a toda costa, sea cual sea el perjuicio para Mark y su familia. Y el asesino quiere que mantenga la boca cerrada para siempre.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1920, '8422641747', 'El jaquemart', 1, '1991', 343, NULL, 'media/core/8422641747.jpg', 1, '2023-04-30 08:12:52.578964', '2023-04-30 08:12:52.578964', 1105, 1, 6, 5, NULL, '', '07_02', NULL, 5, 'Un año después de la publicación de Noticias del mundo real (Andanzas 364), cuarta novela inédita con la que acogimos a Juan Miñana, creemos que era hora de recuperar para nuestro catálogo y para sus muchos lectores El jaquemart, su segunda novela, que no sólo supuso uno de los mejores relatos históricos sobre el pasado, sino que confirmó la sabiduría y la calidad de prosa de su joven autor. En efecto, El jaquemart es una ambiciosa recreación de la Barcelona del siglo XVII, protagonizada por un relojero obstinado en su lucha contra el tiempo, y a la vez un extraordinario ejercicio de estilo de dominio narrativo. La peste asuela Barcelona en los últimos años del reinado de Felipe IV. Buenaventura Deulocrega, maestro en artes y medicina, llega al hospital de la Santa Cruz dispuesto a trabajar contra la epidemia. Allí conocerá a un personaje enigmático y sabio, Juan de Ameno, un relojero del rey que ha pedido asilo en las cámaras privadas del hospital para concebir lo que será su último proyecto: un jaquemart o autómata de bronce destinado a la torre de horas de la catedral. Buenaventura y Juan de Ameno asisten desde ese extraño refugio a los embates de un presente difícil y amargo, y forjan una extraña amistad parapetados tras una constante recreación del pasado que, en forma de fábula urdida con la sutileza de un mecanismo de relojería, parece salvaguardarles del paso implacable del tiempo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1921, '8435007715', 'Las cabezas trocadas', 1, '1986', 159, 'Die verstauchten Köpfe', 'media/core/8435007715.jpg', 1, '2023-04-30 10:42:01.414262', '2023-04-30 10:42:01.414262', 361, 1, 6, 5, 'Narrativa contemporáneas', '', '07_02', NULL, 47, 'Bajo la forma de una ingenua y encantadora narración de aires hindúes, se esconde una reflexión recurrente en la narrativa de Thomas Mann : los conflictos entre el arte y la vida. La anécdota de la que parte es bastante sorprendente: dos jóvenes enamorados de la misma chica intercambian sus cabezas por la intervención de una divinidad hindú, ya que ella ama la interioridad de uno y el cuerpo del otro. Esta solución no resolverá los problemas de los tres personajes. Esta obra es considerada una de las obras breves más importantes de Mann por las muchas lecturas que sugiere y por las diversas reflexiones a las que induce al lector.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1922, '9788422673989', 'Ritos iguales', 1, '1998', 263, 'Equal Rites', 'media/core/9788422673989.jpeg', 1, '2023-04-30 10:53:23.713496', '2023-04-30 10:53:23.713496', 109, 13, 6, 5, NULL, '', '07_02', 'Mundodisco 3', 74, 'Un mago moribundo cede su bastón -y por tanto su poder- a Eskarina, un recien nacido que, según los rituales admitidos, no puede ser mago sino bruja. Con el tiempo, el rito de iniciación se completa con un aprendizaje más formal en la Universidad Invisible, inefable centro de estudios esotericos, donde el mago Simón hace gala de sus increíbles poderes. Juntos, Eskarina y Simón tendrán que hacer frente a una invasión de extrañas criaturas que amenazan con destruir el Mundodisco...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1923, '9788422658474', 'Momo', 1, '1995', 260, 'Momo', 'media/core/9788422658474.jpeg', 1, '2023-04-30 10:57:12.387740', '2023-04-30 10:57:12.387740', 818, 48, 6, 5, NULL, '', '07_02', NULL, 384, 'Momo es una niña con un don muy especial: sólo con escuchar consigue que los que están tristes se sientan mejor, los que están enfadados solucionen sus problemas o que a los que están aburridos se les ocurran cosas divertidas. De repente, la llegada de los hombres grises va a cambiar su vida. Porque prometen que ahorrar tiempo es lo mejor que se puede hacer, y pronto nadie va a tener tiempo para nada. Ni siquiera para jugar con los niños. Momo es la ºnica que no cae en la trampa, y con la ayuda de la tortuga Casiopea y del maestro Hora, llevará al lector a una aventura fantástica llena de enseñanzas sobre la amistad, la bondad y el valor de las cosas sencillas. En definitiva, sobre lo que de verdad nos hace felices.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1924, '9788445076538', 'Crónicas marcianas', 1, '2011', 263, 'The Martian Chronicles', 'media/core/9788445076538.jpeg', 1, '2023-04-30 10:59:56.939327', '2023-04-30 10:59:56.939327', 787, 3, 6, 5, 'Ciencia Ficción', '', '07_02', NULL, 7, 'Un clásico del siglo XX: la obra que consolidó a Bradbury como uno de los mejores escritores de la narrativa norteamericana.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1925, '8435004449', 'El fin de la infancia', 1, '1976', 238, 'Childhood''s End', 'media/core/8435004449.jpeg', 1, '2023-04-30 11:02:26.324818', '2023-04-30 11:02:26.324818', 577, 3, 6, 5, NULL, '', '07_02', NULL, 47, 'Con El fin de la infancia -- escribió Basil Davenport-- Arthur C. Clarke se une al pequeño grupo formado por Olaf Stapledon, C. S. Lewis y quizá H. G. Wells, que ha usado la ciencia-ficción como vehículo de ideas filosóficas. Dicho esto, es necesario añadir apresuradamente que El fin de la infancia es un libro tan ameno, desde el punto de vista de la narrativa pura, como cualquier otra novela común contemporánea. El fin de la infancia --obra que según William Du Bois merece la total atención de los habitantes de esta época de ansiedad-- tiene como tema la futura evolución del hombre. Una raza extraña llega a la Tierra y trae consigo paz, prosperidad..., y la inesperada tragedia de la perfección. ¿Qué seguirá a la extinción de la raza humana? Arthur C. Clarke, en un final de notable belleza, plantea la más alucinante de las hipótesis.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1926, '8437600898', 'El Túnel', 1, '1978', 165, NULL, 'media/core/8437600898.png', 1, '2023-04-30 11:05:37.107038', '2023-04-30 11:05:37.107038', 1106, 1, 6, 5, NULL, '', '07_02', NULL, 153, '"El túnel" (1948), del argentino Ernesto Sábato, es una de las grandes novelas sudamericanas de este siglo, cuyos ecos recogieron pronto en Europa Graham Greene y Camus. El relato, montado con los recursos de la novela policial, desarrolla un personaje que revela su psicología introspectiva e impone al lector un análisis de la desesperanza. El protagonista, Juan Pablo Castel, persigue inútilmente lo inalcanzable, que no es sino el regreso a la infancia, simbolizada en la ventana de un cuadro, motivo reiterado largamente en la narración.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1927, '8420565200806', 'Mecanoscrit del segon origen', 1, '2003', 229, NULL, 'media/core/8420565200806.jpg', 1, '2023-05-01 07:41:40.093638', '2024-04-30 08:42:39.424201', 1107, 48, 6, 5, NULL, '', '07_03', NULL, 2, 'https://es.wikipedia.org/wiki/Mecanoscrito_del_segundo_origen', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1928, '9788415625544', 'El expreso de Tokio', 5, '2018', 214, 'Ten to Sen', 'media/core/9788415625544.jpg', 1, '2023-05-01 07:45:37.001067', '2023-05-01 07:45:37.001067', 1108, 14, 6, 5, NULL, '', '07_02', NULL, 385, 'Los cadáveres de un oscuro funcionario y de la camarera de un restaurante de Tokio son descubiertos en una playa de la isla de Kyushu. Todo parece indicar que se trata de un caso claro: dos amantes que se han suicidado juntos tomando cianuro.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1929, '8473290852', 'La plaça del Diamant', 17, '1979', 253, NULL, 'media/core/8473290852.jpg', 1, '2023-05-01 07:49:22.647925', '2023-05-01 07:49:22.647925', 858, 1, 6, 5, NULL, '', '07_02', NULL, 386, 'La plaza del Diamante ha sido reconocida como una de las mejores novelas catalanas de posguerra. “La novelista – dice Joan Fuster- ha sabido encontrar el tono del personaje con una exactitud prodigiosa. Hay pocas novelas de tanta espontaneidad aparente lograda con tal sutileza.” La acción no puede ser más sencilla a la par que conmovedora, aunque más exacto sería referirse destino de mujer común y la forma como descripción elegíaca de los hechos con la descripción elegíaca del un modo de vivir, de un pedazo de ciudad entrañable.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1930, '8422635763', 'El viaje nupcial', 1, '1986', 166, 'Kush e solli Doruntinën', 'media/core/8422635763.jpeg', 1, '2023-05-01 07:53:55.059883', '2023-05-01 07:53:55.059883', 1073, 1, 6, 5, NULL, '', '07_02', NULL, 107, 'La trama de El cortejo nupcial helado en la nieve hunde sus raíces en unos hechos reales: los sucedidos el 1 de abril de 1981, cuando el Ejército, empleando incluso carros de combate, aplastó a sangre y fuego las manifestaciones de los albaneses de Kosovo en demanda de mejoras y de un marco republicano en el seno de la Federación yugoslava.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1931, '9788483004715', 'L''atles furtiu', 7, '1998', 321, NULL, 'media/core/9788483004715.jpg', 1, '2023-05-01 07:57:25.203933', '2023-05-01 07:57:25.203933', 1109, 16, 6, 5, NULL, '', '07_02', NULL, 387, 'En la Europa del siglo XIV, de judíos, moros y cristianos, de catedrales y ambiciones infinitas, un mapa podía transformar el mundo...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1932, '8485354263', 'Cuentos de los vikingos extraídos de las antiguas sagas', 1, '1986', 113, NULL, 'media/core/8485354263.jpeg', 1, '2023-05-01 08:02:47.369205', '2024-04-30 08:43:02.642999', 1110, 44, 6, 5, 'Biblioteca de cuentos maravillosos', '', '07_03', NULL, 363, 'Los cuentos seleccionados dejan aparte las historias del panteón nórdico de dioses, centrándose tan sólo en relatos que involucran héroes (príncipes, ladrones, infames...) de los países de los mares del Norte. Es decir, historias que son casi punto por punto trasladables a cualquier cultura en las que el protagonista usual es la naturaleza humana, vestida para la ocasión de honor, celos, traición o avaricia... Universales que producen mitos semejantes en todas partes, desde la Grecia Clásica a Dallas, pasando por cómics y folletines de mayor o menor fortuna.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1933, '9788422687795', 'La caverna', 1, '2000', 398, 'A caverna', 'media/core/9788422687795.jpg', 1, '2023-05-01 08:05:07.878905', '2023-05-01 08:05:07.878905', 725, 1, 6, 5, NULL, '', '07_02', NULL, 73, 'Un libro que es también una advertencia sobre nuestras múltiples extinciones cotidianas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1934, '8422637707', 'Asesinato en la convención', 1, '1977', 318, 'Murder at the Aba', 'media/core/8422637707.jpg', 1, '2023-05-01 08:08:39.767608', '2023-05-01 08:08:39.767608', 341, 1, 2, 5, NULL, '', '07_02', NULL, 388, '¿Es posible, en pleno siglo XX, ser un experto en Historia, biología, religión, literatura, geografía... y escribir prolífica y regularmente sobre todos estos temas? ¿Y es posible que ese mismo ser, evidentemente excepcional, sea además uno de los maestros de la ciencia ficción?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1935, '8422649241', 'La tabla de Flandes', 1, '1995', 418, NULL, 'media/core/8422649241.jpg', 1, '2023-05-01 08:10:57.705348', '2023-05-01 08:14:59.903755', 73, 1, 2, 5, NULL, '', '07_03', NULL, 5, 'A finales del siglo XV un viejo maestro flamenco introduce en uno de sus cuadros, en forma de partida de ajedrez, la clave de un secreto que pudo cambiar la historia de Europa.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1936, '8422618958', 'El amante', 1, '1984', 155, 'L''amant', 'media/core/8422618958.jpg', 1, '2023-05-01 08:13:48.906699', '2023-05-01 08:13:48.906699', 1111, 1, 6, 5, NULL, '', '07_02', NULL, 114, 'Esa jovencita bellísima, pero pobre, que vive en Indochina, no es otra que la propia escritora quien, hoy, recuerda las relaciones apasionadas, de intensos amor y odio, que desgarraron a su familia y, de pronto, grabaron prematuramente en su rostro los implacables surcos de la madurez. Pocas personas -y en particular mujeres- permaneceran inmunes a la contagiosa pasión que emana de este libro.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1937, '9788467263787', 'La constalción ddel Perro', 1, '2014', 316, 'The Dog Stars', 'media/core/9788467263787.jpg', 1, '2023-05-01 09:51:38.825616', '2023-05-01 09:51:38.825616', 1112, 1, 6, 5, NULL, '', '07_03', NULL, 389, 'Los humanos casi se han extinguido. Big Hig no está infectado, así que sigue aquí. Intenta mantenerse con vida en un hangar junto a su perro. También con la ayuda de su pequeño avión Cessna y de Bangley, su vecino violento. Y con un libro de poemas, algo de petróleo y cada lata de Coca-Cola que puede conseguir. Su esposa también ha muerto (está tan solo que inventó una constelación para ella). Incluso cuando parece que ya no queda nada, él quiere continuar. Pero sobrevivir ya no es suficiente. Entonces se le presenta la oportunidad de cambiarlo todo, de lanzarse a la búsqueda de lo desconocido para encontrar algo que jamás hubiese imaginado. Llega por fin la novela que sacudió a la crítica mundial.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1938, '9788415472872', 'Poeta en Nueva Work', 2, '2013', 311, NULL, 'media/core/9788415472872.jpg', 1, '2023-05-01 09:54:26.748499', '2023-05-01 09:54:26.748499', 766, 4, 6, 5, NULL, '', '07_03', NULL, 46, '', 'Primera edición del original fijada y anotada por Andrew A. Anderson');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1939, '8422636735', 'Soldado de la niebla', 1, '1991', 382, 'Soldier of the Mist', 'media/core/8422636735.jpeg', 1, '2023-05-01 09:57:33.790846', '2023-05-01 09:58:25.282926', 1113, 1, 6, 5, NULL, '', '07_03', NULL, 74, '"Mi nombre es Latro. No debo olvidarlo. El medico dijo que todo se me olvidaba muy de prisa a causa de una herida que sufri durante el combate. Le dio un nombre a mi enfermedad como si esta fuera un hombre, pero no recuerdo cual fue. Dijo que debo aprender a escribir lo mejor que pueda y de tal modo sere capaz de leer mis escritos cuando haya olvidado algo. Esa es la razon de que me entregara el pergamino y el punzon hecho con el pesado metal que se usa para fabricar los proyectiles de las hondas."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1940, '9788467265385', 'Los besos en el pan', 1, '2015', 313, NULL, 'media/core/9788467265385.jpeg', 1, '2023-05-01 10:00:20.087944', '2023-05-01 10:00:20.087944', 965, 1, 6, 5, NULL, '', '07_03', NULL, 114, 'Hay que ser muy valiente para pedir ayuda, pero hay que ser todavía más valiente para aceptarla. Los besos en el pan, una conmovedora novela sobre nuestro presente.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1941, '8476391056', 'Frankestein o el moderno Prometeo', 1, '1989', 309, NULL, 'media/core/8476391056.jpeg', 1, '2023-05-01 10:05:17.222611', '2023-05-01 10:05:17.222611', 1114, 1, 6, 5, NULL, '', '07_03', NULL, 390, 'La presente edición se completa con un documentado estudio preliminar sobre Mary Shelley y la gestación de «Frankenstein» a cargo de Antonio José Navarro. Mary Shelley (1797-1851) fue hija del pensador radical William Godwin célebre autor del revolucionario ensayo titulado«Political Justice» y de novelas de tradición gótica como «St Leon»y «Caleb Williams» y de Mary Wollstonecraft, autora de la más ardiente defensa sobre la educación y derechos de la mujer que se hubiera hecho hasta entonces, expresada en su obra«Vindication of the Rights of Woman». En 1814 conoció al poeta Percy Bysshe Shelley, que sería el amor de su vida, y con quien huyó al Continente en 1814. En la noche del 17 de junio de 1816, después de una velada en compañía de Lord Byron, Percy B. Shelley, John W. Polidori, Matthew G. Lewis, entre otros, en la que se discutió sobre el galvanismo, los experimentos del doctor Erasmus Darwiny la posibilidad de descubrir el principio vital y conferirlo a la materia inerte, Mary tuvo una pesadilla en la cual un estudiante obsesionado con la creación de vida artificial despierta y contempla horrorizado a su espantoso engendro. Este sueño fue el primer atisbo de una Criatura que se ha elevado por sí misma al pedestal de los mitos básicos del terror. A partir de esta visión de pesadilla, Mary Shelley construyó«Frankenstein, o el moderno Prometeo», una historia que ha estremecido a generaciones de lectores y cuya actualidad permanente han garantizado las numerosas adaptaciones al cine. Una historia destinada no sólo a despertar el horror, sino a proponer una reflexión moral sobre la naturaleza humana y la génesis del Mal.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1942, '8476391099', 'Drácula', 1, '1989', 397, NULL, 'media/core/8476391099.jpeg', 1, '2023-05-01 10:07:25.661859', '2023-05-01 10:07:25.661859', 857, 12, 6, 5, NULL, '', '07_03', NULL, 390, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1943, '8472917711', 'Europa después de Hitles (I)', 1, '1985', 332, 'Europe after Hitler', 'media/core/8472917711.jpg', 1, '2023-05-01 10:13:15.864010', '2023-05-01 10:13:15.864010', 1115, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '13', 329, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1944, '8472917983', 'Comentarios de la guerra de las Galias y de la guerra civil', 1, '1985', 365, 'De Bello Gallico. De Bello Civili', 'media/core/8472917983.jpg', 1, '2023-05-01 10:16:35.032281', '2023-05-01 10:16:35.032281', 762, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '18', 329, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1945, '8472917703', 'Los doce césares', 1, '1985', 324, 'De duodecim Caesarum', 'media/core/8472917703.jpeg', 1, '2023-05-01 10:19:38.371953', '2023-05-01 10:19:38.371953', 1116, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '12', 329, 'A lo largo de sus trece siglos de historia, Roma vivió tres momentos cruciales que marcaron de modo irreversible su evolución política y humana y, a través de ella, la de una gran parte de la actual Europa: la creación de la República tras la expulsión de los reyes etruscos (509 a. C.); la transformación de la República en Imperio (27 a. C.), y, por último, la división definitiva del Imperio en dos partes, Oriental y Occidental, llevada a cabo por Teodosio, con la imposición del cristianismo como religión del Imperio (395 d. C.).INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1946, '8472917959', 'Diario. Relación de viajes', 1, '1985', 224, NULL, 'media/core/8472917959.jpeg', 1, '2023-05-01 10:22:29.436008', '2023-05-01 10:22:29.436008', 1117, 32, 6, 5, 'Biblioteca de la Historia', '', '07_03', '15', 329, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1947, '8472917371', 'Cartas de la conquista de México', 1, '1985', 242, NULL, 'media/core/8472917371.jpg', 1, '2023-05-01 10:25:20.998626', '2023-05-01 10:25:20.998626', 1118, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '1', 329, 'Cinco fueron las Cartas de Relación que envió Cortés a la corona: la primera, enviada a la Reina Doña Juana y al Emperador Carlos V, pérdida pero reemplazada históricamente por una relación con igual motivo por la justicia y regimiento de la Villa Rica de la Vera Cruz (1519) en la cual refiere los primeros acontecimientos en tierra firme, la fundación de la Villa Rica, y solicita la autorización real para que se lo tengan por justicia mayor y capitán general de la armada. La más notable por su valor histórico y literario es la segunda (1520), en la cual narra el desembarco en México y las luchas que condujeron a la toma de Tenochtitlan y su pérdida posterior. La tercera, cursada desde Coyoacán (15 de mayo de 1522) relata la retirada de Tenochtitlan en la noche triste, los preparativos del asalto y la toma de la ciudad en una gesta de dramatismo homérico. En la cuarta (Tenochtitlan, 15 de octubre de 1524) refiere esencialmente la organización del estado conquistado y su intención de continuar ocupando los territorios anexos. La quinta carta (Tenochtitlan, 3 de septiembre de 1526), narra su penosa expedición a las Ibueras (Honduras), se extiende en consideraciones sobre el juicio de residencia que estaba por hacer y se interna en pormenores menos épicos, como gastos, sinsabores y pobreza familiar. El contenido de las cartas es complejo y en ellas se transparenta Cortés, mezcla de místico, héroe y artista. Estas cartas, que fueron publicadas mucho más tarde, son documentos muy interesantes por las revelaciones que contienen y permiten apreciar el complejo mundo espiritual de este conquistador, hombre capaz de oscilar en su comportamiento entre la dulzura comprensiva y la represalia ejemplarizadora más cruel. La edición completa de las cinco cartas es de 1868.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1948, '847291738X', 'La Europa de Hitler', 1, '1985', 463, 'Hitler''s Europe', 'media/core/847291738X.jpg', 1, '2023-05-01 10:28:35.326607', '2023-05-01 10:28:35.326607', 1119, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '2', 329, 'El primero se adentra en aspectos claves de Alemania: la estructura política de la Europa de Hitler, la estructura económica de la Europa de Hitler e Italia. En el segundo de los volúmenes se describe la situación de los países ocupados: Francia, a la que ocupa un gran parte del segundo volúmen (la Francia de Vichy, el movimiento francés libre, desde 1940-1942), los países ocupados en la Europa Occidental (Bélgica, Holanda, Luxemburgo, Dinamarca, Noruega), los países ocupados y satélites de Europa Oriental (Polonia, Ostland, Finlandia, la Checoslovaquia desmembrada, Hungría, Rumania y Bulgaria, Ucrania, Albania, Grecia,...)', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1949, '8472917967', 'Los exiliados románticos (Bakunin, Herzen, Ogarev)', 1, '1985', 294, 'The Romantic Exiles', 'media/core/8472917967.jpeg', 1, '2023-05-01 10:31:36.808750', '2023-05-01 10:31:36.808750', 434, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '16', 329, 'A mediados del siglo XIX, numerosos rusos, liberales y anarquistas, se exiliaron y se esparcieron por Europa en pequeños grupos, reuniéndose episódicamente para discutir sus teorías políticas y publicar clandestinas llamadas a la revolución que debía poner fin a la autocracia zarista. Artistas de la conspiración y de la intriga, vivieron intensamente sus dramáticas existencias, bajo la amenaza más o menos presente del servicio secreto ruso. Algunos, como Aleksandr Herzen, fueron hombres de elevada estatura intelectual que han sido posteriormente admitidos en el panteón marxista; otros, como Bakunin, fueron grandes agitadores, de incalculable valía en la primera etapa de la revolución, pero muy probables candidatos a una ejecución sumaria en la segunda. En la mayoría de ellos, el fervor revolucionario iba unido a un incorregible romanticismo: fueron, en primer lugar, soñadores y poetas, acólitos de Rousseau y de George Sand, hijos y víctimas de la Edad Romántica que nunca abandonaron. En este libro inhabitual -una acertada combinación de historia y anécdota- se desenmarañan algunas de las turbulentas historias de aquellos exiliados románticos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1950, '8472917398', 'Orígenes de la Nación Española. El Reino de Asturias', 1, '1985', 354, NULL, 'media/core/8472917398.jpg', 1, '2023-05-01 10:35:32.993625', '2023-05-01 10:35:32.993625', 1120, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '3', 329, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1951, '8472917865', 'Sobre el nombre y el quién de los españoles', 1, '1985', 284, NULL, 'media/core/8472917865.jpg', 1, '2023-05-01 10:38:13.484352', '2023-05-01 10:38:13.484352', 1121, 11, 6, 5, 'Biblioteca de la Historia', '', '07_03', '8', 329, 'Américo Castro falleció repentinamente en julio de 1972. Su última tarea fue preparar la presente edición que se publicó con carácter de póstuma. La obra muestra hasta qué punto fue vital para él la defensa de una tesis que no era ciencia muerta, sino ideario que tenía por fin último el salvamento de España. Porque cuando se discute el origen de un vocablo, el que sirve para nombrar a los habitantes de España, no se trata de un bizantinismo sólo importante para lingüistas. Es todo el ser de España lo que se debate', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1952, '8472917401', 'Brevísima relación de la destrucción de las Indias', 1, '1985', 150, NULL, 'media/core/8472917401.jpeg', 1, '2023-05-01 10:40:53.423831', '2023-05-01 10:40:53.423831', 1122, 45, 6, 5, 'Biblioteca de la Historia', '', '07_03', '4', 329, 'Fray Bartolomé de las Casas fue considerado el responsable de la leyenda negra sobre la colonización española en América por su vehemente y polémica denuncia de los abusos cometidos contra los indios. La figura de este autor y sus denuncias de los abusos y atropellos cometidos contra los indios y sus propuestas de solución o "remedios", se entienden como precursores de la moderna antropología política y del derecho colonial', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1954, '9788884472946', 'Ciudades  X formas: una nueva mirada hacia el proyecto urbanístico', 1, '2007', 382, NULL, 'media/core/9788884472946.jpg', 1, '2023-05-02 06:21:52.832985', '2023-05-02 06:21:52.832985', 1123, NULL, 6, 5, NULL, '', '06_07', NULL, 391, 'Ciudades: 10 Formas - Una nueva mirada hacia el proyecto urbanístico'', recoge los resultados de varios seminarios de investigación docente llevados a cabo durante tres años dentro del departamento de Planificación y Diseño Urbano en la universidad de Harvard. Dichos seminarios se enfocaron en el desarrollo de una taxonomía pedagógica que facilitara la comprensión de los métodos y herramientas con los cuales los diseñadores dan forma a las ciudades y los territorios abiertos en la actualidad. En las tres últimas décadas,la forma como los diseñadores proyectan la ciudad ha dado un giro significativo. Estas nuevas formas de intervenir en el entorno construido están siendo aplicadas en contextos múltiples con una gran variedad de culturas, escalas e intensidades. Por otro lado, la noción de que el suelo urbano puede ser rehabilitado con éxito se está expandiendo rápidamente y la naturaleza innovadora de este tipo de intervención está creando espacios con una calidad urbana sin precedentes.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1955, '978113517721', 'Matador CH. La mente del artista', 1, NULL, 1, NULL, 'media/core/978113517721.jpg', 1, '2023-05-02 06:29:58.265895', '2023-05-02 06:29:58.265895', NULL, 43, NULL, 5, NULL, '', '06_07', NULL, 392, '¿Qué se cuece en la cabeza de un artista? Este número de Matador es un intento de descubrir el secreto de la creación. Un viaje al interior del artista. A su cerebro, al corazón, al genio, al carácter, a la pasión. Un intenso recorrido en el que se ha involucrado el pintor Eduardo Arroyo, que en esta ocasión juega a ser redactor jefe de la revista.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1956, '8402039618', 'La Odisea', 1, '1974', 446, NULL, 'media/core/8402039618.jpg', 1, '2023-05-02 06:33:02.118955', '2023-05-02 06:33:02.118955', 1124, 1, 6, 5, 'Obras Inmortales', '', '07_03', NULL, 126, '"La Odisea", del poeta griego Homero, es uno de los poemas épicos más importantes de Occidente. La historia narra el viaje de regreso del héroe Odiseo a su patria, la isla de Ítaca, tras su participación en la guerra de Troya. Su travesía estará llena de peligros y aventuras. "La Odisea" es una metáfora del viaje que es la vida para todos nosotros; de ahí que sea un clásico universal.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1957, 'M16425', 'Los trabajadores del mar', 1, '1965', 460, NULL, 'media/core/M16425.jpg', 1, '2023-05-02 06:36:40.725889', '2023-05-02 06:36:40.725889', 1125, 1, 6, 5, 'Colección biblioteca Edaf', '', '07_03', NULL, 366, 'Obra de madurez, publicada en 1866, esta novela mantiene esencialmente los temas de la poética de Víctor Hugo, como son los fuertes contrastes de pasiones y de situaciones, el ideal de una generosidad fatalmente destinada al sacrificio (la del pescador Gilliat en este caso) y la intensa alternancia de claros y sombras. Pero al autor los renueva llenándolos de un contenido nuevo y actualísimo en su época, pues plantea las primeras afirmaciones del mecanicismo y el sentido de la lucha victoriosa del hombre sobre la naturaleza. Los trabajadores del mar, que arranca casi de un tema de leyenda y termina en una atmósfera de pesadilla, en la sombría transparencia de una gruta submarina.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1958, 'B5209', 'Miguel Strogoff', 1, '1972', 282, NULL, 'media/core/sin-imagen_j6Dn2Jm.jpg', 1, '2023-05-02 06:40:39.283260', '2023-05-02 06:44:02.800677', 537, 1, 6, 5, 'Grandes Aventuras', '', '07_03', NULL, 393, '"Y no volverá a ver las cosas de la tierra". Era el versículo del Corán que Miguel Strogoff oyó antes de que la hoja incandescente de un sable al rojo vivo pasara delante de sus ojos. Desde ese momento culminante, el lector, ya irremesiblemente atrapado, acompaña al correo del zar por las estepas siberianas, compartiendo su tesón, sus dudas, tal vez la superstición de aquella liebre de mal agüero que se cruzó en el camino, y acaso su secreto. Novela de aventuras en estado puro, donde el viaje argumental del protagonista se convierte en viaje iniciático del joven, añade la virtud de aliviar la tensión narrativa con las ocurrencias humorísticas de los periodistas Blount y Jolivet.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1959, 'B10114', 'Un capitán de quince años', 1, '1972', 288, NULL, 'media/core/sin-imagen_cGSk2ML.jpg', 1, '2023-05-02 06:43:45.004473', '2023-05-02 06:43:45.004473', 537, 1, 6, 5, 'Grandes Aventuras', '', '07_03', NULL, 393, 'Durante su larga travesía hacia América, el bergantín Pilgrim pierde a toda su tripulación en un desgraciado accidente. De entre los pasajeros que quedan a bordo, el joven Dick Sand es el único que puede asumir el mando del barco. Sin experiencia y sin marinos competentes a su alrededor, el viaje para Dick y el resto de los pasajeros se convertirá en una auténtica odisea llena de peligros.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1960, 'M20051', 'Nuestra Señora de París', 1, '1971', 487, NULL, 'media/core/sin-imagen_IXJ5hdl.jpg', 1, '2023-05-02 06:57:12.941320', '2023-05-02 06:57:12.941320', 1125, 1, 6, 5, 'Colección biblioteca Edaf', '', '07_03', NULL, 366, 'En el París del siglo XV, con sus sombrías callejuelas pobladas por desheredados de la fortuna y espíritus atormentados, la gitana Esmeralda, que predice el porvenir y atrae fatalmente a los hombres, es acusada injustamente de la muerte de su amado y condenada al patíbulo. Agradecido por el apoyo que en otro tiempo recibió de ella, Quasimodo, campanero de Nuestra Señora, de fuerza hercúlea y cuya horrible fealdad esconde un corazón sensible, la salva y le da asilo en la catedral." Nuestra Señora de París" ha dado lugar a numerosos libretos de ópera y a varias versiones cinematográficas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1961, 'B54112-1', 'Las mil y una noches', 1, '1972', 860, NULL, 'media/core/sin-imagen_r7yvkQU.jpg', 1, '2023-05-02 07:14:43.170893', '2023-05-02 07:14:43.170893', 1127, 44, 6, 5, NULL, '', '07_03', 'Tomo I', 394, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1962, 'B54112-2', 'Las mil y una noches', 1, '1972', 865, NULL, 'media/core/sin-imagen_sXZaHXt.jpg', 1, '2023-05-02 07:16:05.014842', '2023-05-02 07:16:05.014842', 1127, 44, 2, 5, NULL, '', '07_03', 'Tomo II', 394, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1963, '8474612918', 'La Ilíada', 1, '1984', 368, NULL, 'media/core/8474612918.jpg', 1, '2023-05-02 07:18:39.745074', '2023-05-02 07:18:39.745074', 1124, 1, 2, 5, NULL, '', '07_03', NULL, 234, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1964, '8439540094', 'Arte de amar / Amores', 1, '1995', 265, NULL, 'media/core/8439540094.jpeg', 1, '2023-05-02 07:22:04.930457', '2023-05-02 07:24:18.031482', 774, 2, 6, 5, 'Los Clásicos de Grecia y Roma', '', '07_03', NULL, 7, 'El arte de amar se compone de tres libros:el primero describe a los hombres, los lugares donde pueden encontrar a las mujeres libertas y la forma de agradarlas. En el segundo da consejos para conservar el amor conquistado de la mujer amada; estos relatos se presentan en tono didáctico, pero rodeados de ironía y de parodia alegre. El tercer libro está dedicado a las mujeres, aconsejándoles en la forma de agradar a los hombres y la manera de mantener su amor por largo tiempo. En esta obra Ovidio toma muchos de los elementos propios de poetas griegos y latinos, anteriores y contemporáneos a él.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1965, '8439540086', 'La Odisea', 1, '1995', 409, NULL, 'media/core/8439540086.jpeg', 1, '2023-05-02 07:23:58.593162', '2023-05-02 07:23:58.593162', 1124, 1, 6, 5, 'Los Clásicos de Grecia y Roma', '', '07_03', NULL, 7, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1966, '9788498150124', 'La Regenta', 1, '2005', 732, NULL, 'media/core/9788498150124.jpeg', 1, '2023-05-02 07:26:45.630682', '2023-05-02 07:26:45.630682', 611, 1, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'La Regenta es la gran novela del XIX español. Las pasiones, odios, celos y obsesiones que despierta Ana Ozores en Vetusta -trasunto de Oviedo- sirve a "Clarín" para llevar a cabo una implacable radiografía de la burguesía española finisecular. En Vetusta, capital de provincia, Ana Ozores, se casa con el antiguo Regente de la Audiencia de la ciudad, Víctor Quintanar, hombre bondadoso pero maniático y mucho mayor que ella.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1967, '9788498150438', 'Vuelva usted mañana y otros artículos', 1, '2005', 174, NULL, 'media/core/9788498150438.jpeg', 1, '2023-05-02 07:33:08.921046', '2023-05-02 07:33:08.921046', 779, 44, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'En este artículo se conocerá la historia de un francés que decide ir a España a realizar unos buenos negocios pero, todo lo que le espera por descubrir le hará que reflexione y tenga una opinión de los españoles distinta a la que ya tenía anteriormente.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1968, '9788498150087', 'Rimas y Leyendas', 1, '2005', 159, NULL, 'media/core/9788498150087.jpeg', 1, '2023-05-02 07:35:15.522889', '2023-05-02 07:35:15.522889', 1128, 4, 2, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'Las dos mejores obras del gran poeta del romanticismo españolINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1969, '9788498150001', 'Historia de la vida del Buscón', 1, '2005', 170, NULL, 'media/core/9788498150001.jpeg', 1, '2023-05-02 07:37:32.809081', '2023-05-02 07:37:32.809081', 763, 1, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'Sinopsis La Historia de la vida del Buscón, indiscutible cima del arte literario español, es un polémico ejemplo de novel picaresca. En ella, Quevedo relata la peripecia vital del pícaro don Pablos de Segovia, desde su infancia a la proyectada fuga a Indias con que termina la obra. Entre estos dos polos se sitúan una serie de aventuras, casi siempre catastróficas, en las que el personaje fracasa constantemente en su búsqueda de estabilidad económica y social, y sus fingimientos de nobleza son desenmascarados sin cesar. Obra amena y difícil, «El Buscón» destaca por su caricaturesca descripción de una sociedad desintegrada y por su espléndida creación verbal, modelo de ingenio y de experimentación lingüística.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1970, '9788498150377', 'Fábulas', 1, '2005', 206, NULL, 'media/core/9788498150377.jpg', 1, '2023-05-02 07:41:26.475949', '2023-05-02 07:41:26.475949', 1129, 44, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', 'Con Félix Maria de Samaniego : https://es.wikipedia.org/wiki/F%C3%A9lix_Mar%C3%ADa_de_Samaniego');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1971, '9788498150421', 'Don Álvaro o la fuerza del sino', 1, '2005', 141, NULL, 'media/core/9788498150421.jpeg', 1, '2023-05-02 07:44:20.739686', '2023-05-02 07:44:20.739686', 1130, 41, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '"Don Álvaro o la fuerza del sino", estrenada en 1835, es la obra más conocida del duque de Rivas, considerada por muchos críticos como la obra que marca el triunfo del Romanticismo en España. Su protagonista, un adinerado indiano procedente de una familia caída en desgracia, ha de mantener a escondidas su relación amorosa con Leonor, una joven aristócrata, puesto que su padre, el marqués de Calatrava, no considera a Don Álvaro digno de su linaje. Los dos enamorados deciden escapar, con tan mala fortuna que son sorprendidos por el marqués, que resulta muerto por accidente. Este hecho es el desencadenante de una serie de dramáticos sucesos que parecen guiar inevitablemente a todos los personajes a su trágico destino. El éxito de esta obra radica en la acertada combinación de elementos, tanto formales como temáticos, que sentaron las bases del drama romántico que luego reproducirán tantas otras obras. El amor, el honor y el sino son los ejes que vertebran esta historia plagada de venganza y de muerte.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1972, '9788498150155', 'Historia del corazón', 1, '2005', 159, NULL, 'media/core/9788498150155.jpeg', 1, '2023-05-02 07:48:01.993734', '2023-05-02 07:48:01.993734', 1131, 4, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'Cuando hablamos del amor en poesía, muy útil nos es la dicotomía entre amor idealizado y amor erótico. En uno, el sujeto forma para sí la imagen de una mujer benéfica y de corporalidad reducida. El otro, trata del contacto corporal y la pasión, tan edificante como destructiva, que lo alimenta. Pero al hablar de la poesía de Vicente Aleixandre, la dicotomía no es igual: erotismo e idealización son acaso causa y anhelada consecuencia, respectivamente. El amor se asume, entonces, como condición humana en todas sus posibilidades, donde los bellos labios pueden ser como espadas. Esta perspectiva característica de la obra de Aleixandre encuentra su realización más feliz en Historia del corazón (1954).INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1973, '9788498150148', 'La casa de Bernarda Alba', 1, '2005', 126, NULL, 'media/core/9788498150148.jpg', 1, '2023-05-02 07:50:12.491010', '2023-05-02 07:50:12.491010', 766, 41, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'La casa de Bernarda Albaconstituye un exponente más de la capacidad de Federico García Lorca para aunar la tradición y la vanguardia por medio de un teatro simbólico de índole muy personal que le sitúa entre los valores más destacados del canon internacional.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1974, '9788498150131', 'Libro de Buen Amor', 1, '2005', 284, NULL, 'media/core/9788498150131.jpg', 1, '2023-05-02 07:52:53.633426', '2023-05-02 07:52:53.633426', 901, 4, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1975, '9788498150049', 'El alcalde de Zalamea', 1, '2005', 127, NULL, 'media/core/9788498150049.jpeg', 1, '2023-05-02 07:54:16.516672', '2023-05-02 07:54:16.516672', 768, 41, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1976, '9788498150414', 'La vida es sueño', 1, '2005', 142, NULL, 'media/core/9788498150414.jpeg', 1, '2023-05-02 07:56:27.094309', '2023-05-02 07:56:27.094309', 768, 41, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1977, '9788496390980', 'La colmena', 1, '2005', 291, NULL, 'media/core/9788496390980.jpg', 1, '2023-05-02 07:58:24.048986', '2023-05-02 07:58:24.048986', 832, 1, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'La colmena, seguramente la obra más valiosa de Camilo José Cela, es un testimonio fiel de la vida cotidiana en las calles, cafés y alcobas de aquel Madrid de 1943, pero es también una amarga crónica existencial. Un aire de rutina y fatalidad ha invadido la conciencia de las gentes. Todos creen que las cosas pasan porque sí y que nada tiene remedio. Entre la abigarrada multitud se oye el solitario zumbido de muchos seres confusos y a la deriva. Como es habitual en su obra, Cela presenta la vida española sin piedad, con agria ironía y humorismo atroz. Sin embargo, de vez en cuando, un soplo compasivo alivia la áspera y dolorida realidad. Eduardo Alonso, que ha preparado esta edición, es novelista y profesor de literatura.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1978, '9788496390997', 'El lazarillo de Tormes', 1, '2005', 125, NULL, 'media/core/9788496390997.GIF', 1, '2023-05-02 07:59:55.165664', '2023-05-02 07:59:55.165664', 1127, 1, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1979, '9788498150292', 'La barraca', 1, '2005', 206, NULL, 'media/core/9788498150292.jpeg', 1, '2023-05-02 08:02:46.566441', '2023-05-02 08:02:46.566441', 1132, 1, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'Sobre las tierras del tío Barret, que se atrevió a romper las cadenas y a cortar la cabeza del amo, don Salvador, con la consiguiente ruina de su familia, pesa una maldición. Convertidas en símbolo de la lucha contra los terratenientes, nadie debe cultivarlas. La hostilidad se desata contra un forastero, Batiste Borrull, que, con el sueño de sacar a su familia adelante, decide arrendarlas, desatando así una tempestad de odio y resentimiento que culmina trágicamente. En la mejor tradición de la novela naturalista, Vicente Blasco Ibáñez (1867-1928) se demora en LA BARRACA (1898) en el análisis de la psicología colectiva y achaca la crueldad de los personajes a los bajos instintos y a la brutalidad del medio en que viven. En estas circunstancias adversas, la lucha del maestro, don Joaquín, para educar a sus alumnos, resulta infructuosa.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1980, '9788498150223', 'Antología poética', 1, '2005', 157, NULL, 'media/core/9788498150223.jpeg', 1, '2023-05-02 08:04:13.506650', '2023-05-02 08:04:13.506650', 763, 4, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1981, '9788498150230', 'El romancero español', 1, '2005', 239, NULL, 'media/core/9788498150230.jpg', 1, '2023-05-02 08:06:16.357084', '2023-05-02 08:06:16.357084', 1127, 4, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'Los romances más viejos que conocemos datan del siglo XV, aunque a menudo cuentan epopeyas de los siglos anteriores. Son poemas cortos épico-líricos que se cantaban acompañados de música. Los juglares los sacaron de la corte y los hicieron llegar al pueblo, que los modificó a su gusto y repitió en lenguaje llano. Ensalzaban figuras nacionales como Bernardo del Capio peleando por la libertad de su padre, recordaban gestas carolingias, o informaban de hechos que interesaba propagar como la conquista de Granada.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1982, '9788498150216', 'Sonata de primavera', 1, '2005', 123, NULL, 'media/core/9788498150216.jpeg', 1, '2023-05-02 08:08:46.579077', '2023-05-02 08:08:46.579077', 1133, 1, 6, 5, 'Clásicos latinos', '', '07_03', NULL, 264, 'Estas "páginas son un fragmento de las Memorias amables que ya muy viejo empezó a escribir en la emigración el Marqués de Bradomín. Un Don Juan admirable, ¡El más admirable tal vez!, era feo, católico y sentimental". Así define don Ramón del Valle-Inclán sus Sonatas, en las que, dentro de la trayectoria del Modernismo y desde una perspectiva absolutamente original, contrahace el viejo mito. El movimiento modernista trae consigo una visión artística de la vida, una ideología religiosa en la que el amor y lo profano se revisten de formas sagradas y, en contraste con el realismo burgués, exalta lo aristocrático refinado y cosmopolita. El protagonista de las Sonatas es un arquetipo de nueva cultura. Difícilmente podría hallarse mejor introductor y compañero de lectura de estas dos Sonatas, donde vamos del ambiente primaveral de la Italia del norte a la exuberancia del estilo mexicano, que Pedro Gimferrer. Escritor y académico de la Real Academia Española de la Lengua, es uno de los primeros especialistas en el Modernismo, e introductor, a la vez, de una corriente neomodernista en la poesía hispánica.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1983, '9788498150209', 'Tres sombreros de copa', 1, '2005', 123, NULL, 'media/core/9788498150209.jpeg', 1, '2023-05-02 08:11:26.379126', '2023-10-02 06:56:46.149511', 1134, 41, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1984, '9788498150193', 'Pepita Jiménez', 1, '2005', 190, NULL, 'media/core/9788498150193.jpeg', 1, '2023-05-02 08:14:17.055107', '2023-05-02 08:14:17.055107', 1135, 1, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'La obra cumbre de Juan Varela y una de las más importantes de la literatura española.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1985, '9788498150353', 'Garcilaso de la Vega y Juan Boscán', 1, '2005', 287, NULL, 'media/core/9788498150353.jpeg', 1, '2023-05-02 08:17:15.413454', '2023-05-02 08:17:15.413454', 1136, 4, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'Con Juan Boscán: https://es.wikipedia.org/wiki/Juan_Bosc%C3%A1n', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1986, '9788498150407', 'Paltero y yo', 1, '2005', 190, NULL, 'media/core/9788498150407.jpeg', 1, '2023-05-02 08:20:10.761206', '2023-05-02 08:20:10.761206', 1137, 4, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '"Platero es pequeño, peludo, suave; tan blando por fuera, que se diría todo de algodón". Platero es un burrito, pero además es la encarnación del compañero inseparable, el amigo ideal. Él nos acompaña en este viaje a traves de los recuerdos del autor llenos de sensaciones, colores, e imágenes. J. R. Jimenez nos cuenta historias de su pueblo natal a traves del amor a Platero, su burro, y ese amor trasciende a todo lo que ve, la naturaleza, el camino, los aromas, los chiquillos y sus juegos y su inocencia, la gente sencilla en su día a día, la vida; y con su lenguaje sencillo y al mismo tiempo poetico, lleno de metáforas, nos hacen sentir esas vivencias como propias. Descubre esta narración lírica que contribuyó sobremanera a que su autor ganara el Premio Nobel de Literatura en 1956 por el conjunto de su obra.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1987, '9788498150391', 'Cancionero y romancero de ausencias', 1, '2005', 206, NULL, 'media/core/9788498150391.jpg', 1, '2023-05-02 08:23:02.446133', '2023-05-02 08:23:02.446133', 100, 47, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, 'Un estremecedor testimonio del final de una poética y de un hombre, que es también el final de una historia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1988, '9788498150384', 'San Juan de la Cruz y Santa Teresa de Jesús', 1, '2005', 1, NULL, 'media/core/9788498150384.jpeg', 1, '2023-05-02 08:24:44.324196', '2023-05-02 08:24:44.324196', NULL, 4, 6, 5, 'Clásicos españoles', '', '07_03', NULL, 264, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1989, '9788467238884', 'La noche de los tiempos', 1, '2009', 829, NULL, 'media/core/9788467238884.jpeg', 1, '2023-05-02 16:27:48.856509', '2023-05-02 16:27:48.856509', 1138, 1, 6, 5, NULL, '', '07_03', NULL, 14, 'Una gran novela de amor ambientada en el año previo al estallido de la guerra civil española.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1990, '9788422688181', 'Sefarad', 1, '2001', 501, NULL, 'media/core/9788422688181.jpg', 1, '2023-05-02 16:30:22.079156', '2023-05-02 16:30:22.079156', 1138, 1, 6, 5, NULL, '', '07_03', NULL, 395, 'Cada mañana despiertas creyendo ser el mismo que la noche anterior, pero no eres una sola persona y no tienes una sola historia. Ésa es la experiencia por la que tienen que atravesar los habitantes de esta novela de novelas, inquietante y conmovedora: por una enfermedad, por un accidente, por una hermosa historia de amor, por una guerra y, sobre todo, por pertenecer a una minoría perseguida, casi todos ellos se ven obligados a cruzar una peligrosa frontera que los ponga a salvo de la violencia y de la irracionalidad que han asolado el siglo XX. Vigorosa denuncia contra toda la marginación, Sefarad es una sabia mezcla de personajes reales (Kafka, Primo Levi, Willi Münzenberg...) y personajes ficticios, de tragedias e ironías, de odios y afectos, al mismo tiempo que de géneros literarios: cada uno de los relatos entrelazados que componen esta novela enriquece y profundiza los anteriores. Antonio Muñoz Molina nos propone una sensible aproximación al mundo de los excluidos, a su intensa capacidad de amar, con la sabiduría de una prosa apasionada que sabrá seducirnos al hablarnos de aquello en lo que no nos atrevemos a pensar.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1991, '3622-63', 'Ben-Hur', 1, '1964', 123, NULL, 'media/core/3622-63.jpg', 1, '2023-05-02 16:38:29.302233', '2023-05-02 17:51:23.613588', 1139, 48, 6, 5, 'Selecciones Juveniles', '', '07_05', NULL, 396, 'La trama básica se desarrolla entorno a la vida de Judá Ben-Hur, un coetáneo y compatriota del Nazareno. Pese a su amistad con el romano Messala, el antagonismo entre estos personajes y un desafortunado accidente llevan a la acaudalada familia de los Hur a la desgracia. El rico judío fue hecho galeote en tanto que la situación de su madre y hermana queda ignorada. El destino hace que, tras una batalla contra los piratas, Ben-Hur se convierta en el hijo adoptivo del noble romano Quinto Arrio. Sin embargo, un objetivo secreto lo devuelve a Oriente, a Antioquía, donde se cruzarán de nuevo los caminos. Con la ayuda del viejo Simónides y el jeque árabe Ilderim, se enfrenta a Messala y consigue su venganza en una carrera de cuádrigas. Después se dirigen a Jerusalén, donde se esperaba la aparición del Mesías.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1992, '3008-63', 'Aventuras de Tom Sawyer', 1, '1963', 124, NULL, 'media/core/3008-63.jpg', 1, '2023-05-02 16:41:58.496763', '2023-05-02 17:51:14.055227', 622, 48, 6, 5, 'Selecciones Juveniles', '', '07_05', NULL, 396, 'Alguien ha dicho queLas aventuras de Tom Sawyer es, ante todo, un libro de memorias. Y, en efecto, el relato de las cosas que le suceden a Tom Sawyer en esa pequeña ciudad a orillas del Mississippi bien puede ser una rememoración de la niñez de Mark Twain. A través de los ojos de sus personajes, el autor nos ofrece la visión de una doble realidad: la del mundo infantil, primitivo, que el lector adulto ya ha perdido, y la del mundo adulto, confuso e ilógico, asentado en unas convenciones que no resultan ser preferibles en ningún aspecto a los códigos de valor de un niño. Es esta una novela que no olvidará ningún lector joven y que hará recordar y sonreír al adulto.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (1993, '2532-63', 'Mis cuentos de hadas', 1, '1963', 62, NULL, 'media/core/2532-63.jpg', 1, '2023-05-02 16:44:38.999204', '2023-05-02 16:44:38.999204', NULL, 48, 6, 5, NULL, '', '07_05', 'Volumen 7', 396, '', '');
