INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2015, '9788422677895', 'Chocolate', 1, '1998', 440, 'Chocolat', 'media/core/9788422677895.jpeg', 1, '2023-05-03 07:31:54.350919', '2023-05-03 07:31:54.350919', 1142, 1, 6, 5, NULL, '', '07_05', NULL, 72, 'El chocolate puede ser mucho más que un placer para los sentidos. A veces, una pecaminosa tentación y otras, una forma de acercar los sueños a la realidad. Vianne Rocher y su hija Anouk llegan al pueblo de Lansquenet para abrir una chocolatería frente a la iglesia. Vianne es alegre y desenfadada, sensual y misteriosa y parece poseer extraños dones.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2016, '9788466657730', 'Felipe', 1, '2015', 772, NULL, 'media/core/9788466657730.jpeg', 1, '2023-05-03 07:36:01.613003', '2023-05-03 07:36:01.613003', 1143, 16, 6, 5, NULL, '', '07_05', NULL, 8, 'Del creador de las series Isabel y El Ministerio del Tiempo, llega la gran novela histórica sobre Felipe II. Su padre le enseñó a ser Emperador. Las mujeres le enseñaron lo que era la vida.Esta es la historia de un niño que no eligió ser hijo de quien era. Que perdió a su madre con doce años y que veía tan poco a su padre que apenas recordaba su cara. Es la historia de un joven que a los dieciséis años gobernaba España por orden del Emperador. De un hombre creyente y supersticioso, marcado por las mujeres que le rodearon, seductor y desconfiado, dueño de una gran sensibilidad y capaz, al mismo tiempo, de las mayores crueldades con sus enemigos.Felipe no eligió ser hijo de Carlos I de España y V de Alemania. Pero lo fue. Ésta es la historia de un hombre que heredó el mundo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2017, '9788401342158', 'El juego de Ripper', 1, '2014', 475, NULL, 'media/core/9788401342158.jpg', 1, '2023-05-03 07:38:43.226125', '2023-05-03 07:38:43.226125', 69, 1, 6, 5, NULL, '', '07_05', NULL, 17, 'Tal como predijo la astróloga más reputada de San Francisco, una oleada de crímenes comienza a sacudir la ciudad. En la investigación sobre los asesinatos, el inspector Bob Martín recibirá la ayuda inesperada de un grupo de internautas especializados en juegos de rol, Ripper.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2018, '9788467263008', 'Y de repente, Teresa', 1, '2014', 559, NULL, 'media/core/9788467263008.jpg', 1, '2023-05-03 07:41:23.415691', '2023-05-03 07:41:23.415691', 215, 16, 6, 5, NULL, '', '07_05', NULL, 107, 'Descubriremos, poco a poco y de manera apasionante, los entresijos de la Inquisición, sus métodos y sus procedimientos. Y con su reconocida destreza como novelista nos hará viajar a aquella época y sentir que hemos estado allí realmente.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2019, '9788467264371', 'Perfidia', 1, '2015', 773, 'Perfidia', 'media/core/9788467264371.jpeg', 1, '2023-05-03 07:44:08.513061', '2023-05-03 07:44:08.513061', 1144, 1, 6, 5, NULL, '', '07_05', NULL, 211, 'PERFIDIAINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2020, '978408087465', 'De la alpargata al Seiscientos', 1, '2010', 410, NULL, 'media/core/9788408087465.jpg', 1, '2023-05-03 07:46:43.627035', '2023-05-03 07:46:43.627035', 26, 15, 6, 5, NULL, '', '07_05', NULL, 7, 'De la alpargata al seiscientos es la continuación de la trilogía formada por Una historia de la guerra civil que no va a gustar a nadie y Los años del miedo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2021, '8422645246', 'Camelot / El libro de Merlín', 1, '1977', 844, 'The Once and Future King / The Book of Merlyn', 'media/core/8422645246.jpeg', 1, '2023-05-03 07:53:43.709339', '2023-05-03 07:53:43.709339', 1145, 1, 6, 5, NULL, '', '07_05', NULL, 76, 'Una serie de pr#cticas m#gicas, debidas a las artes de encantamiento de Merl#n, servir#n a un ni#o llamado Verruga para alcanzar el fabuloso destino que le aguarda: convertirse en el rey Arturo. Una vez arrancada la espada Excalibur, ocupa el trono e inicia sus primeras batallas contra aquellos que se resisten a aceptar su poder#o. Su boda con Ginebra, su amistad con el legendario Lanzarote del Lago y los amores de este con la reina se convierten en el punto central de esta #pica narraci#n de aventuras y personajes medievales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2022, '9788477223368', 'Espejismo', 1, '1989', 352, 'Mirage', 'media/core/9788477223368.jpg', 1, '2023-05-03 07:56:30.151368', '2023-05-03 07:56:30.151368', 658, 13, 6, 5, NULL, '', '07_05', NULL, 9, 'La malvada Calthar, señora de los habitantes del mar, acérrimos enemigos de Haven, provocó aquella terrorífica doble marea que engulló gran parte de la ciudad. Sus soberanos viven sumidos en tribulaciones y para paliarlas, Simorh, la reina, recurre a todas sus invocaciones mágicas y consigue arrancar del limbo al joven Kyre, reencarnación del Buscador del Sol, para que sea su paladín. Una noche, Kyre, impulsado por misteriosas fuerzas, acude a las ruinas del templo donde cobro vida y allí ve a una sugestiva joven que desaparece bajo las aguas. Al mismo tiempo, Gamora, hija de los soberanos de Haven, es raptada y Kyre tendrá que sumergirse también en las aguas para encontrarla. De ese modo descubre que la enigmática joven es Tallian, hija adoptiva de Calthar y reencarnación, a su vez, de su propia esposa en tiempos remotos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2023, '9788422680086', 'Código Génesis', 1, '1999', 510, 'The Genesis Code', 'media/core/9788422680086.jpeg', 1, '2023-05-03 07:59:42.291643', '2023-05-03 07:59:42.291643', 1146, 22, 6, 5, NULL, '', '07_05', NULL, 15, 'Una llamada telefónica despierta a Joe Lassiter para comunicarle que la única familia que le quedaba acaba de morir; su hermana y su joven sobrino han sido víctimas de un incendio. Pero Lassiter no tarda en averiguar que las muertes no han sido accidentales, que alguien los asesinó brutalmente mientras dormían justo antes de incendiar la casa. La policía no tiene pistas, aunque lo que sí sabe Lassiter es que, sea quien sea el asesino, ha ido a dar con el hombre equivocado. Dueño de una moderna empresa de investigación, no hay rastro que se le oculte ni código que se le resista. Y ahora tiene una misión muy personal que llevar a cabo: descubrir quien y por que ha asesinado a una mujer y un niño inocentes. Poco a poco, una serie de crímenes identicos se va destapando y la intriga se vuelve más y más asfixiante. La búsqueda de Lassiter se convierte así en una lucha desesperada en pos de la verdad que nos conduce a un sorprendente y explosivo final.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2024, '9788422681229', 'La Torre de los alquimistas', 1, '1999', 439, 'Die Burg der Alchimisten', 'media/core/9788422681229.jpeg', 1, '2023-05-03 08:02:54.466679', '2023-05-03 08:02:54.466679', 1147, 16, 6, 5, NULL, '', '07_05', NULL, 74, 'Alemania, 1523. Edgar, un espía del arzobispado, se infiltra en la fortaleza de Schönburg para investigar las prácticas alquimistas del conde Frowin. Las sospechas le conducen de inmediato a una torre inexpugnable donde se utilizan cuerpos humanos como ingredientes de una fórmula secreta que convierte el plomo en oro. Sin embargo, las pesquisas se complican cuando el conde aparece asesinado en el interior de una habitación cerrada por dentro. Un hecho inexplicable que desbarata los planes del investigador. Hasta llegar a la resolución del enigma, el espía se verá involucrado en un complot en el que la lucha por el dominio político, los intereses eclesiásticos y las oscuras artes de la alquimia se combinan para llevar a cabo la mayor intriga del Renacimiento.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2025, '9788467231373', 'Antonio B. el Ruso, ciudadano de tercera', 1, '2007', 633, NULL, 'media/core/9788467231373.jpeg', 1, '2023-05-03 08:05:15.575079', '2023-05-03 08:05:15.575079', 1148, 1, 6, 5, NULL, '', '07_05', NULL, 114, 'Basada en hechos reales, Antonio B. el Ruso, ciudadano de tercera es la narración en primera persona de la vida de un hombre desde su nacimiento en Las Cabreras (León) a principios de los años treinta hasta los años setenta, acabado el régimen franquista. Antonio B. arrastra una existencia extremadamente dura, en la que tiene que robar para comer, su madre le abandona, sus vecinos le odian y la autoridad le maltrata constantemente. Conoce cárceles, penales y el manicomio, hasta llegar al País Vasco, donde encuentra trabajo y logra enderezar su vida.Con personajes reales e información fidedigna pues como dice el propio Pinilla, en el relato de su vida Antonio era incapaz de agregar un gramo de fantasía o invención, la narración es sobrecogedora, impetuosa, profundamente emotiva. Las situaciones superan en crudeza todo lo imaginable, y se convierten en un reflejo agudísimo de la vida durante la posguerra, de las penurias y calamidades, de los odios y revanchas, de la miseria y la lucha por salir adelante y escapar de la represión y de la humillación permanentes. El protagonista, que es también un indómito, dispuesto a no dejarse someter nunca, adquiere proporciones desusadas hasta convertirse en un héroe trágico de absoluto realismo.La obra, aparecida hace ahora más de treinta años, se convirtió en un libro de referencia en plena Transición, y es desde entonces uno de los títulos más buscados y esperados de su autor. Hoy, cuando éste se ha convertido en uno de los nombres imprescindibles de la narrativa en castellano, tras la obtención del Premio Nacional de Narrativa y del Premio de la Crítica por Verdes Valles, colinas rojas, la publicación de Antonio B. el Ruso va a ser de nuevo un acontecimiento, por la modernidad del relato y la impresionante veracidad de lo narrado.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2026, '9788467228960', 'Los crímenes del número primo', 1, '2008', 496, NULL, 'media/core/9788467228960.jpeg', 1, '2023-05-03 08:08:40.430967', '2023-05-03 08:08:40.430967', 1149, 14, 6, 5, NULL, '', '07_05', 'Lola Machor 2', 101, 'Un abad y el arzobispo de Pamplona aparecen muertos en una ermita recóndita a unos kilómetros de la ciudad junto a un relicario y una gran cantidad de dinero. A los dos les falta un dedo y tienen las vestiduras rasgadas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2027, '8422630109', 'E invierno en Lisboa', 1, '1988', 252, NULL, 'media/core/sin-imagen_izFAC1h.jpg', 1, '2023-05-03 08:13:53.037835', '2023-05-03 08:13:53.037835', 1138, 1, 6, 5, NULL, '', '07_05', NULL, 14, 'Una peligrosa historia de amor en un entorno entrañable: los tugurios donde se inventó el jazz. Premio de la Crítica y Premio Nacional de Literatura.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2028, '9788467260410', 'El Don', 1, '2014', 346, 'Decoded', 'media/core/9788467260410.jpeg', 1, '2023-05-03 08:17:03.631836', '2023-05-03 08:17:03.631836', 1150, 1, 6, 5, NULL, '', '07_05', NULL, 58, '«Si se para a pensarlo ?continuó el director?, un genio matemático, alguien que desde la infancia había estado en contacto íntimo con la interpretación de los sueños, un hombre que había estudiado la filosofía china y el pensamiento occidental, y que había explorado las complejidades de la mente humana, era alguien que tenía un don y había nacido para ser criptógrafo.»Rong Jinzhen es un chico fuera de lo común: educado por un extranjero en la China de los años veinte, vive una infancia solitaria, sumergido en su propio mundo. Pero pronto desarrolla un don que lo hace extraordinario. Rong puede ver lo que nadie más ve, sus conocimientos van más allá de lo que una persona corriente puede entender. Convertido en un genio de las matemáticas conocido en todo el país, Rong es obligado a abandonar su carrera académica cuando es reclutado por el departamento de criptografía del servicio secreto chino.Atrapado en las grietas de un sistema terrorífico, se convertirá en el mayor descifrador de códigos del país, pero deberá enfrentarse a un reto que nadie ha podido superar hasta el momento, poniendo a prueba los límites de la razón y la cordura. ¿Dónde acaba la genialidad y empieza la locura? Inusual, inclasificable, original, absorbente, fascinante, extraordinario y adictivo, El don, el mayor fenómeno literario en China, ha entrado por la puerta grande en su conquista de Occidente recibiendo el aplauso unánime de la crítica internacional.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2029, '9788467262780', 'Endgame. La llamada', 1, '2014', 517, 'Endgame: The Calling', 'media/core/9788467262780.jpg', 1, '2023-05-03 08:21:43.413937', '2023-05-03 08:21:43.413937', 1151, 1, 6, 5, NULL, '', '07_05', NULL, 15, '12 jugadores.12 linajes milenarios.El juego final ha llegado y sólo uno puede ganar.ENDGAME ES REAL. ENDGAME ES AHORA.¿Quieres jugar?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2030, '9788422667667', 'El pasillo de la muerte', 1, '1997', 380, 'The Green Mile', 'media/core/9788422667667.jpeg', 1, '2023-05-03 08:30:44.417350', '2023-05-03 08:30:44.417350', 8, 1, 6, 5, NULL, '', '07_05', NULL, 96, 'Octubre de 1932, penitenciaría de Cold Mountain. Los condenados a muerte aguardan el momento de ser conducidos a la silla eléctrica. Los crímenes abominables que han cometido les convierten en carnaza de un sistema legal que se alimenta de un círculo de locura, muerte y venganza. Y es esa antesala del infierno Stephen King traza una pavorosa radiografía del horror en estado puro. He aquí, reunida por primera vez en un único volumen y con un prólogo especial del autor, esta escalofriante novela originalmente publicada en seis entregas. Todo un hito en la aclamada trayectoria del maestro indiscutible de la narrativa de terror contemporánea', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2031, '9788493923341', 'Luces de bohemia', 1, '2018', 1, NULL, 'media/core/9788493923341.GIF', 1, '2023-05-03 08:35:10.856166', '2023-05-03 08:35:10.856166', 1133, 41, 6, 5, NULL, '', '07_05', NULL, 397, 'esperpento trágico de la vida literaria de la epoca. Al degradarse la realidad aparece la farsa y, en un segundo nivel, el esperpento; "Los heroes clásicos reflejados en los espejos cóncavos dan el Esperpento", aclara Valle-Inclán.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2032, '9788422680314', 'El collar del neandertal', 1, '1999', 305, NULL, 'media/core/9788422680314.jpeg', 1, '2023-05-03 08:37:39.096899', '2023-05-03 08:37:39.096899', 287, 2, 6, 5, NULL, '', '07_05', NULL, 5, 'El pulso entre neardentales y cromañones y el porqué del triunfo de los segundos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2033, 'DossTortura', 'Dossier Tortura', 1, '1981', 20, NULL, 'media/core/sin-imagen_Fzn1j8R.jpg', 1, '2023-05-03 08:41:12.890068', '2023-05-03 08:41:12.890068', NULL, 39, 6, 5, NULL, '', '07_05', NULL, 398, '', '');
