INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2035, 'B19729', 'Què és l''objecció de consciència', 1, '1977', 43, NULL, 'media/core/sin-imagen_5c6exxw.jpg', 1, '2023-05-03 08:45:35.144811', '2023-05-03 08:45:35.144811', NULL, 39, 6, 5, NULL, '', '07_05', NULL, 399, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2036, '9788479018443', 'El libro de los cuentos de nuestras abuelas', 1, '2002', 305, NULL, 'media/core/9788479018443.jpeg', 1, '2023-05-03 08:49:06.562178', '2023-05-03 08:49:06.562178', 572, 44, 6, 5, NULL, '', '07_05', NULL, 32, '', 'Recopilación de Varda Fiszbein: https://www.lavanguardia.com/libros/autores/varda-fiszbein-35237');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2037, '9788467265583', 'Somos una familia', 1, '2013', 348, 'We Are Familiy', 'media/core/9788467265583.jpg', 1, '2023-05-03 08:51:52.350560', '2023-05-03 08:51:52.350560', 1152, 1, 6, 5, NULL, '', '07_05', NULL, 114, 'Al Santamaria es un niño prodigio que pretende salvar el mundo... después de solucionar un problema más apremiante: encontrar una casa al alcance de la cada vez más magra economía familiar.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2038, '9788467225099', 'Postguerra. Una historia de Europa desde 1945', 1, '2006', 1183, 'Postwar. A History of Europe since 1945', 'media/core/9788467225099.jpg', 1, '2023-05-03 08:55:10.751717', '2023-10-24 16:49:09.534327', 1153, 11, 6, 5, NULL, '', '0107', NULL, 73, 'En 1945 Europa se encontraba en sus momentos más bajos. Gran parte del continente estaba devastado por la guerra, los asesinatos en masa, los bombardeos y el caos. Amplias zonas de Europa del Este empezaban a caer bajo control soviético para cambiar un despotismo por otro. En la actualidad, la Unión Soviética ya no existe y las democracias europeas llegan hasta la frontera de Rusia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2039, '9788422675471', 'La especie elegida. La larga marcha de la evolución humana', 1, '1998', 350, NULL, 'media/core/9788422675471.jpg', 1, '2023-05-03 08:57:38.392812', '2023-05-03 08:57:38.392812', 287, 15, 6, 5, NULL, '', '07_05', NULL, 376, 'La mejor y más documentada síntesis acerca del enigma del hombre y la larga marcha de la evolución humanaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2040, '9788467238846', 'Caligrafía de los sueños', 1, '2011', 436, NULL, 'media/core/9788467238846.jpeg', 1, '2023-05-04 06:04:34.875388', '2023-05-04 06:04:34.875388', 216, 1, 6, 5, NULL, '', '07_05', NULL, 5, 'A mediados de los cuarenta, Ringo es un chiquillo de quince años que pasa las horas muertas en el bar de la señora Paquita, moviendo los dedos sobre la mesa, como si repasara las lecciones de piano que su familia ya no puede pagarle.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2041, '9780718076375', 'Matar a un ruiseñor', 1, '2015', 322, 'To Kill a Mokingbird', 'media/core/9780718076375.jpeg', 1, '2023-05-04 06:09:06.634449', '2023-05-04 06:09:48.692854', 1154, 1, 6, 5, NULL, '', '07_05', NULL, 400, '«Dispara a todos los grajos que quieras, si puedes acertarles, pero recuerda que es pecado matar a un ruiseñor.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2042, '9788420414706', 'Rayuela', 2, '2015', 627, NULL, 'media/core/9788420414706.jpg', 1, '2023-05-04 06:12:52.635447', '2023-05-04 06:12:52.635447', 833, 1, 6, 5, NULL, '', '07_05', NULL, 10, '«Contranovela», «crónica de una locura», «el agujero negro de un enorme embudo», «un feroz sacudón por las solapas», «un grito de alerta», «una especie de bomba atómica», «una llamada al desorden necesario», «una gigantesca humorada», «un balbuceo».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2043, '9788467272734', 'La edad de la penumbra', 1, '2018', 298, 'The Darkening Age', 'media/core/9788467272734.jpg', 1, '2023-05-04 06:18:47.471313', '2023-05-04 06:18:47.471313', 1155, 11, 6, 5, NULL, '', '07_05', NULL, 211, '«Mordaz y documentado, el libro palpita a un ritmo fabuloso, y Nixey evocacon brillantez todo lo que perdimos con la decadencia del mundo clásico.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2044, '9788439726883', 'Las leyes de la frontera', 1, '2012', 382, NULL, 'media/core/9788439726883.jpg', 1, '2023-05-04 06:21:51.948384', '2023-05-04 06:21:51.948384', 245, 1, 6, 5, 'Literatura Mondadori', '', '07_05', NULL, 171, 'En el verano de 1978, cuando España no ha salido aún del franquismo y no termina de entrar en la democracia y las fronteras sociales y morales parecen más porosas que nunca, un adolescente llamado Ignacio Cañas conoce por casualidad al Zarco y a Tere, dos delincuentes de su edad, y ese encuentro cambiará para siempre su vida. Treinta años más tarde, un escritor recibe el encargo de escribir un libro sobre el Zarco, convertido para entonces en un mito de la delincuencia juvenil de la Transición, pero lo que el escritor acaba encontrando no es la verdad concreta del Zarco, sino una verdad imprevista y universal, que nos atañe a todos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2045, '9788467246018', 'Yo confieso', 1, '2011', 753, 'Jo confesso', 'media/core/9788467246018.jpg', 1, '2023-05-04 06:25:40.005722', '2023-05-04 06:25:40.005722', 745, 1, 6, 5, NULL, '', '07_05', NULL, 58, 'Si la tienda de antigüedades de la familia es todo un universo para el niño Adrià, el despacho del padre es el centro de ese universo y su tesoro más preciado un magnífi co violín Storioni, en cuyo estuche aún se aprecia la sombra de un crimen cometido muchos años atrás. La infancia y la adolescencia de Adrià, llena de preguntas sin respuesta, de juegos solitarios y de falta de calor, está dedicada al estudio de la historia y de las lenguas, tal como quiere el padre, y a la práctica del violín, siguiendo los deseos de la madre. Pero un accidente acabará con la vida del padre, sumiendo a Adrià en un estado de culpabilidad y llenando su mundo de secretos y turbios misterios que tardará muchos años en despejar. Una novela ambiciosa, monumental y maravillosa que nos habla del poder, el dolor y la penitencia, el mal y la redención, la venganza, el amor, la culpa y la posibilidad del perdón, y que de la mano de una escritura brillante y a través de una imponente historia recorre los momentos estelares de la historia occidental.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2046, '8436802977', 'Diccionario de Teoriá Económica', 1, '1985', 1, NULL, 'media/core/8436802977.jpg', 1, '2023-05-04 06:30:31.222531', '2023-05-04 06:30:31.222531', 1156, 40, 6, 5, NULL, '', '07_05', NULL, 401, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2047, '9788422686798', 'El origen de la Humanidad', 1, '2001', 207, 'The origin of Humankind', 'media/core/9788422686798.jpg', 1, '2023-05-04 06:34:23.268356', '2023-05-04 06:34:23.268356', 1157, 2, 6, 5, NULL, '', '07_05', NULL, 76, 'En 1984, Richard Leakey realizó en las orillas del lago Turkana, África oriental, uno de los hallazgos de fósiles más importantes de este siglo: el esqueleto de un joven que vivió allí hace más de un millón de años y que pertenecía al género que ahora conocemos como Homo erectus. A partir de este descubrimiento, Leakey nos conduce a su exposición final sobre la evolución humana: la capacidad de andar erguidos ha hecho posible la evolución de los humanos modernos, y todos los elementos de la evolución humana deben contemplarse como algo relacionado con este hecho crucial.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2048, '9788483077894', 'La larga marcha. Medio siglo de política (económica) entre la historia y la memoria', 1, '2007', 449, NULL, 'media/core/9788483077894.jpg', 1, '2023-05-04 06:38:21.548737', '2023-05-04 06:38:21.548737', 528, 11, 6, 5, NULL, '', '07_05', NULL, 192, 'Esta es la crónica de un gigantesco esfuerzo colectivo, la historia de un éxito: la larga marcha de España hacia Europa, esto es, hacia la modernidad. Así presenta Joaquín Estefanía este volumen, que recoge el fruto de muchos años de atención, desde un observatorio privilegiado, al devenir de los acontecimientos políticos y económicos de España. En estas páginas desemboca buena parte de la labor periodística realizada por el autor para el diario Informaciones y el semanario Cuadernos para el Diálogo, para Cinco Días y, sobre todo, para El País. Como él mismo reconoce, por otra parte, un libro de estas características siempre es deudor de la atención y el análisis de otros observadores cualificados que han dejado su testimonio aquí y allá, en multitud de libros y artículos. Consciente del peligro que entraña el hecho de ser contemporáneo de los hechos relatados, Estefanía ha procurado tomar la distancia que requiere el trabajo histórico sin renunciar por ello a la memoria, conteniendo oportunamente, eso sí, la adhesión que ésta impone.La larga marcha es, al mismo tiempo, un relato político y económico, un ensayo hemerográfico, un documento sociológico, una crónica periodística, un testimonio; pero su autor desea que se lea, ante todo, como «una mirada al servicio de la memoria y, con toda humildad, también de la historia de este último medio siglo que ha sido para buena parte de las distintas generaciones de ciudadanos españoles una suerte de utopía factible: Europa».', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2049, '9788430600304', 'Conciencia del subdesarrollo veinticinco años después', 1, '1996', 284, NULL, 'media/core/9788430600304.jpg', 1, '2023-05-04 06:41:08.841721', '2023-05-04 06:41:08.841721', 752, 2, 6, 5, 'Ciencias Sociales', '', '07_05', NULL, 323, 'Repaso a la monstruosa desigualdad entre los pa#ses subdesarrollados y nuestro mundo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2050, '9788422659808', 'Historia de los pueblos árabes', 1, '1992', 595, 'A History of the Arab Peoples', 'media/core/9788422659808.jpg', 1, '2023-05-04 06:46:43.068938', '2023-05-04 06:46:43.068938', 1158, 11, 6, 5, NULL, '', '07_05', NULL, 64, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2051, '9788483833889', 'El lector de Julio Verne', 1, '2012', 417, NULL, 'media/core/9788483833889.jpg', 1, '2023-05-04 06:49:26.378425', '2023-05-04 06:49:26.378425', 965, 1, 6, 5, 'Colección Andanzas', '', '07_05', 'Episodios de una guerra interminable 2', 12, '¿Qué puede escuchar detrás de la puerta el hijo de un guardia civil en un pueblo de Jaén en 1947?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2052, '9788416237005', 'Galveston', 1, '2010', 282, 'Galveston', 'media/core/9788416237005.jpg', 1, '2023-05-04 06:51:55.005685', '2023-05-04 06:51:55.005685', 1159, 1, 6, 5, 'Black Salamandra', '', '07_05', NULL, 29, 'El texano Roy Cady, alto y corpulento, con barba y melena, sombrero de ala ancha y botas de cowboy, lleva unos años ejerciendo de matón profesional en Nueva Orleans. Es un tipo tranquilo, capaz de ver el lado filosófico de las cosas, a la vez comprensivo e implacable. Pero el mismo día en que le diagnostican un cáncer avanzado, mientras bebe unos whiskys y sin haber comentado todavía la aciaga noticia con nadie, intuye que su jefe, el poderoso extorsionador Stan Ptitko, quiere quitárselo de encima, y que el trabajo que le acaba de encargar Stan y que debe llevar a cabo esa noche, una de sus rutinarias visitas de intimidación, es una trampa...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2053, '8420696021', 'Las Crizadas vistas por los árabes', 2, '1989', 290, 'Les croisades vues par les arabes', 'media/core/8420696021.jpg', 1, '2023-05-04 06:55:35.168247', '2023-05-04 06:55:35.168247', 733, 2, 6, 5, NULL, '', '07_05', NULL, 69, 'Basándose en los testimonios de los historiadores y cronistas árabes de la época, Amin Maalouf relata la historia de las cruzadas tal y como las vieron y vivieron en "el otro campo", es decir, en el lado musulmán, punto de vista olvidado hasta la publicación de esta obra. "Las cruzadas vistas por los árabes" abarca el periodo comprendido entre la llegada de los primeros cruzados a Tierra Santa en 1096 y la toma de Acre por el sultán Jalil en 1291, dos agitados siglos que dieron forma a Occidente y al mundo árabe y que aún hoy siguen condicionando sus relaciones.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2054, '8471511037', 'El Hombre en la Prehistoria', 2, '1976', 528, 'Man in Prehistory', 'media/core/8471511037.jpg', 1, '2023-05-04 07:00:59.971176', '2023-05-04 07:00:59.971176', 1160, 2, 6, 5, 'Hombre y Sociedad', '', '07_05', NULL, 402, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2055, '8422694468', 'El castillo del espectro. Antología de relatos fantásticos españoles del siglo XIX', 1, '2002', 284, NULL, 'media/core/8422694468.jpeg', 1, '2023-05-04 07:04:53.702534', '2023-05-04 07:04:53.702534', 572, 44, 6, 5, NULL, '', '07_05', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2056, '8420266963666', 'Titanic', 1, '2012', 185, NULL, 'media/core/8420266963666.jpg', 1, '2023-05-12 06:48:39.013788', '2023-05-12 07:04:54.554569', 1161, 49, 11, 5, NULL, '', '04_00', NULL, NULL, 'Entre los miles de personas que desean un hermoso viaje, el destino elije a dos jóvenes almas para lanzarles el desafío de alimentar una pasión que cambiará sus vidas para siempre. Rose DeWitt Bukater (interpretada por la ganadora de un Oscar® Kate Winslet) es una joven de 17 años y familia de clase alta norteamericana que sufre las estrictas expectativas de la sociedad eduardiana y que se enamora del joven viajero de tercera clase y espíritu libre Jack Dawson (ganador de un Globo de Oro y nominado a los Oscar® Leonardo...', '2 discosINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2057, '9788467043792', 'Antes de los dieciocho. Antología de cuentos', 1, '2015', 249, NULL, 'media/core/9788467043792.jpg', 1, '2023-05-12 09:40:33.417570', '2023-05-12 09:40:33.417570', 572, NULL, 6, 2, 'Colección Austral', '', '0101', NULL, 265, 'Cuentos de los grandes autores de la literatura (Chéjov, Baroja, Cortázar, Allende) donde los protagonistas son niños o adolescentes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2058, '9782070536559', 'Louis Braille l''enfant de la nuit', 1, '1983', 100, 'The Boy who invented Books for the Blind', 'media/core/9782070536559.jpg', 1, '2023-05-12 09:45:28.717324', '2023-05-12 09:45:28.717324', 1162, 27, 6, 2, NULL, '', '0101', NULL, 293, 'À la suite d''un accident, Louis Braille est devenu aveugle à l''âge de trois ans. Mais cela ne l''empêche pas de vivre presque comme tous les autres enfants. C''est à l''école que les difficultés vont commencer car il veut apprendre à lire. Loin de se décourager, Louis se fait alors une promesse incroyable : il trouvera le moyen de déchiffrer ce que ses yeux ne peuvent voir.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2059, '9782070364237', 'Le petit Niolas', 1, '2009', 157, NULL, 'media/core/9782070364237.jpg', 1, '2023-05-12 09:49:47.935966', '2023-05-12 09:49:47.935966', 390, 1, 6, 2, NULL, '', '0101', NULL, 404, 'Les histoires mettent en scène un petit garçon, Nicolas, dans un environnement urbain1 pendant les années 1950, où se melent l’humour et la tendresse de l’enfance. Le personnage, identifié par un dessin au trait, livre ses pensées intimes grace à un langage d’enfant créé par Goscinny. Les thèmes sont avant tout ceux de l’enfance (comme la camaraderie, les disputes, les rapports avec la maitresse d’école, les premières amourettes) mais Goscinny décrypte également le monde complexe des adultes: rapports entre voisins, avec son patron, avec une belle-famille, l’éducation, disputes familiales…', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2060, '9782253002826', 'Arsène Lupin. Gentleman cambrioleur', 43, '2009', 184, NULL, 'media/core/9782253002826.jpg', 1, '2023-05-12 09:53:26.264921', '2023-05-12 09:53:26.264921', 1022, 1, 6, 2, 'Livre de poche', '', '0101', NULL, 405, 'Vif, audacieux, impertinent, rossant sans arrêt le commissaire (qui ici, en l’occurrence, s’appelle l’inspecteur Ganimard), traînant les cœurs après lui et mettant les rieurs de son côté, se moquant des situations acquises, ridiculisant les bourgeois, portant secours aux faibles, Arsène Lupin, gentleman cambrioleur est un Robin des Bois de la «Belle Epoque». Un Robin des Bois bien français : il ne se prend pas trop au sérieux, ses armes les plus meurtrières sont les traits d’esprit ; ce n’est pas un aristocrate qui vit comme un anarchiste mais un anarchiste qui vit comme un aristocrate. Arsène Lupin, après plus d’un demi-siècle, n’a pas vieilli. Il ne vieillira', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2061, '9782011552853', 'Vingt Mille Lieus sous les mers', 1, '2005', 93, NULL, 'media/core/9782011552853.JPG', 1, '2023-05-12 09:56:52.162133', '2023-05-12 09:56:52.162133', 537, 1, 6, 2, 'Lecture facile', '', '0101', NULL, 289, '" C''est aujourd''hui 8 novembre à midi que commence notre voyage sous les eaux ". INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2062, '9782011552464', 'La Tête d''un homme', 1, '2003', 76, NULL, 'media/core/9782011552464.jpg', 1, '2023-05-12 09:59:32.009593', '2023-05-12 09:59:32.009593', 107, 1, 6, 2, 'Lecture facile', '', '0101', NULL, 289, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2063, '9788467322002', 'Arsène Lupin. Gentleman cambrioleur', 1, '2005', 13, NULL, 'media/core/9788467322002.jpg', 1, '2023-05-12 10:02:47.233500', '2023-05-12 10:02:47.233500', 1022, 24, 6, 2, 'Lecture en français facile', '', '0101', NULL, 406, 'Arsène Lupin, gentleman cambrioleur, aime les objets d''art et les bijoux les plus précieux. Il s''introduit chez les gens riches, mais il agit sans violence. Le personnage est astucieux et impertinent. Dans les trois aventures présentées ici, il n''hésite pas à laisser des preuves de son passage pour tromper la police. Il adore se métamorphoser pour échapper à l''inspecteur Ganimard. Principales caractéristiques Le film « Arsène Lupin » est sorti en France fin 2004 et est arrivé sur les écrans en Espagne en 2005. A l''adresse Internet suivante, vous trouverez le site officiel du film de Jean-Paul Salomé, avec Romain Duris et', 'Contien CD');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2064, '8484150887', 'Quelques histoires d''école', 1, '1999', 91, NULL, 'media/core/sin-imagen_na2e92s.jpg', 1, '2023-05-12 10:32:11.624730', '2023-05-12 10:32:11.624730', 572, 44, 6, 2, NULL, '', '0101', NULL, 407, '', '');
