INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2069, '9788853001290', 'Il viaggio di Laurent', 1, '2004', 68, NULL, 'media/core/9788853001290.jpg', 1, '2023-05-12 10:53:18.597946', '2023-05-12 10:54:31.231041', 1166, 1, 6, 2, NULL, '', '0101', NULL, 409, 'Alla scoperta delle proprie origini, Laurent intraprende un viaggio che inizia a Parigi e, passando per Firenze, Roma e Positano, lo condurrà in alcune delle più belle città d`Italia. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2070, '9780194243476', 'The Lost World', 1, '2002', 52, NULL, 'media/core/9780194243476.jpg', 1, '2023-05-12 10:57:37.307517', '2023-05-12 10:58:05.776504', 501, 1, 6, 2, NULL, '', '0101', NULL, 410, 'You said that you wanted danger, didnt you, says McArdle, the editor of the Daily Gazette. And he sends his young reporter, Malone, on a strange journey into South America with the famous Professor Challenger. Challenger believes he can find a lost world full of dinosaurs in the middle of the Amazon forest. But this world is dangerous to reach, and, once the Professor and his small group of explorers arrive, things get even more dangerous for them. Will they', 'Contiene CD');
