INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2073, '9788495824288', 'La canción del pirata', 1, '2002', 20, NULL, 'media/core/9788495824288.jpg', 1, '2023-05-12 11:20:14.534339', '2023-05-12 11:22:29.913341', 618, 4, 6, 2, NULL, '', '0101', NULL, 412, 'Con diez cañones por banda, viento en popa a toda vela... Con esta cuidada adpatación infantil, los niños descubrirán todo el espíritu de estas románticas rimas y aprenderán a amar a nuestros clásicos. Autor: José de Espronceda. Ilustraciones: Lluís Cadafalch.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2074, '9788496034341', 'Margarita', 1, '2003', 20, NULL, 'media/core/9788496034341.jpg', 1, '2023-05-12 11:25:51.650289', '2023-05-12 11:25:51.650289', 905, 4, 6, 2, NULL, '', '0101', NULL, 412, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2075, '9788415594017', 'Bajo la misma estrella', 6, '2014', 300, 'The Fault in Our Stars', 'media/core/9788415594017.jpg', 1, '2023-05-12 11:29:04.948849', '2023-05-12 11:29:04.948849', 1168, 1, 6, 2, NULL, '', '0101', NULL, 11, 'Emotiva, irónica y afilada. Una novela teñida de humor y de tragedia que  habla de nuestra capacidad para soñar incluso en las circunstancias más difíciles.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2076, '9788424636500', 'He jugado con lobos', 1, '2010', 164, 'He jugat amb els llops', 'media/core/9788424636500.jpg', 1, '2023-05-12 11:31:53.573083', '2023-05-12 11:31:53.573083', 1169, 1, 6, 2, NULL, '', '0101', NULL, 413, 'Cuando Marcos tenía apenas siete años su padre lo vendió a un terrateniente para que cuidase de un rebaño de cabras, solo, rodeado de montañas, en la tierra de los lobos. Marcos vivió allí durante más de 10 años, en una comunión perfecta con la naturaleza, que lo ayudó a sobrevivir en la soledad del abandono y a la falta de amor y de afecto. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2077, '9788498381481', 'La jirafa blanca', 1, '2008', 189, 'The White Giraffe', 'media/core/9788498381481.jpg', 1, '2023-05-12 11:35:00.117439', '2023-05-12 11:35:00.117439', 1170, 1, 6, 2, NULL, '', '0101', NULL, 29, 'Tras quedarse huérfana con apenas once años, Martine es enviada a vivir a la reserva natural de Sawubona, en África, un bello y misterioso paraje donde la espera una abuela no muy acogedora y algo enigmática. ¿Qué oculta su abuela? ¿Por qué se respira allí un ambiente tan extraño? ¿Y por qué mantiene a Martine alejada de los animales? Quizá la respuesta se encuentre en las leyendas locales que hablan de una extraña jirafa blanca, muy conocida por los primitivos habitantes del lugar. Una jirafa que convertirá en rey de los animales a quien logre cabalgar sobre su grupa, un ejemplar tan fuerte y altivo como frágil ante la codicia de los cazadores furtivos. Gracias a él, Martine descubrirá sus propias cualidades y vivirá una emocionante aventura en una tierra hermosa y fascinante.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2078, '9780064410939', 'Charlotte''s Web', 1, '1999', 184, NULL, 'media/core/9780064410939.jpg', 1, '2023-05-12 11:40:17.385570', '2023-05-12 11:40:17.385570', 1171, 1, 6, 2, NULL, '', '0101', NULL, 400, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2079, '9788427950160', 'La telaraña de Carlota', 1, '2006', 159, 'Charlotte''s Web', 'media/core/9788427950160.jpg', 1, '2023-05-12 11:43:03.600616', '2023-05-12 11:43:03.600616', 1171, 1, 6, 2, NULL, '', '0101', NULL, 414, 'Ésta es la historia de una niña que quería a un cerdito llamado Wilbur, y de una queridísima amiga de Wilbur llamada INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2080, '9788448920210', 'Bestiari', 7, '2009', 171, NULL, 'media/core/9788448920210.jpg', 1, '2023-05-13 06:09:32.001083', '2023-05-13 06:09:32.001083', 1172, 4, 6, 2, NULL, '', '0101', NULL, 157, 'Amb aquest llibre es pot comprovar que es pot utilitzar el vers per parlar de coses senzilles, quotidianes, com poden ser els animals. Bestiari és un llibre de petits poemes escrit per un dels més grans poetes catalans de tots els temps: Josep Carner. La broma, la tendresa i la ironia hi són ben presents.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2081, '9788420464503', 'Charli y la fábrica de chocolate', 67, '2007', 199, 'Charlie and the chocolate factory', 'media/core/9788420464503.jpg', 1, '2023-05-13 06:12:50.739299', '2023-05-13 06:12:50.739299', 1173, 48, 6, 2, 'Alfaguara Juvenil', '', '0101', NULL, 10, 'Charlie ha tenido mucha suerte. Ha sido uno de los elegidos para visitar la maravillosa fábrica de chocolate Wonka. A veces, la toma de una decisión transforma tu vida de manera radical. Eso es lo que le sucede a Charlie.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2082, '9788447411177', 'L''any trirurany', 1, '2003', 93, NULL, 'media/core/9788447411177.png', 1, '2023-05-13 06:20:10.184211', '2023-05-13 06:20:10.184211', 1174, 4, 6, 2, 'Muntanya encantada', '', '0101', NULL, 415, 'Versos per a tot l''any i per a totes les ocasions: Reis d?Orient i fantasmes, coques de Sant Joan i panellets de Tots Sants, terrícoles i marcians, van desfilant per aquestes pàgines al ritme que els marquen els versos i el calendari.', 'Libro dedicado');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2083, '9788475960906', 'El nen. Contes d''infància', 8, '2007', 174, 'Boy. Taless of childhood', 'media/core/9788475960906.jpg', 1, '2023-05-13 06:24:00.820315', '2023-05-13 06:24:00.820315', 1173, 48, 6, 5, 'L''odissea', '', '0101', NULL, 416, 'Barreja de records inventats i memòries autèntiques, El nen no és ben bé una autobiografia, però conta fets reals de la vida de Roald Dahl que desvetllaran tanta sorpresa com les seves novel·les. Qualsevol lector que estimi els seus llibres quedarà fascinat i admirat en descobrir algunes de les coses que li van passar de nen i de jove.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2084, '9788478442010', 'Caperucita en Manhattan', 48, '2009', 205, NULL, 'media/core/9788478442010.jpg', 1, '2023-05-13 06:27:09.092650', '2023-05-13 06:27:09.092650', 103, 48, 6, 2, 'Las Tres Edades', '', '0101', NULL, 16, 'Sara Allen es una niña de diez años que vive en Brooklyn, Nueva York. Su mayor deseo es ir sola a Manhattan para llevar a su abuela un tarta de fresa. La abuela de esta moderna Caperucita ha sido cantante de music-hall y se ha casado varias veces. El lobo es míster Woolf, un pastelero multimillonario que vive cerca de Central Park en un rascacielos con forma de tarta. Pero el hilo mágico de este relato se centra en miss Lunatic, una mendiga sin edad que vive de día oculta en la estatua de la Libertad y que sale de noche para mediar en las desgracias humanas', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2085, '9788478449460', 'De repente en lo profundo del bosque', 1, '2006', 124, 'pit''om be''omek haya''ar', 'media/core/9788478449460.jpg', 1, '2023-05-13 06:30:57.621583', '2023-05-13 06:30:57.621583', 1433, 48, 6, 2, 'Nuevos Tiempos', '', '0101', NULL, 16, 'El lector tiene en sus manos una Aggadah, una parábola, con todo su simbolismo y carga metafórica, que cuenta la historia de un pequeño pueblo embrujado sobre el cual ha recaído una extraña maldición: la desaparición de todos los animales... De noche, en el pueblo, un raro e imposible silencio habita la oscuridad. También de día la ausencia totalde animales deja su huella: ni un perro, ni un gato, ni siquiera una mosca o un grillo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2086, '9788498411164', 'Kafka y la muñeca viajera', 8, '2008', 145, NULL, 'media/core/9788498411164.jpg', 1, '2023-05-13 06:36:08.141346', '2023-05-13 06:36:08.141346', 285, 1, 6, 2, 'Las Tres Edades', '', '0101', NULL, 16, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2087, '9788484355083', 'Molts contes per jugar', 15, '2007', 157, 'Tante storie per giocare', 'media/core/9788484355083.jpg', 1, '2023-05-13 06:39:01.642408', '2023-05-13 06:39:01.642408', 1176, 44, 6, 2, NULL, '', '0101', NULL, 10, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2088, '9788434891081', 'Billy Elliot', 5, '2009', 190, 'Billy Elliot', 'media/core/9788434891081.jpg', 1, '2023-05-13 06:42:58.445720', '2023-05-13 06:42:58.445720', 1177, 1, 6, 2, 'El barco de vapor', '', '0101', NULL, 417, 'La madre de Billy ha muerto, y tanto su padre como su hermano mayor están inmersos en una de las huelgas de mineros más importantes de todos los tiempos. El padre de Billy lleva a su hijo al gimnasio para que aprenda boxeo, igual que hizo él de pequeño. Pero el chico quiere ser bailarín, algo no bien visto en su pueblo. ¿Conseguirá Billy vencer los prejuicios y alcanzar su sueño? Una estupenda novela que muestra la superación de las dificultades y el derrumbe de los estereotipos de género.', 'Basada en el guion de Lee Hall');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2089, '9788494218675', 'No pregunten por Gagarin', 1, '2014', 143, NULL, 'media/core/9788494218675.png', 1, '2023-05-13 06:47:06.681008', '2023-05-13 06:47:06.681008', 1178, 44, 6, 2, 'Col.lecció Argumenta', '', '0101', NULL, 418, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2090, '9788420448695', '¡Socorro!', 16, '2008', 168, NULL, 'media/core/9788420448695.jpg', 1, '2023-05-13 06:51:22.627062', '2023-05-13 06:51:22.627062', 1179, 1, 6, 2, 'Alfaguara Juvenil', '', '0101', NULL, 10, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2091, '9781471156267', 'It Ends with Us', 1, '2016', 373, NULL, 'media/core/9781471156267.jpg', 1, '2023-05-13 06:58:30.420418', '2023-05-13 06:58:30.420418', 1180, 1, 6, 2, NULL, '', '0101', NULL, 419, 'Lily hasn''t always had it easy, but that''s never stopped her from working hard for the life she wants. She''s come a long way from the small town in Maine where she grew up – she graduated from college, moved to Boston, and started her own business. So when she feels a spark with a gorgeous neurosurgeon named Ryle Kincaid, everything in Lily''s life suddenly seems almost too good to be true.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2092, '9788483650868', 'Aunque seamos malditas', 1, '2008', 476, NULL, 'media/core/9788483650868.gif', 1, '2023-05-13 07:08:43.139601', '2023-05-13 07:12:46.781841', 1181, 1, 6, 2, 'SUMA de letras', '', '0101', NULL, 87, 'Hay algunas acusaciones que marcan toda tu vida… ¿A ti de qué te han acusado? Todos en algún momento nos hemos sentido perseguidos…Ainur, que siempre se ha sentido perseguida, acaba de ganar el primer juicio por acoso laboral en España. Pero los matones de su ex jefe la buscan para matarla. Por ello se tiene que refugiar en el pueblo de sus ancestros, un extraño lugar del norte azotado por el mar. Es allí donde conocerá a los peculiares personajes de la novela: el Farero, que vive en un faro que no alumbra y que ha sido perseguido también por un acto que no cometió; la tuerta Consuelo, que se encarga de difamar a los foráneos; el Señor Oscuro, un hombre en cuya casa no entra la luz; o Satán, el perro-lobo que se le aparece y desaparece… INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2094, '9788861822474', 'Nuova grammatica pratica della lingua italiana', 1, '2002', 1, NULL, 'media/core/9788861822474.jpg', 1, '2023-05-13 07:15:38.286619', '2023-05-13 07:15:38.286619', 1182, 24, 6, 2, NULL, '', '0101', NULL, 420, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2095, 'HabRaq0101', 'Los desposeídos', 1, NULL, 297, 'The Dispossessed', 'media/core/sin-imagen_Dos5UYC.jpg', 1, '2023-05-13 07:27:26.889448', '2023-05-13 07:27:26.889448', 1090, 3, 12, 2, NULL, '', '0101', NULL, NULL, 'Shevek, un físico brillante, originario de Antares, un planeta aislado y "anarquista", decide emprender un insólito viaje al planeta madre Urras, en el que impera un extraño sistema llamado el "propietariado". Shevek cree por encima de todo que los muros del odio, la desconfianza y las ideologías, que separan su planeta del resto del universo civilizado, deben ser derribados. En este contexto la autora explora algunos de los problemas de nuestro tiempo: la posición de la mujer en la estructura social, la complejidad de las relaciones humanas, los méritos y las promesas de las ideologías, las perspectivas del idealismo político en el mundo actual.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2096, '7933700200023', 'Cuba', 1, '2007', 1, NULL, 'media/core/7933700200023.jpg', 1, '2023-05-13 07:32:17.857325', '2023-05-13 07:32:17.857325', 572, 43, 6, 2, 'Dossier', '', '0101', NULL, 43, 'Este número de VANGUARDIA DOSSIER analiza los logros y los fracasos de la revolución, su cara oscura y los desafíos que la elite dirigente tiene planteados.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2097, '7933700200024', 'Irán por dentro', 1, '2007', 1, NULL, 'media/core/7933700200024.jpg', 1, '2023-05-13 07:36:01.792808', '2023-05-13 07:36:01.792808', 572, 43, 6, 2, 'Dossier', '', '0101', NULL, 43, 'Esta monografía de VANGUARDIA DOSSIER analiza Irán por dentro: desde la compleja estructura de poder, que es un círculo vicioso (Schirazi) y una combinación ...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2098, '7933700200026', 'África', 1, '2008', 1, NULL, 'media/core/7933700200026.jpg', 1, '2023-05-13 07:39:35.232146', '2023-05-13 07:39:35.232146', 572, 43, 6, 2, 'Dossier', '', '0101', NULL, 43, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2099, '9782877065085', 'Le Château de ma mère', 1, '2004', 217, NULL, 'media/core/9782877065085.jpg', 1, '2023-05-13 08:37:32.503559', '2023-05-13 08:37:32.503559', 1184, 1, 6, 2, 'Soub¡venirs d''enfance', '', '0101', NULL, 421, 'Le plus beau livre sur l''amitié enfantine : un matin de chasse dans les collines, Marcel rencontre le petit paysan., Lili des Bellons. Ses vacances et sa vie entière en seront illuminées.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2100, '9788424681234', 'El fill de la pluja d''or', 15, '2008', 144, NULL, 'media/core/9788424681234.jpg', 1, '2023-05-13 08:40:03.337962', '2023-05-13 08:40:03.337962', 1185, 1, 6, 2, NULL, '', '0101', NULL, 413, 'Zeus va voler demostrar als humans que no hi ha cap poder superior al del destí. Dànae, que havia estat reclosa pel seu pare, va infantar un fill que Zeus li va fer concebre per mitjà d''una pluja d''or. El fill de la pluja d''or, Perseu, anirà a matar la Medusa, la pitjor de les tres Gorgones, per alliberar Dànae, la seva mare, de les urpes del rei Polidectes, que es vol casar amb ella tant sí com no.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2101, '9788467229097', 'La clave secreta del Universo', 1, '2007', 220, 'George''s Secret Key to the Universe', 'media/core/9788467229097.jpg', 1, '2023-05-13 08:45:38.394057', '2023-05-13 08:45:38.394057', 289, 1, 6, 2, NULL, '', '0101', NULL, 211, 'A George nada le gusta más en el mundo que mirar las estrellas; tambien  le encantaría tener un ordenador con el que navegar y conocer más sobre  el Universo, pero sabe que eso es misión imposible. En casa, sus padres  son tan ecologistas que no quieren ni oír hablar del progreso y la ciencia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2102, 'Ivanhoe_Raq', 'Ivanhoe', 1, NULL, 240, NULL, 'media/core/sin-imagen_EeVrAbs.jpg', 1, '2023-05-13 08:50:06.039616', '2023-05-13 08:50:06.039616', 1186, 1, 6, 2, 'Colecció Robinsones', '', '0101', NULL, 422, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2103, '9788493896096', 'En defensa d''Afrodita', 5, '2018', 275, NULL, 'media/core/9788493896096.jpg', 1, '2023-05-13 08:52:53.263277', '2023-05-13 08:52:53.263277', 572, 2, 2, 2, NULL, '', '0101', NULL, 423, 'Sexe? Amor? Relacions? Parella? Relacions lliures? Tens un repte entre les mans, un repte contra tu, contra tot allò que hem aprés, que ens ha ensenyat. Un repte que ens obliga a canviar l´òptica amb la que mirem el món. Un repte a pensar les relacions sexo-afectives des d´una perspectiva de ruptura i nnovadora. Aquest llibre pot ferir la teva sensibilitat, pot fer que et qüestionis la teva vida i les teves relacions, pot ser un xoc, però aquesta n´és la intenció, forçar-nos a reflexionar sobre allò que mai en haguéssim plantejat. ´En Defensa d´Afrodita´, vol ser un càntic collectiu a une snoves formes de relacionar-nos entre les persones. Unes formes lliures i no coercitives on la llibertat sexual sigui la garant de la construcció de la persona nova en una nova societat.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2104, '9788433977717', 'Cómo ser mujer', 11, '2020', 354, 'How To Be a Woman', 'media/core/9788433977717.jpg', 1, '2023-05-13 08:57:28.667830', '2023-05-13 08:57:28.667830', 1187, 2, 6, 5, 'Colección compactos', '', '0101', NULL, 6, 'No hubo nunca mejor época que ésta para ser mujer: ahora existen el voto femenino y la píldora, y desde 1727 ya no envían a las mujeres a la hoguera por brujas. Pero ¿cómo ser mujer? Ésa es precisamente la gran, eterna pregunta a la que Caitlin Moran se propone responder en una obra que aborda a calzón quitado–a veces literalmente–, con inteligencia, desvergüenza e ironía y también una salvaje franqueza, los principales aspectos de la condición femenina. Mezcla de libro de memorias y de divertida vociferación, apoyándose siempre en sus experiencias como mujer, feminista e hija de una familia numerosa y proletaria, Caitlin Moran se describe con una sinceridad y una audacia militantes, y habla con absoluta naturalidad de la relación con su cuerpo. Y con la comida, con los hombres, con el trabajo, la sexualidad, la maternidad, el aborto. Pero también escribe sobre la importancia de Lady Gaga, y los errores y horrores de la depilación más íntima, o el bótox. Y sobre mucho más, Así, alternando provocativas observaciones sobre la vida de las mujeres con historias ferozmente divertidas sobre sí misma, desnuda, deconstruye y arroja al fuego la imagen políticamente correcta de la mujer del siglo XXI. Y nos descubre página tras página esos secretos que se cuentan en voz baja las amigas verdaderas, y no esas equívocas cole...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2105, '9788499300399', 'El violí d''Auschwitz', 5, '2011', 132, NULL, 'media/core/9788499300399.jpg', 1, '2023-05-13 09:00:47.368687', '2023-05-13 09:00:47.368687', 1188, 1, 6, 2, 'Labutxaca', '', '0101', NULL, 387, 'Per sobreviure, els diu que és fuster, una feina amb una utilitat pràctica que li permet resistir les condicions de vida infrahumanes, i ajornar així la seva probable “eliminació”. Gran aficionat a la música clàssica, el comandant del camp descobreix la veritable professió d’en Daniel i aleshores el sotmet a una prova: li haurà de construir un violí que tingui un so perfecte. El luthier es posa a l’obra, però no es pot ni imaginar el càstig que l’espera si no compleix bé el sinistre encàrrec.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2106, '9788475965826', 'El racisme explicat a la meva filla', 7, '2000', 59, NULL, 'media/core/9788475965826.jpg', 1, '2023-05-13 09:04:02.432508', '2023-05-13 09:04:02.432508', 331, 39, 6, 2, 'Biblioteca Universal', '', '0101', NULL, 416, 'El gran escriptor marroquí Tahar Ben Jelloun descobreix, en un diàleg amb la seva filla, els motius profunds que porten les persones a comportar-se de manera racista. ¿Per què som racistes? ¿Per què tenen por, els racistes? ¿Què és el colonialisme i quines conseqüències té? ¿Som racistes de naixement? Tahar Ben Jelloun desenvolupa hàbilment la resposta (no sempre fàcil) a totes aquestes preguntes, i el resultat és un llibre clar, senzill i valent que els nens agrairan haver llegit i que els adults no haurien doblidar mai.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2107, '9788478449668', 'La historia de Troya', 1, '2006', 196, 'The Tale of Troy', 'media/core/9788478449668.jpg', 1, '2023-05-13 09:07:04.458549', '2023-05-13 09:07:04.458549', 1190, 15, 6, 2, 'Las Tres Edades', '', '0101', NULL, 16, 'Escrita con frescura y energía, ésta es la historia de Helena y del juicio de Paris; de la reunión de los héroes y del sitio de Troya; de Aquiles y su vulnerable talón, criado con miel salvaje y médula de león por un centauro; de Odiseo, el último de los héroes, y de su ardid del Caballo de Madera y de las muchas aventuras en su largo viaje de regreso a Grecia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2108, '9788408068402', 'Viaje en el tiempo', 1, '2007', 288, 'Viaggio nel tempo', 'media/core/9788408068402.jpg', 1, '2023-05-13 09:18:26.225988', '2023-05-13 09:18:26.225988', 1191, 48, 6, 2, 'Infantil & juvenil', '', '0101', NULL, 59, 'Partid conmigo en un increíble y superratónico viaje en el tiempo... visitaremos la Prehistoria, el Antiguo Egipto y la Edad Media ¡palabra de Stilton!INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2109, '9782253167464', 'Le second souffle: suivi du Diable gardien', 1, '2011', 254, NULL, 'media/core/9782253167464.jpg', 1, '2023-05-13 09:23:54.645136', '2023-05-13 09:23:54.645136', 1192, 1, 6, 2, 'Le livre de poche', '', '0101', NULL, 424, 'Il est insupportable, vaniteux, orgueilleux, brutal, inconstant, humain. Sans lui, je serais mort de décomposition. Abdel m’a soigné sans discontinuité, comme si j’étais un nourrisson. Attentif au moindre signe, présent, pendant toutes mes absences, il m’a délivré quand j’étais prisonnier, protégé quand j’étais faible. Il m’a fait rire quand je craquais. Il est mon diable gardien. P. P. d. B.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2110, '9782710330400', 'Antigone', 1, '2008', 123, NULL, 'media/core/9782710330400.jpg', 1, '2023-05-13 09:27:35.984259', '2023-05-13 09:27:35.984259', 1193, 41, 6, 2, 'La petite vermillon', '', '0101', NULL, 425, 'Après Sophocle, l''auteur de théâtre reprend le mythe d''Antigone. Fille d''Oedipe et de Jocaste, la jeune Antigone est en révolte contre la loi humaine qui interdit d''enterrer le corps de son frère Polynice. Présentée sous l''Occupation en 1944, cette pièce met en scène l''absolu d''un personnage en révolte face au pouvoir, à l''injustice et à la médiocrité.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2111, '9782070360215', 'Terre des hommes', 1, '2013', 182, NULL, 'media/core/9782070360215.jpg', 1, '2023-05-13 09:29:33.843722', '2023-05-13 09:29:33.843722', 961, 1, 6, 2, 'Collection folio', '', '0101', NULL, 293, '« Il est inexplicable que nous soyons vivants. Je remonte, ma lampe électrique à la main, les traces de l''avion sur le sol. À deux cent cinquante mètres de son point d''arrêt nous retrouvons déjà des ferrailles tordues et des tôles dont, tout le long du parcours, il a éclaboussé le sable. Nous saurons, quand viendra le jour, que nous avons tamponné presque tangentiellement une pente douce au sommet d''un plateau désert. »', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2112, '9782253029496', 'Un sac de billes', 46, '2011', 285, NULL, 'media/core/9782253029496.jpg', 1, '2023-05-13 09:33:15.616512', '2023-05-13 09:33:15.616512', 1194, 1, 6, 2, 'Livre de poche', '', '0101', NULL, 426, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2113, '9788408085812', 'Wicked. Memorias de una bruja mala', 1, '2016', 575, 'Wicked, the life and times of the wicked witch of the west', 'media/core/9788408085812.jpg', 1, '2023-05-13 09:36:16.317336', '2023-05-13 09:36:16.317336', 1195, 1, 6, 2, NULL, '', '0101', NULL, 7, 'No es fácil ser la mala del cuentoINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2114, '9788466332286', 'La verdad sobre el caso Harry Quebert', 1, '2016', 790, 'La Vérité sur l''Affaire Harry Quebert', 'media/core/9788466332286.JPG', 1, '2023-05-13 09:39:22.729701', '2023-05-13 09:39:22.729701', 553, 1, 6, 2, 'Debolsillo', '', '0101', NULL, 11, 'Quién mató a Nola Kellergan es la gran incógnita a desvelar en esta incomparable historia policíaca cuya experiencia de lectura escapa a cualquier tentativa de descripción.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2115, '9788422662556', 'El Aquimista', 1, '1994', 174, 'O Alquimista', 'media/core/9788422662556.jpg', 1, '2023-05-13 09:42:25.989972', '2023-05-13 09:42:25.989972', 1196, 1, 6, 2, NULL, '', '0101', NULL, 427, 'Cuando quieres algo, todo el Universo conspira para ayudarte a conseguirlo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2116, '9788420474472', 'La emperatriz de los Etéreos', 1, '2008', 305, NULL, 'media/core/9788420474472.jpg', 1, '2023-05-13 09:45:39.748053', '2023-05-13 09:45:39.748053', 1197, 1, 6, 2, 'Alfaguara Juvenil', '', '0101', NULL, 10, 'Un libro muy apropiado para recomendar como lectura en el aula por su gran calidad literaria y por valores como la amistad, el amor y los ideales.Bipa no cree en los cuentos de hadas. No le interesa nada más allá de las cuevas donde vive su tribu. En cambio su amigo Aer, el hijo del extranjero, parece que cada vez se aleja más de la realidad y va dejándose absorber por el brillo de la estrella azul… donde dicen que vive la Emperatriz de los Etéreos. ¿Por qué quiere partir si en el exterior sólo hay hielo y al parecer lo único que se encuentra es la muerte? Bipa decide ir tras él para convencerlo de que vuelva. Su amistad puede más que el miedo a todos los peligros que la esperan. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2117, '9788426155597', 'Cuentos por teléfono', 18, '2002', 143, 'Favole al telefono', 'media/core/9788426155597.gif', 1, '2023-05-13 09:51:52.377675', '2023-05-13 09:51:52.377675', 1176, 44, 6, 5, NULL, '', '0101', NULL, 325, 'Érase una vez......una niña cuyo padre tenía que estar de viaje seis días a la semana. Esta niña no podía dormirse sin que le contaran un cuento. Y cada noche, su padre la llamaba por teléfono y le explicaba un cuento. Dicen que los cuentos eran tan buenos que hasta los operarios de la telefónica suspendían todas las llamadas para escucharlos. Y este es el libro de estos cuentos.Gianni Rodari, es uno de los mejores autores de literatura infantil y su obra es reconocida en el mundo entero.', '');
