INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2144, '9788495495273', 'Astronomía de niños', 1, '2002', 56, NULL, 'media/core/9788495495273.jpg', 1, '2023-05-16 10:11:42.542747', '2023-05-16 10:11:42.542747', 1219, 15, 6, 2, NULL, '', '0102', NULL, 440, 'Los padres y los educadores utilizan en muchas ocasiones los dichos y adivinanzas para explicar las cosas del mundo. Pues este libro sigue la misma tónica, pero con dichos y adivinanzas referidos a la Astronomía. Los autores, profesores de Instituto, tienen una dilatada experiencia en educación infantil, lo que hace que el libro, con algunos dibujos sencillos a todo color, sea fácilmente asequible para los niños. Recomendado para 7 / 8 años. Contiene', '');
