INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2149, '9788496295759', 'Nuber y fenómenps meteorológicos. Clasificación, identificación', 1, '2006', 64, NULL, 'media/core/9788496295759.jpg', 1, '2023-05-16 10:39:49.028095', '2023-05-16 10:39:49.028095', 1222, 15, 6, 2, 'Geoestel Guías', '', '0102', '4', 441, 'Guies de camp de petit format, eminentment pràctiques, per a reconèixer les espècies més comunes. O per a conèixer la diversitat de núvols i fenòmens meteorològics que ens afecten. Estructurades en fitxes, de cada espècie s’especifiquen nom comú i cientícic, descripció, localització, floració i preparació, si s’escau.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2150, '9788467217452', 'El cielo', 1, '2009', 32, NULL, 'media/core/9788467217452.jpg', 1, '2023-05-16 10:43:30.970543', '2023-05-16 10:43:30.970543', 572, 18, 6, 2, NULL, '', '0102', NULL, 442, 'Esta guía de campo pretende ser una eficaz ayuda para la observación del cielo nocturno, así como servir de guía sobre los cometas, meteoros, asteroides, planetas, estrellas, galaxias y otros fenómenos del Universo. Nos proporciona, además, consejos sencillos sobre la utilización de binoculares y telescopios y nos conduce finalmente a conocer cómo es un observatorio astronómico de investigación. Para empezar a conocer el cielo contamos con nuestro sentido de la visión que, junto con el estudio de las cartas celestes, nos permitirá conocer la posición de constelaciones, estrellas y planetas. Con este conocimiento básico podremos profundizar con el uso de los binoculares, que permiten apreciar estrellas dobles, variables, nebulosas, cúmulos estelares, algunas galaxias y detalles de la luna. Cuando hayamos reconocido el cielo y estemos seguros de nuestra afición será el momento de adquirir un telescopio. El manejo de este aparato es más complejo, su transporte, cuidados y mantenimiento deben ser rigurosos y su instalación, adecuada alineación y manejo requieren un poco de', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2151, '9788424179854', '¿Qué sabes de el Egipto de los faraones?', 1, '2001', 24, NULL, 'media/core/9788424179854.jpg', 1, '2023-05-16 10:46:18.954525', '2023-05-16 10:46:18.954525', NULL, 15, 6, 2, NULL, '', '0102', NULL, 240, 'Pirámides, jerolíficos y sarcófagos... El antiguo Egipto está lleno de misterios. Juega con este libro y descubre todas las respuestas a tus preguntas.', '');
