INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2154, '9788439212164', 'La Tierra', 1, '2006', 200, NULL, 'media/core/9788439212164.jpg', 1, '2023-05-16 11:01:41.556209', '2023-05-16 11:01:41.556209', 572, 25, 6, 2, NULL, '', '0102', 'Mi primera enciclopedia con Winnie the Pooh y sus amigos', 443, 'Desde los desiertos más secos hasta los mares más profundos, y desde bosques majestuosos hasta extensas praderas, los niños pueden explorar la Tierra y sus numerosos habitantes a través de bellas fotografías y los descubrimientos de Winnie the Pooh y sus amigos. Aprenderán las respuestas a preguntas como: ¿Qué es una tundra? ¿Dónde se encuentran los desiertos? ¿Cómo es la vida bajo el mar?... Éstas son sólo una muestra de los', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2155, '9788434227613', 'Me llamo Miguel de Cervantes', 1, '2005', 64, NULL, 'media/core/9788434227613.jpg', 1, '2023-05-17 06:09:54.370048', '2023-05-17 06:09:54.370048', 1223, 15, 6, 2, NULL, '', '0102', NULL, 442, 'Miguel de Cervantes. El más ilustre de los escritores españoles de todos los tiempos nació en Alcalá de Henares (Madrid), en 1547. Su vida estuvo llena de incidentes, sobresaltos y aventuras, muchas de las cuales se reflejaron en su extensa obra, entre la que destaca El Ingenioso hidalgo don Quijote de la Mancha. Esta novela, uno de los hitos de la literatura universal, trata de las correrías de un hidalgo medio loco que pretende revivir las hazañas de los fabulosos y disparatados libros de caballerías. La obra, que tiene dos partes, mezcla idealismo y realidad con un gran sentido del humor, ironía y ternura.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2156, '9788489589834', '1605 El año que nació Don Quijote', 3, '2005', 24, NULL, 'media/core/9788489589834.jpg', 1, '2023-05-17 06:11:55.508853', '2023-05-17 06:11:55.508853', 569, 15, 6, 2, NULL, '', '0102', NULL, 444, 'Este libro resume de forma amena, con curiosas ilustraciones de la época, todo lo sucedido a lo largo del año y contexto en que Cervantes escribió su obra maestra:- qué sucedió- cómo se vestía- cuánto valían las cosas- qué descubrimientos se hicieron- cómo eran los anuncios- quiénes eran los famosos y otras curiosidades.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2157, '9789776467811', 'الامير الصغير', 1, NULL, 1, 'Le Petit Prince)', 'media/core/9789776467811.jpg', 1, '2023-05-17 06:15:10.008246', '2023-05-17 06:15:10.008246', 961, 1, 6, 2, NULL, '', '0102', NULL, NULL, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2158, '9788449331893', 'El arte de amar', 1, '2021', 175, 'The Art of Loving', 'media/core/9788449331893.jpg', 1, '2023-05-17 06:19:06.407621', '2023-05-17 06:19:06.407621', 1224, 2, 6, 2, 'Nueva Biv¡blioteca Erich Fromm', '', '0102', NULL, 100, 'El arte de amar es el título más relevante de uno de los pensadores alemanes más influyentes del siglo XX: Erich FrommINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2159, '9788484413158', 'Tesoros de Egipto. Manual de aprendizaje', 1, '2006', 32, NULL, 'media/core/9788484413158.jpg', 1, '2023-05-17 06:26:33.493939', '2023-05-17 06:26:33.493939', 1225, 15, 6, 2, NULL, '', '0102', NULL, 445, 'A principios del siglo XX, Emily Snads inició una dura expedición por las tierras del Nilo para encontrar la tumba de Osiris. Frutode su experiencia nació este libro, donde se enumeran las 30 lecciones fundamentales que harán las delicias de los egiptólogos más exigentes.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2160, '9788428531801', 'El gran libro del Prgreso de la humanidad', 1, '2007', 240, 'Il grande libro del Progresso dell''Umanità', 'media/core/9788428531801.jpg', 1, '2023-05-17 06:31:45.641736', '2023-05-17 06:31:45.641736', 1226, 15, 6, 2, NULL, '', '0102', NULL, 446, 'Este gran libro descubre los más destacados progresos de la humanidad desde la Prehistoria hasta nuestros días, pasando por la antigua Roma, Grecia, la edad Media y la revolución industrial, entre otras epocas. Los objetos de la vida cotidiana, la economía, las civilizaciones, el vestido y las casas nos desvelan los significativos avances que el ser humano ha obtenido hasta llegar a nuestros días: el nacimiento de la agricultura en el Neolítico, la práctica de la medicina en Egipto, la navegación fenicia, las armaduras germanas, las especies descubiertas en las Indias, la máquina de vapor, la teoría de la evolución de la especie de Darwin, la abolición de la esclavitud, la bicicleta, el transatlántico, la cámara fotográfica... Una pequeña enciclopedia general s obre los insólitos interrogantes de la ciencia, de la naturaleza, de l a historia, de la geografía y de la economía. Los niños encontrarán en sus páginas numerosos recuadros de profundización así como originales ilustraciones que reflejan todos los temas relacionados con el progreso de la humanidad. Un libro para "detectives" del saber con ganas de ampliar sus conocimientos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2161, '9788434227378', 'China (grandes civilizaciones)', 1, '2007', 32, NULL, 'media/core/9788434227378.jpg', 1, '2023-05-17 06:34:10.422707', '2023-05-17 06:34:10.422707', 572, 15, 2, 2, 'Grandes civilizaciones', '', '0102', NULL, 442, 'En los inmensos territorios del este de Asia, regados por extensos y caudalosos ríos que desembocan en el océano Pacífico, hace más de 9.000 años comenzó la historia de una gran civilización que se prolongó casi hasta nuestros días. En el año 7000 a.C. empezaron a sentarse las bases para la aparición del gran imperio chino, que se extinguió en 1911 tras el derrocamiento del último emperador. Bajo el dominio de los emperadores se desarrolló una sociedad minuciosamente estructurada y florecieron todas las artes. Los chinos fueron bravos guerreros, pero también llevaron el arte de la pintura, de la literatura o de la filosofía a sus cotas más altas. Y los excelentes artesanos del país supieron convertir en pequeñas obras de arte objetos cotidianos. Por todo ello queremos despertar en los jóvenes lectores el interés por la apasionante civilización china mediante una breve introducción histórica y once temas en los que se abordan con textos e imágenes algunos de los aspectos más importantes de esa cultura milenaria. La imagen central permite hacerse una idea inmediata del tema tratado mientras que los textos, informativos y anecdóticos al mismo tiempo, proporcionan los conocimientos básicos sobre la cuestión. Al final se presenta como aportación complementaria una cronología con los principales períodos de la historia china y un pequeño compendio de curiosidades.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2162, '9788437224749', 'Antigua China', 1, '2007', 48, NULL, 'media/core/9788437224749.jpg', 1, '2023-05-17 06:36:54.573387', '2023-05-17 06:36:54.573387', 572, 15, 6, 2, 'Cómo y Por qué', '', '0102', NULL, 447, 'Los chinos erigieron la construcción más grande de la historia, inventaron la pólvora y fueron los primeros en utilizar una brújulo. Sus emperadores gobernaron un Imperio poderoso, el más antiguo del mundo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2163, '9788467029383', 'Mi primer libro de la Prehistoria', 1, '2008', 55, NULL, 'media/core/9788467029383.jpg', 1, '2023-05-17 06:41:54.336668', '2023-05-17 06:41:54.336668', 287, 15, 6, 2, NULL, '', '0102', NULL, 18, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2164, '9788484412359', 'El gran libro de los dragones', 1, '2004', 32, NULL, 'media/core/9788484412359.jpg', 1, '2023-05-17 06:46:14.305065', '2023-05-17 06:46:14.305065', 1227, 15, 6, 2, NULL, '', '0102', NULL, 445, 'Vive Dios que no ha pisado la Tierra bestia equiparable al poderoso dragón en lo que a fuerza y majestuosidad se refiere, y pocas hay en ella tan dignas de los diligente estudios de los hombres sabios.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2165, '9788484412649', 'Dragones. Manual de aprendizaje', 1, '2005', 72, NULL, 'media/core/9788484412649.jpg', 1, '2023-05-17 06:48:23.173038', '2023-05-17 06:48:23.173038', 1227, 38, 6, 2, NULL, '', '0102', NULL, 445, '¿Estás preparado para saber todo sobre los dragones? Después de El gran libro de los dragones, que publicó editorial Montena el año pasado, el Dr, Ernest Drake te ofrece un testimonio único para convertirte en un experto draconólogo. Estas notas, divididas en 21 lecciones más ejercicios prácticos, te darán el diploma de honor que te acreditará como miembro de la Secreta y Ancestral Sociedad de Draconólogos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2166, '9788425344343', 'Enigmas y juegos de ingenio para romperte la cabeza', 1, '2010', 304, 'The gratest puzzles ever solved', 'media/core/9788425344343.jpg', 1, '2023-05-17 06:51:25.590458', '2023-05-17 06:51:25.590458', 1228, 38, 6, 2, NULL, '', '0102', NULL, 45, '¿Sabías que, igual que la actividad física, el ejercicio mental nos puede proporcionar una sensación de éxito, mejorar nuestro humor, y hasta causarnos un intenso placer? Este libro pretende poner a prueba tu agilidad mental. Para ello te propone un viaje fascinante a través de diferentes épocas, desde el clásico enigma de la esfinge y los acertijos de las antiguas dinastías chinas hasta los tan exitosos sudokus de hoy. Conocerás ingeniosas adivinanzas, rompecabezas, acertijos, enigmas y pasatiempos #algunos de ellos aún sin resolver#, que te ayudarán a fortalecer tu «musculatura mental» y poner tu cerebro en forma.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2167, '9788466636957', 'La misteriosa Sociedad Benedict', 1, '2008', 416, 'The Mysterious Benedict Society', 'media/core/9788466636957.jpg', 1, '2023-05-17 07:08:47.152184', '2023-05-17 07:08:47.152184', 1229, 1, 6, 2, NULL, '', '0102', NULL, 8, 'Después de varias páginas más de preguntas, que Reynie estaba seguro de haber contestado bien en su totalidad, llegó a la última pregunta del examen: «¿Eres valiente?» La señorita Perumal habría dicho que lo era; él en cambio pensaba que no. Al final, viendo que no podía decidirse, escribió: «Espero que sí.» Su respuesta lo condujo junto a otros tres niñosa una misión secreta que sólo los más inteligentes y agudos podrían completar. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2168, '9788420403540', 'Las ventajas de ser un marginado', 1, '2012', 264, 'The Perks  of Being a Wallflower', 'media/core/9788420403540.jpg', 1, '2023-05-17 07:11:36.499744', '2023-05-17 07:11:36.499744', 1230, 1, 6, 2, NULL, '', '0102', NULL, 10, 'Charlie, un chico ingenuo, mordaz y solitario, acaba de empezar el  instituto. Vive con sus padres, su popular hermana y un hermano mayor  que está a punto de comenzar la universidad. La cosa no pinta demasiado  bien el primer día de instituto cuando solo consigue hacer un amigo: un  alternativo profesor de Lengua interesado en despertar el genio creativo de Charlie.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2169, '9788467228304', 'La invención de Hugo Cabret', 1, '2007', 534, NULL, 'media/core/9788467228304.jpg', 1, '2023-05-17 07:24:07.571801', '2023-05-17 07:24:07.571801', 1231, 1, 6, 2, NULL, '', '0102', NULL, 448, 'Una novela que combina una interesante historia con 284 magníficas ilustraciones originales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2170, '9788478447909', 'Corazón de tinta', 11, '2008', 608, 'Tintenherz', 'media/core/9788478447909.jpg', 1, '2023-05-17 07:27:30.993895', '2023-05-17 07:27:30.993895', 1232, 1, 6, 2, 'Las Tres Edades', '', '0102', NULL, 16, 'Quiénes son de verdad Dedo Polvoriento, Capricornio o Lengua de Brujo lo sabrá la joven Meggie por las respuestas que encuentre en un viejo pueblo de las montañas de Liguria... y también en un libro. Cuando Mo, el padre de Meggie, saluda a un extraño visitante que aparece en su casa, la niña siente que aquella persona emana un peligro, quizá una gran amenaza contra su padre... y entonces huyen al sur, a la casa de tía Elinor, propietaria de una de las más fascinantes bibliotecas que uno pueda imaginar. Meggie descubrirá que los forasteros que misteriosamente aparecen y desaparecen, como aquel visitante nocturno, llaman a su padre Lengua de Brujo, ya que tiene el don de dar vida a los personajes de los libros cuando lee en voz alta.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2171, '9788427950047', 'Despereaux', 1, '2004', 240, 'The Tale of Despereaux', 'media/core/9788427950047.jpg', 1, '2023-05-17 07:30:10.472758', '2023-05-17 07:30:10.472758', 1233, 1, 2, 2, NULL, '', '0102', NULL, 414, 'Edward Tulane es un conejo de porcelana amado por una niña de bien. En un viaje a través del océano, el conejo se cae por la borda del barco y es rescatado por un pescador. Viaja durante mucho tiempo con los vagabundos y hasta trabaja durante poco tiempo de espantapájaros. Siempre escucha las esperanzas, sueños e historias de los demás. Aprende a amar, a perder, y a amar de nuevo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2172, '9788420470955', 'El superzorro', 2, '2010', 112, 'Fantastic Mr. Fox', 'media/core/9788420470955.jpg', 1, '2023-05-17 07:32:26.943417', '2023-05-17 07:32:26.943417', 1173, 1, 6, 2, 'Biblioteca Roald Dahl', '', '0102', NULL, 10, 'Benito, Buñuelo y Bufón son los tres granjeros más malvados que te puedas imaginar. Odian a don Zorro y quieren capturarle por todos los medios. Le esperan a la salida de su madriguera, escondidos detrás de los árboles, con la escopeta cargada. Pero don Zorro tiene otros planes... Descubre lo que les tiene preparado en esta aventura llena de ritmo y humor, ilustrada, por primera vez en español, con dibujos de Quentin Blake.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2173, '9788427950368', 'El prodigioso viaje de Edward Tulane', 1, '2007', 196, 'The Miraculous Journey of Edward Tulane', 'media/core/9788427950368.jpg', 1, '2023-05-17 07:35:03.184853', '2023-05-17 07:35:03.184853', 1233, 1, 6, 2, NULL, '', '0102', NULL, 414, 'Un historia singular que te atará hasta la última página.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2174, '9788466740104', 'La pequeña cerillera y otros cuentos', 1, '2004', 341, 'Samlede Eventyr of Historier', 'media/core/9788466740104.jpg', 1, '2023-05-17 07:47:10.566261', '2023-05-17 07:47:10.566261', 1234, 44, 6, 2, NULL, '', '0102', 'Cuentos completos II', 66, 'Se cumplen doscientos años del nacimiento de Hans Christian Andersen (Odense, 1805). Con este motivo, anaya Infantil y Juvenil edita cuatro volúmenes con los Cuentos completos de Andersen. Cada uno de los volúmenes va a precedido de un prólogo a cargo de prestigiosos autores vinculados, profesional o personalmente, a estos cuentos: Fernando Savater, Gustavo Martín Garzo, José María Merino y Carmen Posadas. Las ilustraciones, otro aspecto especialmente importante en esta edición, corren a cargo de cuatro profesionales de una calidad excepcional: Pablo Auladell, Elena Odriozola, Carmen Segovia y Javier Sáez Castán. Estos cuentos contienen numerosos elementos autobiográficos, aunque pueden leerse y apreciarse perfectamente sin saber nada de la vida de su autor. La mayoría de ellos fueron creados por él, pero también hay adaptaciones de cuentos populares, como El traje nuevo del emperador. Junto a la obra de los hermanos Grimm y a la de Perrault, los cuentos de Andersen se han transmitido de generación en generación, y ya forman parte del acervo cultural de nuestra sociedad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2175, '9788422688174', 'Alicia en el País de las Maravillas', 1, '1999', 207, 'Alice''s Adventures in Wonderland', 'media/core/sin-imagen_iOtcAZX.jpg', 1, '2023-05-17 07:51:52.855599', '2023-05-17 07:51:52.855599', 1167, 1, 6, 2, NULL, '', '0102', NULL, 449, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2176, '9788483060650', 'Cuentos completos', 8, '1988', 400, NULL, 'media/core/9788483060650.jpg', 1, '2023-05-17 07:55:40.643887', '2023-05-17 07:55:40.643887', 1235, 44, 6, 2, NULL, '', '0102', NULL, 97, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2177, '9788422686927', 'Cuentos para ir a dormir', 1, '1994', 128, 'Going-to-bed tales', 'media/core/9788422686927.jpeg', 1, '2023-05-17 08:00:14.425807', '2023-05-17 08:00:14.425807', 1236, 44, 6, 2, NULL, '', '0102', NULL, 450, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2178, '9788423683758', 'La Odisea contada a los niños', 1, '2007', 214, NULL, 'media/core/9788423683758.jpg', 1, '2023-05-17 08:03:15.259800', '2023-05-17 08:03:15.259800', 1237, 48, 6, 2, NULL, '', '0102', NULL, 56, 'En este bellísimo relato se narran las aventuras que vive Ulises navegando por el mar Mediterráneo. Enormes tempestades azotan su nave porque el dios del mar, Poseidón, no le quiere nada. Sin embargo, le protege la diosa de la sabiduría, Atenea. Mientras tanto, en su tierra, la isla Ítaca, le están esperando su fiel esposa, Penélope, y su hijo Telémaco, que irá en busca de noticias suyas. Pero también se han instalado en Ítaca los odiosos pre-tendientes de Penélope, que quieren convencerla de que su marido ha muerto y que se pasan el día en el palacio del héroe comiendo y bebiendo… Aunque nada se sabe con certeza, parece que hacia el siglo VIII antes de Cristo, un juglar griego llamado Homero -del que se dice que era ciego- compuso esta historia, la Odisea, que cuenta las aventuras que vivió Ulises desde que se marchó de Troya -acabada la guerra- hasta que llegó, veinte años después, a su patria, Ítaca. La Odisea es un poema maravilloso, que fue compuesto hace muchos, muchísimos años: ¡casi tres mil! La Odisea está escrita en griego, en 12.110 versos. Lectura recomendada a partir de 6 años.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2179, '9788423673810', 'El Quijote contado a los niños', 2, '2005', 196, NULL, 'media/core/9788423673810.jpg', 1, '2023-05-17 08:05:21.083643', '2023-05-17 08:05:21.083643', 1237, 48, 6, 2, NULL, '', '0102', NULL, 56, 'La historia del caballero manchego ha sido contada por la especialista en literatura española del Siglo de Oro, la catedrática Rosa Navarro Durán, con palabras sencillas nacidas de un profundo respeto y fidelidad por el original. La obra incluye todos los capítulos fundamentales de la historia y está estructurada en dos partes como el original.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2180, '9788423678891', 'El Lazarillo contado a los niños', 1, '2006', 166, NULL, 'media/core/9788423678891.jpg', 1, '2023-05-17 08:07:12.515365', '2023-05-17 08:07:12.515365', 1237, 48, 6, 2, NULL, '', '0102', NULL, 56, 'La autora nos trae la magia de las obras clásicas y las deja a buen recaudo de los más pequeños. El libro cuenta con las bellas ilustraciones del dibujante Francesc Rovira y nos empapan de múltiples aventuras. El Lazarillo de Tormes narra las fortunas y adversidades del joven de Tormes. Una obra que dio origen a la novela picaresca.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2181, '9788494033643', 'Fausto', 1, '2020', 261, 'Faust', 'media/core/9788494033643.jpg', 1, '2023-05-17 08:12:02.228526', '2023-05-17 08:12:02.228526', 1238, 4, 6, 2, NULL, '', '0102', NULL, 451, 'En 1925, y tras el gran éxito que tuvieron sus ilustraciones para  la obra Cuentos de imaginación y misterio de Edgar Allan Poe, la  editorial George H. Harrap le encargó al vitralista e ilustrador  irlandés Harry Clarke la que sería, en su propia opinión, su obra  más lograda, y probablemente también la más famosa: las casi  80 imágenes para una de las obras cumbre de la literatura universal,  el poema dramático Fausto, de Johann Wolfgang von  Goethe. La delicada y virtuosa ejecución, unida a una estética  que prefigura el Art Nouveau y la psicodelia y a una imaginación  que no rehuye lo siniestro y lo bizarro, hacen que las estampas  de Clarke conviertan la lectura del gran', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2182, '9781408704202', 'The Casual Vacancy', 1, '2012', 503, NULL, 'media/core/9781408704202.jpg', 1, '2023-05-17 08:14:53.006133', '2023-05-17 08:14:53.006133', 798, 1, 6, 2, NULL, '', '0102', NULL, 452, 'When Barry Fairweather dies unexpectedly in his early forties, the little town of Pagford is left in shock. Pagford is, seemingly, an English idyll, with a cobbled market square and an ancient abbey, but what lies behind the pretty façade is a town at war. Rich at war with poor, teenagers at war with their parents, wives at war with their husbands, teachers at war with their pupils...Pagford is not what it first seems. And the empty seat left by Barry on the parish council soon becomes the catalyst for the biggest war the town has yet seen. Who will triumph in an election fraught with passion, duplicity and unexpected revelations? Blackly comic, thought-provoking and', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2183, '9788466752138', 'El viento en los sauces', 1, '2006', 207, 'The Wind in the Willous', 'media/core/9788466752138.jpg', 1, '2023-05-17 08:17:57.203121', '2023-05-17 08:17:57.203121', 1239, 48, 6, 2, NULL, '', '0102', NULL, 66, 'El viento en los sauces, sin duda unos de los clásicos de la literatura infantil universal, nos presenta el pequeño universo en el que unos personajes entrañables —el fiel Topo, la inteligente Rata de Agua, el enloquecido Sapo y el sensato Tejón— nos ofrecen una exacta metáfora sobre los usos y costumbres de la Inglaterra victoriana de principios del siglo XX.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2184, '9788467505030', 'Cómo entrenar a tu dragón', 1, '2005', 221, 'How to Train Your Dragon', 'media/core/9788467505030.jpg', 1, '2023-05-17 08:20:57.179882', '2023-05-17 08:20:57.179882', 1240, 48, 6, 2, NULL, '', '0102', NULL, 417, 'En la época de los vikingos todos los adolescentes debían demostrar sus habilidades cazando y entrenando a un dragón. Hipo Horrendo Abadejo III no fue una excepción.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2185, '9788496710320', 'Los gigantes de Groil', 1, '2007', 191, NULL, 'media/core/9788496710320.jpg', 1, '2023-05-17 08:24:42.918227', '2023-05-17 08:24:42.918227', 1241, 48, 11, 2, 'Infantil y Juvenil', '', '0102', NULL, 68, '¡Una aventura gigante para gente pequeña! á Desde el país de los gigantes, Groil, una chica llamada Jumbelia se muere de ganas de conocer a la gente pequeña, los dimiplops. La mayoría de los gigantes no cree que los dimiplops existen, y allá abajo, en la tierra, los humanos tampoco creen en los gigantes. ¿Serán muy muy dimis? ¿Igual de dimis que su dedo dimi? Jumbelia sabe que plantando una habichuela gigante en el país de los dimiplops podrá descender hasta allí a traves de su tallo y coleccionar cosas de ese mundo tan pequeño.  Mientras ella baja por el abimplant, los hemanos Jones juegan en el jardín de su casa y no saben que están a punto de encontrarse con un problema gigante. á á  “Los Gigantes de Groil tiene humor, suspense y un idioma inventado que cautiva.” The Evening Standard á Los gigantes de Groil es', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2186, '9788420456027', 'Las madres', 1, '2022', 464, NULL, 'media/core/9788420456027.jpg', 1, '2023-07-11 05:58:55.323106', '2023-07-11 06:06:13.624918', 3, 14, 6, 5, NULL, '', '07_05', 'La novia gitana 4', 10, 'La inspectora Elena Blanco atraviesa el depósito de la Grúa Municipal  Mediodía II de Madrid hasta llegar a una vieja furgoneta que expele un  olor putrefacto. Dentro está el cadáver de un hombre con un burdo  costurón que asciende del pubis al abdomen. Los primeros resultados de  la autopsia aclaran que a este toxicómano le arrancaron algunos órganos  y en su lugar colocaron un feto. Los análisis de ADN revelan que se  trata de su hijo biológico. A los pocos días, aparece en la zona portuaria de A Coruña el cuerpo de un asesor fiscal que ha sido  asesinado con el mismo modus operandi. ¿Qué relación existe entre ambas  víctimas? ¿Y dónde están las madres de los bebés? Se abre así la  investigación del nuevo y perturbador caso de la Brigada de Análisis de  Casos. Mientras la relación entre Elena y Zárate se hace cada vez más  complicada, todos los indicios los acercarán a una misteriosa organización a la que nadie parece poder acercarse sin morir.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2187, '9788408262848', 'La Bestia', 1, '2022', 544, NULL, 'media/core/9788408262848.jpg', 1, '2023-07-11 06:01:15.925592', '2023-07-11 06:05:28.219517', 3, 14, 6, 5, NULL, '', '07_05', NULL, 7, 'Corre el año 1834 y Madrid, una pequeña ciudad que trata de abrirse paso más allá de las murallas que la rodean, sufre una terrible epidemia de cólera. Pero la peste no es lo único que aterroriza a sus habitantes: en los arrabales aparecen cadáveres desmembrados de niñas que nadie reclama. Todos los rumores apuntan a la Bestia, un ser a quien nadie ha visto pero al que todos temen.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2188, '9788417805838', 'La vida no regalada', 1, '2021', 300, NULL, 'media/core/9788417805838.jpg', 1, '2023-07-17 17:36:21.362295', '2023-07-17 17:36:21.362295', 1242, 1, 6, 5, NULL, '', '07_05', NULL, 30, 'La vida no regalada es una novela sin ficción que narra la evolución de España desde los últimos años de la Dictadura hasta llegar a la Transición, a través de la vida de su protagonista, Lorenzo Almendro; el día a día de un niño de un pueblo de Jaén que emigra con sus padres a Barcelona durante los años 60 y se establecen en el barrio de Verdún.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2189, '9788419075796', 'Dioses útiles. Naciones y nacionalismos', 7, '2022', 336, NULL, 'media/core/9788419075796.jpg', 1, '2023-07-22 06:27:14.302101', '2024-01-30 16:49:38.106061', 1243, 2, 6, 5, NULL, '', '07_03', NULL, 346, 'Pocos problemas histórico-políticos habrán experimentado una revolución en su tratamiento por parte de historiadores y científicos sociales comparable a la sufrida por el nacionalismo en las últimas décadas. De ahí que José Álvarez Junco dedique el primer capítulo de este libro a exponer las teorías actuales en torno a naciones y nacionalismos y a proponer unas definiciones iniciales de términos. Recorre, a continuación, los casos de construcción nacional más relevantes, tanto europeos (Inglaterra, Francia, Alemania, Italia, Rusia y el Imperio turco) como de algunas excolonias europeas (Estados Unidos e Iberoamérica). En el tercer capítulo analiza el caso español, que recibe nueva luz al explicarlo en términos comparados. La identidad española, como cualquier otra, es una construcción histórica, producto de múltiples acontecimientos y factores, algunos estructurales pero en su mayoría contingentes. Es decir, que no hay nada atribuible a designios providenciales o misteriosos, ni tampoco a un genio colectivo que habite desde hace milenios en los nativos del país. El libro finaliza con un capítulo en el que describe la construcción de identidades nacionales alternativas a la española en la península Ibérica, comenzando por Portugal y siguiendo por los casos catalán, vasco, gallego y andaluz. El surgimiento y la evolución de las naciones se anclan en factores políticos, económicos o culturales que, en mayor o menor grado, se encuentran también en todas las demás. Por tanto, la distancia y la comparación son, para Álvarez Junco, la actitud y el método más recomendables para comprender adecuadamente problemas políticos o históricos como los que aborda en este libro. Y evitar la emoción es justamente lo que él intenta hacer aquí: racionalizar un problema que es presa habitual de la emocionalidad; someter los sentimientos a la razón, en lugar de, como tantas veces ocurre, poner la razón al servicio de los sentimientos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2190, '9788416620012', 'Breviario de la dignidad humana', 4, '2015', 88, NULL, 'media/core/9788416620012.jpg', 1, '2023-07-22 06:31:11.958844', '2023-07-22 06:31:11.958844', 842, 36, 6, 5, NULL, '', '07_05', NULL, 453, 'SINOPSIS Esta obra es un homenaje a la trayectoria intelectual y vital de Albert Camus con motivo del centenario de su nacimiento. A través de los propios textos del autor, este singular breviario pone de manifiesto el coraje y la lucidez de un escritor excepcional. En Albert Camus. Breviario de la dignidad humana se recogen fragmentos, cuidadosamente elegidos y traducidos por Elisenda Julibert, de las novelas, los ensayos y los diarios de un hombre cuya extraordinaria dignidad lo convierte en un referente moral de nuestra época.  COMPILADORA Elisenda Julibert, que ha realizado y traducido la presente selección de textos, es licenciada en Filosofía, editora y traductora. Albert Camus (Argelia, 1913 - Francia, 1960) fue un novelista, ensayista, dramaturgo y filósofo francés.  En su variada obra desarrolló un humanismo fundado en la conciencia del absurdo de la condición humana. En 1957, a la edad de 44 años, se le concedió el Premio Nobel de Literatura por "el conjunto de una obra que pone de relieve los problemas que se plantean en la conciencia de los hombres de hoy".', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2191, '9788498929713', '1177 a.C. El año en que la civilización se derrumbó', 6, '2016', 360, '1177 B.C. The year civilization collapsed', 'media/core/9788498929713.jpg', 1, '2023-07-22 06:35:31.164503', '2023-07-22 06:35:31.164503', 1244, 15, 6, 5, 'Tiempo de Historia', '', '07_05', NULL, 61, 'En el año 1177 antes de Cristo unos merodeadores de origen desconocido, los llamados «pueblos del mar», llegaron a Egipto, tras causar destrucción y muerte por donde pasaban. Esto sucedía en el inicio de una época de colapso en que desaparecieron las grandes civilizaciones de la Edad del Bronce -egipcios, hititas, micénicos, troyanos, asirios…- en lo que Finkelnstein describe como «uno de los más misteriosos procesos de la historia de la humanidad». ¿Cuál fue la causa de este cataclismo? Eric H. Cline, de la Universidad George Washington, un arqueólogo que ha investigado este tema durante más de veinte años, responde que el fracaso se debió a une serie de causas conectadas entre sí: invasiones, revueltas, terremotos, y, sobre todo, la ruptura de un sistema de relaciones en un mundo que había alcanzado un notable grado de globalización. Algo que nos recuerda los riesgos que amenazan hoy a nuestro propio mundo. Cline pone al alcance del lector medio los más recientes hallazgos de la investigación en un relato realmente apasionante.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2192, '9788498388244', 'El homenaje', 1, '2017', 80, 'La targa', 'media/core/9788498388244.jpg', 1, '2023-07-26 16:54:19.199468', '2023-07-26 16:54:19.199468', 9, 1, 6, 5, NULL, '', '07_03', NULL, 29, 'En este inteligente y divertidísimo relato cargado de ironía, Andrea Camilleri apunta, una vez más, a la cara más absurda del ser humano. Como en la mejor obra de teatro, las intenciones de los personajes se revelan ante nuestros ojos a través de las mentiras que profieren sin pudor y, entre una maraña de leyendas engañosas y honores trasnochados, la realidad termina asomando la cabeza y delatando a los farsantes. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2193, '9788423433322', 'Nadie nace en un cuerpo equivocado. Éxito y miseria de la identidad de género', 12, '2022', 296, NULL, 'media/core/9788423433322.jpg', 1, '2023-07-29 06:17:55.143916', '2023-07-29 06:17:55.143916', 1245, 2, 6, 5, NULL, '', '06_02', NULL, 57, 'El análisis más profundo sobre la identidad de género y la teoría queerINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2194, '9788497594257', 'Un mundo feliz', 1, '2003', 256, 'Brave New World', 'media/core/9788497594257.jpg', 1, '2023-07-29 06:22:52.779410', '2023-07-29 06:22:52.779410', 1246, 29, 6, 5, 'Contemporánea', '', '07_03', NULL, 204, 'Los peores vaticinios del capitalismo se han cumplido: triunfan los dioses del consumo y la comodidad, y el orbe se divide en diez zonas en apariencia seguras y estables. Los humanos ya no procrean, el sexo se ha convertido solo en una diversión y las letras del alfabeto griego se han pervertido para clasificar a los seres humanos por castas. Todos aceptan su lugar en la nueva jerarquía social, perfectamente ordenada. Los valores humanos esenciales no tienen cabida en este mundo y los habitantes se crean in vitro con una técnica concebida a imagen y semejanza de una cadena de montaje. El soma, la droga por excelencia en este mundo distópico que propone Huxley, ayuda a los habitantes a escapar de la rutina. A cambio de este orden pulcro, la libertad de expresión y el pensamiento crítico han sido erradicados. Bernard Marx, el protagonista de la novela, inconformista e inteligente, deberá probar los límites de la sociedad que lo ha engendrado, iniciando un viaje más allá de las fronteras distópicas de su universo.', '1ª edición en inglés, 1969');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2195, '9788441543348', 'Curso intensivo de Python. Introducción práctica a la programación basada en proyectos', 2, '2021', 544, 'Python Crah Course', 'media/core/9788441543348.jpg', 1, '2023-08-04 17:11:42.345844', '2023-08-04 17:11:42.345844', 1247, 24, 6, 5, 'Anaya Multimedia', '', '04_07', NULL, 66, 'Este superventas es una guía imprescindible del lenguaje de programación Python. Una introducción rápida a la programación con Python con la que no tardará nada en empezar a escribir programas, resolver problemas y hacer cosas que funcionen.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2196, '9788494561924', 'Nosotros', 1, '2016', 200, 'Mbl', 'media/core/9788494561924.jpg', 1, '2023-08-23 17:34:14.931612', '2023-08-23 17:34:37.648862', 1248, 13, 6, 5, NULL, '', '07_02', NULL, 348, 'La novela "Nosotros" refleja las terribles consecuencias de los regímenes totalitarios que al comienzo del siglo XX se encontraban en pleno auge. En el futuro nuestro estilo de vida en sociedad basado en la «libertad individual» es un estilo de vida salvaje, desorganizado y nómada. En esta sociedad del futuro los sueños constituyen una grave enfermedad psíquica, la libertad sexual es vista como un acto practicado por bestias salvajes, y la libertad personal, está estrechamente vinculada al crimen.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2197, '9788492672660', 'Pigmalió', 1, '2010', 176, NULL, 'media/core/9788492672660.jpeg', 1, '2023-09-01 16:34:38.382598', '2023-09-01 16:35:40.388902', 1249, 41, 6, 2, 'Col.lecció Educació 62', '', '01_03', NULL, 2, 'Pigmalió (1957) es una versió lliure de l''obra homonima de Bernard Shaw. Martí Jordana, famós i expert professor de fonetica, accepta la "juguesca" que li proposa el coronel Fontanella de transformar Roseta Fernandes, una florista inculta i de baixa extracció social, en una dama de l''alta societat. L''"experiment" funciona be, pero, com en el text adaptat, Oliver subverteix el final feliç del mite clàssic. Introducció, propostes de treball, activitats i materials complementaris a cura de Dolors Madrenas Tinoco, professora de Llengua i literatura en l''ensenyament secundari. És autora del volum Va de broma? Aproximació a la parodia literària (1999).á', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2198, '9788415954101', 'Bearn o la sala de les nines', 2, '2015', 386, NULL, 'media/core/9788415954101.jpg', 1, '2023-09-01 16:38:58.072059', '2023-09-01 16:38:58.072059', 1250, 1, 6, 2, 'Col.lecció Educació 62', '', '01_03', NULL, 2, 'La introducció és una carta que el narrador de la novel·la, Joan Mayol, capellà de la casa i molt possiblement fill natural del senyor de Bearn, escriu a Miquel Gelabert, un antic company de seminari que és ara secretari del cardenal primat. La carta està datada a Bearn el 1890, transcorreguts dos mesos des de la mort dels senyors. Mayol desitja sotmetre la consideració dels seus superiors clergues si deu o no obeir l''última voluntat del difunt senyor de Bearn, que més tard se sabrà que consisteix en la publicació de les seves memòries. Per a això adjunta un manuscrit (la resta de la novel·la), on relata la seva vida a Bearn i la fascinació que va sentir per la personalitat de don Toni.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2199, '9788415192923', 'El Cafè de la Marina', 2, '2013', 271, NULL, 'media/core/9788415192923.jpg', 1, '2023-09-01 16:42:51.116094', '2023-09-01 16:42:51.116094', 1251, 41, 6, 5, 'Col.lecció Educació 62', '', '01_03', NULL, 2, 'El Cafè de la Marina (1933) constitueix una fita en la producció dramàtica de Sagarra: un títol ben representatiu del"poema dramàtic", el gènere característic de lescriptor barceloní, alhora que un dels seus grans èxits de taquilla. Shi recreen el món i lambient mariners, condensats entre les quatre parets duna taverna de pescadors, en un poble costaner, vora el cap de Creus: un microcosmos on convergeixen vides pobres, monòtones, escarrassades. Vet aquí lescenari que emmarca una trama amorosa clàssica: el pare interessat que acorda lliurar la filla a un pretendent ric però repulsiu, contra la voluntat della i les esperances dun aspirant jove, preferit pel cor de la noia. Hi ha, doncs, un triangle sentimental, rivalitat eròtica, passió latent. A més duna galeria de personatges secundaris i dun llenguatge popular viu que, a parer unànime de la crítica, suposen dos mèrits importants, destacables entre altres encerts, dun clàssic de la dramatúrgia catalana.Estudi preliminar, propostes de treball, comentaris de text i material complementari a cura dEnric Martín, professor de lInstitut Jaume Callís de Vic i de la Universitat de Vic.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2200, '9788429719444', 'Mirall trencat', 12, '1991', 297, NULL, 'media/core/9788429719444.jpg', 1, '2023-09-01 16:48:07.749499', '2023-09-01 16:48:07.749499', 858, 1, 6, 2, 'Les millors obres de lla literatura catalana', '', '01_03', NULL, 2, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2201, '9788494201868', 'La piqueta', 1, '2014', 179, NULL, 'media/core/9788494201868.jpg', 1, '2023-09-01 16:51:07.185865', '2023-09-01 16:51:07.185865', 1252, 1, 6, 2, NULL, '', '01_03', NULL, 454, 'En La piqueta encontramos al mejor Ferres, con sus tintes barojianos, y sus reminiscencias de Ignacio Aldecoa, pero siempre singular e inconfundible. Novela aclamada por la crítica tras su publicación, consagró definitivamente a su autor, y está considerada como un clásico del siglo XX. La calidad literaria de La piqueta hace de ella una lectura absolutamente actual para cualquier tipo de público. La atmósfera creada alrededor del angustioso hecho anunciado desde la primera página, el magistral juego con los tiempos, el ritmo narrativo, el acierto en el trazo de los perfiles de los personajes, la complicidad que crea con los protagonistas del drama, atrapan al lector desde el principio, lo implican en la trama, y le hacen sentirse parte de ella.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2202, '9788483461396', 'Todas las almas', 5, '2013', 226, NULL, 'media/core/9788483461396.jpeg', 1, '2023-09-01 16:54:18.725662', '2023-09-01 16:54:18.725662', 1253, 1, 6, 2, 'Debolsillo', '', '01_03', NULL, 11, 'Todas las almas cuenta la historia de los dos brumosos y  singulares años que el narrador pasó en la Universidad de Oxford, una ciudad fuera del mundo y del tiempo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2203, '9788490628102', 'Últimas tardes con Teresa', 1, '2015', 471, NULL, 'media/core/9788490628102.jpg', 1, '2023-09-01 16:57:30.574232', '2023-09-01 16:57:30.574232', 216, 1, 6, 2, 'Debolsillo', '', '01_03', NULL, 11, 'Ambientada en una Barcelona de claroscuros y contrastes, Últimas tardes con Teresa narra los amores de Pijoaparte, típico exponente de las clases más bajas marginadas cuya mayor aspiración es alcanzar prestigio social, y Teresa, una bella muchacha rubia, estudiante e hija de la alta burguesía catalana. Los personajes de esta novela a la vez romántica y sarcástica pertenecen ya, por derecho propio, a la galería de retratos que configuran toda una época...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2204, '9788472237964', 'Historia de una gaviota y del gato que le enseñó a volar', 68, '2016', 138, NULL, 'media/core/9788472237964.jpeg', 1, '2023-09-01 17:00:52.844049', '2023-09-01 17:00:52.844049', 1254, 1, 6, 2, 'Colección Andanzas', '', '01_03', NULL, 12, 'Luis Sepúlveda, a quien el público de lengua española ya conoce bien, tiene dos hijos muy jóvenes, a quienes llama «mis enanos» y a quienes prometió un día escribir una historia acerca de lo mal que gestionamos los humanos nuestro propio entorno, lesionando la naturaleza, que nos brinda tantos bienes, y de paso autolesionándonos sin piedad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2205, '9788408067610', 'El príncipe de la niebla', 1, '2009', 230, NULL, 'media/core/9788408067610.jpg', 1, '2023-09-01 17:03:20.054343', '2023-09-01 17:03:20.054343', 1007, 1, 6, 2, NULL, '', '01_03', NULL, 7, 'El primer gran éxito de Carlos Ruiz Zafón.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2206, '844730020X', 'Las edades de Lulú', 1, '1992', 256, NULL, 'media/core/sin-imagen_Qfwfp5H.jpg', 1, '2023-09-01 17:06:53.842102', '2023-09-01 17:06:53.842102', 965, 1, 6, 2, NULL, '', '01_03', NULL, 32, 'Una larga historia de amor que, como cualquier historia de amor y de sexo que no se resigna a dejar de serlo, va haciéndose más compleja y envolvente.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2207, '9788437615943', 'Sab', 13, '2018', 275, NULL, 'media/core/9788437615943.jpg', 1, '2023-09-01 17:11:01.721095', '2023-09-01 17:11:01.721095', 1255, 1, 6, 2, 'Letras hispánicas', '', '01_03', NULL, 153, '"Sab" constituye una singular aportación a la novela antiesclavista. La autora sigue en ella los modelos típicos de la novela romántica y mezcla reminiscencias autobiográficas y modelos literarios. Hay en ella alegato reivindicador de la dura vida de los negros, solidaridad con los indios víctimas de la barbarie española y compromiso en el sentimiento y pasión por dar un testimonio social.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2208, '9788497593885', 'Paula', 1, '1998', 433, NULL, 'media/core/9788497593885.jpeg', 1, '2023-09-01 17:13:53.934487', '2023-09-01 17:13:53.934487', 69, 1, 6, 2, 'Debolsillo', '', '01_03', NULL, 11, 'Paula es una mujer de 28 años que acaba de casarse y sufre de una extraña enfermedad hereditaria llamada porfiria. Tras una crisis es remitida a un hospital en Madrid donde llegan sus familiares más cercanos a cuidarla y acompañarla. Su madre se ve envuelta en una serie de dolorosas preguntas: "¿Dónde andas, Paula? ¿Cómo serás cuando despiertes? ¿Tendrás memoria o tendré que contarte pacientemente los veintiocho años de tu vida y los cuarenta y nueve de la mía?"INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2209, '9788472230088', 'Relato de un náufrago', 56, '2011', 137, NULL, 'media/core/9788472230088.jpeg', 1, '2023-09-01 17:16:37.751778', '2023-09-01 17:16:37.751778', 602, 27, 6, 2, 'Cuadernos marginales', '', '01_03', NULL, 12, 'Este libro de Gabriel García Márquez no fue concebido para serlo. Más que un texto literario, es el ejemplo de un excelente reportaje, de un periodismo autentico.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2210, '9788497592352', 'El coronel no tiene quien le escriba', 1, '2019', 99, NULL, 'media/core/9788497592352.jpg', 1, '2023-09-01 17:19:15.054434', '2023-09-01 17:19:15.054434', 602, 27, 6, 2, 'Debo', '', '01_03', NULL, 11, 'El coronel no tiene quien le escriba fue escrita por Gabriel García Márquez durante su estancia en París, adonde había llegado, a mediados de los cincuenta, como corresponsal de prensa y con la secreta intención de estudiar cine. El cierre del periódico para el que trabajaba le sumió en la pobreza mientras redactaba en tres versiones distintas esta excepcional novela, que luego fue rechazada por varios editores antes de su publicación.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2211, '9788497592437', 'Crónica de una muerte anunciada', 1, '2015', 137, NULL, 'media/core/9788497592437.jpeg', 1, '2023-09-01 17:21:45.842887', '2023-09-01 17:44:49.953594', 602, 1, 6, 2, 'Debolsillo', '', '01_03', NULL, 11, 'Acaso seaCrónica de una muerte anunciada la obra más «realista» de Gabriel García Márquez, pues se basa en un hecho histórico acontecido en la tierra natal del escritor. Cuando empieza la novela, ya se sabe que los hermanos Vicario van a matar a Santiago Nasar -de hecho, ya le han matado- para vengar el honor ultrajado de su hermana Ángela, pero el relato termina precisamente en el momento en que Santiago Nasar muere.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2212, '9788439735427', 'El amor en los tiempos del cólera', 1, '2021', 400, NULL, 'media/core/9788439735427.jpg', 1, '2023-09-01 17:26:08.820343', '2023-09-01 17:26:08.820343', 602, 1, 6, 2, 'Literatura Random House', '', '01_03', NULL, 11, 'Una edición conmemorativa deEl amor en los tiempos del cólera, un gran clásico de Gabriel García Márquez y una novela  imprescindible de la literatura contemporánea.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2213, '9788420471839', 'Cien años de soledad', 1, '2007', 470, NULL, 'media/core/9788420471839.jpg', 1, '2023-09-01 17:30:22.296362', '2023-09-01 17:30:22.296362', 602, 1, 6, 2, NULL, '', '01_03', NULL, 10, '«La aventura fabulosa de una familia cuyos milagros, fantasías, obsesiones, tragedias, incestos y adulterios representan al mismo tiempo el mito y la historia, la tragedia y la comedia, la vida y la muerte. Su excelente prosa, la naturalidad delos diálogos y una trama ágil y dinámica hacen de este libro uno de mis favoritos.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2214, '9788466331883', 'Clases de literatura. Berkely, 1980', 1, '2016', 305, NULL, 'media/core/9788466331883.jpeg', 1, '2023-09-01 17:33:12.733082', '2023-09-01 17:33:12.733082', 833, 44, 6, 2, 'Debolsillo', '', '01_03', NULL, 11, 'Cortázar inédito. El Cortázar que nos quedaba por conocer, este que entra en el aula y sonríe.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2215, '9788420405384', 'Cuentos completos I (1945 - 1966)', 1, '2015', 639, NULL, 'media/core/9788420405384.jpeg', 1, '2023-09-01 17:36:09.919288', '2023-09-01 17:36:09.919288', 833, 27, 6, 2, NULL, '', '01_03', NULL, 10, 'En este volumen el lector encontrará todas las colecciones de cuentos de  Cortázar publicadas entre 1945 y 1966 y, como novedad, aquellos relatos aparecidos póstumamente en Papeles inesperados (2009) que, por  título o fecha, pudieron pertenecer a ellas: Laotra orilla, Bestiario, Las armas secretas, Final del juego,  Historias de cronopios y de famas  y Todos los fuegos el fuego conforman este primer volumen de los cuentos completos cortazarianos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2216, '9788420405391', 'Cuentos completos II (1969 - 1982)', 1, '2015', 546, NULL, 'media/core/9788420405391.jpg', 1, '2023-09-01 17:37:55.831333', '2023-09-01 17:37:55.832445', 833, 27, 6, 2, NULL, '', '01_03', NULL, 10, 'En este volumen, el lector encontrar# todas las colecciones de cuentos  de Cort#zar publicadas entre 1969 y 1982 y, como novedad, aquellos relatos aparecidos p#stumamente en Papeles inesperados (2009) que  por t#tulo o fecha pudieron pertenecer  a ellas: #ltimo round, Octaedro, Alguien que anda por ah#, Un tal Lucas,  Queremos tanto a Glenda y Deshoras conforman este segundo volumen de los cuentos completos cortazarianos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2217, '9788426420213', 'Cuentos completos', 2, '2015', 545, NULL, 'media/core/9788426420213.jpeg', 1, '2023-09-01 17:40:15.645193', '2023-09-01 17:40:15.645193', 804, 27, 6, 2, NULL, '', '01_03', NULL, 21, 'Poeta, ensayista y narrador, Borges es una de las figuras primordiales de la literatura universal. Ahora, por primera vez, se reúnen en este volumen todos sus cuentos, uno de los legados más influyentes y deslumbrantes de la literatura occidental.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2218, '9780099549482', 'To Kill a Mokinkgbird', 1, '1989', 309, NULL, 'media/core/9780099549482.jpg', 1, '2023-09-02 06:18:09.951430', '2023-09-02 06:18:09.951430', 1154, 1, 6, 2, NULL, '', '01_03', NULL, 11, '''Shoot all the bluejays you want, if you can hit ''em, but remember it''s a sin to kill a mockingbird''. A lawyer''s advice to his children as he defends the real mockingbird of Harper Lee''s classic novel - a black man charged with the rape of a white girl. Through the young eyes of Scout and Jem Finch, Harper Lee explores with exuberant humour the irrationality of adult attitudes to race and class in the Deep South of the thirties. The conscience of a town steeped in prejudice, violence and hypocrisy is pricked by the stamina of one man''s struggle for justice. But the weight of history will only tolerate so much. "To Kill a Mockingbird" is a coming-of-age story, an anti-racist novel, a historical drama of the Great Depression and a sublime example of the Southern writing tradition.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2219, '9780007119530', 'Tolkien and the Great War. The Threshold of Middle-earth', 1, '2003', 313, NULL, 'media/core/9780007119530.jpg', 1, '2023-09-02 06:22:20.633207', '2023-09-02 06:22:20.633207', 1256, 31, 6, 2, NULL, '', '01_03', NULL, 400, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2220, '9788408010524', 'Elisabeth, emperatirz de Austria-Hungria o el hada maldita', 14, '1994', 295, NULL, 'media/core/9788408010524.jpg', 1, '2023-09-02 06:25:52.216686', '2023-09-02 06:25:52.216686', 220, 31, 6, 2, 'Colección Mujeres apasionadas', '', '01_03', NULL, 7, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2221, '9788401422669', 'Diario', 4, '1995', 294, 'Het Achterhuis', 'media/core/sin-imagen_wmux1aX.jpg', 1, '2023-09-02 06:29:19.381848', '2023-09-02 06:29:19.381848', 1257, 31, 6, 2, 'Ave Fénix', '', '01_03', NULL, 17, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2222, '9788495359490', 'El mundo de ayer. Memorias de un europeo', 1, '2017', 546, 'Die Welt von Gestern', 'media/core/9788495359490.jpeg', 1, '2023-09-02 06:34:08.197140', '2023-09-02 06:34:08.197140', 630, 31, 6, 2, NULL, '', '01_03', NULL, 455, 'El mundo de ayer es uno de los más conmovedores y atractivos testimonios de nuestro pasado reciente, escrito además con mano maestra por un europeo empapado de civilización y nostalgia por un mundo, el suyo, que se iba desintegrando a pasos agigantados. Escritor extraordinariamente popular y testigo de excepción de los cambios que convulsionaron la Europa del siglo XX entre las dos guerras mundiales, Zweig recuerda, desposeído y en tierra extrañaen unas circunstancias personales de insospechado dramatismo, los momentos fundamentales de su vida, paralela en mucho a la desmembración de aquella Europa central que se quería más libre y segura, al abrigo de la locura y la tormenta. El resultado es un libro capital, uno de los mejores de Zweig y referencia inexcusable para entender los desvaríos de un siglo devastador.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2223, '9788495359391', 'Veintiuatro horas en la vida de una mujer', 1, '2001', 101, 'Vierundzwanzig Stunden aus dem Leben einer Frau', 'media/core/9788495359391.jpeg', 1, '2023-09-02 06:39:41.647110', '2023-09-02 06:39:41.647110', 630, 1, 6, 2, 'Narrativa del >Acantilado', '', '01_03', NULL, 455, '«?¿Usted no encuentra, pues, odioso, despreciable, que una mujer abandone a su marido y a sus hijas para seguir a un hombre cualquiera, del que nada sabe, ni siquiera si es digno de su amor? ¿Puede usted realmente excusar una conducta tan atolondrada y liviana en una mujer que, además, no es ya una jovencita y que siquiera por amor a sus hijas hubiese debido preocuparse de su propia dignidad?»', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2224, '9788490328378', 'Perdida', 1, '2013', 568, 'Gone Girl', 'media/core/9788490328378.jpeg', 1, '2023-09-02 06:45:01.029015', '2023-09-02 06:45:01.029015', 1258, 1, 6, 2, 'Debolsillo', '', '01_03', NULL, 171, 'En un caluroso día de verano, Amy y Nick se disponen a celebrar su  quinto aniversario de bodas en North Carthage, a orillas del río   Mississippi. Pero Amy desaparece esa misma mañana sin dejar rastro. A  medida que la investigación policial avanza las sospechas recaen sobre  Nick. Sin embargo, este insiste en su inocencia. Es cierto que se muestra extrañamente evasivo y frío, pero ¿es capaz de matar?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2225, '9788417346348', 'Comedia', 1, '2018', 809, 'Commedia', 'media/core/9788417346348.jpg', 1, '2023-09-02 06:48:43.625204', '2023-09-02 06:48:43.625204', 1259, 4, 6, 2, NULL, '', '01_03', NULL, 455, 'Hay obras maestras, como el Quijote, que los autores empiezan sin plan preciso ni determinado: van haciendo de la necesidad virtud, rizando el rizo de la invención. Pero la Comedia pertenece a otra categoría: es el resultado de la deliberación y la perseverancia de Dante. Exiliado de Florencia y condenado a la hoguera, fue incluso contumaz, pues insistió en el imperdonable «error» de crear algo profundamente nuevo y personal. Dramática y tenebrosa en el Infierno, pictórica y melancólica en el Purgatorio y luminosa y musical en el Paraíso, la Comedia es a la Edad Moderna lo que la Odisea a la Antigüedad. Esta nueva traducción de José María Micó, melódica e inspirada, invita al lector de habla hispana a adentrarse en el singular universo dantesco y acompañar al poeta en su viaje por los tres reinos ultramundanos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2226, '9781609420673', 'The Man Who Was Thursday', 1, '2010', 117, NULL, 'media/core/9781609420673.jpg', 1, '2023-09-02 06:52:58.379241', '2023-09-02 06:52:58.379241', 1260, 27, 6, 2, 'Fictions - Classics', '', '01_03', NULL, 456, 'The Supreme Anarchists Council is dedicated to overthrowing the world order. To keep their identities a secret, each of the members has been named after a day of the week. Gabriel Syme, an eccentric poet, is recruited by Scotland Yard to infiltrate the group. He tracks down the six other men and manages to win a place on the council. But after a bizarre twist of events, Syme quickly realizes that appearances are never what they seem in the dangerous world of the political underground.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2227, '847002230X', 'La Celestina', 1, '1977', 263, NULL, 'media/core/847002230X.jpg', 1, '2023-09-02 06:55:43.857327', '2023-09-02 06:55:43.857327', 764, 41, 6, 2, 'ORO', '', '01_03', NULL, 457, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2228, '9788430762002', 'Tirant lo Blanc', 1, '2010', 186, NULL, 'media/core/9788430762002.jpeg', 1, '2023-09-02 06:58:23.740005', '2023-09-02 06:58:23.740005', 1262, 1, 6, 2, 'Biblioteca Teide', '', '01_03', NULL, 172, '«Tirant lo Blanc» és una de les novel·les més importants de la literatura occidental i, sobretot, de la literatura catalana. Escrita per Joanot Martorell entre el 1460 i el 1468, des del moment de la seva primera edició (Valencia, 1490) va ser una de les obres més llegides en el seu temps i fou traduïda a moltes llengües. Des d''aleshores se n''han fet una gran diversitat d''edicions. A la Bilioteca Teide, presentem una adaptació feta en un llenguatge apte per als joves lectors amb la pretensió que aquesta primera lectura de l''obra els porti algún dia a llegir-ne la versió íntegra.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2229, '9788498044171', 'Tirant lo Blanc. Episodis amorosos', 1, '2013', 292, NULL, 'media/core/9788498044171.jpeg', 1, '2023-09-02 07:01:02.009996', '2023-09-02 07:01:02.009996', 1262, 1, 6, 2, 'Clàssics Castellnou', '', '01_03', NULL, 248, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2230, '8471940760', 'Novelas ejemplares', 1, '1973', 374, NULL, 'media/core/sin-imagen_dHUGInI.jpg', 1, '2023-09-02 07:03:48.283391', '2023-09-02 07:03:48.283391', 680, 1, 6, 2, NULL, '', '01_03', NULL, 458, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2231, 'B2346365', 'Novelas ejemplares', 1, '1965', 191, NULL, 'media/core/sin-imagen_mphI04v.jpg', 1, '2023-09-02 07:07:10.968767', '2023-09-02 07:07:10.968767', 680, 1, 6, 2, NULL, '', '01_03', NULL, 5, '', 'Sólo: INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2232, '8422521938', 'Novelas ejemplares', 1, '1975', 315, NULL, 'media/core/sin-imagen_jvocu6A.jpg', 1, '2023-09-02 07:10:42.047772', '2023-09-02 07:10:42.047772', 680, 1, 6, 2, 'Clásicos españoles', '', '01_03', 'II', 459, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2233, '9788467016901', 'El ingenioso hidalgo Don Quijote de la Mancha', 10, '2012', 886, NULL, 'media/core/9788467016901.jpeg', 1, '2023-09-02 07:13:21.019474', '2023-09-02 07:13:21.019474', 680, 1, 6, 2, NULL, '', '01_03', NULL, 460, 'La mejor novela de todas las epocas', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2234, '9788484322818', '¡Adiós, coedera! y otros cuentos', 1, '2001', 279, NULL, 'media/core/9788484322818.jpeg', 1, '2023-09-02 07:16:49.513986', '2023-09-02 07:16:49.513986', 611, 27, 6, 2, 'Clásicos y modernos', '', '01_03', NULL, 61, 'El ya clásico de la literatura contemporánea en edición de Ángeles Ezama, que nos ofrece el texto más fiel a la intención del autor, depurándolo de los errores de las primeras publicaciones periodísticas. Se incluye en la selección no sólo los cuentos más celebrados del autor, sino otros que aunque significativos no han tenido tanta fortuna crítica y editorial.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2235, '9788423342303', 'El camino', 1, '2012', 195, NULL, 'media/core/9788423342303.jpg', 1, '2023-09-02 07:19:32.912197', '2023-09-02 07:19:32.912197', 830, 1, 6, 2, 'Contemporánea Narrativa', '', '01_03', NULL, 460, 'Daniel el Mochuelo intuye a sus once años que su camino está en la aldea, junto a sus amigos, sus gentes y sus pájaros. Pero su padre quiere que vaya a la ciudad a estudiar el Bachillerato. A lo largo de la noche que precede a la partida, Daniel, insomne, con un nudo en la garganta, evocará las correrías con sus amigos -Roque el Moñigo y Germán el Tiñoso- a través de los campos, descubriendo el cielo y la tierra, y revivirá las andanzas de la gente sencilla de la aldea. La simpatía humana con que esa mirada infantil nos introduce en el pueblo, haciéndonos conocer toda una impresionante galería de tipos, y la fuerza con que, a través de rasgos frecuentemente caricaturescos, se nos presentan siempre netos y vivos, son los grandes aciertos de esta novela. El camino es, por su amalgama de nitidez realista, humor sutil, nostalgia contenida e irisación poética, no sólo una de las mejores novelas de Miguel Delibes , sino también, como señalara la crítica, una de las obras maestras de la narrativa contemporánea.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2236, '9788431685027', 'Misericordia', 1, '2011', 338, NULL, 'media/core/9788431685027.jpg', 1, '2023-09-02 07:21:14.077715', '2023-09-02 07:21:14.077715', 527, 1, 6, 2, 'Clásiccos Hispánicos', '', '01_03', NULL, 23, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2237, '8422644258', 'Concepción Arenal', 1, '1993', 339, NULL, 'media/core/8422644258.jpg', 1, '2023-09-02 07:24:12.022145', '2023-09-02 07:24:12.022145', 1264, 31, 6, 2, 'Mujeres de novela', '', '01_03', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2238, '842260437X', 'El viejo y el mar', 1, '1973', 159, 'The old man & the sea', 'media/core/842260437X.jpg', 1, '2023-09-20 07:11:03.116047', '2023-09-20 07:11:52.775042', 1079, 1, 6, 2, NULL, '', '01_04', NULL, 461, 'Con un lenguaje de gran fuerza y sencillez,El viejo y el mar narra la historia de un viejo pescador cubano a quien la suerte parece haber abandonado, y del desafío mayor al que se enfrenta: la batalla despiadada y sin tregua con un pez gigantesco en las aguas del golfo. Escrito en 1952 por encargo de la revistaLife, este relato lo confirmó como uno de los escritores más significativos del siglo XX', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2239, '9788484288442', 'Anna Karénina', 1, '2013', 1008, NULL, 'media/core/9788484288442.jpeg', 1, '2023-09-20 07:15:33.155076', '2023-09-20 07:15:33.155076', 1265, 1, 6, 2, 'Alba minus', '', '01_04', NULL, 119, 'Anna Karénina, que Tolstói empezó a escribir en 1873 y no vería publicada en forma de libro hasta 1878, es una exhaustiva disquisición sobre la institución familiar y, quizá ante todo, como dice Víctor Gallego (autor de esta nueva traducción), «una fábula sobre la búsqueda de la felicidad». La idea de que la felicidad no consiste en la satisfacción de los deseos preside la detallada descripción de una galería espléndida de personajes que conocen la incertidumbre y la decepción, el vértigo y el tedio, los mayores placeres y las más tristes miserias.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2240, 'B8429', 'Oliver Twist // David Copperfield', 1, '1972', 605, NULL, 'media/core/B8429.jpg', 1, '2023-09-20 07:19:25.631016', '2023-09-20 07:19:25.631016', 366, 1, 6, 2, NULL, '', '01_04', NULL, 117, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2241, '9780199536238', 'A Tale of Two Cities', 1, '2008', 361, NULL, 'media/core/9780199536238.jpeg', 1, '2023-09-20 07:22:13.489532', '2023-09-20 07:22:13.489532', 366, 1, 6, 2, 'Oxford World''s Classics', '', '01_04', NULL, 179, 'Dickens'' second historical novel, which he considered ''the best story I have written,'' provides a highly-charged examination of human suffering and human sacrifice. Private experience and public history paralled one another as the political activities and personal responsibilities of these fictional characters, during the French Revolution, draw them into the Paris of the Terror.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2242, '9780199540204', 'The Rover and Other Plays', 1, '2008', 335, NULL, 'media/core/9780199540204.jpeg', 1, '2023-09-20 07:24:48.949336', '2023-09-20 07:24:48.949336', 1266, 1, 6, 2, 'Oxford World''s Classics', '', '01_04', NULL, 179, 'Aphra Behn (1640-89) was both successful and controversial in her own lifetime; her achievements are now recognized less equivocally and her plays, often revived, demonstrate wit, compassion and remarkable range. This edition brings together her most important comedies in a single volume: The Rover, her best-known play; The Feigned Courtesans, a lively comedy of intrigue; The Lucky Chance, a comedy with a bitter edge, which takes a satirical look at marriage customs; and the dazzling and popular farce, The Emperor of the Moon. All the plays have been newly edited and are presented with modernized spelling and punctuation.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2243, '9780199535064', 'The Complete Short Stories', 1, '2010', 227, NULL, 'media/core/9780199535064.jpeg', 1, '2023-09-20 07:27:24.645829', '2023-09-20 07:27:24.645829', 498, 44, 6, 2, 'Oxford World''s Classics', '', '01_04', NULL, 179, 'Oscar Wilde''s shorter fiction includes memorable fairy-tales, witty comedies, and daring narrative experiments: all are contained in this enchanting collection.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2244, '9788431632984', 'El fantasma de Canterville y otros cuentos', 1, '2007', 155, NULL, 'media/core/9788431632984.jpeg', 1, '2023-09-20 07:30:14.222909', '2023-09-20 07:30:14.222909', 498, 44, 6, 2, 'Aula de Literatura', '', '01_04', NULL, 23, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2245, '9781840224016', 'De profundis The Ballad of Reading Gaol & Other Writings', 1, '2002', 280, NULL, 'media/core/9781840224016.jpeg', 1, '2023-09-20 07:33:59.607296', '2023-09-20 07:33:59.607296', 498, 44, 6, 2, 'Wordsworth Classics', '', '01_04', NULL, 462, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2246, '9780141439570', 'The Picture of Dorian Gray', 1, '1985', 213, NULL, 'media/core/9780141439570.jpeg', 1, '2023-09-20 07:37:11.667065', '2023-09-20 07:37:11.667065', 498, 1, 6, 2, 'Penguin Classics', '', '01_04', NULL, 11, 'Enthralled by his own exquisite portrait, Dorian Gray exchanges his soul for eternal youth and beauty. Influenced by his friend Lord Henry Watton, he is drawn into a corrupt double life, indulging his desires in secret while remaining a gentleman in the eyes of polite society. Only his portrait bears the traces of his decadence. Introduction by Robert Mighall. Preface by Peter Ackroyd. Especial Oscar Wilde', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2247, '9781853260063', 'A Portrait of the Artist as a Young Man', 1, '2001', 196, NULL, 'media/core/9781853260063.JPG', 1, '2023-09-20 07:40:19.851271', '2023-09-20 07:40:19.851271', 105, 1, 6, 2, 'Word', '', '01_04', NULL, 462, '', '');
