INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2250, '9788499080291', 'Sentido y sensibilidad', 1, '2009', 369, 'Sense & Sensibility', 'media/core/9788499080291.jpeg', 1, '2023-09-20 07:48:15.864020', '2023-09-20 07:48:15.864020', 1267, 1, 6, 2, 'Debolsillo', '', '01_04', NULL, 171, '', '');
