INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2252, '9782070413119', 'Madame Bovary', 1, '2001', 446, NULL, 'media/core/9782070413119.jpeg', 1, '2023-09-20 07:55:55.062215', '2023-09-20 07:55:55.062215', 1268, 1, 6, 2, 'Folio classique', '', '01_04', NULL, 293, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2253, '9782070374922', 'La Tentation  de saint Antoine', 1, '1983', 236, NULL, 'media/core/9782070374922.jpeg', 1, '2023-09-20 08:00:04.695730', '2023-09-20 08:00:04.695730', 1268, 1, 2, 2, 'Collection folio', '', '01_04', NULL, 293, 'Née de la rencontre avec un tableau de Brueghel et du souvenir des spectacles forains de la foire Saint-Romain à Rouen, La Tentation de saint Antoine résume la diablerie romantique, ses monstres, ses obsessions, ses ténèbres. " Œuvre de toute ma vie ", disait Flaubert, elle est aussi " le cabinet secret de son esprit " selon Baudelaire qui voulait " surtout attirer l''attention du lecteur sur cette faculté souffrante, souterraine et révoltée, qui traverse toute l''œuvre, ce filon ténébreux qui illumine et qui sert de guide à travers ce capharnaüm pan démoniaque de la solitude ".', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2254, '9788437604077', 'Las desventuras del joven Werther', 21, '2012', 192, 'Die Leiden des jungen Werther', 'media/core/9788437604077.jpeg', 1, '2023-09-20 08:03:15.563996', '2023-09-20 08:03:15.563996', 1238, 1, 6, 2, 'Letras universales', '', '01_04', NULL, 318, 'Johann Wolfgang von Goethe (1749-1832) es uno de esos genios que iluminan toda una época: poeta lírico, épico y dramático, científico, versado en las artes, gran estadista. Formó parte del grupo "Sturm und Drang", que marcó el comienzo de la literatura en lengua alemana. "Werther" (1774) influyó en el lenguaje, en las pasiones y hasta en la moda de numerosos jóvenes. El poderoso hálito romántico de la obra, su belleza formal y el acierto de la expresión escogida (la epistolar), lograron que calara hondamente en su época, y quedara para la posteridad como muestra perfecta de literatura subjetivista, y conjunción de vida y poesía.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2255, '9782070411429', 'Germinal', 1, '1978', 700, NULL, 'media/core/9782070411429.jpg', 1, '2023-09-20 08:06:38.286619', '2023-09-20 08:06:38.286619', 1269, 1, 6, 2, 'Folio classique', '', '01_04', NULL, 293, 'Une des grandes grèves du siècle dernier racontée par un journaliste de génie qui en a fait un réquisitoire, un formidable « J''accuse » contre le capital, le roman de la lutte des classes et de la misère ouvrière. Un livre de nuit, de violence et de sang, mais qui débouche sur l''espoir d''un monde nouveau lorsque le héros, Étienne Lantier, quittant la mine « en soldat raisonneur de la révolution », sent naître autour de lui une « armée noire, vengeresse... dont la germination allait bientôt faire éclater la terre ». INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2256, '9788437622552', 'El corazón de las tinieblas', 4, '2010', 249, 'Heart of Darkness', 'media/core/9788437622552.jpeg', 1, '2023-09-20 08:09:28.018831', '2023-09-20 08:09:28.018831', 909, 1, 6, 2, 'Letras universales', '', '01_04', NULL, 318, 'Desde muy joven, Joseph Conrad se sintió atraído por el continente africano y por las aventuras que, supuestamente, aguardaban a aquellos que tuvieran el valor de adentrarse en la espesura de la jungla. El contacto con la realidad del Congo, colonia personal del rey Leopoldo II de Bélgica, cambió, sin embargo, la situación radicalmente. El sistema esclavista, el estado de terror, barbarie y genocidio instaurado por los representantes del rey belga para asegurar la supervivencia del sistema de control de unos pocos europeos sobre millones de africanos, le supuso no solo experimentar una decepción de sus ilusiones infantiles, sino un serio revés en su salud física y psíquica. Esta experiencia africana marcó fuertemente la composición de «El corazón de las tinieblas».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2257, '9780141023571', 'Of Mice and Men', 1, '1978', 121, NULL, 'media/core/9780141023571.jpg', 1, '2023-09-20 08:12:43.789376', '2023-09-20 08:12:43.789376', 657, 1, 6, 2, NULL, '', '01_04', NULL, 11, 'Streetwise George and his childlike friend Lennie are drifters, searching for work in the fields and valleys of California. They have nothing except the clothes on their back, and a hope that one day they''ll find a place of their own and live the American dream. But do dreams come at a price!', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2258, '9780141190273', 'A Streetcar Named Desire', 1, '2004', 107, NULL, 'media/core/9780141190273.jpg', 1, '2023-09-20 09:49:00.679724', '2023-09-20 09:49:00.679724', 853, 41, 6, 2, 'MOdern Classics', '', '01_04', NULL, 11, 'Fading southern belle Blanche Dubois depends on the kindness of strangers and is adrift in the modern world. When she arrives to stay with her sister Stella in a crowded, boisterous corner of New Orleans, her delusions of grandeur bring her into conflict with Stella''s crude, brutish husband Stanley. Eventually their violent collision course causes Blanche''s fragile sense of identity to crumble, threatening to destroy her sanity and her one chance of happiness.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2259, '9780141182636', 'The Great Gatsby', 1, '1990', 172, NULL, 'media/core/9780141182636.jpeg', 1, '2023-09-20 09:52:05.950443', '2023-09-20 09:52:05.950443', 1270, 1, 6, 2, 'MOdern Classics', '', '01_04', NULL, 11, 'Everybody who is anybody is seen at Gatsby''s glittering parties. None of the socialites understand Gatsby. He seems to always be watching and waiting, though no one knows what for. But as the tragic story unfolds, Gatsby''s destructive dreams and passions are revealed.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2260, '9780582275249', 'Animal Farm', 1, '1996', 85, NULL, 'media/core/9780582275249.jpg', 1, '2023-09-20 09:54:59.660389', '2023-09-20 09:54:59.660389', 94, 1, 6, 2, 'Longman', '', '01_04', NULL, 408, 'ALL ANIMALS ARE EQUAL BUT SOME ANIMALS ARE MORE EQUAL THAN OTHERS. When the animals take over the farm, they think it is the start of a better life. Their dream is of a world where all animals are equal and all property is shared. Animal Farm is one of the classic stories of modern English fiction and is a powerful study of the use and abuse of political power.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2261, '9780141187761', 'Nineteen Eighty-Four', 1, '2003', 342, NULL, 'media/core/9780141187761.jpg', 1, '2023-09-20 09:58:57.967322', '2023-09-20 09:58:57.967322', 94, 1, 6, 2, 'MOdern Classics', '', '01_04', NULL, 11, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2262, '9780099477464', 'Brave New World', 1, '2004', 229, NULL, 'media/core/9780099477464.GIF', 1, '2023-09-20 10:25:39.694706', '2023-09-20 10:25:39.694706', 1246, 1, 6, 2, NULL, '', '01_04', NULL, 463, 'Far in the future, the World Controllers have created the ideal society. Through clever use of genetic engineering, brainwashing and recreational sex and drugs all its members are happy consumers. Bernard Marx seems alone in feeling discontent. Harbouring an unnatural desire for solitude, and a perverse distaste for the pleasures of compulsory promiscuity, Bernard has an ill-defined longing to break free. A visit to one of the few remaining Savage Reservations where the old, imperfect life still continues, may be the cure for his distress-Huxley''s ingenious fantasy of the future sheds a blazing light on the present and is', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2263, '9781451678192', 'The Martian Chronicles', 1, '2012', 241, NULL, 'media/core/9781451678192.jpeg', 1, '2023-09-20 10:28:08.335423', '2023-09-20 10:28:08.335423', 787, 3, 6, 2, NULL, '', '01_04', NULL, 419, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2264, '9788497930055', 'Fahrenheit 451', 3, '2010', 175, 'Fahrenheit 451', 'media/core/9788497930055.jpeg', 1, '2023-09-20 10:31:42.214539', '2023-09-20 10:31:42.214539', 787, 1, 6, 2, 'Contemporánea', '', '01_04', NULL, 204, 'Fahrenheit 451 ofrece la historia de un sombrío y horroroso futuro. Montag, el protagonista, pertenece a una extraña brigada de bomberos cuya misión, paradójicamente, no es la de sofocar incendios sino la de provocarlos, para quemar libros. Porque en el país de Montag está terminantemente prohibido leer. Porque leer obliga a pensar, y en el país de Montag esta prohibido pensar. Porque leer impide ser ingenuamente feliz, y en el país de', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2265, '9788497935487', 'La metamorfosis', 3, '2013', 100, 'Die Verwandlung', 'media/core/9788497935487.jpg', 1, '2023-09-20 10:37:44.487623', '2023-09-20 10:37:44.487623', 864, 1, 6, 2, 'Contemporánea', '', '01_04', NULL, 204, 'La transformación, o metamorfosis, de Gregor Samsa en un bicho monstruoso, similar a un enorme escarabajo, es uno de los hitos de la literatura universal. Franz Kafka escribió el relato en 1915 y lo publicó por primera vez en la revista mensualDie Weissen Blätter. En noviembre de ese mismo año, el título se imprimió como libro independiente bajo el sello de la editorial Kurt Wolff, con fecha anticipada de 1916.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2266, '9788420712314', 'Otre vuelta de tuerca', 11, '2009', 178, 'The Turn of the Screw, 1898', 'media/core/9788420712314.jpg', 1, '2023-09-20 10:45:19.885209', '2023-09-20 10:45:19.885209', 1271, 1, 6, 2, NULL, '', '01_04', NULL, 66, 'Una joven inglesa llega a una vieja mansión en el campo para encargarse de la educación de un niño y de una niña que han quedado huérfanos. Poco tiempo después de su llegada, descubre que los niños reciben periódicas "visitas" de sus antiguos preceptores, un hombre y una mujer muertos un año atrás. La institutriz, horrorizada, decide hacer lo posible para defender a los niños, cuya custodia se le había encomendado, y trata de interponerse entre ellos y los fantasmas. Con esta historia, aparentemente tan sencilla, Henry James logró realmente el "más difícil todavía": dar otra vuelta a esa "tuerca" que hay escondida en todo relato de terror.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2267, '9788445005125', '¿Sueñas los androides con ovejas eléctricas?', 1, '2019', 271, 'Do Androids Dream of Electric Sheep?', 'media/core/9788445005125.jpeg', 1, '2023-09-20 10:49:28.792098', '2023-09-20 10:49:28.792098', 1272, 3, 6, 2, 'Colección Austral', '', '01_04', NULL, 210, 'En el año 2021 la guerra mundial ha exterminado a millones de personas. Los supervivientes codician cualquier criatura viva, y aquellos que no pueden permitirse pagar por ellas se ven obligados a adquirir replicas increíblemente realistas. Las empresas fabrican incluso seres humanos. Rick Deckard es un cazarrecompensas cuyo trabajo es encontrar androides rebeldes y retirarlos, pero la tarea no será tan sencilla cuando tenga que enfrentarse a los nuevos modelos Nexus-6, prácticamente indistinguibles de los seres', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2268, '8485224493', 'Al este del Edén // La perla', 1, '1976', 843, 'East of Eden //', 'media/core/8485224493.jpg', 1, '2023-09-20 10:55:07.551977', '2023-09-20 10:55:07.551977', 657, 1, 6, 2, 'Biblioteca Siglo XX', '', '01_04', NULL, 464, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2269, '9788435018968', 'Viaje al fin de la noche', 1, '2011', 576, 'Voyage au boit de la nuit', 'media/core/9788435018968.jpeg', 1, '2023-09-20 11:00:00.617666', '2023-09-20 11:00:00.617666', 1273, 1, 2, 2, 'Pocket', '', '01_04', NULL, 47, 'Viaje al fin de la noche narra la epopeya de Ferdinand Baradamu, herido en la primera guerra mundial en la que participa como voluntario, enamorado de una prostituta sin futuro, sobreviviendo en las colonias francesas en África gracias a un trabajo alienante, persiguiendo su particular sueño americano, de regreso en Francia trabajando como médico ruralINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2270, '8420616559', 'Poemas sociales de guerra y muerte', 4, '1981', 116, NULL, 'media/core/8420616559.jpeg', 1, '2023-09-20 11:05:03.899528', '2023-09-20 11:05:03.899528', 100, 4, 6, 2, 'El libro de bolsillo', '', '01_04', NULL, 69, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2271, '8402056105_1', 'El caminante', 6, '1986', 105, 'Wanderung', 'media/core/8402056105_1.jpg', 1, '2023-09-20 11:11:29.961731', '2023-09-20 11:11:29.961731', 803, 4, 6, 2, 'Libro amigo', '', '01_04', NULL, 126, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2272, '8401442214', 'Hermann Lauscher', 1, '1978', 1, '155', 'media/core/8401442214.jpg', 1, '2023-09-20 11:17:07.020851', '2023-09-20 11:17:07.020851', 803, 1, 6, 2, NULL, '', '01_04', NULL, 17, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2273, '8410018043081', 'Ojos de perro azul', 10, '1986', 1, NULL, 'media/core/8410018043081.jpg', 1, '2023-09-20 11:22:24.871865', '2023-09-20 11:22:24.871865', 602, 44, 6, 2, 'Libro amigo', '', '01_04', NULL, 126, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2274, 'B3554470', 'Un día en la vida de Iván Denisovich', 1, '1970', 175, NULL, 'media/core/B3554470.jpg', 1, '2023-09-20 11:26:19.091442', '2023-09-20 11:26:19.091442', 1275, 1, 6, 2, NULL, '', '01_04', NULL, 5, 'Es este uno de los más conocidos y tambien más escalofriantes testimonios de la crueldad que sufrieron millones de deportados en los campos de trabajo sovieticos. Las terribles condiciones de vida y las vejaciones descritas con detalle por Solzhenitsyn en Archipielago Gulag cobran aquí entidad literaria y, bajo la forma de novela, inmortalizan un drama que nunca caerá en el olvido. El protagonista, Iván DenísovichShújov, lleva encerrado ocho años –de una condena de diez– en un campo de trabajo situado en algún lugar de la estepa siberiana. Aunque en teoría se halla allí por "traición a la patria", la realidad es mucho más amarga: durante la guerra contra Alemania, Denísovich fue capturado por los nazis, pero logró escapar y reintegrarse en las filas sovieticas. Se le acusó entonces de haber huido del ejercito sovietico con la intención de traicionar, y de regresar para ejercer de espía para los alemanes. A fin de evitar la condena a muerte, Denísovich reconoció los hechos de los que se le acusaba y fue mandado al Gulag. Éste es el relato de uno de sus días en el campo de trabajo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2275, '9788483835128', 'La insoportable levedad del ser', 18, '2017', 327, 'Nesnetiselnál lehkost byti', 'media/core/9788483835128.jpeg', 1, '2023-09-20 11:30:14.291943', '2023-09-20 11:30:14.291943', 604, 1, 6, 2, 'Maxi Turquets', '', '01_04', NULL, 12, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2276, '9788420669861', 'El desierto de los tártaros', 3, '2016', 272, 'Il deserto dei Tartari', 'media/core/9788420669861.jpeg', 1, '2023-09-20 11:39:07.889185', '2023-09-20 11:39:07.889185', 1276, 1, 6, 2, 'El libro de bolsillo', '', '01_04', NULL, 69, 'La fascinación que desde su aparición en 1940 ha despertado "El desierto de los tártaros", la más célebre novela de Dino Buzzati (1906-1972), proviene tanto del paisaje formal de la fábula que narra, como de la significación que oculta. La historia del oficial Giovanni Drogo, destinado a una fortaleza fronteriza sobre la que pende una amenaza aplazada e inconcreta, pero obsesivamente presente, se halla cargada de resonancias que la conectan con algunos de los más hondos problemas de la existencia, como la seguridad como valor contrapuesto a la libertad, la progresiva resignación ante el estrechamiento de las posibilidades vitales de realización, o la frustración de las expectativas de hechos excepcionales que cambien el sentido de la existencia. Otras obras de Buzzati en esta colección: "Los siete mensajeros y otros relatos".', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2277, '9788433914798', 'Azul casi transparente', 14, '2021', 144, 'Kagirinaku tomei ni chikai buru', 'media/core/9788433914798.jpeg', 1, '2023-09-20 11:42:20.604756', '2023-09-20 11:42:20.604756', 1277, 1, 6, 2, 'Colección compactos', '', '01_04', NULL, 6, 'Esta primera novela de un estudiante japonés de veinticuatro años fue galardonada con el prestigioso premio Akutagawa. En seis meses se vendieron un millón y medio de ejemplares y el libro desencadenó pasiones. La crítica japonesa habló de «sensibilidad revolucionaria», de «mirada como el zoom de una cámara», de «filtro de lucidez, a través del cual la violencia y el erotismo más crudo adquieren una extraña pureza». Aunque también se acusó a Murakami de cultivar sistemáticamente la pornografía y la brutalidad. En los Estados Unidos, la revista Newsweek la recomendó como «una mezcla de La naranja mecánica, de Burgess, y El extranjero, de Camus». Los protagonistas de esta novela, chicos y chicas en su mayoría jovencísimos, viven cerca de una base norteamericana, consumiendo toda clase de drogas, yendo a conciertos de rock, organizando orgías para los soldados yanquis, todo ello sin aparente pasión ni placer. Con emblemática pasividad, se deslizan hacia la autodestrucción, como resultado no sólo de su situación presente, sino de su futuro bloqueado. El tratamiento del autor, frío y antisentimental, destila sin embargo un sentimiento de algo puro y no mancillado. Su técnica, con su ausencia de tabúes, de condenaciones morales y de detalles superfluos, se aproxima al cinéma-vérité, con unos toques de surrealismo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2278, '9788495501011', 'El médico', 11, '2002', 989, 'The Phisician', 'media/core/9788495501011.jpg', 1, '2023-09-20 11:47:43.817129', '2023-09-20 11:47:43.817129', 257, 1, 6, 2, 'Punto de lectura', '', '01_04', NULL, 8, 'Un joven aprendiz de médico con un don para sanar nunca visto recorrerá la Europa sombría y oscura del siglo XI hasta la fascinante Persia, para encontrarse con el mejor maestro imaginable: el mítico Avicena. Rob J. Cole, un joven londinense del siglo XI que pertenece a una familia de carpinteros, queda huérfano a los nueve años y con la responsabilidad de cuidar de sus cuatro hermanos menores, a quienes va encontrando hogar. Una vez solo coincide con Henry Croft, un cirujano barbero que deambula por Inglaterra montando espectáculos y dedicándose a ejercer de curandero para vender un ungüento milagroso y del que se convierte en aprendiz. Con Henry Croft comparte viaje, cartel y beneficios hasta que el maestro muere. Y es entonces cuando conoce a Benjamin Merlin, un médico judío que le alenta a superarse y hacer realidad su sueño, y que le habla del más eminente médico de la remota Persia: Ibn Sina o Avicena. Rob, llevado por su pasión por sanar y aliviar el dolor, llega a Oriente donde se hará pasar por judío y adoptará el nombre de Jesse ben Benjamin, para no destacar como europeo y poder hacer realidad su sueño: etudiar medicina en la madraza de Ispahán.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2279, '9788420674209', 'El guardián entre el centeno', 4, '2010', 279, 'The Catcher in the Rye', 'media/core/9788420674209.jpeg', 1, '2023-09-20 11:51:35.393183', '2023-09-20 11:51:35.393183', 1278, 1, 6, 2, 'El libro de bolsillo', '', '01_04', NULL, 69, 'Por expreso deseo del autor, no está permitido que la editorial aporte en su material promocional ningún tipo de texto adicional, información biográfica, cita o reseña relacionados con esta obra. El lector interesado podrá, no obstante, encontrar abundante información al respecto en internet.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2280, '9788402076809', 'En el camino', 2, '1983', 400, 'on the road', 'media/core/9788402076809.jpg', 1, '2023-09-20 11:54:41.695493', '2023-09-20 11:54:41.695493', 1041, 1, 6, 2, 'Club Bruguera', '', '01_04', NULL, 126, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2281, '9781786495259', 'Call me by your name', 1, '2019', 248, NULL, 'media/core/9781786495259.jpeg', 1, '2023-09-20 11:57:21.051315', '2023-09-20 11:57:21.051315', 1279, 1, 6, 2, NULL, '', '01_04', NULL, 465, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2282, '9788478886456', 'Harry Potter y el cáliz de fuego', 24, '2008', 672, 'Harry Potter and the Goblet of Fire', 'media/core/9788478886456.jpeg', 1, '2023-09-27 09:55:36.938047', '2023-09-27 09:55:36.938047', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 4', 29, '"Habrá tres pruebas, espaciadas en el curso escolar, que medirán a los  campeones en muchos aspectos diferentes: sus habilidades mágicas, su  osadía, sus dotes de deducción y, por supuesto, su capacidad para sortear el peligro."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2283, '9788478885190', 'Harry Potter y el prisionero de Azkaban', 40, '2008', 360, 'Harry Potter and the Prisoner of Azkaban', 'media/core/9788478885190..jpeg', 1, '2023-09-27 09:58:57.472741', '2023-09-27 10:04:20.463224', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 3', 29, '«Bienvenido al autobús noctámbulo, transporte de emergencia para el  brujo abandonado a su suerte. Levante la varita, suba a bordo y lo llevaremos a donde quiera.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2284, '9788478884957', 'Harry Potter y la cámara secreta', 44, '2008', 296, 'Harry Potter and the Chamber of Secrets', 'media/core/9788478884957.jpeg', 1, '2023-09-27 10:01:18.489906', '2023-09-27 10:01:18.489906', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 2', 29, 'HARRY POTTER Y LA CAMARA SECRETAINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2285, '9788478884452', 'Harry Potter y la piedra filosofal', 51, '2008', 264, 'Harry Potter and the Philosopher''s Stone', 'media/core/9788478884452.jpeg', 1, '2023-09-27 10:03:33.097069', '2023-09-27 10:03:33.097069', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 1', 29, '"Con las manos temblorosas, Harry le dio la vuelta al sobre y vio un  sello de lacre púrpura con un escudo de armas: un león, un águila, un tejón y una serpiente, que rodeaban una gran letra H."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2286, '9788498381955', 'Los cuentos de Beedle el Bardo', 1, '2008', 118, 'The Tales of Beedle the Bard', 'media/core/9788498381955.jpg', 1, '2023-09-27 10:08:38.913993', '2023-09-27 10:08:38.913993', 798, 48, 2, 2, NULL, '', '01_05', NULL, 29, 'Los cuentos de Beedle el Bardo contienen cinco cuentos de hadas muy diferentes, cada uno con su propio carácter mágico, que deleitarán al lector con su humor y la emoción del peligro de muerte.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2287, '9788498382686', 'Animales fantásticos y dónde encontrarlos', 3, '2011', 60, 'Fantastic Beasts & Where to Find Them', 'media/core/9788498382686.jpeg', 1, '2023-09-27 10:11:34.065075', '2023-09-27 10:11:34.065075', 798, 48, 6, 2, NULL, '', '01_05', NULL, 29, 'Este compendio de criaturas mágicas elaborado por Newt Scamander ha  deleitado a generaciones enteras de magos, convirtiendose en un  clásico  del genero. Ahora, esta edición actualizada con un prólogo de Newt, se  revelan seis nuevos animales apenas conocidos fuera  de la comunidad  mágica. Así, los muggles tendrán tambien la oportunidad de descubrir dónde vive el thunderbird, que come el puffskein y por que es conveniente apartar los objetos brillantes de la vista de los escarbatos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2288, '9788498382693', 'Quidditch a través de los tiempos', 2, '2010', 69, 'Quidditch Through the Ages', 'media/core/9788498382693.jpeg', 1, '2023-09-27 10:14:37.297430', '2023-09-27 10:14:37.297430', 798, 48, 2, 2, NULL, '', '01_05', NULL, 29, 'Si alguna vez te has preguntado de dónde proviene la snitch dorada, cómo  adquieren vida las bludgers o por que los Wigtown Wanderers llevan un  cuchillo de carnicero dibujado en el uniforme, entonces querrás leer Quidditch a traves de los tiempos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2289, '9788418174353', 'El Ickabog', 1, '2020', 304, 'The Ickabog', 'media/core/9788418174353.jpeg', 1, '2023-09-27 10:16:56.481512', '2023-09-27 10:16:56.481512', 798, 48, 6, 2, NULL, '', '01_05', NULL, 29, 'Se acerca el ickabog... un monstruo legendario que amenaza un reino y  que pondrá a prueba la valentía de dos chicos. Descubre una aventura  sumamente original sobre el poder de la esperanza y la amistad y su  triunfo contra todo pronóstico, obra de una de las mejores narradoras del mundo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2290, '9788467253429', 'El Hobbit', 1, '1982', 342, 'The Hobbit', 'media/core/9788467253429.jpeg', 1, '2023-09-27 10:31:12.579262', '2023-09-27 10:31:12.579262', 580, 48, 6, 2, NULL, '', '01_05', NULL, 214, 'Un gran clásico moderno y el preludio de las vastas y poderosas mitologías de El Señor de los AnillosINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2291, '9788445077276', 'Los hijos de Húrin', 1, '2015', 289, 'The Tale of the Children of Húrin', 'media/core/9788445077276.jpeg', 1, '2023-09-27 10:34:36.568049', '2023-09-27 10:34:36.568049', 580, 48, 6, 2, 'Biblioteca J. R. R. Tolkien', '', '01_05', NULL, 7, 'El origen de la Tierra MediaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2292, '9788496391680', 'Fairy Oak. El encanto de la Oscuridad', 1, '2007', 352, 'Fairy Oak. L?Incanto del Buio', 'media/core/9788496391680.jpeg', 1, '2023-09-27 10:38:55.099342', '2023-09-27 10:46:31.334438', 1280, 48, 6, 2, NULL, '', '01_05', 'Fairy Oak II', 466, 'Fairy Oak es un pueblo mágico y antiguo, escondido en un tiempo inmortal. Para encontrarlo habría que viajar a las mesetas escocesas, los acantilados de Normandía o Galicia y los valles floridos de Bretaña. El pueblo está habitado por criaturas mágicas y sinmagia (seres como nosotros) que viven en paz y armonía, y a las que es muy difícil distinguir. De hecho, hadas, magos, brujas y sinmagia viven en sus casas de piedra desde hace tanto tiempo que nadie presta atención a sus rarezas. Y todos se parecen, a excepción de las hadas, que son muy pequeñas, luminosas... ¡y vuelan! Los magos y las brujas de Fairy Oak las mandan llamar para que cuiden a los niños más pequeños del pueblo. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2293, '9788496391567', 'Fairy Oak. El secreto de las Gemelas', 1, '2006', 284, 'Fairy Oak. Il Segreto delle Gemelle', 'media/core/9788496391567.jpeg', 1, '2023-09-27 10:42:04.981040', '2023-09-27 10:47:27.049424', 1280, 48, 6, 2, NULL, '', '01_05', 'Fairy Oak', 466, 'Desde hace mas de mil años, a la medianoche en punto , ocurre un hecho magico en las casas de Fairy Oak: minusculas hadas luminosas cuentan historias de niños a brujas de ojos buenos.emocionadas y atentos. Insolito, ¿verdad?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2294, '9788496391963', 'Fairy Oak. El Poder de la Luz', 1, '2008', 384, 'Fairy Oak. Il Potere della Luce', 'media/core/9788496391963.jpeg', 1, '2023-09-27 10:44:39.528554', '2023-09-27 10:44:39.528554', 1280, 48, 6, 2, NULL, '', '01_05', 'Fairy Oak III', 466, 'El último e interesante episodio de la trilogía. El plan del Señor de la Oscuridad ha dado resultado: el miedo a la traición corroe Fairy Oak y obliga a Pervinca a escapar. Las gemelas están separadas…. La Antigua Alianza entre Luz y Oscuridad se ha roto. las defensas de los Mágicos se derrumban, la guerra está perdida. pero quizá no todo sea como parece. la luz aún tiene que demostrar su poder y el amor esconde todavía un secreto.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2295, '9788418538858', 'Fairy Oak. La Historia Perdida', 1, '2020', 400, 'La storia perduta', 'media/core/9788418538858.jpeg', 1, '2023-09-27 10:50:38.197866', '2023-09-27 10:50:38.197866', 1280, 48, 6, 2, NULL, '', '01_05', 'Fairy Oak', 467, 'Con ocasión del 15º aniversario de la serie, una nueva historia nos lleva de vuelta a Fairy OakINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2296, '9788472237391', 'Una Princesa en Berlín', 7, '2004', 504, 'A Princess in Berlin', 'media/core/9788472237391.jpeg', 1, '2023-09-27 10:54:10.383914', '2023-09-27 10:54:10.383914', 1281, 1, 6, 2, 'Fabula', '', '01_05', NULL, 12, 'Berlín, 1922. Reina la confusión en la capital alemana tras la victoria aliada. Recorren las calles, con banderas rojas, las víctimas de la más impresionante inflación de todos los tiempos. Y, tras ellos, las bandas incontroladas de ex-combatientes nacionalistas, que siguen las consignas de un oscuro militar austríaco, Adolf Hitler. Indiferentes al barullo callejero, conservan aún sus privilegios unas pocas familias aristocráticas, en su mayoría judíos, de gran tradición en el mundo de las finanzas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2297, '9788433976598', 'Seda', 4, '2016', 125, 'Seta', 'media/core/9788433976598.jpeg', 1, '2023-09-27 11:05:52.384987', '2023-09-27 11:05:52.384987', 1282, 1, 6, 2, 'Colección compactos', '', '01_05', NULL, 6, 'Alessandro Baricco presentaba la edición italiana de Seda, que tuvo un éxito extraordinario en su país, con estas palabras: Esta no es una novela. Ni siquiera es un cuento. Esta es una historia. Empieza con un hombre que atraviesa el mundo y acaba con un lago que permanece inmóvil, en una jornada de viento. El hombre se llama Hervé Joncour. El lago, no se sabe. Se podría decir que es una historia de amor. Pero si solamente fuera eso, no habría valido la pena contarla. En ella están entremezclados deseos y dolores que se sabe muy bien lo que son pero que no tienen un nombre exacto que los designe. En todo caso, ese nombre no es amor. Esto es algo muy antiguo. Cuando no se tiene un nombre para decir las cosas, entonces se utilizan historias. Así funciona. Desde hace siglos. Todas las historias tienen una música propia. Esta tiene una música blanca. Es importante decirlo porque la música blanca es una música extraña, a veces te desconcierta: se ejecuta suavemente y se baila lentamente. Cuando la ejecutan bien es como oír el silencio y a los que la bailan estupendamente se les mira y parecen inmóviles. La música blanca es algo rematadamente difícil.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2298, '9788417430481', 'La Mil y Una Noches', 1, '2019', 384, 'Alf layla wa-layla', 'media/core/9788417430481.jpeg', 1, '2023-09-27 11:09:04.414838', '2023-09-27 11:09:04.414838', 1127, 44, 6, 2, 'Clásicos Ilustrados', '', '01_05', NULL, 468, 'Las mil y una noches es una recopilación de historias inspiradas por la tradición oral, cuya relevancia fue curiosamente marginal dentro del contexto de la literatura árabe medieval. No obstante, a ella le debemos la fascinación por lo oriental que surgió a partir del siglo XVIII gracias a estudiosos como Antoine Galland, el autor de la primera traducción al frances, o exploradores como Richard Francis Burton, que la tradujo al ingles respetando', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2299, 'B49594', 'Gora', 1, '1972', 496, NULL, 'media/core/sin-imagen_yv9ajlR.jpg', 1, '2023-09-27 11:12:53.643181', '2023-09-27 11:12:53.643181', 627, 1, 6, 2, NULL, '', '01_05', NULL, 17, 'Considerada como una de las novelas más representativas y complejas de Tagore, Gora presenta un retrato magistral de la sociedad bengalí a través de la epopeya de su protagonista. En el relato se entreteje una historia que muestra una India cuya diversidad de razas, culturas y religiones, pero sobre todo la división en castas, provocan un desgarro que lamentablemente no se aleja del que vive en la actualidad.   En Gora, Tagore hace su universal llamamiento, contra toda casta, contra todo puritanismo,', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2300, '8437901375', 'El jardinero', 1, '1981', 140, NULL, 'media/core/8437901375.jpg', 1, '2023-09-27 11:15:19.119616', '2023-09-27 11:15:19.119616', 627, 4, 2, 2, NULL, '', '01_05', NULL, 469, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2301, '9788498384925', 'Una vacante imprevista', 1, '2012', 608, 'The Casual Vacancy', 'media/core/9788498384925.jpeg', 1, '2023-09-27 11:17:35.210092', '2023-09-27 11:17:35.210092', 798, 1, 6, 2, NULL, '', '01_05', NULL, 29, 'La primera novela para adultos de J.K. Rowling.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2302, '9781786892737', 'The Midnight Library', 1, '2021', 288, NULL, 'media/core/9781786892737.jpg', 1, '2023-09-28 06:27:46.996823', '2023-09-28 06:27:46.996823', 1283, 1, 6, 2, NULL, '', '01_05', NULL, 470, 'Nora''s life has been going from bad to worse. Then at the stroke of midnight on her last day on earth she finds herself transported to a library. There she is given the chance to undo her regrets and try out each of the other lives she might have lived. Which raises the ultimate question: with infinite choices, what is the best way to live?', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2303, '9788427202146', 'Sinsajo', 3, '2012', 1, 'Mockingjay', 'media/core/9788427202146.jpeg', 1, '2023-09-28 06:30:31.188971', '2023-09-28 06:30:31.188971', 1284, 48, 6, 2, NULL, '', '01_05', 'Los Juegos del Hambre III', 135, 'Katniss Everdeen ha sobrevivido dos veces a los Juegos del Hambre, pero  no está a salvo. La revolución se extiende y, al parecer, todos han  tenido algo que ver en el meticuloso plan, todos excepto Katniss.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2304, '9788427202139', 'En llamas', 3, '2012', 416, 'Catching Fire', 'media/core/9788427202139.jpeg', 1, '2023-09-28 06:31:25.224705', '2023-09-28 06:33:42.482353', 1284, 48, 6, 2, NULL, '', '01_05', 'Los Juegos del Hambre II', 135, 'Katniss Everdeen ha sobrevivido a Los juegos del hambre. Pero el Capitolio quiere venganza.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2305, '9788467235630', 'Los Juegos del Hambre', 1, '2009', 379, 'The Hunger Games', 'media/core/9788467235630.jpg', 1, '2023-09-28 06:34:57.588421', '2023-09-28 06:38:20.755800', 1284, 48, 6, 2, NULL, '', '01_05', 'Los Juegos del Hambre I', 101, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2306, '9784915512575', 'ハリー・ポッターと謎のプリンス', 1, '2006', 509, 'Harry Potter and the Half-Blood Prince', 'media/core/9784915512575.jpg', 1, '2023-09-28 06:43:25.772882', '2023-09-28 06:43:25.772882', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 3', 471, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2307, '9781408855683', 'Harry Potter and the Goblet of Fire', 1, '2014', 617, NULL, 'media/core/9781408855683.jpeg', 1, '2023-09-28 06:46:42.090716', '2023-09-28 06:46:42.090716', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 4', 472, 'HARRY POTTER AND THE GOBLET OF FIRE (edición en inglés)INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2308, '9789722325332', 'Harry Potter e a Pedra Filosofal', 1, '2018', 254, 'Harry Potter and the Philosopher''s Stone', 'media/core/9789722325332.jpeg', 1, '2023-09-28 06:49:19.164449', '2023-09-28 06:49:19.164449', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 1', 473, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2309, '9655110281', 'ג''יי. קיי. רולינג', 1, '2001', 321, 'Harry Potter and the Philosopher''s Stone', 'media/core/9655110281.jpg', 1, '2023-09-28 06:54:24.438545', '2023-09-28 06:54:24.438545', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 1', 474, 'הארי פוטר מעולם לא היה כוכב של נבחרת קווידיץ'' שמזכה את קבוצתו בנקודות תוך כדי רכיבה על מטאטא גבוה מעל האדמה. הוא לא מכיר לחשי קסם, מעולם לא גידל דרקון מביצה, ומעולם לא עטה גלימת היעלמות. הוא מכיר רק את חייו האומללים עם משפחת דרסלי - דודו ודודתו האיומים ובנם הדוחה דאדלי, בריון מפונק, מגודל ושמן. החדר של ארי הוא ארון פיצפון בתחתית המדרגות, והוריו המאמצים מעולם לא חגגו את יום הולדתו.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2310, '9781408866184', 'Harrius Potter et Philosophi Lapis', 1, '2003', 249, 'Harry Potter and the Philosopher''s Stone', 'media/core/9781408866184.jpeg', 1, '2023-09-28 06:57:20.485851', '2023-09-28 06:57:20.485851', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 1', 472, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2311, '9789533167787', 'Harry Potter i kamen mudraca', 1, '2014', 245, 'Harry Potter and the Philosopher''s Stone', 'media/core/9789533167787.jpg', 1, '2023-09-28 07:00:51.004801', '2023-09-28 07:00:51.004801', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 1', 475, 'Roditelji Harryja Pottera stradali su dok je još bio jednogodišnja beba. Deset je dugih i neveselih ljeta Harry proveo kao neželjen gost pod krovom Dursleyjevih, pod grdnjom navijek ljute tete Petunije, pod podozrivim pogledom neugodnog tetka Vernona i pod pakosnim udarcima bratića Dudleyja', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2312, '9782070612369', 'À l''école des sorciers', 1, '2010', 1, NULL, 'media/core/9782070612369.jpg', 1, '2023-09-28 07:05:03.059839', '2023-09-28 07:05:03.059839', 798, 48, 6, 2, 'Folio Junior', '', '01_05', NULL, 293, 'Le jour de ses onze ans, Harry Potter, un orphelin élevé par un oncle et une tante qui le détestent, voit son existence bouleversée. Un géant vient le chercher pour l''emmener à Poudlard, une école de sorcellerie ! Voler en balai, jeter des sorts, combattre les trolls : Harry se révèle un sorcier doué. Mais quel est le mystère qui l''entoure ? Et qui est l''effroyable V..., le mage dont personne n''ose prononcer le nom ? Amitié, surprises, dangers, scènes comiques, Harry découvre ses pouvoirs et la vie à Poudlard. Le premier tome des aventures du jeune héros vous ensorcelle aussitôt !', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2313, '9780751565355', 'Harry Potteer and the Cursed Child. Parts One and Two', 1, '2016', 330, NULL, 'media/core/9780751565355.jpeg', 1, '2023-09-28 07:10:36.934646', '2023-09-28 07:10:36.934646', 798, 41, 6, 2, NULL, '', '01_05', NULL, 476, 'Based on an original new story by J.K. Rowling, Jack Thorne and John Tiffany, a new play by Jack Thorne, Harry Potter and the Cursed Child is the eighth story in the Harry Potter series and the first official Harry Potter story to be presented on stage. The play will receive its world premiere in London''s West End on 30th July 2016.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2314, '9788498381405', 'Harry Potter y las Reliquias de la Muerte', 1, '2008', 640, 'Harry Potter and the Deathly Hallows', 'media/core/9788498381405.jpeg', 1, '2023-09-28 07:13:50.665840', '2023-09-28 07:13:50.665840', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 7', 29, '"Entregadme a Harry Potter -dijo la voz de Voldemort- y nadie sufrirá  ningún daño. Entregadme a Harry Potter y dejare el colegio intacto. Entregadme a Harry Potter y sereis recompensados."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2315, '9788478889907', 'Harry Potter y el misterio del príncipe', 6, '2009', 576, 'Harry Potter and the Half-Blood Prince', 'media/core/9788478889907.jpeg', 1, '2023-09-28 07:16:37.742770', '2023-09-28 07:16:37.742770', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 6', 29, 'Con dieciseis años cumplidos, Harry inicia el sexto curso en Hogwarts en  medio de terribles acontecimientos que asolan Inglaterra. Elegido capitán del equipo de quidditch, los ensayos, los exámenes y las chicas ocupan todo su tiempo, pero la tranquilidad dura poco.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2316, '9788478887422', 'Harry Potter y la Orden del Fénix', 10, '2008', 928, 'Harry Potter and the Order of the Phoenix', 'media/core/9788478887422.jpeg', 1, '2023-09-28 07:19:27.536139', '2023-09-28 07:19:27.536139', 798, 48, 6, 2, NULL, '', '01_05', 'Harry Potter 5', 128, '«El director cree que no es conveniente que eso continúe ocurriendo.  Quiere que te enseñe a cerrar tu mente al Señor Tenebroso.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2317, '8467435267', 'La princesa prometida', 1, '2006', 478, 'The Princess Bride', 'media/core/8467435267.jpg', 1, '2023-09-28 16:00:14.088920', '2023-09-28 16:00:14.088920', 1285, 48, 6, 2, 'Biblioteca Fantástica Jvenil', '', '0201', NULL, 477, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2318, '9788427933057', 'Jim Botón y los trece salvajes', 9, '1997', 253, 'Jim Knopf und die wilde 13', 'media/core/9788427933057.jpg', 1, '2023-09-28 16:03:16.790700', '2023-09-28 16:03:16.790700', 818, 48, 6, 2, NULL, '', '0201', NULL, 414, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2319, '9788427933040', 'Jim Botón y Lucas el maquinista', 17, '2004', 230, 'Jim Knopf und Lucas der Lokomotiv Führer', 'media/core/9788427933040.jpg', 1, '2023-09-28 16:06:06.186801', '2023-09-28 16:06:06.186801', 818, 48, 6, 2, NULL, '', '0201', NULL, 414, 'Un maquinista de tren llamado Lucas vive junto a su locomotora Emma en Lummerland en un país extraordinariamente pequeño (que además es una isla), ya que en él conviven un rey llamado Alfonso Doce-menos-cuarto, un hombre llamado Manga que siempre está paseando con un sombrero hongo en la cabeza y un paraguas cerrado bajo el brazo, así como una mujer grande y gorda con las mejillas rojas como una manzana llamada señora Quée. Todas estas personas viven en este país que, dice Ende, es más o menos el doble de grande que nuestra vivienda y está ocupado en su mayor parte por una montaña con dos picos, uno alto y el otro más bajo. De repente un día llega un gran paquete en un barco correo con una dirección muy extraña y al abrirlo aparece un niño, un niño negro al que ponen por nombre Jim. Con el tiempo Jim se va haciendo mayor y, claro, ¡¡el país es muy pequeño! Vaya problema para el rey, que llama a Lucas y le dice que tendrán que desprenderse de Emma, la locomotora. El maquinista cabizbajo se retira y decide que si tiene que irse ella ál también lo hará. Para Jim su mejor amigo es Lucas y no quiere dejarle, por lo que resuelto le dice que él también se va con ellos. A partir de este momento estos tres personajes, Jim Boton, Lucas el maquinista, y la locomotora Emma empiezan a vivir las más extraordinarias aventuras.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2320, '9788433972743', 'Nunca me abandones', 8, '2012', 351, 'Never Let Me Go', 'media/core/9788433972743.jpeg', 1, '2023-09-28 16:08:28.368819', '2023-09-28 16:08:28.368819', 963, 1, 6, 2, 'Colección compactos', '', '0201', NULL, 6, 'A primera vista, los jovencitos que estudian en el internado de Hailsham son como cualquier grupo de adolescentes. Practican deportes, tienen clases de arte y descubren el sexo, el amor y los juegos del poder. Hailsham es una mezcla de internado victoriano y de colegio para hijos de hippies de los años sesenta donde no dejan de repetirles que son muy especiales, que tienen una misión en el futuro, y se preocupan por su salud. Los jóvenes también saben que son estériles y que nunca tendrán hijos, de la misma manera que no tienen padres. Kathy, Ruth y Tommy fueron pupilos en Hailsham, y también fueron un juvenil triángulo amoroso. Y ahora, Kathy se permite recordar Hailsham y cómo ella y sus amigos descubrieron poco a poco la verdad. Y el lector de esta novela, utopía gótica, irá descubriendo con Kathy que Hailsham es una representación donde los jóvenes actores no saben que sólo son el secreto terrible de la buena salud de una sociedad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2321, '9788433980878', 'Klara y el Sol', 1, '2021', 334, 'Klara and the Sun', 'media/core/9788433980878.jpeg', 1, '2023-09-28 16:10:36.902580', '2023-09-28 16:10:36.902580', 963, 1, 6, 2, 'Panorama de narrativas', '', '0201', NULL, 6, 'Klara es una AA, una Amiga Artificial, especializada en el cuidado de niños. Pasa sus días en una tienda, esperando a que alguien la adquiera y se la lleve a una casa, un hogar. Mientras espera, contempla el exterior desde el escaparate. Observa a los transeúntes, sus actitudes, sus gestos, su modo de caminar, y es testigo de algunos episodios que no acaba de entender, como una extraña pelea entre dos taxistas. Klara es una AA singular, es más observadora y más dada a hacerse preguntas que la mayoría de sus congeneres. Y, como sus compañeros, necesita del Sol para alimentarse, para cargarse de energía...INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2322, '9788425359934', 'El gato que amaba los libros', 1, '2022', 253, '本 お 守ろうとする 猫 の話', 'media/core/9788425359934.jpeg', 1, '2023-09-28 16:19:41.266903', '2023-09-28 16:19:41.266903', 1286, 1, 6, 2, 'Grijalbo narrativa', '', '0201', NULL, 45, 'La epopeya de Rintaro, el joven heredero de una entrañable librería de  viejo, y de Tora, un sabio e ingenioso gato atigrado, se ha convertido  en un fulgurante éxito internacional. Su emocionante misión consiste  nada más y nada menos que en salvar los libros que están en peligro y  extender así el amor por estos objetos, bellos e inigualables, que son parte imprescindible de nuestra vida.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2323, '9788483835043', 'Tokyo Blues', 32, '2016', 384, 'ノルウェイの森', 'media/core/9788483835043.jpeg', 1, '2023-09-28 16:23:03.708635', '2023-09-28 16:23:03.708635', 243, 1, 2, 2, 'Maxi Turquets', '', '0201', NULL, 12, 'Una historia de amor triangular que se convierte en el relato de una educación sentimental pero también de las pérdidas que implica toda maduración .INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2324, '9788417419561', 'Abrazado a las estrellas', 1, '2020', 184, NULL, 'media/core/9788417419561.jpeg', 1, '2023-09-28 16:28:10.521030', '2023-09-28 16:28:10.521030', 1287, 4, 6, 2, 'Poetica Satori', '', '0201', NULL, 478, 'Chūya Nakahara es uno de los grandes poetas japoneses del siglo xx. A pesar de no gozar de reconocimiento durante su corta vida, Chūya Nakahara renovó por completo la poesía japonesa, liberándola de los cánones estéticos de la tradición y abriendo las puertas a la modernidad. Sus poemas están impregnados de melancolía y captan de un modo genuino el sentir de un autor que ha sido elevado a categoría de icono cultural en Japón.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2325, '9788418668050', 'Agujero', 1, '2021', 189, '穴', 'media/core/9788418668050.jpeg', 1, '2023-09-28 17:18:34.008653', '2023-09-28 17:18:34.008653', 1288, 1, 6, 2, NULL, '', '0201', NULL, 367, 'Al marido de Asa le han ofrecido un trabajo en una zona remota de Japón, junto al hogar en que nació. Durante un verano excepcionalmente cálido, la pareja se instala junto a la casa de los suegros, entre el ensordecedor e invasivo rugido de las cigarras. Hasta que un día Asa se topa con una extraña criatura, que no se parece a nada. La sigue hasta el terraplén de un río y cae en un agujero que parece haber sido creado para ella, y en el que queda atrapada para siempre. Casas asoladas por plagas de comadrejas. Niños fantasma. Pasillos que nos transportan «al otro lado», como si Alicia reviviera en el Japón de la tecnología punta. Oyamada firma un tríptico narrativo literariamente puro sobre la idea de que el entorno que nos rodea puede anticipar nuestras emociones y hasta nuestro destino.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2326, '9788483835241', 'Kafka en la orilla', 23, '2020', 714, '岸辺のカフカ (Umibe no Kafuka)', 'media/core/9788483835241.jpeg', 1, '2023-09-28 17:22:25.121339', '2023-09-28 17:22:25.121339', 243, 1, 2, 2, 'Maxi Turquets', '', '0201', NULL, 12, 'Pasado y presente, sueño y vigilia, se funden en una versión inusitada de la tragedia de Edipo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2327, '9788483832967', 'IQ84 (Libros 1 y 2)', 11, '2019', 737, 'いちきゅうはちよん (Ichi kyū hachi yon)', 'media/core/9788483832967.jpeg', 1, '2023-09-28 17:25:55.092543', '2023-09-28 17:25:55.092543', 243, 1, 6, 2, 'Colección Andanzas', '', '0201', NULL, 12, 'En japones, la letra q y el número 9 son homófonos, los dos se pronuncian kyu, de manera que 1Q84 es, sin serlo, 1984, una fecha de ecos orwellianos. Esa variación en la grafía refleja la sutil alteración del mundo en que habitan los personajes de esta novela, que es, tambien sin serlo, el Japón de 1984. En ese mundo en apariencia normal y reconocible se mueven Aomame, una mujer independiente, instructora en un gimnasio, y Tengo, un profesor de matemáticas. Ambos rondan los treinta años, ambos llevan vidas solitarias y ambos perciben a su modo leves desajustes en su entorno, que los conducirán de manera inexorable a un destino común. Y ambos son más de lo que parecen: la bella Aomame es una asesina; el anodino Tengo, un aspirante a novelista al que su editor ha encargado un trabajo relacionado con La crisálida del aire, una enigmática obra dictada por una esquiva adolescente. Y, como telón de fondo de la historia, el universo de las sectas religiosas, el maltrato y la corrupción, un universo enrarecido que el narrador escarba con precisión orwelliana.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2328, '9788499989600', 'El impulso', 1, '2023', 256, '튜브 (Tube)', 'media/core/9788499989600.jpeg', 1, '2023-09-28 17:31:02.442870', '2023-09-28 17:31:02.442870', 1289, 1, 6, 2, 'Temas de hoy', '', '0201', NULL, 7, 'Andrea Kim Seong-gon es un fracasado. En los negocios, en lo familiar, en lo económico. Ni siquiera cuando toma la decisión de suicidarse tiene éxito. Pero es entonces, desde lo más hondo del abismo, que se obsesiona con algo nimio: cambiar su postura corporal. Lo que Seong-gon no sabe es que este pequeño gesto pondrá en marcha una serie de cambios que renovarán por completo su vida.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2329, '9781529376043', 'Shoko''s Smile', 1, '2022', 256, '쇼코의 미소 (syokoui miso)', 'media/core/9781529376043.jpg', 1, '2023-09-28 17:36:31.010426', '2023-09-28 17:36:31.010426', 1290, 1, 6, 2, 'The bestselling story collection', '', '0201', NULL, 479, 'In crisp, unembellished prose, Choi Eunyoung paints intimate portraits of the lives of young women in South Korea, balancing the personal with the political. In the title story, a fraught friendship between an exchange student and her host sister follows them from adolescence to adulthood. In ''A Son...', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2330, '9788418897771', 'La espera', 1, '2023', 256, '기다림 (gidalim)', 'media/core/9788418897771.jpeg', 1, '2023-09-28 17:39:52.152122', '2023-09-28 17:39:52.152122', 1291, 34, 6, 2, NULL, '', '0201', NULL, 480, 'Gwija tiene 92 años y vive en Corea del Sur. Tras décadas de espera, desea reencontrarse con su hijo mayor. Lo perdió de vista en una columna de refugiados, huyendo del norte, mientras amamantaba al bebé que llevaba en brazos. En un encuentro auspiciado por la Cruz Roja, su amiga Jeong-Sun acaba de reunirse con su hermana pequeña después de sesenta y ocho años separadas. Gwija solo desea poder seguir sus pasos en una nueva edición.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2331, '9788483837061', 'Kitchen', 6, '2021', 206, 'Kitchen', 'media/core/9788483837061.jpeg', 1, '2023-09-28 17:42:33.120953', '2023-09-28 17:42:33.120953', 1292, 1, 6, 2, 'Maxi Turquets', '', '0201', NULL, 12, 'Cuando la jovencísima Mikage se queda sola a la muerte de su abuela, se refugia en la cocina de su vasta casa. Un día, sin embargo, un amable muchacho llama a su puerta y le propone que vaya a vivir con el y con su madre, Eriko. Sin embargo, esta hermosa y acogedora mujer no es quien parece ser. Una fábula en la que la soledad y la aridez emocional quedan mitigadas por la inmensa sabiduría de otro mundo ancestral.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2332, '9788415472568', 'Muchacho de oro, muchacha esmeralda', 1, '2013', 237, 'Gold Boy, Emerald Girl', 'media/core/9788415472568.jpg', 1, '2023-09-28 17:46:29.790373', '2023-09-28 17:46:29.790373', 1293, 44, 6, 2, NULL, '', '0201', NULL, 46, 'Ambientados en su mayoría en la China del siglo XXI, esta bella colección de relatos cortos se nutre de personajes que tratan de reconducir sus vidas en un mundo nuevo y desconocido para ellos. Vecinos de un edificio ruinoso que contemplan con pavor y asombro el boom inmobiliario; una empresaria local metida a filántropo que acoge en su hogar a mujeres en situación delicada; un grupo de ancianas que descubre la fama en el último tramo de sus vidas como detectives privadas especializadas en aventuras extramatrimoniales; una joven que publica un blog para hacer pública la infidelidad de su padre. La magistral colección de Yiyun Li recoge la vida cotidiana de la gente, una vida que se ha visto convulsionada por el cambio global, y con ello se demuestra como una de las escritoras imprescindibles de nuestros tiempos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2333, '9788499987910', 'Almendra', 1, '2020', 252, '아몬드 (amondeu)', 'media/core/9788499987910.jpeg', 1, '2023-09-28 17:57:42.917225', '2023-09-29 07:59:40.986474', 1289, 1, 6, 2, 'Temas de hoy', '', '0201', NULL, 7, 'Yunjae tiene dieciséis años, está en la edad de las emociones desbordadas, el amor y la rabia. Pero las amígdalas de su cerebro son pequeñas, más pequeñas que una almendra y, como consecuencia,Yunjae es incapaz de sentir nada. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2334, '9780553448184', 'The Vegetarian', 1, '2015', 188, '채식주의자 (chaesigjuuija)', 'media/core/9780553448184.jpeg', 1, '2023-09-28 18:01:41.881509', '2023-09-28 18:01:41.881509', 1294, 1, 6, 2, NULL, '', '0201', NULL, 481, 'Before the nightmare, Yeong-hye and her husband lived an ordinary life. But when splintering, blood-soaked images start haunting her thoughts, Yeong-hye decides to purge her mind and renounce eating meat. In a country where societal mores are strictly obeyed, Yeong-hye''s decision to embrace a more plant-like existence is a shocking act of subversion. And as her passive rebellion manifests in ever more extreme and frightening forms, scandal, abuse, and estrangement begin to send Yeong-hye spiraling deep into the spaces of her fantasy. In a complete metamorphosis of both mind and body, her now dangerous endeavor will take Yeong-hye impossibly, ecstatically, tragically far from her once-known self altogether. A disturbing, yet beautifully composed narrative told in three parts, "The Vegetarian" is an allegorical novel about modern day South Korea, but also a story of obsession, choice, and our faltering', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2335, '9788416738342', 'Actos humanos', 1, '2018', 271, '소년이 온다', 'media/core/9788416738342.jpeg', 1, '2023-09-28 18:07:08.838466', '2023-09-28 18:07:08.838466', 1294, 1, 6, 2, NULL, '', '0201', NULL, 482, 'En mayo de 1980, en la ciudad de Gwangju el ejército sofocó una sublevación popular provocando miles de muertos.Actos humanos revive esos terribles sucesos a través de las experiencias de siete personajes diferentes: la tortura, el miedo, la angustia de no encontrar a los desaparecidos, el duelo, el sentimiento de culpa del superviviente, las pesadillas, las heridas, las secuelas, los reencuentros... Y el recuerdo de los muertos, su voz y su luz.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2336, '9788416738519', 'Blanco', 1, '2020', 151, NULL, 'media/core/9788416738519.jpeg', 1, '2023-09-28 18:09:27.998709', '2023-09-28 18:09:27.998709', 1294, 1, 6, 2, NULL, '', '0201', NULL, 482, 'A partir de la redacción aparentemente banal de una lista de cosas blancas, Han Kang hace un conmovedor ejercicio de introspección, buscando el epicentro de su dolor existencial.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2337, '9788418052071', 'Hierba', 1, '2002', 481, NULL, 'media/core/9788418052071.jpeg', 1, '2023-09-29 06:58:59.025928', '2023-09-29 06:58:59.025928', 1291, 34, 6, 2, NULL, '', '0201', NULL, 480, 'Hierba es la historia real de una superviviente: Lee Ok-Sun, una  joven coreana que durante la Guerra del Pacífico fue explotada como  «mujer de consuelo», el eufemismo utilizado por el ejército imperial japonés para referirse a sus esclavas sexuales. A día de hoy, aquel sigue siendo uno de los capítulos más oscuros del siglo XX.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2338, '9788491040668', 'Bari, la princesa abandonada', 1, '2015', 315, 'Bari Degui', 'media/core/9788491040668.jpeg', 1, '2023-09-29 07:03:34.662851', '2023-09-29 07:03:34.662851', 1295, 1, 6, 2, NULL, '', '0201', NULL, 69, 'Cheong Jin, Corea del Norte. Una niña, la séptima hija de la familia de un funcionario, es abandonada al poco de nacer por no ser varón. Rescatada por la abuela, le da el nombre de Bari, como la princesa de una antigua leyenda que sufrió el mismo destino y viajó a los confines de la tierra en busca de un elixir que trajera paz y sosiego a las almas de los vivos y de los muertos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2339, '9788420437927', 'Kim Ji-young, nacida en 1982', 1, '2019', 157, 'Palsip Yi Nyeon Saeng Kim Jiyeong', 'media/core/9788420437927.jpeg', 1, '2023-09-29 07:09:21.156731', '2023-09-29 07:09:21.156731', 1296, 1, 6, 2, 'Narrativa Internacional', '', '0201', NULL, 10, '«Ni siquiera yo sé si me casaré o si tendré hijos. O puede que me muera  antes. ¿Por qué tengo que renunciar a lo que quiero ser o hacer por un futuro que no sé si llegará o no?»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2340, '9788494716935', 'Fábulas y leyendas de Corea. Duendes, fantasmas y hadas', 1, '2017', 196, 'Korean Folk Tales. Imps, Ghosts and Fairies', 'media/core/9788494716935.jpeg', 1, '2023-09-29 07:14:24.685475', '2023-09-29 07:14:24.685475', 1297, 44, 6, 2, NULL, '', '0201', NULL, 483, 'Esta recopilación de leyendas coreanas basadas en las tres grandes religiones del Lejano Oriente (taoísmo, budismo y confucionismo) servirá de guía a cualquiera que desee adentrarse en las profundidades del alma oriental y descubrir las peculiares criaturas que lo habitan.     En ellas descubriremos que las brujas existen y pueden ser honradas, nos enfrentaremos a gigantes devoradores de hombres y a serpientes rencorosas, visitaremos casas encantadas y aprenderemos por qué no hay que temer a', 'Junto con Yi RyukINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2341, '9788499429397', 'El corazón de las tinieblas', 1, '2020', 159, 'Heart of Darkness', 'media/core/9788499429397.jpeg', 1, '2023-09-29 07:17:16.843215', '2023-09-29 07:17:16.843215', 909, 1, 6, 2, 'Austral Singular', '', '0201', NULL, 484, 'El clásico de Joseph Conrad sobre el colonialismo, que inspiró la película“Apocalypse Now”INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2342, '9788433966667', 'El lector', 25, '2018', 203, 'Der Vorleser', 'media/core/9788433966667.jpeg', 1, '2023-09-29 07:21:13.688482', '2023-09-29 07:21:13.688482', 1298, 1, 6, 2, 'Colección compactos', '', '0201', NULL, 6, 'Un adolescente conoce a una mujer madura con la que inicia una relación amorosa. Antes de acostarse juntos, ella siempre le pide que le lea fragmentos de Goethe, Schiller&hasta que un día ella desaparece. Siete años después, el joven, que estudia derecho, acude al juicio de cinco mujeres acusadas de crímenes nazis y descubre que una de ellas es su antigua amante. Una deslumbrante novela sobre el amor, la culpa, el horror y la piedad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2343, '9788433973382', 'El hombre que confundió a su mujer con un sombrero', 15, '2017', 298, 'The Man Who Mistook His Wife for a Hat', 'media/core/9788433973382.jpg', 1, '2023-09-29 07:27:06.819401', '2023-09-29 07:27:06.819401', 1299, 44, 6, 2, 'Colección compactos', '', '0201', NULL, 6, 'En este libro, Oliver Sacks narra veinte historiales médicos de pacientes perdidos en el mundo extraño y aparentemente irremediable de las enfermedades neurológicas. Se trata de casos de individuos, aquejados por inauditas aberraciones de la percepción que han perdido la memoria, y con ella, la mayor parte de su pasado; que son incapaces de reconocer a sus familiares o los objetos cotidianos; que han sido descartados como retrasados mentales y que, sin embargo, poseen insólitos dones artísticos o científicos. Por extraños que parezcan estos casos, el doctor Sacks los relata con pasión humana y gran talento literario. Son estudios que nos permiten acceder al universo de los enfermos nerviosos y comprender su situación frente a las adversidades. Como gran médico, Oliver Sacks nunca pierde de vista el', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2344, '9788491814870', 'Delta de Venus', 1, '2019', 350, 'Delta of Venus', 'media/core/9788491814870.jpeg', 1, '2023-09-29 07:29:33.964614', '2023-09-29 07:29:33.964614', 856, 44, 6, 2, NULL, '', '0201', NULL, 69, 'Escritos a principios de la década de 1940 por encargo de un excéntrico coleccionista de libros que insistía en pedir «menos poesía» y descripciones más explícitas en las escenas sexuales, los relatos de "Delta de Venus" no vieron la luz hasta los años 1970. Ambientados en torno al París de la época e hilados por la aparición recurrente de personajes comunes de distinta importancia según cada cuento, ofrecen una visión libre de las relaciones humanas, en la que el erotismo y el ansia de placer no excluyen ni la belleza ni el sentimiento, ni la amistad ni la búsqueda de la autenticidad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2345, '9788408223467', 'Agnes Grey', 1, '2020', 305, NULL, 'media/core/9788408223467.jpeg', 1, '2023-09-29 07:32:12.680153', '2023-09-29 07:32:12.680153', 1300, 1, 6, 2, 'Colección Austral', '', '0201', NULL, 7, 'El debut novelístico de la menor de las hermanas Brontë. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2346, '9788408181804', 'Cumbres borrascosas', 1, '2018', 411, 'Wuthering Heights', 'media/core/9788408181804.jpeg', 1, '2023-09-29 07:36:12.314755', '2023-09-29 07:36:12.314755', 155, 1, 6, 2, 'Colección Austral', '', '0201', NULL, 7, '«Con un par de pinceladas Emily Brontë podía conseguir retratar el espíritu de una cara de modo que no precisara cuerpo; al hablar del páramo conseguía hacer que el viento soplara y el trueno rugiera», Virginia WoolfINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2347, '9788491048961', 'Jane Eyre', 5, '2019', 644, NULL, 'media/core/9788491048961.jpeg', 1, '2023-09-29 07:38:49.164522', '2023-09-29 07:38:49.164522', 1302, 1, 6, 2, NULL, '', '0201', NULL, 69, 'Dueña de un singular temperamento desde su complicada infancia de huérfana, primero a cargo de una tía poco cariñosa y después en la escuela Lowood, Jane Eyre logra el puesto de institutriz en Thornfield Hall para educar a la hija de su atrabiliario y peculiar dueño, el señor Rochester. Poco a poco, el amor irá tejiendo su red entre ellos, pero la casa y la vida de Rochester guardan un estremecedor y terrible misterio.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2348, '9786075561646', 'Villette', 1, '2020', 468, NULL, 'media/core/9786075561646.jpg', 1, '2023-09-29 07:43:33.702886', '2023-09-29 07:43:33.702886', 1302, 1, 6, 2, 'Cranford Collection', '', '0201', NULL, 32, 'Lucy Snowe, sin familia, sin dinero, sin posición, entra a trabajar en un internado en una ciudad extranjera, Villette. No ser advertida, ni recordada, ni apreciada constituye su presente y, según cree, su destino. Madame Beck, la directora, la sujeta a sus consignas: espionaje y vigilancia; el doctor John, joven y apuesto, seductor y melancólico, cree que está enferma; el profesor Paul Emanuel, un «severo hombrecillo» que oculta, bajo su temperamento colérico, un corazón sacrificado, dice haberla conocido desde el primer momento en que la vio; incluso un fantasma -el de una monja que se recluyó por un amor prohibido- la acosa y aterroriza. Por primera vez íntegra en español, Villette fue la última novela de Charlotte Brontë, construida sobre sus recuerdos como alumna y profesora de un internado en Bruselas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2349, '9786075561837', 'La inquilina de Wildfell Hall', 1, '2021', 358, 'The Tenant of Wildfell Hall', 'media/core/9786075561837.jpg', 1, '2023-09-29 07:46:26.320036', '2023-09-29 07:46:26.320036', 1300, 1, 6, 2, 'Cranford Collection', '', '0201', NULL, 32, 'Tras muchos años de abandono, la destartalada y ruinosa mansión de Wildfell Hall es habitada de nuevo por una misteriosa mujer y su hijo de corta edad. La nueva inquilina -una viuda, al parecer- no tarda, con su carácter retraído y poco sociable, sus opiniones a menudo radicales y su extraña triste belleza, en atraerse las sospechas de la vecindad, y a la vez la rendida admiración de un joven e impetuoso agricultor. Pero la mujer tiene, en efecto un pasado... más terrible y tortuoso si cabe de lo que la peor de las murmuraciones es capaz de adivinar.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2350, '9788408216636', 'Mujercitas', 1, '2020', 686, 'Little Women', 'media/core/9788408216636.jpeg', 1, '2023-09-29 07:48:29.158431', '2023-09-29 07:48:29.158431', 393, 1, 6, 2, 'Colección Austral', '', '0201', NULL, 7, 'La versión íntegra de Mujercitas. Uno de los libros más populares e influyentes de la tradición literaria norteamericana.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2351, '9788467271072', 'El cuento de la criada', 1, '2017', 398, 'The Handmaid''s Tale', 'media/core/9788467271072.jpg', 1, '2023-09-29 07:51:22.103789', '2023-09-29 07:51:22.103789', 955, 1, 6, 2, NULL, '', '0201', NULL, 189, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2352, '9788936438753', '아몬드 (Amondeu)', 1, '2022', 266, NULL, 'media/core/9788936438753.jpeg', 1, '2023-09-29 08:03:38.288330', '2023-09-29 08:05:20.595101', 1289, 1, 6, 2, NULL, '', '0201', NULL, NULL, 'Yunjae tiene dieciséis años, está en la edad de las emociones desbordadas, el amor y la rabia. Pero las amígdalas de su cerebro son pequeñas, más pequeñas que una almendra y, como consecuencia,Yunjae es incapaz de sentir nada. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2353, '9788412577334', 'Los detalles', 1, '2023', 154, 'Detaljerna', 'media/core/9788412577334.jpeg', 1, '2023-09-29 15:51:24.453464', '2023-09-29 15:51:24.453464', 1303, 1, 6, 2, NULL, '', '0202', NULL, 485, 'Una mujer está postrada en cama con fiebre. Con una nitidez casi cegadora, su mente ociosa dibuja semblanzas de algunas personas de su pasado: una ex pareja que saltó a la fama, una amiga de carácter errático, un amor sin futuro, una madre frágil y depend', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2354, '9788973008681', 'Traditional Korean Painting', 1, '2011', 175, NULL, 'media/core/9788973008681.jpg', 1, '2023-09-29 15:57:43.245270', '2023-09-29 15:57:43.245270', 1304, 15, 6, 2, NULL, '', '0202', NULL, 486, 'Traditional Korean Painting, the 27th book in The Spirit of Korean Cultural Roots series, explores the history of Korean painting. In doing so, it gives an overview of the changes and developments in Korean painting through the ages, from prehistoric to modern times, by looking at the major trends and the philosophical and stylistic characteristics according to period.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2355, '9788491582663', 'Un corto viaje a Seúl y Corea del Sur', 1, '2020', 1, NULL, 'media/core/9788491582663.jpg', 1, '2023-09-29 16:00:02.036132', '2023-09-29 16:00:02.036132', NULL, 18, 6, 2, 'Touring', '', '0202', NULL, 66, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2356, '9781526650863', 'I want to die but i want to eat tteokbokki', 1, '2022', 192, '죽고 싶지만 떡볶이는 먹고 싶어 (juggo sipjiman tteogbokk-ineun meoggo sip-eo)', 'media/core/9781526650863.jpeg', 1, '2023-09-29 16:04:38.907164', '2023-09-29 16:04:38.907164', 1305, 1, 6, 2, NULL, '', '0202', NULL, 472, 'Baek Sehee is a successful young social media director at a publishing house when she begins seeing a psychiatrist about her - what to call it? - depression? She feels persistently low, anxious, endlessly self-doubting, but also highly judgemental of others. She hides her feelings well at work and with friends; adept at performing the calmness, even ease, her lifestyle demands. The effort is exhausting, overwhelming, and keeps her from forming deep relationships. This can''t be normal.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2357, '9788412537727', 'Tengo derecho a destruirme', 1, '2020', 119, '나는 나 자신을 파괴할 권리가 있다 (naneun na jasin-eul pagoehal gwonliga issda)', 'media/core/9788412537727.jpeg', 1, '2023-09-29 16:08:02.837811', '2023-09-29 16:08:02.837811', 1306, 1, 6, 2, NULL, '', '0202', NULL, 487, 'TENGO DERECHO A DESTRUIRMEINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2358, '9788494716966', 'Pachinko', 1, '2018', 537, NULL, 'media/core/9788494716966.jpeg', 1, '2023-09-29 16:21:22.031281', '2023-09-29 16:21:22.031281', 1307, 1, 6, 2, NULL, '', '0202', NULL, 483, '"En una pequeña aldea de pescadores a la orilla del mar del Este, un hombre tullido se casa con una muchacha de quince años. La pareja tiene una hija, su adorada Sunja. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2359, '9781908211088', 'BANKSY YOU ARE AN ACCEPTABLE LEVEL OF THREAT', 3, '2012', 225, NULL, 'media/core/9781908211088.jpeg', 1, '2023-09-29 16:25:03.263252', '2023-09-29 16:25:03.263252', NULL, 15, 6, 2, NULL, '', '0202', NULL, 488, 'Banksy is the closest thing we have to Che Guevara. Except, as far as we know, he''s never flunked medical school, shot anyone or attempted to foment revolution in the Congo. You will find, gathered lovingly together, in this book a stunning collection of photography that covers the past 10 years . If that isn''t enough there are some words too.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2360, '9780714878331', 'Korean Art from 1953', 1, '2020', 376, NULL, 'media/core/9780714878331.jpeg', 1, '2023-09-29 16:34:40.888209', '2023-09-29 16:34:40.888209', 1308, 15, 6, 2, NULL, '', '0202', NULL, 489, 'En 1953 se firmó el armisticio que dividió la península en dos países. Este libro nos cuenta el desarrollo del arte desde ese momento en las últimas siete décadas, desde el Avant Garde de los años 50, al feminismo de los 70, del nacimiento de la Gwangju Biennale en los 90 al menor conocido mundo del arte de Corea del Norte. Incluye a todos los artistas que se han asegurado un lugar en el panorama del arte contemporáneo mundial como Nam June Paik, Kimsooja, Do Ho Suh, Lee Bul, y Lee Ufan.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2361, '9781408845646', 'Harry Potter and the Philosoper''s Stone', 1, '2015', 248, NULL, 'media/core/9781408845646.jpeg', 1, '2023-09-29 16:40:24.837255', '2023-09-29 16:40:24.837255', 798, 48, 6, 2, NULL, '', '0202', NULL, 472, 'Prepare to be spellbound by Jim Kay''s dazzling depiction of the wizarding world and much loved characters in this full-colour illustrated hardback edition of the nation''s favourite children''s book  Harry Potter and the Philosopher''s Stone. Brimming with rich detail and humour that perfectly complements J.K. Rowling''s timeless classic, Jim Kay''s glorious illustrations will captivate fans and new readers alike.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2362, '9780714856629', 'La Historia del Arte', 16, '2009', 688, NULL, 'media/core/9780714856629.jpg', 1, '2023-09-29 16:45:02.069103', '2023-09-29 16:45:02.069103', 1309, 24, 6, 2, NULL, '', '0202', NULL, 489, 'El libro de arte más célebre y popular de todos los tiempos, La historia del arte ha sido un éxito de ventas internacional durante más de medio siglo, y se ha traducido a 34 idiomasINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2363, '9788430619382', 'Iluminaciones', 1, '2019', 480, NULL, 'media/core/9788430619382.jpeg', 1, '2023-09-29 16:47:57.752093', '2023-09-29 16:47:57.752093', 1310, 2, 6, 2, 'Clásicos radicales', '', '0202', NULL, 323, 'Esta es la primera selección que se publica en España de los textos fundamentalesde Walter Benjamin, escogidos cuidadosamente a partir de los cuatro volúmenes de Iluminaciones y el de Discursos interrumpidos. Benjamin fue uno de los críticos culturales más originales e indispensables del siglo XX.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2364, '9788417146658', 'El Capital. Libro I El proceso de producción del capital', 1, '2019', 1084, NULL, 'media/core/9788417146658.jpeg', 1, '2023-09-29 16:58:36.890273', '2023-09-29 16:58:36.890273', 1311, 2, 6, 2, NULL, '', '0202', NULL, 490, 'Una de las cimas del pensamiento occidental. Edición facsímil de la primera traducción directa del alemán.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2365, '9788499892719', 'Hisgoria de la fealdad', 1, '2018', 416, 'Storia della bruttezza', 'media/core/9788499892719.jpeg', 1, '2023-09-29 17:03:25.584073', '2023-09-29 17:03:25.584073', 104, 2, 6, 2, NULL, '', '0202', NULL, 204, 'Tras laHistoria de la belleza, he aquí laHistoria de la fealdad. En apariencia, belleza y fealdad son conceptos que se implican mutuamente, y por lo general se considera que la fealdad es la antítesis de la belleza, hasta el punto de que bastaría definir la primera para saber qué es la segunda. No obstante, las distintas manifestaciones de la fealdad a través de los siglos son más ricas e imprevisibles de lo que comúnmente se cree.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2366, '9788499087016', 'Historia de la Belleza', 1, '2018', 440, 'Storia della Bellezza', 'media/core/9788499087016.jpeg', 1, '2023-09-29 17:05:50.448222', '2023-09-29 17:05:50.448222', 104, 2, 2, 2, NULL, '', '0202', NULL, 204, 'Aunque ilustrada con cientos de imágenes de obras maestras de todos los tiempos, este libro no es una historia del arte. Las ilustraciones, así como una amplia antología de textos, de Pitágoras a nuestros días, sirven para reconstruir las distintas ideas de belleza que se han propuesto o discutido desde los tiempos de la Grecia clásica.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2367, '9788426421944', 'Historia de las tierras y los lugares legendarios', 1, '2013', 461, 'Storia delle Terre e dei luoghi leggendari', 'media/core/9788426421944.jpg', 1, '2023-09-29 17:10:13.224077', '2023-09-29 17:10:13.224077', 104, 2, 6, 2, NULL, '', '0202', NULL, 21, '', '');
