INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2375, '9788417800956', 'Bhagavad Gità', 1, '2021', 224, NULL, 'media/core/9788417800956.jpeg', 1, '2023-09-30 06:17:01.884566', '2023-09-30 06:17:01.884566', 1127, 10, 6, 2, NULL, '', '0202', NULL, 497, 'Presentamos por primera vez en nuestro país una edición ilustrada de la Bhagavad Gītā, texto arcano y milenario, cumbre de la sabiduría y la espiritualidad de la historia humana. Un volumen en gran formato y de una belleza arrebatadora.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2376, '9783836559249', 'Los secretos de las obras dee arte. 100 obras maestras en detalle', 1, '2016', 767, NULL, 'media/core/9783836559249.jpeg', 1, '2023-09-30 06:20:53.802660', '2023-09-30 06:20:53.802660', 572, 15, 6, 2, 'Biblitheca Universalis', '', '0202', NULL, 152, 'Conviértase en un detective de la historia del arte con este fascinante estudio sobre los más mínimos detalles de pinturas célebres en todo el mundo, y descubra las historias de personajes y políticos, modas e intrigas, estilos de vida y amores que se esconden detrás.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2377, '9782262032784', 'Dictionnaire de la peinture par les peintres', 1, '2012', 391, NULL, 'media/core/9782262032784.jpg', 1, '2023-09-30 06:24:02.652049', '2023-09-30 06:24:02.652049', 1314, 40, 6, 2, NULL, '', '0202', NULL, 498, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2378, '9788433977991', 'Historia del cine', 3, '2018', 579, NULL, 'media/core/9788433977991.jpeg', 1, '2023-09-30 06:26:53.271915', '2023-09-30 06:26:53.271915', 1315, 15, 6, 2, 'Colección compactos', '', '0202', NULL, 6, 'Aparecida en 1969, ha sido traducida y repetidamente editada, en versiones sucesivamente revisadas, convirtiéndose en un clásico.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2379, '9780810994614', 'The little Dictionary of Fashion', 1, '2007', 1, NULL, 'media/core/9780810994614.jpg', 1, '2023-09-30 06:30:43.011107', '2023-09-30 06:30:43.011107', 1316, 40, 6, 2, NULL, '', '0202', NULL, 499, '', '');
