INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2381, '9788499080598', '211 cosas que una chica lista debe saber', 4, '2012', 269, '211 Things a Bright Girl Can Do', 'media/core/9788499080598.jpeg', 1, '2023-09-30 06:40:02.280171', '2023-09-30 06:40:02.280171', 1317, 36, 6, 5, NULL, '', '0202', NULL, 204, 'C#mo bailar con un hombre m#s bajo que t#INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2382, '9780762450886', 'Poems of the Great War. An Anthology 1914-1918', 1, '2014', 239, NULL, 'media/core/9780762450886.jpeg', 1, '2023-09-30 09:17:29.363332', '2023-09-30 09:17:29.363332', 572, 4, 6, 2, NULL, '', '0204', NULL, 501, '', '');
