INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2384, '9788418141171', 'Campos de Castilla', 1, '2020', 290, NULL, 'media/core/9788418141171.jpeg', 1, '2023-09-30 09:23:26.119206', '2023-09-30 09:23:26.119206', 1035, 4, 6, 2, NULL, '', '0204', NULL, 502, 'Publicado por primera vez en 1912, Campos de Castilla supone una gran evolución en la obra de Antonio Machado, que abandona el simbolismo parisino y el aliento bohemio de su obra anterior en favor de la austeridad soriana. Crece con este libro su vocación regeneracionista, en la que coincide con otros miembros de la Generación del 98, y abre paso a un contenido sentimiento amoroso que dominará sus versos. Poemario muy celebrado por Miguel de Unamuno, Antonio Azorín y Jose Ortega y Gasset, actualmente es considerado un título clásico de la literatura española. El pintor Jose S.-Carralero ha buscado óleos entre su obra paisajística para realizar esta edición ilustrada a color que homenajea a Antonio Machado en el ochenta aniversario de su muerte.', 'Edición ilustrada');
