INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2393, '9788429756715', 'La fàbrica (1970-1971)', 1, '2005', 61, NULL, 'media/core/9788429756715.jpeg', 1, '2023-09-30 09:53:15.024498', '2023-09-30 09:53:15.024498', 1322, 4, 6, 2, 'Col.lecció Educació 62', '', '0204', NULL, 2, 'Este libro escolar de Educación secundaria contiene los conceptos fundamentales que conforman esta materia e incorpora un elevado número de ejercicios para el aprendizaje del alumno. LA FABRICA (AMB PROPOSTES DE LECTURA) de MIQUEL MARTI POL, editado por EDICIONS 62 (01/07/2005), sirve al estudiante para asimilar todo lo necesario y aprender de forma eficaz la materia. Mediante el libro LA FABRICA (AMB PROPOSTES DE LECTURA) se quiere hacer más fácil la labor de asimilación por parte del estudiante, abarcando ampliamente todos los temas, presentándolos de la forma más sencilla para el alumno y enseñando cada uno de los temas de forma simplificada y esquemática. LA FABRICA (AMB PROPOSTES DE LECTURA) es imprescindible para el grupo e incorpora nuevas metodologías eficaces que ayudan a mejorar la calidad educativa en Secundaria.', '');
