INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2398, '9788498958362', 'Antología Poética', 1, '2013', 274, NULL, 'media/core/9788498958362.jpeg', 1, '2023-09-30 10:37:08.588923', '2023-09-30 10:37:08.588923', 766, 4, 6, 2, 'Visor de poesía', '', '0204', NULL, 508, 'Federico García Lorca (1898-1936) es uno de losINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2399, '9788437601144', 'Poema del Cante Jondo / Romancero gitano', 30, '2018', 313, NULL, 'media/core/9788437601144.jpeg', 1, '2023-09-30 11:14:20.810134', '2023-09-30 11:14:20.810134', 766, 4, 6, 2, 'Letras hispánicas', '', '0204', NULL, 509, 'Estas dos obras representan la transfiguración poética del tema de Andalucía, en tono puramente lírico en la primera y con acentos dramáticos en la segunda. Suponen la cima esencial de la poesía de Lorca y han conseguido un éxito y un arraigo en la tradición literaria mayor que ningún otro libro de sus compañeros de generación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2400, '9788498958270', 'Poemas', 2, '2015', 337, NULL, 'media/core/9788498958270.jpg', 1, '2023-09-30 11:16:17.957195', '2023-09-30 11:16:17.957195', 1324, 4, 6, 2, 'Visor de poesía', '', '0204', NULL, 508, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2401, '9788439735090', 'Poesía Portátil', 1, '2018', 432, NULL, 'media/core/9788439735090.jpeg', 1, '2023-09-30 11:21:45.394422', '2023-09-30 11:21:45.394422', 572, 4, 6, 2, NULL, '', '0204', NULL, 171, '', '- Rainer Maria Rilke: Versos de un joven poetaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2402, '9788492837083', 'Calma', 1, '2010', 53, '經 (Jing)', 'media/core/9788492837083.jpeg', 1, '2023-09-30 11:26:28.011329', '2023-09-30 11:26:28.011329', 1325, 27, 6, 2, 'Alpha mini', '', '0204', NULL, 510, 'Este relato, publicado originalmente en 1932, transporta al lector a una aldea rural de la China Republicana. Shen Congwen, uno de los protagonistas de la reforma literaria y de la fundación de la narrativa moderna china, transmite al lector la serenidad y la armonía que se desprenden del paisaje idílico y de la actitud de los personajes. Sin embargo, a esta tranquilidad se yuxtapone magistralmente y en sordina la angustia de una muchacha que espera noticias de su padre y de su hermano mientras se agrava la enfermedad de su madre.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2403, '9780141397603', 'Anthem for Doomed Youth', 1, '2015', 54, NULL, 'media/core/9780141397603.jpg', 1, '2023-09-30 11:28:55.886016', '2023-09-30 11:28:55.886016', 1326, 4, 6, 2, 'Penguin Classics', '', '0204', NULL, 11, '', '');
