INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2406, 'B17882', 'Los veinte mejores poemas de Emily Brontë', 1, '2015', 61, NULL, 'media/core/B17882.jpg', 1, '2023-09-30 11:36:44.113242', '2023-09-30 11:36:44.113242', 155, 4, 6, 2, NULL, '', '0204', NULL, 7, '', 'Edición bilingüe: castellano - InglésINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2407, '9788413620923', 'Antología poética', 3, '2020', 307, NULL, 'media/core/9788413620923.jpeg', 1, '2023-09-30 11:39:55.079373', '2026-01-27 10:05:02.132623', 827, 4, 6, 2, NULL, '', '0204', NULL, 69, 'Autor de novelas, cuentos y piezas teatrales, Mario Benedetti ocupa también un lugar relevante en el ámbito de la poesía, en el que parte de sus creaciones se han convertido en canción popular. La voluntaria aproximación al lenguaje corriente, la construcción de una "épica de lo cotidiano" propiciada por la incorporación de lo social y lo político, el amor y el humor son algunos de los ejes en torno a los cuales giran los versos del gran escritor uruguayo. La presente antología poética, seleccionada por él mismo, constituye una muestra panorámica y difícilmente mejorable de lo más sustancial y conocido de sus versos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2409, '9781449474256', 'Milk and honey', 1, '2015', 204, NULL, 'media/core/9781449474256.jpeg', 1, '2023-09-30 11:51:37.206454', '2023-09-30 11:51:37.206454', 1328, 4, 6, 2, NULL, '', '0204', NULL, 511, 'The book is divided into four chapters, and each chapter serves a different purpose. Deals with a different pain. Heals a different heartache. milk and honey takes readers through a journey of the most bitter moments in life and finds sweetness in them because there is sweetness', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2410, '9781449486792', 'The Sun and her Flowers', 1, '2017', 248, NULL, 'media/core/9781449486792.jpeg', 1, '2023-09-30 11:57:42.103905', '2023-09-30 11:57:42.103905', 1328, 4, 2, 2, NULL, '', '0204', NULL, 511, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2411, '9788403519558', 'La escala de mohs', 1, '2019', 154, NULL, 'media/core/9788403519558.jpeg', 1, '2023-10-01 06:10:32.218221', '2023-10-01 06:10:32.218221', 1329, 4, 6, 2, 'Verso & cuento', '', '0204', NULL, 175, 'La escala de Mohs es una tabla de diez minerales ordenados por su dureza  que se usa para medir la maleabilidad de cualquier otro. Y  eso son  también estos poemas, una unidad de medida de nuestros principios, como  personas y como sociedad, un libro que nos pregunta salvajemente por lo  que creemos y nos creemos. "Todo el mundo se vende. Yo me vendí por tres  milímetros de iris azul tanzanita en cada ojo" escribe Gata. "Todo el mundo tiene un precio".INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2412, '9788482645643', 'El soldat fanfarró', 1, '2012', 142, 'Miles Gloriosus', 'media/core/9788482645643.jpeg', 1, '2023-10-01 06:14:26.865646', '2023-10-01 06:14:26.865646', 1330, 41, 6, 2, 'La Magrana. Clàssics de Grècia i Roma', '', '0204', NULL, 32, 'A Efes, Pirgopolinices, soldat fanfarró i vanitós, ha segrestat l#amant  de Pleusicles, Filocomàsia. Per alliberar-la, Palestrió, esclau de Pleusicles, li para una trampa: fa veure que la cortesana Acroteleucia, que fingeix ser l#esposa del veí ancià del soldat, Periplectomen, se n#ha enamorat perdudament de Pirgopolinices. Aquest, convençut d#haver fet una bona conquesta, es desempallega de Filocomàsia. Mentrestant, Periplectomen, fingint indignació per la gosadia del soldat, li prepara una', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2413, '9788429763331', 'Tragèdies tebanes (Antígona, Èdip rei, Èdip a Colonos)', 1, '2009', 315, NULL, 'media/core/9788429763331.jpeg', 1, '2023-10-01 06:18:10.537540', '2023-10-01 06:18:10.537540', 1331, 41, 6, 2, NULL, '', '0204', NULL, 2, 'La historia d''Èdip i l''esfinx, amb les seves llargues conseqüencies, es una de les llegendes de la cultura grega que han mantingut plena vigencia en l''imaginari occidental fins al dia d''avui. Sofocles, el mes clàssic dels grans dramaturgs atenesos del segle V aC, hi va consagrar les tres tragedies que aquest volum aplega en la versió extraordinària de Carles Riba. Cada obra, completa en ella mateixa, presenta un moment culminant de la historia. Antígona aborda el conflicte que sorgeix entre Creont i la seva neboda, la protagonista del drama, per si cal enterrar o no Polinices, el germà d''Antígona que ha mort lluitant contra la seva ciutat natal. Èdip rei se centra en el moment en que l''home que ha vessat la sang del seu pare i ha entrat al llit de la seva mare pren consciencia de la seva situació. I Èdip a Colonos ens porta al punt en que el protagonista, vell i cec, ha de decidir si es queda al lloc de', 'Edición comentada');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2414, '9788420725925', 'Lazarillo de Tormes', 1, '1985', 122, NULL, 'media/core/9788420725925.jpeg', 1, '2023-10-01 06:20:47.968282', '2023-10-01 06:20:47.968282', 1127, 1, 6, 2, 'Biblioteca didáctica Anaya', '', '0204', NULL, 66, 'En pleno Renacimiento, una época de extraordinaria valoración de la fama, apareció un curioso librito titulado La vida de Lazarillo de Tormes, y de sus fortunas y adversidades. Su desconocido autor ocultó su nombre en el anonimato, levantando así uno de los enigmas más duraderos de la literatura universal. El Lazarillo pone en solfa, con sutil ironía, ciertos aspectos sociales y morales bien poco decorosos de aquella España imperial. Al mismo tiempo se daban los primeros pasos para el nacimiento de la novela picaresca —otra de las manifestaciones singulares de nuestra literatura— y también de la novela moderna. Con esta novelita, su anónimo autor ha suscitado múltiples interpretaciones, a la vez que ha', '');
