INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2417, 'M14009', 'Teatro', 1, '1962', 219, NULL, 'media/core/M14009.jpg', 1, '2023-10-01 06:52:35.141175', '2023-10-01 06:52:35.141175', 1332, 41, 6, 2, 'Clásicos castellaos', '', '0204', NULL, 18, 'Obras:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2418, '9788447365456', 'Coriolano', 1, '2010', 231, NULL, 'media/core/sin-imagen_FytLU8Q.jpg', 1, '2023-10-01 06:54:45.610048', '2023-10-01 06:54:45.610048', 614, 41, 6, 2, NULL, '', '0204', NULL, 32, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2419, '9788467038019', 'Macbeth', 1, '2013', 152, NULL, 'media/core/9788467038019.jpeg', 1, '2023-10-01 06:56:27.980292', '2023-10-01 06:56:27.980292', 614, 41, 6, 2, 'Austral', '', '0204', NULL, 265, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2420, '9788467033380', 'Hamlet', 22, '2013', 215, NULL, 'media/core/9788467033380.jpeg', 1, '2023-10-01 06:58:39.312460', '2023-10-01 06:58:39.312460', 614, 41, 2, 2, 'Austral', '', '0204', NULL, 265, 'HAMLET, la obra más conocida de Shakespeare, es en realidad una pieza llena de lagunas e indefiniciones. Una obra enigmática y misteriosa, en la que cada personaje es un artista de la simulación. El propio Hamlet es un ser en continua transformación. En él caben la ceremoniosidad, la cortesía y la reflexión, junto a la pasión, la burla, el enigma o la posibilidad de la locura. En el castillo de Elsenor, en un ambiente que emana corrupción y desconfianza, claustrofóbico y hostil, se alternan escenas solemnes y reveses irónicos, al tiempo que se agita una corte de personajes cuyo sentido último será llevar a Hamlet a vencer su tensión interna y cumplir la venganza por la muerte de su padre. El magnífico estudio de Ángel-Luis Pujante que precede su traducción analiza el carácter incoherente e incierto de la tragedia y sitúa el atractivo de una obra tan compleja y rica en ese halo de misterio que suscita la duda, requiere la meditación y que la ha convertido en uno de los grandes mitos de Occidente.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2421, '9781853262548', 'Much Ado about Nothing', 1, '1992', 104, NULL, 'media/core/9781853262548.jpg', 1, '2023-10-01 07:01:00.990910', '2023-10-01 07:01:00.990910', 614, 41, 6, 2, 'Wordsworth Classics', '', '0204', NULL, 462, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2422, '9781840224337', 'Romeo and Juliet', 1, '2000', 125, NULL, 'media/core/9781840224337.jpeg', 1, '2023-10-01 07:08:30.550146', '2023-10-01 07:08:30.550146', 614, 41, 6, 2, 'Wordsworth Classics', '', '0204', NULL, 462, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2423, '9788437600925', 'La vida es sueño', 35, '2013', 203, NULL, 'media/core/9788437600925.jpeg', 1, '2023-10-01 07:11:19.804089', '2023-10-01 07:11:19.804089', 768, 41, 6, 2, 'Letras hispánicas', '', '0204', NULL, 153, 'He aquí la creación más lograda y de carácter más universal de Calderón. "La vida es sueño" es, en síntesis, la plasmación barroca de la idea de la fugacidad de la vida con todos los aditamentos geniales de construcción, caracteres y estilo que el autor supo imprimirle. Con este pesimismo radical sobre el valor de la vida humana se interfiere el libre albedrío como afirmación personal de Segismundo -"¿y teniendo yo más vida / tengo menos libertad?"-. Estos dos principios combinados crean una riqueza enorme de sentidos, que en esta edición son desmenuzados críticamente por Ciriaco Morón Arroyo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2424, '19333', 'L''avare', 1, NULL, 87, NULL, 'media/core/19333.jpg', 1, '2023-10-01 07:17:11.561926', '2023-10-01 07:17:11.561926', 1333, 41, 6, 2, 'Classiques Larousse', '', '0204', NULL, 512, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2425, '842971538X', 'Teatre', 1, '1979', 221, NULL, 'media/core/842971538X.jpg', 1, '2023-10-01 07:19:59.567693', '2023-10-01 07:19:59.567693', 1334, 41, 6, 2, NULL, '', '0204', NULL, 2, '', 'Obras:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2426, '9788475224695', 'La importancia de llamarse Ernesto', 3, '2009', 134, NULL, 'media/core/9788475224695.jpeg', 1, '2023-10-01 08:10:29.193346', '2023-10-01 08:10:29.193346', 498, 41, 6, 2, NULL, '', '0204', NULL, 508, 'La importancia de llamarse Ernesto (comedia de enredo, enlazamiento de absurdos, de donde nace el mejor Mihura) es una red compleja de divertimento, disparate y polisemia. Pero, además de lo referido, ahonda en una dualidad: Sin el lado oculto a la sociedad del Bien no hay Vida. La vida perfecta sería la totalidad de Ernesto y Jack juntos. Pero la sociedad burguesa aún la sociedad de hoy, piensese en los Estados Unidos nos exige ser Jack (ser formales, ser como es debido, como la sociedad quiere) pero llamarnos  Ernesto para sobrevivir, ir a una segunda vida (que debiera estar abrazada con la primera) en la que brota nuestro manantial oscuro, la fuerza terrenal del deseo, la transgresión, el eros, el profundo corazón de la materia. Hay que ser Jack dice Wilde, pero sin llamarse Ernesto el lo sabía perfectamente no hay más que represión o supervivencia. En tono de comedia de salón, de alta comedia burguesa la que nace en Inglaterra con Sheridan y su Escuela del escándalo La importancia de llamarse Ernesto es un alegato en pro de la libertad de la vida, en pro del bienestar de la conciencia, en pro de que seamos todos como somos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2427, '9788499304519', 'Quatre peces teatrals', 2, '2013', 332, NULL, 'media/core/9788499304519.jpeg', 1, '2023-10-01 08:14:19.057191', '2023-10-01 08:14:19.057191', 364, 41, 6, 2, 'Labutxaca', '', '0204', NULL, 2, 'La gavina (1896), L''oncle Vània (1897), Tres germanes (1902) i El jardí dels cirerers (1903) són les obres mestres indiscutibles dins la producció dramàtica d''Anton P. Txekhov: quatre peces que van canviar el curs de la tradició teatral russa, europea i nord-americana. Perque Txekhov, per primera vegada, hi va renunciar a desenvolupar una acció dramàtica convencional i es va concentrar en la pintura d''atmosferes, i així va aconseguir que, per sota del text, sense fer-se mai explícita del tot, es reveli sempre el que en podríem dir la vida soterrada: l''autentica vida interior dels personatges, els estats d''ànim d''uns homes i unes dones que, amb mes o menys angoixa i amb mes o menys resignació, assisteixen a l''acompliment del destí que els ha correspost mentre observen la', 'Obres:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2428, '9788437635064', 'Luces de bohemia', 1, '2016', 459, NULL, 'media/core/9788437635064.jpeg', 1, '2023-10-01 08:16:46.145669', '2023-10-01 08:16:46.145669', 1133, 41, 6, 2, 'Letras hispánicas', '', '0204', NULL, 509, 'Situado Valle-Inclán en la encrucijada nacional e internacional tras la Primera Guerra Mundial, observa que por todas partes prevalece lo grotesco.  " La tragedia nuestra no es tragedia " , le dice Max Estrella a Don Latino en  " Luces de bohemia " , lo que da como resultado añade Max Estrella  " el esperpento " , una invención artístico-literaria que es atribuida a Goya. Esa tragedia que no es tragedia es la tragedia del español que vive sin grandeza, sin heroicidades, sin altura de miras, en un momento en el que España se hallaba fuera de las corrientes sociales, políticas, económicas e ideológicas de su entorno europeo:  " España es una deformación grotesca de la civilización europea " . Solo con la forma estetica del esperpento, basada en la deformación sistemática, puede representarse la tragedia no tragedia de España. Pero en  " Luces de bohemia " , el esperpento que en un principio iba a girar en torno a un bohemio, un marginado, se topa con la realidad y su protagonista toma conciencia de ella, dando sentido y proyección estetica y social al esperpento.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2429, '9788437601700', 'Peribáñez y el Comendador de Ocaña', 19, '2003', 199, NULL, 'media/core/9788437601700.jpg', 1, '2023-10-01 08:18:44.990055', '2023-10-01 08:18:44.990055', 767, 41, 7, 2, 'Letras hispánicas', '', '0204', NULL, 509, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2430, '9788437605609', 'Bodas de sangre', 13, '1998', 166, NULL, 'media/core/9788437605609.jpeg', 1, '2023-10-01 08:20:27.367559', '2023-10-01 08:20:27.367559', 766, 41, 6, 2, 'Letras hispánicas', '', '0204', NULL, 509, 'García Lorca convierte la realidad en poesía. En su obra hay ansias de libertad, andalucismo, simbolismo y muerte, pero por encima de todo, poesía dramática.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2431, '9788420671765', 'La casa de Bernarda Alba', 3, '2015', 168, NULL, 'media/core/9788420671765.jpeg', 1, '2023-10-01 08:22:41.666183', '2023-10-01 08:22:41.666183', 766, 41, 6, 2, 'El libro de bolsillo', '', '0204', NULL, 69, 'El asesinato de Federico García Lorca (1898-1936) fijó la imagen de "La casa de Bernarda Alba" como la obra máxima de toda una dramaturgia. Con este drama en el que unos personajes y un espacio se encadenan con suprema maestría a una pasión estéril -el amor no conseguido- cuya liberación sacrificial es la muerte, el poeta granadino llegó, en efecto, a una cumbre similar a la alcanzada por las más grandes creaciones del teatro clásico y contemporáneo. Mario Hernández fija rigurosamente en la presente edición el texto de esta tragedia en la que la tiranía de unas normas sociales opresoras, encarnadas en Bernarda Alba, sofoca de forma implacable el deseo y el ansia de libertad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2432, '9788467033410', 'Tres sombreros de copa', 1, '2014', 147, NULL, 'media/core/9788467033410.jpeg', 1, '2023-10-01 08:25:13.116769', '2023-10-01 08:25:13.116769', 1134, 41, 6, 2, 'Austral', '', '0204', NULL, 265, 'Escrita a comienzos de los años treinta, la comedia TRES SOMBREROS DE COPA, germen de toda la producción teatral de Miguel Mihura, tardó veinte años en ser estrenada y produjo, en el momento de su estreno, escándalo y asombro. Mientras muchos espectadores la calificaban de inmoral, la crítica veía en ella una ruptura con el teatro cómico anterior, un comienzo absoluto que presagiaba el teatro del absurdo. La fuerza dramática de la obra radica en la oposición de dos mundos irreconciliables: el de la burguesía provinciana esclavizada por mil convenciones, y el de un grupo de automarginados de esa sociedad que buscan la libertad y rechazan la moral hipócrita. No hay aquí lucha de clases ni se propugna una alternativa social. Las grandes tensiones se redimen por medio de un humor que rezuma escepticismo.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2435, '9788494837883', 'Las artes y el artesano', 1, '2014', 118, NULL, 'media/core/9788494837883.jpeg', 1, '2023-10-01 09:12:28.326490', '2023-10-01 09:12:28.326490', 498, 2, 6, 2, NULL, '', '0204', NULL, 454, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2436, '9788494510373', 'Cartas a Theo', 1, '2016', 315, NULL, 'media/core/9788494510373.jpeg', 1, '2023-10-01 09:15:59.937245', '2023-10-01 09:16:47.728130', 1336, 53, 6, 2, 'Grandes clásicos', '', '0204', NULL, 360, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2437, '9780241339169', 'The Skeleton''s Holiday', 1, '2018', 48, NULL, 'media/core/9780241339169.jpeg', 1, '2023-10-01 09:19:44.054530', '2023-10-01 09:19:44.054530', 1337, 44, 6, 2, 'Penguin Modern', '', '0204', NULL, 11, 'Leonora Carrington is a British born Surrealist painter and writer now living in Mexico city who has been described, alongside people such as Pablo Picasso and Joan Miro, as one of the leading lights of the Surrealist movement. Born in Lancashire in', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2438, '9788498381498', 'El principito', 1, '2016', 95, 'Le Petit Prince', 'media/core/9788498381498.jpeg', 1, '2023-10-01 10:47:03.544294', '2023-10-01 10:47:03.544294', 961, 1, 6, 2, NULL, '', '0204', NULL, 29, 'Edición oficial en tamaño bolsillo del clásico de la literatura universal, El Principito. Con las preciosas acuarelas del autor,  este clásico de la literatura universal es imprescindible para niños y adultos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2439, '9788498387339', 'El baile', 1, '2016', 94, 'Le Bal', 'media/core/9788498387339.jpeg', 1, '2023-10-01 10:51:10.303497', '2023-10-01 10:51:10.303497', 1338, 27, 6, 2, 'Letras de bolsillo', '', '0204', NULL, 29, 'Instalados en un lujoso piso de París, los Kampf poseen todo lo que el dinero puede comprar, excepto lo más difícil: el reconocimiento de la alta sociedad francesa. Así pues, con el propósito de obtener el codiciado premio, preparan un gran baile para doscientos invitados, un magno acontecimiento social que para el señor y la señora Kampf supondrá, respectivamente, una excelente inversión y la soñada apoteosis mundana. Pero en casa de los Kampf no todos comparten el mismo entusiasmo. Herida en su orgullo por la prohibición materna de asistir al ágape, Antoinette, de catorce años, observa con amargura los agitados preparativos del baile y siente que ha llegado la ocasión de enfrentarse a su madre, afirmarse a sí misma y realizar su propia entrada en la edad adulta. Con un breve gesto, tan impulsivo como espontáneo, provoca una situación absurda que culminará en un final dramático y revelador.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2440, '9788493895044', 'Del Enebro', 6, '2018', 89, 'Van den MAchandel-Boom', 'media/core/9788493895044.JPG', 1, '2023-10-01 10:58:28.188959', '2023-10-01 10:58:28.188959', 1339, 27, 6, 2, NULL, '', '0204', NULL, 513, '- Junto con Wilhelm Karl GrimmINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2441, '9788467271225', 'El festín de Babette', 1, '2006', 109, 'Babettes Gaestebud', 'media/core/9788467271225.jpg', 1, '2023-10-01 11:03:01.916567', '2023-10-01 11:03:01.916567', 1340, 1, 6, 2, NULL, '', '0204', NULL, 514, 'En un aislado pueblo de pescadores en la costa danesa, la comunidad practica los principios religiosos que el pastor ha predicado durante años. Cuando éste muere, sus dos hijas continúan adelante con su obra y su palabra.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2442, '9788467271249', 'Kew Gardens y otros cuentos', 1, '2016', 75, NULL, 'media/core/9788467271249.jpeg', 1, '2023-10-01 11:06:22.279409', '2023-10-01 11:06:22.279409', 807, 44, 6, 2, NULL, '', '0204', NULL, 514, '', 'Cuentos:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2443, '9788467271232', 'Una rubia imponente', 1, '2013', 109, 'Big Blonde', 'media/core/9788467271232.jpg', 1, '2023-10-01 11:11:02.579618', '2023-10-01 11:11:02.579618', 1341, 1, 6, 2, NULL, '', '0204', NULL, 514, '', 'Edición ilustrada');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2444, '9788467271218', 'Los Watson', 1, '2012', 125, 'The Watson', 'media/core/9788467271218.jpeg', 1, '2023-10-01 11:13:00.762355', '2023-10-01 11:13:00.762355', 1267, 1, 6, 2, NULL, '', '0204', NULL, 514, '', 'Edición ilustrada');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2445, '9788420406282', 'La muerte y otras sorpresas', 1, '2010', 150, NULL, 'media/core/9788420406282.jpeg', 1, '2023-10-01 11:15:08.628690', '2023-10-01 11:15:08.628690', 827, 44, 6, 2, NULL, '', '0204', NULL, 10, 'En la ciudad, hombres y mujeres se aman y se odian; mueren, sobreviven,  se deterioran y renacen; sonríen, lloran; se pierden y regresan a traves de caminos muchas veces recorridos, o descubren nuevos senderos iluminados por un radiante sol montevideano.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2446, '9788431625016', 'Relatos fantásticos', 1, '2010', 176, NULL, 'media/core/9788431625016.GIF', 1, '2023-10-01 11:17:17.505002', '2023-10-01 11:17:17.505002', 569, 44, 6, 2, 'Aula de Literatura', '', '0204', NULL, 23, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2447, '9788420525556', 'Antología del cuento literario', 1, '2012', 191, NULL, 'media/core/9788420525556.jpeg', 1, '2023-10-01 11:19:32.767600', '2023-10-01 11:19:32.767600', 572, 44, 6, 2, NULL, '', '0204', NULL, 50, 'La colección Alhambra Literatura añade a las obra más importantes de la Literatura Española de todo los tiempos un estudio preliminar, una bibliografía fundamenteal comentada, una cronología, y un aparato de notas qeu ayudan al lector a la perfecta comprensión del texto.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2448, '9788470903571', 'Escritos de arte de vanguardia 1900/1945', 1, '2009', 509, NULL, 'media/core/9788470903571.jpeg', 1, '2023-10-02 06:41:27.966120', '2023-10-02 06:41:27.966120', 1342, 2, 6, 2, 'Colección Fundamentos', '', '0205', NULL, 196, 'A lo largo de la historia del arte, los períodos de transición se han caracterizado siempre por un notable incremento en la producción teórica de los artistas, cuyos argumentos se convertían así en una de las fuentes más seguras para explicar el porqué de esas crisis, sus orígenes y su proceso de desarrollo. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2449, '9788418796678', 'Sobre belleza', 1, '2023', 474, 'On Beauty', 'media/core/9788418796678.jpeg', 1, '2023-10-02 06:44:31.567586', '2023-10-02 06:44:31.567586', 1343, 1, 6, 2, 'Salamandra bolsillo', '', '0205', NULL, 29, 'Profesor universitario en una pequeña ciudad de Nueva Inglaterra, el británico Howard Belsey está pasando, a sus cincuenta y siete años, por uno de sus momentos más bajos: su futuro academico parece definitivamente estancado y, en su casa, las cosas van de mal en peor. Tras treinta años de convivencia con Kiki, una hermosa activista afroamericana que ahora pesa ciento veinte kilos, un desliz amoroso amenaza con hundir su matrimonio. En cuanto a sus tres hijos, se encuentran absortos en sus propias vidas: el enamoradizo y sesudo Jerome se ha convertido al cristianismo; la ingenua y ambiciosa Zora sigue los dictados de su precoz inteligencia, y el quinceañero Levi es un abanderado de la negritud.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2450, '9788494746703', 'Una flor', 1, '2017', 367, '一本 の 花 (Ippon no hana)', 'media/core/9788494746703.jpeg', 1, '2023-10-02 07:02:48.092869', '2023-10-02 07:02:48.092869', 1344, 44, 6, 2, 'Colección Maestros de la literatura Japonesa', '', '0205', NULL, 28, '"De entre todos los escritores japoneses que alzaron sus voces contra las atrocidades de la guerra y la barbarie de la bomba atómica destaca con letras de oro el nombre de una mujer: Miyamoto Yuriko. Escritora comprometida, Yuriko describió la terrible situación de la clase trabajadora durante el periodo de capitalismo imperialista y militarismo desbocado en los años 30 del pasado siglo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2451, '9788498720778', 'Mujeres que corren con los lobos', 1, '2009', 662, 'Women Who Run Whit The Wolves', 'media/core/9788498720778.jpeg', 1, '2023-10-02 07:07:19.093029', '2023-10-02 07:07:19.093029', 1345, 2, 6, 2, NULL, '', '0205', NULL, 8, '«En toda mujer hay fuerzas poderosas pendientes de descubrir.»Mujeres que corren con los lobos es un fascinante mosaico de historias que nos ofrece una nueva visión de lo femenino y de sus posibilidades.Dentro de toda mujer alienta una vida secreta, una fuerza ponderosa llena de Buenos instintos, creatividad y sabiduría. Es la Mujer Salvaje, una especie en peligro de extinción debido a los contantes esfuerzos de la sociedad por «civilizar» a las mujeres y constreñirlas a rígidos papeles que anulan su esencia instintiva.En este libro, Clarissa Pinkola Estés revela ricos mitos interculturales, cuentos de hadas e historias (muchas de ellas relativas a su propia familia) para contribuir a que las mujeres recuperen su fuerza y su salud, atributos visionarios de esta esencia instintiva.Mediante los relatos y los comentarios de la autora, examinamos el amor y comprendemos a la Mujer Salvaje. Estés ha creado una psicología femenina en un sentido más verdadero, el que lleva al conocimiento del alma', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2452, '9788411071116', 'La Policía de la Memoria', 2, '2022', 390, '密やか な 血書 (Hisoyaka na kessho)', 'media/core/9788411071116.jpeg', 1, '2023-10-02 07:10:29.057810', '2023-10-02 07:10:29.057810', 1346, 1, 6, 2, 'Maxi Turquets', '', '0205', NULL, 12, 'En una pequeña isla se produce un misterioso fenómeno. Un día desaparecen los pájaros, al siguiente podría desaparecer cualquier cosa: los peces, los árboles... Peor aún, también se desvanecerá su memoria, al igual que las emociones y sensaciones asociadas a ellos. Nadie sabrá ni recordará entonces qué eran. Hay incluso una policía dedicada a perseguir a los que conservan la capacidad de recordar lo que ya no existe. En esa isla vive una joven escritora que, tras la muerte de su madre, intenta escribir una novela mientras trata de ayudar a su editor, que está en peligro porque forma parte de los pocos que recuerdan.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2453, '9788411482318', 'Mater 2-10', 1, '2023', 598, NULL, 'media/core/9788411482318.jpeg', 1, '2023-10-02 07:20:01.391849', '2023-10-02 07:20:01.391849', 1295, 1, 6, 2, NULL, '', '0205', NULL, 69, '"De algún modo no sentía el vacío bajo sus pies. Cuando hacía deporte caminando una y otra vez por la zona de la barandilla, sentía el impulso de caminar sobre el aire. Jinoh metió el cuerpo entre los barrotes, inclinándose, y extendió una pierna. Parecía que estaba pisando un mullido colchón o edredón. Sujeto con ambas manos a la barandilla, sacó los dos pies por fuera."INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2454, '9780143107453', 'Dubliners', 1, '2014', 205, NULL, 'media/core/9780143107453.jpeg', 1, '2023-10-02 07:22:36.689157', '2023-10-02 07:22:36.689157', 105, 1, 6, 2, 'Penguin Classics', '', '0205', NULL, 11, 'Perhaps the greatest short story collection in the English language, James Joyce''s Dubliners is both a vivid and unflinching portrait of "dear dirty Dublin" at the turn of the twentieth century and a moral history of a nation and a people whose "golden age" has passed. His richly drawn characters-at once intensely Irish and utterly universal-may forever haunt the reader. In mesmerizing writing rich with evocative imagery, Joyce delves into the heart of the city of his birth, capturing the cadences of Dubliners'' speech and portraying with remarkable realism their outer and inner lives. This magnificent collection of fifteen stories, including such touchstones as "Araby," "Grace," and "The Dead," and in the definitive text authorized by the Joyce estate-collated from all known proofs, manuscripts, and impressions of Dubliners to reflect the author''s wishes-reveals Joyce at his most accessible and most profound.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2455, '9780008365943', 'How to kill your family', 1, '2021', 354, NULL, 'media/core/9780008365943.jpeg', 1, '2023-10-02 07:25:17.066092', '2023-10-02 07:25:17.066092', 1347, 1, 6, 2, NULL, '', '0205', NULL, 400, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2456, '9788419362032', 'Estrella fugaz', 1, '2022', 301, 'Every Falling Star', 'media/core/9788419362032.jpeg', 1, '2023-10-02 07:29:29.760676', '2023-10-02 07:29:29.760676', 1348, 1, 6, 2, NULL, '', '0205', NULL, 515, 'Yasuda ha empezado a trabajar como representante en la oficina de un amigo suyo, Tateishi, a quien admira mucho. Sin embargo, el primer equipo que requiere de sus servicios, pre­sidido por Barisic, ha bajado de repente a segunda. ¿Qué otras sorpresas aguardan en la vida de este agente?', 'Con Susan McClelland');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2458, '9788492649778', 'El gran asombro. La curiosidad como estímulo en la historia de la filosofía', 1, '2010', 415, 'L''étonnement philosophique', 'media/core/9788492649778.jpeg', 1, '2023-10-02 07:38:18.282341', '2023-10-02 07:38:18.282341', 1349, 2, 6, 2, NULL, '', '0202', NULL, 455, 'La filosofía comienza con el asombro, afirma Aristóteles al principio de su "Metafisica". La originalidad de esta historia de la filosofía radica en la nueva ordenación que propone, al estudiar el desarrollo de la filosofía en Occidente, más que a partir de sus tesis principales, desde la naturaleza', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2459, '9788446039556', 'Epistemologías del Sur (perspectivas)', 1, '2014', 1, 'Epistemologias do Soul', 'media/core/9788446039556.jpeg', 1, '2023-10-02 07:41:27.452107', '2023-10-02 07:41:27.452107', 1350, 2, 6, 2, NULL, '', '0205', NULL, 196, '¿Por qué razón, en los últimos dos siglos, la epistemología occidental dominante eliminó de la reflexión el contexto cultural y político de producción y reproducción del conocimiento? ¿Cómo se redefinirían los debates globales actuales sobre democracia, crisis ecológica, derechos humanos, liberación de la mujer, economía, etc., si partimos de un diálogo entre iguales basado en la diversidad epistemológica del mundo? Un libro muy necesario en un mundo al que le cuesta renunciar a su tradicional occidenta-lo-centrismo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2460, '9788420691220', 'Ética. Doce textos fundamentales del siglo XX', 2, '2014', 369, NULL, 'media/core/9788420691220.jpeg', 1, '2023-10-02 07:44:56.918207', '2023-10-02 07:44:56.918207', 1351, 2, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 69, 'Los problemas de la Filosofía Moral contemporánea son presentados en este volumen a través de "Doce textos fundamentales de la ética del siglo xx", encuadrados en sus principales tendencias: la filosofía analítica (G. E. Moore, L. Wittgenstein), la corriente fenomenológico-existencialista (M. Scheler, J.-P. Sartre), los marxismos (E. Bloch, J. Habermas), la polémica entre liberales y comunitaristas (J. Rawls, Ch. Taylor), las aportaciones de la hermenéutica y la postmodernidad (P. Ricoeur, M. Foucault), y las llevadas a cabo en lengua española (J. L. L. Aranguren, J. Muguerza). Traducidos algunos de ellos por primera vez al castellano y ofrecidos en muchos casos en su integridad, estos textos -contextualizados y analizados en el estudio preliminar de Carlos Gómez- recogen los planteamientos básicos de sus autores, haciendo de esta recopilación un excelente instrumento y una introducción inmejorable para conocer los temas cardinales de la reflexión ética de nuestro tiempo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2461, '9788420678818', 'La República', 3, '2018', 680, NULL, 'media/core/9788420678818.jpeg', 1, '2023-10-02 07:47:25.161300', '2023-10-02 07:47:25.161300', 1101, 2, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 69, 'En el período que transcurrió desde su infancia hasta su muerte, Platón (ca. 428-ca. 347 a.C.) conoció la decadencia de la grandeza ateniense, jalonada por numerosos y señalados episodios históricos que, junto con su reiterado fracaso político en Siracusa, influyeron poderosamente tanto en su actividad política como en su trabajo intelectual. "La república" presenta el modelo de ciudad donde la justicia prevalece frente al desorden, la confusión y la perversión; sin embargo, como señala Manuel Fernández-Galiano en la introducción al volumen, el diálogo no apunta a la construcción ideal de una sociedad perfecta de hombres perfectos, sino que es un "tratado de medicina política" con aplicación a los regímenes existentes en su tiempo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2462, '9788420674636', 'El banquete', 3, '2019', 1, NULL, 'media/core/9788420674636.jpeg', 1, '2023-10-02 07:49:29.913014', '2023-10-02 07:49:29.913014', 1101, 2, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 69, 'La extensa y variada obra de Platón (h. 428-h. 347 a.C.) ofrece en "El banquete" un estilo y una configuración peculiares, condicionados por la elección del escenario (una conversación después de una comida) y la naturaleza del tema tratado (el amor, esencial y recurrente a lo largo de la obra platónica). Como señala Carlos García Gual, en este diálogo Platón despliega con habilidad literaria y versátil retórica un abanico de perspectivas que permite al lector advertir la complejidad de los enfoques posibles, para luego establecer, a través de la iluminada revelación de Diotima, su propia teoría, según la cual el impulso erótico se sublima en una escala dialéctica hacia esa idea de Belleza que es también el Bien.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2463, '9788408176053', 'Confesiones', 1, '1993', 385, NULL, 'media/core/9788408176053.jpeg', 1, '2023-10-02 07:52:48.343450', '2023-10-02 07:52:48.343450', 1353, 2, 6, 2, 'Austral', '', '0205', NULL, 7, 'No debemos olvidar que es uno de los pocos «Padres de la Iglesia» que han entrado por derecho propio en la literatura universal y en la historia de la filosofía. La oración de Agustín a partir de su vida consiste en abrir no sólo sus propios problemas delante de la divinidad, sino en pensar ante Dios con el vivo deseo de recibir su luz, a fin de que éste penetre en los problemas intelectuales que más le afectan: qué es el tiempo; qué es el mal; qué es la mente humana; qué es la memoria; qué es el amor y la muerte.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2464, '9788436941722', 'De la urbanidad en las maneras de los niños (De civilitate morum puerilium)', 2, '2006', 112, 'De civilitate morum puerilium', 'media/core/9788436941722.jpg', 1, '2023-10-02 07:56:06.202125', '2023-10-02 07:56:06.202125', 1354, 2, 6, 2, NULL, '', '0205', NULL, 516, 'Publicado por Erasmo de Rotterdam en 1530, representa el primer intento de  tratamiento sistemático de las buenas maneras aplicadas, en este caso concreto,  a la educación de los niños.', 'Edición bilingüe: Castellano - Latín');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2465, '9786071614704', 'Leviatán. O la materia, forma y popder de una república ecelsiástica y civil', 2, '2014', 587, 'Leviathan or the Matter, Form and Power of a Commonwealth Eclesiastical and C', 'media/core/9786071614704.jpeg', 1, '2023-10-02 09:05:08.670518', '2023-10-02 09:05:08.670518', 1355, 2, 6, 2, 'Sección de Obraas de Política y Derecho', '', '0205', NULL, 517, 'Leviatán es una de las obras maestras de la filosofía política. La primera edición inglesa, apare-cida en 1651, habría de dar renombre universal a su autor, cuyas doctrinas se han resumido di-ciendo que predica el utilitarismo en moral y el despotismo en política. El Leviatán -nombre to-mado de la Biblia para designar a la República o Estado- es un monstruo de traza bíblica, inte-grado por seres humanos, dotado de una vida cuyo origen brota de la razón humana, pero que bajo la presión de las circunstancias y necesidades decae, por obra de las pasiones, en la gue-rra civil y en la desintegración, que es la muerte. Constituye el libro una penetrante crítica de la Iglesia y de su política: para acabar con el reino de las tinieblas y de la superstición, el nuevo Estado inglés debería excluir con firmeza todos los defectos orgánicos del antiguo, y ser neta-mente racionalista y laico, un verdadero reino de la luz y de la ciencia. Aparte de su alcance en la evolución científica, la importancia de', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2466, '9788430601011', 'La mano invisible', 1, '2012', 139, 'The Invisible Hand', 'media/core/9788430601011.jpeg', 1, '2023-10-02 09:07:33.455644', '2023-10-02 09:07:33.455644', 469, 2, 6, 2, 'Great Ideas', '', '0205', NULL, 323, 'El decisivo tratado de Adam Smith sobre el mercado libre allanó el camino al capitalismo moderno argumentando que la competencia es el motor de una sociedad productiva y que el interés propio en última instancia logrará enriquecer a toda la comunidad, como si de una"mano invisible"se tratara.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2467, '842970874X', 'Ensayos sobre la igualdad sexual', 1, '1973', 288, 'Essays on sex equality', 'media/core/842970874X.jpg', 1, '2023-10-02 09:15:45.578926', '2023-10-02 09:15:45.578926', 1356, 2, 6, 2, 'Edciones de bolsillo', '', '0205', NULL, 192, '«Han pasado cien años desde la publicación de “El sometimiento de la mujer” y, sin embargo, este ensayo sigue siendo casi único como análisis intelectual de la situación de la mujer, y como llamada a una acción política para lograr la igualdad entre los sexos. Nada que se le pueda comparar había sido publicado antes de 1869, y nada iba a aparecer hasta la publicación en 1898 de “Women and Economics”, de Charlotte Perkins Gilman, y, cincuenta años más tarde, en 1949, “Le deuxième sexe”, de Simone de Beauvoir. Estos tres volúmenes constituyen hitos, tanto en la larga historia del movimiento de la mujer a favor de sus derechos políticos y económicos, como en la historia más corta de los análisis intelectuales de los papeles del sexo y de las relaciones entre los sexos.& Los tres comparten esa rara cualidad del análisis intelectual riguroso combinado con la entrega apasionada a la causa de la igualdad sexual. “El sometimiento de la mujer” tiene un interés muy especial como primero y único de los tres escritos por un hombre [...] Para las generaciones del siglo XX que han visto la tiranía y la supresión de la libertad humana bajo toda clase de gobiernos: fascistas, comunistas y democráticos, la invocación que hace John Stuart Mill de los derechos de los hombres y mujeres a la libertad y a la justicia tiene un fuerte y persistente poder de atracción. Y para las mujeres del siglo XX, que han visto muy poca diferencia en la condición actual, si no en los derechos legales, de la mujer bajo cualquiera de las formas existentes de gobierno, “El sometimiento de la mujer” continúa sirviendo de afirmación repetida de su derecho humano a una plena igualdad, y de análisis agudo de los obstáculos que les impiden el camino hacia este derecho.» (Alice B. Rossi, de la «Introducción»)', 'Con Harriet Taylor MillINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2468, '9788420674568', 'El concepto de la angustia', 2, '2013', 313, 'Begrebet Angest', 'media/core/9788420674568.jpeg', 1, '2023-10-02 09:18:16.262421', '2023-10-02 09:18:16.262421', 1357, 2, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 69, 'Publicado por primera vez en 1844, "El concepto de la angustia" es quizá el libro más conocido del danés Sören Kierkegaard (1813-1855), y en él se articulan algunos de los conceptos en los que se apoya el existencialismo cristiano. La angustia se relaciona con el pecado y con la libertad. Engendrada por la nada, alimentada por la impaciencia, surgida como "realidad de la libertad en cuanto posibilidad", la angustia es "el vértigo de la libertad" y al mismo tiempo un medio de salvación que conduce a la fe, a la verdad que años antes de escribir este libro el autor, en su diario íntimo, confesaba buscar como sentido definitivo de su existencia: "Es preciso encontrar una verdad, y la verdad es para mí hallar la idea por la que esté dispuesto a vivir y morir". Del mismo autor, en esta colección: "Temor y Temblor", "Diario de un seductor", "In vino veritas" y "La repetición".INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2469, '9788415089360', 'Así hablaba Zaratustra', 5, '2016', 320, NULL, 'media/core/9788415089360.jpeg', 1, '2023-10-02 09:21:24.664518', '2023-10-02 09:21:24.664518', 491, 2, 6, 2, 'Colección Eterna', '', '0205', NULL, 360, 'Es una de esas obras universales, tan escasas en número, que han trascendido disciplinas, géneros, fronteras e idiomas, y que han llegado a formar parte de eso que se llama confusamente cultura general. Su profunda influencia en el ámbito cultural europeo, indica que una investigación de su impacto en las distintas naciones de nuestro continente, tiene que convertirse necesariamente en una historia de la cultura europea del siglo XX. Con esta obra Nietzsche abandonó el proyecto de una Nueva Ilustración y apostó por una superación del nihilismo con la ayuda de tres conceptos fundamentales: la voluntad de poder, el superhombre y el eterno retorno. Para expresar esta superación Nietzsche experimentó con una nueva forma que consistía en una dramatización de de la filosofía.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2470, '9788415217831', 'Un paseo invernal', 2, '2015', 117, 'A Winter Walk', 'media/core/9788415217831.jpg', 1, '2023-10-02 09:26:20.326784', '2023-10-02 09:26:20.326784', 1358, 2, 6, 2, NULL, '', '0205', NULL, 497, 'Reunimos en este libro dos de los textos más bellos y menos conocidos del autor de Walden: «Un paseo invernal» relata una caminata inolvidable por el corazón de los Grandes Fríos hacia la primavera de la existencia; «Caminar» es un ensayo magistral sobre el arte del paseo y una defensa cerrada de la vida salvaje y libre, tanto de los animales como de los seres humanos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2471, '9788415217459', 'Walden', 10, '2017', 360, NULL, 'media/core/9788415217459.jpeg', 1, '2023-10-02 09:28:24.448110', '2023-10-02 09:28:24.448110', 1358, 2, 6, 2, 'Colección la muchacha de dos cabezas', '', '0205', NULL, 497, 'En 1845 Thoreau abandona la casa familiar de Concord y se instala en la cabaña que ha construido junto a la laguna de Walden. Pero no se marcha a los bosques para «jugar a la vida», sino para «vivirla intensamente de principio a fin». A partir de esa experiencia escribe uno de los clásicos fundamentales del ensayo moderno. Walden es tanto un experimento literario sin precedentes como un manual para la buena vida: un libro escrito contra toda servidumbre y a favor de la felicidad como única riqueza del ser humano. Walden es una defensa de la vida libre y salvaje, así como una crítica feroz de la sociedad y sus imposiciones, que apenas han variado desde aquella fecha. Walden es un cuestionamiento radical y directo de la institución del trabajo como adocenamiento y del mercado como único dios, así como una lúcida defensa de la simplificación de la vida y del camino que nos lleva a perseguir su esencia y sus placeres cotidianos. Walden es una reflexión sobre la necesidad de preservar tanto la naturaleza y el planeta como el meollo de nuestra propia existencia individual e irreductible. Walden habla de lagunas salvajes y hombres sabios, alces y shakespeares, esclavos huidos y trabajadores sonámbulos, las montañas de Nueva Inglaterra y el Bhagavad Gita, la belleza del fuego hogareño y la Gran Nevada, el silbido devastador del ferrocarril y el recóndito ulular del búho, la erudición de los indios Massasoit y la banalidad de los eruditos de Harvard, la belleza absoluta de la soledad y la importancia inconmensurable de la amistad, el bienestar que exhiben las marmotas y el malestar que aqueja a la mayoría de los seres humanos. Según el propio Thoreau, «Walden es un libro escrito para esa mayoría de hombres que está descontenta con su vida y con los tiempos que le ha tocado vivir, pero que podría mejorarlos. Y también para aquéllos en apariencia ricos, pero que en realidad han acumulado cosas inútiles y no saben muy bien qué hacer con ellas».', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2472, '9788446050759', 'Del Socialismo utópico al Socialismo científico', 1, '2021', 112, 'Socialisme utopiqueet socialisme scientifique', 'media/core/9788446050759.jpeg', 1, '2023-10-02 09:31:08.277137', '2023-10-02 09:31:08.277137', 1028, 2, 6, 2, 'Básica de bolsillo', '', '0205', NULL, 196, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2473, '9788446040903', 'Calle de sentido único', 1, '2018', 96, 'Einbahnstrasse', 'media/core/9788446040903.jpeg', 1, '2023-10-02 09:33:47.883081', '2023-10-02 09:33:47.883081', 1310, 2, 6, 2, 'Básica de bolsillo', '', '0205', NULL, 196, 'La prosa breve de Walter Benjamin hace mucho tiempo que forma parte del canon de los clásicos modernos. Ya se trate de un sello, de una alfombra persa o de un tiovivo, incluso los fenómenos más insignificantes pueden ser objeto de la famosa imaginación intelectual de Benjamin, en busca de una comprensión más profunda del siglo xx. En cada fragmento se perciben las amenazas y catástrofes de la épocaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2474, '9788446037934', 'Antología', 1, '2018', 457, NULL, 'media/core/9788446037934.jpg', 1, '2023-10-02 09:36:28.760904', '2023-10-02 09:36:28.760904', 1359, 2, 6, 2, 'Cuestiones de antagonismo', '', '0205', NULL, 196, '', 'Selección de Manuel Sacristán');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2475, '9788475066868', 'El manifiesto comunista', 1, '2005', 228, NULL, 'media/core/9788475066868.jpeg', 1, '2023-10-02 09:40:55.126641', '2023-10-02 09:40:55.126641', 843, 2, 6, 2, NULL, '', '0205', NULL, 494, 'Publicado por primera vez en Londres en 1848 como programa de la clandestina Liga de los Comunistas, primera organización comunista internacional, El Manifiesto Comunista se convirtió en escasos meses, en bandera teórica del movimiento proletario. Siglo y medio después el que fuera, el panfleto más genial que cualquier otro de la literatura mundial, se ha convertido en un clásico de las ciencias sociales y las humanidades y en', 'Edición comentadaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2476, '9788420673660', 'El Estado y la revolución', 2, '2018', 198, 'Gosudarstvo i revoliutsiya', 'media/core/9788420673660.jpeg', 1, '2023-10-02 09:45:30.979637', '2023-10-02 09:45:30.979637', 466, 2, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 119, 'El Estado y la revolución. La doctrina marxista del Estado y las tareas del proletariado en la revolución fue escrito por Lenin en la clandestinidad, entre agosto y septiembre de 1917, cuando se ocultó de las persecuciones del Gobierno Provisional tras las Jornadas de Julio.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2477, '9788416285303', 'Reforma o revolución', 2, '2018', 130, NULL, 'media/core/9788416285303.GIF', 1, '2023-10-02 09:48:36.202861', '2023-10-02 09:48:36.202861', 1360, 2, 6, 2, 'Colección clásicos del Marxismo', '', '0205', NULL, 518, 'Reforma o Revolución es la primera gran obra política de Rosa Luxemburgo, la que le proporcionaría el reconocimiento político en el Partido Social Demócrata Alemán, y obligaría a los veteranos a considerarla una verdadera dirigente política. De 1897 a 1898 Eduard Bernstein publicó una serie de artículos en Neue Zeit en los que trató de refutar las premisas básicas del socialismo científico, a los que Rosa Luxemburgo contestó con dos artículos que se reunirían después con el título Reforma o Revolución. Como  Bernstein defendiera el abandono del objetivo final de la socialdemocracia, esto es, la revolución social, Rosa Luxemburgo plantea que el dilema resultante, «reforma o revolución», es realmente para la socialdemocracia el de «ser o no ser». Así, la discusión que plantea Rosa Luxemburgo acerca de la postura de Bernstein y sus partidarios no se centra tanto en la manera de luchar, en cuál es la táctica, sino en el futuro de toda la vida del movimiento socialdemócrata.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2478, '9788496004627', 'Autobiografía de una mujer emancipada y otros textos sobre el amor', 1, '2015', 200, NULL, 'media/core/9788496004627.jpeg', 1, '2023-10-02 09:53:04.772383', '2023-10-02 09:53:04.772383', 1361, 2, 6, 2, 'Colección la cosecha de nuestras madres', '', '0205', NULL, 519, 'Alejandra Kolontai es, seguramente, la más completa e interesante de las pensadoras socialistas. Por eso sus obras nunca dejan de hablarnos. La valentía, nobleza y autenticidad que revelan sus escritos nos ayudan a comprender por qué, a pesar de los cambios radicales en la vida sexual de las mujeres, algo sigue permaneciendo más o menos inalterable en los problemas con el amor.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2479, '9788487198809', 'El harén político. El Profeta y las mujeres', 2, '2002', 262, 'Le harem politique. Le Prophète et les femmes', 'media/core/9788487198809.jpg', 1, '2023-10-02 09:56:36.334415', '2023-10-02 09:56:36.334415', 1362, NULL, 6, NULL, NULL, '', NULL, NULL, 520, 'Ameno y riguroso estudio de los orígenes de la misoginia imperante en determinados medios islámicos, en el que la autora muestra la manipulación de las palabras del Profeta por sus interesados exégetas.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2480, '9788446020936', 'Mujeres, raza y clase', 3, '2019', 240, 'Women, Race & Class', 'media/core/9788446020936.jpeg', 1, '2023-10-02 16:09:56.879782', '2023-10-02 16:09:56.879782', 1363, 2, 6, 2, 'Cuestiones de antagonismo', '', '0205', NULL, 196, 'Análisis riguroso y esclarecedor que pone de manifiesto las estrategias de lucha de las mujeres negras y los problemas de composición de las diferencias que siguen desgarrando los movimientos políticos actuales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2481, '9788437626833', 'Mecanismos psíquicos del poder', 4, '2014', 216, 'The Psychic Life of Power. Theories in Subjection', 'media/core/9788437626833.JPG', 1, '2023-10-02 16:14:27.957597', '2023-10-02 16:14:27.957597', 1364, 2, 6, 2, NULL, '', '0205', NULL, 509, 'Como forma de poder, el sometimiento es paradójico. Una de las formas familiares y agónicas en que se manifiesta el poder consiste en ser dominado/a por un poder externo a uno/a. Pero si, siguiendo a Foucault, entendemos el poder como algo que también forma al sujeto, que le proporciona la misma condición de su existencia y la trayectoria de su deseo, entonces el poder no es solamente algo a lo que nos oponemos, sino también, de manera muy marcada, algo de lo que dependemos para nuestra existencia y que abrigamos y preservamos en los seres que somos. La teoría foucaultiana otorga poco protagonismo al ámbito de la psique y no explora el poder en esta doble valencia de subordinación y producción. Si la sumisión es una condición de la sujeción, resulta pertinente preguntar: ¿cuál es la forma psíquica que adopta el poder? Judith Butler acomete el proyecto de elaborar una teoría de la psique para acompañar a la teoría del poder, tarea que los autores adscritos tanto a la ortodoxia foucaultiana como a la psicoanalítica han eludido.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2482, '9788496453517', 'Calibán y la bruja. Mujeres, cuerpo y acumulación originaria', 9, '2018', 368, 'Caliban and the Witch. Women, The Body and Primitive Accumulation', 'media/core/9788496453517.jpeg', 1, '2023-10-02 16:18:26.928386', '2023-10-02 16:18:26.928386', 1365, 2, 6, 2, NULL, '', '0205', NULL, 521, 'De la emancipación de la servidumbre a las herejías subversivas, un hilo rojo recorre la historia de la transición del feudalismo al capitalismo. Todavía hoy expurgado de la gran mayoría de los manuales de historia, la imposición de los poderes del Estado y el nacimiento de esa formación social que acabarí por tomar el nombre de capitalimo no se produjeron sin el recurso a la violencia extrema. La acumulación originaria exigióla derrota de los movimientos urbanos y campesinos, que normalmente bajo la forma de herejía religiosa reivindicaron y pusieron en práctica diversos experimentos de vida comunal y reparto de riqueza. Su aniquilación abrió el camino a la formación del Estado moderno, la expropiación y cercado de las tierras comunes, la conquista y el expolio de América, la apertura del comercio de esclavos a gran escala y una guerra contra las formas de vida y las culturas populares que tomó a las mujeres como su principal objetivo. Al analizar la quema de brujas, Federici no sólo desentraña uno de los episodios más inefables de la historia moderna, sino el corazón de una poderosa dinámica de expropiación social dirigida sobre el cuerpo, los saberes y la reproducción de las mujeres. Esta obra es también el registro de unas voces imprevistas (las de los subalternos: Calibán y la bruja) que todavía hoy resuenan con fuerza en las luchas que resisten', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2483, '9788437622330', 'El segundo sexo', 4, '2013', 912, 'Le deuxième sexe', 'media/core/9788437622330.jpeg', 1, '2023-10-02 16:20:50.107975', '2023-10-02 16:20:50.107975', 1366, 2, 6, 2, NULL, '', '0205', NULL, 509, '«El segundo sexo» no sólo ha nutrido a todo el feminismo que se ha hecho en la segunda mitad del siglo, sino que es el ensayo feminista más importante de la centuria. Todo lo que se ha escrito después en el campo de la teoría feminista ha tenido que contar con esta obra, bien para continuarla en sus planteamientos y seguir desarrollándolos, bien para criticarlos oponiéndose a ellos. «El segundo sexo», que es el ensayo de una filósofa existencialista, se encuadra en el ámbito más amplio de un pensamiento ilustrado que toma de la ilustración precisamente sus aspectos positivos, emancipatorios; ante todo, una concepción igualitaria de los seres humanos, según la cual la diferencia de sexos no altera su radical igualdad de condición. Al mismo tiempo, es un ensayo filosófico que analiza el hecho de la condición femenina en las sociedades occidentales desde múltiples puntos de vista: el científico, el histórico, el psicológico, el sociológico, el ontológico y el cultural. Se trata de un', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2484, '9782070343836', 'La Femme indépendante', 1, '2008', 116, NULL, 'media/core/9782070343836.jpeg', 1, '2023-10-02 16:23:33.776600', '2023-10-02 16:23:33.776600', 1366, 2, 6, 2, NULL, '', '0205', NULL, 293, '" La femme a toujours été, sinon l''esclave de l''homme, du moins sa vassale ; les deux sexes ne se sont jamais partagé le monde à égalité ; et aujourd''hui encore, bien que sa condition soit en train d''évoluer, la femme est lourdement handicapée. En presque aucun pays son statut légal n''est identique à celui de l''homme et souvent il la désavantage considérablement. " Agrégée de philosophie, unie à Jean-Paul Sartre par un long compagnonnage affectif et intellectuel, Simone de Beauvoir (1908-1986) publie son premier roman, L''Invitée, à l''âge de trente-cinq ans. Paru en 1949, Le Deuxième Sexe, dont on trouvera ici quelques pages marquantes, fit d''elle l''une des grandes figures du féminisme du XXe siècle et lui assura une renommée internationale qui marqua durablement sa carrière d''écrivain.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2485, '9782070361373', 'Une mort très douce', 1, '1964', 151, NULL, 'media/core/9782070361373.jpg', 1, '2023-10-02 16:27:47.740539', '2023-10-02 16:27:47.740539', 1366, 31, 6, 2, 'Collection folio', '', '0205', NULL, 293, 'la journée du mardi se passa bien. la nuit, maman fit des cauchemars. " on me met dans une boîte ", disait-elle à la soeur. " je suis là, mais je suis dans la boîte. je suis moi et ce n''est plus moi. des hommes emportent la boîte ! " elle se débattait : " ne les laisse pas m''emporter ! " longtemps poupette a gardé la main posée sur son front : " je te promets. il ne te mettront pas dans la boîte. " elle a réclamé un supplément d''equanil. sauvée enfin de ses visions, maman l''a interrogée : " mais qu''est-ce que ça veut dire, cette boîte, ces hommes ? - ce sont des souvenirs de ton opération ; des infirmiers t''emportent sur un brancard. " maman s''est endormie. " peut-être simone de beauvoir a-t-elle donné d''elle-même, dans ces cent soixante petites pages, sinon le meilleur d''elle-même, au moins le plus secret. " (pierre-henri simon, de l''académie française, le monde.) " simone de beauvoir, dont nous connaissons la sincérité et le courage, nous révèle une', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2486, '9788434423992', 'En el café de los existencialistas. Sexo, café y cigarrillos o cuando filosofar era provocador', 1, '2019', 528, 'At the existencialist café. Freedom, Being and Apricot Cocktails', 'media/core/9788434423992.jpeg', 1, '2023-10-02 16:32:04.747404', '2023-10-02 16:32:04.747404', 1367, 15, 6, 2, NULL, '', '0205', NULL, 144, 'París, 1933: tres amigos están reunidos tomando cócteles de albaricoque en el bar Bec-de-Gaz, en la calle Montparnasse. Son tres jóvenes, Jean-Paul-Sartre, Simone de Beauvoir y Raymond Aron, compañero filósofo que les tienta con un nuevo marco conceptual aparecido en Berlín, la «fenomenología». «¿Sabéis?—les dice—¡si eres fenomenólogo, puedes hablar de este cóctel y hacer filosofía con él!»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2487, '9782070360024', 'L''étranger', 1, '1942', 184, NULL, 'media/core/9782070360024.jpeg', 1, '2023-10-02 16:34:25.818683', '2023-10-02 16:34:25.818683', 842, 1, 6, 2, 'Collection folio', '', '0205', NULL, 293, '« Quand la sonnerie a encore retenti, que la porte du box s''est ouverte, c''est le silence de la salle qui est monté vers moi, le silence, et cette singulière sensation que j''ai eue lorsque j''ai constaté que le jeune journaliste avait détourné les yeux. Je n''ai pas regardé du côté de Marie. Je n''en ai pas eu le temps parce que le président m''a dit dans une forme bizarre que j''aurais la tête tranchée sur une place publique au nom du peuple français... »', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2488, '9781539012887', 'El mito de Sísifo', 1, '2016', 68, NULL, 'media/core/9781539012887.jpeg', 1, '2023-10-02 16:43:43.006270', '2023-10-02 16:43:43.006270', 842, 2, 6, 2, NULL, '', '0205', NULL, 522, 'El mito de Sísifo es el ensayo fundacional de la  filosofía del absurdo, una obra mayúscula que dio a conocer el gran talento de Albert Camus. Publicada en 1942, el mismo año que El  extranjero, fue una de las primeras obras que revelaron al público la inteligencia y la sensibilidad del autor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2489, '9781784870416', 'Yhe Beauty Myth', 1, '2015', 109, NULL, 'media/core/9781784870416.jpeg', 1, '2023-10-02 16:47:00.575346', '2023-10-02 16:47:00.575346', 1368, 2, 6, 2, 'Vintage Classics', '', '0205', NULL, 463, 'En este libro, Naomi Wolf plantea la existencia de una relación perversa entre la liberación femenina, el avance de las mujeres y la exigencia de ideales de belleza cada vez más imposibles. También indica que, si bien este sector ha ganado muchos espacios, el mito de la belleza funciona en la actualidad como un dispositivo para mantener a las mujeres en el sitio subordinado que habían ocupado durante siglos. El peligro más grande del mito, según Wolf, radica en que daña su parte más sensible: la autoestima, por lo que las convierte en personas débiles e inseguras ya que las mujeres occidentales viven bajo la presión constante de ajustarse a un concepto idealizado de belleza creado por la sociedad moderna.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2490, '9788490628720', 'Ensayo sobre la ceguera', 1, '2017', 375, 'Ensaio sobre a Cegueira', 'media/core/9788490628720.jpg', 1, '2023-10-02 16:50:28.378582', '2023-10-02 16:50:28.378582', 1369, 1, 6, 2, 'Contemporánea', '', '0205', NULL, 204, '«Dentro de nosotros hay algo que notiene nombre, esa cosa es lo que somos».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2491, '9788434413672', 'Breve historia y antología de la Estética', 1, '2017', 304, NULL, 'media/core/9788434413672.jpeg', 1, '2023-10-02 16:52:43.452113', '2023-10-02 16:52:43.452113', 1370, 2, 6, 2, 'Ariel Filosofía', '', '0205', NULL, 144, 'Nueva edición de la principal introducción a la estética de las letras españolas. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2492, '9788425448126', 'La sociedad del cansancio', 3, '2022', 120, 'Die Müdigkeitsgesellschaft', 'media/core/9788425448126.jpeg', 1, '2023-10-02 16:55:34.524439', '2023-10-02 16:55:34.524439', 1371, 2, 6, 2, NULL, '', '0205', NULL, 382, 'La tercera edición del indiscutible best seller de Byung-Chul Han, una de las voces filosóficas más innovadoras de los últimosINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2493, '9788425437588', 'La salvación de lo bello', 1, '2015', 112, 'Die Errettungdes Schönen', 'media/core/9788425437588.jpeg', 1, '2023-10-02 17:02:56.236315', '2023-10-02 17:02:56.236315', 1371, 2, 6, 2, 'Pensamiento Herder', '', '0205', NULL, 382, 'Lo pulido, lo liso, lo impecable, son la seña de identidad de nuestra época. Son lo que tienen en común las esculturas de Jeff Koons, los smartphones y la depilación. Estas cualidades ponen en evidencia el actual "exceso de positividad" del que habla Han en otros ensayos, pero que aquí enfoca y desarrolla en el campo del arte y de la estética. Lo bello natural se ha atrofiado en lo liso y pulido de lo bello digital. Hoy nos hallamos en una crisis de lo bello en tanto que se lo satina, convirtiéndolo en objeto del «me gusta», en algo arbitrario y placentero, que se mide por su inmediatez y su valor de uso y de consumo. Pero sin la negatividad del quiebre de lo otro, queda obturado el acceso a lo bello natural y anulada la distancia contemplativa. La belleza es rezagada. No es un brillo momentáneo, sino que alumbra en silencio, y a través de rodeos. A la belleza no se la encuentra en un contacto', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2494, '9788425432750', 'La agonía del Eros', 2, '2017', 96, 'Agonie des Eros', 'media/core/9788425432750.jpeg', 1, '2023-10-02 17:05:06.128788', '2023-10-02 17:05:06.128788', 1371, 2, 2, 2, 'Pensamiento Herder', '', '0205', NULL, 382, 'En esta obra rigurosamente filosófica, Byung Chul Han reflexiona, tomando como referencia a Kant, Heidegger, Lévinas y Canetti, entre otros, sobre la re-acción a la muerte para indagar en la compleja tensión entre este concepto con los de poder, identidad y transformación. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2495, '9788467047837', 'La deshumanización del Arte', 1, '2016', 238, NULL, 'media/core/9788467047837.jpeg', 1, '2023-10-02 17:06:55.280515', '2023-10-02 17:06:55.280515', 473, 2, 6, 2, 'Austral', '', '0205', NULL, 265, 'Un texto clásico, uno de los más lúcidos en la  historia del pensamiento estético español.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2496, '9788491050728', 'El Corán', 1, '2009', 640, NULL, 'media/core/9788491050728.jpeg', 1, '2023-10-02 17:10:46.457052', '2023-10-02 17:10:46.457052', 1127, 20, 6, 2, 'Penguin Clásicos', '', '0205', NULL, 11, 'Edición de Juan Vernet, catedrático de Árabe de la Universitat de BarcelonaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2497, '9788467268676', 'Los mitos griegos', 1, '2016', 267, 'Greek Myths', 'media/core/9788467268676.jpg', 1, '2023-10-02 17:14:47.862533', '2023-10-02 17:14:47.862533', 728, 15, 6, 2, NULL, '', '0205', NULL, 15, 'Un delicioso paseo por el mundo de los mitos griegos. Un clásico imprescindible en cualquier biblioteca.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2498, '9788491047353', 'Mitología nórdica', 1, '2018', 344, NULL, 'media/core/9788491047353.jpeg', 1, '2023-10-02 17:17:47.421610', '2023-10-02 17:17:47.421610', 1372, 15, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 69, 'La mitología nórdica o "vikinga" es menos famosa y popular que la clásica, pero no por ello posee menor interés y atractivo, como numerosas creaciones (de Wagner a J.R.R.Tolkien, de las películas del superhéroe Thor a la serie Vikingos) ponen de manifiesto. Enrique Bernárdez presenta lo esencial de esta mitología en este libro en el que el rigor no está reñido con la amenidad y la divulgación. Después de una introducción que nos proporciona las ideas generales para transitar cómodamente por sus páginas, el autor da cuenta de la organización y el origen del mundo mítico nórdico, presenta a los dioses de época vikinga en dos partes -los Vanes (Niörd, Frey, Freya...) y los dioses ases (Odín, Thor...)-, para pasar al "Crepúsculo" o Destino Final de los dioses, antes de recoger las principales leyendas heroicas. Provista de un utilísimo índice onomástico, la obra concluye con unas notas sobre los usos y abusos de esta mitología, especialmente en el mundo moderno.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2499, '9788499304229', 'Història de Roma', 1, '2012', 452, 'Storia di Roma', 'media/core/9788499304229.jpeg', 1, '2023-10-02 17:20:23.150044', '2023-10-02 17:20:23.150044', 326, 15, 6, 2, 'Labutxaca', '', '0205', NULL, 55, 'Indro Montanelli ha inventat una nova manera d''explicar la història, despullant-la de retòrica i ampul·lositat per fer-ne una reconstrucció viva, senzilla i polèmica. El gran periodista italià comença la seva narració de manera ben planera, afirmant que els romans ja sabien llatí, perquè si l''haguessin hagut d''estudiar no haurien tingut temps per conquerir el món. Segurament la seva Història de Roma no ens descobreix res de nou, ni fa una interpretació original de l''urbs fundada per Ròmul i Rem. És una història que ja ha estat explicada. Però el seu mèrit és tornar-ho a fer sense academicismes, a través d''una sèrie de retrats que', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2500, '9788484893097', 'Afro-Latinoamérica 1800-2000', 1, '2007', 334, 'Afro-Latin American 1800-2000', 'media/core/9788484893097.jpeg', 1, '2023-10-02 17:26:38.043089', '2023-10-02 17:26:38.043089', 1373, 15, 6, 2, NULL, '', '0205', NULL, 523, 'Síntesis de la historia de los afrodescendientes en el conjunto de América Latina, desde México y el Caribe hasta Argentina, y desde el paso de la esclavitud a la libertad en la actualidad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2501, '9788434409538', 'La construcción del presente. El mundo desde 1848 hasta nuestros días', 1, '2013', 685, NULL, 'media/core/9788434409538.JPG', 1, '2023-10-02 17:31:05.916407', '2023-10-02 17:31:05.916407', 1374, 15, 6, 2, NULL, '', '0205', NULL, 144, 'Como ocurrió en los últimos finales de siglo (y en el del XX coincidiendo además con el fin del milenio), parece como si se multiplicase la necesidad de realizar grandes balances y de replantear las bases sobre las que se fundamente la marcha global del mundo. Ahora, estas inquietudes se ven incrementadas con las constatación de lo que es percibido como la desaparición de un clima político y económico que habíamos heredado del siglo XIX y que no servía de referencia. La incertidumbre de futuro invade buena parte de las esferas de la actividad humana, tanto individual como colectiva, con lo que se va extendiendo la necesidad de conocer y revisar el proceso histórico en el que se han construido nuestro presente.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2502, '9788417067465', '¡Viva el Latín! Historias y belleza de una lengua inútil', 1, '2017', 240, 'Viva il latino.Storie E Belleza Di una Lingua Inutile', 'media/core/9788417067465.jpeg', 1, '2023-10-02 17:36:22.039946', '2023-10-02 17:36:22.039946', 1375, 15, 6, 2, NULL, '', '0205', NULL, 61, 'Una defensa apasionada del latín como elemento cohesionador e identitario de todos los europeos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2503, '9788420683300', 'El fascismo', 3, '2014', 265, 'Fascism. Comparison and Definition', 'media/core/9788420683300.jpeg', 1, '2023-10-02 17:42:41.724482', '2023-10-02 17:42:41.724482', 1376, 2, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 69, 'Este documentado ensayo se propone definir el fascismo a través del estudio comparado de los diversos movimientos que han esgrimido ese nombre o que lo han recibido de sus adversarios. Stanley G. Payne establece los criterios que diferencian el fascismo tanto de la derecha autoritaria conservadora como de la extrema derecha. Los sistemas de Mussolini y Hitler, los regímenes de Franco y Salazar, la expansión mimética del fenómeno en diversas naciones europeas y la difusión de sus rasgos doctrinales en otros lugares del planeta suministran un rico material empírico para la síntesis. En su búsqueda de una tipología del «fascismo genérico», Payne rechaza las explicaciones monocausales, subraya la complejidad del este movimiento y apunta los rasgos comunes ideológicos, políticos y retóricos de una manifestación peculiarmente europea e históricamente enmarcada en el periodo de entreguerras.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2504, '9788420651682', 'Camino de servidumbre', 3, '2019', 350, 'The Road of Serfdom', 'media/core/9788420651682.jpeg', 1, '2023-10-02 17:45:32.423600', '2024-02-22 19:02:48.032220', 1377, 2, 6, 2, 'El libro de bolsillo', '', '0205', NULL, 119, 'Publicado en 1944 y traducido a numerosos idiomas, "Camino de servidumbre" popularizó el nombre de Friedrich A. Hayek más allá de las fronteras del mundo académico, donde su prestigio científico (reconocido en 1974 con la concesión del Premio Nobel de Economía) estaba ya sólidamente establecido. La tesis central del libro es que los avances de la planificación económica van unidos necesariamente a la pérdida de las libertades y al progreso del totalitarismo. Resulta notable que una obra de tan acusado filo polémico, nacida para suscitar la controversia y el debate, fuera acogida con respeto incluso por sus críticos debido a su honestidad intelectual, rigor lógico e información fiable. Si Keynes mostró su acuerdo con los puntos de vista de moral y filosofía social de «este gran libro», Schumpeter subrayó un rasgo poco común en obras de este género: «Es un libro cortés que casi nunca atribuye a sus contrarios otra cosa que el error intelectual».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2505, '9788496451254', 'Constitución Española', 9, '2012', 101, NULL, 'media/core/9788496451254.jpg', 1, '2023-10-02 17:48:08.369069', '2023-10-02 17:48:08.369069', NULL, 36, 6, 2, NULL, '', '0205', NULL, 524, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2506, '9788434456907', 'Las democracias. Democracia antigua, democracia liberal y Estado de Bienestar', 2, '2015', 319, NULL, 'media/core/9788434456907.jpeg', 1, '2023-10-02 17:51:22.289554', '2023-10-02 17:51:22.289554', 1378, 2, 6, 2, 'Ciencia Política', '', '0205', NULL, 144, 'Las democracias analiza las radicales diferencias morales y organizativas entre la democracia antigua y las actuales de raíz liberal. Ferran Requejo muestra a estas últimas como productos históricos y de equilibrio en los que conviven distintas dimensiones dotadas de lógicas autónomas (liberal, democrática, social, cultural, nacional, etc.) que mantienen ineludibles tensiones entre ellas. Unas tensiones que conforman la vitalidad creativa y los déficits de legitimación de estos complejos sistemas políticos, y que muestran siempre el viaje de las democracias como inacabado y abierto a la experimentación.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2507, 'B23722', 'El sexo y su influencia en la Historia', 1, '1969', 197, NULL, 'media/core/B23722.jpg', 1, '2023-10-02 17:53:57.544298', '2023-10-02 17:53:57.544298', 1379, 15, 6, 2, NULL, '', '0205', NULL, 525, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2508, '9788484583684', 'La igualdad por razón de sexo en la Unión Europea', 1, '2011', 267, NULL, 'media/core/9788484583684.jpeg', 1, '2023-10-02 17:59:51.804821', '2023-10-02 17:59:51.804821', 1380, 2, 6, 2, NULL, '', '0205', NULL, 526, '', 'Coordinadora junto con Mariona Illamola Dausà');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2509, '9788472903913', 'La revolución sionista ha muerto. Voces israelís contra la ocupación [1967-2007]', 1, '2008', 158, 'La révolution sioniste est morte', 'media/core/9788472903913.jpeg', 1, '2023-10-21 10:42:34.956565', '2023-10-21 10:42:34.956565', 572, 33, 6, 5, 'La Biblioeca del Ciudadano', '', '07_05', NULL, 527, 'El lector se encuentra ante una obra reveladora y necesaria: una selección de textos, a partir de la Guerra de los Seis Días y hasta la actualidad, que denuncian la política hacia los palestinos del Estado de Israel –desde la ocupación hasta las exacciones y las violencias de distintos tipos– desde el interior del mismo: activistas políticos, periodistas, profesores universitarios o simplemente personas de buena voluntad, desgranan en estas páginas reflexiones, denuncias y llamamientos cuyo denominador común es la insistencia en considerar a los palestinos como iguales y en afirmar que la ocupación y la opresión –que, a su vez, arrastran intolerancia y corrupción– son contradictorios con los principios sionistas. Es eso lo que lleva a Avraham Burg, antiguo presidente del Parlamento israelí, a afirmar, en uno de los artículos de este libro, lo que proclama su título: que «la revolución sionista ha muerto».', 'Textos reunidos y presentados por Michel Warschawsky');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2510, '9788439732938', 'Un reino de olivos y ceniza. Escritores contra la ocupación de Palestina', 1, '2017', 512, 'Kingdom of Olives and Ash: Writers Confront the Occupation', 'media/core/9788439732938.jpeg', 1, '2023-10-24 07:22:04.270479', '2023-10-24 07:22:04.270479', 572, 33, 6, 5, 'Literatura Random House', '', '07_05', NULL, 171, 'Veinticinco escritores de primer nivel aportan en este libro su visión  sobre la ocupación israelí de Palestina. Invitados por la ONGBreaking the Silence (Rompiendo el Silencio), sus textos son  apuntes del natural cuando se cumplen cincuenta años de la guerra de los  Seis Días. Lejos del seguimiento mediático del conflicto, estas  historias nacen de encuentros con líderes políticos, intelectuales y  activistas, pero también de la convivencia con empresarios, granjeros, abuelos, padres e hijos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2511, '9788420609010', 'Identidades asesinas', 5, '2022', 181, 'Les identités meurtrières', 'media/core/9788420609010.jpeg', 1, '2023-10-24 10:38:30.137141', '2023-10-24 10:38:30.137141', 733, 2, 6, 5, 'El libro de bolsillo', '', '07_03', NULL, 69, 'Denuncia apasionada de la locura que incita a los hombres a matarse entre sí en el nombre de una etnia, lengua o religión, "Identidades asesinas" es, a la vez, una tentativa de comprender por qué en la historia de la humanidad la afirmación del uno ha significado siempre la negación del otro. Desde su condición de hombre situado entre Oriente y Occidente que gravita sobre toda su obra, ya sea literaria -como en "León el Africano" o "Las escalas de Levante"-, o histórica -como en "Las Cruzadas vistas por los árabes"-, cuando se le pregunta a Amin Maalouf si se siente más libanés o más francés, responde que por igual: «Lo que me hace ser yo mismo y no otro -escribe- es que estoy a caballo entre dos países, entre dos o tres lenguas, entre varias tradiciones culturales. Ésa es mi identidad».INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2513, '9788474235159', 'Naciones y nacionalismo desde 1780', 1, '1991', 197, 'Nations and Nationalism Since 1780', 'media/core/9788474235159.jpg', 1, '2023-10-24 10:44:35.580800', '2023-10-24 10:44:35.580800', 1381, 2, 6, 5, NULL, '', '07_03', NULL, 61, 'El gran historiador británico Eric Hobsbawm, autor de la celebre Historia del siglo XX, nos ofrece en este libro un detallado análisis histórico de la evolución de la nación moderna en los últimos 200 años, desde el protonacionalismo popular hasta la actualidad, procurando distinguir cuidadosamente lo que es historia real de lo que no pasa de ser "mitología programática", y poniendo de relieve la contradicción que parece existir entre la actual reafirmación política de las nacionalidades y la lógica de la integración económica que las empuja, como en el caso de la Unión Europea, a una supranacionalidad cada vez mayor. "Tal vez no todo el mundo este de acuerdo con las afirmaciones de este libro –nos dice el profesor Santos Juliá- pero los análisis de Hobsbawm tienen la virtud de plantear los problemas desde su raíz, no perderse en disquisiciones esencialistas, y devolver a las creencias su historicidad."', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2514, '9788418550898', 'Románticos y racistas. Orígenes ideológicos de los etnonacionalismos españoles', 1, '2021', 455, NULL, 'media/core/9788418550898.jpeg', 1, '2023-10-24 10:49:34.229513', '2024-02-22 19:20:23.198531', 1382, 2, 6, 5, NULL, '', '05_01', NULL, 341, 'La sustancia ideológica del galleguismo, del catalanismo y del nacionalismo vasco es romántico-reaccionaria y racista. Así, con semejante contundencia, se expresa Jorge Polo en estas páginas. El autor escudriña concienzudamente los orígenes ideológicos del galleguismo, del catalanismo y del nacionalismo vasco ?sin descuidar el andalucismo y el nacionalismo canario? y muestra cómo las fuentes intelectuales de las que se nutrieron estos movimientos fueron primordialmente la tradición romántica e idealista, sobre todo en su versión germánica, y el racialismo ?científico?. Las cabezas pensantes de los regionalismos que brotaron en la España de las últimas décadas del siglo XIX fueron románticas, enemigas de las ?ideas de 1789?. Pero también fueron racistas. Hoy, los movimientos separatistas se agitan en una permanente victimización, sucumbiendo a la pegajosa mística de la ?identidad cultural?, apelando a la existencia de unos ?pueblos? cuya esencia espiritual y sanguínea habría permanecido inmutable a lo largo de los siglos. El atractivo de lo ancestral, la seducción de lo nativo.  Polo', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2515, '9788415472957', 'Reinos desaparecidos. La historia olvidada de Europa', 1, '2013', 850, 'Vanished Kingdoms: Exploring Europe''s Lost Realms', 'media/core/9788415472957.jpeg', 1, '2023-10-24 11:00:38.692028', '2023-10-24 11:00:38.692028', 1383, 15, 6, 5, NULL, '', '0107', NULL, 46, 'Cuando pensamos en el pasado de Europa, pensamos en la historia de países que existen hoy -Francia, Inglaterra, España, Alemania, Rusia, etcétera. Y los historiadores se suelen centrar en la historia de países que todavía perviven. Pero la historia de Europa está plagada de reinos, ducados, imperios y repúblicas ya desaparecidos que tuvieron un papel predominante en su tiempo: el Reino de Aragón, que llegó a dominar el Mediterráneo occidental; el Gran Ducado de Lituania, durante décadas el país más grande de Europa; los sucesivos reinos y ducados de Borgoña, cuya brillante historia tiende a olvidarse; el reino imperial de Arlés, el Sacro Imperio Romano Germánico, el Imperio Bizantino. O los más cercanos a nosotros, pero que igualmente se desvanecieron, como los Reinos de Prusia, de Cerdeña o de Galitzia, hasta llegar a Yugoslavia o la Unión Soviética. Este libro estimulante y sorprendente, lleno de historias inesperadas, observaciones y conexiones deslumbrantes, nos ofrece una perspectiva original de la historia de Europa. Y nos recuerda que la nave del Estado -según la memorable metáfora de Platón- ''no navega para siempre. Las naves a veces capean las tormentas, a veces se van a pique. En algunas ocasiones logran llegar al puerto para ser reparadas; en otras, dañadas sin remedio, se desguazan, o se hunden, cayendo bajo la superficie hacia una recóndita postrera morada entre peces y percebes''.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2516, '9788478290598', 'Patrones de Diseño. Elementos  de software orientado a objetos reutilizable', 1, '2009', 344, 'Design Patterns: Elements of Reusable Object-Oriented Software', 'media/core/9788478290598.jpeg', 1, '2023-10-24 11:08:30.307694', '2023-10-24 11:08:30.307694', 1384, 24, 6, 5, NULL, '', '04_07', NULL, 182, 'Es un libro de patrones de diseño que describen soluciones simples y elegantes para problemas específicos del diseño de software orientado a objetos.', 'Los otros de la bande de los cuatro:INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2517, '9788498923735', 'La invención de la tradición', 1, '2012', 318, 'The Invention of Tradition', 'media/core/9788498923735.jpeg', 1, '2023-10-24 16:53:10.738997', '2023-10-24 16:53:10.738997', 1381, 2, 6, 5, 'Libros de Historia', '', '07_05', NULL, 61, 'Este libro, editado por dos reputados historiadores británicos, expone cómo el "invento de las tradiciones" fue un elemento importante de estabilidad en sociedades en proceso de cambio rápido y profundo. Pueblos sin estado –escoceses y galeses-, ciudades a la búsqueda de legitimidad en su propio ámbito nacional o en el mundo colonial –la India británica o diversos estados europeos en Çfrica- y determinados movimientos o grupos sociales, han recorrido a este tipo de inventos. Esta brillante colección de ensayos, que cubre un amplio campo de situaciones dentro y fuera de Europa, nos ayuda a comprender mejor muchas de nuestras "tradiciones inventadas", creencias, ritos y prácticas que, presentados como centenarios, han sido creados o recreados realmente en epocas muy recientes.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2518, '9788423435500', 'Polarizados. La política que nos divide', 1, '2023', 234, NULL, 'media/core/9788423435500.jpeg', 1, '2023-10-24 16:55:59.667081', '2023-10-24 16:55:59.667081', 1385, 2, 6, 5, NULL, '', '07_05', NULL, 57, 'Una reflexión sobre el aumento de la polarización política en España y otros países occidentales en las últimas décadasINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2519, '9788440699534', 'The Beatles. Antología', 1, '2000', 368, NULL, 'media/core/9788440699534.jpeg', 1, '2023-10-25 10:07:34.442537', '2023-10-25 10:07:34.442537', 1386, 31, 6, 1, NULL, '', '01_01C', NULL, 8, 'Se han escrito muchos libros sobre The Beatles, pero ninguno, salvo éste puede considerarse la obra definitiva. Con declaraciones y conversaciones procedentes de las más variadas y completas fuentes se publica “The Beatles. Antología”, un definitivo documento sobre el grupo pop más famoso de todos los tiempos.“The Beatles. Antología” es la biografía de la banda más popular de todos los tiempos, contada desde dentro por sus propios miembros y con más de 1300 fotos, muchas de ellas inéditasINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2520, '9788488526243', 'Libro del caballer Zifar', 1, '2009', 157, NULL, 'media/core/9788488526243.jpeg', 1, '2023-10-25 10:14:59.823207', '2023-10-25 10:14:59.823207', 572, 1, 6, 1, NULL, '', '01_01C', NULL, 528, 'Libro de REYES Y EMPERADORESINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2521, '9788476099513', 'Font d''en Fargues. Gènesi, història i records d''un barri en 100 anys', 1, '2002', 201, NULL, 'media/core/9788476099513.jpg', 1, '2023-10-25 10:50:55.309559', '2023-10-25 10:50:55.309559', 1387, 45, 6, 1, 'Memòria de Barcelona', '', '01_01C', NULL, 221, '', '');
