INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2533, '9788446000433', 'El arte románico', 1, '1992', 552, NULL, 'media/core/sin-imagen_akDsnWF.jpg', 1, '2023-10-25 14:18:58.648384', '2023-10-25 14:18:58.648384', 1396, 11, 6, 1, NULL, '', '01_01C', 'El arte y las grandes civilizaciones', 196, 'Una historia sintética y general del arte del período románico. El libro incluye el desarrollo de los epígrafes siguientes: "Problemas de método", "La aparición del estilo", "La creación arquitectónica", " El desarrollo de la escultura", "Las artes del color", "los nuevos tesoros" y "El fin del arte románico". Las especiales características de la colección, la calidad científica del texto y la abundancia de la documentación gráfica ofrecida, que incluye multitud de ilustraciones en color y blanco y negro y un extenso apéndice de más de cien páginas reservado al análisis en fichas (con plantas, alzados y secciones anejas)', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2534, '9788495677341', 'La Gramática de la Arquitectura', 4, '2006', 331, 'The Grammar of Architecture', 'media/core/9788495677341.jpg', 1, '2023-10-25 14:23:55.459953', '2023-10-27 08:03:06.948790', 1397, 40, 6, 1, NULL, '', '01_04C', NULL, 535, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2535, '9788496103719', 'La Barcelona desaparecida', 2, '2005', 272, NULL, 'media/core/9788496103719.jpeg', 1, '2023-10-25 14:27:40.551931', '2023-10-27 07:39:44.129677', 1389, 11, 6, 1, 'Col.lecció Catalunya en blanc i negre', '', '01_04C', 'IV', 536, 'La Barcelona desaparecida pretende acompañar al lector en un itinerario por la memoria histórica de la Ciudad condal: un viaje extraordinario que revela las personas detrás de las piedras de un tiempo y de un mosaico humano que la evolución urbanística, social y tecnológica lean transformado. Los autores, grandes expertos en rincones y personajes barceloneses, han creado una obra gráfica y documental única para redescubrir la Barcelona del siglo XIX hasta los años sesenta del siglo XX, una Barcelona que ya no existe y que ya no volverá. El libro hace un excepcional homenaje y un retrato magistral de la Cataluña urbana vista en blanco y negro. Gracias a una búsqueda exhaustiva en los mejores archivos, La Barcelona desaparecida contiene mucha imágenes inéditas de la vida', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2536, '9788474442854', 'Leonardo Da Vinci. Dibujos. La invención y el arte en el lenguaje de las imágenes', 2, '1989', 309, NULL, 'media/core/sin-imagen_fTQ9mOR.jpg', 1, '2023-10-25 14:30:52.708334', '2023-10-25 14:30:52.708334', NULL, 15, 6, 1, NULL, '', '01_01C', NULL, 97, '', '');
