INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2563, '8485197216', 'Akathistos (Himno marial griego)', 1, '1981', 1, NULL, 'media/core/8485197216.jpg', 1, '2023-10-27 07:57:10.012968', '2023-10-27 07:57:43.132167', NULL, 30, 6, 1, NULL, '', '01_01C', NULL, 317, '', 'Edición facsímil del códice R.I.19 de la Biblioteca de San Lorenzo el Real de El EscorialINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2564, '9781909526501', 'Led Zeppelin by Led Zeppelin', 1, '2018', 398, NULL, 'media/core/9781909526501.jpg', 1, '2023-10-27 10:58:13.866653', '2023-10-27 10:58:13.866653', 1413, NULL, 6, 1, NULL, '', '01_04C', NULL, 541, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2565, '9788484283317', 'El zoo de cristal // Un tranvía llamado Deseo', 7, '2022', 264, 'The Glass Menagerie // A Streetcar Named Desire', 'media/core/9788484283317.jpeg', 1, '2023-10-28 07:10:51.205656', '2023-10-28 07:10:51.205656', 853, 41, 6, 5, 'Artes escénicas / Obras', '', '07_03', NULL, 119, 'Un tranvía llamado Deseo fue el segundo gran triunfo del autor. Su enloquecida heroína, Blanche Dubois, ajado símbolo de las señoriales tradiciones del sur, se enfrenta, sin aceptarla, a la perentoria adaptación a los nuevos tiempos representada por su hermana y su rudimentario marido.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2566, '9788420609089', 'De repente el último verano y otras piezas cortas', 1, '2022', 296, 'Suddenly Last Summer', 'media/core/9788420609089.jpeg', 1, '2023-10-28 07:13:57.236646', '2023-10-28 07:13:57.236646', 853, 41, 6, 5, NULL, '', '07_03', NULL, 69, 'Autor de obras de teatro intensas y tormentosas popularizadas por versiones cinematográficas inolvidables, como "Un tranvía llamado deseo", "La gata sobre el tejado de zinc" o "La noche de la iguana", Tennessee Williams (1911-1983) es uno de los dramaturgos esenciales del siglo XX. En sus obras -a menudo impregnadas de una fuerte y latente tensión sexual-, el foco de la atención se desplazó de las circunstancias sociales de los personajes o su destino predeterminado al análisis de los sentimientos, presentados como el enigma principal al que se enfrenta el ser humano. "De repente el último verano" gira en torno a la muerte súbita e inesperada del joven Sebastian, protagonista ausente, que desencadena una situación dramática que Williams lleva hasta el límite. Completan el volumen siete piezas dramáticas en un acto, todas ellas espléndidas, que ofrecen un repertorio de las mejores virtudes del autor estadounidense.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2567, '9788424940713', 'Medea', 1, '2023', 99, NULL, 'media/core/9788424940713.jpeg', 1, '2023-10-28 07:17:09.975721', '2023-10-28 07:17:09.975721', 777, 41, 6, 5, NULL, '', '07_03', NULL, 322, 'Conocido sobre todo como filósofo estoico y político de primera línea, Lucio Anneo Seneca (h. 4 a. C. – 65 d. C.) es asimismo una figura fundamental del teatro latino. Autor respetado por el paso del tiempo, de el se ha conservado buena parte de sus obras, entre ellas las únicas tragedias romanas que han llegado hasta nosotros. Todas ellas son valiosas muestras del arte de Seneca, pero tambien de los factores temáticos, estilísticos, filosóficos y sociopolíticos que jalonaron el drama en la antigua Roma.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2568, '9788424939571', 'Medea', 1, '2022', 103, NULL, 'media/core/9788424939571.jpeg', 1, '2023-10-28 07:19:23.608784', '2023-10-28 07:19:23.608784', 1415, 41, 6, 5, NULL, '', '07_03', NULL, 322, 'Eurípides (c. 480-406 a.C) vivió en la época del mayor esplendor político y económico de Atenas, asistió a la construcción del Partenón y los más hermosos monumentos de la Acrópolis, y compartió con sincero patriotismo el orgullo de los Ideales democráticos. De su vida tenemos datos poco fiables. Se nos han conservado dieciocho tragedias, casi todas ellas pertenecientes a la plena madurez del autor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2569, '9788418933264', 'Relatos de fantasmas', 1, '2022', 317, NULL, 'media/core/9788418933264.jpeg', 1, '2023-10-28 07:39:21.217105', '2023-10-28 07:39:21.217105', 572, 44, 6, 5, 'Alma Clásicos ilustrados', '', '05_03', NULL, 468, 'Los fantasmas llevan siglos apareciendose en las páginas de los libros. La presente selección de relatos recorre diferentes países y culturas para abordar la figura del fantasma en la literatura: desde los espectros que vagan de noche arrastrando sus cadenas hasta planteamientos mucho más sutiles o heterodoxos. Autores de todos los generos literarios se dan cita en esta antología para mostrarnos su cara más fantasmal: Poe, Edith Wharton, Blasco Ibáñez y otros tantos firman estos 18 relatos repletos de apariciones y sustos. Dejemonos llevar por los grandes maestros en un inquietante recorrido que, a buen seguro, nos proporcionará momentos inolvidables… y tal vez alguna que otra pesadilla.', 'Edición ilusstradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2570, '9788411315890', 'Los íberos. Historia y arqueología', 1, '2023', 340, NULL, 'media/core/9788411315890.jpeg', 1, '2023-10-28 07:43:14.592302', '2023-10-28 07:43:14.592302', 1416, 15, 6, 5, NULL, '', '05_03', NULL, 68, 'Un apasionante viaje por la historia y territorio de los pueblos íberos y el legado arqueológico que perdura hasta nuestros díasINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2571, '9788491995852', 'Sesenta millones de romanos', 1, '2023', 282, 'Popular Culture in Ancient Rome', 'media/core/9788491995852.jpeg', 1, '2023-10-28 07:46:37.769567', '2023-10-28 07:46:37.769567', 1417, 11, 6, 5, 'Tiempo de Historia', '', '05_03', NULL, 61, 'Las historias de Roma suelen hablarnos tan solo de las élites dirigentes y de su cultura. Este libro, por el contrario, se refiere al pueblo romano: a la masa de 50 a 60 millones de artesanos, trabajadores, campesinos, mendigos o esclavos que formaban el 99 por ciento de la sociedad y que compartían una cultura integrada por sus estrategias de vida y por sus formas de entretenimiento, en ocasiones netamente subversivas. Jerry Toner nos introduce en este ?mundo al revés? y nos guía por terrenos fascinantes, y hasta ahora mal estudiados, como el de la salud mental en unos tiempos llenos de tensiones o el de la historia sensorial, en un intento de reconstruir un mundo de sentidos, olores y sensaciones que separaba al pueblo de la élite, y que es también muy distinto al nuestro. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2572, '9788493741372', 'Indigno de ser humano', 15, '2022', 124, '人間失格', 'media/core/9788493741372.jpeg', 1, '2023-12-29 12:00:09.891497', '2026-01-02 12:32:15.928979', 1419, 1, 6, 5, NULL, '', '07_03', NULL, 542, 'Publicada por primera vez en 1948, Indigno de ser humano es una de las novelas más célebres de la literatura japonesa contemporánea. Su polémico y brillante autor, Osamu Dazai, incorporó numerosos episodios de su turbulenta vida a los tres cuadernos que conforman esta novela y que narran, en primera persona y de forma descarnada, el progresivo declive de Yozo, joven estudiante de provincias que lleva una vida disoluta en Tokio. Repudiado por su familia tras un intento de suicidio e incapaz de vivir en armonía con sus hipócritas semejantes, Yozo malvive como dibujante de historietas y subsiste gracias a la ayuda de mujeres que se enamoran de él pese a su alcoholismo y adicción a la morfina.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2573, '9788494286100', 'En el Japón fantasmal', 1, '2015', 224, 'In ghostly Japan', 'media/core/9788494286100.jpeg', 1, '2023-12-29 12:03:08.491320', '2026-01-02 12:05:19.401053', 1420, 44, 6, 5, NULL, '', '05_02', NULL, 28, 'Un quimono letal poseído por el espíritu de una joven despechada, una enamorada que regresa de entre los muertos para reencontrarse con su amado, una esposa celosa que deja a su sucesora una herencia siniestra, un aullido sobrecogedor que nos advierte de peligros ocultosINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2574, '9788411071475', 'Un año y tres meses', 2, '2022', 80, NULL, 'media/core/9788411071475.jpeg', 1, '2023-12-29 12:07:09.815867', '2026-01-02 12:07:53.219427', 1421, 4, 6, 5, 'Marginales', '', '05_02', NULL, 12, '¿Es la tristeza, la devastación íntima, lo que nos da la medida de nuestro amor cuando perdemos al ser amado? ¿O será tal vez la intimidad de la convalecencia una extraña forma de ternura, el último asidero de la felicidad compartida?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2575, '9788483835586', 'Pasado perfecto', 15, '2021', 240, NULL, 'media/core/9788483835586.jpeg', 1, '2023-12-29 12:09:54.696519', '2026-01-02 12:31:38.001312', 1422, 1, 6, 5, 'Maxi', '', '07_01', 'Mario Conde', 12, 'El primer fin de semana de 1989 una insistente llamada de telefono arranca de su resaca al teniente Mario Conde, un policía esceptico y desengañado. El Viejo, su jefe en la Central, le llama para encargarle un misterioso y urgente caso: Rafael Morín, jefe de la Empresa de Importaciones y Exportaciones del Ministerio de Industrias, falta de su domicilio desde el día de Año Nuevo. Quiere el azar que el desaparecido sea un ex compañero de estudios de Conde, un tipo que ya entonces, aun acatando las normas establecidas, se destacaba por su brillantez y autodisciplina. Por si fuera poco, este caso enfrenta al teniente con el recuerdo de su antiguo amor por la joven Tamara, ahora casada con Morín. "El Conde" –así le conocen sus amigos–, irá descubriendo que el aparente pasado perfecto sobre el que Rafael Morín ha ido labrando su brillante carrera ocultaba ya sus sombras.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2576, '9788418668142', 'Tokio, estación de Veno', 1, '2022', 192, 'JR上野駅公園口', 'media/core/9788418668142.jpeg', 1, '2023-12-29 12:17:45.600126', '2023-12-29 12:17:45.600126', 1423, 1, 6, 4, NULL, '', NULL, NULL, 367, 'Kazu nació en Fukushima en 1933, el mismo año que el emperador japonés, y su vida se ha visto siempre ligada a la de la familia imperial. Su espíritu no puede descansar y se ve condenado a vagar por el parque que se extiende junto a la estación de Ueno, en Tokio, lugar que marcó su existencia y fue el escenario de su muerte. El parque fue lo primero que vio al llegar a Tokio para trabajar como peón en los preparativos de los Juegos Olímpicos de 1964, y también fue allí donde terminó sus días, como uno de los desheredados que lo habitan, traumatizado por el tsunami de 2011 y enfurecido por el anuncio de los Juegos de 2020. Kazu ha perdido toda noción física del mundo, pero su percepción es más aguda que nunca, y de su mano', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2577, '9788418800399', 'Los muerots. Cuento de una noche Navidad', 1, '2022', 128, 'The Dead', 'media/core/9788418800399.jpeg', 1, '2023-12-29 12:20:45.278857', '2023-12-29 12:20:45.278857', 105, 27, 6, 4, NULL, '', NULL, NULL, 318, 'La velada navideña en casa de las señoritas Morkan es el acontecimiento anual por excelencia. El hogar se llena de risas, música y baile para gran disfrute de los invitados y sus anfitrionas. Pero tambien del quedo silencio de los que ya no están. La memoria de los que nos dejaron llevará a los personajes a recorrer caminos largo tiempo olvidados.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2578, '9788418709609', 'Origen e historia íntima del Flamenco', 1, '2021', 192, NULL, 'media/core/9788418709609.jpeg', 1, '2023-12-29 12:24:19.712235', '2025-11-26 12:01:55.216229', 1424, 15, 6, 5, NULL, '', '05_02', NULL, 68, 'El flamenco es arte, pasión, dolor, sentimiento... y misterio. Muchas han sido las teorías que, a lo largo de la historia, se han formulado para explicar su origen, su excepcionalidad y su endemismo andaluz. Algunas, puramente nominalistas y radicalmente erróneas, como la de que viene de Flandes; otras, simplemente reduccionistas, como la de que es un arte gitano. Blas Infante lanzó una nueva y clarividente teoría al asociar su origen con el íntimo dolor de los derrotados y humillados andalusíes y moriscos, fellah mengu, de la que vendría la expresión de flamenco. Antonio Manuel, en su prodigiosa obra Flamenco. Arqueología de lo Jondo, a través del sentimiento y la filología, avanzó en la senda abierta por Infante. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2579, '9788416788088', 'El método Sakuma. El secreto de las top models', 1, '2021', 96, 'Model Ga Himitsu Ni Shitagaru taikan Reset Diet', 'media/core/9788416788088.jpeg', 1, '2023-12-29 12:27:33.351783', '2026-01-02 12:08:21.348856', 1425, 20, 6, 5, NULL, '', '05_02', NULL, 543, 'El fenómeno que ha vendido más de 2.000.000 de ejemplares en Japón y ha puesto en forma a medio mundoINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2580, '9788466331159', 'El bombre de círculos azules', 1, '2020', 256, 'L''homme aux cercles bleus', 'media/core/9788466331159.jpeg', 1, '2023-12-29 12:30:50.872270', '2023-12-29 12:30:50.872270', 5, 1, 6, 4, 'debolsillo', '', NULL, 'Serie comisario Adamsberg 1', 16, 'El comisario Adamsberg se enfrenta a un criminal con una mentalidad  muy retorcida, todo apunta a que se trata de uno de los casos más macabros de su carrera.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2581, '9788418838699', 'Nagori. La nostalgia por la estación que termina', 1, '2023', 136, 'La nostalgie de la saison qui vient de nous quitter', 'media/core/9788418838699.jpeg', 1, '2023-12-29 12:34:13.553163', '2026-01-02 12:06:42.152001', 1426, 1, 6, 5, NULL, '', '05_02', NULL, 544, 'Nagori, literalmente «la huella de las olas», designa en japonés la nostalgia de la separación y, en particular, la nostalgia de la estación que termina, que nos deja y que, a nuestro pesar, dejamos atrás. Remite a la estacionalidad de un fruto o de una hortaliza anunciando su futura ausencia: para recuperar su olor, su sabor y su sensación no nos quedará otro remedio que aguardar un año entero conservando, eso sí, su recuerdo en la memoria de nuestros sentidos. Nagori es asimismo la atmósfera de algo que ya no existe, como la de una casa que evoca el recuerdo de quienes la han habitado. Nagori es lo que queda tras el paso de una persona, de un objeto, de un acontecimiento. Nagori es, también, el momento de la despedida y el anhelo del regreso. Un lúcido y delicioso ensayo imbuido de poesía y clarividencia que, entroncando con la tradición de las fisiologías del gusto que inaugurara Brillat-Savarin en 1825, se halla a medio camino entre el tratado de estética, el libro de antropología cultural, la reflexión lingüística y la guía literaria. Partiendo del término nagori, Ryoko Sekiguchi hace una sagaz meditación sobre nuestro vínculo con la naturaleza y las estaciones ?en concreto, sobre los diferentes sentimientos que éstas despiertan en nosotros? y nos invita a emprender un viaje a través del arte, la poesía, la gastronomía, la sabiduría y el esplendor milenarios de Japón.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2582, '9788417059538', 'La historia del Heavy Metal', 2, '2020', 352, 'A History of Heavy Metal', 'media/core/9788417059538.jpeg', 1, '2023-12-29 12:37:43.698896', '2026-01-02 12:35:24.745481', 1427, 15, 6, 5, NULL, '', '04_05', NULL, 545, 'Esta es la historia de una red mundial de rabiosos fans que escapan de la vulgaridad cotidiana a través de la música, de estrellas épicas que viven en planetas lejanos con dioses de otras épocas, de villanos corporativos que rompen el corazón de esos fans', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2583, '9788417007072', 'La acusación. Cuentos prohibidos de Corea del Norte', 1, '2017', 256, '고발', 'media/core/9788417007072.jpeg', 1, '2023-12-29 12:41:59.619512', '2026-01-02 12:06:09.456015', 1428, 44, 6, 5, NULL, '', '05_02', NULL, 347, 'En el año 2013 un anónimo escritor norcoreano consiguió sacar fuera del país un manuscrito que contenía parte de su obra literaria. Un año después se publicaría en Corea del Sur La acusación, una colección con alguno de los relatos incluidos en ese manuscrito, un contundente retrato de la vida cotidiana bajo el régimen norcoreano. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2584, '9788418346835', 'Eso no estaba en mi libro de Japón', 1, '2021', 240, NULL, 'media/core/9788418346835.jpeg', 1, '2023-12-29 12:45:29.824022', '2026-01-02 12:34:16.146177', 1429, 15, 6, 5, NULL, '', '05_05', NULL, 68, 'A Japón no sólo hay que conocerlo sino también interpretarlo, así como para entender el presente hay que investigar el pasado. La tierra del Sol Naciente es un país colectivista, muy seguro y homogéneo, donde se trabaja mucho y se respeta al prójimo ante todo. ¿De verdad? ¿Qué hay de cierto en esto y qué es lo que implica?Esta es la versión de Beatriz Lizana, una viajera consciente de su propio sesgo occidental que se llevó la mochila cargada de prejuicios pero que se ha dispuesto a derribarlos a su vuelta. Son cuestiones muy variadas que abarcan dudas desde un punto de vista sociológico, lingüístico, histórico, psicológico e incluso genético.En el libro cuenta con un toque de humor, pero con rigor divulgativo, diversas anécdotas que le sucedieron durante el tiempo que viajó por el país, las preguntas que allí le surgieron y las reflexiones a las que llegó hablando con varios japoneses sobre temas como la familia o la amistad.Muchas de las respuestas que encontró en su investigación fueron inesperadas. Algunos de sus descubrimientos: la comunicación no verbal no es universal, en Japón sí existen los rubios Ónaturales- y también la discriminación,', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2585, '9788417173784', 'Maestras', 1, '2023', 256, NULL, 'media/core/9788417173784.jpeg', 1, '2024-01-02 07:12:05.979308', '2024-01-02 07:12:05.979308', 572, 37, 6, 2, NULL, '', NULL, NULL, 546, 'Exposición en el Museo Nacional Thyssen-Bornemisza del 31 de octubre de 2023 al 4 de febrero de 2024.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2586, '9788419499479', 'Lee Miller. Fotografías', 1, '2023', 144, 'Lee Miller: Photographs', 'media/core/9788419499479_kXSl4U6.jpg', 1, '2024-01-02 07:23:58.515440', '2024-01-02 07:23:58.515440', 1430, 36, 6, 2, NULL, '', NULL, NULL, 134, 'Cien de las fotografías más destacadas realizadas por la fotógrafa, modelo y musa surrealista Lee Miller, publicadas como anticipo de la película Lee protagonizada por Kate Winslet en el papel de la fotógrafa.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2587, '9788491995821', 'Emperador de Roma', 1, '2023', 592, 'Emperor of Rome. Ruling the Ancient Roman World', 'media/core/9788491995821.jpeg', 1, '2024-01-02 07:38:55.349842', '2024-01-02 07:38:55.349842', 259, 15, 6, 5, NULL, '', '02_01', NULL, 61, '¿Fanáticos del control, adictos al trabajo o adolescentes malcriados? ¿Cómo eran realmente los emperadores de Roma?INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2588, '9788467052428', 'La tribalización de Europa', 2, '2019', 168, 'The Tribalization of Europe', 'media/core/9788467052428.jpeg', 1, '2024-01-30 16:25:26.340110', '2024-01-30 16:25:26.340110', 1431, 2, 6, 5, NULL, '', '07_03', NULL, 18, 'Una defensa de nuestros valores liberales.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2589, '9788439738015', 'Ñamérica', 1, '2022', 680, NULL, 'media/core/9788439738015.jpeg', 1, '2024-01-30 16:29:40.029183', '2024-01-30 16:29:40.029183', 1432, NULL, 6, 5, 'Biblioteca Martín Caparrós', '', '07_05', NULL, 171, 'Hay una región del mundo donde veinte países y más de 400 millones de  personas comparten una lengua, una historia, una cultura, preocupaciones y esperanzas. La conocemos mal; conocemos sobre todo sus mitos, sus reflejos, sus lugares comunes; la pensamos tal como era en otros tiempos. Esta región se llama o se podría llamar Ñamérica #y este libro quiere contarla y entenderla tal como es ahora.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2590, '9788416964246', 'Contra el fanatismo', 2, '2023', 108, 'How to cure a fanatic', 'media/core/9788416964246.jpeg', 1, '2024-01-30 16:33:35.491859', '2024-01-30 16:33:35.491859', 1433, 2, 6, 5, 'Biblioteca Amos Oz', '', '07_03', NULL, 16, 'Edición revisada y ampliada de este clásico del pensamiento  contemporáneo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2591, '9788411484015', 'Teorías Cínicas', 1, '2023', 432, 'Cynical Theories: How Activist Scholarship Made Everything about Race, Gender, and Identity and Why', 'media/core/9788411484015.jpeg', 1, '2024-01-30 16:37:36.769603', '2024-01-30 16:37:36.769603', 1434, 2, 6, 5, NULL, '', '07_03', NULL, 69, '¿Ha oído que el lenguaje es violencia y que la ciencia es sexista, o que estar obeso es saludable, o que no existe el sexo biológico, o que solo las personas blancas pueden ser racistas? ¿Se pregunta cómo esas ideas han conseguido tan rápidamente poner en entredicho la propia lógica de la sociedad occidental? El presente libro, traducido a más de quince lenguas, documenta la evolución del dogma que subyace a esos postulados, desde sus orígenes en el posmodernismo frances. Hoy, este dogma es reconocible tanto por sus efectos -la cultura de la cancelación y las campañas de acoso en redes sociales- como por sus axiomas, que con demasiada frecuencia son considerados indiscutibles por los medios de comunicación. Helen Pluckrose y James Lindsay desmontan este entramado teórico que sustenta el activismo radical, cuya deriva autoritaria representa una amenaza no solo para la democracia liberal, sino tambien para la modernidad misma.', 'Con James Lindsay');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2592, '9788473395250', 'Del Helenismo a la Edad Media', 1, '2010', 175, 'Dall''ellenismo al medioevo', 'media/core/9788473395250.jpg', 1, '2024-01-30 16:45:25.713545', '2024-01-30 16:45:25.713545', 1435, 2, 6, 5, 'Historia Antigua', '', '07_03', NULL, 196, 'El arqueólogo de fama mundial, Ranuccio Bianchi Bandinelli recogió en este volumen algunos de sus escritos más recientes y significativos en una nueva lectura de recapitulación general de sus múltiples trabajos, con un hilo conductor que nos lleva de la tradición helenística y el ''arte plebeyo'' hasta Roma y la visión del arte al servicio de la política imperial. El propósito de comprender ''historicamente'' el fenónemo de la creatividad artística en todo tiempo y lugar; el análisis de algunas formas y su significado cultural; su perpetuación y transmisión de una época a otra, su repentina desaparición en muchos casos, se traduce en una serie de confrontaciones formales, sobre todo en el campo de la escultura, de la que han de salir las directrices de la tendencia que constituyen la línea de desenvolvimiento del arte en el mundo occidental a partir del helelnismo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2593, '978841266653', 'Sobre el nacionalismo y otros textos políticos', 1, '2023', 182, 'Notes on nationalism', 'media/core/9788412666533.jpeg', 1, '2024-01-30 16:48:42.269377', '2024-01-30 16:48:42.269377', 94, 2, 6, 5, NULL, '', '07_03', NULL, 547, 'En Sobre el nacionalismo George Orwell disecciona uno de los fenómenos políticos y sociales clave de los últimos cien años de historia. Con sencillez y claridad, expone sus características principales, indaga en sus causas históricas, clasifica sus variantes y da su particular receta para combatirlo, algo que considera básicamente ''un esfuerzo moral''.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2594, '9788423355372', 'Breve historia de la Tierra con nosostros dentro', 1, '2023', 224, NULL, 'media/core/9788423355372.jpeg', 1, '2024-02-02 16:19:27.512482', '2024-02-02 16:19:27.512482', 287, 15, 6, 5, 'Booket ciencia', '', '07_03', NULL, 59, 'Un apasionante recorrido por la historia de la biosfera para concienciar a nuestra sociedad sobre la importancia de respetar el entorno.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2595, '9788483468548', 'Hiroshima', 1, '2009', 192, 'Hiroshima', 'media/core/9788483468548.jpeg', 1, '2024-02-02 16:22:44.428388', '2024-02-02 16:22:44.428388', 1436, 45, 6, 5, NULL, '', '07_03', NULL, 204, 'El verano de 1945, William Shawn, director ejecutivo deThe New Yorker, habló con el reportero John Hersey sobre la idea de publicar  un relato que ilustrara la dimensión humana de los efectos de la bomba  atómica en Hiroshima, pues le causaba estupor comprobar que, pese a la  gran cantidad de información sobre la bomba que recibían, se estaba  ignorando lo que realmente había ocurrido en Hiroshima. El reportero aceptó el encargo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2596, '9788408104322', 'No logo. El poder de las marcas', 1, '2022', 576, 'No logo', 'media/core/9788408104322.jpeg', 1, '2024-02-02 16:25:32.341889', '2024-02-02 16:25:32.341889', 1437, 2, 6, 5, 'Actualidad', '', '07_03', NULL, 100, '¿Cómo pasó Bill Gates de trabajar en un garaje a convertirse en un magnate mundial? ¿Por que el nombre de Nike suele identificarse con el trabajo clandestino y la explotación laboral? ¿Por que algunas de las marcas más respetadas del mundo se están viendo acosadas por virulentas campañas en su contra? ¿Que significa todo esto en el contexto del marketing actual y de la globalización? ¿Y que nos dice sobre el futuro de nuestras comunidades y del mundo en que vivimos? Este libro es, a partes iguales, fruto de la investigación periodística y de la observación de nuestro entorno comercial. Su misión, en principio, es explicar la irritación que amplios sectores de la sociedad están empezando a sentir contra las grandes marcas, así como demostrar que las multinacionales han militarizado a sus oponentes. Pero, de paso, nos invita a un periplo fascinante: desde las más lujosas tiendas de ropa de las grandes ciudades a ciertos talleres de Indonesia en los que el trabajo se convierte en degradación, desde los grandes centros comerciales estadounidenses hasta los cuarteles de los activistas que atentan contra las vallas publicitarias o de los piratas informáticos que han declarado la guerra a las multinacionales que violan los', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2597, '9788441441620', 'Sobre la Libertad', 1, '2022', 224, 'On Liberty', 'media/core/9788441441620.jpeg', 1, '2024-02-02 16:28:55.100543', '2024-02-02 16:28:55.100543', 1438, 2, 6, 5, NULL, '', '07_03', NULL, 366, 'La filosofía de Stuart Mill (1806-1873) representa una de las defensas más fuertes del liberalismo fundado en una ética teleológica. Siguiendo la teoría del utilitarismo, para Mill la libertad no es un principio último y absoluto, por lo que no se basa ni en el contrato social ni en los derechos naturales, sino que ha de ser considerada según sus consecuencias sobre la felicidad de los individuos y de la sociedad. El propósito de Sobre la Libertad es la formulación del principio que ha de regular las relaciones entre la sociedad y el individuo con el fin de evitar el despotismo sobre los individuos y las minorías. La limitación de la libertad individual solo está justificada cuando «haya que proteger al género humano» y haya que «evitar que se perjudique a los demás» y nunca porque se piense que sirve para el propio bien del individuo pues este, en lo que a él se refiere, es soberano según la tradición ilustrada europea.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2598, '9788493806156', 'El Arte de la Guerra', 23, '2023', 126, NULL, 'media/core/9788493806156.jpg', 1, '2024-02-06 08:54:29.393793', '2024-02-06 08:54:29.393793', 1031, 2, 6, 5, 'Colección Eterna', '', '07_03', NULL, 360, 'Desde la disposición de los ejércitos hasta el uso de espías, pasando por el estudio del terreno o la relación entre los mandos y los soldados rasos. Puede parecer que los trece capítulos de El arte de la guerra el maestro Sun solo nos habla de estrategia militar, pero lo sugerente de sus sentencias y la profundidad de sus enseñanzas sobre el control de los tiempos, la psicología de las personas y los grupos o la naturaleza del poder convierten este clásico del pensamiento oriental en lectura obligatoria para todo el que quiera aprender a lidiar con éxito con sus conflictos cotidianos.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2599, '9788426381545', 'Cuentos macabros', 3, '2013', 213, 'Les contes macabres', 'media/core/9788426381545.jpg', 1, '2024-02-16 17:07:20.041033', '2024-02-16 17:07:20.041033', 497, 44, 6, 1, NULL, '', '01_02C', NULL, 244, 'Una edición de lujo de los cuentos de Edgar Allan Poe, maestro del terror. Los inquietantes relatos, que se presentan con la traducción de Julio Cortázar, van acompañados de las espectaculares ilustraciones de Benjamin Lacombe. Esta edición única incluye además un texto de Baudelaire sobre la vida y obra de Poe.', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2600, '8426628937', 'Con distinta piel', 1, NULL, 52, 'Adventures in the skin Trade', 'media/core/8426628937.jpg', 1, '2024-02-16 17:16:27.312715', '2024-02-16 17:16:27.312715', 1095, 27, 6, 1, NULL, '', '01_02C', NULL, 5, '', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2601, '8422635852', 'Llanto por Ignacio Sánchez Mejías', 1, '1991', 74, NULL, 'media/core/8422635852.jpg', 1, '2024-02-16 17:21:30.061080', '2024-02-16 17:21:30.061080', 766, 4, 6, 1, NULL, '', '01_02C', NULL, 5, '', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2602, '9788467247923', 'Otra vuelta de tuerca', 1, '2013', 195, 'The Turn of the Screw', 'media/core/9788467247923.jpg', 1, '2024-02-16 17:24:45.186908', '2024-02-16 17:24:45.186908', 1271, 1, 6, 1, NULL, '', '01_02C', NULL, 46, '', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2603, '9788467251029', 'Atlas de las tierras legendarias', 1, '2012', 608, 'The Atlas of Legendary Lands: Fabled Kingdoms, Phantom Islands, Lost Continents and other Mythicall', 'media/core/9788467251029.jpg', 1, '2024-02-16 17:31:30.146822', '2024-02-16 17:31:30.146822', 1439, 23, 6, 1, NULL, '', '01_02C', NULL, 5, 'Traducción de Carme Font. Hasta hace poco más de cien años, nuestro planeta era un lugar lleno de incógnitas y misterios que solo podían explicarse con conjeturas, imaginación y no poca inocencia. El atlas de las tierras legendarias recoge todas las ideas maravillosas, acertadas o no, que nuestros antepasados propusieron para dar forma al mundo. A través de sus más de ochenta mapas y reproducciones pictóricas descubriremos que dicho mundo contenía reinos y continentes imaginarios, que durante la Edad Media los mapas incluían la ubicación del Jardín del Edén, que además de la Atlántida también hemos extraviado los reinos de Hiperbórea y Lemuria, que California estaba habitada por temibles amazonas y la Patagonia, por gigantes. Un colosal trabajo de documentación que trae hasta nuestros días la incertidumbre de las primeras navegaciones, y las esperanzas y el terror que acechaban al hombre más allá', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2604, '9788466752145', 'Platero y yo', 1, '2006', 304, NULL, 'media/core/9788466752145.jpg', 1, '2024-02-16 17:34:04.885740', '2024-02-16 17:34:04.885740', 1137, 4, 6, 1, NULL, '', '01_02C', NULL, 6, 'Platero, un burro color de plata, es el pretexto que sirve al autor para expresar sus emociones más íntimas. Platero y yo (1914) está impregnado del sentimiento de melancolía que caracteriza la primera etapa de Juan Ramón Jiménez. Esta obra de prosa poética es una de las más representativas del autor.', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2605, '9788422697268', 'Historias naturales', 1, '2002', 152, 'Histoires naturelles', 'media/core/9788422697268_vpLSVpk.jpg', 1, '2024-02-16 17:38:10.464826', '2024-02-16 17:38:10.464826', 1440, 44, 6, 1, NULL, '', '01_02C', NULL, 5, '', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2606, '8422632004', 'Una Navidad', 1, '1983', 57, 'One Christmas', 'media/core/8422632004.jpg', 1, '2024-02-16 17:41:38.972289', '2024-02-16 17:41:38.972289', 822, 27, 6, 1, NULL, '', '01_02C', NULL, 211, '', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, an