INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2610, '9788448049010', 'Atlas de la Dragonlance', 1, '1993', 157, 'The Atlas of the Dragonlance World', 'media/core/9788448049010.jpg', 1, '2024-02-16 18:00:25.576224', '2024-02-16 18:00:25.576224', 1443, 23, 6, 1, NULL, '', '01_02C', NULL, 9, 'KRYNN... Adéntrate en el fascinante mundo de la Dragonlance. Acompaña a los héroes dela Lanza en sus épicos viajes a través de Krynn con este libro magníficamente ilustrado. Contempla la hermosura de la sala de audiencias del Príncipe de los Sacerdotes en el Templo de Istar, huele el aroma de las hierbas de Raistlin mientras recorres las estancias de la Torre de la Alta Hechicería de Palanthas o piérdete en los treinta y cinco', '');
