INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2632, '8425203058', 'Egipto. Arte y civilización', 2, '1973', 484, NULL, 'media/core/8425203058.jpg', 1, '2024-02-22 10:33:07.966776', '2024-02-22 10:33:07.966776', 1448, 15, 6, 1, NULL, '', '01_03C', NULL, 145, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2633, '9788480766111', 'Tesoros de los faraones. Las maravillas del Antiguo Egipto', 1, '2006', 215, 'The Glories of Ancient Egypt. Treasures of the Pharaons', 'media/core/9788480766111.jpg', 1, '2024-02-22 11:03:38.262551', '2024-02-22 11:03:38.262551', 1449, 15, 6, 1, NULL, '', '01_03C', NULL, 134, 'Un viaje al arte y los monumentos del Antiguo Egipto a través de más de 170 soberbias fotografías a todo color. Ofrece un fascinante recorrido por uno de los más apasionantes complejos ceremoniales de toda la antigüedad: la ciudad de Tebas, a orillas del Nilo, con sus espléndidos templos y esculturas, así como las cercanas necrópolis del Valle de los Reyes y el Valle de las Reinas. Permite viajar al misterioso mundo de los faraones como nunca antes se había hecho, a través de un recorrido histórico por diferentes reinados y el testimonio de sus templos, tesoros y tumbas. Proporciona, a partir de los últimos descubrimientos arqueológicos realizados, una', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2634, '9788497620314', 'Los faranoes', 1, '2002', 121, 'Les pharaons', 'media/core/9788497620314.jpg', 1, '2024-02-22 11:06:47.505621', '2024-02-22 11:06:47.505621', 118, 15, 6, 1, 'Junior', '', '01_03C', NULL, 361, '¿Quiénes eran los faraones, esos seres divinizados que hicieron construir inmensas pirámides para triunfar sobre la muerte? ¿Cuál es el secreto de los colosos de piedra y los vestigios gigantes que bordean el Nilo? Para intentar solucionar estos enigmas, Christian Jacq conduce a sus jóvenes amigos, Susana e Isidro, a lo largo de miles de años de historia, por un periplo ilustrado de 128 páginas a color tras la pista de losINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2635, '9788430544769', 'Antiguo Egipto', 1, '2002', 235, NULL, 'media/core/9788430544769.jpg', 1, '2024-02-22 11:10:58.574138', '2024-02-22 11:10:58.574138', 1450, 15, 6, 1, 'Arte, Historia y Civilización', '', '01_03C', NULL, 82, 'Un viaje fascinante al Antiguo Egipto. Este Atlas Ilustrado nos acerca a: El Arte, la arquitectura, la literatura, las costumbres, las creencias, el culto a los muertos, la escritura, la vida cotidiana... del Antiguo Egipto. Especial bibliográfico sobre el Antiguo Egipto', '');
