INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2642, '9788426436436', 'Cuento de Navidad', 1, '1990', 152, 'A Christmas Carol', 'media/core/9788426436436.jpg', 1, '2024-02-22 11:50:10.916869', '2024-02-22 11:50:10.916869', 366, 27, 6, 1, NULL, '', '01_03C', NULL, 21, '', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2643, 'M173252007', 'Barcelona 100 Imatges dels cent llocs més interessants', 1, '2007', 207, NULL, 'media/core/sin-imagen_MurDLuP.jpg', 1, '2024-02-22 11:52:37.597101', '2024-02-22 11:52:37.597101', 572, 15, 6, 1, NULL, '', '01_03C', NULL, 43, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2644, '9788482981284', 'Fotografías de ayer y hoy', 1, '1999', 304, 'Photographs: Then and Now', 'media/core/9788482981284.jpg', 1, '2024-02-22 11:56:07.194393', '2024-02-22 11:56:07.194393', 572, 54, 6, 1, NULL, '', '01_03C', NULL, 32, 'Durante más de un siglo, los redactores y fotógrafos de National Geographic han visitado los rincones más interesantes, dramáticos y extraordinarios de nuestro planeta y, con ellos, mes a mes, los lectores les han acompañado en esa aventura. Esta obra amena y deslumbrante invita a explorar la maravillosa diversidad de paisajes y escenas de todo el mundo a través de fotografías del pasado y del presente. Junto a las cautivadoras imágenes que muestran cada remota región del globo, hallará un documento escrito por un redactor que conoce bien la zona y que ha sabido captar, con amenidad y elocuencia, su carácter singular.&lt;;br:GT;Panorámica y perspectiva son características de una obra que sólo National Geographic', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2645, '9788486629557', 'Turner', 1, '1991', 177, NULL, 'media/core/9788486629557.jpg', 1, '2024-02-22 11:59:17.685703', '2024-02-22 11:59:17.685703', 572, 31, 6, 1, NULL, '', '01_03C', NULL, 559, '', '');
