INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2651, '8422651319', 'Un sueño de la Noche de San Juan', 1, '1994', 119, 'A midsummer''s night dream', 'media/core/8422651319.jpg', 1, '2024-02-25 11:08:35.425220', '2024-09-18 16:59:40.278579', 614, 41, 6, 1, NULL, '', '01_04C', NULL, 5, '', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2652, '9788416968657', 'Macbeth', 3, '2018', 216, 'Macbeth', 'media/core/9788416968657.jpg', 1, '2024-02-25 11:16:58.779641', '2024-02-25 11:53:25.038234', 614, 41, 6, 1, NULL, '', '01_04C', NULL, 561, 'La historia de Macbeth «es viscosa y espesa como una sopa de sangre», decía Jan Kott. Tragedia extraída de las Chronicles de Holinshed, sigue reflejando el absurdo de la existencia humana, envolviéndolo en tintes sangrientos. Esta es la historia de un tipo ambicioso cuyo destino lo conduce a la traición y le impide torcer la suerte que unas groseras brujas le pronostican al comienzo de la obra. Fue escrita entre 1603 y 1606, inmediatamente después de El rey Lear y poco antes que Antonio y Cleopatra, y desde entonces la escena y el cine no han dejado de interpretarla. Luis Alberto de Cuenca ha preparado con esmero este particular homenaje a William Shakespeare (1564 - 1616), traduciendo magistralmente, verso a verso, el  prodigioso texto original, en colaboración con José Fernández Bueno. Una versión que se ofrece edición', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2653, '842265380X', 'Gargantúa', 1, '1995', 223, 'Gargantua', 'media/core/842265380X.jpg', 1, '2024-02-25 11:24:20.546333', '2024-02-25 11:52:51.866900', 1453, 1, 6, 1, NULL, '', '01_04C', NULL, 5, '"Gargantúa" constituye, junto con "Pantagruel" una de las cimas de la literatura francesa del siglo XVI y probablemente la más singular y característica suma de la tradición, a la vez que anuncio casi visionario de los nuevos tiempos. Novela de aventuras, filosófica, libro de diversión, está fundado en las virtudes del lenguaje y la risa: nada más sano que liberar al cuerpo y al alma de sus impurezas y terrores riéndose del mal, del dolor y de la necedad.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2654, '9788418395024', 'Carmilla', 1, '2021', 128, NULL, 'media/core/9788418395024.jpg', 1, '2024-02-25 11:29:36.815044', '2024-02-25 11:29:36.815044', 1454, 1, 6, 1, 'Clásicos ilustrados', '', '01_04C', NULL, 468, 'Carmilla, el clásico vampírico de Joseph SheridanLe Fanu, se anticipó en un cuarto de siglo al Drácula de Bram Stoker, pero su valor va mucho más allá que el de ser el antecedente femenino del famoso conde de Transilvania. La escabrosa y atrevida relación entre sus protagonistas, Laura y Carmilla, aún hoy resulta sorprendente. La temática de la femme fatale alcanza aquí su máximo exponente, y los ecos de esta magnífica novela gótica la convierten en uno de los principales referentes del terror que se escribe en la actualidad. Todo un clásico cuya lectura hará las delicias de los amantes del género.', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2655, '842265329X', 'Los 25 grandes del Jazz', 1, '1995', 197, NULL, 'media/core/842265329X.jpg', 1, '2024-02-25 11:49:03.232311', '2024-02-25 11:49:03.232311', 1455, 15, 6, 1, NULL, '', '01_04C', NULL, 5, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2656, '9788401032974', 'El estrecho sendero entre deseos', 1, '2024', 239, 'the Narrow RoadBetween Desires', 'media/core/9788401032974.jpeg', 1, '2024-03-01 16:00:38.975095', '2024-03-01 16:00:38.975095', 196, 13, 6, 5, NULL, '', '07_03', NULL, 11, 'Si hay algo que Bast sabe hacer es negociar. Verlo hacer un trato es ver trabajar a un artista..., pero incluso el pincel de un maestro puede errar. Sin embargo, cuando recibe un regalo y lo acepta sin ofrecer nada a cambio, su mundo se tambalea. Pues, aunque sabe regatear, no sabe deberle nada a nadie.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2657, '9781800241497', 'Lemon', 1, '2021', 147, '레몬', 'media/core/9781800241497.jpg', 1, '2024-04-10 09:03:15.709465', '2024-04-10 09:03:15.709465', 1456, 1, 6, 2, NULL, '', NULL, NULL, 562, 'This is not a murder story. It is the story of those left behind. Parasite meets The Good Son in this piercing psychological portrait of three women haunted by a brutal, unsolved crime.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2658, '9788490707180', 'Muchas vidas, muchos maestros', 2, '2018', 236, 'Many Lives, Many Masters', 'media/core/9788490707180.jpg', 1, '2024-04-10 09:07:05.519151', '2024-04-10 09:07:05.519151', 1457, 1, 6, 2, NULL, '', NULL, NULL, 11, 'La historia real de un psiquiatra, su joven paciente y la terapia de regresión que cambió sus vidas para siempre.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2659, '9788439743071', 'En agosto nos vemos', 1, '2024', 122, NULL, 'media/core/9788439743071.jpeg', 1, '2024-04-24 11:26:39.828812', '2024-08-21 09:20:05.391853', 602, 1, 6, 5, NULL, '', '06_05', NULL, 11, 'Cada mes de agosto Ana Magdalena Bach toma el transbordador hasta la isla donde está enterrada su madre para visitar la tumba en la que yace. Esas visitas acaban suponiendo una irresistible invitación a convertirse en una personadistinta durante una noche al año. Escrita en el inconfundible y fascinante estilo de García Márquez, En agosto nos vemos es un canto a la vida, a la resistencia del goce pese al paso del tiempo y al deseo femenino. Un regalo inesperado para los innumerables lectores del Nobel colombiano.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2660, '9788411074278', 'La ciudad y sus muros inciertos', 1, '2024', 560, '都市とその不確かな壁', 'media/core/9788411074278.jpeg', 1, '2024-04-24 11:29:57.364613', '2024-04-24 11:38:35.920216', 243, 1, 6, 5, NULL, '', '07_05', NULL, 12, 'Poco se imagina el joven protagonista de esta novela que la chica de la que se ha enamorado está a punto de desaparecer de su vida. Se han conocido durante un concurso entre estudiantes de diferentes institutos, y no pueden verse muy a menudo. En sus encuentros, sentados bajo la glicinia de un parque o paseando a orillas de un río, la joven empieza a hablarle de una extraña ciudad amurallada, situada, al parecer, en otro mundo; poco a poco, ella acaba confesándole su inquietante sensación de que su verdadero yo se halla en esa misteriosa ciudad. De pronto, entrado el otoño, el protagonista recibe una carta de ella que quizá suponga una despedida, y eso lo sume en una profunda tristeza. Tendrán que pasar años antes de que pueda atisbar alguna posibilidad de reencontrarla.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2661, '9788413051857', 'Breve historia de Corea', 1, '2023', 324, NULL, 'media/core/9788413051857.jpeg', 1, '2024-04-24 11:34:49.671575', '2024-04-24 11:34:49.671575', 1458, 11, 6, 5, NULL, '', '07_05', NULL, 563, 'Hasta hace treinta años, lo poco que se sabía de Corea en España venía dado por la división política por la que actualmente se encuentra marcada la península. Sin embargo, a comienzos de los años 90, la cultura de Corea del sur ha ido recibiendo cada vez mayor atención gracias a sus producciones musicales y audiovisuales. Sin embargo, poco o nada se sabe sobre la rica historia de estos países que han sufrido uniones, desuniones, ocupaciones y liberaciones. En este libro intentaremos dar claridad a la historia de una península que ha afrontado sus procesos evolutivos de formas dispares y no siempre a la par. Abarcando desde la prehistoria hasta la actualidad, estudiaremos la influencia china en la zona, los diferentes reinos que se han ido sucediendo, las producciones culturales y su filosofía. Atenderemos a personajes emblemáticos sin los que hoy no se podría entender su', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2662, '9788446048565', 'El último hombre', 1, '2023', 572, 'The Last Man', 'media/core/9788446048565.jpeg', 1, '2024-04-24 11:37:11.067186', '2024-04-24 11:37:11.067186', 875, 1, 6, 5, NULL, '', '07_05', NULL, 196, 'El último hombre da título a la novela utópica publicada por Mary Shelley en 1826, en la que retrata una sociedad futura que ha sido arrasada por una terrible plaga.  El relato se ha interpretado como el lamento de la autora por la pérdida de sus seres queridos, así como el profundo cuestionamiento de los ideales revolucionarios y románticos de la autora. Al contrario de lo que sucedió con su "Frankestein", tuvo que esperar a la segunda mitad del siglo xx para recibir el reconocimiento literario que merecía.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2663, '9788494890864', 'El Anacronópete- La Mentempsícosis - Viaje a China -', 1, '2020', 420, NULL, 'media/core/9788494890864.jpeg', 1, '2024-04-30 08:53:30.143666', '2024-04-30 08:53:30.143666', 1459, 3, 6, 5, 'Colección Recuerdos del futuro', '', '07_02', NULL, 564, 'Editado por primera vez en 1887 (años antes que la novela de Welles),  este es el primer libro de la historia que describe una máquina del    tiempo. Hemos remasterizado esta pieza única, hasta ahora solamente    reservada a coleccionistas, haciendo una réplica muy precisa. Hemos    restaurado todas y cada una de las 115 maravillosas ilustraciones, y   hemos agregado más de 110 notas para facilitar la comprensión de       muchas referencias de época.Exactamente como la versión de 1887, esta  edición incorpora 2 historias adicionales: Viaje a China y La          Metempsicósis. Estas historias nos darán un conocimiento más profundo  de la personalidad del autor, y por lo tanto de su obra. El            Anacronópete en el comienzo nos presenta a los personajes y nos        describe los principios de funcionamiento de la invención. Luego, el   autor nos sumerge en una serie de aventuras, con un ritmo creciente y  muchos toques de humor y crítica a la sociedad de la época en que fue  escrito.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2664, '9788432239311', 'Apeirógono', 1, '2021', 528, 'Apeirogon', 'media/core/9788432239311.jpeg', 1, '2024-04-30 08:56:40.100711', '2024-04-30 08:56:40.100711', 1460, 1, 6, 5, 'Bibliotec Formentor', '', '07_03', NULL, 13, 'Un conflicto perpetuo. Dos familias de bandos enfrentados. Un mismo dolor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2665, '9788416788408', 'El método Sakuma . Full body', 1, '2022', 160, 'Taikan Reset Diet Kyukyoko No Bubnyase', 'media/core/9788416788408.jpeg', 1, '2024-05-06 08:03:19.479216', '2026-01-02 12:08:53.386118', 1425, 20, 6, 5, NULL, '', '05_02', NULL, 543, 'El best seller japonés para tonificar y reducir el volumen de las zonas rebeldes INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2666, '9788423349647', 'Don Quijote de la Mancha', 11, '2015', 1016, NULL, 'media/core/9788423349647.jpg', 1, '2024-07-05 10:15:22.344936', '2024-07-05 10:15:22.344936', 908, 1, 6, 5, 'Áncora y Delfín', '', '07_03', 'Volumen 1338', 59, 'La traducción íntegra del Quijote al castellano actual, de la mano de Andrés Trapiello, escritor y reconocido experto en Cervantes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2667, '9788415828662', '¿Qué pasa en Cataluña?', 4, '2013', 128, NULL, 'media/core/9788415828662.jpg', 1, '2024-07-05 10:19:51.958199', '2024-07-05 10:19:51.958199', 1023, 2, 6, 5, NULL, '', '07_03', NULL, 68, 'Manuel Chaves Nogales atendió la dinámica política en Cataluña durante la II República española en dos importantes ocasiones. En diciembre de 1931 entrevistó en profundidad al presidente de la Generalitat Francesc Maciá para su periódico, Ahora, tras la tormenta que supuso su acelerada proclamación de la República catalana. La segunda ocasión se dio entre finales de febrero y principios de marzo de 1936. Tras los arrolladores acontecimientos producidos por la victoria del Frente Popular en las elecciones de febrero de 1936, que suponen la vuelta del gobierno de la Generalitat, encarcelado desde octubre de 1934, Chaves Nogales ofreció, también en Ahora, una visión amplia del caso catalán a través de un grupo de ocho reportajes que se inició exactamente el 26 de febrero con el gran titular «¿Qué pasa en Cataluña?», y que compone el grueso de esta edición. En ese momento Chaves se muestra perspicaz como nunca a la hora de buscar la información sobre un estado de cosas que siempre, por definición en el caso catalán, le parece confuso, hasta el punto de que inicia sus reportajes aludiendo a su dificultad para identificar a"vencedores"y"vencidos". No obstante, el panorama que ofrece, con su lucidez periodística habitual, es una definición perfecta de la dinámica de arreones y frenazos de la política en torno al soberanismo catalán, al que bien pronto define como «una rara substancia que se utiliza en los laboratorios políticos de Madrid como reactivo del patriotismo, y en los de Cataluña como aglutinante de las clases conservadoras». El lector actual puede sacar del relato de aquellos días muchísimos paralelismos con el momento presente de esta edición; pero parece incluso más interesante quedarse con las claves válidas y permanentes que se detectan en estas páginas para desentrañar el «desafío» catalán.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2668, '9788417617677', 'Atlas de los grandes viajeros y exploradores', 1, '2021', 137, 'Atlas das viagens e dos exploradores: as viagens de monges, naturalistas e outros viajantes de todos', 'media/core/9788417617677.jpg', 1, '2024-07-05 10:29:59.713340', '2024-07-05 10:29:59.713340', 1461, 23, 6, 5, NULL, '', '0107', NULL, 565, 'Estos viajes contribuyeron de manera importante a nuestro conocimiento del planeta y al conocimiento mutuo. Aquellos viajeros de distintas épocas y lugares son los personajes principales de este libro, repleto de mapas y muchas, muchas aventuras.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2669, '9788467271898', 'Los pacientes del doctr García', 1, '2017', 752, NULL, 'media/core/9788467271898.jpg', 1, '2024-07-06 10:51:52.744437', '2024-07-06 10:51:52.744437', 965, 1, 6, 5, NULL, '', NULL, 'Episodios de una guerra interminable IV', 114, 'Un fascinante thriller y novela de espías. La historia más internacional y trepidante de Almudena Grandes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2670, '9788491817697', 'La inquilina d Wildfell Hall', 1, '2020', 634, 'The Tenant of Wildfell Hall', 'media/core/9788491817697.jpg', 1, '2024-07-06 10:56:28.998412', '2024-07-06 10:56:28.998412', 1300, 1, 6, 2, NULL, '', NULL, NULL, 69, 'La llegada de una joven desconocida, Helen Graham, y su hijo a la vieja mansión de Wildfell Hall despierta el interés, y luego las sospechas maliciosas, de los habitantes del tranquilo pueblo inglés en que se encuentra la casa. No saben que Helen huye de un turbulento pasado, como irá descubriendo el narrador del relato y enamorado de ella, Gilbert Markham, al leer su diario.  " La inquilina de Wildfell Hall "  es una gran novela en la que destacan no sólo actitudes y opiniones relacionadas con la condición de la mujer muy avanzadas para su tiempo, sino también una moderna representación de las miserias, defectos y debilidades humanos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2671, '9788418107252', 'Seis cuatro', 1, '2021', 647, 'Rokuyon (64)', 'media/core/9788418107252.jpg', 1, '2024-07-13 06:02:33.861028', '2024-07-13 06:02:33.861028', 1462, 14, 6, 5, 'Narrativa', '', '06_02', NULL, 29, 'La pesadilla que ningún padre podría soportar. El caso que ningún inspector podría resolver. El giro que ningún lector podría prever.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2672, '9788411480321', 'El rumor del oleaje', 4, '2022', 200, 'Shiosai', 'media/core/9788411480321.jpg', 1, '2024-08-19 07:34:18.758389', '2024-08-19 07:34:18.758389', 1063, 1, 6, 5, NULL, '', '07_03', NULL, 69, '«Dios del mar, protege a mi bondadosa madre y a mi hermano, que todavía es un niño. Cuando llegue la temporada del buceo y mi madre se sumerja, te ruego que la protejas de los numerosos peligros... Y ahora me gustaría hacerte una petición diferente... Concede algún día, incluso a una persona como yo, una novia hermosa y de buen corazón... digamos una chica como la hija de Terukichi Miyata, que acaba de volver...»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2673, '9788417617905', 'El barrio del incienso', 1, '2022', 280, NULL, 'media/core/9788417617905.jpg', 1, '2024-08-19 07:39:34.951101', '2024-08-19 07:48:43.122894', 1463, 1, 6, 5, NULL, '', '07_03', NULL, 566, 'Uno de los más grandes enigmas literarios de Japón, desconocido en Occidente. «Kawasaki no envejece» (Kenzaburo Oe).INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2675, '9788492663217', 'La agonía de Francia', 10, '2021', 173, NULL, 'media/core/9788492663217.jpg', 1, '2024-08-19 07:46:38.585147', '2024-08-19 07:46:38.585147', 1023, 2, 6, 5, NULL, '', '07_03', NULL, 347, 'En noviembre de 1936, Manuel Chaves Nogales, descorazonado por el rumbo que está tomando la guerra civil, decide abandonar España e instalarse con su familia en París. Allí colaborará con la prensa francesa y latinoamericana e incluso pondrá en marcha una publicación semiartesanal sobre la actualidad española dirigida a los exiliados republicanos. Sabiéndose fichado por la Gestapo, en 1940, pocos días antes de que los nazis entren en París, Chaves abandona la ciudad para dirigirse a Burdeos y desde allí a Londres, donde permanecerá hasta su muerte. INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2676, '9788418968136', 'El desertor', 1, '2023', 336, 'Desertion', 'media/core/9788418968136.jpg', 1, '2024-08-19 07:53:43.932206', '2024-08-19 07:53:43.932206', 1464, 1, 6, 5, 'Narrativa salamandra', '', '07_03', NULL, 29, 'Obra maestra del premio Nobel de Literatura en la que las consecuencias de una relación amorosa prohibida resuenan desde el Imperio británico hasta la independencia africana.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2677, '9788439743897', 'La vegetariana', 1, '2024', 168, '채식주의 자', 'media/core/9788439743897.jpg', 1, '2024-08-19 07:57:00.516256', '2024-08-19 07:57:00.516256', 1294, 1, 6, 5, NULL, '', '07_03', NULL, 171, 'PREMIO BOOKER INTERNACIONAL 2016INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2678, '9788419940452', 'La turista', 1, '2024', 176, '밤의 여행자들', 'media/core/9788419940452.jpg', 1, '2024-08-19 08:50:05.476746', '2024-08-19 08:50:05.476746', 1465, 1, 6, 2, NULL, '', NULL, NULL, 480, 'UN VIAJE DE LUJO A LA BOCA DEL LOBOINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2679, '9788466346122', 'El día que se perdió la cordura', 1, '2019', 456, NULL, 'media/core/9788466346122.jpg', 1, '2024-08-19 08:52:53.435024', '2024-08-19 08:52:53.435024', 1466, 1, 6, 2, 'Debolsillo', '', NULL, NULL, 11, 'Amor, odio, destino, extrañas prácticas, intriga y acción trepidante inundan las páginas de la primera novela de Javier Castillo convertida en un fenómeno editorial.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2680, '9788493749026', 'La creación de las identidades nacionales. Europa: siglos XVIII-XX', 1, '2010', 309, 'La création des identités nationales', 'media/core/9788493749026.jpg', 1, '2024-08-21 09:17:00.069455', '2024-08-21 09:17:00.069455', 1467, 2, 6, 5, NULL, '', '07_05', NULL, 567, 'Las naciones modernas han sido construidas de modo diferente al que cuentan las historias oficiales. Sus orígenes no se pierden en la noche de los tiempos, en esas edades oscuras y heroicas que describen los primeros capítulos de las historias nacionales ;  El sistema IKEA de construcción de las identidades nacionales, que permite montajes diferentes a partir de las mismas categorías elementales, pertenece actualmente al dominio público mundial: Europa lo ha exportado al mismo tiempo que imponía a sus antiguas colonias su modo de organización política ;', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2681, '9788495776464', 'Cambiar el mundo sin tomar el poder. El significado de la revolución hoy', 1, '2002', 312, 'Change the World Without Taking Power: The Meaning of Revolution Today)', 'media/core/9788495776464.jpg', 1, '2024-08-21 09:24:57.999881', '2024-08-21 09:24:57.999881', 1468, 2, 6, 5, NULL, '', '07_02', NULL, 341, 'https://es.wikipedia.org/wiki/Cambiar_el_mundo_sin_tomar_el_poder', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2682, '9788415472445', 'Grandes esperanzas', 1, '2012', 475, 'Great Expectations', 'media/core/9788415472445.jpg', 1, '2024-09-18 16:43:31.536028', '2024-09-18 16:43:31.536028', 366, 1, 6, 1, NULL, '', '01_04C', NULL, 46, 'El joven Pip es protagonista y narrador de una emotiva historia de iniciación en la que hay lugar para el amor y los giros del destino. Es huérfano y vive con su hermana, una mujer irascible que, aunque presume de haber criado a Pip «a mano», acostumbra a castigarlo con una vara con nombre propio. Su marido, un herrero bondadoso y débil de carácter, es el único aliado con el que cuenta el muchacho. El primer hecho excepcional de la vida de Pip ocurre cuando un preso fugado le pide ayuda en mitad de la noche: necesita víveres, una lima y, por supuesto, discreción absoluta. En caso contrario, el siniestro fugitivo está dispuesto a arrancarle el corazón y el hígado. No es sencillo digerir semejante amenaza y además guardar el secreto, pero en breve algo mantendrá ocupada por completo la mente de Pip: conocerá a la señorita Havisham, una anciana adinerada y excéntrica que requerirá la presencia de Pip como pasatiempo para su protegida, la pequeña Estella. Pese al desprecio que le profesa la arrogante muchacha, Pip queda prendado de ella y se hace a sí mismo la promesa en convertirse en un caballero para ser digno de su amor. La oportunidad llega bajo la apariencia de un benefactor anónimo: alguien está dispuesto a hacerse cargo de sus estudios y respaldar su ascenso social.', 'Con motivo del bicentenario del nacimiento de Charles Dickens, presentamos esta edición Grandes esperanzas, ilustrada por Ángel Mateo Charris. Traducción de Manuel Vallvé.');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2683, '9788418141454', 'La Vida en el Misisipi', 1, '2021', 576, 'Life On The Mississipi', 'media/core/9788418141454.jpg', 1, '2024-09-18 16:47:03.123909', '2024-09-18 16:57:18.161821', 622, 45, 6, 1, NULL, '', '01_04C', NULL, 561, 'Después de su gran éxito Las aventuras de Tom Sawyer (1876-1878), Mark Twain publicó La vida en el Misisipi (1883), fruto de sus experiencias como piloto en un vapor fluvial antes de la Guerra de Secesión. Se considera el primer original mecanografiado que llegó a un editor. Sus páginas, al alcance de todos los públicos, están repletas de anécdotas de la no siempre sencilla vida en el río, recuerdos personales de Twain y numerosos hechos históricos, como la expedición de Hernando de Soto. Pero quizá lo más importante del libro sea que Twain contribuye, si acaso no inventa, a la creación del mito del Misisipi como el gran río de Estados Unidos de América. Esta edición ofrece una traducción actualizada de Susana Carral y las más de seiscientas ilustraciones que Edmund H. Garrett realizó para la editio princeps, inéditas hasta ahora en español.', 'Edición ilustrada');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2684, '9788416282944', 'Desde el centro de Europa. 1912-1974 Fotografía checa. colección Dietmart Siegert', 1, '2017', 227, NULL, 'media/core/9788416282944.jpg', 1, '2024-09-18 16:52:58.727251', '2024-09-18 16:52:58.727251', 572, 37, 6, 1, NULL, '', '01_04C', NULL, 568, 'Desde el centro de Europa. Fotografía checa, 1912-1974, presenta una historia de más de sesenta años: la de la fotografía artística de la actual Chequia, uno de los países de la Mitteleuropa donde florecieron con especial intensidad tanto la vanguardia fotográfica de los años veinte y treinta como la fotografía del surrealismo y el informalismo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2685, '9788418725234', 'Gótico. Historia ilustrada', 1, '2021', 279, 'Gothic. An Illustrated History', 'media/core/9788418725234.jpg', 1, '2024-09-18 17:07:39.293900', '2024-09-18 17:07:39.293900', 1469, 15, 6, 1, NULL, '', '01_04C', NULL, 134, 'Una historia que cautivará a cualquiera que desee levantar el velo de nuestra fascinación por lo espeluznante, lo mórbido y lo sobrenatural. * A través de un viaje en el tiempo, recorriendo sus distintas formas de expresión, este libro traza los caminos entrecruzados del gótico, desde las sombras de la historia hasta el corazón mismo de la cultura popular contemporánea. * Ruinas, demonios inmortales, pasajes oscuros y bosques repletos de terrores expuestos y escondidos: los bucles del gótico se han arrastrado por la arquitectura de iglesias, mezquitas y casas señoriales, irrumpiendo incluso en los grandes almacenes de las zonas periféricas y en ciudades superpobladas. La palabra gótico evoca asociaciones con lo oscuro y lo melancólico, lo extraño y lo temido, así como lugares y personas embrujados. Este libro es una mirada sin precedentes a las formas en las que este extraño estilo se ha manifestado a través de la arquitectura, la literatura, el cine, el arte, los videojuegos y más. Desde las obras de Victor Hugo y E. T. A. Hoffmann hasta el gótico del sur, el folclore antiguo y las películas de terror clásicas, se explora cómo una estética que comenzó en los márgenes se ha reinventado a lo largo de los siglos para convertirse en parte de la cultura global dominante. El libro empieza hablando de la arquitectura y la forma góticas, incluidos elementos como el arco, la casa y las ruinas. Analiza la representación del gótico en entornos rurales y urbanos, así como en el desierto y las zonas fronterizas. A continuación, se adentra en las tradiciones y escenarios góticos de todo el mundo, desde los sublimes Alpes y el interior de Australia hasta el páramo ártico, del oscuro reino folclórico del bosque hasta los paisajes postindustriales de hospitales y asilos abandonados, y luego más allá de los límites del planeta, al incognoscible horror cósmico. El autor investiga los monstruos que nos reflejan a nosotros mismos y a la sociedad, y demuestra que a medida que el gótico ha viajado por todo el mundo y a través del tiempo se ha transformado de acuerdo con la forma de nuestros miedos y ansiedades.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2686, '9788491465843', 'Uzumaki', 1, '2017', 656, 'うずまき', 'media/core/9788491465843.jpg', 1, '2024-09-18 17:11:46.549186', '2024-09-18 17:11:46.549186', 1470, 34, 6, 1, 'Planeta Cómic', '', '01_04C', NULL, 7, 'Esta obra maestra está disponible por fin en un único integral. ¡DÉJATE CAER EN LA ESPIRAL DEL TERROR!ESPIRALES… INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2687, '9788467912098', 'Death Note', 1, '2013', 384, 'デスノート', 'media/core/9788467912098.jpg', 1, '2024-09-18 17:19:19.930474', '2024-09-18 17:19:19.930474', 1471, 34, 6, 1, NULL, '', '01_04C', 'I', 350, 'Death Note supuso toda una revolución en el manga: el protagonista, tras encontrar un objeto mágico de inmenso poder, lo utiliza no para hacer el bien sino para convertirse en el gobernante supremo del mundo. Esta historia atípica, un verdadero thriller en viñetas, es un clásico moderno del manga, y como tal, ¡merece una edición a su altura! De los autores de BAKUMAN. Consigue la serie completa de esta nueva edición en 6 volúmenes.', 'Ilustraciones de TAKESHI OBATA');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2688, '9788467912104', 'Death Note', 1, '2013', 392, 'デスノート', 'media/core/9788467912104.jpg', 1, '2024-09-18 17:22:01.694548', '2024-09-18 17:22:01.694548', 1471, 34, 6, 1, NULL, '', '01_04C', 'II', 350, 'SEGUNDO VOLUMEN DE ESTA ESPECTACULAR EDICIÓN DE DEATH NOTE. Light Yagami se ha topado con la horma de su zapato mientras implementa su plan para someter a toda la humanidad. L no le dará cuartel y está dispuesto a hacer lo que sea necesario y a no detenerse ante nada con tal de apresar al asesino Kira .', 'Ilustraciones de TAKESHI OBATA');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2689, '9788467963052', 'Death Note', 1, '2023', 408, 'デスノート', 'media/core/9788467963052.jpg', 1, '2024-09-18 17:23:57.104559', '2024-09-18 17:23:57.104559', 1471, 34, 6, 1, NULL, '', '01_04C', 'III', 350, 'El cerco de L se ha cerrado tanto que Light ha tenido que buscar una salida a su papel de Kira. Al renunciar a Ryuk y al Cuaderno de Muerte olvida todo lo que ha pasado, pero L sigue sospechando de el, ¡y de repente el Cuaderno de Muerte vuelve a la acción! ¿Quien lo controla ahora?', 'Ilustraciones de TAKESHI OBATA');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2690, '9788467912128', 'Death Note', 1, '2013', 408, 'デスノート', 'media/core/9788467912128.jpg', 1, '2024-09-18 17:25:58.917665', '2024-09-18 17:25:58.917665', 1471, 34, 6, 1, NULL, '', '01_04C', 'IV', 350, 'La Yotsuba, una empresa que se ha hecho con el cuaderno asesino, lo está usando para sus propios fines, pero lo que no saben es que Light lo tenía todo previsto y, en realidad, no hacen más que seguir su plan, cuyo objetivo final es acabar con L.', 'Ilustraciones de TAKESHI OBATA');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2691, '9788467963069', 'Death Note', 1, '2023', 376, 'デスノート', 'media/core/9788467963069.jpg', 1, '2024-09-18 17:27:37.806264', '2024-09-18 17:27:37.806264', 1471, 34, 6, 1, NULL, '', '01_04C', 'V', 350, 'Light Yagami sigue desarrollando su plan para dominar el mundo desde su postura como miembro de la policía y como Kira. Pero Near, el heredero de L, está decidido a atrapar al asesino de su colega y cada vez cierra más el cerco en torno al que aspira ser el Dios del Nuevo Mundo.', 'Ilustraciones de TAKESHI OBATA');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2692, '9791164450527', '피터 래빗 이야기', 1, '2019', 219, 'The Tale of Peter Rabbit', 'media/core/9791164450527.jpg', 1, '2024-09-18 17:37:51.133315', '2024-09-18 17:37:51.133315', 1235, 27, 6, 1, NULL, '', '01_04C', NULL, NULL, 'https://es.wikipedia.org/wiki/The_Tale_of_Peter_Rabbit', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2693, '9788494706837', '53 estaciones de Tokaido // 100 aspectos de la luna', 1, '2021', 340, '東海道五十三次    //  つき ヒャクし', 'media/core/9788494706837.jpg', 1, '2024-09-18 17:48:30.173615', '2024-09-18 17:48:30.173615', 1472, 54, 6, 1, NULL, '', '01_04C', NULL, 569, 'https://es.wikipedia.org/wiki/Las_cincuenta_y_tres_estaciones_de_T%C5%8Dkaid%C5%8DINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2696, '9788434311626', 'Zao Wou-KI Obras | Escritos | Entrevistas', 1, '2007', 159, NULL, 'media/core/9788434311626.jpg', 1, '2024-10-03 17:03:42.443109', '2024-10-03 17:03:42.443109', 1473, 31, 6, 1, NULL, '', '01_04C', NULL, 570, 'Las obras,escritos y biografía del pintor francés de origen chino . A partir de un lenguaje abstracto próximo al de Klee , se ha dedicado posteriormente, en una síntesis del arte oriental y occidental, al juego de los vacíos y los llenos y a la realización de una personal suerte de paisajes informales.', 'Edición ilustradaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2697, '9788412786897', 'Miedo', 1, '2024', 112, 'Angst', 'media/core/9788412786897.jpg', 1, '2024-10-04 09:44:13.139572', '2024-10-04 09:44:13.139572', 630, 1, 6, 5, 'Ficcion', '', '07_03', NULL, 571, 'La señora Irene Wagner, joven y elegante dama de la alta burguesía de Viena, tiene por amante a un pianista de poca alcurnia. En realidad, Irene está felizmente casada con un respetable abogado y es madre de unos niños de corta edad; el marido está inmerso en su trabajo, y ella vive rodeada de servidumbre y lujos, no tiene que ocuparse de sus hijos, y sus únicas obligaciones consisten en acudir a fiestas de sociedad y satisfacer sus caprichos. También el amante es otro capricho que encaja perfectamente entre las demás diversiones de su plácida y mullida existencia.Un día, al salir de una cita clandestina, una desconocida aborda a la señora Wagner y le dice que sabe perfectamente quién es y de dónde viene: es una chantajista. Irene le da dinero para que no la delate. A partir de ahí, su vida se convierte en un infierno de desesperación y miedo. Zweig describe magistralmente el calvario psicológico que recorre la protagonista: la mortal angustia que la atenaza al saber que su bienestar y el de su familia dependen de la voluntad de su torturadora la empujarán a buscar una tremenda solución que la libere para siempre de la chantajista. En los años del auge de las teorías de Sigmund Freud, también Zweig destacó como un maestro en la exploración de los más íntimos sentim', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2698, '9788467968965', 'Death Note', 1, '2024', 416, 'デスノート', 'media/core/9788467968965.jpeg', 1, '2024-10-04 09:52:01.963586', '2024-10-04 10:04:01.507958', 1471, 34, 6, 1, NULL, '', '01_04C', 'VI', 350, 'Emocionante desenlace de la historia de Light Yagami, el mortal decidido a convertirse en el dios del nuevo mundo gracias a un Cuaderno de Muerte. Near está haciendo todo lo posible por acorralarle, ¿pero tendrá lo necesario para apresar a Kira?', 'Ilustraciones de TAKESHI OBATA');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2699, '9788419735737', 'Mathilda', 1, '2023', 128, NULL, 'media/core/9788419735737.jpg', 1, '2024-10-04 09:57:17.627623', '2024-10-04 09:57:17.627623', 875, 1, 6, NULL, 'Otraslatitudes', '', NULL, NULL, 291, 'Mary Shelley (Londres, 1797-1851). Mary Wollstonecraft Godwin, conocida como Mary Shelley fue una narradora y ensayista británica famosa, sobre todo, por haber escrito Frankenstein. Editó y promocionó las obras de su esposo, el poeta romántico y filósofo Percy Bysshe Shelley. Gran parte de su obra tiene un marcado carácter autobiográfico, en especial los argumentos basados en la relación padre-hija, como se pone de manifiesto en Mathilda.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2700, '9788401033698', 'Beyond the Story: Crónica de 10 años de BTS', 1, '2023', 576, 'Beyond the Story: 10 year record of BTS', 'media/core/9788401033698_MEKO9oL.jpg', 1, '2024-12-05 08:11:30.750106', '2024-12-05 08:11:30.750106', 1474, 31, 6, 2, NULL, '', NULL, NULL, 17, 'Publicado para celebrar el 10.º aniversario de BTS, contiene historias que van mucho más allá de lo que ya sabes sobre el grupo e incluye fotos ineditas, códigos QR con los vídeos y toda la información de los álbumes.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2701, '9781526662262', 'Welcome to the Hyunam-Dong Booshop', 1, '2023', 297, '어서 오세요, 휴남동 서점입니다', 'media/core/9781526662262_GDAnG3h.jpg', 1, '2024-12-05 08:20:52.510940', '2024-12-05 08:20:52.510940', 1475, 1, 6, 2, NULL, '', NULL, NULL, 472, 'Premio al Mejor Libro del Año, Premio de los Libreros de Corea y Premio de los Libreros de Japón a la Mejor Novela Extranjera.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2702, '9788497938327', 'Puertas de fuego', 3, '2014', 464, 'Gates of Fire', 'media/core/9788497938327_Yg7ak8k.jpg', 1, '2024-12-13 17:22:36.063808', '2025-02-04 07:13:07.060632', 1476, 16, 6, 5, NULL, '', '06_02', NULL, 204, 'Xeones, un espartano superviviente de la batalla de Termópilas nos narra la invasión persa de Grecia en el siglo V a.C.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2703, '9788439741817', 'La clase de griego', 1, '2023', 176, '희랍어 시간', 'media/core/9788439741817_WWfcM4O.jpg', 1, '2024-12-13 17:27:06.078894', '2024-12-13 17:27:06.078894', 1294, 1, 6, 5, NULL, '', '06_02', NULL, 171, '"La clase de griego es impresionante. En humanidad, en lenguaje, en las formas del dolor y el silencio dentro y alrededor de nosotros. Han Kang siempre es una de las escritoras más lúcidas: ensancha el cielo de los sentimientos".Max PorterINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2704, '9788490668061', 'Las malas', 1, '2020', 240, NULL, 'media/core/9788490668061_4TjmYnM.jpg', 1, '2024-12-13 17:30:31.741096', '2024-12-13 17:30:31.741096', 1477, 1, 6, 5, 'Andanzas', '', '06_02', NULL, 12, 'En un ambiente urbano hostil, Camila Sosa narra desde dentro la vida de una comunidad de travestis en Córdoba, Argentina.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2705, '9788413620718', 'Soy un gato', 1, '2023', 584, '吾輩は猫である', 'media/core/9788413620718_Zm8FRVL.jpg', 1, '2024-12-13 17:36:52.882038', '2025-02-20 15:55:48.103735', 1490, 1, 6, 5, 'El libro de bolsillo', '', '06_02', NULL, 69, 'Adoptado de la calle por el profesor Kushami en Tokio, el felino narrador de "Soy un gato" sirve a Natsume Soseki (1867-1916) para hacer un hilarante retrato del ser humano y de una sociedad japonesa en plena mutación durante la modernizadora era Meiji. A la vez que, con gran orgullo, el gato a menudo se indigna por la forma en que lo tratan y rápidamente juzga a los humanos como bestias extrañas y volubles, no escapan a su penetrante mirada ni la propia familia de Kushami con su esposa, sus tres hijas y O-San, la criada, ni los numerosos personajes, a cuál más caricaturesco, que desfilan por la casa, como Meitei, el estudiante esteta, fantasioso y pedante, Kangetsu, el estudiante de doctorado excéntrico, y muchos otros visitantes que hacen de la novela una estampa a la vez festiva y feroz. Traducción de Emilio MasiáAdoptado de la calle por el profesor Kushami en Tokio, el felino narrador de "Soy un gato" sirve a Natsume Soseki (1867-1916) para hacer un hilarante retrato del ser humano y de una sociedad japonesa en plena mutación durante la modernizadora era Meiji. A la vez que, con gran orgullo, el gato a menudo se indigna por la forma en que lo tratan y rápidamente juzga a los humanos como bestias extrañas y volubles, no escapan a su penetrante mirada ni la propia familia de Kushami con su esposa, sus tres hijas y O-San, la criada, ni los numerosos personajes, a cuál más caricaturesco, que desfilan por la casa, como Meitei, el estudiante esteta, fantasioso y pedante, Kangetsu, el estudiante de doctorado excéntrico, y muchos otros visitantes que hacen de la novela una estampa a la vez festiva y feroz. Traducción de Emilio Masiá', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2706, '9788412227994', 'La carta', 1, '2022', 88, 'The Letter', 'media/core/9788412227994_HoR3wW7.jpg', 1, '2024-12-13 17:40:05.464431', '2024-12-13 17:40:36.766792', 1479, 1, 6, 5, 'Pequeños placeres', '', '06_02', NULL, 572, 'Un joven abogado ingles instalado en Singapur recibe la visita de su amigo Robert Crosbie, propietario de una plantación de caucho. El empresario está muy alterado porque su esposa, Leslie, ha sido arrestada por el asesinato de Geoffrey Hammond, capataz de la plantación y amigo de la familia, y quiere pedir al abogado que se encargue de su defensa. A priori no parece un caso muy complicado, especialmente cuando Leslie alega que, la noche del asesinato, Geoffrey va intentó abusar de ella aprovechándose de que estaba sola en la casa de la plantación. Además, el testimonio de Leslie, tan tranquila y sensata, parece muy convincente, o al menos esa es la impresión del abogado hasta que aparece una carta.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2707, '9789722365598', 'Harry Potter e a Pedra Filosofal', 63, '2024', 254, 'Harry Potter and the Philosopher''s Stone', 'media/core/9789722365598_cJWJsap.jpg', 1, '2025-01-02 12:00:41.246907', '2025-01-02 12:00:41.246907', 798, 1, 6, 2, NULL, '', NULL, NULL, 573, 'Harry Potter y la piedra filosofal es el primer volumen de la ya clásica serie de novelas fantásticas de la autora británica J.K. Rowling.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2708, '9788417419165', 'Hanakotoba. El lenguaje de las flores', 7, '2024', 216, NULL, 'media/core/9788417419165_arilf7k.jpg', 1, '2025-01-07 07:18:50.661390', '2025-01-07 07:18:50.661390', NULL, 40, 6, 5, NULL, '', '06_02', NULL, 28, '"El japonés tiene fama de ser un idioma ambiguo, y puede que sea cierto, pero también llega a ser muy preciso. Con este libro no pretendo recopilar palabras que se refieran a costumbres propias de la cultura japonesa y que, como son intraducibles, todos hemos adoptado (kimono, sushi, bonsái, geisha...), sino recoger palabras únicas que nos ilustran emociones, objetos y sucesos que todos hemos experimentado pero que hasta ahora no sabíamos cómo llamarlos. Quizás si conociéramos todos los idiomas, nos conoceríamos mejor a nosotros mismos y al mundo que nos rodea."', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2709, '9788413148588', 'Escuadrón (1)', 1, '2023', 528, 'Skyward', 'media/core/9788413148588_JTN5ave.jpg', 1, '2025-01-07 07:25:22.325355', '2025-01-07 07:25:22.325355', 1480, 13, 6, 5, 'B de bolsillo', '', '06_02', 'Escuadrón', 11, 'El mundo lleva siglos en guerra; la humanidad está atrapada en un planeta constantemente atacado por unos alienígenas decididos a destruirla. Los pilotos son los únicos heroes dispuestos a combatir al enemigo.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2710, '9788411971645', 'El origen de la Justicia', 1, '2023', 263, NULL, 'media/core/9788411971645_hB4uGiJ.jpg', 1, '2025-01-16 10:44:10.278420', '2025-01-16 10:44:10.278420', 1481, 2, 6, 5, 'Teoría segunda época', '', '07_03', NULL, 574, 'Todo el mundo sabe qué es un proceso judicial y ha utilizado cotidianamente la palabra "justicia" para defender aquello en lo que cree. Sin embargo, es absolutamente desconocido cuándo, cómo y dónde se empezaron a celebrar procesos judiciales, y de dónde surgió esa noción de "justicia", que desde luego no es ni natural ni innata.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2711, '9788419392589', 'Todo fluye', 2, '2023', 277, 'Vsiotechiot', 'media/core/9788419392589_GIFS2D2.jpg', 1, '2025-01-17 09:25:26.574743', '2025-01-17 09:25:26.574743', 579, 1, 6, 5, NULL, '', '06_02', NULL, 346, 'Stalin ya no está entre los vivos. En 1954, despues de tres decadas preso en campos penitenciarios, Iván Grigórievich regresa a Moscú para comprobar que la vida allí ha seguido sin el. Desde el desangelado reencuentro, cargado de contención y culpa, con su primo Nikolái, un científico que siempre se ha mantenido fiel al Partido, o el paseo por el lugar donde vivía la mujer a la que amaba, Iván toma conciencia de la magnitud de la tragedia: la libertad no sólo ha sido asesinada en la política, sino tambien en la agricultura, en la filosofía y, sobre todo, en el alma de los rusos. A traves de la voz del protagonista, Vasili Grossman se adentra en uno de los períodos más oscuros y trágicos del siglo XX, una epoca que empieza con Lenin, sigue con Stalin y termina en ese destino que nace de los huesos de una generación perdida. Una novela excepcional que además de retratar las miserias de la condición humana, es un grito contra el sinsentido de los totalitarismos y la afirmación de que la libertad es el bien más preciado del hombre. Vasili Grossman terminó el manuscrito de Todo fluye poco antes de morir, creyendo que su obra maestra,Vida y destino, saludada hoy como la gran novela del siglo XX, jamás vería la luz. Todo fluye se convierte así en el testamento literario de un escrit', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2712, '9788430623761', 'El sueño de Ulises. El Mediterráneo de la Guerra de Troya a las pateras', 2, '2023', 417, NULL, 'media/core/9788430623761_mppIqWb.jpg', 1, '2025-01-17 09:29:42.915846', '2025-01-17 09:29:42.915846', 1482, 2, 6, 5, NULL, '', '06_02', NULL, 323, 'Una iluminadora reflexión sobre el Mediterráneo como escenario de la historiaINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2713, '9788433960160', '84, Charing Cross Road', 7, '2024', 126, NULL, 'media/core/9788433960160_2iZkhEC.jpg', 1, '2025-01-17 09:32:32.417736', '2025-01-17 09:32:32.417736', 1483, 1, 6, 5, 'Colección Compactoss', '', '06_02', NULL, 6, 'En octubre de 1949, Helene Hanff, una joven escritora desconocida, envía una carta desde Nueva York a Marks & Co., la librería situada en el 84 de Charing Cross Road, en Londres. Apasionada, maniática, extravagante y muchas veces sin un duro, la señorita Hanff le reclama al librero Frank Doel volºmenes poco menos que inencontrables que apaciguarán su insaciable sed de descubrimientos. Veinte años más tarde, continºan escribiendose, y la familiaridad se ha convertido en una intimidad casi amorosa. Esta correspondencia excentrica y llena de encanto es una pequeña joya que evoca, con infinita delicadeza, el lugar que ocupan en nuestra vida los libros... y las librerías. 84, Charing Cross Road pasó casi inadvertido en el momento de su publicación, pero desde la decada de los setenta se ha convertido en un verdadero libro de culto a ambos lados del Atlántico.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2714, '9788491815549', 'Historia de la música occidental', 9, '2024', 1408, 'A History of Western Music', 'media/core/9788491815549_ZPyE8vY.jpg', 1, '2025-01-17 09:36:01.152734', '2025-01-17 09:36:01.152734', 1484, 15, 6, 5, 'Alianza Música', '', '06_02', NULL, 69, 'Novena y actualizada edición de este título tan conocido como fundamental para cualquier melómano, con nuevo material que llega hasta la música de nuestros días.La presente "Historia de la música occidental" ha sido calificada por críticos y expertos en la materia como el mejor compendio del desarrollo de la música en el mundo occidental desde las civilizaciones más antiguas hasta nuestros días. La obra, que sólo exige conocimientos elementales de terminología musical y de armonía, constituye un modelo de erudición, amenidad y justas proporciones. En este imprescindible volumen se exploran los estilos, compositores, géneros y obras fundamentales, así como la tensión entre tradición e innovación, pero también abarca una amplia variedad de estilos, religiosos y seculares, serios y humorísticos, cultos y populares, de todo el mundo. Además, ilustran y complementan el texto numerosos y plurales ejemplos musicales, cronologías, biografías, extractos de fuentes originales, resúmenes, una muy prolija bibliografía, un extenso glosario y un pliego de mapas en color. Todo ello hace de esta ya novena edición la más completa obra sobre música occidental jamás escrita.La presente "Historia de la música occidental" ha sido calificada por críticos y expertos en la materia como el mejor compendio del desarrollo de la música en el mundo occidental desde las civilizaciones más antiguas hasta nuestros días. La obra, que sólo exige conocimientos elementales de terminología musical y de armonía, constituye un modelo de erudición, amenidad y justas proporciones. En este imprescindible volumen se exploran los estilos, compositores, géneros y obras fundamentales, así como la', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2715, '9788432316449', 'La rebelión de los catalanes. Un estudio sobre la decadencia de España (1598-1640)', 2, '2022', 672, 'The Revolt of Catalans. A Study in the Decline of spain (1598-1640)', 'media/core/9788432316449_0bTYeRc.jpg', 1, '2025-01-17 09:40:10.136572', '2025-01-17 09:40:10.136572', 1485, 2, 6, 5, 'España', '', '06_02', NULL, 84, 'John H. Elliott analiza el progresivo deterioro de las relaciones entre el Principado de Cataluña y el gobierno de la monarquía en Madrid a lo largo de la primera mitad del siglo XVII. De la feroz represión del bandolerismo catalán a la presión que suponían las nuevas políticas centralizadoras de Olivares, la tensión creciente acabó desembocando en una rebelión que, en última instancia, desempeñó un papel crucial en el declive español.La rebelión catalana de 1640 fue un acontecimiento capital en la Europa del siglo XVII. Sus antecedentes y sus causas uno de los ejes de este magistral y clásico estudio iluminan extraordinariamente la cuestión, largamente debatida, de la decadencia de España. John H. Elliott perfila con trazo firme el progresivo deterioro de las relaciones entre el Principado de Cataluña y el gobierno de la monarquía en Madrid a lo largo de la primera mitad del siglo XVII. De la feroz represión del bandolerismo catalán a la presión que suponían las nuevas políticas centralizadoras de Olivares, la tensión creciente acabó desembocando en una rebelión que, en última instancia, desempeñó un papel crucial en el declive español. Investigación ejemplar y obra fundamental, La rebelión de los catalanes no solo es una lectura esencial para comprender las razones del declive español sino queconstituye, igualmente, un caso paradigmático de la lucha perenne entre las libertades regionales y las necesidades de los gobiernos centrales. La presente edición ha sido revisada en su totalidad e incluye, además, un nuevo prólogo del autor y un estudio de los profesores Pablo Fernández Albaladejo y Julio Pardos Martínez sobre la obra e influencia de J. H. Elliott.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2716, '9788491995265', 'La caída de Robespierre. 24 horas en el París revolucionario', 1, '2023', 506, 'The Fall of Robespierre. 24 Hours in Revolutionary Paris', 'media/core/9788491995265_E09Z8Kb.jpg', 1, '2025-01-20 17:38:05.010412', '2025-01-20 17:38:05.010412', 1486, 45, 6, 5, 'Serie Mayor', '', '06_02', NULL, 61, '24 horas en la vida de una de las figuras más emblemáticas de la Revolución Francesa, el gran arquitecto del Terror.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2717, '9788410352063', 'Strange pictures', 1, '2025', 288, '変な絵', 'media/core/9788410352063_HTukLvv.jpg', 1, '2025-01-26 07:32:25.507414', '2025-01-26 08:02:13.733360', 1487, 12, 6, 5, 'Roja & negra', '', '06_02', NULL, 480, 'EL FENÓMENO DE MISTERIO QUE ARRASA EN JAPÓN.Más de tres millones de lectores en Japón.Traducido a más de treinta idiomas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2718, '9788419744791', 'Sobre la losa', 4, '2023', 432, 'Sur la dalle', 'media/core/9788419744791_aheSEuH.jpg', 1, '2025-01-26 07:36:01.919784', '2025-01-26 07:41:10.890651', 5, 14, 6, 5, 'Policiaca', '', '06_02', NULL, 16, 'UELVE LA REINA DE LA NOVELA NEGRA EUROPEA «¿Soñador? ¿Perezoso? ¿O más bien un genio? Adamsberg es historia viva de la novela negra. Fred Vargas lo borda». Juan Carlos Galindo, El País «Tengo a Fred Vargas como una de las mejores novelistas francesas del momento en cualquier categoría y género». Fernando Savater «La autora más interesante del género policiaco en el presente». José María Guelbenzu Poco después de que el comisario Adamsberg haya regresado a París tras cerrar un caso en Bretaña, la policía de Rennes le pide ayuda para resolver un crimen que parece guardar relación con una oscura leyenda local: el fantasma de un conde apodado «el Cojo», cuya pata de palo sigue resonando por los corredores del castillo de Combourg. Adamsberg se desplaza con su equipo a la zona, donde se ha hallado el cadáver de un vecino después de que el siniestro caminar del cojo se oyera de noche por las calles de Louviec. En el transcurso de la investigación, el comisario no dejará de percibir, sin lograr conectarlas ni darles forma concreta, sus habituales «burbujas mentales», que preceden siempre a la inspiración necesaria para resolver cualquier misterio. Buscando la quietud que permita que estas', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2719, '9788433929471', 'La era de la revancha', 1, '2025', 184, NULL, 'media/core/9788433929471_ndnmmmv.jpg', 1, '2025-02-12 06:48:27.538136', '2025-02-12 06:48:27.538136', 1488, 2, 6, 5, 'Nuevos cuadernos Anagrama', '', '06_02', NULL, 6, 'Ante la angustia y el desconcierto por el rumbo de un mundo que cambia a toda prisa, este texto sitúa, aclara y plantea escenarios de futuro.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2720, '9788420476803', 'Lo que sabe la señorita Kim', 2024, NULL, 232, '우리가 쓴 것', 'media/core/9788420476803_QdjM8Xi.jpg', 1, '2025-02-12 07:23:14.909092', '2025-02-12 07:23:14.909092', 1296, 1, 6, 5, NULL, '', '06_02', NULL, 10, 'El nuevo e impactante libro de la aclamada autora de Kim Ji-Young, nacida en 1982,el fenómeno editorial con 1.500.000 de lectores, finalista del National Book Award.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2721, '9788415979128', 'Kokoro', 10, '2024', 256, 'Kokoro: Sensei no Isho (こゝろ)', 'media/core/9788415979128_0oQerE1.jpg', 1, '2025-02-20 15:55:17.163534', '2025-02-20 16:15:03.161480', 1490, 1, 6, 5, 'Impedimenta narrativa', '', '06_02', '115', 367, 'Coincidiendo con el centenario de su aparición, Impedimenta publica una nueva traducción de la obra maestra de Sōseki, que prefiguraría la de autores de la importancia de Akutagawa, Kawabata o Murakami. «Kokoro» («corazón», en japonés) narra la historia de una amistad sutil y conmovedora entre dos personajes sin nombre, un joven y un enigmático anciano al que conocemos como «Sensei». Atormentado por trágicos secretos que han proyectado una larga sombra sobre su vida, Sensei se abre lentamente a su joven discípulo, confesando indiscreciones de sus días de estudiante que han dejado en él un rastro de culpa, y que revelan, en el abismo aparentemente insalvable de su angustia moral y su lucha por entender los misterios del amor y el destino, el profundo cambio cultural de una generación a la siguiente que caracterizó el Japón de principios del siglo XX. Ninguna biblioteca de literatura japonesa estaría completa sin «Kokoro», la novela más lograda de Natsume Sōseki, la más profunda y la última que completó antes de su muerte.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2722, '9788419407023', 'Atlas de la IA. Poder, política y costes planetarios de la Inteligencia Artificial', 3, '2025', 448, 'Atlas of AI', 'media/core/9788419407023_MBd8paA.jpg', 1, '2025-02-20 16:28:26.091943', '2025-02-20 16:28:26.091943', 1491, 2, 6, 5, NULL, '', '06_02', NULL, 575, '¿Quiénes son los agentes implicados en la creación de significado en inteligencia artificial? ¿Son esos resultados verdades indiscutibles científicamente? ¿A quién beneficia que las soluciones de IA sean tomadas por absolutas referencias en tecnología punta? ¿Qué coste tiene para los individuos? ¿Y para el planeta? Esta obra es el resultado de más de diez años de investigación acerca de la extracción de datos a gran escala, tanto del coste material del mismo ?explotación de minas de tierras raras, árboles en extinción, recursos subvencionados como el agua o la electricidad, explotación de mano de obra?, como de las estrategias subyacentes al dominio de una tecnología que perpetúa el poder y sus sesgos sociales y culturales. Un puzzle donde cada pieza es diseccionada y analizada con minuciosidad científica; un mapa fascinante sobre la avara explotación de los recursos naturales, trabajadores tratados sin escrúpulos, una selección de la información sesgada desde el mismo momento de su recopilación y un pacto entre los estados y las empresas privadas que obvian las responsabilidades que conlleva la extracción y el tratamiento de información privada carente de un contexto. En este libro, la autora nos ofrece una amena explicación de por qué la inteligencia artificial ni es inteligente ni es artificial.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2723, '9788375766097', 'Beksinski 1-4 wydadnie miniaturowe w etui', 1, '2022', 256, NULL, 'media/core/9788375766097_PzVJzQS.jpg', 1, '2025-02-20 16:37:11.964151', '2025-02-20 16:37:11.964151', 1492, 37, 6, 1, 'Art', '', '01_04C', NULL, 576, '''Beksiáski'' - Un conjunto único, muy de lujo de cuatro álbumes de tapa dura de gran tamaño en una elegante edición de escaparate; la colección más completa de Z. La obra artística de Beksiski hasta la fecha. Los dos primeros álbumes fueron lanzados durante la vida del artista, y fueron producidos en cooperación con el propio Maestro. La colección contiene la gran mayoría de obras de Z. Beksiáski en el campo de la pintura, el dibujo y los gráficos por ordenador, con más de 560 reproducciones de ambas colecciones privadas y los archivos del Museo Histórico de Beksiáski en la ciudad natal del artista de Sanok, Polonia.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2724, '9788419419781', 'Hijos de Ápate. Breve filosofía de la verdad, la posverdad y la mentira', 1, '2023', 108, 'Kinderen van Apate', 'media/core/9788419419781_6Yx5arH.jpg', 1, '2025-03-26 11:17:54.806438', '2025-03-26 11:32:28.170905', 1493, 2, 6, 5, 'Biblioteca de ensayo', '', '06_02', NULL, 16, 'Cuando Pandora abrió su famosa caja y la diosa Çpate escapó de su prisión, el engaño y la mentira se extendieron por todo el mundo. Desde entonces, Çpate vive entre nosotros y, según argumenta Gescinska en este ensayo, todos descendemos de ella. Pero como hijos de Çpate podemos rebelarnos y ofrecer resistencia a la tentación de la mentira, lo cual nunca fue tan necesario como en estos tiempos de posverdad, hechos alternativos y noticias falsas. El autentico problema de nuestra era es la falta de autenticidad y veracidad, conceptos que Gescinska define, respectivamente, como la sinceridad con nosotros mismos y con los demás. Lo que determina la calidad de una afirmación es la intención del hablante. Por eso, para combatir la proliferación de la mentira no basta con ofrecer más herramientas con las que comprobar los hechos. Sin un nuevo compromiso con la autenticidad y la veracidad, la democracia está más amenazada y, con ello, corremos el riesgo de perder nuestro bien más preciado: la libertad.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2725, '9788412135336', 'Panza de burro', 24, '2025', 172, NULL, 'media/core/9788412135336_NnWBv7Z.jpg', 1, '2025-03-26 11:23:29.616173', '2026-01-02 12:12:12.235966', 1494, 1, 6, 2, NULL, '', '02_05', NULL, 577, '«Reconozco que al principio, cuando Panza de burro solo había crecido unos capitulitos, pensé que sería una novela sencilla y hermosa que abriría un hachazo en esa tela de invernadero que parecía ocultar un imaginario y un mundo que debían ser mostrados. Más adelante, la grandeza del libro, la inteligencia y el salvajismo de Andrea, su pulso poético y su falta total de miedo hicieron trizas la rafia, y quedó a la vista una plantación intrincada, dolorosa, inmensa, nada sencilla. Hice la primera edición en un salón de Lisboa, y creo que fue allí cuando me di cuenta de que el libro era mucho más grande de lo que imaginé. También, y esto es importante, sentí envidia. Una envidia por la imposibilidad de escribir yo algo así». —Sabina Urraca.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2726, '9788483831915', 'El fin del mundo y un despiadado país de las maravillas', 3, '2024', 484, '世界の終りとハードボイルド・ワンダーランド', 'media/core/9788483831915_i3uoAvW.jpg', 1, '2025-03-26 11:27:38.393498', '2025-03-26 11:27:38.393498', 243, 1, 6, 5, 'Colección Andanzas', '', '06_02', NULL, 12, 'Una fascinante combinación de cyberpunk, novela negra, relato fantástico y reflexión moral a un ritmo trepidante en un mundo de desolación, ternura e identidades ambiguas.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2727, '9788439736851', 'El Hambre', 2, '2024', 662, NULL, 'media/core/9788439736851_pOQxSZ1.jpg', 1, '2025-03-26 11:31:42.105139', '2025-03-26 11:31:42.105139', 1495, 2, 6, 5, NULL, '', '06_02', NULL, 171, '*Premio Ortega y Gasset de Periodismo a la Trayectoria profesional 2023*INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2728, '9788483102503', 'Al sur de la forntera, al oeste del Sol', 10, '2023', 268, '国境の南、太陽の西', 'media/core/9788483102503_UPyFLyQ.jpg', 1, '2025-03-27 11:19:41.855685', '2025-03-27 11:19:41.855685', 243, 1, 6, 5, 'Colección Andanzas', '', '06_02', NULL, 12, 'La fascinante historia del reencuentro entre un hombre y una mujer que compartieron secretos y confidencias en la adolescencia.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2729, '9788467270785', 'Una columna de fuego', 1, '2017', 935, 'A Column of Fire', 'media/core/9788467270785_qhdfn7K.jpg', 1, '2025-05-26 06:14:52.595565', '2025-05-26 06:14:52.595565', 197, 16, 6, 5, NULL, '', '06_02', NULL, 34, 'La saga de Los pilares de la Tierra y Un mundo sin fin, que ha cautivado a millones de lectores, prosigue ahora con la magnífica y apasionante nueva novela de Ken Follett.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2730, '9788467226546', 'El asno de oro', 1, '2008', 300, 'Asinus aureus', 'media/core/9788467226546_VqhL43w.jpg', 1, '2025-05-27 09:56:37.124029', '2025-05-27 10:01:41.985710', 1496, 1, 6, 5, 'Biblioteca Clásica Gredos', '', '02_02', NULL, 578, 'https://es.wikipedia.org/wiki/Las_metamorfosis_(Apuleyo)', '');
