INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2742, '9788410079731', 'Lo que aprendí de las mujeres. Confesiones y anécdotas de un cirujano plástico', 1, '2024', 1, NULL, 'media/core/9788410079731_diIeLME.jpeg', 1, '2025-08-08 09:13:13.672369', '2025-08-08 09:13:13.672369', 1500, 31, 6, 5, NULL, '', '06_02', NULL, 580, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2743, '9788420479446', 'Misión en París', 1, '2025', 360, NULL, 'media/core/9788420479446_t2GJSKb.jpeg', 1, '2025-09-03 11:20:57.269032', '2025-09-03 11:20:57.269032', 73, 1, 6, NULL, NULL, '', NULL, 'Las aventuras del Capitán Alatriste VIII', 10, 'Es medianoche. Íñigo Balboa, que forma parte de los Correos Reales del rey católico, aguarda expectante la llegada del capitán Alatriste, de Francisco de Quevedo y de Sebastián Copons a París, donde se encuentra para entregar unos despachos al conde de Guadalmedina. Hace casi un año que no se reúnen, cuando acabó la arriesgada encomienda que tuvieron que afrontar en Venecia. Son tiempos complejos para Francia: desde hace unos meses, los hugonotes de La Rochela, con apoyo inglés, están viviendo un duro asedio por parte de las fuerzas francesas a las órdenes del cardenal Richelieu. Por mediación de Quevedo, Alatriste y sus amigos se ven envueltos en una peligrosa misión secreta ideada por el conde-duque de Olivares. Esta vez el objetivo es de tal magnitud, que la aventura a la que se enfrentan podría cambiar para siempre el curso de los acontecimientos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2744, '9788419719713', 'Descolonizando la mente palestina', 1, '2024', 147, 'Decolonising the Palestinian MInd', 'media/core/9788419719713_VGZyVSb.jpeg', 1, '2025-09-23 16:12:55.409747', '2025-09-28 06:43:58.003170', 1501, 2, 6, 5, NULL, '', '06_02', NULL, 581, 'Texto para entender la causa Palestina con dos capítulos grabados en audio desde las ruinas de Gaza en estos días y transcritos para ser leídos «Estoy de pie sobre las ruinas de una casa en la ciudad de Gaza, oteando el horizonte». Son las palabras iniciales de este libro, finalizado mediante mensajes de voz mientras Gaza, donde vivía el autor antes de exiliarse, está siendo aniquilada. Pero Descolonizar la mente palestina no trata del último ataque israelí sobre Gaza. Es una crítica aguda a los Acuerdos de Oslo, a los territorios creados por el imperialismo en nombre de la solución de los dos Estados. También es un texto, escrito a quemarropa, sobre la folklorización de la lucha y la emancipación palestinas, que se han convertido en una conducta habitual por parte de las organizaciones históricas que luchan por la liberación de Palestina. Haidar Eid se basa en la obra de Edward Said, a quien los palestinos aprecian por su implacable crítica de su situación, para hacer un llamamiento por un cambio de conciencia. Vislumbra, desde las ruinas de Gaza, un nuevo periodo de amenaza sin precedentes sobre la cultura, la identidad y el futuro del pueblo palestino. «Un grito desde Gaza».', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2745, '9788412953039', 'Breve historia del conflicto entre Israel y Palestina', 1, '2025', 136, 'A Very Short History of the Israel-Palestine Conflict (2024)', 'media/core/9788412953039_4Cq0Qkn.jpeg', 1, '2025-09-23 16:18:35.184698', '2025-09-28 06:44:13.669490', 1502, 2, 6, 5, NULL, '', '06_02', NULL, 340, 'La devastación del 7 de octubre de 2023 y los horrores que siguieron asombraron al mundo. Pero el conflicto palestino-israelí no empezó el 7 de octubre. Tampoco empezó en 1967, cuando Israel ocupó Cisjordania, ni en 1948, cuando se declaró el Estado de Israel. Empezó en 1882, cuando los primeros colonos sionistas llegaron a lo que entonces era la Palestina otomana. Ilan Pappé desentraña la historia de dos pueblos que ahora comparten una misma tierra. Remontándose a los padres fundadores del sionismo, Pappé nos conduce con maestría por los vericuetos de la política internacional hacia Israel-Palestina, la resistencia palestina a la ocupación y los cambios que se están produciendo en el propio Israel.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2746, '9788418283932', 'Contra el imperio de los datos. De armas, cables y otros artefactos', 1, '2025', 152, NULL, 'media/core/9788418283932_Y22tGpc.JPG', 1, '2025-09-23 16:24:52.930055', '2025-09-28 06:44:48.369709', 1503, 2, 6, 5, NULL, '', '06_02', NULL, 582, 'Este libro es una invitación a mirar de frente la distopía digital que ya habitamos. Coordinado por el Colectivo Disonancia de Chile, este libro reúne textos de distintas voces entre ellas, Aaron Swartz y Dmytri Kleiner que desmontan las promesas vacías del progreso tecnológico y ponen el foco en lo que muchas veces se oculta tras las pantallas: control, explotación y falsas inclusiones.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2747, '9788430627875', 'Sobre Palestina', 1, '2025', 288, 'Über Palästina', 'media/core/9788430627875_yBCfBY0.jpeg', 1, '2025-09-23 16:28:46.553271', '2025-09-28 06:43:40.728854', 1504, 2, 6, 5, NULL, '', '07_03', NULL, 323, 'En 1944, la corriente sionista europea estaba a punto de lograr el objetivo de fundar su propio Estado en territorio palestino. Fueron muchos los intelectuales que participaron de este planteamiento, entre ellos Hannah Arendt, quien elaboró un breve estudio acerca de la viabilidad del proyecto, posicionándose a favor de la creación del Estado de Israel, aunque con ciertas reticencias: este asentamiento no debía realizarse sin establecer las condiciones con claridad, debido al peligro de desembocar en una convivencia truncada y hostil. Advirtió, además, de que Estados Unidos podría aprovecharse de la situación para apropiarse del petróleo de la región.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2748, '9791399142006', 'Reflejos de Japón 365 días con alma', 1, '2025', 429, NULL, '', 1, '2025-12-29 07:38:28.078555', '2025-12-29 07:38:28.078555', 1505, 15, 6, NULL, NULL, '', NULL, NULL, 583, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2749, '9782072995736', 'Une saison en enfer 1873. Photographies, écrits, dessins Pattti Smith', 1, '2023', 166, NULL, 'media/core/9782072995736_zh0nBPy.jpg', 1, '2026-01-01 19:23:44.046636', '2026-01-01 19:23:44.046636', 1506, 4, 6, 1, NULL, '', NULL, NULL, 293, '"J''avais seize ans quand je me suis sentie attirée par lui pour la première fois, par l''image de son visage et par ses poèmes qui me déconcertaient et me séduisaient à la fois. Plongée dans leur charme enivrant, j''en ressortais tremblante, sans vraiment me souvenir de ce que je venais de lire. Pourtant, ses mots se gravaient dans mon cerveau, s''enroulaient comme un cordage sur le pont d''un navire fantôme naviguant dans une brume mortelle. Une saison en enfer a été pour moi une drogue de jeunesse, comme un concentré de haschisch, ou une bonne dose d''alcool." P.S. Dans cet ouvrage illustré qu''elle a entièrement conçu, Patti Smith a choisi de mettre en regard les poèmes d''Une saison en enfer avec des moments de sa propre histoire, grâce à des dessins, photos, documents, textes inédits... Se dessine ainsi la relation très particulière qu''elle entretient avec le poète depuis toujours.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2750, '9780141190280', 'Cat on a Hot tin Roof', 1, NULL, 1, NULL, 'media/core/9780141190280_WmhanUb.jpg', 1, '2026-01-02 12:18:45.785847', '2026-01-02 12:18:45.785847', 853, 41, 6, 2, 'Modern classics', '', '02_05', NULL, 11, 'A sizzling drama of desire, avarice and deception set in the American Deep South, Tennessee Williams''''s Cat on a Hot Tin Roof is published in Penguin Modern Classics.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2751, '9788426432957', 'Pan de ángeles. Memorias', 1, '2025', 283, 'Bread of Angels', 'media/core/9788426432957_NRMVU3j.jpg', 1, '2026-01-07 08:14:41.218146', '2026-01-08 07:21:22.602863', 1507, 31, 6, 5, NULL, '', '03_02', NULL, 21, '«Dios susurra a través de una arruga en el papel pintado», escribe Patti Smith en estas extraordinarias memorias en las que, desde su primer recuerdo hasta sus actuales inquietudes, teje un inolvidable relato de una vida consagrada a la belleza, la música, la poesía y el amor.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2753, '9788417347628', 'Dune', 9, '2024', 778, NULL, 'media/core/9788417347628_6R9jLfx.jpg', 1, '2026-01-07 08:24:10.650709', '2026-01-09 10:12:01.893414', 1509, 3, 6, 5, NULL, '', '02_02', NULL, 585, 'La mayor epopeya de todos los tiempos, en nueva edición con la traducción corregida en 2019.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2754, '9788419346025', 'Los misterios de la taberna Kamogawa', 6, '2025', 185, '鴨川食堂', 'media/core/9788419346025_kSvQgnF.jpg', 1, '2026-01-09 10:06:40.180128', '2026-01-09 10:06:40.180128', 1510, 1, 6, 5, NULL, '', '05_02', 'Taberna Kamogawa 1', 29, 'Los misterios de la taberna Kamogawa es una de las novelas más apetitosas que vas a leer jamás. Una historia llena de ternura sobre una pareja de detectives formada por el padre y la hija del Kamogawa Shokudo, un restaurante escondido en Kioto, que siempre está lleno. El éxito entre la clientela radica en que este dúo singular se ha especializado en preparar exactamente el plato que el público anhela y recuerda de su pasado y no es capaz de reproducir o encontrar. Y lo hacen investigando la historia de la persona en cuestión. Kamogawa Koishi y su padre Nagare, antiguo detective, escuchan las confidencias de sus comensales, que anhelan revivir un momento mágico, y recrean los platos cocinados por sus seres queridos, en una novela deliciosa en todos los sentidos.', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2755, '9788419942319', 'La península de las casas vacías', 25, '2025', 694, NULL, 'media/core/9788419942319_dUdulJ3.jpg', 1, '2026-01-09 10:11:41.578190', '2026-01-09 10:11:41.578190', 1511, 1, 6, 5, 'Nuevos Tiempos', '', '02_02', NULL, 16, 'He aquí la historia de la descomposición total de una familia, de la deshumanización de un pueblo, de la desintegración de un territorio y de una península de casas vacías.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2756, '9788419836762', 'Es lloga habitació', 1, '2025', 155, NULL, 'media/core/9788419836762_sPTgF21.jpg', 1, '2026-01-11 17:28:19.655380', '2026-01-11 17:28:19.655380', 1512, 1, 6, 2, NULL, '', NULL, NULL, 586, 'L''Abril s''enfrontarà amb humor als entrebancs de la vida al costat de la seva nova companya de pisINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2757, '9788991388529', 'The May 18 Democratic Uprising', 1, '2020', 262, NULL, 'media/core/9788991388529_96HXOel.jpg', 1, '2026-01-14 07:38:36.063942', '2026-01-14 07:38:36.063942', 572, 11, 6, 2, NULL, '', '02_01', NULL, 587, '', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2758, '9788426405685', 'Contra el Fascismo', 1, '2018', 64, 'Il fascismo eterno', 'media/core/9788426405685_WMFcVbo.jpg', 1, '2026-01-20 18:39:16.427262', '2026-01-20 18:39:16.427262', 104, 2, 6, 5, NULL, '', '07_02', NULL, 21, '«El fascismo eterno aún nos rodea, aunque lleve traje de paisano. Puede volver en cualquier momento, aunque se disfrace de las formas más inocuas. Nuestro deber es detectarlo, quitarle la máscara y denunciar en voz alta cada una de sus gestas.»INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2759, '9788411480437', 'Nacionalidad y nacionalismo', 1, '2022', 240, NULL, 'media/core/9788411480437_J3vniCc.webp', 1, '2026-01-20 18:47:37.730038', '2026-01-20 18:47:37.730038', 1513, 2, 6, 5, NULL, '', '02_02', NULL, 69, 'Este volumen reúne por primera vez todos los textos de Isaiah Berlin acerca del nacionalismo, en los que explica que se trata de una inflamación agresiva y destructora que debe ser condenada, pero que engarza con la necesidad universal de pertenencia a un grupo humano. Es cuando esta necesidad es herida ohumillada, cuando sobreviene el nacionalismoINSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2760, '9788411002523', 'Los mitos de la inmigración. 22 falsos mantras sobre el tema que más nos divide', 3, '2024', 600, 'How Migration Really Works. A Factful Guide to the Most Decisive Issue in Politics', 'media/core/9788411002523_EbCObCJ.webp', 1, '2026-01-20 18:56:50.111059', '2026-01-20 18:56:50.111059', 1514, 2, 6, 5, NULL, '', '02_02', NULL, 192, 'Una exploración global del pasado, presente y futuro de la migración que pretende corregir décadas de prejuicios, desinformación y polarización.INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2761, '9791387597139', 'La morera de Jerusalén', 1, '2025', 208, 'Il gelso di Gerusalemne. L''altra storia raccontata dagli alberi', 'media/core/9791387597139_aYCPx6T.webp', 1, '2026-01-20 19:02:56.193226', '2026-01-20 19:02:56.193226', 1515, 1, 6, 5, 'La muchacha de dos cabezzas', '', '02_02', NULL, 497, '¿Y si la historia pudiese contarse desde otro punto de vista, no necesariamente humano? Éste es un libro extraño y bello. Un volumen de botánica política. O un libro de política vegetal. Es un recorrido por la historia de Palestina y Oriente Próximo, con relatos que nos hablan de la ocupación, la guerra y la resistencia, así como de la cotidianidad y la belleza de la vida, pero con una particularidad: está narrado desde la perspectiva de los árboles o colocándolos en el centro del relato. Así, a través de estos altos testigos silenciosos, Paula Caridi aborda historias íntimas, otras políticas, algunas trágicas y vinculadas a las infames guerras de Yahvé y al exterminio de todo un pueblo, que nos permiten entender desde una perspectiva inédita lo que vemos con desolación en las noticias. «Creo que he comprendido que es hora de escuchar otra historia, además de esa tan pequeña y cruel, definida por nosotros, los humanos, con la sangre de otros humanos. Demasiada sangre. Es hora de aprender de los árboles y pedir perdón». «Una obra sorprendente, que entrelaza historia, política, memoria y naturaleza con una sensibilidad única». L''Espresso «Un ensayo que es, al mismo tiempo, un manifiesto, un relato íntimo y una poderosa reflexión política sobre la situación actual en Gaza». HuffPost Italia «Un libro que nos obliga a mirar la historia desde otra perspectiva, más justa, más amplia, más humana».', '');
INSERT INTO core_titulos (id, EAN, titulo, numeroEdicion, anyoEdicion, numeroPaginas, tituloOriginal, portada, numeroEjemplares, created, updated, codiAutor_id, codiGenero_id, codiSoporte_id, codiUbicacion_id, coleccion, contraportada, codiEstante_id, serie, codiEditorial_id, sinopsis, observaciones) VALUES (2762, '9780241773703', 'Historia de la exploración mapa a mapa', 1, '2025', 288, NULL, 'media/core/9780241773703_sYuUUvJ.webp', 1, '2026-01-20 19:08:34.607052', '2026-01-20 19:08:34.607052', 572, 23, 6, 5, NULL, '', '02_02', NULL, 588, 'Un impresionante recorrido histórico, mapa a mapa, sobre los intrépidos exploradores de todo el mundoINSERT INTO core_tituloshastags (id, codiHastag_id, codiTitulo_id) VALUES (1, 8, 884);
